\section{Introduction}

For a complex measure $\mu$ on the unit circle $\T \subset \C$ and polynomials $f,g$ in a complex variable, define
\begin{equation}\label{defquasihilbert}
    \langle f , g\rangle_{\mu} := \int\limits_{\T} f g^* d \mu \, , \end{equation}
where, for functions $g$ in one or several complex variables,  we define
\begin{equation}\label{stardef}
 g^* (z_1,\dots, z_n)) := \overline{g \left ( ({\overline{z_1}})^{-1},\dots, ({\overline{z_n}})^{-1}\right )}\, .   
\end{equation}
This operation coincides with complex conjugation if all variables are in $\T$ but preserves analyticity if $g$ extends analytically.
While one may define a pairing \eqref{defquasihilbert} of polynomials more generally for distributions $\mu$ on $\T$, in this paper we
shall mainly be interested in the case of measures.
We say $f$ is left orthogonal to $g$, or $g$ is right orthogonal to $f$, 
if 
$\langle f, g \rangle_{\mu}  = 0$.
We call a polynomial $\Phi$ left or right orthogonal, if 
$\langle \Phi,p\rangle_\mu=0$
or $\langle p, \Phi\rangle_\mu=0$, respectively, 
 for all polynomials  $p$ of degree strictly less than that of $\Phi$.

Define $\mathcal{T}$ to be the class of 
complex probability measures $\mu$ on $\T$ such that, for each $n\in \mathbb{N}_0$, there exist a unique left orthogonal monic polynomial $\Phi_n$ and a unique right orthogonal  monic polynomial $\ti \Phi_n$ of degree $n$. We call the sequences $(\Phi_n)$ and $(\ti \Phi_n)$ the one-sided orthogonal polynomials associated to $\mu$. 
In Lemma \ref{lem:Szego_rec_general}, we show for $\mu\in \mathcal{T}$ 
 the generalized Szeg\H o recurrence relations $\Phi_0=\ti \Phi_0=1$ and,
 for $n\in \mathbb{N}_0$, 
\begin{equation}\label{eq:Szego_recur_intro}
\Phi_{n+1} - z \Phi_n = \overline{F_{n+1}} z^n \ti  \Phi_n ^* \, , \qquad     \ti \Phi_{n+1} - z \ti \Phi_n = \overline{\ti F_{n+1}} z^n \Phi_n ^* \, ,
\end{equation}
for some complex numbers $F_{n+1}$ and $\ti F_{n+1}$ depending on $\mu$.
Define  $\mathcal{T}_+$ to be the class of measures $\mu \in \mathcal{T}$ for which $F_{n} = \ti F_{n}$ for all $n\geq 0$.
In this case, induction with \eqref{eq:Szego_recur_intro} shows $\Phi_n = \ti \Phi_n$ for all $n \geq 0$. 
The class $\mathcal{T}_+$ contains all nonnegative probability measures on $\T$, when the polynomials $(\Phi_n)$ are the well-studied orthogonal polynomials on the unit circle \cite{simon}. More generally, $\mathcal{T}_{+}$ contains all real probability measures, whose associated polynomials were studied in \cite{Landau, Krein_sign}.

Motivated by the $SU(2)$-valued nonlinear Fourier series \cite{tsai}, here we  study the class $\mathcal{T}_{-}$ of measures $\mu \in \mathcal{T}$ for which $F_{n} = -\ti F_{n}$ for all $n\geq 1$.
We have not been able to identify literature where this class  has been studied.
If $\mu \in \mathcal{T}_{-}$, then  \eqref{eq:norm_poly_potential} shows that the monic polynomials $\Phi_n$ and $\ti \Phi_n$ satisfy 
\begin{equation}\label{normPhi}
   \langle \Phi_n,\ti \Phi_n\rangle_\mu   =   \prod\limits_{j=1} ^n (1 + |F_j|^2) >0\, .
 \end{equation}
 Thus one may divide the polynomials $\Phi_n$, $\ti \Phi_n$ 
 by the square root of the left side of \eqref{normPhi} and obtain so-called normalized left and right orthogonal polynomials $\phi_n$, $\ti \phi_n$  with positive leading coefficient and, for all $j,k\in \mathbb{N}_0$, with the Kronecker delta $\delta_{jk}$,
\begin{equation}\label{orthonormal}
    \langle \phi_j, \ti \phi_k \rangle_{\mu} = \delta_{j k} \, .
\end{equation}
In particular, \eqref{orthonormal} shows that the function
\begin{equation}\label{reprokernel}
    K_n(z, \lambda) := \sum_{j=0}^n \ti\phi_j(z ) {\phi_j^*(\lambda)}  
\end{equation}
is a reproducing kernel, since it satisfies
\begin{equation}\label{reproducing}
    \langle f(\cdot) , K_n (\cdot, \lambda ) \rangle_{\mu}  = f(\lambda) 
\end{equation}
for all normalized left orthogonal polynomials $f$ of degree at most $n$ and thus for all polynomials $f$ of degree at most $n$. 
Note that $K$ is analytic in both variables due to the star in \eqref{reprokernel} in place of a complex conjugation often done in the literature.


Our first main result is a Mate-Nevai-Totik \cite{matenevaitotik} type universality theorem for reproducing kernels $K_n$ generated by measures $\mu \in \mathcal{T}_{-}$. Define the Dirichlet kernel
    \[
    D_n (z, \lambda) := \sum\limits_{j=0} ^{n} z^j {\lambda^{-j}}  
    \]
    as the reproducing kernel associated to the uniform probability measure $\frac{d |z|}{2 \pi}$ on $\T$. 
Given $\mu\in \mathcal{T}_-$, let $E(\mu)$ denote the set of all $s\in \T$ such that
$s$ is not in the support of the  singular part of $\mu$, $s$ is a Lebesgue point of the Radon-Nikodym derivative $\frac{w}{2 \pi}$ of $\mu$ with respect to arclength, and in particular $|w(s)| < \infty$.
For $s\in E(\mu)$ and $n\in \mathbb{N}_0$, define
\begin{equation}\label{defineL}
    L(\mu,s,n):=\int\limits_{\T} \min \left \{n+1, \frac{1}{(n+1)|y-s|^2} \right \}  \left | d\mu (y) - w(s) \meas{y} \right |\, ,
    \end{equation}
    where $d |y|$ denotes the arclength measure on $\T$.
 Recall that Lebesgue differentiation implies that for all $s\in E(\mu)$ we have
\begin{equation}
    \lim_{n\to \infty} L(\mu,s,n)=0\, ,
\end{equation}
because the integrand in
\eqref{defineL} is an approximate identity while the measure   in
\eqref{defineL} has Lebesgue density $0$ at $s$.
\begin{theorem}\label{fejerconvergence}
    Let $\mu \in \mathcal{T}_{-}$, $C\geq 2$, $s\in E (\mu)$ and  $n\in \mathbb{N} _0$ with $n\ge 2C$. If we have $|z-s|\le C/n$ and $|\lambda-s|\le C/n$, then
    \begin{equation}\label{eq:KLbound}
        \frac{1}{n+1} \left| \overline{w (s)} K_n(z, \lambda ) -  D_n(z, \lambda ) \right| \leq  e^{30C} L(\mu,s,n) \, .
    \end{equation}
\end{theorem}
See \cite{Bessonov, Gubkin, EiLuSi, EiLuWo} for related universality results. Theorem \ref{fejerconvergence} can also be seen as a nonlinear generalization of the convergence of Fej\'er means, as will be elaborated in the appendix. 
Thanks to  Theorem \ref{fejerconvergence}, we develop in Section \ref{sec:lpfe} a remarkable local representation of the one-sided orthogonal polynomials $(\phi_n)$ near $s \in \T$ by parameters 
\begin{equation}\label{def:A_B_n}
        A_{n,s} := \frac{\phi_n(s)-\phi_n(s\gamma_n)}{2s^n} \, , \qquad 
    B_{n,s} := \frac{\phi_n(s)+\phi_n(s\gamma_n)}{2} \, , 
    \end{equation}
where 
\begin{equation}\label{gamman}
    \gamma_n :=e^{i\pi/n}\ .
\end{equation}
Our remaining results are all proved by careful analysis of these local parameters in three regions, pictured in Figure \ref{fig:fig}. In what follows, if no measure is specified in an integral over $\T$, we take the measure to be normalized arclength $\meas{s}$.
    \begin{theorem}\label{thm:conv_to_AB}
    Let  $\mu \in \mathcal{T}_{-}$ and $s\in E(\mu)$.
For any increasing integer sequence $(n_k)$,
\begin{equation}\label{subshyp1}
     \lim\limits_{k\to \infty} A_{n_k, s} B_{n_k, s} =0\, ,
    \end{equation}
    implies
\begin{equation}\label{subscon1}
     \lim\limits_{k\to \infty} ({\phi_{n_k}^*(s)}\ti \phi_{n_k}(s))^2 = {\overline{w(s)^{-2}}}\, .
    \end{equation}

Assume further that both $\lim\limits_{n\to \infty}|F_n|=0$ and
\begin{equation}\label{convabhyp}
      \lim\limits_{n \to \infty} \int\limits_{\T} \left | \phi_n^* (s)  \ti \phi_n (s) - \frac{1}{\overline{w (s)}} \right | = 0 \, .
      \end{equation} 
    There is a set $ E_0 (\mu)\subset E(\mu)$ of full measure such that  for every $s\in E_0(\mu)$, we have   
\begin{equation}\label{subshyp2}
     \lim\limits_{n\to \infty} ({\phi_{n}^*(s)}\ti \phi_{n}(s))^2 = {\overline{w(s)^{-2}}} \, ,
    \end{equation} 
    implies both
\begin{equation}\label{subscon2}
     \lim\limits_{n\to \infty} {\phi_{n}^*(s)}\ti \phi_{n}(s) = {\overline{w(s)^{-1}}} \, ,
    \end{equation}
    \begin{equation}\label{subscon3}
     \lim\limits_{n\to \infty} A_{n,s} B_{n,s}=0 \, .
    \end{equation}
\end{theorem}

