As Lemma \ref{smallablem} shows,
small $A$ has the effect that $ \phi_n^*  \ti \phi_n$ is close to $-\overline{w(s)^{-1}}$, while small $B$ has the effect that $ \phi_n^*  \ti \phi_n$ is close to $\overline{w(s)^{-1}}$. The first part of
Theorem \ref{thm:conv_to_AB} tautologically avoids the yellow region 
via assumption \eqref{subshyp1}, and thus obtains the convergence of $(\phi_n^*  \ti \phi_n)^2$ to $\overline{w(s)^{-2}}$. The yellow region creates large fluctuations of $ \phi_n^*  \ti \phi_n$ on Heisenberg large arcs of $\T$. This region can be suppressed by a milder integral condition \eqref{convabhyp}, as is done in the second part of Theorem \ref{thm:conv_to_AB}, or later in Theorem \ref{thm:lacunary}. The integral assumption \eqref{convabhyp} in Theorem \ref{thm:conv_to_AB}, combined with results of Section \ref{sec:lpre},
together provide a positive distance between the regions of small $A$ and small $B$. As we 
control the regions for all $n$ by the very strong assumption \eqref{subshyp2} over the full sequence of natural numbers,
smallness of $(F_n)$ implies
that asymptotically one can not jump this distance. The sequence therefore stabilizes in one of the regions, and the region of small $B$ is preferred 
given
the convergence \eqref{convabhyp} in mean. We obtain almost everywhere convergence of $ \phi_n^*  \ti \phi_n$ to
$\overline{w(s)^{-1}}$.












In the case $\mu \in \mathcal{T}_+$, there has been recent activity connecting the behavior of roots of the sequence $(\Phi_n)$ of orthogonal polynomials on the unit circle (OPUC, see \cite{simon} for an extensive treatise) to  pointwise almost everywhere boundedness \cite{Poltoratski, bessonovdenisov2021zero}. 
The following theorem shows that condition 
\eqref{subshyp1} is equivalent to the condition
 \begin{equation}\label{subshyp3}
        \liminf_{k\to \infty} n_k\min\{|z-s|: \phi_{n_k}(z)=0\} = \infty
    \end{equation}
on the zeros of the left orthogonal polynomials. The combination of 
Theorems \ref{thm:conv_to_AB} and \ref{zeros theorem} then provides an 
analog of \cite[Theorem 3]{bessonovdenisov2021zero} in the present setting of  measures $\mu \in \mathcal{T}_{-}$, connecting pointwise convergence to the behavior of zeros of orthogonal polynomials.

\begin{theorem}\label{zeros theorem}
    Let  $\mu \in \mathcal{T}_{-}$ and $s\in E(\mu)$. For all $0<\epsilon < 10^{-5}$, there is an $n_0>40$ such that, for all $n>n_0$, we have \eqref{convergence of AB1} below implies \eqref{zeros going to infinity1} below:
\begin{equation}\label{convergence of AB1}
     |A_{n,s} B_{n,s}|\ge  \epsilon \, .
    \end{equation}
\begin{equation}\label{zeros going to infinity1}
        \min\{|z-s|: \phi_{n}(z)=0\} \le 10^4\epsilon^{-1}n^{-1} \, .
    \end{equation}
Moreover,  if in addition $e^{\epsilon^{-1}} > |w(s)|$, then \eqref{zeros going to infinity2}
implies \eqref{convergence of AB2}:
\begin{equation}\label{zeros going to infinity2}
        \min\{|z-s|: \phi_{n}(z)=0\} \le 
  \epsilon^{-1}n^{-1} \, .
    \end{equation}
\begin{equation}\label{convergence of AB2}
     |A_{n,s} B_{n,s}|\ge e ^{-10\epsilon^{-1}}\, .
    \end{equation}
\end{theorem}
A monotone increasing sequence $(n_k)$ is called lacunary if there exists an $L>1$ such that for all $k\in \mathbb{N}_0$ we have
$n_{k+1}\ge Ln_k$.
\begin{theorem}\label{thm:lacunary}
    Let $\mu \in \mathcal{T}_{-}$ and assume the integral condition \eqref{convabhyp} and that $\|(F_n)\|_{\ell^2(\mathbb{N}_0)}$ is finite. 
    If $(n_k)$ is a lacunary sequence, then for almost every $s \in \T$, we have  \[
    \lim\limits_{k \to \infty} { (\phi_{n_k}^* (s)} \ti\phi_{n_k} (s))^2 = {\overline{w (s)^{-2}}}\, .
    \]

\end{theorem}
If  $F_n$ is square
summable,
one can  relate measures $\mu \in \mathcal{T}_{-}$ to the $SU(2)$-valued nonlinear Fourier series, similarly 
to how one can relate measures $\mu \in \mathcal{T}_{+}$ and the associated OPUC  to the $SU(1,1)$-valued nonlinear Fourier series \cite{TaoThiele2012}.  For such $(F_n)$, define $\phi_n$ and $\ti \phi_n$ by \eqref{recursion phi} and \eqref{recursion ti phi} and initial condition $\phi_0 = \ti \phi_0 = 1$, and define the functions
\begin{equation}\label{eq:NLFT_defn_intro}
a_n (z):= \frac{\phi_n (z) + \ti \phi_n (z)}{2 z^n} \, , \quad  b_n ^* (z):=  \frac{\phi_n (z) - \ti \phi_n (z)}{2 z^n}\, .
\end{equation}
If  $F:=(F_j)$  is square summable, then $(a_n^*,b_n)$ has an $H^2 (\D) \times H^2 (\D)$ limit $(a,b)$, where the Hardy space $H^p(\D)$
is a space of analytic functions on $\D$ with $L^p$
extensions to $\T$. This limit $(a,b)$ is called the $SU(2)$-nonlinear Fourier series (NLFS) of the sequence $F$, see \cite{tsai} for details on the NLFS.
A celebrated open problem, called the nonlinear Carleson problem, is to determine whether $(a_n,b_n)$ converges almost everywhere to $(a,b)$. 
The paper \cite{Poltoratski} suggests the study of the simpler question of almost everywhere convergence of functionals of $(a_n,b_n)$ such as $|a_n|$.
In the $SU(2)$ setting, convergence of 
$\phi_{n_k}^*\ti\phi_{n_k}$
implies 
convergence of 
$|\phi_{n_k} (s)+\ti\phi_{n_k} (s) |^2 $
by \eqref{eq:ortho_polys_det2},
which implies convergence of $|a|$ by \eqref{eq:NLFT_defn_intro}.
However, in the present paper, we are not able to prove very strong results of convergence of
$\phi_{n_k}^*\ti\phi_{n_k}$ and instead address
the even simpler question of convergence of $(\phi_{n_k}^*\ti\phi_{n_k})^2$,
which can  be expressed
as a functional in $(a_{n_k},b_{n_k})$, as done in Theorem \ref{thm:su2}.
Unfortunately, not all
square summable sequences $F_n$
are covered by the techniques in this paper, as the second part of Theorem \ref{thm:su2} shows. The first part of Theorem \ref{thm:su2} gives  sufficient condition for square summable sequences in terms of the NLFS to provide measures $\mu\in \mathcal{T}_-$. In particular,
Theorem \ref{thm:su2} constructively provides an 
interesting class of measures $\mu \in \mathcal{T}_{-}$ to which all the previous Theorems \ref{fejerconvergence}-\ref{thm:lacunary} apply.


\begin{theorem}\label{thm:su2}
\begin{enumerate}[align=left, leftmargin=0pt, itemindent=1em, labelsep=0.2em, nosep]
    \item \label{thm:su2_part1}
  Let $b\in H^\infty (\D)$ vanish at the origin and satisfy
  \begin{equation}\label{su2hyp1}
      \|b\|_{H^\infty(\D)}<2^{-\frac 12}\, .
  \end{equation}
Let $a^*\in H^2(\D)$
   be outer such that for almost every $s\in \T$ 
 \begin{equation}\label{su2hyp2}
     |a(s)|^2+|b(s)|^2=1\, .
  \end{equation} 
   Then there exists
   $(F_n)\in \ell^2(\mathbb{N}_0)$ so that $(a,b)$ is the associated nonlinear Fourier series of $(F_n)$ and $(\phi_n,\ti \phi_n)$ defined by
\eqref{recursion phi}, \eqref{recursion ti phi} 
are the normalized left and right orthogonal polynomials of a measure $\mu \in \mathcal{T}_-$
satisfying \eqref{convabhyp}. Moreover, let $(n_k)$ be a lacunary sequence. For almost every $s\in \T$,
 \begin{equation}\label{su2con}
     \lim_{k\to \infty}
(a_{n_k}^*+b_{n_k})^2(a_{n_k}-b_{n_k}^*)^2(s)=(a^*+b)^2(a-b^*)^2(s)\, .
\end{equation} 
\item \label{thm:su2_part2}
Requirement \eqref{su2hyp1} is sharp, namely there exists an $(F_n)\in \ell^2(\mathbb{N}_0)$ whose associated NLFS $(a,b)$ satisfies $a^* \in H^2 (\D)$ is outer and
\[
\|b\|_{H^{\infty} (\D)} = 2^{- \frac 1 2} \, ,
\]
but the monic polynomials
$(\Phi_n,\ti \Phi_n)$ defined  by \eqref{eq:Szego_recur_intro} are not left and right orthogonal polynomials for any measure $\mu\in \mathcal{T}_-$.
\end{enumerate}
\end{theorem}




