\section{Polynomials generated by a complex measure}\label{polynomials generated by a complex measure}
Let $\mu$ be a complex probability measure on $\T$, i.e., a complex measure with
\[
\int\limits_{\T} d \mu = 1 \, .
\]
Let $f$ and $g$ be polynomials in $z \in \T$.
Recalling definitions \eqref{defquasihilbert} and 
\eqref{stardef},  note 
\begin{equation}\label{mumubar}
    \langle f, g \rangle_{\mu}= \overline{\langle g, f \rangle_{\overline{\mu}}} \, ,
\end{equation} 
\begin{equation} \label{switchstar}
    \langle f, g \rangle_{\mu}=\langle g^*, f^* \rangle_{\mu} \, .
\end{equation}
 By \eqref{mumubar}, a polynomial is right orthogonal with respect to $\mu$ precisely if it is left orthogonal with respect to $\overline{\mu}$. 
 \begin{lemma}\label{unique}
    Let $\mu$ be a complex probability measure on $\T$ and assume that  for each $n\in \mathbb{N}_0$ there exists a left orthogonal monic polynomial $\Phi_n$ of degree $n$. The following statements are equivalent:
\begin{enumerate}
    \item \label{item:inner_prod_nonzero} For each $n\in \mathbb{N}_0$, 
\begin{equation}\label{unique1}
    \langle\Phi_n, z^n\rangle_\mu\neq 0\, .
    \end{equation}
\item \label{item:unique_poly} For each $n\in \mathbb{N}_0$, $\Phi_n$ is the unique degree $n$ left orthogonal monic polynomial.
\item \label{item:det_nonzer}  For each $n \in \mathbb{N}_0$, the matrix determinant
\begin{equation}\label{unique90}
\Delta_n := \det \begin{pmatrix}
    c_0 & c_{-1} & \ldots &  c_{-n} \\
   c_1 & c_0 & \ldots &  c_{-(n-1)}\\
    \vdots & \vdots & \ddots &  \vdots \\ 
   c_{n}  & c_{n-1} & \ldots &  c_0 
\end{pmatrix}
\end{equation}
is nonzero, where $c_{j} := \int\limits_{\T} z^j d\mu$ denotes the $j$-th moment of $\mu$.
\end{enumerate}
In particular, if any of the above hold, then for all $n \geq 1$, we have Heine's formula 
\begin{equation}\label{eq:Heine}
\Phi_n (z) = \frac{1}{\Delta_{n-1}} \det \begin{pmatrix}
   z^n & z^{n-1} & z^{n-2} & \ldots & z & 1 \\
   c_{1} & c_0 & c_{-1} & \ldots & c_{-(n-2)} & c_{-(n-1)} \\
   c_2 & c_1 & c_0 & \ldots & c_{-(n-3)} & c_{-(n-2)}\\
   \vdots & \vdots & \vdots & \ddots & \vdots & \vdots \\ 
   c_n & c_{n-1}  & c_{n-2} & \ldots & c_1 & c_0 
\end{pmatrix} \, .
\end{equation}
    \end{lemma}
\begin{proof}
    Let $\mu$, $\Phi_n$ be given as in the lemma.
We first show that \eqref{item:inner_prod_nonzero} and \eqref{item:unique_poly} are equivalent, by showing each fails if and only if and the other fails. Assume that \eqref{item:unique_poly} fails, i.e., there is $n\in \mathbb{N}_0$ such that
there exists a left orthogonal monic polynomial $\Psi_n\neq \Phi_n$.
We may assume $n$ is minimal for which such  $\Psi_n$ exists. 
 The nonzero polynomial $\Phi_n-\Psi_n$ is left orthogonal
to all polynomials of degree less than $n$. As difference of two monic polynomials, 
it has degree strictly less than $n$, call it $j$. Dividing by its highest coefficient, we obtain a left orthogonal monic polynomial  of degree $j$. By minimality of $n$, this polynomial is equal to $\Phi_j$. We conclude $\langle \Phi_j,z^j \rangle_\mu=0$ as $\Phi_n-\Psi_n$ is left orthogonal to all polynomials of degree less than $n$. Thus \eqref{item:inner_prod_nonzero} fails. 

Now assume that \eqref{item:inner_prod_nonzero} fails, i.e., there is some $n$ for which we have $\langle\Phi_n, z^n \rangle_\mu= 0\, .
$
Then $\Phi_n$ is left orthogonal
to all polynomials of degree $n$, since from
any such polynomial we can subtract a multiple of $z^n$ to obtain a polynomial of lower degree. Then $\Phi_{n+1}+\Phi_n$ 
is a left orthogonal
monic polynomial of degree $n+1$ different from $\Phi_{n+1}$, meaning  \eqref{item:unique_poly} fails. Thus \eqref{item:unique_poly} and \eqref{item:inner_prod_nonzero} are equivalent.

We now show \eqref{item:unique_poly} and \eqref{item:det_nonzer} are equivalent. We assume first that \eqref{item:det_nonzer} holds. Noting that $\Phi_0 = 1$ is unique monic polynomial of degree $0$, let $n \geq 1$. Let 
\begin{equation}\label{unique100}
   \Phi_n ^{k}(z) = z^n + \sum\limits_{j=0}^{n-1} x_j ^k z^j \, , 
\end{equation}
denote two left orthogonal polynomials for $k=1, 2$. Then 
\begin{equation}\label{unique101}
\langle \Phi_n ^k, z^j \rangle_{\mu} = 0 \, , \qquad 0 \leq j\leq n-1 \, .
\end{equation}
Expanding in terms of $(x_j ^k )$, this last condition is equivalent the linear system 
\begin{equation}\label{unique102}
\begin{pmatrix}
   c_0 & c_1 & \ldots & c_{n-1}  \\
   c_{-1} & c_0 & \ldots & c_{n-2}  \\
   \vdots & \vdots & \ddots & \vdots  \\
   c_{-(n-1)} & c_{-(n-2)} & \ldots & c_0  
\end{pmatrix} \begin{pmatrix}
   x_0  \\ x_1  \\ \vdots \\ x_{n-1}   
\end{pmatrix} = - \begin{pmatrix}
    c_n \\ c_{n-1} \\  \vdots \\ c_1
\end{pmatrix}
\end{equation}
having solutions $(x_j ^1)$ and $(x_j ^2)$. 
But the matrix on the left of \eqref{unique102} has nonzero determinant, and hence trivial kernel. Hence $(x_{j} ^1) = (x_j ^2)$, meaning $\Phi_n ^1 = \Phi_n ^2$. Thus \eqref{item:unique_poly} holds.

Now assume \eqref{item:unique_poly} holds, and let $n \geq 1$. Then writing our given left orthogonal polynomial 
\begin{equation}\label{unique103}
   \Phi_n (z) = z^n + \sum\limits_{j=0} ^{n-1} x_j z^j \, , 
\end{equation}
 we have that \eqref{unique102} has a solution. Then $\Delta_{n-1} \neq 0$ if and only if the matrix on the left of \eqref{unique102} has trivial kernel, which holds if and only if \eqref{unique102} has at most one solution. Let $(x_j ^1)$ and $(x_j ^2)$ denote two solutions. Then the polynomials defined in \eqref{unique100} must both be left orthogonal polynomials. By assumption, they must be equal, and hence $(x_j ^1) = (x_j ^2)$. Thus $\Delta_{n-1} \neq 0$. Thus \eqref{item:det_nonzer} holds.

We now prove \eqref{eq:Heine} holds. Let $\Psi_n$ denote the right side of \eqref{eq:Heine}, which is well-defined by \eqref{item:det_nonzer}. By cofactor expansion, $\Psi_n$ is monic of degree $n$. And as for left orthogonality, we note that
\[
\langle \Psi_n, z^j \rangle_{\mu} = \frac{1}{\Delta_{n-1}} \det \begin{pmatrix}
   c_{n-j} & c_{n-1-j} & c_{n-2-j} & \ldots & c_{-(j-1)} & c_{-j} \\
   c_{1} & c_0 & c_{-1} & \ldots & c_{-(n-2)} & c_{-(n-1)} \\
   c_2 & c_1 & c_0 & \ldots & c_{-(n-3)} & c_{-(n-2)}\\
   \vdots & \vdots & \vdots & \ddots & \vdots & \vdots \\ 
   c_n & c_{n-1}  & c_{n-2} & \ldots & c_1 & c_0 
\end{pmatrix}, 
\]
which vanishes if $0 \leq j \leq n-1$, because then the determinant is of a matrix with a repeated row. Thus $\Psi_n$ is a monic left orthogonal polynomial of degree $n$, and by \eqref{item:unique_poly}, it must equal $\Phi_n$. 
\end{proof}




\begin{lemma}\label{lem:Szego_rec_general}
    Let $\mu \in \mathcal{T}$. For each $n\in \mathbb{N}_0$, there exist unique constants $F_{n+1}, \ti F_{n+1} \in \C $ such that we have the Szeg\H o recurrence
    \eqref{eq:Szego_recur_intro}.
    \end{lemma}

\begin{proof}

 Because each $\ti \Phi_n$ is monic,
induction shows that for each $n\in \mathbb{N}_0$ we have
\begin{equation}\label{largespan}
\operatorname{Span} \{1, z, \ldots, z^{n} \}=
\operatorname{Span} \{ \ti \Phi_0,  \ti \Phi_1 , \ldots,   \ti \Phi_{n}  \} \, . \end{equation}
Applying the star operation \eqref{stardef} to \eqref{largespan} for $n-1$ and multiplying by $z^n$ gives
\begin{equation}\label{smallspan}
\operatorname{Span} \{z^n, z^{n-1}, \ldots, z^{1} \}=
\operatorname{Span} \{z^n \ti \Phi_0 ^*, z^n \ti \Phi_1 ^*, \ldots, z^{n}  \ti \Phi_{n-1} ^* \}.    
\end{equation}
Because both $\Phi_{n+1}$ and $z \Phi_n$ are monic polynomials of degree $n+1$,
  their difference is a polynomial of degree $n$. Let $F_{n+1}$ denote the coefficient of the constant term of this polynomial,
then
\begin{equation}\label{expanddifference}
\Phi_{n+1} - z \Phi_n -\overline{F_{n+1}} z^n \ti \Phi_n ^* = \sum\limits_{j=0}^{n-1} d_j z^n \ti \Phi_j ^* \, ,\end{equation}
because the left side is in the space  \eqref{smallspan}. 
Let $0 \leq \ell \leq n-1$ and pair \eqref{expanddifference}
from the right with $z^n \Phi^*_\ell$ to obtain
\begin{equation}\label{expand1}
\langle \Phi_{n+1},z^n\Phi^*_\ell\rangle_\mu
- \langle z \Phi_n ,z^n\Phi^*_\ell\rangle_\mu -\overline{F_{n+1}} \langle  z^n \ti \Phi_n ^* ,z^n\Phi^*_\ell\rangle_\mu = \sum\limits_{j=0}^{n-1} d_j 
\langle z^n \ti \Phi_j ^*,z^n\Phi^*_\ell\rangle_\mu  \, ,\end{equation}
The first term on the left side of \eqref{expand1} vanishes
because  $\Phi_{n+1}$ is left orthogonal and $z^{n}\Phi^*_\ell$ is a polynomial of degree less than $n+1$.  
Similarly, the second term vanishes because we can divide both factors in the pairing by $z$
and $z^{n-1}\Phi^*_\ell$
is a polynomial of degree less than $n$. The pairing in the third term can be rewritten with \eqref{switchstar} as  
\begin{equation}\label{expand2}
 \langle  z^n \ti \Phi_n ^* ,z^n\Phi^*_\ell\rangle_\mu
 =\langle   \ti \Phi_n ^* ,\Phi^*_\ell\rangle_\mu
 =\langle  \Phi_\ell,
 \ti \Phi_n \rangle_\mu=0\, ,
\end{equation}
where we have used right orthogonality of $\ti \Phi_n$.
By the analogous computation as \eqref{expand2}, most terms on the right side of \eqref{expand1} vanish and we obtain
\begin{equation}\label{expand3}
 0
 = d_\ell \langle  \Phi_\ell,
 \ti \Phi_\ell \rangle_\mu\, .
\end{equation}
By Lemma \ref{unique}, we obtain $d_\ell=0$. As $0\le \ell\le n-1$ was arbitrary,  identity \eqref{expanddifference} becomes the first Szeg\H o relation in \eqref{eq:Szego_recur_intro}.
The second relation is shown analogously, switching the roles of left and right. Uniqueness of $F_n$ and $F_{n+1}$ follows because the polynomials on the right side of the 
Szeg\H o relations \eqref{eq:Szego_recur_intro} are nonzero.

\end{proof}



In what follows, we employ the convention that a product indexed by the empty set equals $1$.
\begin{lemma}\label{lem:phiortho}
If $\mu\in \mathcal{T}_-$, then for all $n \geq 0$, we have 
\begin{equation}\label{eq:norm_poly_potential}
\langle \Phi_n , \ti \Phi_n \rangle_{\mu}  =  \prod\limits_{j=1}^n (1 + |F_j|^2)  \, . 
\end{equation}

\end{lemma}
\begin{proof}
    From the Szeg\H o recurrence \eqref{eq:Szego_recur_intro}, it follows that for  $n \geq 0$, we have
\begin{equation}\label{eq:pre_Szego_recursion}
\begin{pmatrix}
    \frac{\Phi_{n+1}}{z^{n+1}} & - \left ( \frac{ \ti \Phi_{n+1}}{z^{n+1}} \right )^* \\ \frac{\ti \Phi_{n+1}}{z^{n+1}} & \left ( \frac{\Phi_{n+1}}{z^{n+1}} \right )^*
\end{pmatrix} = \begin{pmatrix}
    \frac{\Phi_{n}}{z^{n}} & - \left ( \frac{\ti \Phi_{n}}{z^{n}} \right )^* \\ \frac{\ti \Phi_{n}}{z^{n}} & \left ( \frac{\Phi_{n}}{z^{n}} \right )^*
\end{pmatrix} \begin{pmatrix}
    1 &  F_{n+1} z^{n+1}\\
    - \overline{F_{n+1}} z^{-(n+1)} & 1 
\end{pmatrix} \, .
\end{equation}
Taking determinants and applying induction with 
the initial condition $\Phi_0 = \ti \Phi_0 =1$, which follows from the monic assumption, gives for  $n \geq 0$,
\begin{equation}\label{eq:det_polys}
\Phi_n \Phi_n ^* + \ti \Phi_n (\ti \Phi_n) ^* = 2 \prod\limits_{j=1}^n (1 + |F_j|^2) \, .
\end{equation}
Integrating \eqref{eq:det_polys} with respect to the probability measure $\mu$ on $\T$ yields
\begin{equation}\label{eq:Phi_det_integrate}
\langle \Phi_n ,  \Phi_n \rangle_{\mu}+
\langle \ti \Phi_n , \ti \Phi_n \rangle_{\mu}
 = 2 \prod\limits_{j=1}^n (1 + |F_j|^2) \, .
\end{equation}
But $\Phi_n$ and $\ti \Phi_n$ are left and right orthogonal, respectively, to the polynomial $\ti \Phi_n - \Phi_n$ because it has degree at most $n-1$, and therefore
\begin{equation}\label{eq:norms_Phi_inner_prod}
\langle \Phi_n ,  \Phi_n \rangle_{\mu} = \langle \Phi_n , \ti \Phi_n \rangle_{\mu}  = 
\langle \ti \Phi_n , \ti \Phi_n \rangle_{\mu} 
\end{equation}
Identities \eqref{eq:Phi_det_integrate} and \eqref{eq:norms_Phi_inner_prod} yield
\eqref{eq:norm_poly_potential}, which proves the lemma.
\end{proof}
With Lemma \ref{lem:phiortho} and left-orthogonality of $\Phi_n$, we have
\[
\langle \Phi_n, \ti \Phi_n \rangle_{\mu} =  \langle \Phi_n, z^n \rangle_{\mu} \neq 0 \, .
\]
Thus we define the normalized polynomials
 \begin{equation}\label{defphi}
     \phi_n = \frac{\Phi_n}{\sqrt{\langle \Phi_n , \ti \Phi_n \rangle_{\mu}}} \, ,  \qquad \ti \phi_n = \frac{\ti \Phi_n}{\sqrt{\langle \Phi_n , \ti \Phi_n \rangle_{\mu}}}\, .
 \end{equation}
 They inherit from $\Phi_n$, $\ti \Phi_n$ and Lemma \ref{lem:phiortho} the orthonormality relation \eqref{orthonormal} thanks to the normalization of $\mu$ as probability measure, and using in addition 
 Lemma \ref{lem:Szego_rec_general}, we see that they also satisfy the recursion relations $\phi_0=\ti \phi_0=1$
  and 
\begin{equation}\label{recursion phi}
    \phi_{n+1} = \frac{1}{\sqrt{1+|F_{n+1}|^2}} \left( z\phi_n + z^n \overline{F_{n+1}} \ti \phi_n^* \right) \, ,
\end{equation}
\begin{equation}\label{recursion ti phi}
    \ti \phi_{n+1} = \frac{1}{\sqrt{1+|F_{n+1}|^2}} \left( z\ti \phi_n - z^n \overline{F_{n+1}} \phi_n ^* \right) \, .
\end{equation}
Rewriting the recursion \eqref{recursion phi}, \eqref{recursion ti phi} as a matrix product gives
\begin{equation}\label{phirecursion}
   \phimat_{n+1} (z) =\phimat_n (z) \zmat^{1-n} \fmat_{n+1} \zmat^{1+n}
\end{equation}
with the matrices
\begin{equation}
    \phimat_n (z) =2^{-\frac 12}
   \begin{pmatrix}
       \phi_{n} (z) & -\ti {\phi_{n}}^* (z) \\
       \ti \phi_{n} (z) & \phi_{n}^* (z)
    \end{pmatrix}
\end{equation}
\begin{equation}
    \fmat_n=\frac 1{\sqrt{1+|F_n|^2}}\begin{pmatrix} 1 & F_n\\ -\overline{F_n } & 1\end{pmatrix}\ ,
\end{equation}
\begin{equation}\label{defzmat}
    \zmat = \begin{pmatrix} z^{\frac 1 2} & 0\\ 0 & z^{-\frac 12} \end{pmatrix}\ .
\end{equation}
The square root of $z$ in the definition of $\zmat$ is to be understood formally in the sense that
$\zmat$ will always appear 
with an accumulated even power
in a product, so that the resulting product can be rewritten
involving only integer powers of $z$.




With the Hadamard gate
\begin{equation}
    \hmat= 2^{-\frac 12}\begin{pmatrix}
       1 & -1\\
       1 & 1
    \end{pmatrix}\, ,
\end{equation}
we have the initial condition $\phimat_0=\hmat$ and thus can
solve the recursion \eqref{phirecursion} as
\begin{equation}\label{phiproduct}
    \phimat_n=\hmat \prod_{0<j\le n} ^{\curvearrowright}\zmat^{2-j} \fmat_j\zmat^{j}=\hmat \left ( \prod_{0<j\le n} ^{\curvearrowright} \zmat \fmat_j \right  )\zmat^{n} \, ,
\end{equation}
where we use the directed product notation
\[
\prod_{a< j\le b} ^{\curvearrowright} M_{j} :=  M_{a+1}\ldots M_{b-1} M_b \, .
\]
Because for $z\in \T$, we have $\hmat, \zmat, \fmat_j$ are all unitary with determinant $1$, then by \eqref{phiproduct} the product $\phimat_n$ must be as well. Taking the determinant of $\phimat_n$ thus yields for $s\in \T$, 
\begin{equation} \label{eq:ortho_polys_det2}
    |\phi_n (s) |^2+|\ti\phi_n (s) |^2=2\, .
\end{equation}
We note the following Plancherel type inequality
\begin{lemma}\label{lem:plancherel}
Let $l,m\in \mathbb{N}_0$ with $l<m$. We have   
\begin{equation}\label{plancon}
-2\int\limits_\T \log(\frac 12|\phi_l^*\phi_m+\ti \phi_l^* \ti \phi_m|)
\le \sum_{l<j\le m} \log(1+|F_j|^2)\, .
\end{equation}

\end{lemma}
\begin{proof}
    We have with \eqref{phiproduct}
\begin{equation}\label{plan1}
\phimat_l^{-1}\phimat_m=\zmat^{-l}\left ( \prod_{l<j\le m} ^{\curvearrowright} \zmat \fmat_j \right )\zmat^m\, .
    \end{equation}
    The upper left entry 
\begin{equation}\label{u(z)=}
     u(z):=\frac 12 \left(\phi_l^*\phi_m+\ti \phi_l^* \ti \phi_m\right)(z)
\end{equation}    
   of the left side of 
\eqref{plan1} is a linear combination of monomials $z^k$ for $k \in \ZZ$. Counting powers of $z$
on the right side of \eqref{plan1}, each such monomial $z^k$ is a product of a factor $z^{-\frac l2}$, then $m-l$ factors of which each is  $z^{1/2}$ or $z^{-1/2}$ and then
one factor of $z^{m/2}$.
The lowest possible power $k$ is then $0$, meaning $u$ is a polynomial in $z$. The coefficient in front of $z^0$ can have only 
second row factors of the matrices $\zmat \fmat_j$
and thus is the product of lower right entries of the matrices $\zmat \fmat_j$. 
Evaluating $u$ at $0$ to obtain the constant term, we
have
\begin{equation}
    \frac 12 \left(\phi_l ^* \phi_m+\ti \phi_l ^* \ti \phi_m \right)(0)
=\prod_{l<j\le m} (1+|F_j|^2)^{-\frac 12}\, .
\end{equation}
Using that the 
polynomial  is analytic on $\mathbb{D}$ and 
thus  the logarithm of its modulus is subharmonic, we obtain
\begin{equation}\label{plan2}
\int\limits_\T \log(\frac 12 |\phi_l^*\phi_m+\ti \phi_l^* \ti \phi_m|)
\ge 
\log(\frac 12 |\phi_l^*\phi_m+\ti \phi_l^* \ti \phi_m|)(0)=
-\frac 12 \sum_{l<j\le m} \log(1+|F_j|^2)\, .
\end{equation}
This proves \eqref{plancon} and hence the lemma.
\end{proof}









\begin{lemma}[Christoffel-Darboux formula]\label{christoffeldarboux}
For all $n\in \mathbb{N}_0$ and all $\lambda \neq 0$, we have
\begin{equation}\label{eq:CD}
        (1-z \lambda^{-1}) K_n(z, \lambda) =
     { z^{n+1} \lambda}^{-n-1} \phi_{n+1}^*(z) {\ti \phi_{n+1}(\lambda)}    - \ti\phi_{n+1}(z) {\phi_{n+1}^*(\lambda)} \, .
    \end{equation}
\end{lemma}

\begin{proof}
Define for a complex parameter $\lambda$ the matrices
\begin{equation}
    \qmat:=\begin{pmatrix}
       0 & 1\\
       0 & 0
    \end{pmatrix}\, , \ 
\Lambda := \begin{pmatrix}
\lambda^{\frac 1 2} & 0 \\ 0 & \lambda^{ - \frac 1 2}
\end{pmatrix} \, ,
\end{equation}
where the remarks after the definition \eqref{defzmat} of $\zmat$ also apply analogous to $\Lambda$. Define 
\begin{equation}\label{kn1}L_n(z, \lambda)=2\lambda^{-\frac{n+1}2}z^{\frac{n+1}2}
\tr(\Lambda^{n+1}\phimat_{n+1}^{-1}(\lambda)\qmat \phimat_{n+1}(z) \zmat^{-n-1})
        \ .
\end{equation}  
The innermost triple product of matrices in \eqref{kn1} is
a tensor of the first column of $\phimat^{-1}_{n+1}(\lambda)$ with the second row of $\phimat_{n+1}(z)$ and thus 
\begin{equation}\label{kn10}
    \phimat_{n+1}^{-1}(\lambda)\qmat \phimat_{n+1}(z)=\frac 12\begin{pmatrix}
        \phi_{n+1}^*(\lambda)\ti \phi_{n+1}(z) & { \phi_{n+1}^*(\lambda)}\phi_{n+1}^*(z) \\
    -\ti \phi_{n+1}(\lambda) \ti \phi_{n+1}(z) & -{\ti \phi_{n+1}(\lambda)}\phi_{n+1}^*(z)
    \end{pmatrix}\, .
\end{equation}
With that we compute
$L_n(z, \lambda)$ to be the negative of the right side of \eqref{eq:CD}, and so we will be done once we verify that $L_n(z, \lambda)$ also coincides with the left side of \eqref{eq:CD}.
Note that $L_{-1}( z, \lambda)=0$.
Peeling off one factor in the product \eqref{phiproduct}, we observe
\begin{equation}\label{kn2}
    \Lambda^{n+1}\phimat_{n+1}^{-1}(\lambda)\qmat \phimat_{n+1}(z) \zmat^{-n-1}=
    \fmat_{n+1}^{-1}\Lambda^{-1}\Lambda^{n}\phimat_{n}^{-1}(\lambda)Q \phimat_{n}(z) \zmat^{-n}\zmat\fmat_{n+1}\, .
\end{equation}
  As the trace is invariant under conjugation by a matrix, we obtain\begin{equation}\label{kn3}L_n(z, \lambda)=2\lambda^{-\frac{n+1}2}z^{\frac{n+1}2}
    \tr(\Lambda^{n-1}\phimat_{n}^{-1}(\lambda)\qmat \phimat_{n}(z) \zmat^{-n+1})
        \ .
\end{equation}  
Comparing \eqref{kn3} with $n+1$ and \eqref{kn1} with $n$, we compute for $n\ge -1$
\begin{equation*}%\label{kn4}
    L_{n+1}(z, \lambda)-L_n(z, \lambda)=
\end{equation*}    
\begin{equation*} %\label{kn5}
2 { \lambda^{-\frac{n+2}2}z^{\frac{n+2}2}}{\tr(\Lambda^{n}\phimat_{n+1}^{-1}(\lambda)\qmat \phimat_{n+1}(z) \zmat ^{-n})}   
\end{equation*}
\begin{equation*}%\label{kn6}
-2
{\lambda^{-\frac{n+1}2}z^{\frac{n+1}2}}
{\tr(\Lambda^{n+1}\phimat_{n+1}^{-1}(\lambda)\qmat \phimat_{n+1}(z) \zmat ^{-n-1})}
\end{equation*}
\begin{equation}\label{kn7}
=2
{\tr\left(
\left(
{\lambda^{-\frac{n+2}2}z^{\frac{n+2}2}} \operatorname{Id}-
{\lambda^{-\frac{n+1}2}z^{\frac{n+1}2}}\Lambda Z^{-1}
\right)
\Lambda^{n}\phimat_{n+1}^{-1}(\lambda)\qmat \phimat_{n+1}(z) \zmat ^{-n}\right)}
\end{equation}
by linearity of the trace and invariance of the trace under conjugation. 
Finally, because the diagonal matrix
\[
\lambda^{- \frac 1 2 } z^{\frac 1 2} \operatorname{Id} -  \Lambda \zmat^{-1}
\]
vanishes at its bottom right entry, then 
\eqref{kn7} becomes  the upper left entry of
\begin{equation}\label{kn8}
2\left(
{\lambda^{-\frac{n+2}2}z^{\frac{n+2}2}}-
{\lambda^{-\frac{n}2}z^{\frac{n}2}}
\right)
\Lambda^{n}\phimat_{n+1}^{-1}(\lambda)\qmat \phimat_{n+1}(z) \zmat ^{-n}
\end{equation}
which, by \eqref{kn10}, is equal to
\begin{equation}\label{kn80}
\left(
{\lambda^{-1}z-1}
\right)
\phi_{n+1} ^* (\lambda)\ti \phi_{n+1} (z) \, .
\end{equation}
By telescoping and then \eqref{reprokernel}, we obtain
\begin{equation} \label{kn9}
    L_n(z, \lambda)=\sum\limits_{\ell=0}^{n} L_{\ell}(z, \lambda) - L_{\ell-1}(z, \lambda)
    =\sum\limits_{\ell=0}^{n} (\lambda^{-1} z-1) \phi_{\ell} ^* (\lambda) \ti \phi_{\ell} (z)= \left(\lambda^{-1}z-1
\right)K_n(\lambda , z)\, ,
\end{equation}
which is the left side of \eqref{eq:CD}.
\end{proof}








%We also have the following Christoffel-Darboux identity.\begin{lemma}\label{christoffeldarboux}   Let $\mu \in \mathcal{T}_{-}$. Then   \begin{equation}\label{eq:CD}     K_n(\lambda,z) =     \frac{ \bar{\lambda}^{n+1} \overline{\ti\phi_{n+1}^*(\lambda)} z^{n+1} \phi_{n+1}^*(z)  - \ti\phi_{n+1}(z)\overline{\phi_{n+1}(\lambda)}}   {1 - \bar\lambda z} \, .   \end{equation}\end{lemma}





The relation \eqref{eq:NLFT_defn_intro} can be written as
\begin{equation}\label{eq:polys_full_prod_formula}
    \gmat_n=\hmat^{-1} \phimat_n \zmat^{-2n} 
\end{equation}
with the matrix
\begin{equation}\label{define}
    \gmat_n=\begin{pmatrix}
    a_n & b_n \\ - b_n^* & a_n^*
\end{pmatrix}
\end{equation}
The product representation \eqref{phiproduct} then gives
\begin{equation}\label{gproduct}
    \gmat_n= \left ( \prod_{0<j\le n} ^{\curvearrowright}\zmat \fmat_j \right ) \zmat^{-n} \, ,
\end{equation}
or equivalently
\begin{equation}\label{gproduct1}
    \gmat_n= \prod_{0<j\le n} ^{\curvearrowright}\zmat ^j\fmat_j\zmat^{-j} \, .
\end{equation}
The latter is the representation of the $SU(2)$- nonlinear Fourier series in \cite{tsai},
\begin{equation}\label{tsai}
     G_n=\prod_{0<j\le n} ^{\curvearrowright} \frac{1}{\sqrt{1 + |F_{j}|^2}}\begin{pmatrix}
    1 & F_{j} z^{j} \\ -\overline{ F_{j}} z^{-j} & 1
\end{pmatrix}\, .
\end{equation}

In the proof of Theorem \ref{thm:su2}  we will refer to facts about the $SU(2)$-valued NLFS in  \cite{tsai, QSP_NLFA}, 
such as if $(F_n)\in \ell^2$, then 
$G_n$ has an entry-wise limit 
\[
G = \begin{pmatrix}
    a & b \\ -b^* & a^*
\end{pmatrix}
\]
in the sense of $L^2(\T)$ which turns out also in $H^2(\D)$
for the second column of $G_n$. We will also use that
\begin{equation}\label{eq:a_positive}
a_n ^* (0) \, , \qquad a^* (0) >0 \, .
\end{equation}














\section{Proof of Theorem \ref{fejerconvergence}}

Let $\mu \in \mathcal{T}_{-}$
and let $C\ge 2$. In what follows, $B(s,r)$ denotes the ball with radius $r$ and center $s$.
\begin{lemma}\label{lem:poly_bd_gen}
Let $n\ge 1$. The functions $f,g,h,k$ defined by
\begin{equation}\label{eq:poly_bds_gen}
f(z)=\phi_n(z) \, , \quad  g(z)=\tilde{\phi_n}(z) \, , \quad h(z)= z^n \phi_n^*(z) \, , \quad  k(z) = z^n \tilde{\phi_n} ^* (z) \, , 
\end{equation}
are polynomials of degree at most $n$
 and bounded by $\sqrt{2}$ on $\D$ and by $e^{2C}$ on the ball $B(0, 1 + C/n)$. 
\end{lemma}

\begin{proof}
Because $\phi_n$ and $\ti \phi_n$ are polynomials of degree $n$, then $f,g, h, k$ are polynomials of degree at most $n$. 
By \eqref{eq:ortho_polys_det2}, the polynomials 
    $f, g, h, k$
 are bounded by $\sqrt{2}$ for $z$ on $\T$ and by the maximum
principle also for $z$ in the unit disc $\D$.
Now assume  $1 \leq |y| \leq 1 + \frac{C}{n}$. Then, with $z=\overline{y^{-1}} \in \D$, and using the bound of $|h(z)| \leq \sqrt{2}$, we have
\[
|f(y)| = |\phi_n(y)|= |\phi_n^*(z)| =  |y^n z^n \phi_n^*(z)|
 = |h(z)y ^n |\leq \sqrt{2}|y|^n \leq \sqrt{2} \left ( 1 + \frac{C}{n} \right )^n \leq  e^{2C} \, .
\]
This along with a similar argument for $g, h, k$, using the bound of $k$, $f$, $g$ by $\sqrt{2}$ on $\mathbb{D}$,   respectively, completes the proof of the lemma.
%To see the derivative bounds, we can dispense with the $n=0$ case since then $f,g,h, k$ are all constant and have derivative $0$. So assume $n \geq 1$. Note that by Cauchy's integral formula, the derivative of an entire function at a point is bounded by $r^{-1}$ times the supremum of the function itself on a disc of radius $r$ about the point. Applying this with a disc of radius $\frac Cn$ and using the poinwise bounds of the functions established earlier with $2C$ in place of $C$ proves the derivative bounds.
\end{proof}



\begin{lemma}\label{lem:kbounds}
    Let $s\in \T$
     and let $n  \geq 2 C$. For all $x \in B(0, 1 + C/n)$ and $y\in B(s,C/n)$,  we have the estimate  \begin{equation}\label{kernel estiamte K}
        |K_n(x, y)| \leq e^{12C} \min (n+1,|s-x|^{-1}) \, . 
    \end{equation}
%\ct{do we need this?}If in addition   $y' \in B(0, 1 + C/n)$ with $2|y-y'|<|s-y|$, then
% \begin{equation} \label{kernel estiamte K diff}    |K_n(x, y) - K_n(x, y') | \leq C' |y-y'|\min(n, |s-y|^{-1}) \, . \end{equation}

    \end{lemma}
    \begin{proof}
     The representation \eqref{reprokernel} of $K_n$ as sum of $n+1$ products of normalized one-sided orthogonal polynomials and Lemma \ref{lem:poly_bd_gen} give the estimate 
\begin{equation}\label{kernel estiamte K first}
        |K_n(x, y)| \leq  e^{4C} (n+1)\, . 
    \end{equation}
To verify \eqref{kernel estiamte K}, it remains to show
\begin{equation}\label{kernel estiamte K 2}
        |K_n(x, y)| \leq   {e^{12C}}{|s-x|^{-1}} \, .  
    \end{equation}
    If 
    \[
    |s-x| \leq 2C n^{-1} \, ,
    \]
    then \eqref{kernel estiamte K first} implies \eqref{kernel estiamte K 2}. Thus it suffices to show \eqref{kernel estiamte K 2} when  
\begin{equation}\label{cd3}
 |s-x|\ge {2C}n^{-1} \, . 
\end{equation}
  The Christoffel-Darboux formula \eqref{eq:CD} gives for $K_n(x,y)$ the estimate
\begin{equation}\label{darbouxxy}
    |y^n (y-x)| | K_n (x,y)| = |x^{n+1}\ti\phi_{n+1}(y) \phi_{n+1}^*(x)  - y^{n+1}\ti\phi_{n+1}(x){\phi_{n+1}^*(y)}| \leq 2 e^{8C} \, ,
\end{equation}
where in the last step we apply Lemma \ref{lem:poly_bd_gen} with index $n+1$ and constant $2C$.
The first term on the left of \eqref{darbouxxy},
multiplied by $e^{3C}$, we estimate from below with \eqref{cd3}
\begin{equation*}
 e^{3C}\left |y^n(x-y) \right | \ge e^C(1+2Cn^{-1})^n(1-Cn^{-1})^n ||y-s|-|x-s||\, . 
\end{equation*}
Noting that $2|y-s|\le |x-s|$ by \eqref{cd3}, we have the lower bound 
\begin{equation} \label{eq:CD_denom_estimate}
  e^{3C}\left |y^n(x-y) \right | \ge (1+Cn^{-1}-2(Cn^{-1})^2)^n  \left |s-x \right |
 \ge \left |s-x \right |\, ,\end{equation}
 where in the last step we used $n\ge 2C$.
The estimates \eqref{darbouxxy} and \eqref{eq:CD_denom_estimate} show \eqref{kernel estiamte K 2} and complete the proof of the lemma.

%\ct{do we need this?}

%We turn to the proof of \eqref{kernel estiamte K diff}

%The proof is similar to the above. Namely, we must prove two estimates for the difference on the left of \eqref{kernel estiamte K diff}. The first estimate follows by proving a derivative analogue of Lemma \ref{lem:poly_bd_gen} to bound on the derivatives of our polynomials using the Cauchy integral formula, and then summing in $n$. The second estimate follows from a uniform bound on the derivative of the kernel when $|y-s| \geq \frac{8C}{n}$. We can get a good estimate using the Christoffel-Darboux formula \eqref{eq:CD}.





\end{proof}







We now prove Theorem \ref{fejerconvergence}. Assume $s\in E(\mu)$. Let $n \geq 2C$ and $z, \lambda \in B(s, \frac{C}{n})$. 
Thanks to \eqref{mumubar}
and \eqref{switchstar}, the 
polynomials $\phi_n$ and $\ti \phi_n$ switch roles of left and right orthogonal polynomials when passing from
$\mu$ to $\overline{\mu}$. With the definition \eqref{reprokernel} of the reproducing kernel we thus obtain
for the  kernel $\ti K_n$ associated to $\overline{\mu}$:
\begin{equation}
    \ti K_n (z, \lambda) = {K_n^*(\lambda, z)}\, .
\end{equation}
The reproducing  property \eqref{reproducing}, first for $\ti K_n$ and then $D_n$, yields 
\begin{equation}\label{cd10}
   {D_n (z, \lambda)} = { \int\limits_{\T}  {{D}_n (y, \lambda) }  \ti K_n ^* (y, z) d\overline{\mu} (y)} 
\end{equation}
\[
= \int\limits_{\T} K_n (z, y)  D_n (y,\lambda) \left ( d  \overline{ \mu} (y) - \overline{w(s)} \meas{y} \right )  +  \overline{w(s)} {\int\limits_{\T} {K_n (z,y)   D_n (y, \lambda)} \meas{y} }
\]
\[
= \int\limits_{\T} K_n (z,y)  {D}_n ( y, \lambda) \left ( d  \overline{\mu} (y) - \overline{w(s)} \meas{y} \right )  + \overline{w(s)} {K_{n} (z, \lambda)} \, .
\]
Rewriting the left side of \eqref{eq:KLbound}
with \eqref{cd10} and then estimating with Lemma \ref{lem:kbounds}, which analogously holds for $D_n$, gives\begin{equation}\label{firstthm1}
    \frac{1}{n+1}| \overline{w(s)} K_n (z, \lambda) - D_n (z, \lambda)|
    \end{equation}
    \begin{equation*}\leq  \frac{1}{n+1}\int\limits_{\T} |K_n (z,y)|  |D_n (y,\lambda)| \left | d \mu (y) - w(s) \meas{y} \right | 
\end{equation*}
\[
\leq e^{24C} \int\limits_{\T} \min \left \{ n+1, \frac{1}{(n+1)|y-s|^2} \right \}  \left | d \mu (y) - w(s) \meas{y} \right |  \, .
\]
This completes the proof of Theorem \ref{fejerconvergence}.



\section{Local parameters, first estimates}
\label{sec:lpfe}



Let $\mu\in \mathcal{T}_-$.
We prove some estimation and  approximation lemmas for local parameters $A_{n,s},B_{n,s},  \ti A_{n,s},\ti B_{n,s}$ 
of the normalized one sided orthogonal polynomials. These local parameters are  
sums and differences over shifts by a $2n$-th root of unity: define $A_{n,s}$ and $B_{n,s}$ as in \eqref{def:A_B_n}, and for $\gamma_n$ as in \eqref{gamman}, define the analogous
    \begin{equation}\label{def:ti A_B_n}
        \ti A_{n,s} := \frac{\ti \phi_n(s)-\ti \phi_n(s\gamma_n)}{2s^n} \, , \qquad 
    \ti B_{n,s} := \frac{\ti \phi_n(s)+\ti \phi_n(s\gamma_n)}{2} \, . 
    \end{equation}
Let $s\in E(\mu)$. As $s$ will be fixed throughout the section, 
we abbreviate notation by  omitting the subscript $s$ in
 \eqref{def:A_B_n} and 
 \eqref{def:ti A_B_n}.
Note that Lemma \ref{lem:poly_bd_gen} implies the bound \begin{equation}\label{eq:bd_A_B}
     |A_n|, |B_n |, |\ti A_n|, |\ti B_n |\leq \sqrt{2}   \, .  
    \end{equation}

The local parameters $A_n, B_n$ provide a local approximation of $\phi_n$ around $s$. 
\begin{lemma}[Local approximation of polynomials]\label{approximation with A B C D}
Let $C\geq 4$ and $4C\le n$ and $|z-s|\le C/n$. Then
    \begin{equation}\label{eq lemma abcd}
        \left| \phi_n(z) - A_nz^n-B_n \right|  \le   e^{36C} L(\mu,s,n)\, . 
    \end{equation}
\end{lemma}
\begin{proof}
Let $C$, $n$, and $z$ be given as in the lemma. Define $y:=\overline{z^{-1}}$. Note that 
\begin{equation}\label{upperlowerz}
  \frac 34\le |z|, |y|\le  \frac 43 \ .  
\end{equation}
Using the lower bound on $|z|$ and the fact that $|s|=1$, we estimate
\begin{equation}\label{ysestimate}
    |1-ys^{-1}|=|y-s| = |\overline{z^{-1}} - \overline{s^{-1}} | = \frac{|\overline{s}-\overline{z}|}{|\overline{sz}|} \le 2C/n \, ,
\end{equation} which also implies
\begin{equation}\label{ysgammaestimate}
    |1-y(s\gamma_n)^{-1}| \leq |y||1-\gamma_n| + |1-ys^{-1}| \leq \frac{4}{3} \pi/n + 2 C/n \leq 4 C/n \, ,
\end{equation}
By Theorem \ref{fejerconvergence}, each of the three expressions
\begin{equation}\label{eq:CD_conv_zs_2}
-\overline{ w  (s)}K_{n-1} (y, s) +  D_{n-1} (y,s)\, ,
\end{equation}
\begin{equation} \label{eq:CD_conv_zgamma_2}
    -\overline{ w  (s)}K_{n-1} (y,s \gamma_n) + D_{n-1} (y, s\gamma_n)\, ,
    \end{equation}
\begin{equation} \label{eq:CD_conv_sgamma_2}
    -\overline{ w  (s)}K_{n-1} (s, s \gamma_n)+ D_{n-1} (s, s \gamma_n) \end{equation}
is bounded in absolute value by 
\[
 n e^{31C} L(\mu,s,n) \, .
\]
By the Christoffel-Darboux formula of Lemma \ref{christoffeldarboux} applied to $K_n$ and $D_n$, and the bounds \eqref{ysestimate} and \eqref{ysgammaestimate} to estimate the left-most terms in \eqref{eq:CD},
each of the three expressions 
\begin{equation}\label{eq:CD_conv_zs}
\overline{ w  (s)}[\ti \phi_n (y) \phi_n ^* (s) - y^n s^{-n} \phi_n^*(y) \ti\phi_n (s)] +  (1-y^n s^{-n} )
\end{equation}
\begin{equation} \label{eq:CD_conv_zgamma}
    \overline{ w  (s)}[\ti \phi_n (y) \phi_n ^* (s\gamma_n) + y^n s^{-n} \phi_n^*(y) \ti\phi_n (s\gamma_n)] + (1+y^n s^{-n} )
    \end{equation}
\begin{equation} \label{eq:CD_conv_sgamma}
    \overline{ w  (s)}[ \ti \phi_n (s) \phi_n ^* (s\gamma_n) +  \phi_n^*(s) \ti\phi_n (s\gamma_n)] + 2 \end{equation}
is bounded in absolute value by 
\[
4C e^{31 C} L(\mu,s,n) \leq e^{32C} L(\mu,s,n) \, .
\]
We multiply \eqref{eq:CD_conv_zs} by  $\phi_n ^* (s\gamma_n )$, \eqref{eq:CD_conv_zgamma} by $-\phi_n ^* (s)$
and \eqref{eq:CD_conv_sgamma} by $s ^{-n} y^n \phi_n ^* (y)$,  and then sum up the three terms.
Note that all terms arising in square brackets cancel: the first summand in brackets of \eqref{eq:CD_conv_zs} cancels
the first summand in brackets of \eqref{eq:CD_conv_zgamma}, the second summand in brackets in \eqref{eq:CD_conv_zs} cancels the 
first summand in \eqref{eq:CD_conv_sgamma}, while 
the second summand in brackets in \eqref{eq:CD_conv_zgamma} cancels the
second summand in  \eqref{eq:CD_conv_sgamma}.

Using Lemma \ref{lem:poly_bd_gen} and the triangle inequality, we obtain
\[ |(1-y^n s^{-n} )\phi_n ^* (s\gamma_n )-(1+y^n s^{-n})\phi_n ^* (s)+2s ^{-n} y^n \phi_n ^* (y)|
\leq  e^{35C} L(\mu,s,n) \, .
\]
Rewriting $y$ in terms of $z$ and conjugating inside the absolute value signs gives
\[ |(1-z^{-n} s^{n} )\phi_n (s\gamma_n )-(1+z^{-n} s^{n})\phi_n  (s)+2s ^{n} z^{-n} \phi_n (z)|
\leq e^{35C} L(\mu,s,n)\, .
\]
Finally, we multiply both sides by $\frac{s^{-n} z^n}{2}$, which is bounded by $e^{C}$, to obtain
\[ |  2^{-1} (s ^{-n} z^{n}-1 )\phi_n (s\gamma_n )- 2^{-1} (s ^{-n} z^{n}+1)\phi_n  (s)+ \phi_n (z)|
\leq e^{36C} L(\mu,s,n) \, .
\]
This is \eqref{eq lemma abcd} by definition of $A_n$ and $B_n$, which proves Lemma \ref{approximation with A B C D}.
\end{proof}



\begin{lemma}\label{lem:liminf_A_B_nonzero}
    Let $n\ge 40$.  We have
\begin{equation}\label{sum squares ab}
|A_n|^2+|B_n|^2+|\ti A_n|^2+|\ti B_n|^2 =2 \, .
\end{equation}

\begin{equation}\label{product ab}
|A_n  \overline{B_n} + \ti A_n \overline{\ti B_n}| \leq e^{372} L(\mu, s, n)    
\end{equation}

\begin{equation}\label{difference ab square}
 \left | -\ti A_n \overline{A_n} +    \ti B_n \overline{B_n} + \frac{1}{\overline{w (s)}} \right |
\leq  e^{370} L (\mu, s, n) \, .   
\end{equation}    
\end{lemma}
\


\begin{proof}
Note \eqref{sum squares ab} follows from the determinant identity \eqref{eq:ortho_polys_det2}, since we compute
\[
2(|A_n|^2 + |B_n|^2 + |\ti A_n|^2 + |\ti B_n|^2) = |\phi_n (s)|^2 + |\ti \phi_n(s)|^2 +  |\phi_n (s \gamma_n)|^2 + |\ti \phi_n(s \gamma_n )|^2 = 4 \, .
\]

Set $C=10$, and note $n \geq 4C$. 
If for some complex numbers $X,Y$, we have  $|X-Y|  < M$, then 
\[
| |X|^2 - |Y|^2 |  = ||X| - |Y| | (|X| + |Y|) \leq M (|X| + |Y|)\, .
\]
This with the local approximation Lemma \ref{approximation with A B C D} and the  bounds \eqref{eq:bd_A_B} gives  for $t\in B(s,C/n) \cap \T$
\[
| |A_n t^n + B_n|^2 - |\phi_n|^2 | \leq e^{365} L (\mu, s, n) \, .
\]
Using the analogous inequality for $\ti \phi_n$,  the triangle inequality, and  the identity  \eqref{eq:ortho_polys_det2} for the sum of squares of $\phi_n$, $\ti \phi_n$, gives
\begin{equation}\label{eq:approx_det_id}
| |A_n t^n + B_n|^2 + |\ti A_n t^n + \ti B_n|^2 -2| \leq e^{370} L(\mu, s, n) \, .
\end{equation}
Using \eqref{sum squares ab}, the left side of \eqref{eq:approx_det_id} can be written as
\begin{equation}\label{two real part}
    \left|2 \Re (t^n (
  A_{n} \overline{ B_{n}} + \ti{A_{n}} \overline{\ti B_{n}} )) \right|\ .
\end{equation} 
 Inequality \eqref{product ab} follows by picking $t$ so that 
 \[
   \Re (t^n (
  A_{n} \overline{ B_{n}} + \ti{A_{n}} \overline{\ti B_{n}} )) = A_{n} \overline{B_{n}} + \ti{A_{n}} \overline{\ti B_{n}} \, ,
\]
which is possible as $t^n$ takes all values in $\T$ on any arc of $\T$ of length 
$2\pi/n$. 
Taking a limit in \eqref{eq:CD_conv_sgamma} while using upper bounds of Lemma \ref{lem:poly_bd_gen}
on $|\phi_n|$ $|\ti \phi_n|$  by $\sqrt{2}$ on $\T$
shows $|w(s)|>1/4$.
Thus dividing   \eqref{eq:CD_conv_sgamma} by $\overline{w}(s)$, we obtain
\[
| \ti \phi_n (s) \phi_n ^* (s\gamma_n) +  \phi_n^*(s) \ti\phi_n (s\gamma_n) + \frac 2{\overline{ w (s)}}| \leq e^{325} L(\mu, s, n) \, .
\]
Using the upper bounds on $\phi_n$ and $\ti \phi_n$
again and 
 the definition of $A_n$ and $B_n$
\[
| (\ti A_n s^n + \ti B_n)  (  -\overline{A_n}s^{-n} + \overline {B_n} ) +  (\overline{A_n}s ^{-n} + \overline{B_n} ) ( -\ti A_n s^{n} + \ti B_n) + \frac{2}{\overline{w(s)}}| 
\leq e^{370} L(\mu, s, n) \, .
\]
As the cross terms on the left side vanish, dividing by $2$ we obtain \eqref{difference ab square}.
\end{proof}

\begin{lemma}\label{lem:lwr_bd_w}
 We have $|w(s)|\ge 1\, .$
\end{lemma}
\begin{proof}
We have for $n\ge 40$,
using firstly \eqref{difference ab square} and secondly \eqref{sum squares ab}:
\begin{equation}\label{betterw1}
 |w(s)|^{-1}\le |A_n \ti A_n|+ |B_n \ti B_n| + e^{370}L(\mu, s,n) 
\end{equation}
\begin{equation*}\label{betterw2}
= 1- \frac 12(|A_n|- |\ti A_n|)^2- \frac 12 (|B_n|- |\ti B_n|)^2 +e^{370}L(\mu, s,n) 
\le 1+e^{370}L(\mu, s,n)\ \, .
\end{equation*}
Taking a limit as $n$ tends to $\infty$ proves the lemma.
\end{proof}



The following two lemmas say that only the $A$'s or the $B$'s can be small, and whichever is small determines whether $ \phi_n ^* \ti \phi_n $ is close to $-\overline{w(s)^{-1}}$ or $\overline{w(s)^{-1}}$.

\begin{lemma}\label{abtocdlem}

Let $0<\eta \le \frac 12$.
Let $n_0\ge 40$ be large enough so that for $n\ge n_0$ we have 
    \begin{equation}\label{abtocd1}
        e^{1000}L(\mu,s,n)\le \eta |w(s)|^{-2} \, .
    \end{equation}
Let $n\ge n_0$.
Let $(C,D,\ti C, \ti D)$ be one of the four tuples
\begin{equation*}
 (|A_n|,|B_n|,|\ti A_n|,|\ti B_n|)\, , \ (|\ti A_n|,|\ti B_n|, |A_n|, |B_n|)\, , 
\end{equation*}
\begin{equation*}
 (|B_n|,|A_n|,|\ti B_n|,|\ti A_n|)\, , \ (|\ti B_n|,|\ti A_n|, |B_n|, |A_n|)\, .
\end{equation*}
If
\begin{equation}\label{abtocdhyp}
 \eta \le C\le (8|w(s)|)^{-1}   \, ,
\end{equation}
then
\begin{equation}\label{abtocdcon1}
 (4|w(s)|)^{-1}  \le \ti D  \le 2\, ,
\end{equation}
\begin{equation}\label{abtocdcon2}
  (4|w(s)|)^{-1} \le  D  \le 2\, ,
\end{equation}
\begin{equation}\label{abtocdcon3}
(9|w(s)|)^{-1}{C} \le  \ti C\le (9|w(s)|){C}   \, .
\end{equation}

\end{lemma}
\begin{proof}
Throughout the proof, we shall freely use the upper bounds on $C,D,\ti C, \ti D$ by $2$ from \eqref{eq:bd_A_B}.
The triangle inequality with \eqref{difference ab square}, the assumed upper bound in \eqref{abtocdhyp} and the lower bound on $|w|$ in Lemma \ref{lem:lwr_bd_w} gives
 \begin{equation}\label{abtocd2}
        (2|w(s)|)^{-1}\le D\ti D \, .
    \end{equation}
This implies \eqref{abtocdcon1} and \eqref{abtocdcon2}.
By \eqref{product ab} and the lower bounds  \eqref{abtocdhyp} and \eqref{abtocdcon2}, we obtain    
\begin{equation}\label{abtocd4}\left|\frac {CD}{\ti D}-\ti C \right| \le  e^{-100} C |w(s)|^{-1}\, .
    \end{equation}
Using \eqref{abtocdcon1}, \eqref{abtocdcon2} and the lower bound on $|w|$ from Lemma \ref{lem:lwr_bd_w}, we obtain \eqref{abtocdcon3}.
\end{proof}

\begin{lemma}\label{smallablem}
    Let $0<\eta<10^{-10} |w(s)|^{-2}$.
    Let $n_0\ge 40$ be large enough so that for $n\ge n_0$ we have 
\begin{equation}\label{smallabhyp1}
e^{1000}L(\mu,s,n)\le \eta^2 \, .
    \end{equation}
Let $n\ge n_0$. If $|A_n|<\eta^2$ or $|\ti A_n| <\eta^2$, then
\begin{equation}\label{smallabcon1}
\left| \phi_{n} ^* (s)\ti \phi_{n} (s)  +
\overline{w(s)^{-1}}\right|\le \eta \, .
\end{equation}
If $|B_n|<\eta^2$ or $|\ti B_n| <\eta^2$, then
\begin{equation}\label{smallabcon2}
\left|\phi_{n} ^* (s)\ti \phi_{n} (s) -
\overline{w(s)^{-1}}\right|\le \eta \, .
\end{equation}
\end{lemma}

\begin{proof}



 Assume first $|A_{n}|\le \eta^2$.
 Lemma \ref{abtocdlem}, and then the upper bound on $|w|^{-1}$ from Lemma \ref{lem:lwr_bd_w}, imply 
\[
|\ti A_{n}| \leq 9|w(s)| |A_n| \leq 10 |w(s)| \eta^2 \leq 10^{-8}\eta \, .
\]
Then \eqref{difference ab square}  implies
\begin{equation}\label{subs101}
\left|\ti B_{n} \overline{B_{n}}+
\overline{w(s)^{-1}}\right|\le 10^{-4}\eta \, .
\end{equation}
With the local approximation Lemma \ref{approximation with A B C D}, we obtain \eqref{smallabcon1}.
If instead $|\ti A_{n}|\le \eta^2$,
 Lemma \ref{abtocdlem} 
implies $| A_{n}|\le 10^{-8}\eta$ and we obtain 
again \eqref{subs101} and 
\eqref{smallabcon1}.
Assume now $|B_{n}|\le \eta^2$. Lemma \ref{abtocdlem} 
implies $|\ti B_{n}|\le 10^{-8}\eta$ and \eqref{difference ab square} implies
\begin{equation}\label{subs210}
\left|\ti A_{n} \overline{A_{n}}-
\overline{w(s)^{-1}}\right|\le 10^{-4}\eta \, .
\end{equation}
Now the local approximation Lemma \ref{approximation with A B C D} gives \eqref{smallabcon2}. Similarly,
if  $|\ti B_{n}|\le \eta^2$,
we conclude $| B_{n}|\le 10^{-8}\eta$ and obtain 
\eqref{subs203} and \eqref{smallabcon2}. This completes the proof of the lemma.

\end{proof}



\section{Local parameters, refined estimates}

\label{sec:lpre}

The estimates in this section will be used in the second
part of Theorem \ref{thm:conv_to_AB}.
We continue to fix $\mu\in \mathcal{T}_-$ and $s\in E(\mu)$. The next two lemmas consider the case the left side of \eqref{product ab} is small, i.e., in what follows one should take $(a,b,c,d) = (A_n, B_n, \ti A_n, \ti B_n)$ and $\epsilon = e^{372} L(\mu,s,n)$.

\begin{lemma}\label{abcdlem}
    Let $\epsilon,\eta>0$. Let $a,b,c,d$ be complex numbers 
    bounded below in absolute value by $\eta$ and above in absolute value by $2$.
Assume
\begin{equation}\label{abcdhyp}
    |a\overline{b}+c\overline{d}|\le \epsilon\, .
\end{equation}
Then 
\begin{equation}\label{abcdcon}
    \left||\overline{a}c-\overline{b}d|- (|ac|+|bd|)\right|\le
    4\eta^{-1} \epsilon\, .
\end{equation}
\end{lemma}

\begin{proof}
We multiply the left side of \eqref{abcdcon} by $|a|$
and then apply the triangle inequality with \eqref{abcdhyp} 
twice to obtain
\begin{equation*}
    \left||a\overline{a}c-a\overline{b}d|- (|a^2c|+|abd|)\right|
\end{equation*}
\begin{equation}\label{abcd01}
   \le  \left||a\overline{a}c+c\overline{d}d|- (|a^2c|+|cd^2|)\right|+ 2|d|\epsilon =2|d|\epsilon\, .
\end{equation}
Using $|d|\le 2$ and $|a|\ge \eta$ proves \eqref{abcdcon}
and completes the proof of the lemma.
\end{proof}













\begin{lemma}\label{4abcdlem}
    Let $\epsilon >0$ and $a,b,c,d$ be reals 
    bounded above by $\sqrt{2}$. If both 
\begin{equation}\label{4abcdhyp1}
        a^2+b^2+c^2+d^2=2
    \end{equation}
    and
\begin{equation}\label{4abcdhyp2}
    |ab-cd|\le \epsilon\, ,
\end{equation}
then
\begin{equation}\label{4abcdcon}
    \left|(ac+bd)^2(ad+bc)^2- 4abcd\right|\le 1000 \epsilon\, .
\end{equation}
\end{lemma}
\begin{proof}
From \eqref{4abcdhyp1}, it suffices to prove 
\begin{equation}\label{4abcd1}
    |(ac+bd)^2(ad+bc)^2- (a^2+b^2+c^2+d^2)^2abcd|\le 1000\epsilon\, .
\end{equation}
Expanding terms, sorting the binomial expressions to
account first for pure squares and then mixed terms gives
for the polynomial inside the absolute values
\begin{equation}\label{4abcd2}
     a^4 c^2 d^2+ a^2 b^2 c^4 + a^2 b^2 d^4+ b^4 c^2 d^2
\end{equation}
\begin{equation}\label{4abcd3}
    + (a^2c^2  +  b^2d^2 +  a^2d^2 +  b^2 c^2) (2abcd)
\end{equation}
\begin{equation}\label{4abcd4}
    + 4(abcd)^2
  \end{equation}
\begin{equation}\label{4abcd5}
    - (a^4 + b^4 + c^4 + d^4)(abcd)
\end{equation}
\begin{equation}\label{4abcd6}
    - (a^2b^2 + a^2c^2+a^2d^2+b^2c^2+b^2d^2+c^2d^2)(2abcd) .
\end{equation}
Thanks to hypothesis \eqref{4abcdhyp2} and the upper bound on $a,b,c,d$, 
we may replace $abcd$ in each individual summand by $(ab)^2$ or $(cd)^2$ as 
we desire, up to an error of at most $64\epsilon$.

Therefore, up to such error, the four terms in \eqref{4abcd2}
match up with the four terms in \eqref{4abcd5}. Thus these two lines differ by at most $256\epsilon$.

Furthermore, four of the six terms in \eqref{4abcd6} match up
exactly with the four terms in \eqref{4abcd3} and thus cancel.
The remaining two terms in \eqref{4abcd6}, again up to an error of 
$64\epsilon$, each match with half of \eqref{4abcd4}.
This proves \eqref{4abcd1} and thus \eqref{4abcdcon},
completing the proof of the lemma.

\end{proof}

\begin{lemma}\label{approx with zeros}
   Let $0<\eta< 2^{-1}$,
   and $n\geq 400$. Assume $\eta \le |A_n|,|B_n|,|\ti{A}_n|,|\ti{B}_n|$. Then
\begin{equation}\label{eq:square_prod_An_zeros1}
\left |
(|\ti A_n A_n| +|\ti{B}_n B_n|)^2 - \frac{1}{|w|^2} \right |\leq \eta^{-1} e^{385} L(\mu,s,n)\, ,
\end{equation}

\begin{equation}\label{eq:solve_r_w_poly1}
\left| 4 \left(\left| \frac{A_n \ti{B}_n}{B_n \ti{A}_n}\right|^{\frac 12}+ \left|\frac{B_n \ti{A}_n}{A_n \ti{B}_n}\right|^{\frac 12}\right)^{-2}  - \frac{1}{|w|^2} \right | \leq \eta^{-4} e^{400} L(\mu,s,n) \, .
\end{equation}


\end{lemma}
\begin{proof}

We first prove \eqref{eq:square_prod_An_zeros1}.
Applying Lemma \ref{abcdlem} to \eqref{product ab}  gives
\begin{equation}\label{abcdappl}
\left |
|\overline{A_n} \ti{A}_n- \overline{B}_n \ti {B}_n|
- (|A_n \ti{A}_n|+|B_n\ti{B}_n| ) \right|\le \eta^{-1}
e^{375} L(\mu, s, n)    .
\end{equation}
Applying further 
\eqref{difference ab square}
with the triangle inequality gives with $\eta<2^{-1}$
\begin{equation}\label{abcdappl2}
\left |
|A_n \ti{A}_n|+|B_n\ti{B}_n| -\frac 1{|w(s)|}\right|\le \eta^{-1}
e^{380} L(\mu, s n)  \, .
\end{equation}
With $|w(s)|\ge 1$ from Lemma \ref{lem:lwr_bd_w} and the upper bound on $A_n, B_n, \ti A_n, \ti B_n$ from \eqref{eq:bd_A_B}, multiplying Inequality \eqref{abcdappl2} by
\begin{equation*}%\label{abcdappl2}
|A_n \ti{A}_n|+|B_n\ti{B}_n| +\frac 1{|w(s)|}\le 5  \, ,
\end{equation*}
we obtain \eqref{eq:square_prod_An_zeros1}, thus completing this part of the proof.

Next, we prove \eqref{eq:solve_r_w_poly1}.
By \eqref{eq:square_prod_An_zeros1} and the triangle inequality,
it suffices to prove
\begin{equation}\label{eq:square_ratios}
\left |
(|\ti A_n A_n| +|\ti{B}_n B_n|)^2 - 4 
\left(\left| \frac{A_n \ti{B}_n}{B_n \ti{A}_n}\right|^{\frac 12}+ \left|\frac{B_n \ti{A}_n}{A_n \ti{B}_n}\right|^{\frac 12}\right)^{-2}
\right |\leq  \eta^{-4} e^{395} L(\mu,s,n)\, .
\end{equation}
Using
\begin{equation}\label{auxaabb}
    \eta^2\le |B_n\ti{A}_n|+|A_n \ti{B}_n| \, ,
\end{equation}
it suffices to prove 
\begin{equation}\label{eq:square_ratios2}
\left |
(|\ti A_n A_n| +|\ti{B}_n B_n|)^2
(|B_n\ti{A}_n|+|A_n \ti{B}_n|)^2- 4 \left|{A_n \ti{B}_n}{B_n \ti{A}_n}\right|\right|\leq e^{395} L(\mu,s,n)\, .
\end{equation}
This however follows from applying Lemma \ref{4abcdlem} 
to $(a,b,c,d) = (|A_n|, |B_n|, |\ti A_n|, |\ti B_n|)$,
 using \eqref{sum squares ab} and
\eqref{product ab} 
to verify the assumptions of Lemma \ref{4abcdlem}.
 This completes the proof of  \eqref{eq:solve_r_w_poly1}
and thus the proof of Lemma \ref{approx with zeros}.

\end{proof}








The following lemma basically says in \eqref{abybcon} that $|A_n \ti B_n|$ and $|\ti A_n B_n|$ are roughly comparable.
\begin{lemma}\label{abyblem}
Let $0 < \eta < 10^{-10}|w(s)|^{-2}$ and let $n_0>400$ be large enough so that for $n\ge n_0$ we have 
    \begin{equation}\label{abybhyp1}
        e^{1000}L(\mu,s,n)\le \eta ^8 \, .
    \end{equation}
Let $n>n_0$. Let $(C,D,\ti C,\ti D,\sigma)$ be one of the tuples
\[({A_n},{B_n}, {\ti A_n}, \ti B_n,1)\, , \ 
(\overline{\ti A_n},\overline{\ti B_n}, \overline{A_n}, \overline{B_n},1)\, , \]
\[
({B_n},{A_n}, {\ti B_n}, \ti A_n,-1)\, , \ (\overline{\ti B_n},\overline{\ti A_n}, \overline{B_n}, \overline{A_n},-1)\, . 
\]
Assume both 
\begin{equation}\label{abybhyp2}
    \eta\le |C|\le 10^{-10}|w(s)|^{-2}\, ,
\end{equation}
\begin{equation}\label{abybhyp3}
\left|  \phi_n^*(s)\ti \phi_n(s)+\sigma \overline{w(s)^{-1}}\right|\le  \eta^5\, .
\end{equation}
Then
\begin{equation}\label{abybcon}
    \frac 1 4  \le \left|\frac DC \right| \left|1-\left|\frac{C\ti D}{\ti CD}\right|\right|\le 4 \, .
\end{equation}
\end{lemma}
\begin{proof}
Throughout the proof, we shall freely use the upper bounds  \eqref{eq:bd_A_B}
as well as the upper bounds of $|\phi_n(s)|$ and $|\ti\phi_n(s)|$  by $2$ 
by \eqref{eq:ortho_polys_det2}. 

Assumption \eqref{abybhyp3} and the local approximation Lemma \ref{approximation with A B C D} applied with constant $4$ give
\begin{equation}\label{abyb1}
\left|   \overline{A_{n}} \ti A_{n} +\overline{B_{n}} \ti B_{n} +  \overline{A_{n}}  \ti B_{n} s^{- n} + \ti A_{n} \overline{B_{n}} s^{n} +\sigma \overline{w(s)^{-1}}\right|\le  10\eta^5 \, .    
\end{equation}
This can be rewritten with suitable  $\tau\in \{-1,1\}$ as 
\begin{equation}\label{abyb2}
\left|   \overline{C} {\ti C} +\overline{D} \ti D +  \overline{C}  \ti D s^{-\tau n} + \ti C \overline{D} s^{\tau n} +\sigma \overline{w(s)^{-1}}\right|\le  10\eta^5 \, .    
\end{equation}
Using \eqref{difference ab square}, which may be rewritten as
\begin{equation} \label{difference ab square CD}
\left | -\ti C \overline{C} + \ti D \overline{D} + \sigma \overline{w^{-1}} \right | \leq e^{370} L(\mu,s,n)
\end{equation}
we obtain from \eqref{abyb2} that
\begin{equation}\label{abyb3}
\left|   2\overline{C} {\ti C}  +  \overline{C}  \ti D s^{\tau n} + \ti C \overline{D} s^{-\tau n} \right|\le  20\eta^5 \, .    
\end{equation}
Dividing by $\overline{C} \ti C$ and using Assumption \eqref{abybhyp2} and Lemma \ref{abtocdlem}, we obtain
\begin{equation}\label{abyb4}
 \left| 2 + \frac{{\ti D}}{\ti C } s^{\tau n} + \frac{\overline{D}}{ \overline{C} }s^{ -\tau n} \right|\le  10^{-5} \, .
\end{equation}
By \eqref{product ab}, which may be written as
\[
\left |C \ti C + D \ti D \right | \leq e^{372} L(\mu, s,n) \, ,
\]
and Lemma \ref{abtocdlem}, we have
\begin{equation}\label{abyb5}
\left|\frac{\ti C \overline{\ti D}}{C \overline{D}}
+1\right|,
\left|\left|\frac{\ti C \overline{\ti D}}{C \overline{D}}\right|
-1\right|
\le \eta^5 \, .
\end{equation}
Hence, applying Lemma \ref{abtocdlem} with \eqref{abyb5}, 
\begin{equation}\label{abyb6}
\left|\left|\frac{C \ti D}{\ti C D}\right|+\frac {C \ti D}{\ti C D}\right|\le 
\left|\left|\frac{C \ti D}{\ti C D}
\frac{\ti C \overline{\ti D}}{C \overline{D}}\right|-\frac{C \ti D}{\ti C D}
\frac{\ti C \overline{\ti D}}{C \overline{D}}
\right|+\eta^2= \eta^2  \, .
\end{equation}
Using \eqref{abyb6} in \eqref{abyb4} gives
\begin{equation}\label{abyb7}
 \left| 2 - \left|\frac{C \ti D}{\ti C D}\right|\frac{{ D}}{ C } s^{ \tau n} + \frac{\overline{D}}{ \overline{C} }s^{ -\tau n} \right|\le  10^{-4} \, .
\end{equation}
Separating real and imaginary part in \eqref{abyb7} gives
\begin{equation}\label{abyb8}
 \left| 2 - \left(\left|\frac{C \ti D}{\ti C D}\right|-1\right)
 \Re \left(\frac{{ D}}{ C } s^{ \tau n}\right) \right|\le  10^{-4} \, ,
\end{equation}
\begin{equation}\label{abyb9}
 \left| \left(\left|\frac{C \ti D}{\ti C D}\right|+1\right)
 \Im \left(\frac{{ D}}{ C } s^{ \tau n}\right) \right|\le  10^{-4} \, .
\end{equation}
Inequalities \eqref{abyb8} and \eqref{abyb9} together with \eqref{abyb5} show that the imaginary part of $(D/C) s^{\tau n}$ is less than $10^{-2}$ times the real part: indeed, using first \eqref{abyb8}, then \eqref{abyb9} and finally \eqref{abyb5}, we compute
\[
10^{4} \left | \Im \left(\frac{{ D}}{ C } s^{ \tau n}\right) \right  | \leq 1  \leq  (2 - 10^{-4}) \leq  \left | \left|\frac{C \ti D}{\ti C D}\right|-1\right |
 \left | \Re \left(\frac{{ D}}{ C } s^{ \tau n}\right) \right | \leq  \eta^{5} \left | \Re \left(\frac{{ D}}{ C } s^{ \tau n}\right) \right | \, .
\] 
Hence the ratio between real part and absolute value of $(D/C)s^{\tau n}$ is between $9/10$ and $10/9$.
Thus by \eqref{abyb5} and \eqref{abybhyp1}, in \eqref{abyb8} we can replace the real part of $(D/C) s^{\tau n}$ by its absolute value to get
\begin{equation}\label{abyb10}
 \left| 2 - \left | \left|\frac{C \ti D}{\ti C D}\right|-1\right |
 \left | \frac{{ D}}{ C } \right| \right|\le  10^{-3} \, ,
\end{equation} which  implies \eqref{abybcon} and completes the proof of the lemma.

\end{proof}


\begin{lemma}\label{abclem}

Let $0<\eta \leq 10^{-10} |w(s)|^{-2}$ and let $n_0>400$ be large enough so that for $n\ge n_0$ we have \begin{equation}\label{abchyp1}
e^{1000}L(\mu,s,n)\le \eta ^8 \, .
    \end{equation}
Let $n>n_0$. 
Let $(C,\sigma)$ be one of the tuples $(A_n,1)$, $(B_n,-1)$, $(\overline{\ti A_n}, 1)$, $(\overline{\ti B_n},-1)$. 
If $|w(s)|>1$, assume
\begin{equation}\label{abchyp2}
 \eta \le |C|\le 10^{-10}|w(s)|^{-2}\min(1,|w(s)|-1)   \, .
\end{equation}
If $|w(s)|=1$, assume
\begin{equation}\label{abchyp3}
 \eta \le |C|\le 10^{-10}\, .
\end{equation}
Then 
\begin{equation}
    \label{abccon}
    \eta^5 \le \left|\phi_n^*\ti \phi_n+ \sigma {\overline{w(s)^{-1}}}\right|\le (2|w(s)|)^{-1}
    %<|w(s)|^{-1} \le \left|\phi_n^*\ti \phi_n-\sigma {\overline{w(s)^{-1}}}\right|
  \, .
\end{equation}
\end{lemma}

\begin{proof}

Given $(C,\sigma)$
as in the lemma, we consider the unique completion to a tuple
$(C,D,\ti C, \ti D,\sigma)$ as listed in Lemma \ref{abyblem}.
By  \eqref{difference ab square}, or equivalently \eqref{difference ab square CD}, as well as \eqref{abchyp1}, \eqref{abchyp2}, and \eqref{abchyp3},  we have
\begin{equation}\label{abc3}
\left| \ti D\overline{D}+\sigma \overline{w(s)^{-1}}\right|\le (20|w(s)|)^{-1}\, .
\end{equation}
By the local approximation Lemma \ref{approximation with A B C D} applied with constant $4$ and the Lemma \ref{abtocdlem}, we obtain from \eqref{abc3} 
\begin{equation}\label{abc4}
\left|\ti \phi_n(s)  \phi_n^*(s)+\sigma \overline{w(s)^{-1}}\right|\le (10|w(s)|)^{-1} \, .
\end{equation}
%Hence, with the triangle inequality,
%\begin{equation}\label{abc5}
%\left| \ti \phi_n(s) \phi_n^*(s)- \sigma \overline{w(s)}^{-1}\right|\ge |w(s)|^{-1}
%\, .\end{equation}
%Estimates \eqref{abc4} and \eqref{abc5} show two of the inequalities in \eqref{abccon}. 
This shows one inequality in  \eqref{abccon}. 
To prove  the other inequality, assume to get a contradiction that
\begin{equation}\label{abc6}
\left|  \phi_n^*(s)\ti \phi_n(s)+\sigma \overline{w(s)^{-1}}\right|\le  \eta^5\, .
\end{equation}
Set
\begin{equation}\label{abc10}
    t:= \left| {C \ti D }{ (\ti C D)^{-1}}\right|\,  
\end{equation}
and apply Lemma \ref{abyblem} to obtain
\begin{equation}\label{abc60}
    4^{-1}\le |DC^{-1}||1-t|\le 4\, .
\end{equation}
By \eqref{eq:solve_r_w_poly1}, we have
\begin{equation}\label{abc11}
|4( t+2+t^{-1})^{-1}  - |w(s)|^{-2}|\le \eta^6\, .\, 
\end{equation}
Note that as $\eta \to 0$, we have $\max(t,t^{-1})$ goes to $v:=\mathrm{exp}(2 \mathrm{arccosh}(|w|))$. In what follows, we now analyze three different cases one after the other: the case when $t$ is very far from $1$ and $v$, the case when $t$ is close to $1$ but nearer to $v$, and then the case where $t$ is very close to $1$. 
Assume first $|w(s)|>1.01$.
Then \eqref{abc11} gives $\max(t,t^{-1})>1.001$ and thus 
\begin{equation}\label{abc43}
|t-1|>10^{-4} \, .
\end{equation}
But then \eqref{abc60} gives $|DC^{-1}|\le 10^5$. This gives a contradiction
with 
\eqref{abchyp2}, and \eqref{abchyp1} and
Lemma \ref{abtocdlem}.
Assume next $1<|w(s)|\le 1.01$.
Then \eqref{abc11} gives $\max(t,t^{-1})<1.1$ and thus 
\begin{equation}\label{abc44}
|t-1|<0.2 \, .
\end{equation}
We obtain from \eqref{abc11}
\begin{equation}\label{abc45}
|4|w(s)|^2-t-2-t^{-1}|\le \eta^5 \, ,
\end{equation}
or equivalently
\begin{equation}\label{abc47}
|4(|w(s)|+1)(|w(s)|-1)-{(t-1)^2}t^{-1}|\le \eta^5 \, .
\end{equation}
It follows, using the bound on $\eta$ from \eqref{abchyp2}, that
\begin{equation}\label{abc48}
|t-1|\ge (|w(s)|-1)^\frac 12\ge |w(s)|-1 \, .
\end{equation}
Then \eqref{abc60} gives $|DC^{-1}|\le 10(|w(s)|-1)^{-1}$. This gives a contradiction
with 
\eqref{abchyp2}, and \eqref{abchyp1} and
Lemma \ref{abtocdlem}.
Finally, assume $|w(s)|=1$.
Then \eqref{abc11} implies
\begin{equation}\label{abc61}
|t-1|\le \eta^3
\end{equation}
Then \eqref{abc60} gives $|DC^{-1}|\ge 4^{-1} \eta^{-3}$.
This gives again a contradiction
with 
\eqref{abchyp3}, and \eqref{abchyp1} and
Lemma \ref{abtocdlem},
and completes the proof of the lemma.






\end{proof}




\section{Proof of Theorem \ref{thm:conv_to_AB}}

Once again, we freely use the upper bounds \eqref{eq:ortho_polys_det2} on the normalized orthogonal polynomials and \eqref{eq:bd_A_B} on the local parameters in this section.

We now prove that \eqref{subshyp1} implies \eqref{subscon1}.
Let $\mu\in \mathcal{T}_-$, let $s\in E(\mu)$, and let $(n_k)$ be a monotone increasing sequence of natural numbers. Assume that \eqref{subshyp1} holds, we show
\eqref{subscon1}.
Let $0<\epsilon<10^{-10} |w(s)|^{-2}$.
By Lebesgue differentiation and
assumption \eqref{subshyp1}, there is $k_0$ such that for all $k>k_0$
\begin{equation}
    \label{subs100}
    e^{1000}L(\mu, s,n)\, ,\  \min(|A_{n_k}|,|B_{n_k}|)\le \epsilon^6\, .
\end{equation}
Let $k>k_0$. By Lemma \ref{smallablem}, we obtain
\begin{equation}\label{subs102}
\min \left ( \left| \phi_{n_k}^* (s) \ti \phi_{n_k} (s)  +
\overline{w(s)^{-1}}\right|,
\left|\phi_{n_k}^* (s) \ti \phi_{n_k} (s) -
\overline{w(s)^{-1}}\right| \right )
\le \epsilon^2 \, .
\end{equation}
With the binomial formula and upper bound $|w^{-1}|\leq 1$ from Lemma \ref{lem:lwr_bd_w}, we obtain
\begin{equation}\label{subs103}
\left| ( \phi_{n_k} ^* (s) \ti\phi_{n_k} (s) )^2 -
\overline{w(s)^{-2}}\right|
\le \epsilon \, .
\end{equation}
As $\epsilon$ was arbitrarily small, we obtain \eqref{subscon1}.
This completes the proof of the first part of Theorem \ref{thm:conv_to_AB}.
Before turning to the second part, we prove some auxiliary lemmas. In what follows, we let $|E|$ of a set $E \subset \T$ denote its arclength. Note that
\[
|E| = \int\limits_{\T} \mathbf{1}_{E} \, d|s| = 2 \pi \int\limits_{\T} \mathbf{1}_E \, , 
\]
since the last integral denotes the mean value of $\mathbf{1}_E$ on $\T$.

\begin{lemma}\label{phiphi}
    Let $a,b,c,d,z,y,x,v$ be complex numbers bounded in absolute value by $2$. Let $J$ be an arc on $\T$.
    Let $m,n$ be  positive integers with  
\begin{equation}\label{phiphihyp}
        10^7|J|^{-1}\leq m,n,|m-n|,|2m-n|, |m-2n|\, .
    \end{equation}
   Then  
   \begin{equation}
       \label{phiphicon}
       \int\limits_J ||a s^m+ b|| c s^{-m}+  d|- |z s^n+y|| x s^{-n}+ v|| \,  d|s|\,  \ge 
10^{-2} \min(|ab|,|cd|,|zy|,|xv|)^4|J|\, . 
   \end{equation}
\end{lemma}
\begin{proof}
Define, for $s\in \T$,
\begin{equation}\label{phiphi2}
   o(s):= |a s^m+ b|^2| c s^{-m}+ d|^2- |z s^n+y|^2|x s^{-n}+v|^2
    \, .
\end{equation}
Expanding squares, we obtain  for some real number $k$
depending on $a$ through $v$ and with dots representing
analogous expressions with letters $z,y,x,v$
\begin{equation}\label{phiphi3}
   o(s)= (|a|^2+|b|^2+ a\overline{b}s^m+b\overline{a}s^{-m})
   (|c|^2+|d|^2+ d\overline{c}s^m+c\overline{d}s^{-m})-(\dots)
\end{equation}
\begin{equation}\label{phiphi4}
   o(s)= a\overline{b}\overline{c}d s^{2m}+(|a|^2\overline{c}d+|b|^2\overline{c}d+ 
   a\overline{b}|c|^2+a\overline{b}|d|^2)s^m 
\end{equation}
\begin{equation*}
  \ + (|a|^2c \overline{d} +|b|^2c \overline{d} + 
   \overline{a}b|c|^2+\overline{a}b|d|^2)s^{-m} + \overline{a}bc\overline{d}s^{-2m}-(\dots)+k\, .
\end{equation*}
 Note that \eqref{phiphi4} expands into 21 summands. We expand the square modulus $o(s)\overline{o(s)}$ into the sum of 21  diagonal terms,
    where each such term is a summand of
    \eqref{phiphi4} multiplied by its own complex conjugate, and  420 off diagonal terms.
The diagonal terms add up to $2K^2+k^2$, where $K$ is defined by
\begin{equation}\label{phiphi1}
    K^2= |a|^2|b|^2 |c|^2|d|^2+(|a|^4+|b|^4) |c|^2|d|^2 +|a|^2|b|^2(|c|^4+|d|^4) +(\dots)\, .
\end{equation}
%\begin{equation*}
%    +|z|^2|y|^2 |x|^2|v|^2+(|z|^4+|y|^4) |x|^2|v|^2 +|z|^2|y|^2(|x|^4+|v|^4)\, .
%\end{equation*}
Estimating the 420 off diagonal terms from above,
using that each of the 20 coefficients in
\eqref{phiphi4}
other than $k$  can be estimated in absolute value by $K$, gives by the reverse triangle inequality

\begin{equation}\label{phiphi5}\int\limits_{J} |o|^2 \, d|s| \ge 2K^2|J| + k^2|J|
-380K^2\left(\sum_{-2\le h,j\le 2, h^2+j^2\neq 0} |\int\limits_J s^{hn+jm} \, d|s| |\right)
\end{equation}
\begin{equation*}
-20|k|K\left(\sum_{-2\le h\le 2, h\neq 0} |\int\limits_J s^{hn} \, d|s||\right)
-20|k|K\left(\sum_{-2\le j\le 2, j\neq 0} |\int\limits_J s^{jm} \, d |s||\right)
\end{equation*}
Note that the integrands in \eqref{phiphi5} are powers of $s$, which oscillate with frequency at least $|J| 10^{-7}$ on $\T$ by Assumption \eqref{phiphihyp}. For any integral within \eqref{phiphi5}, we can reduce the domain of integration $J$ by any disjoint union of arcs on which the integrand undergoes exactly one full period, all without changing the value of the integral. Using this to reduce the domains of integration to an arc of size smaller than one full period, which by Assumption \eqref{phiphihyp} has arclength less than 
$10^{-6}|J|$, we  obtain
with trivial estimates on these integrals
\begin{equation}\label{phiphi6}
  \int\limits_{J} |o|^2 \, d|s| \ge (2K^2 + k^2- 380 K^2 10^{-6} -  40 |k|K 10^{-6})|J|\ge K^2|J| \, .
\end{equation}
With the assumed upper bound on $a,b,c,d,z,y,x,v$ we obtain 
\begin{equation}\label{phiphi7}
    \int\limits_{J} |o|^2 \, d|s| \le \int\limits_J 
    ||a s^m+ b|| c s^{-m}+ d|- |z s^n+y||x s^{-n}+v|| \, d|s|
\end{equation}
\begin{equation*}
   \times \sup_{t\in J}(|a s^m+ b|| c s^{-m}+ d|+ |z s^n+y||x s^{-n}+v|)
\end{equation*}
\begin{equation*}\label{phiphi8}
  \le 32 \int\limits_J 
    ||a s^m+ b|| c s^{-m}+ d|- |z s^n+y||x s^{-n}+v|| \, d |s| \, .
\end{equation*}
Inequalities \eqref{phiphi6} and \eqref{phiphi7}, along with \eqref{phiphi5}, show \eqref{phiphicon}, which completes  the proof of the  lemma.
\end{proof}































For $\eta  \in (0, \frac{1}{2})$ and  $m \in \mathbb{N}_0$, define
\begin{equation}\label{subs200}
    \Sigma_{\eta} ^m := \{ s\in E(\mu) \,:\, \,\forall n>m \text{ we have } 
\eta < \min(|A_n|,|B_n|,|\ti A_n|,|\ti B_n|) \} \, .
\end{equation}
\begin{lemma}\label{recur}
Let $\mu \in \mathcal{T}_{-}$, let $\eta  \in (0, \frac{1}{2})$ and $m \in \mathbb{N}_0$. If \eqref{convabhyp} holds, 
then  $|\Sigma_{\eta}^m| = 0$.
\end{lemma}

\begin{proof}
We proceed by contrapositive. Let $\mu, \eta,m $ be given and assume that  $|\Sigma_\eta^m|>0$.  Using $\Sigma_\eta^m\subset \Sigma_\eta^n$ for all $m<n$ and Lebesgue differentiation, 
there is $m_0>10^9$ and a subset $\Sigma\subset \Sigma_\eta^{m_0}\cap E(\mu)$ with
positive measure  such that
for all $s\in \Sigma$ and all $n>m_0$ we have
\begin{equation}\label{recur1}
    10^{10^{10^{10}}}L(\mu,s,n)\le \eta^8\, .
\end{equation}
Define $m_k:=4^km_0$ for $k\ge 1$.
For each $k\ge 0$, cover the set $\Sigma$ by a collection $\mathcal{J}_k$ of arcs $J$ with
\begin{equation}\label{recur3}
     |J|\le 10^{8}m_k^{-1}
 \end{equation}
such that every point of $\T$ is contained in at most two arcs of $\mathcal{J}_k$.
For $J\in \mathcal{J}_k$, we estimate with the local approximation Lemma \ref{approximation with A B C D},
applied at some point $s\in \Sigma\cap J$ for $C=10^{9}$ and for $n$ equals both $m_k$ and $m_{k+1}\le 10m_k$
and with the pointwise upper bound by $2$ on $\phi_n$, $\ti \phi_n$ and $A_n,B_n,\ti A_n,\ti B_n$
 \begin{equation}\label{recur4}
     \int\limits_{J} \left| |\phi_{m_k} \ti \phi_{m_k}| - 
     |\phi_{m_{k+1}} \ti \phi_{m_{k+1}}| \right| \, d |s| 
\end{equation}
\begin{equation*}
     \ge \int\limits_{J} \left| |(A_{m_k}s^{m_k}+B_{m_k})(\ti A_{m_k}s^{m_k}+\ti B_{m_k}) | -\right. 
\end{equation*}
\begin{equation*}  \left.|(A_{m_{k+1}}s^{m_{k+1}}+B_{m_{k+1}})(\ti A_{m_{k+1}}s^{m_{k+1}}+\ti B_{m_{k+1}}) | \right|\, d |s| -10^{-10}\eta^8|J|  \, .
\end{equation*}
With Lemma \ref{phiphi} for the obvious choice of parameters, using that
\eqref{phiphicon} is satisfied thanks to $m_{k+1}=4m_k$, we therefore obtain 
with \[
 |A_{m_k} B_{m_k}|, |\ti A_{m_k} \ti B_{m_k}|, |A_{m_{k+1}} B_{m_{k+1}}|, |\ti A_{m_{k+1}} \ti B_{m_{k+1}}| >\eta^2 
\]
that
 \begin{equation}\label{recur5}
     \int\limits_{J} \left| |\phi_{m_k} \ti \phi_{m_k}| - 
     |\phi_{m_{k+1}} \ti \phi_{m_{k+1}}| \right| \, d|s| \ge 10^{-3} \eta^8 |J|\, .
\end{equation}
Summing over $J\in \mathcal{J}_k$ and using that each point of $T$ is covered by at most two arcs of $\mathcal{J}_k$ while the union of arcs covers $\Sigma$, we obtain
 \begin{equation}\label{recur6}
     2\int\limits_{\T} \left| |\phi_{m_k} \ti \phi_{m_k}| - 
     |\phi_{m_{k+1}} \ti \phi_{m_{k+1}}| \right| \, d|s| \ge 10^{-3} \eta^8 |\Sigma|\, .
\end{equation}
It follows that the sequence $\phi_{m_k} ^* \ti \phi_{m_k}$ does not converge in
$L^1(\T)$, i.e., \eqref{convabhyp} fails. This proves the lemma.

\end{proof}




\begin{lemma}\label{lem:cty_phi_A_B}
For every $s \in \T$ and  $n\in \mathbb{N}_0$, 
\begin{equation}\label{phibyf}
    \left | \phi_{n+1} (s) - s\phi_{n} (s) \right| \leq 4 |F_{n+1}| 
\end{equation}
and, if $n\ge 1 $,
\begin{equation}\label{abbyf}
  |A_{n+1} - A_n|, |B_{n+1} - B_n| \leq 8|F_{n+1}| + \frac{1000}{n}  \, .  
\end{equation}
\end{lemma}
\begin{proof}
By the recursion equation \eqref{recursion phi} and then the bounds in Lemma \ref{lem:poly_bd_gen}, we have
\begin{equation}
\label{eq:diff_phi_s}
  \left | \phi_{n+1} (s) - s\phi_{n} (s) \right|
=  \left| s\phi_n(s) \left ( \frac{1}{\sqrt{1+|F_{n+1}|^2}}-1 \right ) + \frac{s^n \overline{F_{n+1}} \ti\phi_n^*(s) }{\sqrt{1+|F_{n+1}|^2}}\right|\le 4|F_{n+1}|\, ,
\end{equation}
where we used
\begin{equation} 
1- \frac{1}{\sqrt{1+|F_{n+1}|^2}}
\leq 
{\sqrt{1+|F_{n+1}|^2}} -1\le |F_{n+1}|\, .
 \end{equation}
   This proves \eqref{phibyf}.
 We have by Definition
 \eqref{def:A_B_n} and then the triangle inequality
   \[
   2 \left | |A_{n+1} | - |A_{n} | \right | = \left | |\phi_{n+1} (s) - \phi_{n+1} (s \gamma_{n+1})| - |s (\phi_{n} (s) - \phi_{n} (s \gamma_{n}))| \right | 
   \]
   \[\le 
  \left | \left ( \phi_{n+1} (s) - s\phi_n (s) \right ) - \left (  \phi_{n+1} (\gamma_{n+1} s) - s\phi_n (\gamma_{n} s) \right ) \right | \, . 
  \]
    \[\le 
  \left|  \phi_{n+1} (s) - s\phi_n (s)\right|+
  \left|  \phi_{n+1} (\gamma_{n+1} s) - s\phi_n (\gamma_{n+1} s)\right|+
  \left|  \phi_{n} (\gamma_{n+1} s) - \phi_n (\gamma_{n} s)\right|  \, . 
  \]
 By \eqref{eq:diff_phi_s} and the mean value theorem along the arc connecting $\gamma_{n+1}s$ with $\gamma_n s$, we obtain the bound
\begin{equation}\label{eq:bds_polys_cts_1}
2 \left | |A_{n+1} | - |A_{n} | \right | \le 8 |F_{n+1}| + |\gamma_{n+1} -\gamma_n| | \sup\limits_{z \in \T} |  \phi_n ' (z)| \, .  \end{equation}
 We have by Definition \eqref{gamman} of $\gamma$ that
\begin{equation}\label{smallf1}
    |\gamma_{n+1} -\gamma_n|\le \frac \pi n-\frac \pi{n+1}=\frac \pi {n(n+1)} \, .
\end{equation}
As for bounding $|\phi' (z)|$, by the Cauchy integral formula for a circle of radius $2/n$ centered at $z$ and then by the bounds of Lemma \ref{lem:poly_bd_gen},
\begin{equation}\label{smallf2}
     |\phi_n ' (z)|\le 
n\sup_{|y|\le 1+1/n} |\phi_n(y)|\le 100n\, .
\end{equation}
Combining \eqref{eq:bds_polys_cts_1}
with \eqref{smallf1} and \eqref{smallf2} proves to bound for $A_{n+1}-A_n$ in \eqref{abbyf}, and the 
  bound for $B_{n+1}-B_n$ follows in analogous fashion.
\end{proof}
















%\subsection{\texorpdfstring{Proof of \eqref{convergence of a} along the integers implies \eqref{convergence of AB 2} }{Proof of (1.11) along the integers implies (1.10)} }









We are ready to 
prove the second part of Theorem \ref{thm:conv_to_AB}.
Assume \eqref{convabhyp} and $\lim\limits_{n\to \infty}|F_n|=0$. Let us first define the set $E_0 (\mu)$.
By \eqref{convabhyp}, there is a monotone increasing
sequence $(m_k)$ such that $\phi_{m_k}^*\phi_{m_k}$
converges to $\overline{w(s)^{-1}}$
on a set $E_1(\mu)$ of full measure. Pick such a subsequence and set. Using the sets $\Sigma_\eta^m$ defined in \eqref{subs200}, define
\begin{equation}
    {E}_0(\mu):=
{E}_1(\mu) \setminus \left ( \bigcup\limits_{\eta \in 2^{-\N-2}} \bigcup\limits_{m\ge 1}  \Sigma_{\eta}^m \right ) \, .
\end{equation}
The set $E_0(\mu)$ has full measure in $\T$ by Lemma \ref{recur}.
Let $s\in E_0(\mu)$, and now assume \eqref{subshyp2} holds at this $s$. 

If $|w(s)|>1$, let
\begin{equation}\label{subs110}
\eta^{\frac 1 {100}}<10^{-12}|w(s)|^{-2}\min \{|w(s)|-1, 1 \}
\end{equation}
and if $|w(s)|=1$, let
\begin{equation}\label{subs190}
\eta^ { \frac{1}{100}}<10^{-12}|w(s)|^{-2}\, .
\end{equation}
Pick $n_0\geq 1000 \eta^{-2}$ large enough so that for all $n>n_0$ we have,  using first the assumption $F_n \to 0$, and  then Lebesgue differentiation, then Assumption \eqref{subshyp2},
\begin{equation}\label{subs111}
    |F_n|<10^{-10}\eta\, .
\end{equation}
\begin{equation}\label{subs112}
   e^{1000}L(\mu,s,n)< \eta^{10} \, ,
\end{equation}
\begin{equation}\label{subs113}
   |( \phi_n^*(s)\ti \phi_n(s))^2- \overline{w(s)^{-2}}|< \eta^{10} \, .
\end{equation}
As $s\not \in \Sigma_{10 \eta} ^{n_0}$, there exists $n_1>n_0$ such that
\begin{equation}\label{subs114}
\min(|A_{n_1}|,|B_{n_1}|,|\ti A_{n_1}|, |\ti B_{n_1}|)\le 10\eta\, .
\end{equation}
Assume first $|B_{n_1}|\le 10\eta$.
We then claim that for all $n\ge n_1$
\begin{equation}\label{subs115}
  |B_{n}|\le 10\eta  \, .
\end{equation}
We prove \eqref{subs115} by induction, the case $n=n_1$ being given. 
Assume \eqref{subs115} is proven for some $n\ge n_1$. We claim that
$|B_{n}|\le \eta$. Indeed, if not, then by Lemma \ref{abclem}, we must have 
\[
\eta^{5} \leq |\phi_n ^* (s) \ti \phi_n (s) - \overline{w(s)^{-1}}| \, ,
\]
which combined with \eqref{subs113}, implies
\begin{equation}\label{subs116}
|\phi_n ^* (s) \ti \phi_n (s) + \overline{w(s)^{-1}}| < \eta^{5} \, .
\end{equation}
On the other hand, by Lemma \ref{abtocdlem}, we have
\begin{equation}\label{subs117}
|A_n|, |\ti A_n| \geq (4|w(s)|)^{-1} \, .
\end{equation}
Furthermore by \eqref{abtocdcon3}, we also have
\begin{equation}\label{subs118.2}
|\ti B_n| \leq 100|w(s)|\eta \, .
\end{equation}
Combining estimates \eqref{subs117}, \eqref{subs116}, the bounds \eqref{subs115} and \eqref{subs118.2},
and approximation Lemma \ref{approximation with A B C D} with $C=10$, we obtain
\begin{equation}\label{subs119}
\left | \overline{A_n} \ti A_n + \overline{w(s)^{-1}} \right | < 100\eta ^{\frac 1 2} \, .
\end{equation}
On the other hand, using again the bound \eqref{subs115} on $|B_n|$ and \eqref{difference ab square} yields
\begin{equation} \label{subs120}
\left |-\overline{A_n} \ti A_n  + \overline{w(s) ^{-1}} \right | < 100 \eta ^{\frac 1 2} \, . 
\end{equation}
But \eqref{subs119} and \eqref{subs120} both contradict each other. Thus $|B_n| \leq \eta$. By Lemma \ref{lem:cty_phi_A_B},
we conclude $|B_{n+1}|\le 10\eta$.
This completes the proof of \eqref{subs115} by induction.
As $\eta$ was arbitrarily small, we obtain  
the conclusion \eqref{subscon3}.
Moreover, with Lemma \ref{smallablem} we obtain conclusion \eqref{subscon2}.
If $|\ti B_{n_1}|\le 10\eta$, then an analogous arguments gives
\eqref{subscon2}, and that $\ti A_n \ti B_n \to 0$, which then implies \eqref{subscon3} by \eqref{product ab}.

Now assume $|A_{n_1}|\le 10\eta$. Analogous arguments
give $|A_{n}|\le \eta$
for all $n\ge n_1$ and thus, by Lemma \ref{smallablem}
\begin{equation}\label{subs203}
\left| \phi_{n} ^* (s) \ti \phi_{n} (s)  +
\overline{w(s)^{-1}}\right|\le \eta ^{\frac 1 2} \, .
\end{equation}
However, as $s\in E_1(\mu)$, there exists $n_2>n_1$ with
\begin{equation}\label{subs202}
\left| \phi_{n_2} ^* (s) \ti \phi_{n_2} (s)  -
\overline{w(s)^{-1}}\right|\le \eta ^{\frac 1 2} \, .
\end{equation}
By the triangle inequality,
\eqref{subs203} and \eqref{subs202} contradict each other for $n=n_2$. Thus the case 
$|A_{n_1}|<10\eta$ is not possible.
By the analogous arguments, the case $|\ti A_{n_1}|<10\eta$ is not possible.
This proves Theorem \ref{thm:conv_to_AB}.

















\section{Proof of Theorem \ref{zeros theorem}}



Let $\mu \in \mathcal{T}_{-}$ and $s\in E(\mu)$. 
Let $0< \epsilon\le  10^{-5}$.
With the Lebesgue differentiation theorem and elementary calculus, we find $n_0$ large enough so that for all $n>n_0$
\begin{equation}\label{zero1}
e^{10^{2}\epsilon^{-1}} L(\mu, s, n)\le |w(s)|^{-2}\, ,
\end{equation}
\begin{equation}\label{zero1.5}
   (10^{2}\epsilon^{-1})^{\frac 1 n}-1
   \le 10\epsilon^{-1}{n}^{-1}\, .
\end{equation}
\begin{equation}\label{zero1.7}
   10^4\epsilon^{-1}\le n\, ,
\end{equation}
Let $n> n_0$.
We first prove that \eqref{convergence of AB1}  
 implies         
 \eqref{zeros going to infinity1}.
Assume \eqref{convergence of AB1}. Using the upper bound \eqref{eq:bd_A_B} of $A_n,B_n$ by $2$, we obtain
\begin{equation}\label{zero3}
 \frac \epsilon {2}\le  | A_{n }|,|B_{n}| \le 2\, .
\end{equation}
The zeros of $A_n z^n+B_n$ are $n$ equidistant points on the circle of radius $r$ about the origin, where $|A_n|r^n=|B_n|$. 
Using \eqref{zero1.5} and \eqref{zero3}, we derive
\begin{equation}\label{zero4}
    |r-1|\le 10 \epsilon^{-1}n^{-1}\, .
\end{equation}
Hence there is  a zero $re^{i\theta}$
of $A_n z^n+B_n$
with distance at most 
\begin{equation}\label{zero5}
    |r-1|+10n^{-1}\le  20 \epsilon^{-1}n^{-1}
\end{equation}
from the point  $s\in \T$.
Consider the annular sector
$$K := \{q e^{i\zeta} \,: \, e^{-100 \epsilon^{-1}}  < q^n < e^{100 \epsilon^{-1}}  \text{ and } |\zeta-\theta| < \pi/n \}  \, .$$
The sector $K$  contains the zero $re^{i\theta}$.
Note that for $qe^{i\zeta}\in K$ we have 
\begin{equation}\label{zero5.5}
    |qe^{i \zeta} - s|   \leq  |q -1 | + | e^{i \zeta} - s |    \leq (e^{100\epsilon^{-1} n^{-1}} -1)  + 10 n^{-1}  \leq  10^3\epsilon^{-1} n^{-1} \, .
\end{equation}
In particular, the approximation Lemma \ref{approximation with A B C D} holds on $K$ with $C=10^4\epsilon^{-1}$.
For $qe^{i\zeta}$ on the pieces of the boundary of $K$ where $|\zeta-\theta|=\pi/n$, we have
\[|A_{n} q^n e^{i\zeta n}+B_n|\ge |B_n| \,  \]
because $re^{i\theta}$ is a zero of $A_nz^n+B_n$ and thus $A_n q^{n} e^{i \zeta n}$ and $B_n$ have the same argument.

For $qe^{i\zeta}$ on the piece of the boundary of $K$ where $q^n=e^{100\epsilon^{-1}}$, we have 
\[|A_{n} q^n e^{i\zeta n}+B_n|\ge e^{100\epsilon^{-1}}|A_n| -|B_n|\ge |B_n| \]
by \eqref{zero3}.
On the piece of the boundary where $q^n=e^{-100\epsilon^{-1}}$, we have 
\[|A_{n} q^n e^{i\zeta n}+B_n|\ge |B_n|-e^{-100\epsilon^{-1}}|A_n| \ge |B_n| \]
again by  \eqref{zero3}.
Hence, for $z$ on the boundary of $K$,
\begin{equation}\label{zero10}
    |A_n z^n + B_n|\ge 2^{-1} \epsilon\, .
\end{equation}
This together with local approximation Lemma \ref{approximation with A B C D} yields
\[
|An z^n + B_n| > |\phi_n(z) - (A_n z^n + B_n)|
\]
for $z \in \partial K$. By Rouch\'e's theorem, $\phi_n$
also has a zero in $K$.
With \eqref{zero5.5}, this completes the proof of 
 \eqref{zeros going to infinity1}.

We turn to the proof that \eqref{zeros going to infinity2} implies \eqref{convergence of AB2} and thus assume in addition $e^{\epsilon^{-1}} \geq |w(s)|$. 
Assume \eqref{zeros going to infinity2} and pick a zero $z$ of $\phi_n$ with 
\begin{equation}\label{zero20}
    |z-s|\le \epsilon^{-1}n^{-1}\, .
\end{equation}
With $\phi_n(z)=0$, the approximation
Lemma \ref{approximation with A B C D},  and the choice of $n$ that yields \eqref{zero1}, we conclude
\begin{equation}\label{zero300}
    |A_nz^n-B_n|\le e^{-10\epsilon^{-1}}\, .
\end{equation}
Squaring and using the triangle inequality gives
\begin{equation}\label{zero21}
    |A_nB_nz^n|\ge |A_n z^n|^2+|B_n|^2 - e^{-20\epsilon^{-1}}\, .
\end{equation}
Dividing by $z^n$ and using that $|z^n|, |z|^{-n}<e^{2\epsilon^{-1}}$, 
\begin{equation}\label{zero22}
    |A_nB_n|\ge (|A_n|^2+|B_n|^2)e^{-4\epsilon^{-1}} - e^{-18\epsilon^{-1}} \, .
\end{equation}
Inequality \eqref{difference ab square} together with the upper bound $|\ti A_n|, |\ti B_n|\le 2$ gives the lower bound
\begin{equation}\label{zero200}\max(|A_n|,|B_n|)\ge 10^{-1}|w(s)|^{-1}\, ,
\end{equation}
which can be applied to 
\eqref{zero22} to obtain with the upper bound  $e^{\epsilon^{-1}}$ by
 $|w(s)|$,
\begin{equation}\label{zero23}
    |A_nB_n| \geq 10^{-1} |w^{-1}| e^{-4 \epsilon^{-1}} - e^{-18 \epsilon^{-1}} \geq 10^{-1} e^{-5 \epsilon^{-1}} - e^{-18\epsilon^{-1}} \ge e^{-10\epsilon^{-1}} \, .
\end{equation}
This gives \eqref{convergence of AB2} and completes the proof of Theorem \ref{zeros theorem}.










































\section{Proof of Theorem \ref{thm:lacunary}}

We begin with three preliminary lemmas to further compare the sizes of two waves with lacunary frequencies. 

\begin{lemma}\label{fourlem}
    Let $a,b,c,d$ be complex numbers bounded in absolute value by $2$. Let $J$ be an arc on $\T$.
    Let $m,n$ be  positive integers with  
\begin{equation}\label{fourhyp}
        10^7|J|^{-1}\leq m,n,|m-n|,|2m-n|, |m-2n|\, .
    \end{equation}
   Then
   \begin{equation}
       \label{fourcon}
    \int\limits_J (|a s^m+ b|- |c s^n+d|)^2\, d|s|\ge 
10^{-6}\min(|ab|,|cd|)^8|J|\, .
   \end{equation}
\end{lemma}
\begin{proof}
Define
\begin{equation}\label{four1}
   o(s):= |a s^m+ b|^2- |c s^n+d|^2 \, .
\end{equation}
Applying Lemma \ref{phiphi} with the obvious parameters
gives
\begin{equation}\label{four100}
    \| o\|_{L^1(J, \, d|s|)}\ge 10^{-2}\min(|ab|,|cd|)^4|J|\, .
\end{equation}
Applying Cauchy Schwarz and the assumed upper bound on $a$, $b$, $c$, and $d$ gives
\begin{equation}\label{four6}
    \|o\|_{L^1(J, \, d|s|)}\le 
     \||a s^m+ b|+ |c s^n+d|\|_{L^2(J, \, d|s|)}
    \||a s^m+ b|- |c s^n+d|\|_{L^2(J, \, d|s|)}
\end{equation}
\begin{equation*}
    \le 8|J|^{\frac 12}
    \||a s^m+ b|- |c s^n+d|\|_{L^2(J, \, d|s|)}\, .
\end{equation*}
Inequalities \eqref{four100} and \eqref{four6} imply\eqref{fourcon} and complete the proof of the lemma.
\end{proof}













\begin{lemma}\label{sin}
Let $a$ and $m$ be positive, let $b,c$ be nonnegative with $b\le a$, and let $\zeta$ be real.
Let $J$ be an
interval on $\R$ with  $|J|>10 m^{-1}$.  Then
\begin{equation}\label{sincon}
    \int\limits_{J} (\sqrt{a+b\sin(m(x-\zeta))}-c)^2\, dx \ge 10^{-2} a^{-1} b^2 |J|\, .
\end{equation}
\end{lemma}
\begin{proof}
   After translation and dilation, we assume $m=1$ and $\zeta=0$. Dividing by $a$ if necessary and replacing $b/a$ by $b$ and $c/\sqrt{a}$ by $c$, we may assume $a=1$.
The left side of 
\eqref{sincon} is then larger than 
the $L^2$ norm squared of 
the projection of 
$\sqrt{1+b\sin x}$ onto the 
orthogonal complement of $\mathbf{1}_J$. To obtain a lower bound on this projection, pick  a disjoint union $I\subset J$ of
full periods of $\sin(x)$ with $2|I|>|J|$, which exists by assumption on  $J$, and pair
with the function function $\mathbf{1}_{I}\sin$, which has mean zero is hence in the orthogonal complement of constant functions. Because $\mathbf{1}_{I}$ has $L^2$ norm $2^{-\frac 12}|I|^{\frac 12}$, we thus estimate the left side of 
\eqref{sincon} from below by
\begin{equation}\label{sin4}
2|I|^{-1}\left(\int\limits_{ I}\sin(s)\sqrt{1+b\sin(s)}\, ds\right)^2 \, .
\end{equation}
We divide the domain of integration in \eqref{sin4} into the set $I_+\subset I$  where $\sin$
is positive and $I_-=I\setminus I_+$.
Using for $0\le x\le 1$ the elementary inequality
\begin{equation}\label{sin5}
    1\le 1+x\le \left(1+\frac x2\right)^2\, ,
\end{equation}
we estimate with the assumption $b\le 1$
\begin{equation}\label{sin6}
\int\limits_{ I_+}\sin(s)\sqrt{1+b\sin(s)}\, ds
\ge \int\limits_{ I_+}\sin(s)\, ds\, ,
\end{equation}
\begin{equation}\label{sin8}
\int\limits_{ I_-}\sin(s)\sqrt{1+b\sin(s)}\, ds
\ge \int\limits_{ I_-}\sin(s)\left(1+ 2^{-1}b \sin(s)\right)\, ds\, .
\end{equation}
Adding \eqref{sin6} and \eqref{sin8} and using that $\sin(s)$ has integral zero on $I$  gives
\begin{equation}\label{sin9}
\int\limits_{ I}\sin(s)\sqrt{1+b\sin(s)}\, ds
\ge  
2^{-1}b\int\limits_{ I_-}\sin(s)^2\, ds = 8^{-1}b |I|\, ,
\end{equation}
where we used that $\mathbf{1}_{I_-}\sin^2$ has mean $1/4$ over each period.
Inserting \eqref{sin9} into \eqref{sin4} and using $2|I|\ge |J|$
proves \eqref{sincon}
and completes the proof of the lemma.
\end{proof}



















\begin{lemma}\label{unbalanced}
    Let $a,b,c,d$ be complex numbers bounded in absolute value by $2$ and assume
    \begin{equation}\label{unbalancedhyp}\min(|a|,|b|)|\ge 10^2\min(|c|,|d|)\, .
    \end{equation}
     Let $J$ be an arc on $\T$.
    Let $m,n$ be  positive integers with  
\begin{equation}\label{unbalancedhyp1}
        10^3|J|^{-1}\le m,n\, .
    \end{equation}
   Then 
\begin{equation}
       \label{unbalancedcon}
    \int\limits_J (|a s^m+ b|- |c s^n+d|)^2\, d|s|\ge 
10^{-4} \min(|a|,|b|)^2|J|\, .
   \end{equation}
\end{lemma}
\begin{proof}
Define
\begin{equation}\label{unbalanced1.1}
    u(s):=|a s^m+ b|- \max(|c|,|d|)\, ,\ 
 v(s):=\max (|c|,|d|)
    - |c s^n+d|
\end{equation}
Then we estimate the left side of \eqref{unbalancedcon}
 by
\begin{equation}
\label{unbalanced2}
    \|u-v\|^2\ge (\|u\|-\|v\|)^2
    \ge \|u\|(\|u\|-2\|v\|)\ge
    \|u\|(\|u\|-2\min(|c|,|d|)|J|^{\frac 12})\, ,
\end{equation}
where the norms are in $L^2(J, \, d|s|)$
and in the last step we have used that for all $s\in \T$
\[
    -\min(|c|,|d|)=\max (|c|,|d|)
    - |c|-|d| \le v(s)\le \max (|c|,|d|)
    - ||c|-|d|| =\min(|c|,|d|)\, .
\]
Noting that, writing $s = e^{i x}$ for $x \in [0, 2 \pi)$, for some real $\zeta$, we have
\begin{equation}\label{unbalanced4}
 |a s^m+ b|=\sqrt{a^2+b^2+2|a b|\sin(m(x-\zeta))}\,  . \end{equation}
By Lemma \ref{sin}, which takes Assumption \eqref{unbalancedhyp1}, to estimate
\begin{equation}\label{unbalanced5}
\|u\| \ge 5^{-1}|ab|(|a|^2+|b|^2)^{-\frac 12}|J|^{\frac 12}
\ge 10^{-1}\min(|a|,|b|)|J|^{\frac 12}
\, .
\end{equation}
Inserting \eqref{unbalanced5} into \eqref{unbalanced2}
and using the assumption \eqref{unbalancedhyp}
proves \eqref{unbalancedcon}
and thus completes the proof of the lemma.
\end{proof}










We turn to the proof of Theorem \ref{thm:lacunary}. 
Let $\mu\in \mathcal{T}_-$ be given and
assume \eqref{convabhyp} and that $\|F\|_{\ell^2(\mathbb{N}_0)}$ is finite.
