\begin{equation}\label{tfive22}
     -2 \int\limits_{\bigcup\limits_{I \in  \mathcal{I}^{(j)}} I} \log \left( \frac 12\left| \phi_{l}^* \phi_{h} + \ti \phi_{l}
     \ti \phi_{h} \right|
     \right) \, d|s|\ge 
10^{-110}\eta^8
\sum_{J\in \mathcal{I}^{(j)}}
|J| \, .
