\begin{lemma}\label{twosin}
Let $a,b,c,d$ be nonnegative real numbers with $b+c\le a$. Let $m$ be a positive and $\phi,\psi$ be real numbers.
Let $J$ be an
interval with $|J|>10 m^{-1}$.  Then
\begin{equation}\label{twosincon}
    \int_J (\sqrt{a+b\sin(m(s-\phi))+c\sin(2m(s-\psi))}-d)^2\, ds \ge 10^{-10} a^{-1}(b^2+c^2)|J|\, .
\end{equation}
\end{lemma}
\begin{proof}
   By translation and dilation, we assume $m=1$ and $\psi=0$. By normalization, we assume $a=1$.
The left-hand-side of 
\eqref{twosincon} is then larger than the 
the $L^2$ norm squared of 
the projection of 
\begin{equation}\label{twosin10}
    \sqrt{1+b\sin(s-\phi)+c\sin(2s)}
\end{equation}
onto the 
orthogonal complement of the constant function. To obtain a lower bound on that projection, we pick  a disjoint union $I\subset J$ of
full periods of $\sin $ with $2|I|>|J|$, which exists by assumption on  $J$, and pair
with the mean zero function $f$ defined by
\begin{equation}
    \label{twosin11}
f(s)=1_I(s)(b\sin(s-\phi)+c\sin(2s))\, ,
\end{equation}
which has $L^2$ norm 
\begin{equation}
    \label{twosin12}
2^{-1} (b^2+c^2)^{\frac 12}|I|^{\frac 12}\, .
\end{equation}

 We thus estimate the left-hand-side of 
\eqref{twosincon} from below by
\begin{equation}\label{twosin4}
4(b^2+c^2)^{-1}|I|^{-1}\left(\int_{ I}f(s)\sqrt{1+f(s)}\, ds\right)^2
\end{equation}
We divide the domain of integration in \eqref{twosin4} into the set $I_+\subset I$  where $f$
is positive and $I_-=I\setminus I_+$.
Using for $0\le x\le 1$ the elementary inequality
\begin{equation}\label{twosin5}
    1\le 1+x\le \left(1+\frac x2\right)^2\, ,
\end{equation}
we estimate with the assumption $b+c\le 1$
\begin{equation}\label{twosin6}
\int_{ I_+}f(s)\sqrt{1+f(s)}\, ds
\ge \int_{ I_+}f(s)\, ds\, ,
\end{equation}
\begin{equation}\label{twosin8}
\int_{ I_-}f(s)\sqrt{1+f(s)}\, ds
\ge \int_{ I_-}f(s)\left(1+ 2^{-1}f(s)\right)\, ds\, .
\end{equation}
Adding \eqref{twosin6} and \eqref{twosin8} and 
using that $f$ has mean zero gives
\begin{equation}\label{twosin20}
\int_{ I}f(s)\sqrt{1+f(s)}\, ds
\ge  2^{-1}\int_{ I_-}f(s)^2\, ds
\, .
\end{equation}
We have $2|I_-|=|I|$
as the signs of $\sin(s-\phi)$ and $\sin(2s)$ are independent. Morover,
on a subset of $I$ of measure at least $3|I|/4$ both functions $\sin(s-\phi)$ and $\sin(2s)$ are larger in absolute value than $\frac 1{100}$ and , and then likewise on a subset of $I_-$ of measure at least $|I|/4$. Hence 
\begin{equation}\label{twosin20}
\int_{ I}f(s)\sqrt{1+f(s)}\, ds
\ge  10^{-5}(b^2+c^2)|I|
\, .
\end{equation}


Inserting \eqref{twosin20} into \eqref{twosin4} and using $2|I|\ge |J|$
estimates the left side of \eqref{twosincon} for the assumed values of $a$ and $m$ and $\psi$ from below by
\begin{equation}\label{twosin21}
    10^{-10}(b^2+c^2)|J|\, .
\end{equation}
This proves \eqref{sincon}
and completes the proof of the lemma.
\end{proof}

















\begin{lemma}\label{fourlem}
    Let $a,b,c,d$ be complex numbers bounded in absolute value by $2$. Let $J$ be an arc on $\T$.
    Let $m,n$ be  positive integers with  
\begin{equation}\label{fourhyp}
        10^3|J|^{-1}|\le m,n,|m-n|\, .
    \end{equation}
   Then
   \begin{equation}
       \label{fourcon}
    \int_J (|a s^m+ b|- |c s^n+d|)^2\, ds\ge 
10^{-4}\min (|ab|,|cd|)^4|J|\, .
   \end{equation}
\end{lemma}
\begin{proof}
Define
\begin{equation}\label{four1}
   o(s):= |a s^m+ b|^2- |c s^n+d|^2 \, .
\end{equation}
Expanding squares, we obtain
for $s\in \mathbb{T}$
\begin{equation}\label{four2}
   o(s)= a\overline{b}s^m+
     \overline{a} {b}s^{-m}- 
     c \overline{d}s^n-
     \overline{c} {d}s^{-n} +{k}
\end{equation}
for some real constant $k$. Define $M\ge 0$ by
\begin{equation}\label{four3}
    M^2=|ab|^2+|cd|^2\, .
\end{equation}
and note that each of the coefficients in \eqref{four2} involving $a,b,c,d$ is bounded in absolute value by $M$.
    Expanding $o(s)\overline{o(s)}$ with the expression \eqref{four2} into five diagonal and thus constant terms and ten off diagonal terms and then estimating the off diagonal terms from above gives by the  triangle inequality the estimate
\begin{equation}\label{four4}\|o\|_{L^2(J)}^2\ge 2M^2|J| + k^2|J|-|k|M
\left[
 2|\int_J s^{n}|
-2|\int_J s^{m}|
\right]
\end{equation}
\begin{equation*}
-M^2\left[
 2|\int_J s^{n-m}|
-2|\int_J s^{n+m}|
-|\int_J s^{2n}|
-|\int_J s^{2m}|
\right]
\, .
\end{equation*}
We can shrink the intervals of integration in these integrals by any disjoint union of full periods of the integrand without changing the value of the integral. Thereby reducing to  domains of integration to less than one period, which by assumption \eqref{fourhyp} is less than 
$10^{-2}|J|$,  we  obtain
with trivial estimates on these integrals the inequality \ct{this follows from Lemma 17 setting a=c, b=d etc}
\begin{equation}\label{four5}
  \|o\|_{L^2(J)}^2\ge \left[2M^2 + k^2-  |k|M - \frac 12 M^2\right]|J|\ge M^2|J| .
\end{equation}

Together with the inequality
\begin{equation}\label{four6}
    \|o\|_{L^2(J)}^2\le 
     \||a s^m+ b|+ |c s^n+d|\|_{L^2(J)}
    \||a s^m+ b|- |c s^n+d|\|_{L^2(J)}
\end{equation}
\begin{equation*}
    \le 8|J|^{\frac 12}
    \||a s^m+ b|- |c s^n+d|\|_{L^2(J)}
\end{equation*}
by the assumed upper bound on $a$, $b$, $c$, and $d$, this implies \eqref{fourcon} and thereby proves the lemma.
\end{proof}

