\begin{algorithm}\label{alg-1}
\caption{Logistic growth with explicit cell cycle length SSA}\label{alg:Log_CCD_SSA}
\begin{algorithmic}
\State \textbf{Input:} initial number of motile cells $Q_0=Q(0)$ and proliferating cells $P_0=P(0)$, initial distribution of remaining times $(\Theta_1,\dots,\Theta_{P_0})$, proliferating rate constant $r$, carrying capacity $K$, distribution for the length of the cell cycle and halting condition $t_{end}$.\\
\State 
\textbf{Initialisation:} \\
Set $t \gets 0$ \Comment{Set system time to zero.}
\State Set $Q\gets Q(0)$ and $\underbar{P}\gets(\Theta_1,\dots,\Theta_{P_0})$
\Comment{Set initial state of the system.}\\

\While{$ t\leq t_{end} \textrm{ and } 0 < Q+2\cdot len(\underbar  P) < K$}
\State Calculate the propensity function $a$ according to Eq. (\ref{eq:wm_cell_cycle}).
\State Sample $\tau \sim Exp(a)$ according to Eq. (\ref{eq:wm_cell_cycle}).
\State Calculate the minimal of remaining times $t_{R_D}$ according to Eq. (\ref{eq:cc_tRD}).\\
\If{$\tau < t_{R_D}$}  \Comment{\textbf{A quiscent cell enters cell cycle}}
\State $t \gets t + \tau$
\Comment{Advance system time}
\State $\underbar P\gets (\Theta_1-\tau,\dots,\Theta_{P}-\tau)$
\Comment{Decrease remaining times of proliferating cells}
\State $Q\gets Q-1$
\Comment{Decrease the number of motile cells}
\State Obtain $\vartheta$
\Comment{Obtain cell cycle length for the new proliferating cell}
\State $\underbar P\gets (\Theta_1,\dots,\Theta_{P},\vartheta)$
\Comment{Add the cell cycle length to the list of remaining times in the proliferating list}\\
\ElsIf{$t_{R_D} < \tau$} \Comment{\textbf{A proliferating cell completes cell cycle}}
\State $t \gets t + t_{R_D}$
\Comment{Advance system time}
\State Get index $i$ of $t_{R_D}$ in $\underbar P$
\Comment{Find the proliferating cell with the least remaining time}
\State $\underbar P.delete(\underbar P[i])$ 
\Comment{The proliferating cell with the least remaining time leaves cell cycle}
\State $\underbar P\gets (\Theta_1-t_{R_D},\dots,\Theta_{P}-t_{R_D})$
\Comment{Decrease remaining times of proliferating cells}
\State $Q\gets Q+2$
\Comment{Two new (motile) daughter cell is created}\\
\EndIf
\EndWhile
\end{algorithmic}
\end{algorithm}

