q_1f^2+q_2ff'+q_3(f')^2=G,
\end{align}
where $q_1=a_1a_3+\frac{nA}{(2n-1)G}$, $q_2=\frac{n(n-1)}{2n-1}[\frac{G'}{G}-2(a_1+a_3)]$, $q_3=n(n-1)$. By Lemma \ref{lm2.2} and \eqref{3.14}, we have
