By \eqref{3.16} and \eqref{3.13} that
\begin{align}
\label{3.17}
\frac{A}{G}=-\frac{1}{2}\left[\left(\frac{G'}{G}\right)'-\frac{1}{2}\left(\frac{G'}{G}\right)^2+(a_1+a_3)\frac{G'}{G}\right].
\end{align}

Now we claim $G'\equiv0$. Otherwise,  suppose $G'\not\equiv0$, differentiating \eqref{3.17}, we get
\begin{align}
\label{3.18}
  \left(\frac{A}{G}\right)'=-\frac{1}{2}\left[\left(\frac{G'}{G}\right)''-\frac{1}{2}\left(\frac{G'}{G}\right)\left(\frac{G'}{G}\right)'+(a_1+a_3)\left(\frac{G'}{G}\right)'\right].
\end{align}
Differentiating $q^2\equiv4q_1q_3$, get $q_2q_2'=2q_1'q_3$, that is
\begin{align}
\label{3.19}
\left(\frac{A}{G}\right)'=\frac{n-1}{2(2n-1)}\left(\frac{G'}{G}\right)'\left[\frac{G'}{G}-2(a_1+a_3)\right].
\end{align}
Denote $\phi=\frac{G'}{G}$. By \eqref{3.18} and \eqref{3.19}, we have
\begin{align}
\label{3.20}
(a_1+a_3)\phi'=n\phi\phi'-(2n-1)\phi''.
\end{align}

If $\phi'\equiv0$, then $G=c_5e^{c_6z}$, $c_5,c_6$ are constants. Because $G'\not\equiv0$, so $c_5c_6\not=0$. Which means $T(r,G)=O(r)$ a contradiction.

If $\phi'\not\equiv0$, from \eqref{3.20} that
\begin{align*}
e^{(a_1+a_3)z}=c_7G^n(\phi')^{-(2n-1)},~~c_7\in\mathbb{C}\setminus\{0\}
\end{align*}
}
which implies $a_1+a_3=0$. Subsisting $a_1+a_3=0$ into \eqref{3.20}, then
\begin{align}
\label{3.21}
 c_7G^n=\left[\left(\frac{G'}{G}\right)'\right]^{2n-1}.
\end{align}
If $z_3$ is a  zero of $G$, then $z_3$ is a pole of $\frac{G'}{G}$. Subsisting $z_3$ into \eqref{3.21}, we get a contradiction. If $z_4$ is a pole of $G$ of multiplicity $k$, where $k$ is a positive integer, then $z_4$ is a pole of $\frac{G'}{G}$ of multiplicity $1$. Subsisting $z_4$ into \eqref{3.21}, we get $kn=4n-2$. Which implies $n=\frac{-2}{k-4}$, so $0<k\le3$. We get $n=2$ or $n=1$, this contradicts the hypothesis $n\ge 3$. Thus $G$ does not have  zero and pole. Since $T(r,G)=o(r)$, thus $G$ is a constant, which  contradicts with $G'\not\equiv0$.

Now we get $G'\equiv0$, then by \eqref{3.17} $A\equiv0$.  By \eqref{3.13}, then $(2n-1)\frac{f''}{f'}=a_1+a_3$. Which implies $f(z)=c_8e^{\frac{(a_1+a_3)z}{2n-1}}+c_9,$ where $~c_8, ~c_9\in\mathbb{C}\setminus 0$. Subsisting $f$ into \eqref{F}, by the Lemma 2.6, we have the follow asserts.

If $\frac{n(a_1+a_3)}{2n-1}=a_1$, we get $\frac{a_1}{a_3}=\frac{n}{n-1}$.  Thus $f(z)=t_1e^{\frac{a_1z}{n}}+t_0$, where $t_0\not=0$ is a constant, $t_1^n=p_1,$ $-t_0^n$ equals to  the constant term of $P_d(z,t_1e^{\frac{a_1z}{n}}+t_0)$.

If $\frac{n(a_1+a_3)}{2n-1}=a_2$, we get $\frac{d_5(a_1+a_3)z}{2n-1}=a_1$, where $0<d_5\le n-2$ is a integer. Which implies $d_5a_2=na_1$, this contradicts the hypothesis $\frac{a_2}{a_1}\le\frac{n-2}{n}$.

If $\frac{n(a_1+a_3)}{2n-1}=a_3$, we get $\frac{a_1}{a_3}=\frac{n-1}{n}$.  Thus $f(z)=t_2e^{\frac{a_3z}{n}}+t_3$, where $t_3\not=0$ is a constant, $t_2^n=p_3,$ $-t_3^n$ equals the constant term of $P_d(z,t_2e^{\frac{a_3z}{n}}+t_3)$.

\end{subcase}


\begin{subcase}
\rm{
Suppose $q_2^2\not\equiv4q_1q_3$. From \eqref{3.15} that
\begin{align*}
 2(a_1+a_3)=2n\frac{G'}{G}-(2n-1)\frac{(q^2-4q_1q_3)'}{q^2-q_1q_3}
\end{align*}
then there exists $c_3\not=0$ such that $e^{2(a_1+a_3)z}=c_3G^{2n}(q^2-4q_1q_3)^{-(2n-1)}.$ Thus $a_1=-a_3$, then  $f^{n-2}G-a_1a_3f^n=n(n-1)f^{n-2}(f')^2+nf^{n-1}f''$. Substituting $f^{n-2}G-a_1a_3f^n$ into \eqref{3.3} and \eqref{3.5}, we have
\begin{align*}
a_1f^n-nf^{n-1}f'+\frac{f^{n-2}G}{a_1+a_2}+\frac{H_1}{a_1+a_2}=2a_1p_3e^{a_3z}
\end{align*}
\begin{align*}
a_1f^n+nf^{n-1}f'+\frac{f^{n-2}G}{a_1-a_2}+\frac{H_2}{a_1-a_2}=2a_1p_1e^{a_1z}
\end{align*}

Multiplying $2a_1p_3e^{a_3z}$ and $2a_1p_1e^{a_1z}$, we have
\begin{align}
\label{3.22}
a_1^2f^{2n}-n^{2}f^{2(n-1)}(f')^2=4a_1^2p_1p_3+F(z,f),
\end{align}
where $F(z,f)$ is a differential-difference polynomial of $f$ of degree at most $2n-2$. Further write the equation \eqref{3.22} in
to $f^{2n-2}\Omega(z)=4a_1^2p_1p_3+F(z,f)$, where $\Omega(z)=a_1^2f^2-n^2(f')^2$. By the Lemma \ref{Clunie}, we have $m(r,\Omega)=S(r,f)$. Combining $N(r,f)=S(r,f)$, yields $T(r,\Omega)=S(r,f)$. By Lemma \ref{ccy2004}, then $\Omega$ is a constant. So differentiating $\Omega$, we have
\begin{align}
\label{3.23}
2a_1^2f=2n^2f''.
\end{align}

Solving the \eqref{3.23}, we have
\begin{align*}
    f(z)=\gamma_4e^{\frac{a_1z}{n}}+\gamma_5e^{\frac{a_3z}{n}},
\end{align*}
where $\gamma_4$ and $\gamma_5$ are nonzero constant. Subsisting $f$ in \eqref{F}, then $\gamma_4^n=p_1$, $\gamma_5^n=p_3$.

It's worth noting that we started Case 2 with the assumption $P_d(z,0)\not\equiv0$. So if $P_d(z,0)=0$, we have
\begin{align*}
   f(z)=\gamma_4e^{\frac{a_1z}{n}}+\gamma_5e^{\frac{a_3z}{n}}+\gamma_6,
\end{align*}
where $\gamma_6$ is a constant.
}
\end{subcase}
\end{proof}

\section{Proofs of Theorems 1.2 and 1.3}
\begin{proof}[Proof of Theorem 1.2] Suppose that equation \eqref{F} admits a meromorphic solution $f$ with $\rho_2(f)<1$.
Let $P_d(z,f)=P$, then we rewrite \eqref{F} as
\begin{align}
\label{4.1}
f^n+P=p_1e^{a_1z}+p_2e^{a_2z}+p_3e^{a_3z}.
\end{align}
By Lemma \ref{lm2.7} and Lemma \ref{lm2.8}, we have $m(r,f)=O(r)$. So $f$ is transcendental. By Lemma \ref{lm2.1}, $f$ is an entire function and $T(r,f)=O(r)$.

 Without loss of generality, we assume of $P_d(z,0)\not\equiv0$.  Otherwise, we make
the transformation $g+a=f$ for a suitable constant $a$, such $a^n+P_d(z,a)\not=0$. Then \eqref{4.1} is converted
to the form $g^n+Q(z,g)= p_1e^{a_1z}+p_2e^{a_2z}+p_3e^{a_3z}$, where $Q(z,g)$ is a difference polynomial in $g$ of degree $d=n-1$ and $Q(z,0)=a^n+P_d(z,a)\not\equiv0$.

 By Lemma \ref{c2.11}, we have $m(r,\frac{1}{f})=S(r,f)$, and $m(r,\frac{a_j}{f^n})=S(r,f),~j=1,2,3$.
Since $\frac{a_1}{a_2}\in \{ \frac{s}{n}:1\le s \le n-1\}$,  $\frac{a_3}{a_2}\in \{ \frac{t}{n}:1\le t \le n-1\}$, where $s,t$ are positive integer. $\frac{e^{a_1z}}{f^{n-1}}=\left(\frac{e^{a_2z}}{f^n}\right)^{\frac{s}{n}}\frac{1}{f^{n-1-s}}$. $\frac{e^{a_3z}}{f^{n-1}}=\left(\frac{e^{a_2z}}{f^n}\right)^{\frac{t}{n}}\frac{1}{f^{n-1-t}}$, then we have $m(r,\frac{e^{a_1z}}{f^{n-1}})=S(r,f)$ and $m(r,\frac{e^{a_3z}}{f^{n-1}})=S(r,f)$.

Differentiating \eqref{4.1}  and eliminating $e^{a_2z}$ yields
\begin{align}
\label{4.2}
f^{n-1}(a_2f-nf')+a_2P-P'=(a_2-a_1)p_1e^{a_1z}+(a_2-a_3)p_3e^{a_3z}.
\end{align}

 Let $E_1=\{\theta\in[0,2\pi):|f(re^{i\theta})|\le1\}$, $E_2=\{\theta\in[0,2\pi):|f(re^{i\theta})|>1\}$, and
 \begin{align}
 \label{4.3}
\phi(z)=a_2f-nf'.
 \end{align}


If $\theta_1\in E_1$, then $ \phi(re^{i\theta_1}) = a_2f(re^{i\theta_1})-f(re^{i\theta_1})\frac{f'(re^{i\theta_1})}{f(re^{i\theta_1})}$. By logarithmic derivative lemma and $|f(re^{i\theta})|\le1$, we have  $\int_{E_1}\log^{+}|\phi(re^{i\theta_1})|d\theta=S(r,f)$.
If  $\theta_1\in E_2$, then rewrite \eqref{4.3} into  $\phi=-\frac{a_2P-P'}{f^{n-1}}+(a_2-a_1)p_1\frac{e{^{a_1z}}}{f^{n-1}}+(a_2-a_3)p_3\frac{e^{a_3z}}{f^{n-1}}$. By Lemma \ref{lm2.7}, $|f(re^{i\theta})|>1$, $m(r,\frac{e^{a_1z}}{f^{n-1}})=S(r,f)$ and $m(r,\frac{e^{a_3z}}{f^{n-1}})=S(r,f)$, then $\int_{E_2}\log^{+}|\phi(re^{i\theta_1})|d\theta=S(r,f)$. So $\phi$ is an entire function satisfies $m(r,\phi)=S(r,f)$.

Using Lemma \ref{lm3.5}  to \eqref{4.3},  we get $f(z)=c_1e^{\frac{a_2z}{n}}+\gamma(z)$, where $|\gamma(z)|\le e^{o(1)|z|}$ uniformly in $\overline S_{1,\epsilon}\cup \overline S_{2}$ as $z\to\infty$, $c_1$ is a constant. Because $T(r,f)=O(r)$, so $\rho(f)=\mu(f)=1$, $\rho(\gamma)\le1$. If $\rho(\gamma)<1$
, then $\gamma$ is a small function of $f$. If $\rho(\gamma)=1$, then by applying the Phragm\'en-Lindel\"of theorem (see \cite[Theorem 7.3]{holl}) to the $\gamma(z)$, we have $|\gamma(z)|\le e^{o(1)|z|}$ uniformly as $z\to\infty$ in $\mathbb{C}$, so $\gamma$ is  also a small function of $f$.
Subsisting $f$ into \eqref{F}, we have $c_1^n=p_2$. This completes the proof.
\end{proof}


\begin{proof}[Proof of Theorem 1.3]
Suppose $f$ is a meromorphic solution \eqref{th1.3} such that
$T(r,p_j)$$=S(r,f),$ $~j=1,2,3$. We aim for a contradiction. It is easy to see
$T(r,f)\le O(r)+S(r,f)$  and $N(r,f)=S(r,f)$. Thus the small function of
$f$ is also the small function of $e^{z}$. By Lemma \ref{lm2.8}, we have  $T(r,f)=O(r)$,
write \eqref{th1.3} as
\begin{align*}
(fe^{\frac{-a_3z}{n}})^n-p_3=p_1e^{(a_1-a_3)z}+p_2e^{(a_2-a_3)z}.
\end{align*}

Let $g=fe^{\frac{-a_3z}{n}}$, $b_1=a_1-a_3\not=0$, $b_2=a_2-a_3\not=0$. Then
\begin{align}
\label{4.4}
g^n-p_3=p_1e^{b_1z}+p_2e^{b_2z}.
\end{align}
By Lemma \ref{lm2.8}, we have
\begin{align}
\label{4.5}
T(r,g)=O(r),~m(r,\frac{1}{g})=S(r,g).
\end{align}
Thus $S(r,g)=S(r,f)=S(r,e^{z})$,  then $~N(r,g)=S(r,g).$
Differentiating \eqref{4.4} yields
\begin{align}
\label{4.6}
ng^{n-1}g'-p_3'=(p_1'+b_1p_1)e^{b_1z}+(p_2'+p_2b_2)e^{b_2z}.
\end{align}
Eliminating $e^{b_2z}$ from \eqref{4.6} and \eqref{4.4}, we have
\begin{align}
\label{4.7}
    np_2g^{n-1}g'-(p_2'+p_2b_2)g^n+P=Ae^{b_1z},
\end{align}
where $P=-p_2p_3'+p_3(p_2'+b_2p_2)$, $A=p_2(p_1'+b_1p_1)-p_1(p_2'+b_2p_2)$.
We claim $A\not\equiv0$, $P\not\equiv0$. Otherwise, if $A\equiv0$, then $b_1-b_2=\frac{p_2'}{p_2}-\frac{p_1'}{p_1}$. By integration, we get $e^{(b_1-b_2)z}=c\frac{p_2}{p_1}, c \in\mathbb{C}\setminus0$, which implies $b_1=b_2$, it is a contradiction. Thus $A\not\equiv0$.
Using the same idea we have $P\not\equiv0$.
Differentiating \eqref{4.7} yields
\begin{align}
\label{4.8}
np_2g^{n-2}(g')^2+np_2'g^{n-1}g'&+np_2g^{n-1}g''-(p'+p_2b_2)'g^n+(p'+p_2b_2)g^{n-1}g'+P'\\ \nonumber
&=(A'+Ab_1)e^{b_1z}.
\end{align}
Eliminating $e^{b_1z}$ from \eqref{4.7} and \eqref{4.8}, then
\begin{align}
\label{4.9}
    g^{n-2}(d_1g^2+d_2gg'+d_3(g')^2+d_4gg'')=R,
\end{align}
where $d_1=(p'+p_2b_2)(A'+Ab_1)-A(A'+Ab_1)'$, $d_2=-np_2(b_1+b_2)A-np_2A'$, $d_3=np_2A$, $d_4=np_2A$, $R=(A'+Ab_1)P-AP'$.

Let $Q(z,g)=d_1g^2+d_2gg'+d_3(g')^2+d_4gg''$, we claim $Q(z,g)\not\equiv0$. Otherwise $R\equiv0=(A'+Ab_1)P-AP'$, by integration $\frac{A}{P}=c_2e^{b_1z},~ c_2 \in\mathbb{C}\setminus0$, it is a contradiction.

By \eqref{4.9} and $m(r,\frac{1}{g})=S(r,g)$, we get $m(r,Q)=S(r,g)$. Thus $T(r,Q)=S(r,g)$.  $T(r,g^{n-2})=T(r,\frac{R}{Q})=S(r,g)$, note that $n\ge3$, we get a contradiction, and then the proof is completed.
\end{proof}











