In the HB$\chi$PT formalism, the LO baryon Lagrangian reads~\cite{Ou-Yang:2024neq,Wang:2018gpl},
\begin{equation}
\begin{aligned}
\mathcal{L}_{\mathcal{T/N}\phi}^{(1)}=&\left\langle\overline{\mathcal{N}}(i v \cdot D) \mathcal{N}\right\rangle-i\left\langle \overline{\mathcal{T}}^\mu(v \cdot D-\delta) \mathcal{T}_\mu\right\rangle   \\
&+\mathcal{C}\left\langle\overline{\mathcal{T}}^\mu u_\mu \mathcal{N}\right\rangle+\text { H.c. }+2 \mathcal{H} \left\langle\overline{\mathcal{T}}^\mu S^\nu u_\nu \mathcal{T}_\mu\right\rangle,    
\end{aligned}
\end{equation}
\begin{equation}\label{eq:L_BPhi_1}
\begin{aligned}
\mathcal{L}_{\mathcal{B} \phi}^{(1)} = &\frac{1}{2}\left\langle\bar{\mathcal{B}}_{\bar{3}} i v \cdot D \mathcal{B}_{\bar{3}}\right\rangle+\left\langle\bar{\mathcal{B}}_6\left(i v \cdot D-\delta_2\right) \mathcal{B}_6\right\rangle-\left\langle\bar{\mathcal{B}}_6^*\left(i v \cdot D-\delta_3\right) \mathcal{B}_6^*\right\rangle \\
& +2 g_1\left\langle\bar{\mathcal{B}}_6 S \cdot u \mathcal{B}_6\right\rangle+2 g_2\left\langle\bar{\mathcal{B}}_6 S \cdot u \mathcal{B}_{\bar{3}}\right\rangle+\text { H.c. }+g_3\left\langle\bar{\mathcal{B}}_{6 \mu}^* u^\mu \mathcal{B}_6\right\rangle+\text { H.c. } \\
& +g_4\left\langle\bar{\mathcal{B}}_{6 \mu}^* u^\mu \mathcal{B}_{\bar{3}}\right\rangle+\text { H.c. }+2 g_5\left\langle\bar{\mathcal{B}}_6^* S \cdot u \mathcal{B}_6^*\right\rangle+2 g_6\left\langle\bar{\mathcal{B}}_{\bar{3}} S \cdot u \mathcal{B}_{\bar{3}}\right\rangle,
\end{aligned}
\end{equation}
where $\delta, \delta_1, \delta_2$, and $\delta_3$ represent the average mass differences between different baryon multiplets:
\begin{equation}
\begin{aligned}
&\delta=M_{\mathcal{T}}-M_{\mathcal{N}}= 294 ~\mathrm{MeV}, \\
	&\delta_1=M_{\mathcal{B}_{6}^*}-M_{\mathcal{B}_{6}}= 67~\mathrm{MeV}, \\
	&\delta_2=M_{\mathcal{B}_{6}}-M_{\mathcal{B}_{\bar{3}}}= 127~\mathrm{MeV}, \\
	&\delta_3=M_{\mathcal{B}_{6}^*}-M_{\mathcal{B}_{\bar{3}}}= 194 ~\mathrm{MeV},
\end{aligned}
\end{equation}
where the masses $M$ refer to the average values within each baryon multiplet. In this work, we neglect the mass splittings among states within the same multiplet. The parameters $\mathcal{C}, \mathcal{H}$, and $g_i$ denote the coupling constants.

The next-to-leading order (NLO) baryon Lagrangian reads:
\begin{equation}\label{eq:L_TPhi_2}
    \mathcal{L}_{\mathcal{T}/\mathcal{N} \phi}^{(2)}=-\left\langle \overline{\mathcal{T}}^\mu\frac{\left(v\cdot D\right)^2-D^2}{2M_{\mathcal{T}}}\mathcal{T}_\mu\right\rangle+b_2 \frac{-i}{2 M_\mathcal{N}} \left\langle \overline{\mathcal{T}}^\mu F_{\mu \nu}^{+} S^\nu \mathcal{N}\right\rangle+ \text{H.c.},
\end{equation}
\begin{equation}\label{eq:L_BPhi_2}
\begin{aligned}
\mathcal{L}_{\mathcal{B} \phi}^{(2)} = & \frac{1}{2}\left\langle \bar{\mathcal{B}}_{\bar{3}} \frac{\left(v\cdot D\right)^2-D^2}{2M_{\bar{3}}}\mathcal{B}_{\bar{3}}\right\rangle+\left\langle \bar{\mathcal{B}}_6 \frac{\left(v\cdot D\right)^2-D^2}{2M_{6}}\mathcal{B}_6\right\rangle-\left\langle \bar {\mathcal{B}}_6^{*\mu} \frac{\left(v\cdot D\right)^2-D^2}{2M_{6^*}}\mathcal{B}_{6\mu}^*\right\rangle\\
& -\frac{i d_2}{4 M_N}\left\langle\bar{\mathcal{B}}_3\left[S^\mu, S^\nu\right] \hat{F}_{\mu \nu}^{+} \mathcal{B}_3\right\rangle-\frac{i d_3}{4 M_N}\left\langle\bar{\mathcal{B}}_3\left[S^\mu, S^\nu\right] \mathcal{B}_3\right\rangle\left\langle F_{\mu \nu}^{+}\right\rangle-\frac{i d_5}{4 M_N}\left\langle\bar{\mathcal{B}}_6\left[S^\mu, S^\nu\right] \hat{F}_{\mu \nu}^{+} \mathcal{B}_6\right\rangle \\
& -\frac{i d_6}{4 M_N}\left\langle\bar{\mathcal{B}}_6\left[S^\mu, S^\nu\right] \mathcal{B}_6\right\rangle\left\langle F_{\mu \nu}^{+}\right\rangle-\frac{i f_2}{4 M_N}\left\langle\bar{\mathcal{B}}_3\left[S^\mu, S^\nu\right] \hat{F}_{\mu \nu}^{+} \mathcal{B}_6\right\rangle+\text { H.c. }+\frac{i f_4}{4 M_N}\left\langle\bar{\mathcal{B}}_3 \hat{F}_{\mu \nu}^{+} S^\nu \mathcal{B}_6^{* \mu}\right\rangle+\text { H.c. } \\
& +\frac{i f_6}{4 M_N}\left\langle\bar{\mathcal{B}}_6 \hat{F}_{\mu \nu}^{+} S^\nu \mathcal{B}_6^{* \mu}\right\rangle+\text { H.c. }+\frac{i f_7}{4 M_N}\left\langle\bar{\mathcal{B}}_6 S^\nu \mathcal{B}_6^{* \mu}\right\rangle\left\langle F_{\mu \nu}^{+}\right\rangle+\text {H.c. }+\frac{i f_9}{4 M_N}\left\langle\bar{\mathcal{B}}_6^{* \mu} \hat{F}_{\mu \nu}^{+} \mathcal{B}_6^{* \nu}\right\rangle \\
& +\frac{i f_{10}}{4 M_N}\left\langle\bar{\mathcal{B}}_6^{* \mu} \mathcal{B}_6^{* \nu}\right\rangle\left\langle F_{\mu \nu}^{+}\right\rangle,
\end{aligned}
\end{equation}
where $b_2,\,d_i$, and $f_i$ are the coupling constants. The traceless part of the field strength tensor, $\hat{f}_{\mu \nu}^{+}=f_{\mu \nu}^{+}-\frac{1}{3} \left\langle f_{\mu \nu}^{+}\right\rangle$ is related to the traceless charge matrix of the light quarks $Q_l=\operatorname{diag}\left(\frac{2}{3},-\frac{1}{3},-\frac{1}{3}\right)$. The trace part $\left\langle f_{\mu \nu}^{+}\right\rangle$ is related to the charge matrix of the charm quark $Q_c=\operatorname{diag}\left(\frac{1}{3}, \frac{1}{3}, \frac{1}{3}\right)$. We use the nucleon mass to render the LECs dimensionless. This choice is particularly convenient, as many physical quantities are often expressed in units of the nuclear magneton. In the following Feynman diagrams, we use black dots ({\large $\bullet$}) to represent the vertices from $\mathcal{L}_{\mathcal{T}/\mathcal{N} \phi}^{(2)}$ and $\mathcal{L}_{\mathcal{B} \phi}^{(2)}$.

The $\mathcal{L}_{\mathcal{T}/\mathcal{N} \phi }^{(3)}$ and $\mathcal{L}_{\mathcal{B} \phi}^{(3)}$ generate Compton scattering amplitudes that are odd in the photon momentum. However, the forward Compton scattering amplitudes are even in photon momentum due to crossing symmetry. Thus $\mathcal{L}_{\mathcal{T}/\mathcal{N} \phi }^{(3)}$ and $\mathcal{L}_{\mathcal{B} \phi}^{(3)}$ do not contribute to the polarizabilities and do not need to be considered explicitly~\cite{Bernard:1991rq,Bernard:1991ru,Bernard:1992qa,Bernard:1993bg,Bernard:1993ry}.

According to the standard power counting~\cite{Bernard:1995dp,Scherer:2002tk}, the chiral order $D_\chi$ of a Feynmen digram is
\begin{equation}
	D_{\chi}=2L+1+\sum_d (d-2)N_d^{\phi}+\sum_d(d-1)N_d^{\phi B},
\end{equation}
where $L$, $N_d^{\phi}$ and $N_d^{\phi B}$ are the numbers of loops, pure meson vertices and meson-baryon vertices, respectively. $d$ is the chiral dimension. 

In the Coulomb gauge,  the photon-baryon-baryon vertices derived from $\mathcal{L}_{\mathcal{T}/\mathcal{N} \phi}^{(1)}$ and $\mathcal{L}_{\mathcal{B} \phi}^{(1)}$ are proportional to $\epsilon \cdot v=0$. This condition significantly reduces the number of Feynman diagrams that need to be calculated. The tree and loop Feynman diagrams contributing to the electromagnetic polarizabilities up to \(\mathcal{O}(p^3)\) are shown in Fig.~\ref{fig:fmdiagrams_full}.  


