Using the $\mathcal{J}$-function defined in Appendix~\ref{appendix:loop_integrals}, we obtain the form factors for the $\mathcal{T}\phi$-loop diagrams in Figs.~\ref{fig:fmdiagrams_full}($c$)--($g$):
\begin{align}
U^{(c)}_{\xi}(\omega)= & C\sum_{\chi}\frac{D^{(c)}_{\xi,\chi}}{F_\chi^2}\mathcal{J}_0(\omega,0,M_{\chi}^2),\label{eq:U_6_c_T}\\
	U^{(d+e)}_{\xi}(\omega)= & C\left[\sum_{\chi} \frac{D_{\xi,\chi}^{(d+e)}}{F_\chi^2}\int_0^1 dx~\mathcal{J}^{\prime}_2(\omega x,0,M_{\chi}^2)\right],\\
	U^{(f)}_{\xi}(\omega)= & C\left[\sum_{\chi} \frac{D_{\xi,\chi}^{(f)}}{F_\chi^2}\int_0^1dx~ (1-x)(d+1)\mathcal{J}_6^{\prime\prime}(\omega x,0,M_{\chi}^2)\right.\notag \\
	&\quad ~ -\left. \sum_{\chi} \frac{D_{\xi,\chi}^{(f)}}{F_\chi^2} \int_0^1dx~\omega^2(1-x)x^2\mathcal{J}_2^{\prime\prime}(\omega x,0,M_{\chi}^2)\right],\\
