	V^{(f)}_{\xi}(\omega)= & C\left[\sum_{\chi} \frac{1}{4 F_\chi^2}D^{(f)}_{\xi,\chi}\int_0^1dx~(1-x)\left[8x(2x-1)+(2x-1)^2(d-1)\right]\mathcal{J}_2^{\prime\prime}(\omega x,0,M_{\chi}^2)\right.\notag \\
