	U^{(f)}_{\xi}(\omega)= & A\left[\sum_{\chi} \frac{D_{\xi,\chi}^{(f)}}{F_\chi^2}\int_0^1dx~ (1-x)(d+1)\mathcal{J}_6^{\prime\prime}(\omega x,0,M_{\chi}^2)\right.\notag \\
	&\quad ~ -\left. \sum_{\chi} \frac{D_{\xi,\chi}^{(f)}}{F_\chi^2} \int_0^1dx~\omega^2(1-x)x^2\mathcal{J}_2^{\prime\prime}(\omega x,0,M_{\chi}^2)\right],\\
	U^{(g)}_{\xi}(\omega)= &A\sum_{\chi}\frac{D^{(g)}_{\xi,\chi}}{F_\chi^2}(d-1)\mathcal{J}_2^{\prime}(0,0,M_{\chi}^2),\\
