	S_\chi&=M_\pi^2\left(10R_\pi+9\delta_1\right)+\delta_1^2\left(-9\delta_1-R_\pi\right).
	\end{aligned}
\end{equation}

In the heavy quark limit with $g_5^2 = 3 g_3^2$~\cite{Cheng:1993kp,Cho:1992nt,Jiang:2015xqa} and  $\delta_1 = 0$ , we have
\begin{equation}
	R_\chi = \frac{\pi M_\chi}{2}, \quad S_\chi = 5 \pi M_\chi^3.
\end{equation}
It is easy to verify that in the heavy quark limit:
\begin{equation}\label{eq:relation_hqs}
	\alpha_E^{(c-g)}(\xi) =5 \alpha_E^{(c'-g')}(\xi),\quad \beta_M^{(c-g)}(\xi) = 5 \beta_M^{(c'-g')}(\xi).
\end{equation}
In realistic physical scenarios, $\delta_1$ represents a non-zero mass splitting that reduces the energy difference between $\mathcal{B}_6\phi$ and $\mathcal{B}_6^*$. Therefore, we expect the electromagnetic polarizabilities arising from the $\mathcal{B}_6\phi$-loop diagrams to be enhanced compared to those in the heavy quark limit.

Finally, by summing all the contributions calculated above, we can obtain the total electromagnetic polarizabilities:
\begin{equation}
	\begin{aligned}
	\alpha_E^{\mathrm{Tot.}}(\xi) &=\alpha_E^{(c-g)}(\xi)+\alpha_E^{(c^\prime-g^\prime)}(\xi),\\
	\beta_M^{\mathrm{Tot.}}(\xi) &=\beta_M^{(b^\prime)}(\xi)+\beta_M^{(c-g)}(\xi)+\beta_M^{(c^\prime-g^\prime)}(\xi).
    \end{aligned}
\end{equation}



\subsection{NUMERICAL RESULTS}\label{sec:NUMERICAL_RESULTS}

The low-energy constant $g_2$ can be determined by decay width of $\Sigma_c$,
\begin{equation}
\Gamma\left(\Sigma_c \rightarrow \Lambda_c \pi\right)=\frac{g_2^2}{4 \pi f_\pi^2} \frac{M_{\Lambda_c}}{M_{\Sigma_c}}\left|\vec{p}_\pi\right|^3,
\end{equation}
\begin{equation}
    g_2=-0.568 \pm 0.023.
\end{equation}
The other low energy constants $g_3,g_5$ can be extracted with the help of quark model~\cite{Yan:1992gz}. 
\begin{equation}
    g_3=-\sqrt{2} g_2=0.803\pm 0.080\pm0.032 , \quad g_5=\sqrt{6}g_2=-1.39 \pm0.14\pm 0.056,
\end{equation}
The first uncertainty arises from the assumed 10\% error introduced by using the quark model, while the second is due to the experimental uncertainty in the $\Sigma_c^{(*)}$ widths. 

In tree diagram Fig.~\ref{fig:fmdiagrams_full}($b'$), the the coefficients $C_\xi$ contain two remaining LECs ($f_6$ and $f_7$), as shown in Table~\ref{tab:C_xi}. For the lack of experimental data of electromagnetic decay of singly heavy barons, we fit the $C_\xi$'s from the quark model and Lattice QCD simulations, following the same approach in our previous work~\cite{Chen:2024xks}. This fit yields the following results (in units of $\mu_N$):
\begin{equation}
	\mu_u=-2\mu_d=1.078(88),\quad \mu_s=-0.456(23),\quad \mu_c=0.205(15),
\end{equation}
The values in parentheses represent the uncertainties originating from the lattice QCD results. It can be seen that the magnetic moment of the charm quark is suppressed by $1/m_c$. Then we calculate the transition magnetic moments for singly charmed baryons in quark model~\cite{Wang:2018gpl}, which are (in units of $\mu_N$):
\begin{align}
	&\mu_{\Sigma_c^{*++} \rightarrow \Sigma_c^{++} \gamma}  =\frac{2 \sqrt{2}}{3}\left(\mu_u-\mu_c\right)=0.82(10),\\
	&\mu_{\Sigma_c^{*+} \rightarrow \Sigma_c^{+} \gamma}  =\frac{ \sqrt{2}}{3}\left(\mu_u+\mu_d-2\mu_c\right)=0.06(3),\\
	&\mu_{\Sigma_c^{*0} \rightarrow \Sigma_c^{0} \gamma}  =\frac{ 2 \sqrt{2}}{3}\left(\mu_d-\mu_c\right)=-0.70(5),\\
	&\mu_{\Xi_c^{*+} \rightarrow \Xi_c^{\prime +} \gamma}  =\frac{ \sqrt{2}}{3}\left(\mu_u+\mu_s-2\mu_c\right)=0.10(6),\\
	&\mu_{\Xi_c^{*0} \rightarrow \Xi_c^{\prime 0} \gamma}  =\frac{ \sqrt{2}}{3}\left(\mu_d+\mu_s-2\mu_c\right)=-0.66(3),\\
	&\mu_{\Omega_c^{*0} \rightarrow \Omega_c^{0} \gamma}  =\frac{2 \sqrt{2}}{3}\left(\mu_s-\mu_c\right)=-0.62(3).
\end{align}
