\section{General Spin-averaged Compton Tensor}\label{appendix:General_Spin-averaged_Compton_Tensor}
The general spin-averaged Compton tensor $\Theta_{\mu \nu}$ with gauge invariance and crossing symmetry can be expressed in terms of four independent basis tensors $\mathcal{L}_i^{\mu \nu}$ that are free from singularities~\cite{Bernabeu:1976jq},
\begin{equation}
\Theta^{\mu \nu}=\sum_{i=1}^4 B_i\left(q^2, Q \cdot K\right) \mathcal{L}_i^{\mu \nu},
\label{eq:general compton}
\end{equation}

\begin{equation}
\begin{aligned}
& L_1^{\mu \nu}=k \cdot k^{\prime} g^{\mu \nu}-k^\mu k^{\prime \nu}, \\
& L_2^{\mu \nu}=k \cdot k^{\prime} Q^\mu Q^\nu-Q \cdot K\left(Q^\mu k^{\prime \nu}+k^\mu Q^\nu\right)+(Q \cdot K)^2 g^{\mu \nu}, \\
&L_3^{\mu \nu}  =k \cdot k^{\prime}\left(Q^\mu k^\nu+k^{\prime \mu} Q^\nu\right)-Q \cdot K\left(k^\mu k^\nu+k^{\prime \mu} k^{\prime \nu}\right), \\
&L_4^{\mu \nu}  =k^{\prime \mu} k^\nu,
\end{aligned}
\end{equation}
where we denote the four-momenta of the initial (final) target particle and photon by p and k (p' and k'),  respectively, and define $Q=\frac{p+p^{\prime}}{2}$,$K=\frac{k+k^{\prime}}{2}$ and $q=p'-p$.

The pole-free part of the electromagnetic polarizabilities arises at the photon momentum order of $O(p^2)$. Consequently, the term $\mathcal{L}_3^{\mu \nu}$, beging of order $O(p^3)$ does not contribute to the polarizabilities. In contrast, the $\mathcal{L}_4^{\mu \nu}$ term does not contribute due to the kinematical zero of the associated factor  $B_4(0,0)$~\cite{Llanta:1979kj}. 

\section{Loop Integrals}\label{appendix:loop_integrals}
To combine propagator denominators, we introduce integrals over Feynman parameters:
\begin{equation}
	\frac{1}{A_1 A_2 \cdots A_n}=\int_0^1 d x_1 \cdots d x_n \delta\left(\sum x_i-1\right) \frac{(n-1)!}{\left[x_1 A_1+x_2 A_2+\cdots x_n A_n\right]^n}.
\end{equation}
To regularize divergent loop integrals, we use the dimensional regularization scheme and expand them around 4-dimensional spacetime. In this way, one can define the loop functions that frequently occur in calculations~\cite{Bernard:1995dp,Scherer:2002tk,Hemmert:1996rw}. Here, we list only those that we need:
\begin{equation}
\begin{aligned}
\frac{1}{i} &\int \frac{d^d \ell}{(2 \pi)^d} \frac{\left\{1, \ell_\mu \ell_\nu, \ell_\mu \ell_\nu \ell_\alpha \ell_\beta\right\}}{(v \cdot \ell-\omega-i \epsilon)\left(M_{\chi}^2-\ell^2-i \epsilon\right)}  \\
&=\left\{J_0\left(\omega, M_{\chi}^2\right)\right.,\quad g_{\mu \nu} J_2\left(\omega, M_{\chi}^2\right)+v_\mu v_\nu J_3\left(\omega, M_{\chi}^2\right),\quad \left.\left(g_{\mu \nu} g_{\alpha \beta}+\text { perm. }\right) J_6\left(\omega, M_{\chi}^2\right)+\ldots\right\}.
\end{aligned}
\end{equation}
All loop-integrals can be expressed via the basis-function $J_0$:
\begin{equation}\label{eq:J0_J2_J6}
\begin{aligned}
	J_0\left(\omega, M_{\chi}^2\right) & =-4 L \omega+\frac{\omega}{8 \pi^2}\left(1-2 \ln \frac{M_\chi}{\mu}\right)-\frac{1}{4 \pi^2} \sqrt{M_{\chi}^2-\omega^2} \arccos \frac{-\omega}{M_\chi}+\mathcal{O}(d-4),\\
J_2\left(\omega, M_{\chi}^2\right) & =\frac{1}{d-1}\left[\left(M_{\chi}^2-\omega^2\right) J_0\left(\omega, M_{\chi}^2\right)-\omega \Delta_{\chi}\right], \\
J_6\left(\omega, M_{\chi}^2\right) & =\frac{1}{d+1}\left[\left(M_{\chi}^2-\omega^2\right) J_2\left(\omega, M_{\chi}^2\right)-\frac{M_{\chi}^2 \omega}{d} \Delta_{\chi}\right].
\end{aligned}
\end{equation}
In Eq.~\eqref{eq:J0_J2_J6} we have used
\begin{equation}
\begin{aligned}
\Delta_{\chi} & =2 M_{\chi}^2\left(L+\frac{1}{16 \pi^2} \ln \frac{M_\chi}{\mu}\right) +\mathcal{O}(d-4),\\
L & =\frac{\mu^{d-4}}{16 \pi^2}\left[\frac{1}{d-4}+\frac{1}{2}\left(\gamma_E-1-\ln 4 \pi\right)\right],
\end{aligned}
\end{equation}
The $\gamma_E=0.557215$ is Euler constant. The scale $\mu$ is introduced in dimensional regularization.

For the spin-averaged forward Compton scattering amplitude, $J_i(-\omega-\delta)$ and $J_i(\omega-\delta)$ always appear symmetrically. Therefore, for simplicity, we define a new $\mathcal{J}$-function:
\begin{equation}
	\mathcal{J}_i(\omega,\delta,M_{\chi}^2)=J_i(\omega-\delta,M_{\chi}^2)+J_i(-\omega-\delta,M_{\chi}^2)
\end{equation}
With $\mathcal{J}_i^{\prime}$ and $\mathcal{J}_i^{\prime \prime}$ we define the first and second partial derivative with respect to $M_{\chi}^2$,

\begin{equation}
\begin{aligned}
\mathcal{J}_i^{\prime}\left(\omega,\delta ,M_{\chi}^2\right) & =\frac{\partial}{\partial\left(M_{\chi}^2\right)} \mathcal{J}_i\left(\omega, \delta,M_{\chi}^2\right) \\
\mathcal{J}_i^{\prime \prime}\left(\omega, \delta,M_{\chi}^2\right) & =\frac{\partial^2}{\partial\left(M_{\chi}^2\right)^2} \mathcal{J}_i\left(\omega,\delta, M_{\chi}^2\right)
\end{aligned}
\end{equation}

\section{The electromagnetic polarizabilities of singly bottom baryons}~\label{appendix:b_baryon_polarizabilities}

The analytical expression for the electromagnetic polarizabilities of singly bottom baryons is basically the same as that for singly charmed baryons. The only difference is that the parameters should be replaced as follows:
\begin{equation}
	g_1\to g_{1,b},\quad g_{3}\to g_{3,b},\quad \delta_1\to \delta_{1,b},\quad C_{\xi}\to C_{\xi,b}.
\end{equation}
Using the same approach as in Sec.~\ref{sec:NUMERICAL_RESULTS}, we determine the parameters as:
\begin{equation}
	g_{3,b}=0.707 \pm 0.071 \pm 0.025,\quad 
    g_{5,b}=1.225 \pm 0.123 \pm 0.043,\quad \delta_{1,b}=20~\mathrm{MeV}.
\end{equation}
The magnetic moment of the $b$ quark cannot be precisely determined due to the lack of experimental or lattice QCD data. However, since the bottom quark is extremely heavy, its magnetic moment should be very small and will not significantly affect the final results. We estimate it as:
\begin{equation}
	\mu_b=(-0.05\pm 0.05)\mu_N.
\end{equation}
