% assigning the lengths $L_b(t)$ to each tip $v$, and $j$.
% We write $\ell(t):=(L_b)_{\mathrm{t}(b)\in \mathcal{T}_t}$, where $\mathrm{t}(b)$ denotes the terminal vertex of $b$.
% Note that the codomain of $\ell$
For $b$ of which the terminal vertex, denoted by $\mathrm{t}(b)$, belongs to $\mathcal{T}_t$,
the length dynamics is governed by
\begin{equation}\label{eq:tipgrowth}
	% \dot{\ell}= \gamma c(\mathcal{T}_t,t) - \rho,
	% \dot{\ell}_v = \gamma_v c(v,t) - \rho_v, \quad v\in \mathcal{T}_t.
	\dot{L}_b = \gamma_v c(v,t) - \rho_v, \quad v=\mathrm{t}(b)\in \mathcal{T}_t,
\end{equation}
where we define
\begin{equation}
	\dot{L}_{b_t^i} := \lim_{h\to 0} \frac{L_{b_{t+h}^i}-L_{b_t^i}}{h}.
\end{equation}
% The parameters defining the tip growing rule $\kappa(\cdot,t)\gamma(\cdot,t),\rho(\cdot,t):\mathcal{T}_t\to \mathbb{R}_{\geq 0}$ are the material cost, the growing rate, and the retraction rate.
% The parameters defining the tip growth rule are the growth rate $\gamma=(\gamma_v):(0,\infty)\to \mathbb{R}^{|\mathcal{T}_t|}_{\geq 0}$ and the retraction rate $\rho=(\rho_v):(0,\infty)\to\mathbb{R}^{|\mathcal{T}_t|}$.
The parameters defining the tip growth rule are the growth rate $\gamma_v\geq 0$ and the retraction rate $\rho_v\in\mathbb{R}$.
Taking into account that the growth only occurs at the tips---not anywhere in the interior of the edge, and supposing that the construction cost rate is $\kappa>0$, we have for $v=\mathrm{t}(b)\in \mathcal{T}_t$:
% and $\mathrm{t}(b)=v$:
\begin{equation}
	% J|_{\partial\Gamma_t} = \left(c|_{\partial \Gamma_t} + \kappa\right)\dot{\ell}_t|_{\partial\Gamma_t},
	% F_v[c] = -\left(c(v,t) + \kappa\right)\dot{\ell}_v(t)=-\gamma_v c(v,t)^2-(\kappa-\rho_v)c(v,t)+\kappa\rho_v.
	\begin{split}
		F_v[c] &= -\left(c(v,t) + \kappa\right)\dot{L}_b(t)\\
		&=-\gamma_v c(v,t)^2-(\kappa-\rho_v)c(v,t)+\kappa\rho_v.
	\end{split}
	% \quad \dot{\ell}_t|_{\partial\Gamma_t} = \gamma c|_{\partial\Gamma_t} - \rho.
	\label{eq:bdry}
\end{equation}
