% We now turn toward a different growth rule in which the retraction-induced growth enhancement idea holds.
The previous result suggests that we might need a mechanism which mitigates the escape of the material.
For this, we now consider a coupling between a growing tip and an oscillating star-shaped network (Figure~\ref{fig:coupled}).
This oscillating network is inspired by a growth cone---a structure on the tip of a growing neurite of a neuron consisting of small spike-like membrane protrusions called filopodia.
The oscillating network will periodically convert and store material, and directly feed it to the growing tip.
This circumvents the disadvantage in the previous set up that the material from the retracting edges has to be transported a long distance to the growing tip.
We shall see that this will indeed produce retraction-induced growth enhancement.

The network structure $\Gamma_t$, $t\geq 0$, now consists of two (topologically) connected components: an edge $e^1_t$ connecting a large pool of material at $v^0_t$ to a growing tip $v^1_t$, and an oscillating network which is an $N$-star graph centered at $v^2_t$ with tips $v^i_t$ for $i=3,\dots,2+N$ connected through $e^i_t$ (Figure~\ref{fig:coupled}).
Mathematically, the tips are $\mathcal{T}_t=\{v^1_t,v^3_t,\dots,v^{2+N}_t\}$, but from the physical point of view we could consider the oscillating network together with $v^1_t$ as parts of a ``compound'' growing tip of the branch $e^1_t$.
% The lengths $\ell(t)$ corresponding to the tips $\mathcal{T}_t=\{v^1_t,v^3_t,\dots,v^{2+N}_t\}$ satisfy the same growth condition \eqref{eq:tipgrowth} with $\gamma=(\gamma,0,\dots,0)+ (0,\gamma,\dots,\gamma)\sin(t/\tau)$ and $\rho\equiv 0$.
We choose the bonds $b^i_t$ with $i=1,3,...,2+N$ pointing away from $v^1_t$ or $v^2_t$ so that $\mathrm{t}(b^i_t)=v^i_t$.
The free material concentration $c$ satisfies \eqref{eq:advdiff} with the same parameter \eqref{eq:param_tipgrowth} as previously.
The lengths $L_{b^i_t}$ satisfy the same growth condition \eqref{eq:tipgrowth} with
% $\gamma=(\gamma,0,\dots,0)+ (0,\gamma,\dots,\gamma)\sin(t/\tau)$ and $\rho\equiv 0$.
\begin{subequations}\label{eq:param_compound}
	\begin{equation}
		\gamma_{v^i_t} = \begin{cases}
			% \gamma(t) = \begin{cases}
			\gamma_0,                                               & \text{ if }i=1,            \\
			\frac{\gamma_0}{2} \left(1+\sin(\frac{t}{\tau})\right), & \text{ if } i=3,\dots,N+2, \\
		\end{cases}
	\end{equation}
	\begin{equation}
		\rho_{v^i_t} = \begin{cases}
			% \rho(t) = \begin{cases}
			0,                                                    & \text{ if }i=1,           \\
			\frac{\rho_0}{2} \left(1-\sin(\frac{t}{\tau})\right), & \text{ if } i=3,\dots,N+2
			% \text{ and } L_{b^i_t}>0 
			\\
		\end{cases}
	\end{equation}
\end{subequations}
Here, for $v^i_t$, $i=3,\dots,N+2$, we impose an alternation between growth and retraction with a period $\tau$ and maximal rates $\gamma_0$ and $\rho_0$ respectively.

% The caveat is that we need to adjust the initial length and $\gamma$ so that the lengths remain positive; this is possible since we have a maximum principle which limit the concentration at the tips.
The vertex condition at the material source $v^0_t$ is given by
\begin{subequations}\label{eq:vc_compound}
	\begin{equation}
		F_{v^0_t}[c]= k_0(c_* - c(v^0_t,t))
	\end{equation}
	which can be interpreted as supplying the vertex $v_0^0$ with an infinite pool of material of cencentration $c_*$, and $k_0$ is the coupling strength.
	Since we are also coupling the growing tip $v^1_t$ with the oscillating network at $v^2_t$, we will modify the vertex condition \eqref{eq:bdry} by adding coupling terms to $F_{v^1_t}$ and $F_{v^2_t}$ from what would otherwise be the same local tip growth as \eqref{eq:bdry} and Neumann-Kirchoff conditions:
	\begin{equation}
		F_{v^1_t}[c] = -\left(c(v^1_t,t) + \kappa\right)\dot{L}_{b^1_t} - k_1 \left(c(v^1_t,t) - c(v^2_t,t)\right),
	\end{equation}
	\begin{equation}
		F_{v^2_t}[c] = k_1 \left(c(v^1_t,t) - c(v^2_t,t)\right),
	\end{equation}
	\begin{equation}
		F_{v^i_t}[c]=-\left(c(v^i_t,t) + \kappa\right)\dot{L}_{e^i_t}, \quad i=3,\dots,N+2.
	\end{equation}
\end{subequations}
Lastly, the tips of the oscillating network satisfy the same tip growth vertex condition \eqref{eq:bdry}.

In summary, the compound tip growth problem reads
\begin{subequations}\label{eq:compound_tip}
	\begin{equation}
		\partial_t c +  a \partial_x c - D \partial_{xx} c = 0 \quad \text{in}\quad \Gamma_t,\quad t>0,
	\end{equation}
	\begin{equation}
		% \dot{\ell} = \gamma (c(v,t))_{v\in \mathcal{T}_t} - \rho,
		\dot{L}_{e^i_t} =
		\gamma_{v^i_t} c(v^i_t,t) - \rho_{v^i_t},
	\end{equation}
	\begin{equation}
		\sum_{b\in \mathcal{B}_{v^i_t}} J_b(v^i_t,t) = F_{v^i_t}[c],
	\end{equation}
	with parameters in \eqref{eq:param_compound}, vertex conditions \eqref{eq:vc_compound}, and we consider the initial conditions:
	\begin{equation}
		c(\cdot,0)\equiv 0, \quad
		L_{e^1_0} = L_0, \quad
		L_{e^3_0}=\dots=L_{e^{N+2}_0} = L_1
	\end{equation}
	for some $L_1>L_0>0$.
\end{subequations}

