\subsubsection{Model reduction}
Under certain parametric scheme, namely when the diffusion timescale is much smaller than the oscillation timescale, we could reduce the system into a single ODE describing the length dynamics.
% In this note, we present a very simple model of retraction-induced growth enhancement of neurons.
% We are interested in the elongation of a neurite represented by the domain $(0,L(t))$ through which material needs to be transported to the growth cone at the tip $x=L$.
% The bottom line is that we will arrive at an ODE describing the dynamics of the length $L$,
% from which we observe numerically that that this idea does work when the retracting branches move along with the tip, similar to filopodia at the growth cone.
By assuming
\begin{equation*}
	\frac{L_0^2/D}{\tau} \ll 1,
\end{equation*}
% the concentration of the material being transported satisfies 
we obtain the quasi-steady state advection-diffusion equation for the free material:
\begin{equation}\label{eq:advdiff}
	a\partial_x \tilde{c} - D\partial_{xx} \tilde{c} = 0\quad\text{in}\quad e^1_t.
	% a\partial_x c - D\partial_{xx} \tilde{c} = 0\quad\text{in}\quad e^1_t.
\end{equation}
% The growth cone is modeled as a separated homogeneous compartment with material concentration
Moreover, we assume that the coupling strength $k_1$ is strong---in particular,
\begin{equation*}
	k_1\gg L_0D,
\end{equation*}
so that we approximate
\begin{equation}
	\tilde{c}(v^1_t,t) = \tilde{c}(v^2_t,t).
\end{equation}
Further, by assume in contrast that
\begin{equation*}
	\frac{\tau}{L_1^2/D}\ll 1,
\end{equation*}
we could approximate
\begin{equation}
	\partial_x\tilde{c} = 0 \quad\text{in}\quad e^i_t,\ i=3,\dots,N+2.
\end{equation}
Therefore, the concentration on the oscillating network is approximately constant:
\begin{equation}
	\tilde{c}|_{e^i_t} \equiv C(t),\quad i=3,\dots,N+2.
\end{equation}
Since the material fluxes on $b^1_t$ is constant, the vertex conditions \eqref{eq:vc_compound} for \eqref{eq:advdiff} at $v^0_t,v^1_t$ are reduced to
\begin{equation}\label{eq:bdry_gc}
	J_{b^1_t}:=a\tilde{c} - D\partial_x \tilde{c} \equiv  %\begin{cases}
	k (c_*-\tilde{c}(0,t)) % & \text{at}\quad x=0, \\
	% k_1 (\tilde{c}-c)   & \text{at}\quad x=L.
	% \end{cases}
	= (C(t)+\kappa) \left(\dot{L}_{e^1_t}+\sum_{i=3}^{N+2}\dot{L}_{e^i_t}\right).
\end{equation}
% Here, the base of the neurite is coupled with an infinite pool of material of a fixed concentration $c_*$, and $k$ are coupling parameters;
% $\kappa$ is the cost rate of the construction, and $l=l(t)$ is the length of $N$ small branches at the growth cone which rapidly alternates between growth and retraction.
% Let us denote by $c= \tilde{c}(L,t)$ the growth cone material concentration and the
% \begin{equation}\label{eq:growthcone}
% 	V \dot{c} = AJ|_L - \kappa (\dot{L} + N\dot{l})
% \end{equation}
% where $V$ and $A$ are growth cone volume and cross sectional area, $\kappa$ is the cost rate of the construction, and $l=l(t)$ is the length of $N$ small branches at the growth cone which rapidly alternates between growth and retraction.
For simplicity, we modify the length dynamics so that
\begin{equation}\label{eq:reduced_growth}
	\dot{L}_{e^1_t} = \gamma C,\quad \dot{L}_{e^i_t}=\gamma C \sin (t/\tau),\quad i=3,\dots,N+2,
\end{equation}
Here, in \eqref{eq:bdry_gc} and \eqref{eq:reduced_growth}, we remove the $0$ subscription from $k_0$ and $\gamma_0$ to avoid cluttering of notations.

% where $\gamma$ is the growth rate and the period of growth-retraction oscillation is of period $\tau/2\pi$.
% Note that the approximation \eqref{eq:advdiff} should hold for $L\ll D/\gamma$ and $\tau\approx L/\gamma$.
% With this, we can rewrite \eqref{eq:growthcone} as
% \begin{equation}
% 	\dot{c} = - \left(\frac{\kappa\gamma}{V} \left(1 - N\sin \frac{t}{\tau}\right) + \frac{Ak_1}{V}\right) c + \frac{Ak_1 \tilde{c}|_L}{V}.
% \end{equation}

We will express $C$ in terms of $L_{e^1_t}$ so that the model is reduced to a single ODE.
Suppose for now that $a\neq 0$.
For notational convenience, we simply write $L=L_{e^1_t}$.
The general solution to the advection-diffusion \eqref{eq:advdiff} reads
\begin{equation}\label{eq:shaftconc}
	\tilde{c}(x,t)= \tilde{c}(0,t) + \partial_x \tilde{c}(0,t)\frac{D}{a} \left(\exp \left(\frac{ax}{D}\right)-1\right).
\end{equation}
For $x=0$, the boundary condition \eqref{eq:bdry_gc} gives
\begin{equation}\label{eq:rootconc}
	\tilde{c}(0,t) = \frac{D}{a+k} \partial_x \tilde{c}(0,t) + \frac{kc_*}{a+k}.
\end{equation}
Substituting \eqref{eq:rootconc} into \eqref{eq:shaftconc} and using the last equality of \eqref{eq:bdry_gc}, we get
\begin{equation}\label{eq:slope}
	\partial_x \tilde{c}(0,t) = \frac{(a+k)C(t)- kc_*}{D + \frac{(a+k)D}{a} \left(\exp \left(\frac{La}{D}\right) - 1\right)}
\end{equation}
Using \eqref{eq:slope} and \eqref{eq:rootconc}, we arrive at
\begin{equation}
	C(t) = \frac{\frac{ak}{a+k}c_* \left(1+ \frac{a+k}{a} \left(\exp \left(\frac{La}{D}\right)-1\right)\right)+ \frac{k^2c_*}{a+k}}{\kappa\gamma \left(1 + N  \sin \frac{t}{\tau}\right) \left(1+ \frac{a+k}{a} \left(\exp \left(\frac{La}{D}\right)-1\right)\right)+k}
\end{equation}
Similarly, for $a=0$, we have
\begin{equation}
	C(t) = \frac{kc_*}{\kappa\gamma\left(1 + N  \sin \frac{t}{\tau}\right) \left(1+ \frac{kL}{D}\right) + k}
\end{equation}
Thus, we obtain
\begin{equation}\label{eq:lengthODE}
	\dot{L} =
	\begin{cases}
		\frac{\frac{ak}{a+k}c_* \left(1+ \frac{a+k}{a} \left(\exp \left(\frac{La}{D}\right)-1\right)\right)+ \frac{k^2c_*}{a+k}}{\kappa \left(1 + N  \sin \frac{t}{\tau}\right) \left(1+ \frac{a+k}{a} \left(\exp \left(\frac{La}{D}\right)-1\right)\right)+k\gamma} & \text{for}\quad a \neq 0, \\
		\frac{kc_*}{\kappa\left(1 + N  \sin \frac{t}{\tau}\right) \left(1+ \frac{kL}{D}\right) + k\gamma}                                                                                                                                                            & \text{for}\quad a = 0.
	\end{cases}
\end{equation}

