\subsection{Discretization}
We will describe a numerical method for \eqref{eq:intstar} and \eqref{eq:bdrystar}.
For each $i$, we subdivide $e^i_*$ into $N$ edges by ``adding'' $N-1$ vertices while preserving the direction of each bond $v^{j}_* \overset{b^i_*}{\longrightarrow} v^k_*$ so that it becomes
\begin{equation*}
	v^j_* \sim v^{i,0}_* 
	\overset{b^{i,1}_*}{\longrightarrow} v^{i,1}_* \overset{b^{i,2}_*}{\longrightarrow} v^{i,2}_*\overset{b^{i,3}_*}{\longrightarrow}\cdots \overset{b^{i,N-1}_*}{\longrightarrow}v^{i,N-1}_*\overset{b^{i,N}_*}{\longrightarrow} v^{i,N}_*\sim v^k_*
	% v^i_N.
\end{equation*}
This yields a (combinatorial) graph $\tilde{\Gamma} = (\mathcal{\tilde{V}},\mathcal{\tilde{E}})$ which is a discretization of $\Gamma_*$.
We seek $c^n = (c^n_{v})_{v\in \mathcal{\tilde{V}}}$ such that $c^n_{v^{i,k}_*} \approx \hat{c}(k\delta x, n \delta t)$ on $e^i_*$ where $\delta t>0$ and $\delta x = 1/N$.

Define the backward time difference operator:
\begin{equation}
	(\mathcal{D}^-_t u)^n := \frac{u^n - u^{n-1}}{\delta t}.
\end{equation}
Denote by $\Delta^\top$ the incidence matrix of $\tilde{\Gamma}$.
Let $l^n = (l^n_{e})_{e\in \mathcal{\tilde{E}}}$ and $\dot{l}^n = (\dot{l}^n_{e})_{e\in \mathcal{\tilde{E}}}$ with $l^n_{e^{i,k}_*}     \approx L^i_{n\delta t}$.
For functions on vertices $u^n=(u^n_{v})_{v\in \mathcal{\tilde{V}}}$ and similarly on edges $w^n = (w^n_{e})_{e\in \mathcal{\tilde{E}}}$,
we can define gradient and divergence on $\tilde{\Gamma}$:
\begin{gather}
	\mathrm{grad}_{\tilde{\Gamma}}\, u^n := \left(\mathrm{diag}\frac{1}{l^n\delta x}\right) \Delta u^n,\\
	\mathrm{div}_{\tilde{\Gamma}}\,w^n := -\frac{1}{\delta x}\Delta^\top w^n.
\end{gather}

After choosing averaging operators $\tilde{\mathcal{A}}:\mathbb{R}^\mathcal{V}\to \mathbb{R}^\mathcal{E}$ and $\mathcal{A}:\mathbb{R}^\mathcal{E}\to \mathbb{R}^\mathcal{V}$, we can write the equation for the finite difference scheme:
\begin{equation}
	\begin{split}
		(\mathcal{D}^-_t c)^n + \left(\mathrm{diag} \frac{1}{\mathcal{A}l^n}\right)\mathrm{div}_{\tilde{\Gamma}}\, \left(- \dot{l}^n\tilde{\mathcal{A}}(\tilde{\xi}c^n) + a^n \tilde{\mathcal{A}} c^n - \mathrm{grad}_{\tilde{\Gamma}}\,c^n\right)\\
		+ \mathrm{diag} \left(\mathcal{A} \left(\frac{\dot{l}^n}{l^n}\right)\right) c^n = s^n + g^n
	\end{split}
	\label{eq:disc_c}
\end{equation}
where, in the simple tip growth, we have
\begin{equation}
	g^n_{v^{i,k}_*} =\begin{cases}
		\frac{1}{l^n_{e^{i,k}_*}\delta x} \left(c^n_{v^{i,k}_*} + \kappa^n_{v^{i,k}_*}\right) \dot{l}^n_{v^{i,k}_*} & \text{if $v^{i,k}_*$ is a tip}, \\
		0                                                                                           & \text{otherwise}.
	\end{cases}
\end{equation}
For the setup in \ref{sec:growth_at_junction} where we have coupling between a growing tip and an oscillating network, we simply add similar coupling terms to $g^n$.

% \subsection{Operator splitting}
% If the averaging operator is of high order accurate, one can do more complicated splitting methods.
% The simplest first order splitting method is as in Algorithm~\ref{algo:split}.
To solve this along with the length dynamic, we apply a first order splitting method as in Algorithm~\ref{algo:split}.
\begin{algorithm}
	\caption{First order splitting method}
	\begin{algorithmic}[1]
		\State Initialize $c^0, l^0$
		\For{$n\in \{1,\cdots,n_*\}$}
		\State $\dot{l}^{n}_{e^i_k} = \gamma^{n-1} c^{n-1}_{v^i_N} - \rho^{n-1}$ if $v^i\in \partial\Gamma_*$
		\State $l^n = l^{n-1} + \dot{l}^{n}\delta t$
		\State Solve the linear system \eqref{eq:disc_c} for $c^n$
		\EndFor
	\end{algorithmic}
\label{algo:split}
\end{algorithm}

