        \int_0^T \sum_{j=1}^m \bigl[ Y_t^{-1} \sigma(t, X_t) \bigr]_j \cdot A_{jk}(t) \, dt \\
        \int_0^T \sum_{j=1}^m \bigl[ Y_t^{-1} \sigma(t, X_t) \bigr]_j \cdot B_{jk}(t) \, dt \\
        \int_0^T \sum_{j=1}^m \bigl[ Y_t^{-1} \sigma(t, X_t) \bigr]_j \cdot C_{jk}(t) \, dt
    \end{align*}
    using nested numerical integration or matrix operations for efficiency.
