\appendix
\section{Topological Properties of \texorpdfstring{$\mathscr{L}_k^\sharp$}{L\_k}}
\label{app:Lk-topology}

Fix an integer \(k \ge 2\) and recall:
\[
  \mathscr{L}_k^\sharp := 
  \left( \bigsqcup_{i=1}^k \mathbb{R}_i \right)\big/\!\sim,
  \quad
  (x,i)\sim(y,j) \iff
  \begin{cases}
    x = y \neq 0,\\
    x = y = 0 \text{ and } i = j.
  \end{cases}
\]

%--------------------------------------------------------------------
\subsection{Local charts and separation axioms}

\begin{proposition}[Local Euclideanity]\label{propA:local}
\(\mathscr{L}_k^\sharp\) is a 1-dimensional, second-countable, \(T_1\) space. Every point
admits a neighbourhood homeomorphic to an open interval in~\(\mathbb{R}\),
so \(\mathscr{L}_k^\sharp\) is locally Euclidean. However, it is \emph{not}
Hausdorff: the \(k\) origins cannot be separated by disjoint opens.
\end{proposition}

\begin{proof}
If \(p = [x]_i\) with \(x \neq 0\), then \(p\) lies in \(\mathbb{R}_i \setminus \{0_i\}\),
which is open and homeomorphic to \((x-\varepsilon,x+\varepsilon)\) via \([x]_i \mapsto x\).
For \(p = o_i\), let \(\varepsilon > 0\) and define
\[
  U_i = \{[x]_i : |x| < \varepsilon\}
        \cup \;\bigcup_{j \neq i}\!\!\;\; \{[x]_j : 0 < |x| < \varepsilon\}.
\]
The map sending \([x]_j \mapsto x\) collapses all origins to 0, yielding
a homeomorphism \(U_i \cong (-\varepsilon, \varepsilon)\).
Second-countability follows from the real lines. Points are closed
since singletons are closed in each \(\mathbb{R}_i\).
No origin can be separated from the others by disjoint opens, proving non-Hausdorffness.
\end{proof}

\begin{lemma}[Indistinguishable origins]\label{lemA:origins-indist}
For every open \(N \subset \mathscr{L}_k^\sharp\) containing \(o_i\) and every \(j\), one has
\(o_j \in N\). Thus all neighbourhood filters of the \(o_i\) coincide.
\end{lemma}

\begin{proof}
From Proposition~\ref{propA:local}, a basic open \(U_i \subset N\)
contains all non-zero \([x]_j\) with \(0 < |x| < \varepsilon\), whose closure
contains each \(o_j\), hence \(o_j \in N\).
\end{proof}

%--------------------------------------------------------------------
\subsection{Path connectivity and fundamental group}

\begin{proposition}[Path-connectedness]\label{propA:path}
\(\mathscr{L}_k^\sharp\) is path-connected.
\end{proposition}

\begin{proof}
Any two points in the same branch can be joined by a straight path.
If \(p\) and \(q\) lie in different branches, join \(p\) to its origin,
use a small neighbourhood around the origins to move to the origin of the second
branch, then go to \(q\). The concatenated path is continuous.
\end{proof}

\begin{proposition}[Trivial fundamental group]\label{propA:pi1}
\(\pi_1(\mathscr{L}_k^\sharp) = 0\).
\end{proposition}

\begin{proof}
Let \(\alpha : S^1 \to \mathscr{L}_k^\sharp\) be a loop. Cover its image with
finitely many local charts as in Proposition~\ref{propA:local}. By successively
deforming each segment into an interval around an origin, one can contract
\(\alpha\) entirely. Hence \(\alpha\) is null-homotopic.
\end{proof}

%--------------------------------------------------------------------
\subsection{A pseudometric model}

\begin{lemma}[Pseudometric generating the topology]\label{lemA:pseudo}
Define
\[
  d\bigl([x]_i, [y]_j\bigr) :=
  \begin{cases}
    |x - y|, & i = j,\\
    |x| + |y|, & i \neq j.
  \end{cases}
\]
Then \(d\) is a pseudometric on \(\mathscr{L}_k^\sharp\), and the open balls
\(B_d(p,\varepsilon)\) form a basis for its topology. Moreover,
\(d(p,q) = 0\) iff \(p = q\) or \(p, q\) are both origins.
\end{lemma}

\begin{proof}
Triangle inequality is clear in both cases. For \([x]_i \notin \{o_1,\dots,o_k\}\),
the ball \(B_d([x]_i, \varepsilon)\) is the usual interval in \(\mathbb{R}_i\).
For an origin \(o_i\), the ball \(B_d(o_i,\varepsilon)\) contains all
\([x]_j\) with \(|x| < \varepsilon\) and all origins. This matches the basic
opens from Proposition~\ref{propA:local}.
\end{proof}

%--------------------------------------------------------------------
\subsection*{Consequences for the main text}

\begin{itemize}[leftmargin=1.4em]
  \item Proposition~\ref{propA:pi1} confirms that
        \(\pi_1(\mathscr{L}_k^\sharp) = 0\): the space is simply connected,
        despite its non-Hausdorff nature.
  \item Lemma~\ref{lemA:origins-indist} explains all failures of path- and
        homotopy-lifting, as continuous maps cannot distinguish among the origins.
\end{itemize}


\section{Failure of Path and Homotopy Lifting}
\label{app:path-homotopy}

Fix the projection \(\pi : \mathscr{L}_k^\sharp \to Y = \Gamma \cup \{z\}\),
the accumulation point \(z \in Y\), and the basepoint
\[
  x_0 = \iota(1) \in U, \quad p_0 = [1] \in \mathscr{L}_k^\sharp.
\]
On \(\mathscr{L}_k^\sharp \setminus \pi^{-1}(z) \cong U\), classical lifting works;
at \(z\), it fails.

%--------------------------------------------------------------------
\subsection{Non-uniqueness of path lifts}

\begin{lemma}\label{lemB:path}
Define
\[
  \alpha : [0,1] \to Y, \qquad
  \alpha(t) =
  \begin{cases}
    \iota(1 - 2t), & 0 \le t < \tfrac{1}{2},\\[4pt]
    z,             & t = \tfrac{1}{2},\\[4pt]
    \iota(2t - 1), & \tfrac{1}{2} < t \le 1.
  \end{cases}
\]
Then \(\alpha\) is continuous (in the subspace topology from \(D\)), with
\(\alpha(0) = \alpha(1) = x_0\) and \(\alpha(\tfrac{1}{2}) = z\).
Moreover, for each \(o_i \in \pi^{-1}(z)\) there exists a unique lift
\(\widetilde\alpha_i : [0,1] \to \mathscr{L}_k^\sharp\) with
\(\widetilde\alpha_i(0) = p_0\) and \(\widetilde\alpha_i(\tfrac{1}{2}) = o_i\).
Hence, there are exactly \(k\) distinct lifts.
\end{lemma}

\begin{proof}
For \(t \neq \tfrac{1}{2}\), \(\alpha(t) \in U\), so the lift must be
\([x]_i\) with \(x = \iota^{-1}(\alpha(t))\). At \(t = \tfrac{1}{2}\), the image is
\(z\), and \(\widetilde\alpha_i(\tfrac{1}{2}) = o_i\) defines a continuous extension
since \(\iota(\mathbb{R} \setminus \{0\})\) accumulates only at \(z\).
By Lemma~\ref{lemA:origins-indist}, distinct \(o_i\) yield distinct lifts,
yielding \(k\) total lifts.
\end{proof}

\begin{corollary}\label{corB:noULP}
The map \(\pi\) fails the unique path-lifting property and is therefore not a semicovering.
\end{corollary}

%--------------------------------------------------------------------
\subsection{Failure of homotopy lifting}

\begin{theorem}\label{thmB:homotopy}
There exists a homotopy
\[
  H : [0,1]^2 \to Y, \qquad
  H(s,0) = H(s,1) = x_0, \quad H(\tfrac{1}{2},t) = z,
\]
but no continuous lift \(\widetilde H : [0,1]^2 \to \mathscr{L}_k^\sharp\) with
\(\widetilde H(s,0) = p_0\) can exist.
\end{theorem}

\begin{proof}
Suppose \(\widetilde H\) exists. Then
\[
  f(s) := \widetilde H(s,1) \in \{o_1, \dots, o_k\}
\]
defines a continuous map into a discrete set of indistinguishable points.
By Lemma~\ref{lemA:origins-indist}, such a map must be constant.
However, evaluating at \(s=0\) and \(s=1\) yields distinct \(o_i\), a contradiction.
\end{proof}

%--------------------------------------------------------------------
\subsection*{Summary}

Lemmas~\ref{lemB:path} and Theorem~\ref{thmB:homotopy} confirm that
\(\pi\) violates classical path- and homotopy-lifting at the single
non-Hausdorff fibre over \(z\), dismantling the usual covering-space
framework.
%======================================================================
\section{The Deck--Transformation Group}
\label{app:deck}

Let \(p : \widetilde X \to X\) be a covering map.
A \emph{deck transformation} is a homeomorphism
\(h : \widetilde X \to \widetilde X\) satisfying \(p \circ h = p\).
For the projection \(\pi : \mathscr{L}_k^\sharp \to Y = \Gamma \cup \{z\}\),
we determine \(\Deck(\pi)\).

%--------------------------------------------------------------------
\begin{lemma}
The map \(\pi\) is injective on
\(V = \mathscr{L}_k^\sharp \setminus \pi^{-1}(z)\),
so any deck transformation must restrict to the identity on \(V\).
\end{lemma}

%--------------------------------------------------------------------
\begin{proposition}[Deck group]\label{propC:deck}
\[
  \Deck(\pi) \;\cong\; \mathfrak S_k.
\]
\end{proposition}

\begin{proof}
For each permutation \(\sigma \in \mathfrak S_k\), define
\[
  h_\sigma\bigl([x]_i\bigr) :=
  \begin{cases}
    [x]_{\sigma(i)}, & x \neq 0,\\
    o_{\sigma(i)},   & x = 0.
  \end{cases}
\]

\emph{(i) Well-defined and continuous.}  
For \(x \neq 0\), the class \([x]_i\) is independent of \(i\), so the assignment is consistent.
Each branch \(\mathbb{R}_i\) is mapped homeomorphically onto \(\mathbb{R}_{\sigma(i)}\),
and the indistinguishability of the origins (Lemma~\ref{lemA:origins-indist}) ensures continuity at \(x = 0\).

\emph{(ii) Commutativity with \(\pi\).}  
For \(x \neq 0\), we have
\[
  \pi(h_\sigma([x]_i)) = \iota(x) = \pi([x]_i),
\]
and for \(x = 0\), both sides equal \(z\). Hence \(h_\sigma \in \Deck(\pi)\).

\emph{(iii) Isomorphism.}  
The assignment \(\sigma \mapsto h_\sigma\) defines an injective homomorphism
\(\mathfrak S_k \hookrightarrow \Deck(\pi)\).  
Conversely, any \(h \in \Deck(\pi)\) must act as the identity on \(V\)
since \(\pi\) is injective there.
Thus \(h\) is uniquely determined by its action on the origins,
which must be a permutation, proving surjectivity.
\end{proof}

%--------------------------------------------------------------------
\begin{corollary}\label{corC:not-regular}
Although \(\pi|_V : V \xrightarrow{\cong} U\) is a local homeomorphism,
the full map \(\pi\) is not a regular (Galois) cover in the classical sense
over Hausdorff spaces: the deck group acts trivially on \(V\) but non-trivially
on the inseparable fibre over \(z\).
\end{corollary}

\begin{remark}
Classical \(k\)-sheeted covers of a punctured disk have cyclic deck groups;
here, the non-Hausdorff fibre inflates that symmetry to the full symmetric group
\(\mathfrak S_k\).
\end{remark}


%======================================================================
\section{A Full-Disk Variant}
\label{app:full-disk}

The main text fixes the codomain \( Y = \Gamma \cup \{z\} \). For readers who prefer a surjective map onto the \emph{entire} disk \( D \), we describe a radially extended version that preserves all pathologies documented in Sections~\ref{sec:failure}–\ref{sec:comparison}.

%--------------------------------------------------------------------
\subsection{Radially thickened total space}

Define the thickened total space:
\[
  \mathfrak{L}_k^\sharp := 
  \left( \mathscr{L}_k^\sharp \times [0,1] \right) \big/ 
  \bigl( ([x]_i,1) \sim ([x]_j,1) \text{ for all } x, i, j \bigr).
\]
Geometrically, each branch of \( \mathscr{L}_k^\sharp \) is thickened into a “radial tube,” and the outer ends of all tubes (\( t = 1 \)) are glued together to form a shared boundary circle.

%--------------------------------------------------------------------
\subsection{The map \texorpdfstring{$\mathfrak{p}$}{��}}

Let \( r : D \setminus \Gamma \to [0,1] \) denote the normalized radial distance from \( \Gamma \) to \( \partial D \). Define
\[
  \mathfrak{p} \bigl( [x]_i, t \bigr) := (1 - t)\,\iota(x) + t \cdot r\bigl( \iota(x) \bigr) \cdot \frac{ \iota(x) }{ \| \iota(x) \| }.
\]

\begin{lemma}\label{lemD:basic}
The map \( \mathfrak{p} : \mathfrak{L}_k^\sharp \to D \) is continuous and surjective.  
Its fibre over \( z \) is \( \{o_1, \dots, o_k\} \), retaining its non-Hausdorff structure.
\end{lemma}

\begin{proof}[Sketch]
Continuity is straightforward away from \( z \). At \( t = 1 \), all tube endpoints map to \( \partial D \), leaving the fibre over \( z \) unchanged. Surjectivity follows from the radial interpolation from \( \iota(x) \) to the boundary.
\end{proof}

%--------------------------------------------------------------------
\subsection{Persistence of the pathologies}

\begin{proposition}\label{propD:pathologies}
The map \( \mathfrak{p} \) exhibits exactly the same pathologies as the core construction:
\begin{enumerate}[label=(\alph*)]
  \item \( \mathfrak{p} \) restricts to a \( 1 \)-sheeted covering on 
        \( \mathfrak{L}_k^\sharp \setminus \mathfrak{p}^{-1}(z) \).
  \item Path and homotopy lifting fail; monodromy is undefined.
  \item The deck transformation group is \( \Deck(\mathfrak{p}) \cong \mathfrak{S}_k \), acting by permutation of the radial tubes.
\end{enumerate}
\end{proposition}

\begin{proof}[Idea]
One lifts loops and homotopies from Appendix~\ref{app:path-homotopy} by holding the \( t \)-coordinate fixed; uniqueness fails as before. Any deck transformation must fix all points with \( t > 0 \), hence corresponds to permuting the tubes, yielding \( \mathfrak{S}_k \).
\end{proof}

%--------------------------------------------------------------------
\subsection*{Illustration}

\begin{figure}[ht]
\centering
\begin{tikzpicture}[scale=1,cap=round,>=stealth]

  % ambient closed disk (context only)
  \draw[dashed, gray!40] (0,0) circle (3);
  \node[gray!60,scale=0.8] at (2.9,-2.4) {$D$};

  % singular point  z
  \filldraw[black] (0,0) circle (2pt) node[below right] {$z$};

  % image curve  Γ
  \draw[very thick, teal, ->]
        (-2,-1)  .. controls (-1,-0.3) and ( 1,0.4) .. (2,1);
  \node[teal] at (2.3,1.3) {$\Gamma$};

  % three radial tubes  (k = 3)
  \foreach \y/\lab in {1.1/1, 0/2, -1.1/3}{
      % horizontal branch segment
      \draw[very thick, pink!70] (-4,\y) -- (-2.6,\y);
      % curved arrow into z
      \draw[->, thick]
            (-2.4,\y) .. controls (-1.4,0.45*\y) and (-0.6,0.25*\y) ..
            (0,0);
      % branch label
      \node[left] at (-4.2,\y) {$\R_{\lab}$};
  }

  % legend
  \node at (4,0) {$\mathfrak{L}_k^\sharp \longrightarrow \cdots$};

\end{tikzpicture}
\caption{Radial thickening of each branch of \(\mathscr{L}_k^\sharp\) (shown for \(k=3\));
each tube still collapses to the same non-Hausdorff fibre over \(z\),
while \(\mathfrak{p}\) is a 1-sheeted local homeomorphism away from \(z\).}
\label{fig:radial-extension}
\end{figure}

This full-disk version confirms that \textbf{the Hausdorffness of the
\emph{total} space, not the niceness of the base, is the critical
axiom}.  Readers interested in 2-manifold settings may adopt
\(\mathfrak{p}\) as their working example; all the failures reported in
Sections~\ref{sec:failure}–\ref{sec:comparison} hold verbatim.



