\subsection{Implementation  of GSFR }\label{imple}
\hspace{2em}
In this subsection, we present the implementation procedure of the GSFR algorithm, which consists of the following steps:

{\itshape
\begin{enumerate}[label=(\arabic*)]
    \item 
    \textbf{Initialization:} Set $\hat{J}_0 = \emptyset$, the maximum number of iterations $m_{\mathrm{stop}} = K_n$, and the iteration index $m = 1$.

    \item 
    \textbf{Variable Selection:} At the $m${\text{th}} step, for each predictor variable $j = 1, \dots, p$, compute $\hat{\mu}_{\hat{J}_m-1,j}$, and select
    \[
    \hat{j}_{m} = \arg\max_{1 \le j \le p} \left|\hat{\mu}_{\hat{J}_m-1,j}\right|.
    \]

    \item 
    \textbf{Prediction and Residuals:} Update predictions and compute residuals as
    \[
    \hat{y}_{m}(\mathbf{x}_t) = \hat{y}_{m-1}(\mathbf{x}_t) + \hat{\beta}_{\hat{j}_{m}} \hat{x}_{t \hat{j}_{m}; \hat{J}_m-1}^{\perp}, \quad
    U_t^{(m)} = y_t - \hat{y}_{m}(\mathbf{x}_t),
    \]
    where
    \[
    \hat{\beta}_{\hat{j}_{m}} = \frac{\sum_{t=1}^{n}y_t\hat{x}_{t \hat{j}_{m}; \hat{J}_{m-1}}^{\perp}}{\sum_{t=1}^{n}(\hat{x}_{t \hat{j}_{m}; \hat{J}_{m-1}}^{\perp})^2}, \quad (1 \le t \le n).
    \]

    \item 
    \textbf{Orthogonalization:} Update the orthogonalized predictor variables. For \( j = 1, \dots, p \), compute
    \[
    \hat{x}_{t j; \hat{J}_{m}} = \hat{x}_{t j; \hat{J}_{m-1}} + \hat{\alpha}_{j ; \hat{j}_{m}} \hat{x}_{t \hat{j}_{m}; \hat{J}_{m-1}}^{\perp}, \quad
    \hat{x}_{t j; \hat{J}_{m}}^{\perp} = x_{t j} - \hat{x}_{t j; \hat{J}_{m}},
    \]
    where
    \[
    \hat{\alpha}_{j ; \hat{j}_{m}} = \frac{\sum_{t=1}^{n} x_{t j} \hat{x}_{t \hat{j}_{m}; \hat{J}_{m-1}}^{\perp}}{\sum_{t=1}^{n} (\hat{x}_{t \hat{j}_{m}; \hat{J}_{m-1}}^{\perp})^2}, \quad (1 \le t \le n).
    \]

    \item 
    \textbf{Iteration Check:} Increment \(m\) by one. If \(m \le m_{\mathrm{stop}}\), return to step (2); otherwise, proceed to the next step.

    \item 
    \textbf{Model Size Selection:} Compute
    \[
    \hat{k}_n = \arg\min_{1 \leq m \leq K_n-1} \hat{\triangle}_{\hat{J}_m},
    \]
    and select the estimated optimal model with variable index set \( \hat{J}_{\hat{k}_n} \).
\end{enumerate}
}



