Similar to \citet{ingStepwiseRegressionMethod2011}, we replace \( x_{tj} \) with \( x_{tj} / \sigma_j \) and \( x_j \) with \( x_j / \sigma_j \) in both GSFR and its population version. This standardization allows us to assume, without loss of generality, that \( \sigma_j = 1 \), for all \( 1 \leq j \leq p_n \), leading to \( z_j = x_j \).



\subsection*{Lemmas for Theorem \ref{theorem1}}
The following lemmas, adapted from \citet{ingStepwiseRegressionMethod2011} to fit the GSFR framework, play a key role in proving Theorem \ref{theorem1}. Detailed proofs can be found in the supplementary material of \citet{ingStepwiseRegressionMethod2011}.

\begin{lemma}
With the same notation and assumptions as {those} in Theorem \ref{theorem1}, 
there exists $C>0$ such that
\begin{equation}
\max _{1 \leq i, j \leq p_{n}} P\left\{\left|\sum_{t=1}^{n}\left(x_{t i} x_{t j}-\sigma_{i j}\right)\right|>n \delta_{n}\right\} \leq \exp \left(-C n \delta_{n}^{2}\right)
\nonumber
\end{equation}
for all large $n$, where $\sigma_{i j}=\operatorname{Cov}\left(x_{i}, x_{j}\right)$ and $\delta_{n}$ are positive constants satisfying $\delta_{n} \rightarrow 0$ and $n \delta_{n}^{2} \rightarrow \infty$ as $n \rightarrow \infty$. Define \(\boldsymbol{\Gamma}(J)\) as in  (\ref{assumption5_equation1}), and let \(\hat{\boldsymbol{\Gamma}}_{n}(J)\) be the corresponding sample covariance matrix.
Then, for all large $n$,
\begin{equation}
P\left\{\max _{1 \leq \sharp(J) \leq K_{n}}\left\|\hat{\boldsymbol{\Gamma}}_{n}(J)-\boldsymbol{\Gamma}(J)\right\|>K_{n} \delta_{n}\right\} \leq p_{n}^{2} \exp \left(-C n \delta_{n}^{2}\right).
\nonumber
\end{equation}
If furthermore $K_{n} \delta_{n}=O(1)$, then there exists $c>0$ such that
\begin{equation}
P\left\{\max _{1 \leq \sharp(J) \leq K_{n}}\left\|\hat{\boldsymbol{\Gamma}}_{n}^{-1}(J)-\boldsymbol{\Gamma}^{-1}(J)\right\|>K_{n} \delta_{n}\right\} \leq p_{n}^{2} \exp \left(-c n \delta_{n}^{2}\right)
\nonumber
\end{equation}
for all large $n$, where $\hat{\boldsymbol{\Gamma}}_{n}^{-1}$ denotes a generalized inverse when $\hat{\boldsymbol{\Gamma}}_{n}$ is singular.
\label{lemma1}
\end{lemma}
\par

\begin{lemma}
With the same notation and assumptions as 
{those} in Lemma \ref{lemma1}, let $\delta_{n}$ be positive numbers such that $\delta_{n}=O\left(n^{-\theta}\right)$ for some $0<\theta<1 / 2$ and $n \delta_{n}^{2} \rightarrow \infty$. Then there exists $\eta>0$ such that for all large $n$,
\begin{equation}
\max _{1 \leq i \leq p_{n}} P\left(\left|\sum_{t=1}^{n} \varepsilon_{t} x_{t i}\right| \geq n \delta_{n}, \Omega_{n}\right) \leq \exp \left(-\eta n \delta_{n}^{2}\right),
\nonumber
\end{equation}
where $\Omega_{n}=\left\{\max _{1 \leq t \leq n}\left|\varepsilon_{t}\right|<(\log n)^{2}\right\}$. It follows from assumption (\ref{assumption2}) that $\lim _{n \rightarrow \infty} P\left(\Omega_{n}^{c}\right)=0$.
\label{lemma2}
\end{lemma}
\par

\begin{lemma}
With the same notation and assumptions as {those} in Lemma \ref{lemma1}, and using Lemmas \ref{lemma1} and \ref{lemma2}, the following result holds for some $\lambda>0$,
\begin{equation}
\begin{array}{l}
P\left(\max _{\sharp(J) \leq K_{n}-1, i \notin J}\left|n^{-1} \sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i ; J}^{\perp}\right|>\lambda\left(\frac{\log p_{n} }{n}\right)^{1 / 2}, \Omega_{n}\right)=o(1), \\
P\left(\max _{i, j \notin J, \sharp(J) \leq K_{n}-1}\left|n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i ; J}^{\perp}-E\left(x_{j} x_{i ; J}^{\perp}\right)\right|>\lambda\left(\frac{\log p_{n} }{n}\right)^{1 / 2}\right)=o(1).
\end{array}
\nonumber
\end{equation}
\label{lemma3}
\end{lemma}
\par



\begin{lemma}
We cite Theorem 2 from \citet{borodinProjectionGreedyAlgorithm2021} to demonstrate the convergence rate of the semi-population version of GSFR. Let
\begin{equation*}
 x_{0} \in \mathcal{D}^{\lambda}:=\overline{\left\{\sum_{k=1}^{m} \lambda_{k} s_{k}: s_{k} \in D, m \in \mathbb{N}, \sum_{k=1}^{m}\left|\lambda_{k}\right| \leq \lambda\right\}}.
\end{equation*}
Then
\begin{equation}
\left|x_{n}\right| \leq \frac{\lambda}{\left(1+\sum_{j=0}^{n-1} t_{j}^{2}\right)^{1 / 2}}.
\nonumber
\end{equation}
\label{lemma4}
\end{lemma}

\subsection*{Proof of Theorem \ref{theorem1}}

\begin{proof}
To avoid the possible numerical problem caused by dividing extremely small $\left(\sum_{t=1}^{n} \left(\hat{x}^{\bot}_{t i; J}\right)^{2}\right)^{1/2}$, we prove a more general result  using 
\begin{equation*}
	\hat{\mu}_{J, i} = \frac{n^{-1} \sum_{t=1}^{n} \left(y_{t} - \hat{y}_{t; J}\right) \hat{x}_{t i; J}^{\bot}}{\left(n^{-1} \sum_{t=1}^{n} \left(\hat{x}^{\bot}_{t i; J}\right)^{2}\right)^{1/2}+\rho_{1}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2} },
\end{equation*}
where constant $\rho_{1} \ge 0$.
For $i \notin J$, we further simplify (\ref{ref3}):

\begin{equation}
\mu_{J, i}=\frac{\sum_{j \notin J} \beta_{j} E\left[\left(x_{j}-x_{j}^{(J)}\right) x_{i}\right]}{E\left[{x_{i;J}^{\bot^{2}}}\right]^{1/2}} =\frac{\sum_{j \notin J} \beta_{j} E\left[x_{j}\left(x_{i}-x_{i}^{(J)}\right)\right]}{E\left[{x_{i;J}^{\bot^{2}}}\right]^{1/2}} =\frac{\sum_{j \notin J} \beta_{j} E\left(x_{j} x_{i ; J}^{\perp}\right)}{E\left[{x_{i;J}^{\bot^{2}}}\right]^{1/2}}.
\label{ref6}
\end{equation}

Since $y_{t}=\sum_{j=1}^{p_{n}} \beta_{j} x_{t j}+\varepsilon_{t}$ and $\hat{y}_{t;J} = \sum_{i\in J}\beta _{i}x_{ti} + \sum_{i\notin J}\beta _{i}\hat{x}_{ti;J}+\hat{\varepsilon }_{t;J}$, where $\hat{\varepsilon }_{t;J}$ and $\hat{x}_{t i ; J}$ represent the fitted values of $\varepsilon_{t}$ and $x_{t i}$, respectively, and since 
\(
\sum_{t=1}^{n}\left(\varepsilon_{t}-\hat{\varepsilon}_{t ; J}\right) x_{t i}=\sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i ; J}^{\perp}
\),
by applying (\ref{ref3}) and (\ref{ref6}), it follows that 

\begin{equation}
\begin{aligned}
    \hat{\mu}_{J, i} - \mu_{J, i} 
    &= \frac{n^{-1} \sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i; J}^{\perp}}
    {\left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2}
    +\rho_{1}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2} }  \\
    &\quad + \sum_{j \notin J} \beta_{j} \left\{ 
    \frac{n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp}}
    {\left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2}
    +\rho_{1}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2} } 
    - \frac{E\left(x_{j} x_{i; J}^{\perp}\right)}
    {E\left(x_{i; J}^{\perp^2}\right)^{1/2}} \right\}.
\end{aligned}
\label{ref7}
\end{equation}

We now derive probability bounds for the right-hand side of (\ref{ref7}).  
First, we establish a result similar to (A.15) in \cite{ingStepwiseRegressionMethod2011}.  
By Lemma \ref{lemma3} and for the same $\lambda > 0$,  

\begin{align}
    &P\Bigg(\max_{i \notin J, \sharp(J) \leq K_{n}-1}  
    \Big| n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\perp^2}  
    - E\left(x_{i; J}^{\perp^2}\right) \Big|  
    > \lambda \left ( \frac{\log p_{n} }{n}  \right ) ^{1/2} \Bigg) \nonumber \\
    &= P\Bigg(\max_{i \notin J, \sharp(J) \leq K_{n}-1}  
    \Big| n^{-1} \sum_{t=1}^{n} x_{t i} \hat{x}_{t i; J}^{\perp}  
    - E\left(x_{i} x_{i; J}^{\perp}\right) \Big|  
    > \lambda \left ( \frac{\log p_{n} }{n}  \right ) ^{1/2} \Bigg) \nonumber \\
    &\le P\Bigg(\max_{i, j \notin J, \sharp(J) \leq K_{n}-1}  
    \Big| n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp}  
    - E\left(x_{j} x_{i; J}^{\perp}\right) \Big|  
    > \lambda \left ( \frac{\log p_{n} }{n}  \right ) ^{1/2} \Bigg) = o(1).
    \label{collary1}
\end{align}


Since (\ref{assumption5_equation2}) assumes $\min_{1 \leq \sharp(J) \leq K_{n}} \lambda_{\min }(\boldsymbol{\Gamma}(J))>\delta$ for some small $\delta>0$, it follows that $x_{t1} , \dots, x_{tp_{n}}$ are linearly independent and so are $x_{1} , \dots, x_{p_{n}}$. 

Note for $i \notin J$,

\begin{equation*}
	x_{i: J}^{\perp}=x_{i}-x_{i}^{(J)}=x_{i}-\beta^{(i;J)}_{1}x_{1^{(J)}}-\beta^{(i;J)}_{2}x_{2^{(J)}}-\dots- \beta^{(i;J)}_{\sharp(J)}x_{\sharp(J)^{(J)}},
\end{equation*}

here $\{x_{k^{(J)}}\}_{k=1}^{\sharp(J)}$ are the variables with indices in $J$ (ordered increasingly), and $\beta^{(i;J)}_{k}$ are their corresponding projection coefficients.

Then

\begin{align}
    E\left ( x_{i: J}^{\perp^{2}} \right ) &= E\left (\left ( x_{i}-x_{i}^{(J)} \right )^{2} \right ) \nonumber \\
    &= E\Bigg( \Big( x_{i} - \beta^{(i;J)}_{1} x_{1^{(J)}}  
    - \beta^{(i;J)}_{2} x_{2^{(J)}} - \dots  
    - \beta^{(i;J)}_{\sharp(J)} x_{\sharp(J)^{(J)}} \Big)^{2} \Bigg).
    \label{ref8}
\end{align}


Define $(\sharp(J)+1) \times 1$ column  

\begin{equation*}
	\mathbf{\beta}^{(i;J)} = \begin{bmatrix}
1 \quad (\text{row } 1) \\
-\beta^{(i;J)}_{k} \quad (\text{row } k+1, k=1,\ldots,\sharp(J)) \\
\end{bmatrix},
\end{equation*}
then the equation (\ref{ref8}) can be represented in the quadratic form
\[
\mathbf{\beta}^{(i;J)\top} \boldsymbol{\Gamma}(J\cup\{i\}) \mathbf{\beta}^{(i;J)},
\]
where, without loss of generality, the variable ordering in the construction of $\boldsymbol{\Gamma}(J\cup\{i\})$ is consistent with that in the coefficient vector $\mathbf{\beta}^{(i;J)}$. We have
\begin{equation}
    \mathbf{\beta}^{(i;J)^{\prime }}\boldsymbol{\Gamma}(J\cup\{i\} )\mathbf{\beta}^{(i;J)} 
    \ge \frac{\mathbf{\beta}^{(i;J)^{\prime }}\boldsymbol{\Gamma}(J\cup\{i\} )\mathbf{\beta}^{(i;J)}}{\mathbf{\beta}^{(i;J)^{\prime }}\mathbf{\beta}^{(i;J)}}  
    \ge \min_{\mathbf{x}\ne \mathbf{0} } \frac{\mathbf{x^{\prime }}\boldsymbol{\Gamma}(J\cup\{i\} )\mathbf{x}}{\mathbf{x}^{\prime }\mathbf{x}} 
    =\lambda_{\min }(\boldsymbol{\Gamma}(J\cup\{i\} ) )> \delta >0,
    \label{collary2}
    \nonumber
\end{equation}
which proves $E\left ( x_{i: J}^{\perp^{2}} \right) > \delta >0$ for $i \notin J $ and $\sharp(J) \leq K_{n}-1$. Note by assumption 

\begin{equation*}
	E\left ( x_{i: J}^{\perp^{2}} \right) = E\left ( x_{i}^{2}\right) - E\left ( x_{i}^{(J)^{2}}\right)\le E\left ( x_{i}^{2}\right) = 1 ,
\end{equation*}
we summarize that for $i \notin J $

\begin{equation}
	\delta < E\left ( x_{i: J}^{\perp^{2}} \right) \le 1.
	\label{collary2}
\end{equation}

Combing (\ref{collary1}) and (\ref{collary2}) we now show that there exists a positive constant $s>0$, independent of m and n, such that

\begin{equation}
\begin{aligned}
\lim_{n \rightarrow \infty} P\left(A_{n}^{c}\left(K_{n}\right)\right) &= 0, \text{ where} \\
A_{n}(m) &= \left\{\max_{(J, i): \sharp(J) \leq m-1, i \notin J}\left|\hat{\mu}_{J, i}-\mu_{J, i}\right| \leq s\left(\frac{\log p_{n}}{n}\right)^{1/2}\right\}.
\end{aligned}
\label{ref9}
\end{equation}\\

To prove (\ref{ref9}), it suffices to show that for some $\lambda^{*}>0$,
\begin{equation}
	P\left(\max _{\sharp(J) \leq K_{n}-1, i \notin J}\left|\frac{n^{-1} \sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i; J}^{\perp}}{\left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2}+\rho_{1}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}}\right|>\lambda^{*}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}, \Omega_{n}, \Omega^{\prime}_{n}\right)=o(1),
	\label{ref10}
\end{equation}
\\
\begin{equation}
\begin{split}
    P\Bigg(&\max_{\sharp(J) \leq K_{n}-1, i,j \notin J} 
    \Bigg| \sum_{j \notin J} \beta_{j} \Bigg\{ \frac{n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp}} 
    {\left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2} + \rho_{1} \left( \frac{\log p_{n}}{n} \right)^{1/2}} \\
