\end{split}
\label{ref11}
\end{equation}

where 
\[\Omega^{\prime}_{n}=\left \{ \max_{i \notin J, \sharp(J) \leq K_{n}-1} \left| n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\perp^2} - E\left(x_{i; J}^{\perp^2}\right)\right| \le \lambda \left ( \frac{\log p_{n} }{n}  \right ) ^{1/2} \right \}.\]

We now prove

\begin{equation}
	P\left(\max _{\sharp(J) \leq K_{n}-1, i \notin J}\left|\frac{n^{-1} \sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i; J}^{\perp}}{\left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2}+\rho_{1}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}}\right|>\lambda_{1}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}, \Omega_{n},  \Omega^{\prime}_{n}\right)=o(1),
	\label{ref12}
    \nonumber
\end{equation}
where \( \delta^{\prime} = \frac{\delta}{4} \) and \( \lambda _{1} =\frac{\lambda }{{\delta^{\prime}}^{\frac{1}{2}}} \).

Since for sufficiently large n we have $ n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\perp^2} > \delta^{\prime}>0$ on $\Omega^{\prime}_{n}$, it suffices to prove

\begin{equation}
	P\left(\max _{\sharp(J) \leq K_{n}-1, i \notin J}\left|n^{-1} \sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i; J}^{\perp}\right|>\lambda_{1}{\delta^{\prime}}^{\frac{1}{2}}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}, \Omega_{n},  \Omega^{\prime}_{n}\right)=o(1).
    \nonumber
\end{equation} 

Using Lemma \ref{lemma3}, we have
\begin{align}
    &P\left(\max _{\sharp(J) \leq K_{n}-1, i \notin J}\left|n^{-1} \sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i; J}^{\perp}\right|>\lambda_{1}{\delta^{\prime}}^{\frac{1}{2}}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}, \Omega_{n},  \Omega^{\prime}_{n}\right) \nonumber \\
    &= P\left(\max _{\sharp(J) \leq K_{n}-1, i \notin J}\left|n^{-1} \sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i; J}^{\perp}\right|>\lambda\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}, \Omega_{n},  \Omega^{\prime}_{n}\right) \nonumber \\
    &\le P\left(\max _{\sharp(J) \leq K_{n}-1, i \notin J}\left|n^{-1} \sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i; J}^{\perp}\right|>\lambda\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}, \Omega_{n} \right)
