\begin{align*}
    P\Bigg(&\max _{\sharp(J) \leq K_{n}-1, i,j \notin J} 
    \Bigg|\sum_{j \notin J} \beta_{j} 
    \Bigg\{ \frac{n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp}} 
