    + \rho_{1} \left( \frac{\log p_{n} }{n} \right)^{1/2}} \\
    &\quad\quad - \frac{E\left(x_{j} x_{i; J}^{\perp}\right)} 
    {E\left(x_{i; J}^{\perp^2}\right)^{1/2}} 
    \Bigg\} \Bigg| > \lambda_{2} \left( \frac{\log p_{n} }{n} \right)^{1/2}, 
    \Omega^{\prime}_{n} \Bigg) \\
    &\leq P\Bigg(\max _{\sharp(J) \leq K_{n}-1, i,j \notin J} 
    \Bigg| \frac{n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp}} 
    {\left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2} 
    + \rho_{1} \left( \frac{\log p_{n} }{n} \right)^{1/2}} \\
    &\quad\quad - \frac{E\left(x_{j} x_{i; J}^{\perp}\right)} 
    {E\left(x_{i; J}^{\perp^2}\right)^{1/2}} 
    \Bigg| > \left( \frac{2\lambda }{\delta^{\prime^{3/2}}} 
    + \frac{\rho_{1} }{\delta^{\prime}}  \right) 
    \left( \frac{\log p_{n} }{n} \right)^{1/2}, 
    \Omega^{\prime}_{n} \Bigg) \\
    &\leq P\Bigg(\max _{\sharp(J) \leq K_{n}-1, i,j \notin J} 
    E\left(x_{i; J}^{\perp^2}\right)^{1/2} 
    \Bigg| n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp} 
    - E\left(x_{j} x_{i; J}^{\perp}\right) \Bigg| \\
    &\quad + \max _{\sharp(J) \leq K_{n}-1, i,j \notin J}  
    \Bigg| \left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2} 
    + \rho_{1} \left( \frac{\log p_{n} }{n} \right)^{1/2} 
    - E\left(x_{i; J}^{\perp^2}\right)^{1/2} \Bigg| \\
    &\quad\quad \times \Bigg| E\left(x_{j} x_{i; J}^{\perp}\right) \Bigg| 
    > \left( \frac{2\lambda }{\delta^{\prime^{1/2}}} + \rho_{1} \right) 
    \left( \frac{\log p_{n} }{n} \right)^{1/2}, \Omega^{\prime}_{n} \Bigg).
\end{align*}

Since $\left | E\left(x_{j} x_{i; J}^{\perp}\right) \right | = \left| E\left(x_{j; J}^{\perp}x_{i; J}^{\perp}\right) \right |\le 1$ and $ \max_{i \notin J, \sharp(J) \leq K_{n}-1} \left| n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\perp^2} - E\left(x_{i; J}^{\perp^2}\right)\right| \le \lambda \left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}$ on $\Omega^{\prime}_{n}$, by Lemma \ref{lemma3} we have

\begin{align}
    \text{RHS} &\le P\Bigg(\max_{\sharp(J) \leq K_{n}-1, i,j \notin J} 
    \Bigg| n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp} 
    - E\left(x_{j} x_{i; J}^{\perp}\right) \Bigg| \nonumber \\
    &\quad\quad + \frac{\lambda}{ \delta^{\prime^{1/2}}} 
    \left( \frac{\log p_{n}}{n} \right)^{1/2} 
    > \frac{2\lambda}{\delta^{\prime^{1/2}}} \left( \frac{\log p_{n}}{n} \right)^{1/2}, \Omega^{\prime}_{n} \Bigg) \nonumber \\
    &= P\left(\max _{\sharp(J) \leq K_{n}-1, i,j \notin J} \left|n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp}-E\left(x_{j} x_{i; J}^{\perp}\right) \right|
         > \frac{\lambda}{\delta^{\frac{1}{2}}}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}, \Omega^{\prime}_{n} \right)\nonumber \\
    &\le P\left(\max _{\sharp(J) \leq K_{n}-1, i,j \notin J} \left|n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp}-E\left(x_{j} x_{i; J}^{\perp}\right) \right|
         >\lambda \left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}\right)\nonumber \\
    &=o(1)\nonumber
\end{align}

Let $\lambda^{*} = \max\left \{ \lambda_{1} ,   \lambda_{2} \right \} $ , then (\ref{ref10}) and (\ref{ref11}) hold using $\lambda^{*}$. Let $s=2\lambda^{*}$,

\begin{align}
	&P\left(\max_{(J, i): \sharp(J) \leq m-1, i \notin J}\left|\hat{\mu}_{J, i}-\mu_{J, i}\right| > s\left(\frac{\log p_{n}}{n}\right)^{1/2}\right)
	\nonumber \\
	&\le P\left(\max _{\sharp(J) \leq K_{n}-1, i \notin J}\left|\frac{n^{-1} \sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i; J}^{\perp}}{\left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2}+\rho_{1}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}}\right| \right.\nonumber \\ 
	&\left. + \max _{\sharp(J) \leq K_{n}-1, i,j \notin J}\left|\sum_{j \notin J} \beta_{j} \left\{ \frac{n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp}}{\left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2}+\rho_{1}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}} - \frac{E\left(x_{j} x_{i; J}^{\perp}\right)}{E\left(x_{i; J}^{\perp^2}\right)^{1/2}} \right\}\right|> 2\lambda^{*}\left(\frac{\log p_{n}}{n}\right)^{1/2}\right) \nonumber \\
   &\le P\left(\max _{\sharp(J) \leq K_{n}-1, i \notin J}\left|\frac{n^{-1} \sum_{t=1}^{n} \varepsilon_{t} \hat{x}_{t i; J}^{\perp}}{\left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2}+\rho_{1}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}}\right|>\lambda^{*}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}\right) \nonumber \\&+
       P\left(\max _{\sharp(J) \leq K_{n}-1, i,j \notin J}\left|\sum_{j \notin J} \beta_{j} \left\{ \frac{n^{-1} \sum_{t=1}^{n} x_{t j} \hat{x}_{t i; J}^{\perp}}{\left(n^{-1} \sum_{t=1}^{n} \hat{x}_{t i; J}^{\bot^2}\right)^{1/2}+\rho_{1}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}} - \frac{E\left(x_{j} x_{i; J}^{\perp}\right)}{E\left(x_{i; J}^{\perp^2}\right)^{1/2}} \right\}\right|>\lambda^{*}\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2} \right) \ \nonumber\\
   &=o(1).\nonumber
\end{align}

For any  $0<\xi<1 $, let $\tilde{\xi}=2 /(1-\xi)$ and take 
\begin{equation}
	B_{n}(m)=\left\{\min _{0 \leq i \leq m-1} \max _{1 \leq j \leq p_{n}}\left|\mu_{\hat{J}_{i}, j}\right|>\tilde{\xi} s\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}\right\},
    \nonumber
\end{equation}
in which we set $\mu_{J, j}=0 $ if $ j \in J $ , and $\mu_{\hat{J}_{0}, j}=\mu_{\emptyset, j} $ . We now show that for all $1 \leq q \leq m$, 

\begin{equation}
	\left|\mu_{\hat{J}_{q-1}, \hat{j}_{q}}\right| \geq \xi \max _{1 \leq i \leq p_{n}}\left|\mu_{\hat{J}_{q-1}, i}\right| \text { on } A_{n}(m) \bigcap B_{n}(m),
	\label{ref13}
\end{equation}
Note that on $A_{n}(m) \bigcap B_{n}(m)$,
\begin{align}
\left|\mu_{\hat{J}_{q-1}, \hat{j}_{q}}\right| & \geq-\left|\hat{\mu}_{\hat{J}_{q-1}, \hat{j}_{q}}-\mu_{\hat{J}_{q-1}, \hat{j}_{q}}\right|+\left|\hat{\mu}_{\hat{J}_{q-1}, \hat{j}_{q}}\right| \nonumber \\
& \geq-\max _{(J, i): \sharp(J) \leq m-1, i \notin J}\left|\hat{\mu}_{J, i}-\mu_{J, i}\right|+\left|\hat{\mu}_{\hat{J}_{q-1}, \hat{j}_{q}}\right| \nonumber\\
& \geq-s\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}+\max _{1 \leq j \leq p_{n}}\left|\hat{\mu}_{\hat{J}_{q-1}, j}\right|\left(\text { since }\left|\hat{\mu}_{\hat{J}_{q-1}, \hat{j}_{q}}\right|=\max _{1 \leq j \leq p_{n}}\left|\hat{\mu}_{\hat{J}_{q-1}, j}\right|\right) \nonumber\\
& \geq-2 s\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}+\max _{1 \leq j \leq p_{n}}\left|\mu_{\hat{J}_{q-1}, j}\right| \label{ref34}\\
& \geq \xi\max_{1 \leq j \leq p_{n}}\left|\mu_{\hat{J}_{q-1}, j}\right|,\nonumber
\end{align}

since $2 s\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2}<(2 / \tilde{\xi}) \max _{1 \leq j \leq p_{n}}\left|\mu_{\hat{J}_{q-1}, j}\right|$  on  $B_{n}(m)$ and $1-\xi=2 / \tilde{\xi}$.

Consider the semi-population version of the GSFR, which uses the variable selector \(\left(\hat{j}_{1}, \hat{j}_{2}, \dots \right)\) and approximates \(y(\mathbf{x})\) by \(y_{\hat{J}_{m}}(\mathbf{x})\). Equation (\ref{ref13}) demonstrates that this semi-population version of GSFR is consistent with the PrWGA in \citet{borodinProjectionGreedyAlgorithm2021} on \(A_{n}(m) \cap B_{n}(m)\). Using Lemma \ref{lemma4}, we prove

\begin{equation}
	E_{n}\left[\left\{y(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right] \leq\left(\sum_{j=1}^{p_{n}}\left|\beta_{j}\right|\right)^{2}\left(1+m \xi^{2}\right)^{-1} \text { on } A_{n}(m) \bigcap B_{n}(m) .
	\label{ref14}
\end{equation}

For  $0 \leq i \leq m-1, E_{n}\left[\left\{y(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right] \leq E_{n}\left[\left\{y(\mathbf{x})-y_{\hat{J}_{i}}(\mathbf{x})\right\}^{2}\right]$, and therefore 

\begin{align}
E_{n}\left[\left\{y(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right] & \leq \min _{0 \leq i \leq m-1} E_{n}\left\{\left(y(\mathbf{x})-y_{\hat{J}_{i}}(\mathbf{x})\right)\left(\sum_{j=1}^{p_{n}} \beta_{j} x_{j}\right)\right\} \nonumber\\
& \leq \min _{0 \leq i \leq m-1}  \max _{1 \leq j \leq p_{n}}\left |  \frac{E_{n}\left\{\left(y(\mathbf{x})-y_{\hat{J}_{i}}(\mathbf{x})\right)\left(x_{j}-x^{(\hat{J}_{i})}_{j} \right)\right\}}{{E_{n}\left(x_{j; \hat{J}_{i}}^{\perp^2}\right)}^{\frac{1}{2} } } \right | \sum_{j=1}^{p_{n}} \left |\beta_{j}  \right |     \nonumber\\
& = \min _{0 \leq i \leq m-1} \max _{1 \leq j \leq p_{n}}\left|\mu_{\hat{J}_{i}, j}\right| \sum_{j=1}^{p_{n}}\left|\beta_{j}\right| \nonumber\\
& \leq \tilde{\xi} s\left ( \frac{\log p_{n} }{n}  \right ) ^{1/2} \sum_{j=1}^{p_{n}}\left|\beta_{j}\right| \text { on } B_{n}^{c}(m) .\nonumber
\end{align}

Combining this with (\ref{assumption4}) and (\ref{ref14}), and the assumption that $m \leq K_{n}=O((n/\log p_{n})^{1 / 2})$ yields

\begin{equation}
	E_{n}\left[\left\{y(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right] I_{A_{n}(m)} \leq C^{*} m^{-1} 
	\label{ref16}
\end{equation}
for some $C^{*}>0$. In addition, since (\ref{ref9}) and (\ref{ref14}) $\forall \varepsilon >0$, $\exists M_{1} > C^{*}$, such that

\begin{equation*}
	 P\left (\max _{1 \leq m \leq K_{n}} m E_{n}\left[\left\{y(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right]\ge  M_{1}\right ) \le 1-P\left (A_{n}\left(K_{n}\right)  \right ) ,
\end{equation*}
and since $\lim_{n \to \infty} P\left (A_{n}\left(K_{n}\right)  \right )=1$ , $\exists N_{\varepsilon }$ , s.t. $1-P\left (A_{n}\left(K_{n}\right)  \right )<\varepsilon$ for $n>N_{\varepsilon }$. Take $M_{2\varepsilon}$ such that for $1\le n \le N_{\varepsilon }$
\begin{equation*}
	P\left (\max _{1 \leq m \leq K_{n}} m E_{n}\left[\left\{y(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right]\ge  M_{2\varepsilon}\right ) \le \varepsilon ,
\end{equation*}
taking $M_{3\varepsilon}=\max\left \{ M_{1\varepsilon}, M_{2\varepsilon} \right \}$ we have $\forall n >0$

\begin{equation*}
	P\left (\max _{1 \leq m \leq K_{n}} m E_{n}\left[\left\{y(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right]\ge  M_{3\varepsilon}\right ) \le \varepsilon,
\end{equation*}
following this we conclude that
\begin{equation}
	\max _{1 \leq m \leq K_{n}} m E_{n}\left[\left\{y(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right]=O_{p}(1).
	\label{result1}
\end{equation}

Let $\mathbf{q}(J)=E\left(y \mathbf{x}_{J}\right)$  and  $\mathbf{Q}(J)=n^{-1} \sum_{t=1}^{n}\left(y_{t}-\mathbf{x}_{t}^{\prime}(J) \boldsymbol{\Gamma}^{-1}(J)\right. \mathbf{q}(J)) \mathbf{x}_{t}(J)$.

Note 
\begin{align}
	\hat{y}_{m}(x)-y_{\hat{J}_{m}}(x)&=\mathbf{x}^{\prime}\left ( \hat{J}_{m} \right ) \left[\hat{\boldsymbol{\Gamma}}^{-1}\left(\hat{J}_{m}\right) \frac{\sum_{t=1}^{n}  \mathbf{x}_{t}\left(\hat{J}_{m}\right) y_{t}}{n}-\boldsymbol{\Gamma}^{-1}\left(\hat{J}_{m}\right) \boldsymbol{q}\left(\hat{J}_{m}\right)\right]
	   \nonumber \\
	&=\mathbf{x}^{\prime}\left ( \hat{J}_{m} \right )\hat{\boldsymbol{\Gamma}}^{-1}\left(\hat{J}_{m}\right) \left[\frac{\sum_{t=1}^{n}  \mathbf{x}_{t}\left(\hat{J}_{m}\right) y_{t}}{n}-\hat{\boldsymbol{\Gamma}}\left(\hat{J}_{m}\right)\boldsymbol{\Gamma}^{-1}\left(\hat{J}_{m}\right) \boldsymbol{q}\left(\hat{J}_{m}\right)\right]
	\nonumber \\
	&=\mathbf{x}^{\prime}\left ( \hat{J}_{m} \right )\hat{\boldsymbol{\Gamma}}^{-1}\left(\hat{J}_{m}\right) \frac{1}{n} \sum_{t=1}^{n} \left (  y_{t}- \mathbf{x}^{\prime}_{t}\left(\hat{J}_{m}\right)\boldsymbol{\Gamma}^{-1}\left(\hat{J}_{m}\right) \boldsymbol{q}\left(\hat{J}_{m}\right)\right )\mathbf{x}_{t}\left(\hat{J}_{m}\right) \nonumber \\
	&=\mathbf{x}^{\prime}\left ( \hat{J}_{m} \right )\hat{\boldsymbol{\Gamma}}^{-1}\left(\hat{J}_{m}\right)\mathbf{Q}(\hat{J}_{m}), \nonumber 
\end{align}
using this we show
\begin{align}
	E_{n}&\left(\hat{y}_{m}(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right)^{2}
	\nonumber
	\\&=\mathbf{Q}^{\top}\left(\hat{J}_{m}\right) \hat{\boldsymbol{\Gamma}}^{-1}\left(\hat{J}_{m}\right) \boldsymbol{\Gamma}\left(\hat{J}_{m}\right) \hat{\boldsymbol{\Gamma}}^{-1}\left(\hat{J}_{m}\right) \mathbf{Q}\left(\hat{J}_{m}\right) \nonumber \\
	&\leq\left\|\mathbf{Q}\left(\hat{J}_{m}\right)\right\|^{2}\left\|\hat{\boldsymbol{\Gamma}}^{-1}\left(\hat{J}_{m}\right)\right\|^{2}\left\|\hat{\boldsymbol{\Gamma}}\left(\hat{J}_{m}\right)-\boldsymbol{\Gamma}\left(\hat{J}_{m}\right)\right\|+\left\|\mathbf{Q}\left(\hat{J}_{m}\right)\right\|^{2}\left\|\hat{\boldsymbol{\Gamma}}^{-1}\left(\hat{J}_{m}\right)\right\| ,\nonumber
\end{align}
where for $\mathbf{A} \in \mathbf{R}  ^{m\times n}$, $\left \|  \mathbf{A}  \right \|=\max_{\left \|  x  \right \|_{2}=1}{\left \|  \mathbf{A}x  \right \|}_{2} $.


To estimate $\left\|\mathbf{Q}\left(\hat{J}_{m}\right)\right\|^2$, we have
\begin{align}
\mathbf{Q}(\hat{J}_{m})
        &=\frac{1}{n} \sum_{t=1}^{n} y_{t}\mathbf{x}_{t}\left(\hat{J}_{m}\right)- \mathbf{x}^{\prime}_{t}\left(\hat{J}_{m}\right)\boldsymbol{\Gamma}^{-1}\left(\hat{J}_{m}\right) \boldsymbol{q}\left(\hat{J}_{m}\right)\mathbf{x}_{t}\left(\hat{J}_{m}\right)
           \nonumber \\
        &=\frac{1}{n} \sum_{t=1}^{n} \left ( \mathbf{x}_{t}^{\prime}\mathbf{\beta}+\varepsilon_{t} \right ) \mathbf{x}_{t}\left(\hat{J}_{m}\right)- \mathbf{x}^{\prime}_{t}\left(\hat{J}_{m}\right)\boldsymbol{\Gamma}^{-1}\left(\hat{J}_{m}\right) E\left ( \sum_{i=1}^{p_{n} }\left ( x_{i} \beta_{i}  \right )\mathbf{x}\left(\hat{J}_{m}\right)  \right ) \mathbf{x}_{t}\left(\hat{J}_{m}\right)
        \nonumber \\
        &=\frac{1}{n} \sum_{t=1}^{n}\varepsilon_{t} \mathbf{x}_{t}\left(\hat{J}_{m}\right)- \sum_{i=1}^{p_{n} }\beta_{i} \sum_{t=1}^{n}\left ( x_{ti}- \mathbf{x}^{\prime}_{t}\left(\hat{J}_{m}\right)\boldsymbol{\Gamma}^{-1}\left(\hat{J}_{m}\right)\mathbf{g}_{i} \left ( \hat{J}_{m} \right )  \right ) \mathbf{x}_{t}\left(\hat{J}_{m}\right)
        \label{ref15}.
\end{align}

Since $\forall j^{*} \in \hat{J}_{m}$
\begin{align}
	&\left | \frac{1}{n} \sum_{t=1}^{n} x_{ti}x_{tj^{*}}-\sigma _{ij^{*}}+\sigma _{ij^{*}} - \mathbf{g}^{\prime}_{i} \left ( \hat{J}_{m} \right )\boldsymbol{\Gamma}^{-1}\left(\hat{J}_{m}\right)\frac{1}{n} \sum_{t=1}^{n}\mathbf{x}_{t}\left(\hat{J}_{m}\right)x_{tj^{*}} \right | 
	\nonumber \\
	&=\left | \frac{1}{n} \sum_{t=1}^{n} x_{ti}x_{tj^{*}}-\sigma _{ij^{*}}+\mathbf{g}^{\prime}_{i} \left ( \hat{J}_{m} \right )\boldsymbol{\Gamma}^{-1}\left(\hat{J}_{m}\right)\mathbf{g}_{j^{*}} \left ( \hat{J}_{m} \right ) - \mathbf{g}^{\prime}_{i} \left ( \hat{J}_{m} \right )\boldsymbol{\Gamma}^{-1}\left(\hat{J}_{m}\right)\frac{1}{n} \sum_{t=1}^{n}\mathbf{x}_{t}\left(\hat{J}_{m}\right)x_{tj^{*}} \right |
	\nonumber \\
	&\le \max _{1\leq i, j \leq p_{n}}\left |n^{-1} \sum_{t=1}^{n} x_{t i} x_{t j}-\sigma_{i j} \right | \left ( 1+\max _{1 \leq \sharp(J) \leq K_{n}, 1 \leq l \leq p_{n}}\left\|\boldsymbol{\Gamma}^{-1}(J) \mathbf{g}_{l}(J)\right\|_{1} \right ) 
	\nonumber
\end{align}
combining (\ref{ref15}) we have
\begin{equation}
	\begin{aligned}
\left\|\mathbf{Q}\left(\hat{J}_{m}\right)\right\|^{2} \leq & 2 m \max _{1 \leq i \leq p_{n}}\left(n^{-1} \sum_{t=1}^{n} \varepsilon_{t} x_{t i}\right)^{2}+2 m \max _{1 \leq i, j \leq p_{n}}\left(n^{-1} \sum_{t=1}^{n} x_{t i} x_{t j}-\sigma_{i j}\right)^{2} \\
& \times\left(\sum_{j=1}^{p_{n}}\left|\beta_{j}\right|\right)^{2}\left(1+\max _{1 \leq \sharp(J) \leq K_{n}, 1 \leq l \leq p_{n}}\left\|\boldsymbol{\Gamma}^{-1}(J) \mathbf{g}_{l}(J)\right\|_{1}\right)^{2} .
\end{aligned}
\nonumber
\end{equation}

Combine this with (\ref{assumption5_equation2}), (\ref{assumption4}), Lemma \ref{lemma1} and Lemma \ref{lemma2}, we now prove
\begin{equation}
	\max _{1 \leq m \leq K_{n}}\left\{\frac{n\left\|\mathbf{Q}\left(\hat{J}_{m}\right)\right\|^{2}}{m \log p_{n}}\right\}=O_{p}(1).
	\label{result2}
\end{equation}

For every \(\varepsilon > 0\), take $M^{\prime}=\max\left \{ \frac{8M^{\prime}_{1}}{C}, \frac{8M^{\prime}_{1}}{\eta}  \right \} $, where  
\[
M^{\prime}_{1}=\left(\sum_{j=1}^{p_{n}}\left|\beta_{j}\right|\right)^{2}\left(1+\max _{1 \leq \sharp(J) \leq K_{n}, 1 \leq l \leq p_{n}}\left\|\boldsymbol{\Gamma}^{-1}(J) \mathbf{g}_{l}(J)\right\|_{1}\right)^{2},
\]
then \(\exists N^{\prime}_{1}, \forall n> N^{\prime}_{1},\) 

\begin{align*}
    P\Bigg( &\max_{1 \leq m \leq K_{n}} \left\{ \frac{n \left\| \mathbf{Q}\left(\hat{J}_{m}\right) \right\|^{2}}{m \log p_{n}} \right\} > M^{\prime} \Bigg) \\
    &\le P\Bigg( \max_{1 \leq m \leq K_{n}} \left\{ \frac{n \left\| \mathbf{Q}\left(\hat{J}_{m}\right) \right\|^{2}}{m \log p_{n}} \right\} > M^{\prime}, \Omega_{n} \Bigg) + \frac{\varepsilon}{2},
\end{align*}

\begin{align*}
    P\Bigg( &\max_{1 \leq m \leq K_{n}} \left\{ \frac{n \left\| \mathbf{Q}\left(\hat{J}_{m}\right) \right\|^{2}}{m \log p_{n}} \right\} > M^{\prime}, \Omega_{n} \Bigg) \\
    &\le P\left( \max_{1 \leq i \leq p_{n}} \left( \frac{\sum_{t=1}^{n} \varepsilon_{t} x_{t i}}{n} \right)^2 > \frac{M^{\prime}}{4} \frac{\log p_{n}}{n}, \Omega_{n} \right) \\
    &\quad + P\left( M^{\prime}_{1} \max_{1 \leq i,j \leq p_{n}} \left( \frac{\sum_{t=1}^{n} x_{t i} x_{t j}}{n} - \sigma_{i j} \right)^2 > \frac{M^{\prime}}{4} \frac{\log p_{n}}{n} \right).
\end{align*}



By Lemma \ref{lemma1}, $\exists N^{\prime}_{2} >0, \forall n>N^{\prime}_{2}$ such that

\begin{align*}
	P\Bigg(M^{\prime}_{1}&\max _{1 \leq i, j \leq p_{n}}\left(\frac{\sum_{t=1}^{n}x_{ti}x_{tj} }{n} -\sigma_{i j}\right)^2>\frac{M^{\prime}}{4}  \frac{\log{p_{n}}}{n}\ \Bigg) \\
        & \le p^2_{n} \max _{1 \leq i, j \leq p_{n}}P\left(\left | \frac{\sum_{t=1}^{n}x_{ti}x_{tj} }{n} -\sigma_{i j}\right |>(\frac{M^{\prime}}{4M^{\prime}_{1}}  \frac{\log{p_{n}}}{n})^{\frac{1}{2}} \right) \nonumber \\
	&\le \exp \left ( \left ( 2 -\frac{CM^{\prime}}{4M^{\prime}_{1}} \right )  \log{p_{n} }\right  )		\nonumber \\
	&< \frac{\varepsilon}{4}.
        \nonumber
\end{align*}

Similarly, by Lemma \ref{lemma2} we have $\exists N^{\prime}_{3} >0, \forall n>N^{\prime}_{3}$
\begin{equation*}
	P\left(\max _{1 \leq i \leq p_{n}} \left(\frac{ \sum_{t=1}^{n} \varepsilon_{t} x_{t i}}{n}\right)^2 > \frac{M^{\prime}}{4}  \frac{\log{p_{n}}}{n} , \Omega_{n}\right) \le p_{n}\exp \left ( -\eta\frac{M^{\prime}}{4M^{\prime}_{1}}  \log{p_{n}}\right ) < \frac{\varepsilon}{4}.
\end{equation*}

Take $N^{\prime}=\max\left \{N^{\prime}_{1} , N^{\prime}_{2},  N^{\prime}_{3} \right \} $, then $\forall n>N^{\prime}$ 

\begin{equation*}
	P\left (\max _{1 \leq m \leq K_{n}}\left\{\frac{n\left\|\mathbf{Q}\left(\hat{J}_{m}\right)\right\|^{2}}{m \log p_{n}}\right\}>M^{\prime}  \right )< \varepsilon.
\end{equation*}

Take $M^{\prime}_{2\varepsilon }$ such that $\forall n \le N^{\prime}$
\begin{equation*}
	P\left (\max _{1 \leq m \leq K_{n}}\left\{\frac{n\left\|\mathbf{Q}\left(\hat{J}_{m}\right)\right\|^{2}}{m \log p_{n}}\right\}>M^{\prime}_{2\varepsilon }  \right )< \varepsilon,
\end{equation*}
and take $M^{*}_{\varepsilon }=\max\left \{M^{\prime}_{\varepsilon },   M^{\prime}_{2\varepsilon }\right \} $, then $\forall n>0$

\begin{equation*}
	P\left (\max _{1 \leq m \leq K_{n}}\left\{\frac{n\left\|\mathbf{Q}\left(\hat{J}_{m}\right)\right\|^{2}}{m \log p_{n}}\right\}>M^{*}_{\varepsilon }  \right )< \varepsilon,
\end{equation*}
result (\ref{result2}) follows immediately.
\\
Moreover, by Lemma \ref{lemma1} and take $M^{\prime}_{3}>(\frac{2}{c})^{\frac{1}{2}}+\frac{1}{\delta}$,  
$\forall \varepsilon, \exists N^{\prime}_{4\varepsilon} >0, \forall n>N^{\prime}_{4\varepsilon}$ 
\begin{align*}
P\Bigg(&\max _{1 \leqslant m \leqslant k_{n}}\left\|\hat{\mathbf{\Gamma} }^{-1}\left(\hat{J}_{m}\right)\right\|>M^{\prime}_{3} \Bigg)  \\
&\leqslant P\left(\max _{1 \leqslant m \leqslant k_{n}}\left\|\hat{\mathbf{\Gamma}}^{-1}\left(\hat{J}_{m}\right)-\mathbf{\Gamma}^{-1}\left(\hat{J}_{m}\right)\right\|+\max _{1 \leqslant m \leqslant k_{n} }\left\|\mathbf{\Gamma}^{-1}\left(\hat{J}_{m}\right)\right\|>M^{\prime}_{3 }\right) \nonumber \\
&\leqslant P\left(\max _{1 \leqslant \sharp(J) \leqslant k_{n}}\left\|\hat{\mathbf{\Gamma}}^{-1}(J)-\mathbf{\Gamma}^{-1}(J)\right\|+\max _{1 \leqslant \sharp(J) \leqslant k_{n}}\left\|\Gamma^{-1}(J)\right\|>M^{\prime}_{3 }\right) \nonumber\\
&\leqslant P\left(\max _{1 \leqslant \sharp(J) \leqslant k_{n}}\left\|\hat{\mathbf{\Gamma}}^{-1}(J)-\mathbf{\Gamma}^{-1}(J)\right\|>M^{\prime}_{3}-\frac{1}{\delta}\right),\nonumber\\
&\le \nonumber \varepsilon.
\end{align*}

Take $M^{\prime}_{4\varepsilon }$ such that $\forall n \le N^{\prime}_{4\varepsilon}$
\begin{equation*}
	P\left(\max _{1 \leqslant m \leqslant k_{n}}\left\|\hat{\mathbf{\Gamma} }^{-1}\left(\hat{J}_{m}\right)\right\|>M^{\prime}_{4\varepsilon } \right)\le \nonumber \varepsilon,
\end{equation*}
we similarly conclude that 
\begin{equation}
	\max _{1 \leq m \leq K_{n}}\left\|\hat{\boldsymbol{\Gamma}}^{-1}\left(\hat{J}_{m}\right)\right\|=O_{p}(1), \max _{1 \leq m \leq K_{n}}\left\|\hat{\boldsymbol{\Gamma}}\left(\hat{J}_{m}\right)-\boldsymbol{\Gamma}\left(\hat{J}_{m}\right)\right\|=O_{p}(1),
	\nonumber
\end{equation}
and
\begin{equation}
	\max _{1 \leq m \leq K_{n}} \frac{n E_{n}\left[\left\{\hat{y}_{m}(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right]}{m \log p_{n}}=O_{p}(1)
	\label{result3}.
\end{equation}

By combining the expressions
\[
E_{n}\left[\left\{y(\mathbf{x})-\hat{y}_{m}(\mathbf{x})\right\}^{2}\right] = E_{n}\left[\left\{y(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right] + E_{n}\left[\left\{\hat{y}_{m}(\mathbf{x})-y_{\hat{J}_{m}}(\mathbf{x})\right\}^{2}\right],
\]
and incorporating the results from (\ref{result1}) and (\ref{result3}), we conclude that:


\begin{equation}
	\\max _{1 \leq m \leq K_{n}}\left(\frac{E\left[\left\{y(\mathbf{x})-\hat{y}_{m}(\mathbf{x})\right\}^{2} \mid y_{1}, \mathbf{x}_{1}, \ldots, y_{n}, \mathbf{x}_{n}\right]}{m^{-1}+n^{-1} m \log p_{n}}\right)=O_{p}(1).
    \nonumber
\end{equation}

\end{proof}



\subsection*{Proof of Theorem \ref{theorem2}}
\begin{proof}
The structure of this proof parallels that of \citet{ingStepwiseRegressionMethod2011}, with appropriate adjustments for GSFR. Let \(a > 0\) and define \(A_n(m)\) by (\ref{ref9}), where \(m = \lfloor a n^{\gamma} \rfloor = o(K_n)\). By (\ref{ref9}) and (\ref{ref16}), we have
\[
\lim_{n \to \infty} P(A_n^c(m)) \leq \lim_{n \to \infty} P(A_n^c(K_n)) = 0,
\]
and
\[
E_n\{[y(\mathbf{x}) - y_{\hat{J}_m}(\mathbf{x})]^2 \} I_{A_n(m)} \leq C^* m^{-1}.
\]

From this, it follows that
\begin{equation}
	\lim_{n \to \infty} P(F_n) = 0, \quad \text{where } F_n = \left\{ E_n[y(\mathbf{x}) - y_{\hat{J}_m}(\mathbf{x})]^2 > C^* m^{-1} \right\}.
	\label{ref20}
\end{equation}


For \(J \subseteq \{1, \dots, p_n\}\) and \(j \in J\), let \(\hat{\beta}_j(J)\) denote the coefficient of \(x_j\) in the best linear predictor \(\sum_{i \in J} \hat{\beta}_i(J)x_i\) of \(y\) that minimizes \(E[y - \sum_{i \in J} \lambda_i x_i]^2\). Define \(\hat{\beta}_j(J) = 0\) if \(j \notin J\). Note that
\begin{equation}
	E_n[y(\mathbf{x}) - y_{\hat{J}_m}(\mathbf{x})]^2 = E_n\left\{\sum_{j \in \hat{J}_m \cup N_n} (\beta_j - \hat{\beta}_j(\hat{J}_m)) x_j \right\}^2.
	\label{ref17}
\end{equation}

From (\ref{assumption4}) and (\ref{assumption6_equation2}), it follows that
\[
\sharp(N_n) = O(n^{\gamma/2}),
\]
yielding \(\sharp(\hat{J}_m \cup N_n) = o(K_n)\). It then follows from (\ref{ref17}) that for all large \(n\),
\begin{equation}
	E_n\{[y(\mathbf{x}) - y_{\hat{J}_m}(\mathbf{x})]^2\} \geq \left(\min_{j \in N_n} \beta_j^2\right) \min_{1 \leq \sharp(J) \leq K_n} \lambda_{\min}(\Gamma(J)),
	\label{ref18}
\end{equation}

on \(\{N_n \cap \hat{J}_m^c \neq \emptyset\}\).

Combining this result with (\ref{ref18}), (\ref{assumption6_equation2}), and (\ref{assumption5_equation1}), we obtain
\begin{equation}
	E_n\{[y(\mathbf{x}) - y_{\hat{J}_m}(\mathbf{x})]^2\} \geq b n^{-\gamma},
	\label{ref19}
    \nonumber
\end{equation}
for some \(b > 0\) and all large \(n\). By choosing \(a\) in \(m = \lfloor a n^\gamma \rfloor\) large enough, we have \(b n^{-\gamma} > C^* m^{-1}\), implying that \(\{N_n \cap \hat{J}_m^c \neq \emptyset\} \subseteq F_n\), where \(F_n\) is defined above. Hence, by (\ref{ref20}),
\[
\lim_{n \to \infty} P(N_n \subseteq \hat{J}_m) = 1.
\]

Therefore, the GSFR algorithm path, which terminates after \( m = \lfloor a n^\gamma \rfloor \) iterations, includes all relevant regressors with probability approaching 1. This result also holds for the GSFR path terminating after \( K_n \) iterations, provided that \( K_n / m \to \infty \).
\end{proof}






\subsection*{Proof of Theorem \ref{theorem3}}
\begin{proof}

First, from \eqref{ref9} and Theorem \ref{theorem2}, we know the probability of the event \( A_{n}\left(K_{n}\right) \) and \( A^{\prime}_{n}\left(K_{n}\right) \) satisfies
\begin{align*}
    \lim_{n \to \infty} P\left(A_{n}\left(K_{n}\right)\right) = 1, \\
     \lim_{n \to \infty} P\left(A^{\prime}_{n}\left(K_{n}\right)\right) = 1,
    \nonumber
\end{align*}
where
\begin{align*}
    &A_{n}(m) = \left\{\max_{(J, i): \sharp(J) \leq m-1, i \notin J} \left|\hat{\mu}_{J, i} - \mu_{J, i}\right| \leq s\left(\frac{\log p_{n}}{n}\right)^{1/2}\right\},\\
    &A^{\prime}_{n}(m) = \left\{\tilde{k}_n<K_{n}\right\}.
    \nonumber
\end{align*}

By definition,  on the event \(  A_{n}\left(K_{n}\right)\cap  A^{\prime}_{n}\left(K_{n}\right) \), we have
\begin{equation}
    0 < \hat{\triangle}_{\hat{J}_{\hat{k}_n}} \le \hat{\triangle}_{\hat{J}_{\tilde{k}_n}}.
    \label{ref25}
\end{equation}

 Using \eqref{ref25}, we have
\begin{equation}
    \hat{\triangle}_{\hat{J}_{\hat{k}_n}} = \frac{\left| \hat{\mu}_{\hat{J}_{\hat{k}_n}, \hat{j}_{\hat{k}_n+1}} \right| + \rho_2 \frac{1}{n^{1.5\gamma + \varepsilon_0 }}}{\left| \hat{\mu}_{\hat{J}_{{\hat{k}_n}-1}, \hat{j}_{{\hat{k}_n}}} \right| + \rho_2 \frac{1}{n^{1.5\gamma + \varepsilon_0 }}} 
    \le \hat{\triangle}_{\hat{J}_{\tilde{k}_n}} = \frac{\left| \hat{\mu}_{\hat{J}_{{\tilde{k}_n}}, \hat{j}_{{\tilde{k}_n}+1}} \right| + \rho_2 \frac{1}{n^{1.5\gamma + \varepsilon_0 }}}{\left| \hat{\mu}_{\hat{J}_{{\tilde{k}_n}-1}, \hat{j}_{{\tilde{k}_n}}} \right| + \rho_2 \frac{1}{n^{1.5\gamma + \varepsilon_0}}}.
    \label{ref26}
    \nonumber
\end{equation}

From \eqref{ref9}, we obtain
\begin{equation}
    \frac{\left| \mu_{\hat{J}_{\hat{k}_n}, \hat{j}_{\hat{k}_n+1}} \right| + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - s \left( \frac{\log p_n}{n} \right)^{1/2}}{\left| \mu_{\hat{J}_{{\hat{k}_n}-1}, \hat{j}_{{\hat{k}_n}}} \right| + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}} 
    \le \frac{\left| \mu_{\hat{J}_{{\tilde{k}_n}}, \hat{j}_{{\tilde{k}_n}+1}} \right| + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}}{\left| \mu_{\hat{J}_{{\tilde{k}_n}-1}, \hat{j}_{{\tilde{k}_n}}} \right| + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - s \left( \frac{\log p_n}{n} \right)^{1/2}}.
    \label{ref27}
\end{equation}

It is easy to see the following relationship: for \( m \ge \tilde{k}_n \), we have \( \left| \mu_{\hat{J}_{m}, \hat{j}_{m+1}} \right| = 0 \). Thus, on the event \( \{\hat{k}_n > \tilde{k}_n\} \cap A_{n}\left(K_{n}\right)\cap  A^{\prime}_{n}\left(K_{n}\right) \), it follows that 
\(\left| \mu_{\hat{J}_{\hat{k}_n-1}, \hat{j}_{\hat{k}_n}} \right| = 0\), \(\left| \mu_{\hat{J}_{\hat{k}_n}, \hat{j}_{\hat{k}_n+1}} \right| = 0\) and \(\left| \mu_{\hat{J}_{\tilde{k}_n}, \hat{j}_{\tilde{k}_n+1}} \right| = 0\). 

Consequently, we obtain the bounds
\begin{equation}
    \frac{\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - s \left( \frac{\log p_n}{n} \right)^{1/2}}{\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0}} + s \left( \frac{\log p_n}{n} \right)^{1/2}} \leq \hat{\triangle}_{\hat{J}_{\hat{k}_n}} 
    \leq \frac{\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}}{\left| \mu_{\hat{J}_{\tilde{k}_n-1}, \hat{j}_{\tilde{k}_n}} \right| + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - s \left( \frac{\log p_n}{n} \right)^{1/2}}.
    \label{ref28}
\end{equation}

Now, because \(N_{n} \cap \hat{J}_{\tilde{k}_n-1}^{c} \neq \emptyset\). From \eqref{ref18}, we have
\begin{equation}
    E_n\left\{\left[y(\mathbf{x}) - y_{\hat{J}_{\tilde{k}_n-1}}(\mathbf{x})\right]^2\right\} 
    \geq \left(\min_{j \in N_n} \beta_j^2\right) \min_{1 \leq \sharp(J) \leq K_n} \lambda_{\min}(\Gamma(J)) \geq b n^{-\gamma},
    \label{ref29}
\end{equation}
for some \(b > 0\). 

Since \(\left| \mu_{\hat{J}_{\tilde{k}_n-1}, \hat{j}_{\tilde{k}_n}} \right| = \sqrt{\sigma_{\hat{J}_{\tilde{k}_n-1}}^2 - \sigma_{\hat{J}_{\tilde{k}_n}}^2}\), and \(\sigma_{\hat{J}_{\tilde{k}_n}}^2 = 0\) (as all relevant variables are already selected), \eqref{ref29} implies
\begin{equation}
    \left| \mu_{\hat{J}_{\tilde{k}_n-1}, \hat{j}_{\tilde{k}_n}} \right| = E_n\left\{\left[y(\mathbf{x}) - y_{\hat{J}_{\tilde{k}_n-1}}(\mathbf{x})\right]^2\right\}^{1/2} 
    \geq \sqrt{b} n^{-\frac{1}{2}\gamma}.
    \label{ref30}
\end{equation}

Combining \eqref{ref28} and \eqref{ref30}, we have
\begin{equation}
        \frac{\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0}} - s \left( \frac{\log p_n}{n} \right)^{1/2}}{\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}} \leq \hat{\triangle}_{\hat{J}_{\hat{k}_n}} 
    \leq \frac{\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}}{\left ( \rho_2 + \sqrt{b} \right ) \frac{1}{n^{1.5\gamma + \varepsilon_0 }} - s \left( \frac{\log p_n}{n} \right)^{1/2}}.
    \label{ref31}
    \nonumber
\end{equation}

Since \(K_n / n^{1.5\gamma + \varepsilon_0} \to \infty\), for sufficiently large \(n\), the following inequalities hold:
\[
1 - \varepsilon_1 \leq  \frac{\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0}} - s \left( \frac{\log p_n}{n} \right)^{1/2}}{\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}} ,
\]
and
\[
\frac{\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}}{\left ( \rho_2 + \sqrt{b} \right ) \frac{1}{n^{1.5\gamma + \varepsilon_0 }} - s \left( \frac{\log p_n}{n} \right)^{1/2}}
\leq \frac{\rho_2}{\rho_2 + \sqrt{b}} + \varepsilon_1,
\]
where \(0 < \varepsilon_1 < \frac{\sqrt{b}}{2(\rho_2 + \sqrt{b})}\).



Thus, on \(\{\hat{k}_n > \tilde{k}_n\} \cap A_{n}\left(K_{n}\right)\) with sufficiently large n, we have
\begin{equation}
   1 - \varepsilon_1
     \leq \hat{\triangle}_{\hat{J}_{\hat{k}_n}} 
     \leq \frac{\rho_2}{\rho_2 + \sqrt{b}} + \varepsilon_1,
    \label{ref31}
    \nonumber
\end{equation}
which leads to a contradiction. Therefore,
\begin{align}
    &\lim_{n \to \infty} P(\hat{k}_n > \tilde{k}_n,A_{n}\left(K_{n}\right)\cap A^{\prime}_{n}\left(K_{n}\right) ) = 0, \nonumber \\
     & \lim_{n \to \infty} P(\hat{k}_n > \tilde{k}_n) = 0.
    \label{ref32}
\end{align}


On the event \(\{\hat{k}_n < \tilde{k}_n\} \cap A_{n}\left(K_{n}\right)\cap A^{\prime}_{n}\left(K_{n}\right)\), using \eqref{assumption4}, we have 
\begin{equation}
    0 \leq \left| \mu_{\hat{J}_{\hat{k}_n-1}, \hat{j}_{\hat{k}_n}} \right| \leq E\left[y\left(\mathbf{x}\right)^2\right]^{1/2} \leq M,
    \nonumber
\end{equation}
for some \(M > 0\).

Combining this with \eqref{ref27}, we obtain
\begin{equation}
    \frac{\left| \mu_{\hat{J}_{\hat{k}_n}, \hat{j}_{\hat{k}_n+1}} \right| + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - s \left( \frac{\log p_n}{n} \right)^{1/2}}{M + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}} 
    \leq \frac{\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}}{\left| \mu_{\hat{J}_{{\tilde{k}_n}-1}, \hat{j}_{{\tilde{k}_n}}} \right| + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - s \left( \frac{\log p_n}{n} \right)^{1/2}}.
    \label{ref33}
\end{equation}

From \eqref{ref34}, we note that
\begin{equation}
    -2 s\left( \frac{\log p_{n} }{n} \right)^{1/2} + \max _{1 \leq j \leq p_{n}} \left|\mu_{\hat{J}_{\hat{k}_n}, j}\right| 
    \leq \left| \mu_{\hat{J}_{\hat{k}_n}, \hat{j}_{\hat{k}_n+1}} \right|.
    \label{ref35}
\end{equation}

Moreover,  we have
\begin{align}
    E_{n}\left[\left\{y(\mathbf{x}) - y_{\hat{J}_{\hat{k}_n}}(\mathbf{x})\right\}^{2}\right] 
    &= E_{n}\left\{\left(y(\mathbf{x}) - y_{\hat{J}_{\hat{k}_n}}(\mathbf{x})\right) \left(\sum_{j = 1}^{p_{n}} \beta_{j} x_{j}\right)\right\} \nonumber \\
    &\leq \max _{1 \leq j \leq p_{n}} \left|\mu_{\hat{J}_{\hat{k}_n}, j}\right| \sum_{j = 1}^{p_{n}} \left|\beta_{j}\right| \nonumber \\
    &\leq M \max _{1 \leq j \leq p_{n}} \left|\mu_{\hat{J}_{\hat{k}_n}, j}\right|.
    \label{ref36}
\end{align}

Using \eqref{ref35} and \eqref{ref36}, we obtain
\begin{equation}
    \frac{E_{n}\left[\left\{y(\mathbf{x}) - y_{\hat{J}_{\hat{k}_n}}(\mathbf{x})\right\}^{2}\right]}{M} 
    \leq 2 s\left( \frac{\log p_{n} }{n} \right)^{1/2} + \left| \mu_{\hat{J}_{\hat{k}_n}, \hat{j}_{\hat{k}_n+1}} \right|.
    \label{ref37}
\end{equation}

Combining \eqref{ref33}, \eqref{ref37}, and \eqref{ref18}, and noting that \(K_n / n^{1.5\gamma + \varepsilon_0} \to \infty\), for sufficiently large n we deduce
\begin{align}
    \left| \mu_{\hat{J}_{{\tilde{k}_n}-1}, \hat{j}_{{\tilde{k}_n}}} \right| &+ \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - s \left( \frac{\log p_n}{n} \right)^{1/2}\\
    &\leq \frac{\left[M + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}\right] [\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}]}{\left| \mu_{\hat{J}_{{\hat{k}_n}}, \hat{j}_{{\hat{k}_n}+1}} \right| + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - s \left( \frac{\log p_n}{n} \right)^{1/2}} \nonumber \\
    &= \frac{\left[M + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}\right] [\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}]}{\left| \mu_{\hat{J}_{{\hat{k}_n}}, \hat{j}_{{\hat{k}_n}+1}} \right| + 2s \left( \frac{\log p_n}{n} \right)^{1/2} + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - 3s \left( \frac{\log p_n}{n} \right)^{1/2}} \nonumber \\
    &\leq \frac{\left[M + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}\right] [\rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} + s \left( \frac{\log p_n}{n} \right)^{1/2}]}{\frac{b}{M} n^{-\gamma} + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - 3s \left( \frac{\log p_n}{n} \right)^{1/2}} \nonumber \\
     &\leq \frac{2\left ( M+\rho_2 + s \right )  \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }}}{\frac{b}{M} n^{-\gamma} + \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }} - 3s \left( \frac{\log p_n}{n} \right)^{1/2}} \nonumber \\
    &\leq \frac{2\left ( M+\rho_2 + s \right )  \rho_2\frac{1}{n^{1.5\gamma + \varepsilon_0 }}}{\frac{b}{M} n^{-\gamma} } \nonumber \\
    &\leq 2\frac{M\left ( M+\rho_2 + s \right )  \rho_2}{b}\frac{1}{n^{\frac{1}{2} \gamma + \varepsilon_0 }}.
    \label{ref38}
\end{align}

From \eqref{ref38}, we deduce
\begin{equation}
    \left| \mu_{\hat{J}_{{\tilde{k}_n}-1}, \hat{j}_{{\tilde{k}_n}}} \right| \leq 2\frac{M\left ( M+\rho_2 + s \right )  \rho_2}{b}n^{-\left ( \frac{1}{2} \gamma + \varepsilon_0 \right )  },
    \nonumber
\end{equation}
which contradicts \eqref{ref30}. Therefore, we conclude
\begin{align}
   &\lim_{n \to \infty} P(\hat{k}_n < \tilde{k}_n,A_{n}\left(K_{n}\right)\cap A^{\prime}_{n}\left(K_{n}\right) ) = 0,\nonumber \\
     & \lim_{n \to \infty} P(\hat{k}_n < \tilde{k}_n) = 0.
    \label{ref39}
\end{align}

Combining \eqref{ref32} and \eqref{ref39}, we establish the desired result:
\begin{equation}
    \lim_{n \to \infty} P(\hat{k}_n = \tilde{k}_n) = 1. \nonumber
\end{equation}
\end{proof}



