\section{Preliminary on Differential Privacy}
\begin{definition}[R\'enyi Divergence]
\label{def:renyi_divergence}
Let \( X \) and \( Y \) be two discrete random variables over a common support of \( n \) elements, with probability mass functions \( \{p_i\} \) and \( \{q_i\} \), respectively. The R\'enyi divergence of order \( \alpha > 0 \), \( \alpha \neq 1 \), from \( X \) to \( Y \) is defined as
\[
D_\alpha(X \parallel Y) = \frac{1}{\alpha - 1} \log \left( \sum_{i=1}^{n} \frac{p_i^\alpha}{q_i^{\alpha - 1}} \right),
\]
where \( p_i = \Pr[X = x_i] \) and \( q_i = \Pr[Y = x_i] \).
\end{definition}

\begin{definition}[R\'enyi Divergence for Continuous Distributions]
\label{def:renyi_continuous}
Let \( p(x) \) and \( q(x) \) be two continuous probability density functions defined over a common domain \( \mathcal{X} \subseteq \mathbb{R}^d \). The R\'enyi divergence of order \( \alpha > 0 \), \( \alpha \neq 1 \), from \( p \) to \( q \) is defined as
\[
D_\alpha(p \parallel q) 
= \frac{1}{\alpha - 1} \log \int_{\mathcal{X}} p(x)^\alpha q(x)^{1 - \alpha} \, dx
= \frac{1}{\alpha - 1} \log \mathbb{E}_{x \sim q} \left( \frac{p(x)}{q(x)} \right)^\alpha,
\]
where \( \mathbb{E}_{x \sim q} \) denotes the expectation with respect to the distribution \( q(x) \).
\end{definition}


% \subsection{Proposition}
\begin{proposition}[RDP~\cite{mironov2017renyi}]\label{proposition:RDP+MGF}
For any $\alpha \geq 0$, if at time step $t$ the randomized mechanism $M_t$ satisfies
\[
\left(\alpha + 1, \frac{K_{M_t}(\alpha)}{\alpha}\right)\text{-RDP},
\]
then the composed mechanism $M$ over $K$ iterations satisfies at least
\[
\left(\alpha + 1, \frac{ \sum_{t=1}^K K_{M_t}(\alpha) }{\alpha}\right)\text{-RDP}.
\]
\end{proposition}

This proposition is based on the additivity of RDP, the Rényi divergence of several mechanisms satisfying RDP accumulates under composition.

% \subsection{Corollary}
\begin{corollary}[From RDP to DP]\label{corollary:From RDP to DP}
Combining Proposition~\ref{From RDP to DP} and Proposition~\ref{proposition:RDP+MGF}, we obtain the following result.
If the randomized training mechanism $M_t$ satisfies RDP at time step $t$, then
\[
\left(\frac{K_{M_t}(\alpha) + \log(1/\delta)}{\alpha}, \delta\right)\text{-DP},
\]
therefore, we can determine the minimal privacy loss $\varepsilon$ under a given $\delta$ via tuning the Rényi order
\[
\varepsilon(\delta) = \min_\alpha \frac{K_{M_t}(\alpha) + \log(1/\delta)}{\alpha}.
\]
Conversely, given a fixed $\varepsilon$, the minimal achievable $\delta$ is
\[
\delta = \min_\alpha \exp\left(K_{M_t}(\alpha) - \alpha \varepsilon\right).
\]
\end{corollary}

These results indicate that we can use the moment generating function (MGF) to optimize differential privacy accounting, and determine optimal privacy compositions by tuning the Rényi order $\alpha$.



\section{Deferred Proofs for Section~\ref{sec:Theoretical Analysis}}

\subsection{Proof of Theorem~\ref{the:Privacy Guarantee of DPIGU}}\label{proof:Privacy Guarantee of DPIGU}
\begin{proof}
We analyze the privacy guarantee of AdaDPIGU under the Gaussian mechanism with top-$k$ sparsification.

Let \(\boldsymbol{g}_t(\boldsymbol{x}_i)\) denote the clipped per-sample gradient at step \(t\). Given a clipping threshold \(C\), the \(\ell_2\)-sensitivity of the aggregated gradient between any pair of neighboring datasets \(D\) and \(D'\) (differing in at most one sample) satisfies
\[
\max_{D, D'} \left\| \sum_{\boldsymbol{x}_i \in D} \boldsymbol{g}_t(\boldsymbol{x}_i) - \sum_{\boldsymbol{x}_i \in D'} \boldsymbol{g}_t(\boldsymbol{x}_i) \right\|_2 \leq C.
\]

Now suppose a fixed top-\(k\) binary mask \(\boldsymbol{m} \in \{0, 1\}^d\) is applied to every gradient update. The masked per-sample gradient becomes
\[
\boldsymbol{g}_t'(\boldsymbol{x}_i) := \boldsymbol{x} \odot \boldsymbol{g}_t(\boldsymbol{x}_i).
\]

Since the mask is fixed and applied element-wise, it is a post-processing operation, which does not increase sensitivity. Therefore, the masked gradients satisfy the same sensitivity bound
\[
\max_{D, D'} \left\| \sum_{\boldsymbol{x}_i \in D} \boldsymbol{g}_t'(\boldsymbol{x}_i) - \sum_{\boldsymbol{x}_i \in D'} \boldsymbol{g}_t'(\boldsymbol{x}_i) \right\|_2 \leq C.
\]

In the Gaussian mechanism, the added noise before masking is drawn as
\[
\boldsymbol{\zeta}_t \sim \mathcal{N}(\boldsymbol{0}, \sigma^2 C^2 \boldsymbol{I}_d).
\]

Applying the same fixed top-\(k\) mask yields
\[
\boldsymbol{m} \odot \boldsymbol{\zeta}_t \sim \mathcal{N}\left(\boldsymbol{0}, \sigma^2 C^2 \operatorname{diag}(\boldsymbol{m})\right),
\]
where \(\operatorname{diag}(\boldsymbol{m})\) is a diagonal matrix that zeroes out all unmasked coordinates.
This masking operation restricts noise to a lower-dimensional subspace without affecting the statistical independence of the retained coordinates. Specifically
\[
\mathbb{E}[\boldsymbol{m} \odot \boldsymbol{\zeta}_t] = \boldsymbol{0}, \quad
\text{Cov}[\boldsymbol{m} \odot \boldsymbol{\zeta}_t] = \sigma^2 C^2 \operatorname{diag}(\boldsymbol{m}).
\]

Since the masking is deterministic and independent of the dataset, and the overall update process remains a valid Gaussian mechanism with the same sensitivity and scaled noise, the differential privacy guarantee is preserved.

By the post-processing theorem of differential privacy~\cite{dwork2014algorithmic}, the masked mechanism satisfies the same \((\varepsilon, \delta)\)-DP guarantee as the unmasked Gaussian mechanism.

\end{proof}

\subsection{Proof of Theorem~\ref{the:DPSGD}}\label{proof:DPSGD}
\begin{proof}
Assume the training mechanism at round \( t \) is denoted as \( M_t \), which maps neighboring datasets \( d, d' \in \mathcal{D} \) to output distributions over model parameters \( \boldsymbol{\theta}_t \). We consider the following condition on the output distribution similarity
\[
\sup_{\boldsymbol{\theta}_t \in \mathcal{R},\, d, d'} \left| \log \frac{\Pr[M_t(d) = \boldsymbol{\theta}_t]}{\Pr[M_t(d') = \boldsymbol{\theta}_t]} \right| \leq \varepsilon.
\]

To analyze the accumulation of privacy loss over multiple training steps, we follow the composition analysis introduced by Abadi et al.~\cite{abadi2016deep}. Let the model at round \( t \) receive parameters \( \boldsymbol{\theta}_{t-1} \) from the previous round, and update them using stochastic gradient descent.

We define the privacy loss random variable
\[
c(\boldsymbol{\theta}_t, M_t, \boldsymbol{\theta}_{t-1}, d, d') 
= \log \frac{\Pr[M_t(\boldsymbol{\theta}_{t-1}, d) = \boldsymbol{\theta}_t]}{\Pr[M_t(\boldsymbol{\theta}_{t-1}, d') = \boldsymbol{\theta}_t]}, 
\quad \boldsymbol{\theta}_t \sim M_t(\boldsymbol{\theta}_{t-1}, d).
\]

This random variable measures the change in output distribution of the mechanism when applied to neighboring datasets. To quantify the tail of this change, we consider the moment generating function (MGF) of the privacy loss, defined for Rényi order \( \alpha \) as
\begin{align*}
K_{M_t}^{d,d'}(\alpha) 
&:= \log \mathbb{E}_{\boldsymbol{\theta}_t \sim M_t(\boldsymbol{\theta}_{t-1}, d)} \left[ \exp\left( \alpha \cdot c(\boldsymbol{\theta}_t, M_t, \boldsymbol{\theta}_{t-1}, d, d') \right) \right] \\
&= \log \mathbb{E}_{\boldsymbol{\theta}_t \sim M_t(\boldsymbol{\theta}_{t-1}, d)} \left[ \left( \frac{\Pr[M_t(\boldsymbol{\theta}_{t-1}, d) = \boldsymbol{\theta}_t]}{\Pr[M_t(\boldsymbol{\theta}_{t-1}, d') = \boldsymbol{\theta}_t]} \right)^\alpha \right].
\end{align*}

By a change of measure, this expression can be rewritten as
\[
K_{M_t}^{d,d'}(\alpha) 
= \log \mathbb{E}_{\boldsymbol{\theta}_t \sim M_t(\boldsymbol{\theta}_{t-1}, d')} \left[ \left( \frac{\Pr[M_t(\boldsymbol{\theta}_{t-1}, d)]}{\Pr[M_t(\boldsymbol{\theta}_{t-1}, d')]} \right)^{\alpha + 1} \right].
\]

Since the training process consists of \( K \) rounds of mechanisms \( M_1, \cdots, M_K \), where each round depends only on the previous round's model parameter, the training procedure forms a Markov chain. This Markov property implies that the privacy loss random variables at different steps are conditionally independent
\[
\Pr[M_t(\boldsymbol{\theta}_{t-1}, d) = \boldsymbol{\theta}_t \mid M_{t-1}(\boldsymbol{\theta}_{t-2}, d) = \boldsymbol{\theta}_{t-1}] = \Pr[M_t(\boldsymbol{\theta}_{t-1}, d) = \boldsymbol{\theta}_t].
\]

As a result, the total privacy loss across the training procedure \( M_{1:K} \) can be expressed as a sum of per-step losses
\[
c(\boldsymbol{\theta}_{1:K}, M_{1:K}, \boldsymbol{\theta}_0: \boldsymbol{\theta}_{K-1}, d, d') 
= \sum_{t=1}^K \log \frac{\Pr[M_t(\boldsymbol{\theta}_{t-1}, d) = \boldsymbol{\theta}_t]}{\Pr[M_t(\boldsymbol{\theta}_{t-1}, d') = \boldsymbol{\theta}_t]} 
= \sum_{t=1}^K c(\boldsymbol{\theta}_t, M_t, \boldsymbol{\theta}_{t-1}, d, d').
\]

Accordingly, the moment generating function (MGF) of the total privacy loss also satisfies the additive property
\[
K_{M_{1:K}}^{d,d'}(\alpha) = \sum_{t=1}^{K} K_{M_t}^{d,d'}(\alpha).
\]

To ensure a worst-case guarantee over all neighboring datasets \( d, d' \in \mathcal{D} \), we define the global MGF upper bound as
\[
K_{M_{1:K}}(\alpha) := \sup_{d, d' \in \mathcal{D}} K_{M_{1:K}}^{d,d'}(\alpha) = \sum_{t=1}^{K} \sup_{d, d' \in \mathcal{D}} K_{M_t}^{d,d'}(\alpha) = \sum_{t=1}^{K} K_{M_t}(\alpha).
\]

This shows that even in the worst-case scenario, the overall privacy loss of the composed mechanism remains additive in terms of Rényi divergence.

According to Definition~\ref{def:renyi_continuous}, we can directly relate the moment generating function $K_{M_t}^{d,d'}(\alpha)$ to the c divergence as follows
\begin{align*}
K_{M_t}^{d,d'}(\alpha) &= \log \mathbb{E}_{\boldsymbol{\theta}_t \sim M_t(\boldsymbol{\theta}_{t-1}, d)} \left[ \left( \frac{\Pr[M_t(\boldsymbol{\theta}_{t-1}, d) = \boldsymbol{\theta}_t]}{\Pr[M_t(\boldsymbol{\theta}_{t-1}, d') = \boldsymbol{\theta}_t]} \right)^{\alpha} \right] \\
&= \alpha D_{\alpha+1} \left( M_t(\boldsymbol{\theta}_{t-1}, d) \, \| \, M_t(\boldsymbol{\theta}_{t-1}, d') \right).
\end{align*}

Therefore, the MGF provides a way to characterize the deviation between outputs of training mechanisms on neighboring datasets. Furthermore, we can use MGF to express the privacy guarantee parameter of RDP.
According to Corollary~\ref{corollary:From RDP to DP}, we analyze differential privacy from a probabilistic perspective. For any pair of neighboring datasets \( d, d' \), if the single-round privacy loss is defined as \( c(\boldsymbol{\theta}_t, M_t, \boldsymbol{\theta}_{t-1}, d, d') \), then the cumulative privacy loss over \( K \) steps is
\[
c(\boldsymbol{\theta}_t, M) = \sum_{t=1}^K c(\boldsymbol{\theta}_t, M_t, \boldsymbol{\theta}_{t-1}, d, d').
\]

To bound the tail of this loss, we apply Markov’s inequality to the moment generating function of the cumulative privacy loss
\begin{align*}
\Pr[c(\boldsymbol{\theta}_t, M) > \varepsilon] 
&= \Pr[\exp(\alpha c(\boldsymbol{\theta}_t, M)) > \exp(\alpha \varepsilon)] \\
&\leq \frac{\mathbb{E}[\exp(\alpha c(\boldsymbol{\theta}_t, M))]}{\exp(\alpha \varepsilon)}.
\end{align*}

Assuming the mechanisms \( M_1, \dots, M_K \) are conditionally independent given the Markov assumption, the expectation decomposes as
\[
\mathbb{E}[\exp(\alpha c(\boldsymbol{\theta}_t, M))] 
= \prod_{t=1}^{K} \mathbb{E}[\exp(\alpha c(\boldsymbol{\theta}_t, M_t))] 
= \exp\left( \sum_{t=1}^K K_{M_t}^{d,d'}(\alpha) \right).
\]

Therefore, we obtain the following bound
\[
\Pr[c(\boldsymbol{\theta}_t, M) > \varepsilon] 
\leq \exp\left( \sum_{t=1}^K K_{M_t}^{d,d'}(\alpha) - \alpha \varepsilon \right) 
= \delta.
\]

Rearranging, we find that to ensure \((\varepsilon, \delta)\)-differential privacy, it suffices to guarantee
\[
\sum_{t=1}^{K} K_{M_t}^{d,d'}(\alpha) \leq \alpha \varepsilon + \log \left( \frac{1}{\delta} \right).
\]

As stated earlier, although overlapping between datasets may occur, the worst-case privacy loss only arises under extreme differences between neighboring datasets. To ensure rigorous privacy guarantees, we must consider the maximum Rényi divergence over all neighboring dataset pairs \( (d, d') \). In practice, we directly compute the upper bound of the moment generating function (MGF), \( K_{M_t}^{d,d'}(\alpha) \), at each training step.

According to the analysis of Abadi et al.~\cite{abadi2016deep}, under the Gaussian mechanism with subsampling rate \( q \), the Rényi divergence at order \( \alpha \) satisfies
\[
K_{M_t}^{d,d'}(\alpha) \leq \frac{q^2 \alpha^2}{\sigma^2}.
\]

Assuming a total of \( T \) training steps with independent mechanisms, the MGF of the composed mechanism satisfies the additive property
\[
K_{M}(\alpha) = \sum_{t=1}^T K_{M_t}^{d,d'}(\alpha) \leq \frac{T q^2 \alpha^2}{\sigma^2}.
\]

Combining Corollary~\ref{corollary:From RDP to DP}, we can translate this Rényi bound into an \((\varepsilon, \delta)\)-DP guarantee by minimizing
\[
\delta = \min_\alpha \exp\left( K_M(\alpha) - \alpha \varepsilon \right).
\]

Substituting the bound into the expression gives
\[
\delta \leq \exp\left( \frac{T q^2 \alpha^2}{\sigma^2} - \alpha \varepsilon \right).
\]

Taking derivative with respect to \( \alpha \) and solving for the optimal order yields
\[
\alpha^* = \frac{\sigma^2 \varepsilon}{2 T q^2}.
\]

Plugging back gives the minimal achievable \( \delta \)
\[
\delta = \exp\left( -\frac{\sigma^2 \varepsilon^2}{4 T q^2} \right).
\]

Rearranging yields the required noise scale to ensure \((\varepsilon, \delta)\)-DP
\[
\sigma = \frac{2q \sqrt{T \log(1/\delta)}}{\varepsilon}.
\]
\end{proof}


\subsection{Proof of Theorem~\ref{the:clip+SGD}}\label{theproof:clip+SGD}

\begin{proof}
We start from the $G$-smoothness of the objective to derive a descent inequality involving the true gradient and the noisy, clipped update $\bar{\boldsymbol{g}}_t$. By taking expectations and bounding the gradient norm using the clipping threshold $C$, we obtain an upper bound on the expected inner product $\mathbb{E}[\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \bar{\boldsymbol{g}}_t \rangle]$. Averaging over $T$ steps and applying the lower bound on the loss function, we arrive at a convergence-type bound that quantifies optimization progress under differentially private updates.

According to the $G$-smoothness assumption, the loss function satisfies
\begin{align*}
\mathcal{L}(\boldsymbol{\theta}_{t+1}) 
&\leq \mathcal{L}(\boldsymbol{\theta}_t) + \langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \boldsymbol{\theta}_{t+1} - \boldsymbol{\theta}_t \rangle + \frac{G}{2} \|\boldsymbol{\theta}_{t+1} - \boldsymbol{\theta}_t\|^2 \notag \\
&= \mathcal{L}(\boldsymbol{\theta}_t) - \eta \langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \bar{\boldsymbol{g}}_t \rangle + \frac{G \eta^2}{2} \|\bar{\boldsymbol{g}}_t\|^2.
\end{align*}
Taking expectation on both sides and rearranging terms yields
\begin{align*}
\mathbb{E}[\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \bar{\boldsymbol{g}}_t \rangle] 
&\leq \frac{1}{\eta} \mathbb{E}\left[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})\right] 
+ \frac{G \eta}{2} \mathbb{E}[\|\bar{\boldsymbol{g}}_t\|^2] \\
&\leq \frac{1}{\eta} \mathbb{E}\left[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})\right] 
+ \frac{\eta G C^2}{2}.
\end{align*}
where the last inequality follows from the clipping bound $\|\bar{\boldsymbol{g}}_t\| \leq C$.
Taking average over $T$ steps
\[
\frac{1}{T} \sum_{t=1}^{T} \mathbb{E}[\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \bar{\boldsymbol{g}}_t \rangle] 
\leq \frac{1}{T \eta} \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_1) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] + \frac{\eta G C^2}{2T}.
\]
Since $
\mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_{t+1})] \geq \min_\theta \mathcal{L}(\boldsymbol{\theta}),
$
we have
\[
\mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_1) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
= \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_1)] - \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_{t+1})] 
\leq \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_1)] - \min_\theta \mathcal{L}(\boldsymbol{\theta}).
\]
Thus, we can obtain
\[
\frac{1}{T} \sum_{t=1}^{T} \mathbb{E}[\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \bar{\boldsymbol{g}}_t \rangle] 
\leq \frac{1}{T \eta} \left( \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_1)] - \min_\theta \mathcal{L}(\boldsymbol{\theta}) \right) + \frac{\eta G C^2}{2T}.
\]
\end{proof}



\subsection{Proof of Lemma~\ref{lemma:topk_energy_retention}}\label{theproof:topk_energy_retention}

\begin{proof}
The argument is adapted from~\cite{beznosikov2023biased}, which analyzes the energy preserved by top-$k$ projections.
By definition of the top-$k$ mask \( \boldsymbol{m}^{(k)} \), we have
\[
\langle \boldsymbol{u}, \boldsymbol{m}^{(k)} \odot \boldsymbol{u} \rangle 
= \sum_{i=1}^{d} m_i^{(k)} u_i^2 
= \|\boldsymbol{m}^{(k)} \odot \boldsymbol{u}\|^2.
\]

Thus, the energy retention ratio is given by
\[
\alpha(\boldsymbol{u}) := \frac{\|\boldsymbol{m}^{(k)} \odot \boldsymbol{u}\|^2}{\|\boldsymbol{u}\|^2}.
\]

To establish a lower bound on \(\alpha(\boldsymbol{u})\), assume that \(\boldsymbol{u}\) is non-negative and sorted in non-decreasing order: \( u_{(1)} \leq \cdots \leq u_{(d)} \). Then the top-$k$ mask selects the $k$ largest coordinates \( u_{(d-k+1)}, \dots, u_{(d)} \), and we obtain
\[
\alpha(\boldsymbol{u}) = \frac{\sum_{i=d-k+1}^{d} u_{(i)}^2}{\sum_{i=1}^{d} u_{(i)}^2}.
\]

Since both the numerator and denominator consist of squared non-negative terms and the numerator selects the largest \(k\) values, the minimum value of this ratio is achieved when all entries are equal. In this case, each \(u_i^2 = c\) for some constant \(c > 0\), and
\[
\alpha(\boldsymbol{u}) = \frac{k c}{d c} = \frac{k}{d}.
\]

Therefore, we conclude that
\[
\alpha(\boldsymbol{u}) \geq \frac{k}{d}.
\]
\end{proof}


\subsection{Proof of Corollary~\ref{cor:topk_mask_expectation}}\label{theproof:topk_mask_expectation}
\begin{proof}
By Lemma~\ref{lemma:topk_energy_retention}, for any realization of the random vector $\boldsymbol{v} \in \mathbb{R}^d$, we have
\[
\|\boldsymbol{m}^{(k)} \odot \boldsymbol{v}\|^2 = \alpha(\boldsymbol{v}) \cdot \|\boldsymbol{v}\|^2,
\]
taking expectation on both sides gives
\[
\mathbb{E} \|\boldsymbol{m}^{(k)} \odot \boldsymbol{v}\|^2 = \mathbb{E}[\alpha(\boldsymbol{v}) \cdot \|\boldsymbol{v}\|^2].
\]

Since $\alpha(\boldsymbol{v}) \leq \alpha_t := \sup_{\boldsymbol{v}} \alpha(\boldsymbol{v})$ by definition, and assuming $\boldsymbol{v}$ has finite second moment, we apply the inequality
\[
\mathbb{E}[\alpha(\boldsymbol{v}) \cdot \|\boldsymbol{v}\|^2] 
\leq \alpha_t \cdot \mathbb{E} \|\boldsymbol{v}\|^2.
\]

Therefore,
\[
\mathbb{E} \|\boldsymbol{m}^{(k)} \odot \boldsymbol{v}\|^2 
\leq \alpha_t \cdot \mathbb{E} \|\boldsymbol{v}\|^2,
\]
which completes the proof.
\end{proof}



\subsection{Proof of Theorem~\ref{the:topk+noise+SGD}}\label{proof:topk+noise+SGD}

\begin{proof}
The goal is to upper bound the average squared gradient norm under differentially private updates with sparsified gradients. The proof starts from the $G$-smoothness inequality to relate the loss decrease to the update direction. We substitute the masked and noise-perturbed gradient into the update rule and take expectations to isolate the alignment term between the true gradient and the update. Using Lemma~\ref{lemma:topk_energy_retention}, we quantify the energy retained by the top-$k$ mask via a factor $\alpha_t$. The norm of the masked noisy gradient is then bounded via Corollary~\ref{cor:topk_mask_expectation}, leading to an upper bound that accounts for both gradient variance and additive Gaussian noise. After rearranging terms and averaging over $T$ steps, we arrive at a convergence-style result that decays as $\mathcal{O}(1/\sqrt{T})$, with a dependence on $\alpha_t$, $B$, $d$, and $\sigma^2$.
From the $G$-Lipschitz smoothness condition, we have
\[
\langle \nabla f(\boldsymbol{y}), (\boldsymbol{x}-\boldsymbol{y}) \rangle = \nabla f(\boldsymbol{y})^T (\boldsymbol{x}-\boldsymbol{y}),
\]
\[
f(\boldsymbol{x}) \leq f(\boldsymbol{y}) + \nabla f(\boldsymbol{y})^T(\boldsymbol{x}-\boldsymbol{y}) + \frac{G}{2} \|\boldsymbol{x}-\boldsymbol{y}\|^2.
\]

Note that Gaussian noise is added to the aggregated gradient, and is scaled by the batch size $B$ before updating the model. Then we have
\[
\mathcal{L}(\boldsymbol{\theta}_{t+1}) \leq \mathcal{L}(\boldsymbol{\theta}_t) + \langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), (\boldsymbol{\theta}_{t+1} - \boldsymbol{\theta}_t) \rangle + \frac{G}{2} \|\boldsymbol{\theta}_{t+1} - \boldsymbol{\theta}_t\|^2.
\]

The noise-injected SGD update rule is
\[
\boldsymbol{\theta}_{t+1} = \boldsymbol{\theta}_t - \eta 
\Bigg( \boldsymbol{m} \odot 
\bigg( \nabla \mathcal{L}(\boldsymbol{\theta}_t) + 
\frac{1}{B} \Big( \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \Big) 
\bigg) \Bigg).
\]

Then we obtain
\[
\mathcal{L}(\boldsymbol{\theta}_{t+1}) 
\leq \mathcal{L}(\boldsymbol{\theta}_t) 
- \eta \Bigg\langle 
\nabla \mathcal{L}(\boldsymbol{\theta}_t),\ 
\boldsymbol{m} \odot 
\bigg( \nabla \mathcal{L}(\boldsymbol{\theta}_t) 
+ \frac{1}{B} \Big( \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \Big) 
\bigg) 
\Bigg\rangle
\]

\[
+ \frac{\eta^2 G}{2} 
\Bigg\| 
\boldsymbol{m} \odot 
\bigg( \nabla \mathcal{L}(\boldsymbol{\theta}_t) 
+ \frac{1}{B} \Big( \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \Big) 
\bigg) 
\Bigg\|^2.
\]


Taking expectation and rearranging, we have
\begin{align}
&\eta \, \mathbb{E} \left\langle 
\nabla \mathcal{L}(\boldsymbol{\theta}_t),\ 
\boldsymbol{m} \odot \left( 
\nabla \mathcal{L}(\boldsymbol{\theta}_t) + \frac{1}{B} \sum_i \boldsymbol{z}_{t,i} + \frac{1}{B} \boldsymbol{z}_\sigma 
\right) 
\right\rangle \notag \\
&\leq \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
+ \eta^2 \mathbb{E} \left[ 
\frac{G}{2} \left\| 
\boldsymbol{m} \odot \left( 
\nabla \mathcal{L}(\boldsymbol{\theta}_t) + \frac{1}{B} \sum_i \boldsymbol{z}_{t,i} + \frac{1}{B} \boldsymbol{z}_\sigma 
\right) 
\right\|^2 
\right]
\label{eq:expected_inner_bound}
\end{align}

Since (by Lemma~\ref{lemma:topk_energy_retention})
\[
\langle \boldsymbol{u}, \boldsymbol{m}^{(k)} \odot \boldsymbol{u} \rangle = \alpha_t \|\boldsymbol{u}\|^2,
\]
where $\alpha_t := \|\boldsymbol{m}^{(k)} \odot \nabla \mathcal{L}(\boldsymbol{\theta}_t)\|^2 / \|\nabla \mathcal{L}(\boldsymbol{\theta}_t)\|^2$,
substituting back, we obtain
\begin{align*}
&\eta \, \mathbb{E} \left\langle 
\nabla \mathcal{L}(\boldsymbol{\theta}_t),\ 
\boldsymbol{m} \odot \left( \nabla \mathcal{L}(\boldsymbol{\theta}_t) + \frac{1}{B} \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right) 
\right\rangle \\
&= \eta \left\{
\mathbb{E} \langle \nabla \mathcal{L}(\boldsymbol{\theta}_t),\ \boldsymbol{m} \odot \nabla \mathcal{L}(\boldsymbol{\theta}_t) \rangle 
+ \mathbb{E} \left\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t),\ 
\boldsymbol{m} \odot \left( \frac{1}{B} \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right) \right\rangle
\right\} \\
&= \eta \left\{ 
\alpha_t \|\nabla \mathcal{L}(\boldsymbol{\theta}_t)\|^2 
+ \alpha_t \, \mathbb{E} \left\langle \boldsymbol{g}_\theta,\ \frac{1}{B} \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right\rangle 
\right\} \\
&= \eta \alpha_t \|\nabla \mathcal{L}(\boldsymbol{\theta}_t)\|^2.
\end{align*}

By substituting into Equation~\ref{eq:expected_inner_bound}, we obtain
\begin{equation}
\eta \alpha_t \|\nabla \mathcal{L}(\boldsymbol{\theta}_t)\|^2 
\leq \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
+ \frac{G \eta^2}{2} \mathbb{E} \left\| 
\boldsymbol{m} \odot \left( \nabla \mathcal{L}(\boldsymbol{\theta}_t) + \frac{1}{B} \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right) 
\right\|^2
\label{eq:final_bound}
\end{equation}

By expanding the squared norm term
\[
\frac{G \eta^2}{2} \, \mathbb{E} \left( \boldsymbol{m}^2 \left[ \left( \nabla \mathcal{L}(\boldsymbol{\theta}_t) \right)^2 
+ \frac{1}{B^2} \left( \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right)^2 
+ 2 \nabla \mathcal{L}(\boldsymbol{\theta}_t) \cdot \frac{1}{B} \left( \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right)
\right] \right)
\]
\[
= \mathbb{E} \left\| 
\boldsymbol{m} \odot \left( \nabla \mathcal{L}(\boldsymbol{\theta}_t) + \frac{1}{B} \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right) 
\right\|^2,
\]
where the expectation of the inner product between the gradient and the noise is zero, due to their independence.

Since (by Corollary~\ref{cor:topk_mask_expectation})
\begin{align}
&\mathbb{E} \left\| 
\boldsymbol{m} \odot \left( \nabla \mathcal{L}(\boldsymbol{\theta}_t) + \frac{1}{B} \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right) 
\right\|^2 \notag \\
&\leq \alpha_t \,
\mathbb{E} \left\| \nabla \mathcal{L}(\boldsymbol{\theta}_t) + \frac{1}{B} \left( \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right) \right\|^2.
\label{eq:mask_bound_alpha}
\end{align}

To further simplify the upper bound in Equation~\eqref{eq:mask_bound_alpha}, we expand the squared norm of the noisy gradient as
\begin{align*}
&\mathbb{E} \left\| \nabla \mathcal{L}(\boldsymbol{\theta}_t) + \frac{1}{B} \left( \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right) \right\|^2 \\
&= \mathbb{E} \left\| \nabla \mathcal{L}(\boldsymbol{\theta}_t) \right\|^2 
+ \mathbb{E} \left\| \frac{1}{B} \left( \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right) \right\|^2 
+ 2 \, \mathbb{E} \left\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t),\ \frac{1}{B} \left( \sum_i \boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma \right) \right\rangle \\
&= \left\| \nabla \mathcal{L}(\boldsymbol{\theta}_t) \right\|^2 
+ \mathbb{E} \left\| \frac{1}{B} \sum_i \boldsymbol{z}_{t,i} \right\|^2 
+ \mathbb{E} \left\| \frac{1}{B} \boldsymbol{z}_\sigma \right\|^2 
+ \frac{2}{B} \sum_i \mathbb{E} \left\langle \boldsymbol{z}_{t,i},\ \boldsymbol{z}_\sigma \right\rangle.
\end{align*}

Also, we have
\[
\mathbb{E} \| \boldsymbol{z}_{t,i} \|^2 = \mathbb{E} \sum_I \boldsymbol{z}_{t,i}^2 = \sum_I \mathbb{E} \boldsymbol{z}_{t,i}^2 = \sum_I \boldsymbol{z}_{t,i}^2 = d \sigma^2,
\]
according to Equation~\ref{eq:mask_bound_alpha}, it follows that
\begin{equation}
\mathbb{E} \left\| \boldsymbol{m} \odot \left( \nabla \mathcal{L}(\boldsymbol{\theta}_t) + \frac{1}{B} \sum_I (\boldsymbol{z}_{t,i} + \boldsymbol{z}_\sigma) \right) \right\|^2 
\leq \alpha_t \left[\| \nabla \mathcal{L}(\boldsymbol{\theta}_t) \|^2 + \frac{\sigma_g^2}{B} + \frac{d \sigma^2}{B^2} \right]
\label{eq:masked_norm_upper_bound}
\end{equation}

Substituting Equation~\ref{eq:masked_norm_upper_bound} into Equation~\ref{eq:final_bound}, we obtain
\[
\eta \alpha_t \| \nabla \mathcal{L}(\boldsymbol{\theta}_t) \|^2 
\leq \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
+ \frac{\alpha_t G \eta^2}{2} \left( \| \nabla \mathcal{L}(\boldsymbol{\theta}_t) \|^2 
+ \frac{\sigma_g^2}{B} + \frac{d \sigma^2}{B^2} \right),
\]

Taking $\eta = \frac{1}{G \sqrt{T}}$, we have
\[
\frac{\alpha_t}{G \sqrt{T}} \| \nabla \mathcal{L}(\boldsymbol{\theta}_t) \|^2 
\leq \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
+ \frac{\alpha_t}{2 G T} \left( \| \nabla \mathcal{L}(\boldsymbol{\theta}_t) \|^2 
+ \frac{\sigma_g^2}{B} + \frac{d \sigma^2}{B^2} \right),
\]

We collect the coefficient of $\|\nabla \mathcal{L}(\boldsymbol{\theta}_t)\|^2$
\[
\left( \frac{1}{G\sqrt{T}} - \frac{1}{2GT} \right) \alpha_t \|\nabla \mathcal{L}(\boldsymbol{\theta}_t)\|^2 
\leq \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
+ \frac{\alpha_t}{2GT} \left( \frac{\sigma_g^2}{B} + \frac{d\sigma^2}{B^2} \right),
\]
\[
\left( \frac{1}{G\sqrt{T}} - \frac{1}{2GT} \right) 
= \frac{2}{2G\sqrt{T}} - \frac{1}{2G\sqrt{T}} = \frac{2 - \frac{1}{\sqrt{T}}}{2G\sqrt{T}}.
\]

Since $T > 1$, we have $2 - \frac{1}{\sqrt{T}} > 1$,
therefore
\[
\left( \frac{1}{G\sqrt{T}} - \frac{1}{2GT} \right) 
= \frac{2 - \frac{1}{\sqrt{T}}}{2G\sqrt{T}} > \frac{1}{2G\sqrt{T}}.
\]

Thus, we obtain
\[
\frac{\alpha_t}{2G\sqrt{T}} \|\nabla \mathcal{L}(\boldsymbol{\theta}_t)\|^2 
\leq \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
+ \frac{\alpha_t}{2GT} \left( \frac{\sigma_g^2}{B} + \frac{d\sigma^2}{B^2} \right).
\]

We have
\[
\| \nabla \mathcal{L}(\boldsymbol{\theta}_t) \|^2 
\leq \frac{2G \sqrt{T}}{\alpha_t} \, \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
+ \frac{1}{\sqrt{T}} \left( \frac{\sigma_g^2}{B} + \frac{d \sigma^2}{B^2} \right).
\]

Taking average over $T$ steps
\[
\frac{1}{T} \sum_t \| \nabla \mathcal{L}(\boldsymbol{\theta}_t) \|^2 
\leq \frac{2G\sqrt{T}}{r} \cdot \frac{1}{T} \sum_t \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
+ \frac{1}{\sqrt{T}} \left( \frac{\sigma_g^2}{B} + \frac{d \sigma^2}{B^2} \right),
\]

Since
\[
\mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_{t+1})] \geq \min_\theta \mathcal{L}(\boldsymbol{\theta}),
\]
we have
\[
\mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_1) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
= \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_1)] - \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_{t+1})] 
\leq \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_1)] - \min_\theta \mathcal{L}(\boldsymbol{\theta}).
\]

Therefore,
\[
\frac{1}{T} \sum_t \| \nabla \mathcal{L}(\boldsymbol{\theta}_t) \|^2 
\leq \frac{2G}{\alpha_t \sqrt{T}} \left( \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_1)] - \min_\theta \mathcal{L}(\boldsymbol{\theta}) \right) 
+ \frac{1}{\sqrt{T}} \left( \frac{\sigma_g^2}{B} + \frac{d \sigma^2}{B^2} \right).
\]


\end{proof}


\subsection{Proof of Theorem~\ref{the:topk+clip+DPSGD}}\label{proof:topk+clip+DPSGD}

\begin{proof}
This proof aims to upper bound the expected alignment between the true gradient and the privatized update $\tilde{\boldsymbol{g}}_t$ under coordinate-wise masking and additive Gaussian noise. Starting from the $G$-smoothness of the loss function, we derive a one-step descent inequality by substituting the noisy SGD update rule. The inner product $\langle \nabla \mathcal{L}, \tilde{\boldsymbol{g}}_t \rangle$ is then isolated and upper bounded by the function value decrease and the second-order moment of the update. The masked noise contribution is controlled via a sparsity-aware energy retention factor $\alpha_t$, and the variance of the Gaussian noise is explicitly computed. Combining these steps yields a convergence-style upper bound that reveals how $\alpha_t$, $B$, $d$, and $\sigma$ jointly affect training dynamics under differential privacy.
By the $G$-smoothness of $\mathcal{L}$, we have
\[
\mathcal{L}(\boldsymbol{\theta}_{t+1}) 
\leq \mathcal{L}(\boldsymbol{\theta}_t) + \langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), (\boldsymbol{\theta}_{t+1} - \boldsymbol{\theta}_t) \rangle + \frac{G}{2} \| \boldsymbol{\theta}_{t+1} - \boldsymbol{\theta}_t \|^2,
\]
using the update rule
\[
\boldsymbol{\theta}_{t+1} = \boldsymbol{\theta}_t - \eta \left( \tilde{\boldsymbol{g}}_t + \boldsymbol{m} \odot \boldsymbol{z}_{DP} \right),
\]
where the average clipped gradient $\tilde{\boldsymbol{g}}_t$ is defined by
\[
\tilde{\boldsymbol{g}}_t = \frac{1}{B} \sum_i \frac{\boldsymbol{g}_t'(\boldsymbol{x}_i)}{\max(1, C / \|\boldsymbol{g}_t'(\boldsymbol{x}_i)\|)},
\]
we get
\begin{align*}
\mathcal{L}(\boldsymbol{\theta}_{t+1}) 
&= \mathcal{L}(\boldsymbol{\theta}_t) 
- \eta \langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \tilde{\boldsymbol{g}}_t + \boldsymbol{m} \odot \boldsymbol{z}_{DP} \rangle 
+ \frac{G \eta^2}{2} \left\| \tilde{\boldsymbol{g}}_t + \boldsymbol{m} \odot \boldsymbol{z}_{DP} \right\|^2 \\
&= \mathcal{L}(\boldsymbol{\theta}_t) 
- \eta \langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \tilde{\boldsymbol{g}}_t \rangle 
- \eta \langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \boldsymbol{m} \odot \boldsymbol{z}_{DP} \rangle 
+ \frac{G \eta^2}{2} \left\| \tilde{\boldsymbol{g}}_t + \boldsymbol{m} \odot \boldsymbol{z}_{DP} \right\|^2,
\end{align*}
We take expectation and rearrange
\begin{align*}
\mathbb{E}[\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \tilde{\boldsymbol{g}}_t \rangle] 
&= \frac{1}{\eta} \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
- \mathbb{E}[\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \boldsymbol{m} \odot \boldsymbol{z}_{DP}] + \frac{G \eta}{2} \mathbb{E}[\| \tilde{\boldsymbol{g}}_t + \boldsymbol{m} \odot \boldsymbol{z}_{DP} \|^2] \\
\\
&= \frac{1}{\eta} \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
+ \frac{G \eta}{2} \left( \mathbb{E}[\| \tilde{\boldsymbol{g}}_t \|^2] + \mathbb{E}[\| \boldsymbol{m} \odot \boldsymbol{z}_{DP} \|^2] \right).
\end{align*}

Since (by Corollary~\ref{cor:topk_mask_expectation})
\[
\mathbb{E} \left\| \boldsymbol{m}^{(k)} \odot \boldsymbol{v} \right\|^2 
\leq \alpha_t \cdot \mathbb{E} \|\boldsymbol{v}\|^2,
\]
we have
\[
\mathbb{E}[\| \boldsymbol{m} \odot \boldsymbol{z}_{DP} \|^2] 
\leq \alpha_t \cdot \mathbb{E}[\|\boldsymbol{z}_{DP}\|^2].
\]

Therefore
\[
\mathbb{E}[\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \tilde{\boldsymbol{g}}_t \rangle] 
\leq \frac{1}{\eta} \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})] 
+ \frac{G \eta}{2} \left( \mathbb{E}[\| \tilde{\boldsymbol{g}}_t \|^2] + \alpha_t \cdot \mathbb{E}[\| \boldsymbol{z}_{DP} \|^2] \right).
\]

Since each $\boldsymbol{z}_i \sim \mathcal{N}(\boldsymbol{0}, \sigma^2 C^2 \boldsymbol{I}_d)$ is independent, the average noise vector is
\[
\boldsymbol{z}_{DP} := \frac{1}{B} \sum_{i=1}^B \boldsymbol{z}_i \sim \mathcal{N}(\boldsymbol{0}, \frac{\sigma^2 C^2}{B} \boldsymbol{I}_d),
\]
and thus
\[
\mathbb{E}[\|\boldsymbol{z}_{DP}\|^2] = \operatorname{tr}(\operatorname{Cov}(\boldsymbol{z}_{DP})) = d \cdot \frac{\sigma^2 C^2}{B}.
\]

Therefore
\begin{align*}
\mathbb{E}[\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \tilde{\boldsymbol{g}}_t \rangle]
&\leq \frac{1}{\eta} \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})]
- 0 + \frac{G \eta}{2} \left( \mathbb{E}[\| \tilde{\boldsymbol{g}}_t \|^2] + \alpha_t \cdot \frac{d \sigma^2 C^2}{B} \right) \nonumber \\
&\leq \frac{1}{\eta} \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})]
+ \frac{G \eta}{2} \left( C^2 + \alpha_t \cdot \frac{d \sigma^2 C^2}{B} \right).
\end{align*}

Thus,
\[
\mathbb{E}[\langle \nabla \mathcal{L}(\boldsymbol{\theta}_t), \tilde{\boldsymbol{g}}_t \rangle]
\leq \frac{1}{\eta} \mathbb{E}[\mathcal{L}(\boldsymbol{\theta}_t) - \mathcal{L}(\boldsymbol{\theta}_{t+1})]
+ \frac{G \eta}{2} \left( C^2 + \alpha_t \cdot \frac{d \sigma^2 C^2}{B} \right).
\]
\end{proof}




