\subsection{Discussion}\label{subsec:Discussion}

\subsubsection{The Bayesian approach for more general SPDEs}\label{subsec:Generalisation1}

A natural extension to \eqref{eq:SPDE} is the semi-linear SPDE
\begin{equation}
    \D X_t = A X_t \,\D t + F(X_t)\,\D t + B \,\D W_t,\quad 0\le t\le T,\label{eq:SPDE_GeneralSemiLinear}
\end{equation}
defined on a bounded domain $\Lambda\subset \mathbb{R}^d$, where $A\colon\operatorname{dom}(A)\subset L^2(\Lambda)\to L^2(\Lambda)$ generates a $C_0$-semi-group on $L^2(\Lambda)$, $B\colon L^2(\Lambda)\to L^2(\Lambda)$ is linear bounded operator and $F\colon L^2(\Lambda)\to L^2(\Lambda)$ is not necessarily of Nemytskii type as in \eqref{eq:SPDE}. Typical examples for $A$ include $A=\nu\Updelta$ (diffusivity $\nu>0$), $A=-(-\Updelta)^\rho$ (fractional Laplacian with $\rho \ge 1/2$) and $A=\partial_y (a(y)\partial_y\MTemptyplaceholder)$ (divergence form), while $B$ can for example have the form $B=\sigma\identity$ (space-time white noise with intensity $\sigma$) or $B=-(-\Updelta)^{-\kappa}$ with $\kappa>0$, the latter inducing higher spatial smoothness for the solution. Sufficient conditions for the wellposedness of \eqref{eq:SPDE_GeneralSemiLinear} as a (unique) mild and weak solution on $L^2(\Lambda)$ are provided in Theorems 7.2 and 7.5 of \citet{DaPrato2014} and Proposition G.0.5 of \citet{Roeckner2015}. If
\begin{equation*}
    \sup_{t\in[0,T]}\EV[f]{\exp(\delta\norm{B\inv F(X_t)}_{L^2(\Lambda)}^2)}<\infty
\end{equation*}
for some $\delta>0$, Theorem 10.18 of \citet{DaPrato2014} shows that the log-likelihood with respect to the nonlinearity $F$ is given by
\begin{equation*}
    \ell (F) = \int_0^T \iprod{B\inv F(X_t)}{B\inv[\D X_t - A X_t\,\D t]}_{L^2(\Lambda)}-\frac{1}{2}\int_0^T \norm{B\inv F(X_t)}_{L^2(\Lambda)}^2\,\D t.
\end{equation*}
Analogously to \eqref{eq:aux_Def_Likelihood}, we define the first integral as the $L^2(\prob[0]{})$-limit
\begin{equation*}
	\sum_{k\in\mathbb{N}}\int_0^T\iprod*{F(X_t)}{(B\inv)^\ast e_k}_{L^2(\Lambda)}\left(\iprod*{(B\inv)^\ast e_k}{\D X_t}_{L^2(\Lambda)} - \iprod*{A^\ast (B\inv)^\ast e_k}{X_t}_{L^2(\Lambda)}\,\D t\right)
\end{equation*}
for an orthonormal basis $(e_k)_{k\in\mathbb{N}}$ of $L^2(\Lambda)$ such that $e_k\in \operatorname{dom}(A^\ast(B\inv)^\ast)$, $k\in\mathbb{N}$. 

This shows that the likelihood is well-defined and the Bayesian procedure is applicable under mild assumptions. The likelihood is quadratic in the operator $F$, so Gaussian conjugacy is preserved (assuming a suitable Gaussian prior). The computation of the likelihood, however, requires knowledge of the operators $A$ and $B$. By adjusting the likelihood, the analysis presented in this paper transfers to the setting $A=\nu\Updelta$ and $B=\sigma\identity$ for known $\nu,\sigma^2>0$.

\subsubsection{Spatial ergodicity for more general SPDEs}\label{subsec:Generalisation2}

The analysis of the posterior distribution in the general setting \eqref{eq:SPDE_GeneralSemiLinear} is delicate. On the one hand, by following the proofs of Propositions \ref{prop:DensityBoundedDerivative} and Theorem \ref{thm:SubgaussianConcentration}, the concentration results for the averages $\int_0^T\frac{1}{\lambda} \int_{\lambda\bar{\Lambda}} g(X_t(y))\,\D y\D t$ can be generalised beyond $A=\Updelta$ and $B=\identity$, provided that there exists some $0<\alpha<1$ such that
\begin{equation*}
    \int_0^t \norm{B G_{t-s}^\lambda(y,\eta)}_{L^2(\Lambda)}^2\,\D s\sim t^{-\alpha},\quad 0\le t\le T,
\end{equation*}
for all $\lambda\ge 1$ where $G^\lambda$ is the Green function of $A$ on $\Lambda$. On the other hand, if $B\inv$ is an unbounded operator on $L^2(\Lambda)$ or $F$ is not of Nemytskii-type, the Hellinger semi-metric $h_\lambda$ no longer takes the form of an average, since 
\begin{equation*}
	h_\lambda(F,G)^2 = \frac{1}{\lambda}\int_0^T\norm{B\inv(F(X_t)-G(X_t))}_{L^2(\Lambda)}^2\,\D t.
\end{equation*}
Whereas $B\inv$ is in general a local operator and spatial ergodicity is expected, the analysis requires a precise understanding of the joint action of $B\inv$ and any candidate functions $F, G$ on $X_t$ and lies beyond the scope of this work.

\subsubsection{Small noise asymptotics}\label{subsec:Rescaling}

Suppose we observe $Y^\sigma = (Y_t(y)\,\colon \, (t,y)\in[0,T] \times\bar{\Lambda})$ solving the SPDE \eqref{eq:Y_rescaled} on a domain $\bar{\Lambda}\subset\mathbb{R}$ with known diffusivity $\nu>0$ and known noise level $\sigma>0$. Provided that $f$ is Lipschitz-continuous, the log-likelihood reads
\begin{equation*}
    \ell(f) = \frac{1}{\sigma^2}\int_0^T \iprod{F(Y_t)}{\D Y_t-\nu\Updelta Y_t}_{L^2(\bar{\Lambda})} - \frac{1}{2\sigma^2}\int_0^T \norm{F(Y_t)}_{L^2(\bar{\Lambda})}^2\,\D t.
\end{equation*}
Analogously to Subsection \ref{subsec:Bayes_Setting_Posterior}, Gaussian conjugacy holds, and the posterior distribution can be analysed in the small noise asymptotic $\sigma\to 0$ with diffusivity $\nu>0$ held constant. Using Theorem 3 of \citet{Ibragimov2003} and the proof strategy of Proposition 5.2 of \citet{vanzantenRateConvergenceMaximum2005a}, it can be shown that the appropriate limiting metric is given by
\begin{equation*}
    \int_0^T\int_{\bar{\Lambda}}\left(g(Y_t^{\operatorname{det}}(y))-\tilde{g}(Y_t^{\operatorname{det}}(y))\right)^2\,\D y\D t,\quad g,\tilde{g}\in\Theta,
\end{equation*}
where $Y^{\operatorname{det}}$ satisfies the deterministic PDE \eqref{eq:Y_rescaled} with $\sigma=0$ and $f=f_0$. Posterior contraction in this metric can be shown along the lines of Subsection 3.1 of \citet{vandermeulenConvergenceRatesPosterior2006}.


\section{The Malliavin calculus and the proof of Theorem \ref{thm:SubgaussianConcentration}}\label{sec:Proof_Subgaussian_Concentration}

The Malliavin calculus was initiated by \citet{malliavinStochasticCalculusVariation1978} to obtain a probabilistic proof of Hörmander's Theorem and has since experienced significant extensions and new areas of application. The interested reader is referred to the monographs \citet{SanzSole2005, nualartMalliavinCalculusRelated2006, bogachevDifferentiableMeasuresMalliavin2010, nualartIntroductionMalliavinCalculus2018, ikedaIntroductionMalliavinsCalculus1984, nourdinNormalApproximationsMalliavin2012, malliavinStochasticCalculusVariations2006, malliavinStochasticAnalysis1997} and references therein. Its interpretation as an \enquote{infinite-dimensional differential calculus on the Wiener space} \citep{nualartMalliavinCalculusRelated2006} makes the Malliavin calculus appealing in our setting, since we are aiming to control quantities, e.g.\ $\mathcal{G}_\lambda$, which are nonlinear transformations of the Gaussian process $(W_t)_{t\in[0,T]}$. If $X$ is the solution to the semi-linear SPDE \eqref{eq:SPDE} and $f\in C^1(\mathbb{R})$, then the Malliavin derivative $(\tau,z)\mapsto\mathcal{D}_{\tau,z}X_t(y)\in L^2([0,T],L^2(\Lambda))$ of $X_t(y)$ for any time point $0<t\le T$ and location $y\in\Lambda$ exists. It satisfies the linear PDE with random coefficients
\begin{equation}
	\begin{cases}
		\partial_t \mathcal{D}_{\tau,z} X_t(y) = \partial_y^2 \mathcal{D}_{\tau,z}X_t(y) + f'(X_t(y))\mathcal{D}_{\tau,z}X_t(y),& 0\le\tau<t\le T,\quad  z\in\Lambda\\
		\mathcal{D}_{\tau,z}X_\tau(y) = \delta_{\tau,z}(y),&z\in\Lambda,
	\end{cases}\label{eq:malliavin_derivative}
\end{equation}
and $\mathcal{D}_{\tau,z}X_t(y)=0$ for $0< t<\tau\le T$, $z,y\in\Lambda$. Assume that $g\in C^1(\mathbb{R})$. We apply the Malliavin calculus at two instances in the proof of the sub-Gaussian concentration of Theorem \ref{thm:SubgaussianConcentration}. The first instance is the well-known Clark-Ocone formula in the form given by Proposition 6.3 in \citep{chenSpatialErgodicitySPDEs2021}, which implies
	\begin{equation}
		\mathcal{G}_{\lambda} - \EV*[f]{\mathcal{G}_{\lambda}} = \mathcal{M}_T\coloneq \int_0^T \int_\Lambda \EV*[f]{\mathcal{D}_{\tau,z}\mathcal{G}_{\lambda}\given \mathscr{F}_{\tau}}\,\mathcal{W}(\D z,\D \tau),\label{eq:Clark_ocone}
	\end{equation}
	almost surely, where $(\mathscr{F}_t)_{t\ge 0}$ is the natural filtration generated by $\mathcal{W}$.
	 The stochastic integral $\mathcal{M}$ is a martingale (in time) with quadratic variation
	\begin{equation*}
		\langle \mathcal{M}\rangle_T = \int_0^T \int_\Lambda \EV[f]{\mathcal{D}_{\tau,z}\mathcal{G}_\lambda\given \mathcal{F}_\tau}^2 \,\D z\D \tau = \int_0^T\int_\Lambda \bigg(\int_\tau^T \frac{1}{\lambda}\int_\Lambda  \EV[f]{g'(X_t(y))\mathcal{D}_{\tau,z} X_t(y)\given \mathcal{F}_\tau}\,\D y\D t\bigg)^2\,\D z\D \tau.
	\end{equation*}
	This representation allows us to control deviations of $\mathcal{G}_{\lambda}$ by bounding the quadratic variation $\langle \mathcal{M}\rangle_T$ and applying a (martingale) Bernstein inequality.
	 Lemma 4.6 of \citet{gaudlitzNonparametricEstimationReaction2023} shows that $\langle \mathcal{M}\rangle_T$ can be controlled once we can bound the conditional expectation
	 \begin{equation*}
		\abs{\EV[f]{g'(X_t(y))\given \mathcal{F}_\tau}}.
	 \end{equation*}
  At this point, a second application of the Malliavin calculus allows us to control the conditional expectation via density estimates. Importantly, the subsequent bound on the derivatives of the density of $X_t(y)$ does not depend on the initial condition.
\begin{proposition}\label{prop:DensityBoundedDerivative}
    Let $X_0\in C(\Lambda)$ be any deterministic initial condition, $N\in \mathbb{N}_0$, $K>0$ and $f\in\mathcal{F}_{N+2,K}$. Then there exists a constant $0<p_{\max}^{(N)}<\infty$, depending on $T$, $K$ and $N$, such that we have for all $0\le n\le N$, $0<t\le T$ and $\lambda\ge 1$
		\begin{equation*}
			\abs{\partial_x^n p_{f,\lambda}(t,y,x)}\le p_{\max}^{(N)}t^{-(N+1)/4},\quad x\in\mathbb{R}, y\in\Lambda.
		\end{equation*}
\end{proposition}
\begin{proof}
    The proof follows the classical approach for proving the smoothness of densities using the Malliavin calculus of \citet{watanabeLecturesStochasticDifferential1984, ikedaIntroductionMalliavinsCalculus1984}, see also Section 2.1.4 of \citet{nualartMalliavinCalculusRelated2006} and Section 7.2 of \citet{nualartIntroductionMalliavinCalculus2018} for modern expositions. It is carried out in Subsection \ref{subsec:DensityDerivatives}.
\end{proof}
\begin{remark}[Assuming $f\in \mathcal{F}_{N+2,K}$]\label{rmk:OnDensity}
	Proposition \ref{prop:DensityBoundedDerivative} shows that assuming $f\in \mathcal{F}_{N+2,K}$ in Theorem \ref{thm:SubgaussianConcentration} allows us to control the derivatives of the density up to the order $N\in\mathbb{N}_0$. The gap of 2 between the regularity of $f$ and the regularity of the density is commonly found when proceeding similarly to Theorem 2.1.4 of \citet{nualartMalliavinCalculusRelated2006}, see \citep{carmonaRandomNonlinearWave1988a, milletStochasticWaveEquation1999, marquez-carrerasStochasticPartialDifferential2001, dalangPotentialTheoryHyperbolic2004, SanzSole2005, nualartExistenceSmoothnessDensity2007a, dalangHittingProbabilitiesSystems2009,  marinelliExistenceRegularityDensity2013}. The gap has been reduced by \citet{nourdinDensityFormulaConcentration2009, romitoSimpleMethodExistence2018}, but their results do not apply to our required case $N=1$. Providing a tighter connection between the regularity of $f$ and of the density poses an intricate question for future research.
\end{remark}

We proceed with the proof of the sub-Gaussian concentration for spatio-temporal averages in Theorem \ref{thm:SubgaussianConcentration} (\ref{num:SubgaussianThm2}) in three steps.
 When $g\in C^1(\mathbb{R})$, we combine the integration-by-parts formula with the bounds for $\partial_x p_{f,\lambda}(t,y,x)$ from Proposition \ref{prop:DensityBoundedDerivative} to obtain a bound for $\abs{\EV[f]{g'(X_t(y))\given \mathcal{F}_\tau}}$ in terms of $\norm{g}_{L^1(\mathbb{R})}$ in Lemma \ref{lem:Bayes_BoundConditionalExpectation}.
  Subsequently, when $g\in C^1(\mathbb{R})$ we apply Lemma 4.6 of \citet{gaudlitzNonparametricEstimationReaction2023} to obtain the claimed sub-Gaussian concentration for $\mathcal{G}_{\lambda}(g)$ in Lemma \ref{lem:General_Deviation_Control}.
   We conclude by an approximation argument for $g\in L^1(\mathbb{R})$.

\subsubsection*{Step 1: Bounding the conditional expectation}

We denote by $\mathcal{P}$ the set of all functions $\mathbb{R}\to\mathbb{R}$ that are of at most polynomial growth.
 The subsequent lemma bounds the conditional expectation $\abs{\EV[f_0]{g'(X_t(y))\given \mathcal{F}_\tau}}$ in terms of $\norm{g}_{L^1(\mathbb{R})}$ by combining the integration-by-parts formula with the bound for the derivative of the density $\partial_xp_{f,\lambda}(t,y,x)$ from Proposition \ref{prop:DensityBoundedDerivative}.
\begin{lemma}\label{lem:Bayes_BoundConditionalExpectation}
	Let $f_0\in\Theta$ and $g\in L^1(\mathbb{R})\cap C^1(\mathbb{R})\cap \mathcal{P}$. Then
	\begin{equation*}
		\abs{\EV[f_0]{g'(X_t(y))\given \mathcal{F}_\tau}}\le \norm{g}_{L^1(\mathbb{R})}p_{\max}^{(1)}(t-\tau)^{-1/2},\quad y\in\Lambda,\quad 0\le\tau<t\le T.
	\end{equation*}
\end{lemma}
\begin{proof}
	Using the Markov property of $t\mapsto X_t$ we can write
	\begin{equation*}
		\EV[f_0]{g'(X_t(y))\given \mathcal{F}_\tau}  = \EV[f_0]{g'(X_t(y))\given X_\tau} = \left.\EV[f_0]{g'(X_{t-\tau}(y))}\right|_{X_0=X_\tau}
	\end{equation*}
	Let $\xi=X_\tau$. In the next step, we rewrite the expectation on the right-hand-side as an integral with respect to the density $p_{f_0,\lambda}(s,y,\MTemptyplaceholder)$ of the process $(X_s(y)\,\vert\, y\in\Lambda, 0<s<T-\tau)$ conditioned to start at the initial condition $\xi$, which is treated as deterministic due to the conditioning.
	 Noting that the density $p_{f_0,\lambda}(s,y,\MTemptyplaceholder)$ depends on initial condition $\xi\in C(\Lambda)$, we find
	\begin{equation*}
		\EV[f_0]{g'(X_t(y))\given \mathcal{F}_\tau}=\left.\int_{\mathbb{R}} g'(x)p_{f_0,\lambda}(t-\tau,y,x) \,\D x\right|_{X_0=\xi}
	\end{equation*}
	for all $y\in\Lambda$ and $0\le\tau<t\le T$.
	 Proposition \ref{prop:DensityBoundedDerivative} with $f=f_0$ shows that $p_{f_0,\lambda}(t,y,\MTemptyplaceholder)\in C^1(\mathbb{R})$ for any deterministic and continuous initial condition.
	  Furthermore, Part \eqref{num:cordensitybounds_c} of Corollary \ref{cor:DensityBounds} (below) shows that $p_{f_0,\lambda}(t,y,\MTemptyplaceholder)$ has Gaussian tails for any deterministic initial condition.
	   Since $g'$ grows at most polynomially, we integrate by parts without boundary terms to obtain
	\begin{equation*}
		\abs{\EV[f_0]{g'(X_t(y))\given \mathcal{F}_\tau}} = \abs*{\int_{\mathbb{R}} g(x) \partial_x p_{f_0,\lambda}(t-\tau,y,x)\,\D x}.
	\end{equation*}
	Applying the $\xi$-independent upper bound for $\norm{\partial_x p_{f_0,\lambda}(t,y,\MTemptyplaceholder)}_{L^\infty(\mathbb{R})}$ from Proposition \ref{prop:DensityBoundedDerivative} with $f=f_0$, we find
	\begin{equation*}
		\abs{\EV[f_0]{g'(X_t(y))\given \mathcal{F}_\tau}}  \le \norm{g}_{L^1(\mathbb{R})}p_{\max}^{(1)}(t-\tau)^{-1/2}.
	\end{equation*}
\end{proof}

\subsubsection*{Step 2: Subgaussian concentration for $g\in C^1(\mathbb{R})$}

\begin{lemma}[Subgaussian concentration of $\mathcal{G}_{\lambda}(g)$ -- $C^1(\mathbb{R})$-version]\label{lem:General_Deviation_Control}
	Let $f_0\in \Theta$ and $g\in L^1(\mathbb{R})\cap C^1(\mathbb{R})\cap\mathcal{P}$. Then there exists a constant $C$, depending on $\norm{f_0}_{C^3(\mathbb{R})}$ and $T$, such that we can bound
	\begin{equation}
		\prob*[f_0]{\abs{\mathcal{G}_{\lambda}(g)-\EV[f_0]{\mathcal{G}_{\lambda}(g)}}\ge \lambda^{-1/2} x}\le 2\exp\bigg(-\frac{x^2}{2 C \norm{g}_{L^1(\mathbb{R})}^2}\bigg),\quad x\ge 0.\label{eq:Subgaussian_1}
	\end{equation}
\end{lemma}
\begin{proof}
	Using the Clark-Ocone formula, we can write
	\begin{equation*}
		\mathcal{G}_{\lambda}(g)-\EV[f_0]{\mathcal{G}_{\lambda}(g)}=\mathcal{M}_T\coloneq\int_0^T\int_\Lambda \EV*[f_0]{\mathcal{D}_{\tau,z}\mathcal{G}_{\lambda}(g)\given\mathcal{F}_\tau}\,\mathcal{W}(\D z,\D \tau),
	\end{equation*}
	which is a martingale in time under $\prob[f_0]{}$ evaluated at time $T$ with quadratic variation
	\begin{equation*}
		\langle \mathcal{M} \rangle_T=\frac{1}{\lambda^2}\int_0^T \int_\Lambda \bigg(\int_\tau^T \int_\Lambda \EV[f_0]{g'(X_t(y))\mathcal{D}_{\tau,z}X_t(y)\given \mathcal{F}_\tau}\,\D y\D t\bigg)^2\,\D z\D\tau.
	\end{equation*}
    The bound $\abs{\EV[f_0]{g'(X_t(y))\given \mathcal{F}_\tau}}\le \norm{g}_{L^1(\mathbb{R})}p_{\max}^{(1)}(t-\tau)^{-1/2}$ from Lemma \ref{lem:Bayes_BoundConditionalExpectation} implies that we can use Lemma 4.6 of \citet{gaudlitzNonparametricEstimationReaction2023} with $\kappa(t,\tau) = \norm{g}_{L^1(\mathbb{R})} p_{\max}^{(1)}(t-\tau)^{-1/2}$ to obtain
	\begin{align*}
		\langle \mathcal{M}\rangle_T&
        %&\le \frac{1}{\lambda^2}\int_0^T \bigg(\int_\tau^T \norm[\bigg]{\int_\Lambda \EV[f]{g'(X_t(y))\mathcal{D}_\tau  X_t(y)\given \mathcal{F}_\tau}}_{L^2(\Lambda)}\,\D t\bigg)^2\,\D \tau\\
	    %& \le \frac{1}{\lambda^2}\int_0^T \bigg(\int_\tau^T \lambda^{1/2}\bigg(\kappa(t,\tau)+e^{\Lip{f} t}\Lip{f} \int_\tau^t \EV[f]{\kappa(t,s)\given \mathcal{F}_\tau}\,\D s \bigg)\,\D t\bigg)^2\,\D\tau \\
		 \le \frac{1}{\lambda}\norm{g}_{L^1(\mathbb{R})}^2 (p_{\max}^{(1)})^2  \int_0^T \bigg(2(T-\tau)^{1/2} + e^{\Lip{f_0} T}\Lip{f_0} \frac{4}{3}(T-\tau)^{3/2}\bigg)^2\,\D\tau\\
		& = \frac{1}{\lambda}\norm{g}_{L^1(\mathbb{R})}^2 (p_{\max}^{(1)})^2 \left(2T^2 + \frac{16}{9}T^3 e^{\Lip{f_0} T}\Lip{f_0}+\frac{4}{9}T^4e^{2\Lip{f_0} T}\Lip{f_0}^2\right).
	\end{align*}
	Therefore, we can almost surely bound the quadratic variation by
	\begin{equation*}
		\langle \mathcal{M}\rangle_T \le C^2 \frac{1}{\lambda} \norm{g}_{L^1(\mathbb{R})}^2,
	\end{equation*}
	with a suitable constant $C$ depending on $T$ and $\norm{f_0}_{C^3(\mathbb{R})}$. The Bernstein inequality for continuous martingales (see page 153 of \citet{RevuzYor1999}) implies that for $x\ge 0$
	\begin{equation*}
		\prob*[f_0]{\abs{ \mathcal{G}_{\lambda}(g)-\EV[f_0]{\mathcal{G}_{\lambda}(g)}} \ge \frac{C}{\sqrt{\lambda}}  x} = \prob*[f_0]{\abs{ \mathcal{M}_T} \ge \frac{C}{\sqrt{\lambda}} x, \langle \mathcal{M}\rangle_T \le\frac{C^2}{\lambda} \norm{g}_{L^1(\mathbb{R})}^2}  \le 2\exp\bigg(-\frac{x^2}{2  \norm{g}_{L^1(\mathbb{R})}^2}\bigg).
	\end{equation*}
	This concludes the proof of the sub-Gaussian concentration inequality \eqref{eq:Subgaussian_1}.
\end{proof}

\subsubsection*{Step 3: Approximation and conclusion}

\begin{proof}[Proof of Theorem \ref{thm:SubgaussianConcentration} \eqref{num:SubgaussianThm2}]
	Let $\tilde{\mathcal{G}}_\lambda(g) =  \mathcal{G}_\lambda(g)-\EV[f_0]{\mathcal{G}_{\lambda}(g)}$. Fix any $x\ge 0$ and take an approximating sequence $(g_n)_{n\in\mathbb{N}}\subset L^1(\mathbb{R})\cap C^1(\mathbb{R})$ with compact, growing supports and $\norm{g-g_n}_{L^1(\mathbb{R})}\to 0$ as $n\to \infty$. Since the map $g\mapsto \tilde{\mathcal{G}}_{\lambda}(g)$ is linear, we obtain for all $n\in\mathbb{R}$ the bound
	\begin{align*}
		\prob[f_0]{\abs{\tilde{\mathcal{G}}_{\lambda}(g)}\ge \lambda^{-1/2} x}&=\prob[f_0]{\abs{\tilde{\mathcal{G}}_{\lambda}(g_n) - \tilde{\mathcal{G}}_{\lambda}(g_n-g)}\ge \lambda^{-1/2} x}\\
        &\le  \prob[f_0]{\abs{\tilde{\mathcal{G}}_{\lambda}(g_n)}\ge \lambda^{-1/2} x/2} + \prob[f_0]{\abs{\tilde{\mathcal{G}}_{\lambda}(g_n-g)}\ge \lambda^{-1/2} x/2}.
	\end{align*}
	Applying Lemma \ref{lem:General_Deviation_Control} to $\tilde{\mathcal{G}}_{\lambda}(g_n)$ and Markov's inequality to $\tilde{\mathcal{G}}_{\lambda}(g_n-g)$, we find
	\begin{equation*}
		\prob[f_0]{\abs{\tilde{\mathcal{G}}_{\lambda}(g)}\ge \lambda^{-1/2} x}\le 2\exp\bigg(-\frac{x^2}{4C^2\norm{g_n}_{L^1(\mathbb{R})}^2}\bigg) + 2\lambda^{1/2}\frac{\EV[f_0]{\abs{\tilde{\mathcal{G}}_{\lambda}(g_n-g)}}}{ x}.
	\end{equation*}
	The triangle inequality and the upper density bound from Part \eqref{num:cordensitybounds_a} of Corollary \ref{cor:DensityBounds} imply
	\begin{equation*}
		\EV[f_0]{\abs{\tilde{\mathcal{G}}_{\lambda}(g_n-g)}}\le \frac{2}{\lambda} \EV[f_0][][\bigg]{\int_0^T\int_\Lambda \abs*{g_n(X_t(y))-g(X_t(y))}\,\D y\D t}\lesssim_{T,\norm{f_0}_{C^3(\mathbb{R})}}\norm{g_n-g}_{L^1(\mathbb{R})}\to 0.
	\end{equation*}
    as $n\to\infty$, which shows the sub-Gaussian concentration inequality \eqref{eq:Subgaussian_2}. 
\end{proof}

\section{Proofs for Sections \ref{subsec:Posterior_Contraction} and \ref{subsec:BvM}} \label{sec:Bayes_proofContraction}

Let us first recall a few facts for the wavelet approximation spaces $V_M=\operatorname{span}(\psi_\mu\,\colon\, \abs{\mu}\leq M)$. Define the associated projection operators 
\begin{align*}
P_Mf\coloneq \sum_{\abs{\mu}\leq M}\iprod{f}{\psi_{\mu}}_{L^2(\Xi)}\psi_{\mu},\quad f\in L^2(\Xi). 
\end{align*}
Standard wavelet-theory (e.g., Proposition 4.1.5 of \citet{gineMathematicalFoundationsInfiniteDimensional2015} which also applies to the boundary-corrected Daubechies wavelets) gives for $f\in H^\beta(\Xi)$ (or $f\in C^\beta(\Xi)$) the classical wavelet (Jackson) estimates 
\begin{equation}
\norm*{f-P_Mf}_{L^2(\Xi)}\lesssim 2^{-M\beta}\norm{f}_{H^\beta(\Xi)} \quad \left(\text{ or }\norm*{f-P_Mf}_{L^\infty(\Xi)}\lesssim 2^{-M\beta}\norm{f}_{C^\beta(\Xi)}\quad\right)\label{eq:Bayes_SupNorm_Approximation}
\end{equation}
with implied constants depending on $\beta$, the wavelet basis and the domain $\Xi$. 

The proof of the posterior contraction (Theorem \ref{thm:PosteriorContraction}) proceeds using a variant of Theorem 2.1 and Lemma 2.2 of \citet{vandermeulenConvergenceRatesPosterior2006}, see also Theorem 7 of \citet{nicklNonparametricStatisticalInference2020}. It relies on the Bernstein inequality for martingales and carries over to the present setting with minor notational changes that are left to the reader. Define the metric
\begin{equation*}
    d_\lambda(f,g)^2\coloneq \EV[f_0]{h_\lambda(f,g)^2},\quad f,g\in L^\infty(\mathbb{R}),
\end{equation*}
For $f,g\in \Theta$ the upper and lower density bounds of Corollary \ref{cor:DensityBounds} imply the norm equivalence
\begin{equation}
    \tilde{c}\norm{f-g}_{L^2(\Xi)}\le d_\lambda(f,g)\le \tilde{C}\norm{f-g}_{L^2(\Xi)},\label{eq:norm_equivalence_d}
\end{equation}
where $0<\tilde{c},\tilde{C}<\infty$ are constants depending only on $\Lip{f_0}$, $T$ and $\Xi$.
\begin{theorem}[Theorem 2.1, Lemma 2.2 of \citet{vandermeulenConvergenceRatesPosterior2006}]\label{thm:TripleVan}
	Let $f_0\in \Theta$ and let $\mathfrak{B}_\lambda\subset \Theta$ be a $\lambda$-dependent parameter set. Let $\bar{\epsilon}_\lambda\to 0$ such that $\lambda\bar{\epsilon}_\lambda^2\to\infty$. Suppose that for any constants $0<\smash{\underbar{c}},\bar{c},C_1,C_2,C_3,C_4<\infty$ with $C_1-C_3\ge \max(\bar{c},C_4)$ there exist measurable sets $\mathcal{B}_\lambda\subset\mathfrak{B}_\lambda$ and $C_2,C_3>0$ such that
	\begin{align}
		 & \text{Sieve set: } \Pi_\lambda(\mathcal{B}_\lambda^c)\le e^{-C_1 \lambda\bar{\epsilon}_\lambda^2}\label{eq:Cond1}                            \\
		 & \text{Entropy bound: } \log(N(\mathcal{B}_\lambda,d_\lambda,\bar{\epsilon}_\lambda))\le C_2 \lambda\bar{\epsilon}_\lambda^2,\label{eq:Cond2}            \\
		 & \text{Small ball probability: } \Pi_\lambda(f\colon  d_\lambda(f,f_0)\le\bar{\epsilon}_\lambda)\ge e^{-C_3\lambda\bar{\epsilon}_\lambda^2}\label{eq:Cond3}, \\
		\begin{split}
			 & \lim_{\lambda\to \infty}\mathrm{P}_{f_0}\Big(\big\{\Forall f\in\mathfrak{B}_\lambda\text{ s.t. }h_\lambda(f,f_0)\ge C_4 \bar{\epsilon}_\lambda\colon \quad \smash{\underbar{c}}d_\lambda(f,f_0)\le h_\lambda (f,f_0)\big\} \\
			 & \quad\cap \big\{\Forall f,g\in\mathfrak{B}_\lambda\text{ s.t. }h_\lambda(f,g)\ge C_4 \bar{\epsilon}_\lambda\colon \quad h_\lambda(f,g)\le \bar{c} d_\lambda(f,g)\big\}\Big)=1.
		\end{split}\label{eq:Cond4}
	\end{align}
	Then, for every $K_\lambda\to\infty$,
	\begin{equation*}
		\Pi_\lambda(f\in \mathfrak{B}_\lambda\colon  h_\lambda(f,f_0)\ge K_\lambda\bar{\epsilon}_\lambda\,\vert\, X^\lambda)\xrightarrow{\prob[f_0]{}}0,\quad \lambda\to \infty.
	\end{equation*}
\end{theorem}



\begin{proof}[Proof of Theorem \ref{thm:PosteriorContraction}]
	%	Theorem 4.5 of \citep{vandervaartRatesContractionPosterior2008} implies the existence of measurable sets $B_\nu\subset V_J$ such that for $\epsilon_\lambda=(\sigma^2)^{-\alpha/(2\alpha+1)}\log{\sigma^{-2}}$\todo{get rid off $\log{}$-factors somehow? Why need $\norm{}_\infty$-norm?}
	%	\begin{enumerate}[(a)]
	%		\item $\log{N(B_\nu,\norm{}_\infty,3\epsilon_\lambda)}\le 6 C\epsilon_\lambda^2\sigma^{-2}$,
	%		\item $\bar{\Pi}_\nu(f\nin B_\nu)\le e^{-C\epsilon_\lambda^2\sigma^{-2}}$,
	%		\item $\bar{\Pi}_\nu(\norm{f-f_0}_\infty<4\epsilon_\lambda)\ge e^{-\epsilon_\lambda^2\sigma^{-2}}$.
	%	\end{enumerate}\todo{check for rescaled prior!}


	%By Remark \ref{rmk:GoodSet} we can restrict ourselves to the analysis on $\mathcal{F}_{3,r}\cap V_J$ for some large but fixed $r>0$.\todo{why?}
	We first prove posterior concentration in the Hellinger semi-metric $h_{\lambda}$ by verifying the conditions of  Theorem \ref{thm:TripleVan} with $\bar{\epsilon}_{\lambda}\coloneq L\varepsilon_{\lambda}$ and with the sets $\mathfrak{B}_\lambda=V_M$, $\mathcal{B}_{\lambda}=V_M\cap B(0,\norm{}_{H^{\beta_0}(\Xi)},L\sqrt{\lambda}\epsilon_{\lambda})$ for some large enough $L>0$. For such $L$, parts \eqref{lem:aux_rescaled_Prior_sieve}-\eqref{lem:aux_rescaled_Prior_smallball} of Lemma \ref{lem:Prior} (below) already show that conditions \eqref{eq:Cond1}-\eqref{eq:Cond3} hold, recalling the norm equivalence \eqref{eq:norm_equivalence_d}. We are therefore left with verifying condition \eqref{eq:Cond4}. To this end, the main ingredients are the approximation bound \eqref{eq:Bayes_SupNorm_Approximation} and the sub-Gaussian concentration of the Hellinger semi-metric $h_\lambda$ (Lemma \ref{lem:supremum_Control_Hellinger}). Suppose that
    \begin{equation}
        2\smash{\underbar{c}} d_\lambda(f,g)\le h_\lambda(f,g)\le \frac{1}{2}\bar{c}d_\lambda(f,g),\quad f,g\in V_M.\label{eq:Claim_Proof_Contraction}
    \end{equation}
    for some $\bar{c}>0$ and $0<\smash{\underbar{c}}<1/2$. This condition already implies the second condition in \eqref{eq:Cond4}. To prove its first condition, we note that $P_Mf_0$ is the projection of $f_0$ onto $V_M$. Since $f_0\in C^{\beta}(\Xi)$ and the frequency cut-off satisfies $2^{-M\beta}\lesssim 2^{-\beta/(2\beta+1)}\leq  \epsilon_\lambda$, we can apply the Jackson estimate \eqref{eq:Bayes_SupNorm_Approximation} to obtain $\norm{f_0-P_M f_0}_{L^\infty(\Xi)}\lesssim \norm{f_0}_{C^\beta(\Xi)}\epsilon_\lambda$. Since $h_\lambda(f_0,P_Mf_0)\le \sqrt{T}\norm{f_0-P_Mf_0}_{L^\infty(\Xi)}$, we deduce the bias bounds $h_\lambda(f_0,P_Mf_0)\le C_{T,f_0}\epsilon_\lambda$ and $d_\lambda(f_0,P_M f_0)\le C_{T,f_0}\epsilon_\lambda$ for some constant $0<C_{T,f_0}<\infty$. Consequently, for $f\in V_M$ with $h_\lambda(f,f_0)\ge C_4\epsilon_\lambda$, we have
    \begin{align*}
        \smash{\underbar{c}} d_\lambda(f,f_0)&\le \smash{\underbar{c}} d_\lambda(f,P_Mf_0) + \smash{\underbar{c}} d_\lambda(f_0,P_Mf_0)\le \frac{1}{2}h_\lambda(f,P_Mf_0) + \smash{\underbar{c}}C_{T,f_0}\epsilon_\lambda\\
        &\le \frac{1}{2}\left(h_\lambda(f,f_0) + h_\lambda(f_0,P_Mf_0)\right) + \smash{\underbar{c}} C_{T,f_0}\epsilon_\lambda\\
        &\le \frac{1}{2}\left(h_\lambda(f,f_0) + C_{T,f_0}\epsilon_\lambda\right) + C_{T,f_0}\epsilon_\lambda\\
        &\le h_\lambda(f,f_0)\left(\frac{1}{2} + \frac{C_{T,f_0}}{2C_4} + \frac{\smash{\underbar{c}}C_{T,f_0}}{C_4}\right).
    \end{align*}
    By readjusting the constant $C_4$, we find $\smash{\underbar{c}} d_\lambda(f,f_0)\le h_\lambda(f,f_0)$, as required.	The probability of the event \eqref{eq:Claim_Proof_Contraction} equals
	\begin{align*}
		 & \prob[f_0][][\bigg]{\Forall f,g\in V_M,f\neq g\colon\quad 4\smash{\underbar{c}}^2-1\le \frac{h_\lambda(f,g)^2}{d_\lambda(f,g)^2}-1 \le \frac{1}{4}\bar{c}^2 -1} \\
		 &\hspace{15em}  \ge 1-\prob[f_0][][\bigg]{\sup_{f,g\in V_M, f\neq g}\frac{\abs{h_\lambda(f,g)^2-d_\lambda(f,g)^2}}{d_\lambda(f,g)^2}>K},
	\end{align*}
	where we chose $K=\min(1-4\smash{\underbar{c}}^2,\bar{c}^2/4-1)>0$. Lemma \ref{lem:supremum_Control_Hellinger} (below) with $x=K\lambda^{1/2}/\hat{C}\ge 0$ yields 
	\begin{equation}
		\prob[f_0][][\bigg]{\forall f,g\in V_M \colon\quad 2\smash{\underbar{c}} d_\lambda(f,g)\le h_\lambda(f,g)\le \frac{1}{2}\bar{c}d_\lambda(f,g)}\le \exp\bigg(\hat{c}\operatorname{dim}(V_M) - \frac{K^2}{\lambda \hat{C}^2}\bigg)\to 0,
        \label{eq:ProofContractionGoodEvent}
	\end{equation}
    as $\lambda\to\infty$, because $\lambda^{-1/2}\sqrt{\operatorname{dim}(V_M)}\sim \lambda^{-\beta/(2\beta+1)}\to 0$. This statement verifies \eqref{eq:Cond4} and we can apply Theorem \ref{thm:TripleVan} to find posterior contraction rates in the (random) Hellinger semi-metric $h_\lambda$ such that
	\begin{equation*}
		\Pi_\lambda(f\in V_M \colon h_\lambda(f,f_0)\ge K_\lambda \epsilon_\lambda\, \vert\,  X^\lambda)\xrightarrow{\prob[f_0]{}}0
	\end{equation*}
	for every $K_\lambda\to\infty$ as $\lambda\to\infty$. To extend the posterior concentration to $d_\lambda$, we recall \eqref{eq:ProofContractionGoodEvent} and the bias bound $\max(h_\lambda(f_0,P_Mf_0),d_\lambda(f_0,P_Mf_0))\le C_{T,f_0}\epsilon_\lambda$ to obtain for any $\tilde{K}_\lambda\to\infty$ as $\lambda\to\infty$ the convergence
	\begin{align*}
		\Pi_\lambda\left(f\in V_M\colon d_\lambda(f,f_0)\ge \tilde{K}_\lambda \epsilon_\lambda\, \vert\,  X^\lambda \right)\hspace{-10em}&\\
        &\le \Pi_\lambda\bigg(f\in V_M\colon \frac{h_\lambda(f,P_M f_0)}{2\smash{\underbar{c}}} + C_{T,f_0}\epsilon_\lambda \ge \tilde{K}_\lambda \epsilon_\lambda\, \vert\,  X^\lambda \bigg) + \smallo_{\prob[f_0]{}}(1)\\
        &\le \Pi_\lambda\bigg(f\in V_M\colon \frac{h_\lambda(f,f_0) + h_\lambda(f_0,P_Mf_0)}{2\smash{\underbar{c}}} + C_{T,f_0}\epsilon_\lambda \ge \tilde{K}_\lambda \epsilon_\lambda\, \vert\,  X^\lambda \bigg) + \smallo_{\prob[f_0]{}}(1)\\
        &\le \Pi_\lambda\bigg(f\in V_M\colon \frac{h_\lambda(f,f_0) + C_{T,f_0}\epsilon_\lambda}{2\smash{\underbar{c}}} + C_{T,f_0}\epsilon_\lambda \ge \tilde{K}_\lambda \epsilon_\lambda\, \vert\,  X^\lambda \bigg) + \smallo_{\prob[f_0]{}}(1)\\
        &= \Pi_\lambda\bigg(f\in V_M\colon h_\lambda(f,f_0)\ge \Big(\tilde{K}_\lambda - C_{T,f_0} - \frac{C_{T,f_0}}{2\smash{\underbar{c}}}\Big)2\smash{\underbar{c}}\epsilon_\lambda\, \vert\,  X^\lambda \bigg) + \smallo_{\prob[f_0]{}}(1)\xrightarrow{\prob[f_0]{}} 0.
	\end{align*}
    Combining the result from the last display with the norm equivalence \eqref{eq:norm_equivalence_d} between $d$ and $\norm{}_{L^2(\Xi)}$ yields \eqref{num:PosteriorContraction_L2}.
    In the final step, we extend the posterior convergence to $\norm{}_0$. By \eqref{num:PosteriorContraction_L2} and Lemma \ref{lem:Prior} \eqref{lem:aux_rescaled_Prior_restrict}, we find that the posterior concentrates on $B(0,\norm{}_{H^{\beta_0}(\Xi)},L'')$ with probability approaching 1 for any large enough $L''$. Since $\beta_0> 3/2$, the posterior further concentrates by the Sobolev embedding on $\mathcal{F}_{1,L}$ for $L>0$ large enough. This proves \eqref{eq:Concentration_on_Lipschitzball}. Note that for $g,h\colon\mathbb{R}\to\mathbb{R}$, $h_\lambda(g,h)^2 - \norm{g-h}_0^2 = \mathcal{G}_{\lambda}( (g-h)^2)$. Corollary \ref{cor:Convergence_polynomials} (below) with $k=2$, $f=f_0$ and $h=g-\tilde{g}$ then yields
    \begin{equation*}
        \sup_{f\in \mathcal{F}_{1,L}}\abs*{d_\lambda(f,f_0) - \norm{f-f_0}_0}\le C_{L,\Lip{f_0}}\lambda^{-1/2}\le \epsilon_\lambda
    \end{equation*}
    whenever $\lambda$ is large enough. Consequently,
    \begin{equation*}
        \Pi_\lambda\left(f\colon \norm{f-f_0}_0\ge K_\lambda \epsilon_\lambda\,\vert\, X^\lambda \right) \le \Pi_\lambda\left(f\colon d_\lambda(f,f_0)\ge (\tilde{K}_\lambda+1) \epsilon_\lambda\,\vert\, X^\lambda \right) + \smallo_{\prob[f_0]{}}(1)
    \end{equation*}
    converges to zero in $\prob[f_0]{}$-probability as $\lambda\to\infty$. 
\end{proof}

\begin{lemma}\label{lem:Prior}
	For $0\leq\beta_0<\beta$ and $f_0\in H^\beta(\Xi)$ consider the Gaussian wavelet prior $\Pi_\lambda$ from \eqref{eq:Prior} on $V_M$  with cut-off $M=M_\lambda\in\mathbb{N}$ such that $2^M\sim \lambda^{1/(2\beta+1)}$. Let $\epsilon_\lambda = \lambda^{-\beta/(2\beta+1)}\log(\lambda)$ and let $0<C<\infty$ such that $2^M\le C_1 \lambda^{1/(2\beta+1)}$. Then for any large enough $L,L',L''$ and any $L'''>0$ there exist constants $0<C_1,C_2,C_3<\infty$ depending on $L,L',L''$ and $\Xi$ such that the following properties hold:
	\begin{enumerate}[(a)]
		\item\label{lem:aux_rescaled_Prior_sieve} Sieve set: $\Pi_\lambda(f\in V_M:\norm{f}_{H^{\beta_0}(\Xi)}>L\sqrt{\lambda}\varepsilon_{\lambda})\le \exp(-C_1\lambda\varepsilon^2_{\lambda})$.
		\item\label{lem:aux_rescaled_Prior_entropy} Entropy bound: $\log\left(N\left(V_M\cap B(0,\norm{}_{H^{\beta_0}(\Xi)},L\sqrt{\lambda}\varepsilon_\lambda), \norm{}_{L^2(\Xi)}, \epsilon_\lambda\right)\right)\le C_2\lambda \epsilon_\lambda^2$.
        \item\label{lem:aux_rescaled_Prior_smallball} Small ball probability: $\Pi_\lambda (f\in V_M:\norm{f-f_0}_{L^2(\Xi)}\leq L'\epsilon_\lambda)\ge \exp(-C_3\lambda\varepsilon^2_{\lambda})$.	
        \item\label{lem:aux_rescaled_Prior_restrict} Posterior regularity:
        \begin{equation*}
            \Pi_\lambda(f\in V_M: \norm{f}_{H^{\beta_0}(\Xi)}> L'',\norm{f-f_0}_{L^2(\Xi)}\leq L'''\varepsilon_{\lambda}\,\vert\, X^\lambda)\xrightarrow{\prob[f_0]{}} 0,\qquad\lambda\to\infty.
        \end{equation*} 
	\end{enumerate}
\end{lemma}
\begin{proof}
	See Section \ref{sec:Appendix_Stats}.	
\end{proof}

