\begin{lemma}\label{lem:supremum_Control_Hellinger}
	Grant Assumption \ref{assump:Parameterspace}, let $f_0\in\Theta$ and let $M\in\mathbb{N}$ be the frequency cut-off. Then
	\begin{equation}
		\prob[f_0][][\bigg]{\sup_{g,h\in V_M\colon g\neq h} \abs[\bigg]{\frac{h_\lambda(g,h)^2- d_\lambda(g,h)^2}{d_\lambda(g,h)^2}}\ge \hat{C}\lambda^{-1/2} x}\le \exp\left(\hat{c}\operatorname{dim}(V_M)-x^2/2\right),\label{eq:Bayes_Probability}
	\end{equation}
	for any $x\ge 0$, where $0<\hat{c},\hat{C}<\infty$ are absolute constants depending only on $\norm{f_0}_{C^3(\mathbb{R})}$, $T$ and $\Xi$.
\end{lemma}

