\begin{proof}[Proof of Proposition \ref{prop:Bayes_lowerBounds}]
	Since $\norm{}_{L^2(\Xi)}$ and $\norm{}_0$ are equivalent norms by \eqref{eq:norm_equivalence}, it suffices to prove the lower bound in terms of $\norm{}_{L^2(\Xi)}$. The proof follows from combining the methodology developed in Section 2.6 of \citet{Tsybakov2009} with the upper density bound of Part \eqref{num:cordensitybounds_a} of Corollary \ref{cor:DensityBounds}. For simplicity, we restrict to the case $\Xi=[0,1]$ and proceed as in Section 2.6.1 of \citet{Tsybakov2009} with the sample size $n$ replaced by the size of the domain $\lambda$. For some constant $c_0>0$ to be chosen later we can construct $N\gtrsim 2^{c_0\ceil{\lambda^{1/(2\beta+1)}}/8}$ many $\lambda$-dependent hypotheses $f_{j}$, $j=1,\dots, N$, which satisfy the following properties:
	\begin{enumerate}[(a)]
		\item $f_{j}\in \mathcal{F}_{\beta,L}\cap\Theta$ for all $j=1,\dots, N$;
		\item $\norm{f_{j}-f_{k}}_{L^2(\Xi)}\gtrsim \lambda^{-2\beta/(2\beta+1)}$ uniformly in $j\neq k$, for $\lambda$ sufficiently large;
		\item $\norm{f_{j}}_{L^2(\mathbb{R})}^2=\norm{f_{j}}_{L^2(\Xi)}^2\le c\lambda^{-2\beta/(2\beta +1)}$, $j=1,\dots, M$ for some $c>0$ not depending on $j$, or $N$.
	\end{enumerate}
	In view of Theorem 2.5 of \citet{Tsybakov2009}, it suffices to prove with respect to the Kullback-Leibler distance
	\begin{equation}
		d_{\operatorname{KL}}\left(\prob[f_{j}]{}\,\Vert\, \prob[f_{0}]{}\right)\le \lambda\tilde{C} \norm{f_{j}}_{L^2(\Xi)}^2,\quad j=1,\dots, N,\quad  \lambda\ge 1,\label{eq:Bayes_Lowerbound_Claim}
	\end{equation}
	for some constant $0<\tilde{C}<\infty$. Suppose \eqref{eq:Bayes_Lowerbound_Claim} is true. Then $d_{\operatorname{KL}}(\prob[f_{j}]{}\,\Vert\,\prob[f_{0}]{})\le c\tilde{C}\lambda^{1/(2\beta +1)}\lesssim \log(N)$
	for an appropriate choice of the constant $c$, similarly to Section 2.6.1 of \citet{Tsybakov2009}. This verifies condition (2.46) of Theorem 2.5 of \citet{Tsybakov2009} and the claimed lower bound follows. To show \eqref{eq:Bayes_Lowerbound_Claim} we apply the density bound of Part \eqref{num:cordensitybounds_a} of Corollary \ref{cor:DensityBounds} to bound
    \begin{equation*}
        \int_{0}^T \int_{\Lambda}\EV*[f_{j}]{f_{j}(X_t(y))^2}\,\D y\D t \lesssim_{T,L} \lambda \norm{f_j}_{L^2(\mathbb{R})}^2.
    \end{equation*}
    Consequently, we find for $j=1,\dots, N$
	\begin{align*}
		d_{\operatorname{KL}}\left(\prob[f_{j}]{}\,\Vert\,\prob[f_0]{}\right) & = \EV[f_{j}][][\bigg]{\operatorname{log}\bigg(\frac{\D \prob[f_{j}]{}}{\D \prob[f_0]{}}\bigg)}                                                       
		= \frac{1}{2}\int_{0}^T \int_{\Lambda}\EV*[f_{j}]{f_{j}(X_t(y))^2}\,\D y\D t  \lesssim_{T,L} \lambda\norm{f_{j}}_{L^2(\mathbb{R})}^2.
	\end{align*}\qedhere
\end{proof}

The proof of the Bernstein--von Mises Theorem \ref{thm:BvM} follows the general proof strategy of \citet{castillo2013} to show weak convergence in $H^{-\rho}(\Xi)$ by pointwise convergence of the Laplace transforms for the finite-dimensional distributions. Before proving the theorem, we state a lemma about expansion of the Laplace transform followed by a number of maximal inequalities that ensure convergence of the finite-dimensional distributions is all we need to show. Fix any $\gamma\in H^\rho(\Xi)$. For $K,\bar{K}>0$, $2^{M}\sim \lambda^{1/(2\beta_0+1)}$ and $\epsilon_{\lambda}=\lambda^{-\beta_0/(2\beta_0+1)}\log(\lambda)$ define the set
    \begin{align}
    	D_\lambda
    	 & = \Set{f\in V_M\colon  \norm{f-f_0}_{L^2(\Xi)}\leq K\epsilon_{\lambda}, \norm{f}_{H^\beta(\Xi)}\leq \bar{K}}\label{eq:D_t}
    \end{align}
    and introduce the restricted posterior 
    \begin{align}
        \Pi_\lambda^{D_\lambda}(A\,|\,X^\lambda)=\Pi_\lambda(A\cap D_\lambda\,|\,X^\lambda)/\Pi_\lambda(D_\lambda\,|\,X^\lambda),\quad A\subset C(\mathbb{R})\,\, \text{any Borel set}. \label{eq:restr_posterior}
    \end{align}
    For large enough $\bar{K}$ we find from Lemma \ref{lem:Prior} \eqref{lem:aux_rescaled_Prior_restrict} that $D_\lambda$ is asymptotically negligible under the posterior:
    \begin{align}
        \Pi_\lambda(D^c_\lambda\,|\,X^\lambda)\xrightarrow{\prob[f_0]{}} 0,\quad \lambda\to\infty.\label{eq:D_negligible}
    \end{align}

\begin{lemma}[Asymptotic expansion of the Laplace Transform]\label{lem:ExpansionLaplaceTransform}
	Grant Assumption \ref{assump:Parameterspace} and let $f_0\in\Theta$. Suppose that $2^{M}\sim \lambda^{1/(2\beta_0+1)}$ and $\epsilon_{\lambda}=\lambda^{-\beta_0/(2\beta_0+1)}\log(\lambda)$. For $\gamma\in H^{\rho}(\Xi)$, $\rho>3/2$, write $\gamma_0=\gamma/p_{f_0}$ and define the process
	\begin{align*}
		G_\lambda(\gamma) = \sqrt{\lambda}\iprod{f-f_0}{\gamma}_{L^2(\Xi)} + \sqrt{\lambda}\mathcal{G}_{\lambda}((f-f_0)P_M\gamma_0) - W_\lambda(P_M\gamma_0),\quad f\sim \Pi_\lambda(\MTemptyplaceholder\vert\, X^\lambda).
	\end{align*}
	Then the following holds for $\gamma,\bar\gamma\in H^{\rho}(\Xi)$, $u\in \mathbb{R}$:
	\begin{enumerate}[(a)]
		\item\label{num:Laplace_Metrics} There exist constants $0<C,\bar C<\infty$ depending only on $T,\Xi,K$ such that
			\begin{align*}
				\EV[\lambda][D_\lambda]{e^{u (G_\lambda(\gamma)-G_\lambda(\bar\gamma))}\given X^\lambda} \leq \frac{C}{\Pi_\lambda(D_\lambda\,|\,X^\lambda)}e^{u^2d_1(\gamma,\bar \gamma)^2/2+\abs{u}d_2(\gamma,\bar \gamma)},
			\end{align*}
			where $d_1$, $d_2$ are metrics on $H^{\rho}(\Xi)$ given by
			\begin{align}
            \begin{split}
				d_1(\gamma,\bar\gamma) &= \bar{C}\norm{P_M(\gamma_0-\bar\gamma_0)}_{\infty},\\
                d_2(\gamma,\bar\gamma) &= \bar{C}\sqrt{\lambda} \epsilon_\lambda\norm{\gamma_0-\bar\gamma_0-P_M (\gamma_0-\bar\gamma_0)}_{L^2(\Xi)}.
            \end{split}\label{eq:Metrics_d1d2}
			\end{align}

		\item\label{num:Laplace_Convergence} $\EV[\lambda][D_\lambda]{e^{u G_{\lambda}(\gamma)}\given X^\lambda}\overset{\prob[f_0]{}}{\rightarrow}e^{u^2\norm{\gamma_0}^2_{0}/2}$ as $\lambda\to\infty$.
\end{enumerate} 
\end{lemma}
\begin{proof}
	See Section \ref{sec:Appendix_Stats}.
\end{proof}

\begin{lemma}[Maximal inequalities]\label{lem:SubGaussianBounds}
	Suppose the assumptions of Lemma \ref{lem:ExpansionLaplaceTransform} hold and consider the set
	\begin{equation*}
		\mathcal{F} = \Set{g=(f-f_0)P_M\gamma_0\given f\in D_\lambda, \gamma\in H^{\rho}(\Xi), \norm{\gamma}_{H^{\rho}(\Xi)}\leq 1}.
	\end{equation*}
	Then we have for any $J\geq 1$:
	\begin{enumerate}[(a)]
		\item $\EV[f_0]{\sup_{g\in\mathcal{F}}\abs{\mathcal{G}_{\lambda}(g)}}= o(\lambda^{-1/2})$.\label{num:Maximal1}
		\item $\EV[f_0]{\sup_{\gamma\in B(0,\norm{}_{H^\rho(\Xi)},1)}\abs{\mathbb{W}(\gamma-P_J\gamma)}}\lesssim 2^{-J/2}$. \label{num:Maximal2}
		\item $\EV[\lambda][D_\lambda]{\sup_{\gamma\in B(0,\norm{}_{H^\rho(\Xi)},1)}\abs{G_\lambda(\gamma-P_J\gamma)}\given X^\lambda}\lesssim 2^{-J(\rho-1)}+\lambda^{-(\rho-3/2)/(2\beta_0+1)}$. \label{num:Maximal3}
		\item\label{num:Maximal4} $\EV[f_0]{\sup_{\gamma\in B(0,\norm{}_{H^\rho(\Xi)},1)}\abs{W_\lambda(P_M(\gamma_0-P_J\gamma_0))}}\lesssim 2^{-J/2}$.
	\end{enumerate}
\end{lemma}
\begin{proof}
	See Section \ref{sec:Appendix_Stats}.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:BvM}]~
\begin{enumerate}[(a)]
\item By a standard inequality for the total variation distance (e.g., Page 142 of \citet{Vaart1998}) and \eqref{eq:D_negligible} we have
	\begin{align}
        \operatorname{TV}\left(\Pi_\lambda(\MTemptyplaceholder|\,X^\lambda),\Pi_\lambda^{D_\lambda}(\MTemptyplaceholder|\,X^\lambda)\right)\leq 2\Pi_\lambda(D^c_\lambda\,|\,X^\lambda)\xrightarrow{\prob[f_0]{}} 0,\quad \lambda\rightarrow \infty.\label{eq:TV_convergence}
	\end{align}
    Consider for $\gamma\in H^\rho(\Xi)$ and $\gamma_0=\gamma/p_{f_0}$ the processes 
	\begin{align*}
		G_\lambda(\gamma) 
            &= \sqrt{\lambda}\iprod{f-f_0}{\gamma}_{L^2(\Xi)} + \sqrt{\lambda}\mathcal{G}_{\lambda}((f-f_0)P_M\gamma_0) - W_\lambda(P_M\gamma_0),\\
        \bar{G}_\lambda(\gamma) 
			&= \sqrt{\lambda}\iprod{f-f_0}{\gamma}_{L^2(\Xi)}  - W_\lambda(P_M\gamma_0).
	\end{align*}
	By Lemma \ref{lem:ExpansionLaplaceTransform}   \eqref{num:Laplace_Convergence} the Laplace transform of $G_\lambda(\gamma)$ with $f\sim \Pi^{D_\lambda}_\lambda(\MTemptyplaceholder|\,X^\lambda)$ converges pointwise conditionally on $X^\lambda$ in $\prob[f_0]{}$-probability to the Laplace transform of a centred normal distribution with variance $\norm{\gamma_0}^2_0=\norm{\gamma/p_{f_0}^{1/2}}^2_{L^2(\Xi)}$. This convergence transfers to the Laplace transform of $\bar G_\lambda(\gamma)$ with $f\sim \Pi_\lambda(\MTemptyplaceholder|\,X^\lambda)$ since $G_\lambda(\gamma)=\bar G_\lambda(\gamma)+\smallo_{\prob[f_0]{}}(1)$ by Lemma \ref{lem:SubGaussianBounds} \eqref{num:Maximal1}. Recall from Proposition 29 of \citet{nickl2020b} that convergence of Laplace transforms in probability is equivalent to weak convergence of the respective laws in probability. As $\bar G_\lambda(\gamma)$ is conditionally on the data Gaussian, this means that also the total variation distance between $\mathcal{L}(\bar G_\lambda(\gamma))$ and $\mathcal{L}(\mathbb{W}(\gamma))=N(0,\norm{\gamma_0}^2_0)$ converges to zero in $\prob[f_0]{}$-probability. 

    Finally, we argue that in this convergence $\bar{G}_{\lambda}(\gamma)$ can be replaced by $\sqrt{\lambda}\iprod{f-\hat f}{\gamma}_{L^2(\Xi)}$. Again, conditional Gaussianity of $\bar{G}_{\lambda}(\gamma)$ and the arguments in the proof of Theorem 2.7 of \citet{monard2019} show that the moments of $\bar G_\lambda(\gamma)$ converge conditionally on the data to the moments of $\mathcal{L}(\mathbb{W}(\gamma))$ in $\prob[f_0]{}$-probability. So, in particular,
	\begin{align}
		\sqrt{\lambda}\iprod{\hat f-f_0}{\gamma}_{L^2(\Xi)} - W_\lambda(P_M\gamma_0)=\EV[\lambda]{\bar G_\lambda(\gamma)\given X^\lambda}=\smallo_{\prob[f_0]{}}(1),\label{eq:moment_convergence}
	\end{align} 
	and thus $\sqrt{\lambda}\iprod{f-\hat f}{\gamma}_{L^2(\Xi)}=\bar G_\lambda(\gamma)+\smallo_{\prob[f_0]{}}(1)$, implying the claimed convergence in total variation distance in $\prob[f_0]{}$-probability.
	\item For an index $J\in\mathbb{N}$ to be chosen later define on $H^{\rho}(\Xi)$ the projected processes $\bar G_{\lambda,J}$ and $\mathbb{W}_J$ through $\bar G_{\lambda,J}(\gamma)=\bar G_\lambda(P_J\gamma)$ and $\mathbb{W}_J(\gamma)=\mathbb{W}(P_J\gamma)$. By the triangle inequality for the metric $\beta_{-\rho}=\beta_{H^{-\rho}(\Xi)}$ we find 
	\begin{align*}
		\beta_{-\rho}\left(\prob[][\bar G_\lambda]{}, \prob[][\mathbb{W}]{}\right) 
			& \leq \beta_{-\rho}\left(\prob[][\bar G_{\lambda,J}]{}, \prob[][\mathbb{W}_J]{}\right)
			+ \beta_{-\rho}\left(\prob[][\bar G_\lambda]{}, \prob[][\bar G_{\lambda,J}]{}\right) + \beta_{-\rho}\left(\prob[][\mathbb{W}]{}, \prob[][\mathbb{W}_J]{}\right).
	\end{align*}
	From \eqref{num:BvM_TVConvergence} we know for any fixed $\gamma\in H^\rho(\Xi)$ that $\prob[][\bar G_{\lambda,J}(\gamma)]{}$ converges weakly to $\prob[][\mathbb{W}_J(\gamma)]{}$. By linearity, the same holds true for any finite linear combination  $\gamma=\sum_{i=1}^m a_i\gamma_i$ with $\gamma_i\in V_J$, $i=1,\dots, m$, $a\in\mathbb{R}^m$, $m\in\mathbb{N}$. By the Cramér-Wold device we thus have weak convergence of the finite-dimensional distributions of $\bar G_J$. In particular, for $J$ fixed,
	\begin{align}
		\beta_{-\rho}\left(\prob[][\bar G_{\lambda,J}]{}, \prob[][\mathbb{W}_J]{}\right)\xrightarrow{\prob[f_0]{}} 0,\quad \lambda\to \infty.\label{eq:BVM_term1}
	\end{align}
	Let $\tilde{G}_\lambda$ and $\tilde{G}_{\lambda,J}$ be defined as $\bar{G}_\lambda$ and $\bar{G}_{\lambda,J}$, respectively, but with $f\sim \Pi^{D_\lambda}_\lambda(\MTemptyplaceholder|\,X^\lambda)$ instead of $f\sim \Pi_\lambda(\MTemptyplaceholder|\,X^\lambda)$. The standard inequality \eqref{eq:TV_convergence} yields $\operatorname{TV}(\prob[][\tilde G_\lambda]{}, \prob[][\tilde G_{\lambda,J}]{})=\smallo_{\prob[f_0]{}}(1)$ and $\operatorname{TV}(\prob[][\tilde G_{\lambda,J}]{}, \prob[][\bar G_{\lambda,J}]{})=\smallo_{\prob[f_0]{}}(1)$ uniformly in $J\in\mathbb{N}$. Recalling the variational characterisation of the total variation distance \eqref{eq:TV} we get
	\begin{align*}
		&\beta_{-\rho}\left(\prob[][\bar G_\lambda]{}, \prob[][\bar G_{\lambda,J}]{}\right)
			\leq\beta_{-\rho}\left(\prob[][\bar G_\lambda]{}, \prob[][\tilde G_\lambda]{}\right) + \operatorname{TV}\left(\prob[][\tilde G_\lambda]{}, \prob[][\tilde G_{\lambda,J}]{}\right) + \operatorname{TV}\left(\prob[][\tilde G_{\lambda,J}]{}, \prob[][\bar G_{\lambda,J}]{}\right)\\
			&\quad = \sup_{F\colon\Lip{F}\leq 1} \abs[\bigg]{\int_{V_M}F(\bar G_\lambda)\D\Pi^{D_\lambda}_{\lambda}(\MTemptyplaceholder|\,X^\lambda)-\int_{V_M}F(\bar G_{\lambda,J})\D\Pi^{D_\lambda}_{\lambda}(\MTemptyplaceholder|\,X^\lambda)}
            + \smallo_{\prob[f_0]{}}(1).
	\end{align*}
	Using the Lipschitz property of the functions $F$ and then applying Lemma \ref{lem:SubGaussianBounds} \eqref{num:Maximal1} and \eqref{num:Maximal3}, the first term is up to error terms uniform in $J$ upper bounded by 
	\begin{align*}
		\EV*[\lambda][D_\lambda]{\norm{\bar G_\lambda-\bar G_{\lambda,J}}_{H^{-\rho}(\Xi)}\given X^\lambda} &=\EV[\lambda][D_\lambda][\Big]{\sup_{\norm{\gamma}_{H^\rho(\Xi)}\leq 1}\abs*{\bar G_\lambda(\gamma-P_J\gamma)}\given X^\lambda}\\
        &= \EV*[\lambda][D_\lambda][\Big]{\sup_{\norm{\gamma}_{H^\rho(\Xi)}\leq 1}\abs*{G_\lambda(\gamma-P_J\gamma)}\given X^\lambda} + \smallo_{\prob[f_0]{}}(1)\\
        &= \mathcal{O}_{\prob[f_0]{}}(2^{-J/2}) + \smallo_{\prob[f_0]{}}(1).
	\end{align*}
	From this deduce
	\begin{align}
		\beta_{-\rho}\left(\prob[][\bar G_\lambda]{}, \prob[][\bar G_{\lambda,J}]{}\right)= \mathcal{O}_{\prob[f_0]{}}(2^{-J/2})+\smallo_{\prob[f_0]{}}(1).\label{eq:BVM_term2}
	\end{align}
	Finally, using Lemma \ref{lem:SubGaussianBounds} \eqref{num:Maximal2} we find that
	\begin{equation}
		\beta_{-\rho}\left(\prob[][\mathbb{W}]{}, \prob[][\mathbb{W}_J]{}\right)\leq \EV[f_0]{\norm{\mathbb{W}-\mathbb{W}_J}_{H^{-\rho}(\Xi)}}\lesssim 2^{-J/2}.\label{eq:Projection_Betadistance_GaussianPart}
	\end{equation}
	Combining this with \eqref{eq:BVM_term1}, \eqref{eq:BVM_term2} and because $J\in\mathbb{N}$ was arbitrary, we obtain in all $\beta_{-\rho}(\prob[][\bar{G}_\lambda]{}, \prob[][\mathbb{W}]{})= \smallo_{\prob[f_0]{}}(1)$ as $\lambda\to\infty$. Consequently, the (Gaussian) law of $\bar{G}_\lambda$ converges weakly in $H^{-\rho}(\Xi)$ to the law of $\mathbb{W}$. As in \eqref{num:BvM_TVConvergence} we can invoke the arguments of Theorem 2.7 of \citet{monard2019} to conclude that $\EV[\lambda]{\bar{G}_\lambda\given X^\lambda}\rightarrow 0$ in $\prob[f_0]{}$-probability relative to $H^{-\rho}(\Xi)$) and $\sqrt{\lambda}(f-\hat{f}) =\bar{G}_\lambda+\smallo_{\prob[f_0]{}}(1)$ in $H^{-\rho}(\Xi)$.
\end{enumerate}\qedhere
\end{proof}

\begin{proof}[Proof of Corollary \ref{cor:BvM_Truth}]
	We only need to prove Part \eqref{num:cor_BvM_uniform} as Part \eqref{num:cor_BvM_pointwise} is a special case. The proof of Theorem \ref{thm:BvM} \eqref{num:BvM_BetaConvergence} already argues that 
	\begin{align}
		\sqrt{\lambda}(\hat f-f_0)=W_\lambda(P_M(\MTemptyplaceholder)_0)+\EV[\lambda]{\bar G_\lambda\given X^\lambda}=W_\lambda(P_M(\MTemptyplaceholder)_0)+\smallo_{\prob[f_0]{}}(1)
	\end{align} 
	in $H^{-\rho}(\Xi)$. It therefore suffices to show that $W_\lambda(P_M(\MTemptyplaceholder)_0)$ converges to $\mathbb{W}$ in distribution in $H^{-\rho}(\Xi)$. As in \eqref{eq:Projection_Betadistance_GaussianPart} we find from Lemma \ref{lem:SubGaussianBounds} \eqref{num:Maximal4} and linearity of $W_\lambda$ that
	\begin{equation*}
		\beta_{-\rho}\left(\prob[][W_{\lambda}(P_M(\MTemptyplaceholder)_0)]{}, \prob[][W_{\lambda}(P_J(\MTemptyplaceholder)_0)]{}\right)\le \EV[f_0]{\norm{W_{\lambda}(P_M(\MTemptyplaceholder)_0)-W_{\lambda}(P_J(\MTemptyplaceholder)_0)}_{H^{-\rho}(\Xi)}}=\mathcal{O}_{\prob[f_0]{}}(2^{-J/2}).
	\end{equation*}
    By the triangle inequality for the $\beta_{-\rho}$ metric as in the proof of Theorem \ref{thm:BvM} \eqref{num:BvM_BetaConvergence} we find by Lemma \ref{lem:SubGaussianBounds} \eqref{num:Maximal2} and \eqref{num:Maximal4} for $1\leq J\leq M$ the bound
	\begin{equation*}
		\beta_{-\rho}\left(\prob[][W_{\lambda}(P_M(\MTemptyplaceholder)_0)]{}, \prob[][\mathbb{W}]{}\right)
			 \leq \beta_{-\rho}\left(\prob[][W_{\lambda}(P_J(\MTemptyplaceholder)_0)]{}, \prob[][\mathbb{W}_J]{}\right) + \mathcal{O}_{\prob[f_0]{}}(2^{-J/2}).
	\end{equation*}
	From Lemma \ref{lem:LAN} we know that $W_{\lambda}(P_J\gamma_0)$ converges in distribution to the random variable $\mathbb{W}_J(\gamma)\sim N(0,\norm{P_J\gamma_0}^2_0)$ for any fixed $\gamma\in V_m$ and $J\in\mathbb{N}$. By linearity, the same holds true for any finite linear combination of functions in $V_J$, and thus by the Cramér-Wold device $W_{\lambda}(P_J\gamma)$ converges in distribution in $H^{-\rho}(\Xi)$ to $\mathbb{W}$. From this obtain the claim.
\end{proof}

