\section{Remaining proofs for the statistical results}\label{sec:Appendix_Stats}

This section contains the remaining proofs for Lemmas \ref{lem:Prior}, \ref{lem:supremum_Control_Hellinger}, \ref{lem:ExpansionLaplaceTransform} and \ref{lem:SubGaussianBounds}.

\begin{proof}[Proof of Lemma \ref{lem:Prior}]~
\begin{enumerate}[(a)]
\item We have $\operatorname{dim}(V_M)\lesssim 2^M\lesssim \lambda^{1/(2\beta+1)}\leq\lambda\varepsilon^2_{\lambda}$. So, for $L$ large enough $\operatorname{dim}(V_M)\leq (L^2/2)\lambda\varepsilon^2_{\lambda}$. For this $L$, we find with the random variables $Z_{\mu}\overset{i.i.d.}{\sim} N(0,1)$, $|\mu|\leq M$, from \eqref{eq:Prior} that
	\begin{equation*}
		\Pi_{\lambda}(f\in V_M:\norm{f}^2_{H^{\beta_0}(\Xi)}> L^2\lambda\varepsilon^2_{\lambda})
			=\prob[][][]{\sum_{|\mu|\leq M}Z^2_{\mu}>L^2\lambda\varepsilon^2_{\lambda}}\leq\prob[][][]{\sum_{|\mu|\leq M}(Z^2_{\mu}-1)>(L^2/2)\lambda\varepsilon^2_{\lambda}},
	\end{equation*}
	where the last inequality holds since there are at most $\operatorname{dim}(V_M)$ many $Z_{\mu}$ in the sum. The random variables $Z_{\mu}^2-1$ are independent centred chi-squared random variables. A standard subexponential inequality (e.g., Equation 3.29 of \citet{gineMathematicalFoundationsInfiniteDimensional2015}) implies for the last probability the upper bound 
	\begin{align*}
		\exp\bigg(-\frac{(L^2/2)^2(\lambda\varepsilon^2_{\lambda})^2}{4\operatorname{dim}(V_M)+(L^2/2)\lambda\varepsilon^2_{\lambda}}\bigg) \leq \exp(-(L^2/10)\lambda\varepsilon^2_{\lambda}).
	\end{align*}
	\item Note $\norm{f}_{H^{\beta_0}(\Xi)}\leq 2^{M\beta_0}\norm{f}_{L^2(\Xi)}$ for $f\in V_M$. Hence, 
	\begin{align*}
		&\log\left(N\left(V_M\cap B(0,\norm{}_{H^{\beta_0}(\Xi)},L\sqrt{\lambda}\varepsilon_\lambda), \norm{}_{L^2(\Xi)}, \epsilon_\lambda\right)\right)\\
		&\hspace{10em}  \leq \log\left(N\left(B(0,\norm{}_{\mathbb{R}^{\operatorname{dim}(V_M)}},L2^{M\beta_0}\sqrt{\lambda}\varepsilon_\lambda), \norm{}_{\mathbb{R}^{\operatorname{dim}(V_M)}}, \epsilon_\lambda\right)\right)\\
		&\quad \leq \operatorname{dim}(V_M)\log(3L2^{M\beta_0}\sqrt{\lambda})\lesssim \lambda^{1/(2\beta+1)}\log(\lambda)\lesssim \lambda\epsilon_\lambda^2,
	\end{align*} 
	using a metric entropy estimate for finite-dimensional Euclidean balls (Proposition 4.3.34 of \citet{gineMathematicalFoundationsInfiniteDimensional2015}).
	\item For $f_0\in H^{\beta}(\Xi)$ we have $\norm{f_0-P_Mf_0}_{L^2(\Xi)}\lesssim 2^{-M\beta}\norm{f_0}_{H^\beta(\Xi)}\lesssim \varepsilon_{\lambda}$, so for $L'$ large enough with $C=L'/2$
	\begin{align*}
		&\Pi_\lambda (f\in V_M:\norm{f-f_0}_{L^2(\Xi)}\leq L'\epsilon_\lambda) \geq \Pi_\lambda (f\in V_M:\norm{f-P_Mf_0}_{L^2(\Xi)}\leq C\epsilon_\lambda)\\
		&\quad \geq \Pi_\lambda (f\in V_M:\norm{f-P_M f_0}_{H^{\beta_0}(\Xi)}\leq C\epsilon_\lambda)\gtrsim \Pi_{\lambda}(f\in V_M:\norm{f}_{H^{\beta_0}(\Xi)}\leq C\epsilon_\lambda),
	\end{align*}
	concluding with Corollary 2.6.18 of \citep{gineMathematicalFoundationsInfiniteDimensional2015}, noting $P_Mf_0\in V_M$ and $\norm{P_Mf_0}_{\mathbb{H}^{\lambda}}\leq \norm{f_0}_{H^{\beta}(\Xi)}$, cf. \eqref{eq:RKHS}. Using the notation from (a) and letting $Z\overset{d}{\sim} N(0,1)$, the last expression is equal to
	\begin{align*}
		&\prob[][][]{\sum_{|\mu|\leq M}Z^2_{\mu}\leq C^2\varepsilon^2_{\lambda}}\geq \prob[][][]{\operatorname{dim}(V_M)\max_{|\mu|\leq M}Z^2_{\mu}\leq C^2\varepsilon^2_{\lambda}}\\
		&\quad = \prob[][][]{\operatorname{dim}(V_M)Z^2\leq C^2\varepsilon^2_{\lambda}}^{\operatorname{dim}(V_M)}\geq \prob[][][]{|Z|\leq C'\lambda^{-1/2}}^{\operatorname{dim}(V_M)}
	\end{align*}
	for some $C'>0$, using again that $\operatorname{dim}(V_M)\lesssim \lambda\varepsilon^2_{\lambda}$. Since the standard normal density is uniformly bounded away from zero near the origin, the last probability is up to a constant lower bounded by $\lambda^{-\operatorname{dim}(V_M)/2}\gtrsim \exp(-c\lambda^{1/(2\beta+1)}\log(\lambda))=\exp(-c\lambda\varepsilon^2_{\lambda})$ for some $c>0$. Adjusting the constant for multiplicative factors yields the desired small ball lower bound.
	\item Suppose $f\in V_M$ with $\norm{f-f_0}_{L^2(\Xi)}\leq L'''\varepsilon_{\lambda}=L'''\lambda^{-\beta/(2\beta+1)}\log(\lambda)$. Then, by the triangle inequality, we have
\begin{align*}
		\norm{f}_{H^{\beta_0}(\Xi)}
			&\leq \norm{f-P_Mf_0}_{H^{\beta_0}(\Xi)} + \norm{P_Mf_0}_{H^{\beta_0}(\Xi)}\\
            &\le 2^{M\beta_0}\norm{f-P_Mf_0}_{L^2(\Xi)}+ \norm{f_0}_{H^{\beta}(\Xi)}\\
            &\leq 2^{M\beta_0}\norm{f-f_0}_{L^2(\Xi)} + 2^{M\beta_0}\norm{f_0-P_Mf_0}_{L^2(\Xi)} + \norm{f_0}_{H^{\beta}(\Xi)}\\
            &\leq 2L''' \lambda^{(\beta_0-\beta)/(2\beta+1)}\log(\lambda) + \norm{f_0}_{H^{\beta}(\Xi)},
	\end{align*}
	which is bounded by a constant uniformly in $\lambda$ for $\lambda\to\infty$ as long as $\beta>\beta_0$. This proves the claim taking $L''>\norm{f_0}_{H^\beta(\Xi)}$ large enough, depending on $L'''$.
    \end{enumerate}
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:supremum_Control_Hellinger}]
	Given the sub-Gaussian concentration of the spatio-temporal averages of Theorem \ref{thm:SubgaussianConcentration} \eqref{num:SubgaussianThm2}, the proof of Lemma \ref{lem:supremum_Control_Hellinger} can be carried out along the lines of the proof of Lemma 4 of \citet{nicklNonparametricStatisticalInference2020}. We include the proof for completeness. To this end, define $\tilde{M}\coloneq\operatorname{dim}(V_M) \lesssim 2^{M}$. For $g,h\in V_M$ we write $g = \mathbf{g}\transpose \mathbf{\Psi}$ and $h=\mathbf{h}\transpose\mathbf{\Psi}$, where $\mathbf{g},\mathbf{h}\in \mathbb{R}^{\tilde{M}}$ and $\mathbf{\Psi}=(\psi_{\mu}\,\colon\,\abs{\mu}\le M)$.\\
	\textbf{Step 1 (Rewriting the probability in \eqref{eq:Bayes_Probability}).}  Introduce the empirical Gram matrix
    \begin{equation*}
        \hat{\mathbf{G}} = \frac{1}{\lambda}\int_0^T\int_\Lambda \mathbf{\Psi}(X_t(y))\mathbf{\Psi}(X_t(y))\transpose\,\D y\D t\in\mathbb{R}^{\tilde{M}\times\tilde{M}},
    \end{equation*}
    which depends on $\lambda$ and on $f_0$ through the law of $X$. Then
	\begin{align*}
		h_\lambda(g,h)^2 & = \frac{1}{\lambda}\int_0^T\int_\Lambda \bigg(\sum_{k=1}^{\tilde{M}} (\mathbf{g}_k-\mathbf{h}_k)\mathbf{\Psi}_k(X_t(y))\bigg)^2\,\D y\D t          \\
		& = \frac{1}{\lambda}\sum_{k,j=1}^{\tilde{M}} \mathbf{g}_k\mathbf{h}_j \int_0^T\int_\Lambda \mathbf{\Psi}_k(X_t(y))\mathbf{\Psi}_j(X_t(y))\,\D y\D t \\
		& =(\mathbf{g}-\mathbf{h})\transpose \hat{\mathbf{G}}(\mathbf{g}-\mathbf{h}).
	\end{align*}
	Similarly, with the Gram matrix $\mathbf{G} = \frac{1}{\lambda}\EV[f_0]{\int_0^T\int_\Lambda \mathbf{\Psi}(X_t(y))\mathbf{\Psi}(X_t(y))\transpose\,\D y\D t}$, we find
	\begin{equation*}
		d_\lambda(g,h)^2=(\mathbf{g}-\mathbf{h})\transpose \mathbf{G}(\mathbf{g}-\mathbf{h}).
	\end{equation*}
	Thus, the probability in \eqref{eq:Bayes_Probability} equals
	\begin{equation*}
		\prob[f_0][][\bigg]{\sup_{\mathbf{g},\mathbf{h}\in \mathbb{R}^{\tilde{M}}\colon (\mathbf{g}-\mathbf{h})\transpose\mathbf{G} (\mathbf{g}-\mathbf{h})\neq 0}\abs{\frac{(\mathbf{g}-\mathbf{h})\transpose(\hat{\mathbf{G}}-\mathbf{G})(\mathbf{g}-\mathbf{h})}{(\mathbf{g}-\mathbf{h})\transpose\mathbf{G} (\mathbf{g}-\mathbf{h})}}\ge \lambda^{-1/2}\hat{C}x}.
	\end{equation*}
	Define $\mathbf{u}\coloneq \mathbf{g}-\mathbf{h}\in \mathbb{R}^{\tilde{M}}$, the $\mathbf{G}$-unit ball $\Gamma\coloneq\Set{\mathbf{u}\in\mathbb{R}^{\tilde{M}}\given \norm{\mathbf{u}}_\mathbf{G}^2\coloneq \mathbf{u}\transpose \mathbf{G} \mathbf{u}\le 1}$ and $\mathbf{M} = \hat{\mathbf{G}}-\mathbf{G}$.  Then the probability in \eqref{eq:Bayes_Probability} equals
	\begin{equation}
		\prob*[f_0]{\sup_{\mathbf{u}\in \Gamma} \mathbf{u}\transpose\mathbf{M} \mathbf{u}\ge \lambda^{-1/2} \hat{C}x}.\label{eq:Bayes_Probability_2}
	\end{equation}
	\textbf{Step 2 (Bounding the probability \eqref{eq:Bayes_Probability_2} using a $\delta$-covering).} For $\delta>0$ let $(\mathbf{u}^l)_{l=1}^{N(\delta)}$ be a minimal $\delta$-covering of $\Gamma$ in $\norm{}_{\mathbf{G}}$-distance. Denote by $\mathbf{u}^l=\mathbf{u}^l(\mathbf{u})$ the closest point in the covering to $\mathbf{u}\in\Gamma$ such that $\norm{\mathbf{u}-\mathbf{u}^l}_{\mathbf{G}}\le \delta$. We obtain the bound
	\begin{equation}
		\abs*{(\mathbf{u}-\mathbf{u}^l)\transpose\mathbf{M} (\mathbf{u}-\mathbf{u}^l)}\le  \delta^2 \sup_{\mathbf{w}\in \Gamma}\abs{\mathbf{w}\transpose \mathbf{M} \mathbf{w}},\quad \mathbf{u}\in\Gamma.\label{eq:aux_Bayes_Prob_1}
	\end{equation}
	Moreover, using the norm equivalence \eqref{eq:norm_equivalence_d}, we find for any $\mathbf{v}\in\mathbb{R}^{\tilde{M}}$ the bound
	\begin{equation*}
		\norm{\mathbf{v}}_{\mathbb{R}^{\tilde{M}}}=\norm*{\mathbf{v}\transpose \mathbf{\Psi}}_{L^2(\Xi)}\lesssim_{T,K,\Xi}  \bigg(\int_0^T\frac{1}{\lambda}\int_\Lambda\EV[f_0]{(\mathbf{v}\transpose \mathbf{\Psi}(X_t(y)))^2}\,\D y\D t\bigg)^{1/2}=\norm{\mathbf{v}}_{\mathbf{G}}.
	\end{equation*}
	Denote by $\lambda_{\max}$ the maximal eigenvalue of $\mathbf{M}$, then we find
	\begin{equation*}
		\abs{(\mathbf{u}-\mathbf{u}^l)\transpose \mathbf{M} \mathbf{u}^l}  \le \norm{\mathbf{u}-\mathbf{u}^l}_{\mathbb{R}^{\tilde{M}}}\norm{\mathbf{M} \mathbf{u}^l}_{\mathbb{R}^{\tilde{M}}}\lesssim_{T,K,\Xi} \delta \lambda_{\max}\norm{\mathbf{u}^l}_{\mathbb{R}^{\tilde{M}}} \lesssim_{T,K,\Xi}  \delta \sup_{\norm{\mathbf{v}}_{\mathbb{R}^{\tilde{M}}}\le 1}\abs{\mathbf{v}\transpose\mathbf{M} \mathbf{v}}.
	\end{equation*}
	The norm equivalence \eqref{eq:norm_equivalence_d} implies $\norm{\mathbf{v}}_{\mathbb{R}^{\tilde{M}}}^2\gtrsim_{T,K}\norm{\mathbf{v}}_{\mathbf{G}}^2$ for any $v\in\mathbb{R}^{\tilde{M}}$ and thus
	\begin{equation}
		\abs{(\mathbf{u}-\mathbf{u}^l)\transpose\mathbf{M} \mathbf{u}^l}\lesssim_{T,K,\Xi} \delta \sup_{\mathbf{w}\in\Gamma}\abs{\mathbf{w}\transpose\mathbf{M} \mathbf{w}},\quad \mathbf{u}\in\Gamma.\label{eq:aux_Bayes_Prob_2}
	\end{equation}
	Combining \eqref{eq:aux_Bayes_Prob_1} and \eqref{eq:aux_Bayes_Prob_2}, we find for any $0<\delta<1$ the bound
	\begin{equation*}
		\sup_{\mathbf{u}\in\Gamma}\abs{\mathbf{u}\transpose\mathbf{M} \mathbf{u}}\le \tilde{C}\big((\delta^2+2\delta )\sup_{\mathbf{w}\in\Gamma}\abs{\mathbf{w}\transpose \mathbf{M} \mathbf{w}} + \max_{1\le l\le N(\delta)}\abs{(\mathbf{u}^l)\transpose \mathbf{M} \mathbf{u}^l}\big),
	\end{equation*}
	where the constant $\tilde{C}$ depends on $K$, $T$ and $\Xi$. Fixing any $\delta$ small enough such that $\tilde{C}(\delta^2+2\delta)\le 1/2$, we obtain
	\begin{equation*}
		\sup_{\mathbf{u}\in\Gamma}\abs{\mathbf{u}\transpose \mathbf{M} \mathbf{u}}\le 2 \tilde{C}\max_{1\le l\le N(\delta)}\abs{(\mathbf{u}^l)\transpose \mathbf{M} \mathbf{u}^l}.
	\end{equation*}
	The union bound implies that the probability \eqref{eq:Bayes_Probability_2} is bounded by
	\begin{equation*}
		N(\delta)\sup_{\mathbf{u}\in \Gamma}\prob*[f_0]{\abs{\mathbf{u}\transpose\mathbf{M} \mathbf{u}}\ge \sigma Cx/(2\tilde{C})}.
	\end{equation*}
	\textbf{Step 3 (Conclusion).} Introduce for $\mathbf{u}\in\mathbb{R}^{\tilde{M}}$ the function $u=\mathbf{u}\transpose \mathbf{\Psi}$ and note that
	\begin{equation*}
		\mathbf{u}\transpose \mathbf{M} \mathbf{u} = \int_0^T\frac{1}{\lambda}\int_\Lambda u(X_t(y))^2\,\D y\D t - \EV[f_0][][\bigg]{\int_0^T\frac{1}{\lambda}\int_\Lambda u(Z_t(y))^2\,\D y\D t} = \mathcal{G}_{\lambda}(u^2),
	\end{equation*}
	we can apply Theorem \ref{thm:SubgaussianConcentration} \eqref{num:SubgaussianThm2} to find
	\begin{equation*}
		\prob*[f_0]{\abs{\mathbf{u}\transpose \mathbf{M} \mathbf{u}} \ge \lambda^{-1/2} \hat{C}x/(2\tilde{C})}\le 2\exp\left(-\frac{x^2\hat{C}^2}{8C^2\tilde{C}^2\norm{u}_{L^2(\mathbb{R})}^4}\right),\quad \mathbf{u}\in\Gamma, x\ge 0,
	\end{equation*}
	with $\norm{\mathbf{u}}_{\mathbb{R}^{\tilde{M}}}=\norm{u}_{L^2(\mathbb{R})}\lesssim_{T,K,\Xi} \norm{\mathbf{u}}_{\mathbf{G}}\le 1$ by the norm equivalence \eqref{eq:norm_equivalence_d}. Since we have $\norm{}_{\mathbb{R}^{\tilde{M}}}\lesssim_{T,K,\Xi} \norm{}_{\mathbf{G}}\lesssim_{T,K}\norm{}_{\mathbb{R}^{\tilde{M}}}$ and $\delta$ is fixed, the covering number $N(\delta)$ satisfies $N(\delta)\le e^{\hat{c} \tilde{M}}$ for some constant $\hat{c}<\infty$ depending on $K$, $T$ and $\Xi$. Consequently, we find
	\begin{equation*}
		\prob[f_0][][\bigg]{\sup_{g,h\in V_M\colon g\neq h} \abs[\bigg]{\frac{h_\lambda(g,h)^2- d_\lambda(g,h)^2}{d_\lambda(g,h)^2}}\ge \lambda^{-1/2} \hat{C}x} \le N(\delta)2\exp\left(-\frac{x^2\hat{C}^2}{8C_{T,K}^2\tilde{C}^2}\right) \le 2\exp\left(c\tilde{M} - \frac{x^2\hat{C}^2}{8C^2\tilde{C}^2}\right).
	\end{equation*}
	Readjusting the constant $\hat{C}$ completes the proof.
\end{proof}


\begin{proof}[Proof of Lemma \ref{lem:ExpansionLaplaceTransform}]~
\begin{enumerate}[(a)]
\item Let $Z_{\lambda} \coloneq \int_{D_\lambda}e^{\ell_\lambda(f)}\D\Pi_{\lambda}(f)= \Pi_\lambda(D_\lambda)$ and write $\tilde{\gamma}=P_M\gamma_0\in V_M$, $g=f-u\lambda^{-1/2} \tilde{\gamma}$. Note that 
    \begin{align*}
        \sqrt{\lambda}\mathcal{G}_\lambda((f-f_0)\tilde{\gamma}) = \frac{1}{\sqrt{\lambda}} \int_0^T \iprod{(f-f_0)(X_t)}{\tilde{\gamma}(X_t)}_{L^2(\Lambda)} - \sqrt{\lambda}\iprod{f-f_0}{\tilde{\gamma}}_0.
    \end{align*}
    We thus find from the LAN-expansion (Lemma \ref{lem:LAN}) under $\prob[f_0]{}$ that $\ell_\lambda(f)-\ell_\lambda(g)$ equals
	\begin{align*}
			& u W_{\lambda}(\tilde{\gamma}) + \frac{u^2}{2}\mathcal{I}_\lambda(\tilde{\gamma}) -\frac{u}{\sqrt{\lambda}} \int_0^T \iprod{(f-f_0)(X_t)}{\tilde{\gamma}(X_t)}_{L^2(\Lambda)}\,\D t\\
			&\hspace{10em}=u W_{\lambda}(\tilde{\gamma}) + \frac{u^2}{2}\mathcal{I}_\lambda(\tilde{\gamma}) -u\sqrt{\lambda} \mathcal{G}_{\lambda}((f-f_0)\tilde{\gamma}) - u\sqrt{\lambda}\iprod{f-f_0}{\tilde{\gamma}}_0.
	\end{align*}
	With this and $$r_{\lambda}\coloneq\norm{p_{f_0}}_{L^\infty(\Xi)}\abs{u}\sqrt{\lambda} K\epsilon_\lambda\norm{\gamma_0-\tilde{\gamma}}_{L^2(\Xi)}$$ we get
	\begin{align}
		\EV[\lambda][D_\lambda]{e^{uG_\lambda(\gamma)}\given X^\lambda} 
			& =Z_\lambda^{-1}\int_{D_\lambda}e^{uG_\lambda(\gamma)+\ell_\lambda(f)}\,\D \Pi_\lambda(f)\nonumber\\
			&=Z_\lambda^{-1}\int_{D_\lambda}e^{\frac{u^2}{2}\mathcal{I}_\lambda(\tilde{\gamma}) +u\sqrt{\lambda} \iprod{f-f_0}{\gamma_0-\tilde{\gamma}}_0+\ell_\lambda(g)}\,\D \Pi_\lambda(f)\nonumber\\
			& \leq e^{\frac{u^2}{2}\mathcal{I}_\lambda(\tilde{\gamma})+r_{\lambda}} Z_\lambda^{-1}\int_{D_\lambda}e^{\ell_\lambda(g)}\,\D \Pi_\lambda(f).\label{eq:LaplaceTransformUpperBound_1}
	\end{align}
    Set $D_{\lambda,u}\coloneq \Set{g=f-u\lambda^{-1/2} \tilde{\gamma}\given f\in D_\lambda}\subset V_M$ and let $\Pi_{\lambda,u}$ be the law of $f-u\lambda^{-1/2} \tilde{\gamma}$ under the rescaled prior. Recalling the RKHS norm $\norm{h}_{\mathbb{H}^\lambda}= \norm{h}_{H^{\beta_0}(\Xi)}$, $h\in V_M$, from \eqref{eq:RKHS} the Cameron-Martin theorem \citep[Theorem 2.6.13]{gineMathematicalFoundationsInfiniteDimensional2015} implies
	\begin{align*}
		\int_{D_{\lambda}}e^{\ell_{\lambda}(g)}\D \Pi_{\lambda}(f)
		 & = \int_{D_{\lambda,u}}e^{\ell_{\lambda}(g)}\D \Pi_{\lambda,u}(g) = \int_{D_{\lambda,u}}e^{\ell_{\lambda}(g)}\frac{\D \Pi_{\lambda,u}}{\D \Pi_\lambda}(g)\,\D \Pi_{\lambda}(g)                        \\
		 & = \int_{D_{\lambda,u}}e^{\ell_\lambda(g)}\exp{\left(-u\lambda^{-1/2}\iprod{\tilde{\gamma}}{g}_{H^{\beta_0}(\Xi)}-\frac{u^2}{2\lambda}\norm{\tilde{\gamma}}_{H^{\beta_0}(\Xi)}^2\right)}\,\D\Pi_\lambda(g).
	\end{align*}
    For $g\in D_{\lambda,u}$ and $f\in D_\lambda$ we have $f=P_Mf$ and $\norm{P_M(f-f_0)}_{H^{\beta_0}(\Xi)}\leq 2^{M\beta_0}\norm{f-f_0}_{L^2(\Xi)}\leq K 2^{M\beta_0}\epsilon_\lambda\lesssim \log(\lambda)$, so
	\begin{align}
		\norm{g}_{H^{\beta_0}(\Xi)} \lesssim \log(\lambda) + \norm{f_0}_{H^{\beta_0}(\Xi)} + \abs{u}\lambda^{-1/2}\norm{\tilde\gamma}_{H^{\beta_0}(\Xi)}.\label{eq:g_upper}
	\end{align}
    We thus have for a constant $c$ depending on $f_0$ and $K$
	\begin{align*}
		&\abs*{-u\lambda^{-1/2}\iprod{\tilde{\gamma}}{g}_{H^{\beta_0}(\Xi)}-\frac{u^2}{2\lambda}\norm{\tilde{\gamma}}_{H^{\beta_0}(\Xi)}^2} \\
        &\quad \leq c\left(u^2\lambda^{-1}\norm{\tilde{\gamma}}^2_{H^{\beta_0}(\Xi)} + \abs{u}\lambda^{-1/2}\log(\lambda)\norm{\tilde{\gamma}}_{H^{\beta_0}(\Xi)}\right)=\colon \bar{r}_{\lambda},
	\end{align*}
	hence 
	\begin{align*}
		Z_\lambda^{-1}\int_{D_\lambda}e^{\ell_\lambda(g)}\,\D \Pi_\lambda(g) 
		&\leq e^{\bar{r}_\lambda}Z_\lambda^{-1}\int_{D_{\lambda,u}}e^{\ell_\lambda(g)}\,\D \Pi_\lambda(g)
		=e^{\bar{r}_\lambda} \frac{\Pi_\lambda(D_{\lambda,u}\,|\,X^\lambda)}{\Pi_\lambda(D_{\lambda}\,|\,X^\lambda)}.
	\end{align*}	
	Combining this with \eqref{eq:LaplaceTransformUpperBound_1} we have shown
	\begin{align}
		\EV*[\lambda][D_\lambda]{e^{uG_\lambda(\gamma)}\given X^\lambda} \leq \frac{e^{\frac{u^2}{2}\mathcal{I}_\lambda(\tilde{\gamma})+r_\lambda+\bar r_\lambda}}{\Pi_\lambda(D_{\lambda}\,|\,X^\lambda)}. \label{eq:LaplaceTransformUpperBound}
	\end{align}	
	To obtain the result for $\bar\gamma=0$, use the basic inequality $a\leq a^2+1$ for $a\geq 0$ such that $\bar{r}_\lambda\leq c(2u^2\lambda^{-1}\log(\lambda)^2\norm{\tilde\gamma}^2_{H^{\beta_0}(\Xi)}+1)$, as well as the relations $\norm{\tilde{\gamma}}_{H^{\beta_0}(\Xi)}\leq 2^{M\beta_0}\norm{\tilde\gamma}_{L^2(\Xi)}\lesssim \norm{p^{-1}_{f_0}}_{L^\infty(\Xi)}2^{M\beta_0}\norm{\gamma}_{L^\infty(\Xi)}$ and $\lambda^{-1/2}2^{M\beta_0}\log(\lambda) =\lambda^{-(1/2)/(2\beta_0+1)}\log(\lambda)=o(1)$. The result for general $\bar\gamma$ follows by linearity of $g\mapsto G_\lambda(g)$.
\item The proof of \eqref{eq:LaplaceTransformUpperBound} also shows
	\begin{align*}
		\EV[\lambda][D_\lambda]{e^{uG_\lambda(\gamma)}\given X^\lambda} \geq e^{\frac{u^2}{2}\mathcal{I}_\lambda(\tilde\gamma)-r_\lambda-\bar r_\lambda}\frac{\Pi_\lambda(D_{\lambda,u}\,|\,X^\lambda)}{\Pi_\lambda(D_{\lambda}\,|\,X^\lambda)}.	
	\end{align*}	
	Since $p_{f_0}\in C^1(\Xi)$ by Proposition \ref{prop:DensityBoundedDerivative} and because $p_{f_0}$ is bounded away from zero on $\Xi$, it follows that $1/p_{f_0}$ induces a bounded multiplication operator on $C^1(\Xi)$, hence $\norm{\gamma_0}_{C^1(\Xi)}\lesssim \norm{\gamma}_{C^1(\Xi)}$. The Sobolev embedding yields \begin{align}
	    \norm{\gamma_0}_{C^1(\Xi)}\lesssim \norm{\gamma}_{H^\rho(\Xi)}.\label{eq:gamma0_bound}
	\end{align}
    The wavelet Jackson estimates \eqref{eq:Bayes_SupNorm_Approximation} thus imply $\norm{\gamma_0-P_M\gamma_0}_{L^\infty(\Xi)}\lesssim 2^{-M}$. Moreover, $\norm{\tilde\gamma}_{H^1(\Xi)}\leq \norm{\gamma_0}_{H^1(\Xi)}\lesssim_{\Xi} \norm{\gamma_0}_{C^1(\Xi)}$, so with $\beta_0>3/2$
    \begin{align}
        \norm{\tilde\gamma}_{H^{\beta_0}(\Xi)}\leq 2^{M(\beta_0-1)}\norm{\tilde\gamma}_{H^{1}(\Xi)}\lesssim_{\Xi} 2^{M(\beta_0-1)}\norm{\gamma_0}_{C^1(\Xi)}.\label{eq:projected_gamma_norm}
    \end{align}
    Since $\lambda^{-1/2}2^{M\beta_0}\log(\lambda) =\sqrt{\lambda}\epsilon_{\lambda}2^{-M}=\lambda^{-(1/2)/(2\beta_0+1)}\log(\lambda)=o(1)$, this means $r_\lambda,\bar{r}_\lambda\rightarrow 0$  as $\lambda\rightarrow\infty$, such that
    \begin{align*}
		\frac{\EV[\lambda][D_\lambda]{e^{uG_\lambda(\gamma)}\given X^\lambda}}{e^{\frac{u^2}{2}\mathcal{I}_\lambda(\tilde\gamma)}\frac{\Pi_\lambda(D_{\lambda,u}\,|\,X^\lambda)}{\Pi_\lambda(D_{\lambda}\,|\,X^\lambda)}}\overset{\prob[f_0]{}}{\rightarrow}1.	
	\end{align*}
    We proceed by studying the denominator in the last display. Since $\gamma_0$ is supported on $\Xi$ and is Lipschitz-continuous as a function on $\Xi$, by the Kirszbraun extension theorem (Exercise 3.6.14 of \citet{gineMathematicalFoundationsInfiniteDimensional2015}) $\gamma_0$ extends to a Lipschitz-continuous function on $\mathbb{R}$ with the same Lipschitz constant. We can therefore apply Lemma \ref{lem:LAN} to show that $\mathcal{I}_\lambda(\gamma_0)\rightarrow \norm{\gamma_0}^2_{0}$ in $\prob[f_0]{}$-probability. Since also 
    \begin{equation*}
        \abs{\mathcal{I}_{\lambda}(\tilde\gamma)-\mathcal{I}_{\lambda}(\gamma_0)}\leq T\norm{\gamma_0-\tilde\gamma}_{\infty}(\norm{\gamma_0}_{\infty}+\norm{\tilde\gamma}_{\infty})\rightarrow 0,
    \end{equation*}
    we conclude $\mathcal{I}_\lambda(\tilde\gamma)\rightarrow \norm{\gamma_0}^2_{0}$ in $\prob[f_0]{}$-probability. By \eqref{eq:D_negligible} the claimed convergence in \eqref{num:Laplace_Convergence} follows if we can show $\Pi_\lambda(D^c_{\lambda,u}\,|\,X^{\lambda})=\smallo_{\prob[f_0]{}}(1)$. By conditioning on the data and using Lemma \ref{lem:Prior} \eqref{lem:aux_rescaled_Prior_restrict} together with the posterior contraction from Theorem \ref{thm:PosteriorContraction} we only have to argue that $D_{\lambda,u}\subset B(0,\norm{}_{H^{\beta_0}(\Xi)},L)$ for a large enough radius $L>0$ (depending on $u$). But this follows already from \eqref{eq:g_upper}, since by \eqref{eq:projected_gamma_norm}, $\lambda^{-1/2}\norm{\tilde\gamma}_{H^{\beta_0}(\Xi)}\lesssim \lambda^{-1/2}2^{M(\beta_0-1)}=o(1)$.
    \end{enumerate}\qedhere
\end{proof}

Recall from Definition 2.3.5 of \citet{gineMathematicalFoundationsInfiniteDimensional2015} that a centred process $Z=(Z(f)\colon f\in\mathcal{F})$ for an index set $\mathcal{F}$ with pseudo-distance $d$ is sub-Gaussian if its increments are sub-Gaussian, i.e.
\begin{align*}
    \prob{\abs{Z(f)-Z(g)}\geq x} \leq 2\exp{\left(-\frac{x^2}{2d^2(f,g)}\right)},\quad x>0,\quad f,g\in\mathcal{F}.
 \end{align*}
The next lemma is a basic deviation inequality for $Z$ uniformly over $\mathcal{F}$ and follows from standard sub-Gaussian calculus (see e.g., Chapter 2.3 of \citet{gineMathematicalFoundationsInfiniteDimensional2015}, and also Lemma 1 in \citet{nicklNonparametricStatisticalInference2020}). 

\begin{lemma}\label{lem:UniformSubgaussianConcentration}
	Let $(Z(f):f\in \mathcal{F})$ be a sub-Gaussian process with a pseudo-distance $d$. Denote by $\operatorname{diam}(\mathcal{F})=\sup_{f,g\in\mathcal{F}}d(f,g)$ the $d$-diameter of $\mathcal{F}$ and let
	\begin{equation*}
		J_{\mathcal{F}}\coloneq \int_0^{\operatorname{diam}(\mathcal{F})}\sqrt{\log{2N(\mathcal{F},6d,\tau)}},\,\D\tau<\infty
	\end{equation*}
    be the Dudley entropy integral, where $N(\mathcal{F},6d,\tau)$ denotes the covering number of the set $\mathcal{F}$ by $d$-balls of radius $\tau/6$. Then we have $\EV{\sup_{f\in\mathcal{F}}\abs{Z(f)}}\leq 4\sqrt{2}J_{\mathcal{F}}$ and
	\begin{align*}
		\prob*{\sup_{f\in\mathcal{F}}\abs{Z(f)}\geq 4\sqrt{2}J_{\mathcal{F}}+196J_{\mathcal{F}}x}\leq e^{-x^2/2}.
	\end{align*}
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lem:SubGaussianBounds}]~
\begin{enumerate}[(a)]
\item Fix any $g\in\mathcal{F}$. Since $g$ is supported on $\Xi$, by Theorem \ref{thm:SubgaussianConcentration} \eqref{num:SubgaussianThm2} and linearity of $\gamma\mapsto \mathcal{G}_\lambda(\gamma)$, $\sqrt{\lambda}(\mathcal{G}_{\lambda}(g)-\EV[f_0]{\mathcal{G}_\lambda(g)})$ has sub-Gaussian increments with respect to $\norm{}_{L^1(\Xi)}$. Moreover, $g$ is supported on $\Xi$ and thus globally Lipschitz-continuous. This allows us to apply Lemma \ref{lem:UniformSubgaussianConcentration} and Theorem \ref{thm:SubgaussianConcentration} \eqref{num:SubgaussianThm3} to obtain
    \begin{equation} 
        \EV[f_0]{\sup_{g\in\mathcal{F}}\abs{\mathcal{G}_{\lambda}(g)}} \leq \EV[f_0]{\sup_{g\in\mathcal{F}}\abs{\mathcal{G}_{\lambda}(g)-\EV[f_0]{\mathcal{G}_{\lambda}(g)}}}+\sup_{g\in\mathcal{F}}\abs{\EV[f_0]{\mathcal{G}_{\lambda}(g)}}\lesssim \lambda^{-1/2}J_{\mathcal{F}} + \lambda^{-1}\sup_{g\in\mathcal{F}}\norm{g}_{C^1(\Xi)}.\label{eq:Maximal_aux1}
    \end{equation}
    We proceed by bounding these two summands. We have $\gamma\in H^{\rho'}(\Xi)$ for $3/2<\rho'<3/2+\varepsilon$ for any small enough $\varepsilon>0$. Using the Sobolev embedding and \eqref{eq:projected_gamma_norm} with $\rho'$ instead of $\beta$ for $\gamma\in H^{\rho'}(\Xi)$ we find $\norm{P_M\gamma_0}_{C^1(\Xi)}\lesssim 2^{M(\rho'-1)}$. This means for $g\in\mathcal{F}$
    \begin{align}
		\norm{g}_{C^1(\Xi)} 
            &\leq \norm{f-f_0}_{C^1(\Xi)}\norm{P_M\gamma_0}_{C^1(\Xi)}\lesssim 2^{M(\rho'-1)}\norm{f-f_0}_{H^{\rho'}(\Xi)}\nonumber\\
            &\leq 2^{M(\rho'-1)} \norm{P_M(f-f_0)}_{H^{\rho'}(\Xi)} + 2^{M(\rho'-1)}\norm{f_0-P_Mf_0}_{H^{\rho'}(\Xi)}\nonumber \\
            &\leq 2^{M(2\rho'-1)} \norm{f-f_0}_{L^2(\Xi)} + 2^{-M(\beta-2\rho'+1)}\nonumber \\
            &\lesssim 2^{M(2\rho'-1)}\varepsilon_\lambda + 2^{-M(\beta-2\rho'+1)} \lesssim \lambda^{-(\beta_0-2\rho'+1)/(2\beta_0+1)},\label{eq:lipschitz_g}
	\end{align}
    such that $\mathcal{F}$ is contained in a $C^1(\Xi)$-ball of radius $\Gamma\coloneq C\lambda^{-(\beta_0-2\rho'+1)/(2\beta_0+1)}$ for some constant $C>0$. We obtain from Corollary 4.3.38 of \citet{gineMathematicalFoundationsInfiniteDimensional2015} for any $\epsilon>0$ the metric entropy estimate
	\begin{align*}
		N(\mathcal{F}, \norm{}_{L^1(\Xi)}, \epsilon) \lesssim N(B(0,\norm{}_{C^1(\Xi)},\Gamma),\norm{}_{L^1(\Xi)},\epsilon)\lesssim \exp{(\Gamma/\epsilon)}.
	\end{align*}
    Moreover, we find that $\mathcal{F}$ has $\norm{}_{L^1(\Xi)}$-diameter 
	\begin{align*}
		\sup_{g,\bar{g}\in\mathcal{F}}\norm{g-\bar{g}}_{L^1(\Xi)}&\leq 2\sup_{g\in\mathcal{F}}\norm{g}_{L^1(\Xi)}\lesssim \sup_{f\in D_{\lambda}}\norm{f-f_0}_{L^2(\Xi)}\norm{P_M\gamma_0}_{L^\infty(\Xi)}
        \leq 2^{M(\rho'-1)}\epsilon_\lambda,
	\end{align*}
	so the Dudley entropy integral in Lemma \ref{lem:UniformSubgaussianConcentration} satisfies 
	\begin{align}
    \begin{split}
		J_{\mathcal{F}} &\lesssim \int_0^{\Gamma 2^{-M\rho'}}\sqrt{\log (2) + \Gamma/\epsilon}\,\D\epsilon \lesssim \Gamma 2^{-M\rho'/2}.
    \end{split}\label{eq:Dudley_Integral}
	\end{align} 
	Combining this bound with \eqref{eq:Maximal_aux1} and \eqref{eq:lipschitz_g} gives 
	\begin{align*}
		\EV[f_0]{\sup_{g\in\mathcal{F}}\abs{\mathcal{G}_{\lambda}(g)}} \lesssim \lambda^{-1/2}\Gamma 2^{-M\rho'/2} + \lambda^{-1}\Gamma = \lambda^{-1/2}(\lambda^{-\frac{\beta_0+1-3\rho'/2}{2\beta_0+1}} + \lambda^{-\frac{2\beta_0+3/2-2\rho'}{2\beta_0+1}}).
	\end{align*}
	The claimed maximal inequality follows for $\beta_0>3/2$ from taking $\varepsilon$ sufficiently small.
\item Fix any $\gamma\in B(0,\norm{}_{H^\rho(\Xi)},1)$. We have $\EV{e^{u\mathbb{W}(\gamma)}} = e^{u^2\norm{\gamma_0}_0^2/2}\leq e^{u^2c\norm{\gamma}_{L^\infty(\Xi)}^2/2}$ for any $u\in\mathbb{R}$ and a constant $c>0$ depending on $p_{f_0}$. In particular, $\mathbb{W}$ is sub-Gaussian on $\bar{\mathcal{F}}_{J}=\Set{h-P_Jh\,\colon\, h\in H^{\rho}(\Xi),\norm{h}_{H^{\rho}(\Xi)}\leq 1}$, $J\geq 1$, relative to $\norm{}_{L^{\infty}(\Xi)}$, and by the Jackson estimate \eqref{eq:Bayes_SupNorm_Approximation} and the Sobolev embedding $\bar{\mathcal{F}}_J$ has $\norm{}_{L^{\infty}(\Xi)}$-diameter 
	\begin{align}
		\sup_{\gamma,\bar\gamma\in B(0,\norm{}_{H^{\rho}(\Xi)},1)}\norm{\gamma-\bar\gamma-P_J(\gamma-\bar\gamma)}_{L^{\infty}(\Xi)}\lesssim 2^{-J}\norm{\gamma-\bar\gamma}_{C^1(\Xi)}\lesssim  2^{-J}.\label{eq:diameter_bound}
	\end{align}
	By another application of the Sobolev embedding and $\rho>3/2$, $\bar{\mathcal{F}}_{J}$ is contained in a $C^{1}(\Xi)$-ball of radius $C$ for some $C>0$. Consequently, using again Corollary 4.3.38 of \citet{gineMathematicalFoundationsInfiniteDimensional2015} we get
    \begin{align}
        N(\bar{\mathcal{F}}_J, \norm{}_{L^\infty(\Xi)}, \epsilon) \lesssim N(B(0,\norm{}_{C^{1}(\Xi)},C), \norm{}_{L^\infty(\Xi)}, \epsilon) \lesssim \exp{(C/\varepsilon)}.\label{eq:sub_entropy}
    \end{align}
    The claim follows from Lemma \ref{lem:UniformSubgaussianConcentration}, noting similar to \eqref{eq:Dudley_Integral} that the Dudley entropy integral satisfies $J_{\bar{\mathcal{F}}_{J}}\lesssim 2^{-J/2}$.
\item We use the notation from Lemma \ref{lem:ExpansionLaplaceTransform} and write $\sigma_1=d_1(\gamma,\bar \gamma)$, $\sigma_2=d_2(\gamma,\bar \gamma)$. Lemma \ref{lem:ExpansionLaplaceTransform} \eqref{num:Laplace_Metrics} and \eqref{eq:D_negligible} show for a random variable $0<C_\lambda<\infty$ satisfying $C_\lambda\rightarrow 1$ in $\prob[f_0]{}$-probability that
	\begin{align*}
		\EV[\lambda][D_\lambda]{e^{u (G_\lambda(\gamma)-G_\lambda(\bar\gamma))}\given X^\lambda} \leq C_\lambda e^{u^2\sigma_1^2/2+\abs{u}\sigma_2}.
	\end{align*}
	By the exponential Markov inequality, this gives for any $x>0$, $u\in\mathbb{R}$ the deviation inequality
	\begin{align*}
		\Pi^{D_\lambda}_{\lambda}\left(\abs{G_\lambda(\gamma)-G_\lambda(\bar\gamma)}\geq x\,\Big\vert\, X^\lambda\right) \leq 2C_{\lambda}e^{u^2\sigma^2_1/2+\abs{u}\sigma_2-ux}.
	\end{align*}
	Applying this to $u=x/(\sigma_1^2+\sigma_2x)$ implies 
	\begin{align*}
		\Pi^{D_\lambda}_{\lambda}\left(\abs{G_\lambda(\gamma)-G_\lambda(\bar\gamma)}\geq x\,\Big\vert\, X^\lambda\right) \leq 2eC_{\lambda}e^{-x^2/(2(\sigma_1^2+\sigma_2x))}, 
	\end{align*}
	which in turn gives for $z>0$
	\begin{align}
		\Pi^{D_\lambda}_{\lambda}\left(\abs{G_\lambda(\gamma)-G_\lambda(\bar\gamma)}\geq \sigma_1\sqrt{2z}+2\sigma_2z\,\Big\vert\, X^\lambda\right) \leq 2eC_{\lambda}e^{-z}.\label{eq:G_subgaussian}
	\end{align}	
	Up to modifying the metrics $d_1$, $d_2$ to absorb the factor $eC_\lambda$ into the upper bound, this means that the process $G_\lambda$ has (conditional on $X^\lambda$) mixed tails with respect to $d_1$, $d_2$ in the sense of Equation (3.8) of \citet{dirksen2015a}. As discussed before \eqref{eq:gamma0_bound}, $1/p_{f_0}\in C^1(\Xi)$, such that $1/p_{f_0}$ is a bounded multiplication operator on $H^1(\Xi)$ by Equation (1.87) of \citet{Yagi2010}. With this, if $\norm{\gamma}_{H^\rho(\Xi)}\leq 1$, then we have by the Sobolev embedding 
	\begin{align}
        d_1(\gamma,0) = 
		&\norm{P_M(\gamma-P_J\gamma)_0}_{L^\infty(\Xi)}
            \lesssim \norm{P_M(\gamma-P_J\gamma)_0}_{H^{1}(\Xi)}   leq \norm{(\gamma-P_J\gamma)_0}_{H^{1}(\Xi)}\nonumber\\
            &\lesssim \norm{\gamma-P_J\gamma}_{H^{1}(\Xi)} \lesssim 2^{-J(\rho-1)}\label{eq:d1}
	\end{align}
    and $d_2(\gamma,0)\lesssim \sqrt{\lambda}\epsilon_\lambda 2^{-M\rho}\norm{\gamma}_{H^\rho(\Xi)}\lesssim \lambda^{-(\rho-1/2)/(2\beta_0+1)}$. Together with the tail bound in \eqref{eq:G_subgaussian}, Lemma A.2 of \citet{dirksen2015a} implies  the moment bound	
	\begin{align*}
		\sup_{\gamma\in\bar{\mathcal{F}}_J}\EV[\lambda][D_\lambda]{\abs{G_\lambda(\gamma)}\given X^\lambda} \lesssim \sup_{\gamma\in\bar{\mathcal{F}}_J}(d_1(\gamma,0)+d_2(\gamma,0)) \lesssim 2^{-J(\rho-1)}+\lambda^{-(\rho-1/2)/(2\beta_0+1)}.
	\end{align*}
    We then obtain the claimed maximal inequality from Theorem 3.5 of \citet{dirksen2015a} by proving the following two entropy integral bounds:
	\begin{align}
    \begin{split}
		\int_0^{\infty}\sqrt{\log (2N(\bar{\mathcal{F}}_J, d_1, \epsilon))}\,\D\epsilon  &\lesssim 2^{-J(\rho-1)},\\
        \int_0^{\infty}\log (2N(\bar{\mathcal{F}}_J, d_2, \epsilon))\,\D\epsilon
			&\lesssim \lambda^{-(\rho-3/2)/(2\beta_0+1)}.
            \end{split}
            \label{eq:metric_entropy_integral_bounds}
	\end{align}	
	For this, let $\tilde{\mathcal{F}}_J=\{P_M\gamma_0:\gamma\in\bar{\mathcal{F}}_J\}$. We have $N(\bar{\mathcal{F}}_J,d_1,\varepsilon)=N(\tilde{\mathcal{F}}_J,\bar{C}\norm{}_{L^\infty(\Xi)},\varepsilon)$. Recalling \eqref{eq:d1}, we have $\norm{P_M(\gamma-P_J\gamma)_0}_{H^1(\Xi)}\lesssim 2^{-J(\rho-1)}$ if $\norm{\gamma}_{H^\rho(\Xi)}\leq 1$, such that $\tilde{\mathcal{F}}_J\subset B(0,\norm{}_{H^1(\Xi)},c2^{-J(\rho-1})$ for a constant $c=c(p_{f_0},\Xi)$ depending only on $p_{f_0}$ and $\Xi$. From Corollary 4.3.38 of \citet{gineMathematicalFoundationsInfiniteDimensional2015} we get $N(\bar{\mathcal{F}}_J,d_1,\varepsilon)\lesssim \exp(c2^{-J(\rho-1)}/\varepsilon)$, and \eqref{eq:diameter_bound} gives $    \sup_{\gamma,\bar\gamma\in\bar{\mathcal{F}}_J}d_1(\gamma,\bar\gamma)\lesssim 2^{-J(\rho-1)}$. The first integral bound in \eqref{eq:metric_entropy_integral_bounds} follows as in \eqref{num:Maximal2}. Regarding the second bound, note $\bar{\mathcal{F}}_J\subset B(0,\norm{}_{H^\rho(\Xi)},1)$ and $d_2(\gamma,\bar\gamma)\leq \sqrt{\lambda}\epsilon_\lambda\norm{\gamma-\bar\gamma}_{L^2(\Xi)}$ we have by Corollary 4.3.38 of \citet{gineMathematicalFoundationsInfiniteDimensional2015}
	\begin{align*}
		N(\bar{\mathcal{F}}_J, d_2, \epsilon) 
			&\leq N(\bar{\mathcal{F}}_J,\norm{}_{L^2(\Xi)},\varepsilon/(\sqrt{\lambda}\varepsilon_\lambda)) \lesssim \exp{((C\sqrt{\lambda}\varepsilon_\lambda/\varepsilon)^{1/\rho})}
	\end{align*}
    for a constant $C>0$. The second integral bound is obtained from
	\begin{align*}
		\int_0^{\infty}\log (2N(\bar{\mathcal{F}}_J, d_2, \epsilon))\,\D\epsilon 
			&\lesssim \int_0^{\bar c\sqrt{\lambda}\epsilon_\lambda 2^{-M\rho}}(\log (2) + \exp{((C\sqrt{\lambda}\varepsilon_\lambda/\varepsilon)^{1/\rho})}\,\D\epsilon\\
            &\lesssim  \sqrt{\lambda}\epsilon_\lambda 2^{-M\rho} + (\sqrt{\lambda}\varepsilon_\lambda)^{1/\rho}(\sqrt{\lambda}\epsilon_\lambda 2^{-M\rho})^{1-1/\rho}\\
            &\lesssim \lambda^{-(\rho-3/2)/(2\beta_0+1)}.
	\end{align*}
\item Let $\langle h\rangle_t=\lambda^{-1}\int_0^t\norm{h(X_s)}^2_{L^2(\Lambda)}\D s$ denote the quadratic variation of the continuous martingale $W_\lambda(h)\int_0^t h(X_s)\D W_s$, $t\geq 0$, for a square integrable function $h$. Then $\langle h\rangle_T\leq T\norm{h}_{\infty}^2$ and the Bernstein inequality for continuous martingales (e.g., Page 153 of \citet{RevuzYor1999}) implies for $x\geq 0$ 
	\begin{align*}
		\prob[f_0]{\abs{W_{\lambda}(\gamma)}\geq x} 
			&= \prob[f_0]{\abs{W_{\lambda}(\gamma)}\geq x, \langle \gamma\rangle_T\leq T\norm{\gamma}_{L^\infty(\Xi)}} \leq 2\exp\left(-\frac{x^2}{2T\norm{\gamma}_{L^\infty(\Xi)}^2}\right)
	\end{align*}
    for any $\gamma\in B(0,\norm{}_{H^\rho(\Xi)},1)$. In particular, $W_{\lambda}(\gamma)$ is sub-Gaussian with respect to the distance $d=T\norm{}_{\infty}^2$. Up to a constant this is the distance $d_1$ from \eqref{eq:Metrics_d1d2}, and the claim follows from Lemma \ref{lem:UniformSubgaussianConcentration} and the bound on the Dudley entropy integral relative to $d_1$ in \eqref{eq:metric_entropy_integral_bounds}.
\end{enumerate}
\end{proof}



\section{Probabilistic results}\label{sec:Appendix_Probability}

This section \ref{sec:Appendix_Probability} collects the general properties of the SPDE \eqref{eq:SPDE}, the required upper bounds for the derivative of the density $\partial_x p_{f_0,\lambda}(t,y,x)$ (Proposition \ref{prop:DensityBoundedDerivative}) and the convergence of $X_t(\lambda\bar{y})\xrightarrow{d}Z_t^{\bar{y}}(0)$ as $\lambda\to\infty$ in Proposition \ref{prop:Convergencetoglobal}.


\subsection{Properties of the semi-linear SPDE}\label{subsec:ProbabilisticProperties}


    As shown in Subsection \ref{subsec:Rescaling}, the process $Y_t(y)\coloneq X_t(\lambda^{-1}y)$ for $0\le t\le T$ and $y\in\Lambda$ satisfies the SPDE
    \begin{equation}
        \D Y_t(y) = \nu\Updelta Y_t(y)\,\D t+ f(Y_t(y))\,\D t + \nu^{1/4}\,\D W_t(y),\quad Y_0=\chi,\label{eq:Y_appendix1}
    \end{equation}
    on $\bar{\Lambda}$ with diffusivity level $\nu = \lambda^{-2}$ and noise level $\sigma = \lambda^{-1/2}=\nu^{1/4}$. The equivalence shows that the probabilistic results of \citet{gaudlitzNonparametricEstimationReaction2023} for the $(Y_t)_{t\in[0,T]}$ from \eqref{eq:Y_appendix1} also apply to $(X_t)_{t\in[0,T]}$ from \eqref{eq:SPDE} for any $\lambda\ge 1$. In the following, we collect the key analytical properties of the process $(X_t)_{t\in[0,T]}$.

		\begin{lemma}[Lemma E.1 of \citet{gaudlitzNonparametricEstimationReaction2023}]\label{lem:aux_WellPosedness}
            Let $\lambda\ge 1$ and $X_0\in C(\Lambda)$ be any deterministic initial condition for the SPDE \eqref{eq:SPDE}.
            \begin{enumerate}[(a)]
			\item\label{num:aux_wellposed_a} The semi-linear SPDE \eqref{eq:SPDE} has a unique mild solution $(X_t(y) \,\vert\, 0\le t\le T, y\in\Lambda)$ given by
            \begin{equation}
            \begin{split}
                X_t(y) =\int_\Lambda G_t(y,\eta)X_0(\eta)\,\D\eta+  \int_0^t \int_\Lambda G_{t-s}^\lambda (y,\eta)\mathcal{W}(\D \eta,\D s)+\int_0^t\int_\Lambda G_{t-s}^\lambda (y,\eta)f(X_s(\eta))\,\D \eta\D s.
                \end{split}
                \label{eq:RandomField1}
            \end{equation}
			\item\label{num:aux_wellposed_b} The Malliavin derivative $\mathcal{D}X_t(y)\in L^2([0,T],L^2(\Lambda))$ of $X_t(y)$ from \eqref{eq:RandomField1} exists for all times $0< t\le T$, locations $y\in\Lambda$, and satisfies 
            \begin{equation*}
                \mathcal{D}_{\tau,z}X_t(y) = G_{t-\tau}^\lambda(y,z) + \int_0^t\int_\Lambda G_{t-s}^\lambda(y,\eta)f'(X_s(\eta))\mathcal{D}_{\tau,z}X_s(\eta)\,\D \eta\D s
            \end{equation*}
            for all $0\le\tau<t$, and $z\in\Lambda$.
			\item\label{num:aux_wellposed_c} The process $(X_t(y) \,\vert\, 0\le t\le T, y\in\Lambda)$ from \eqref{eq:RandomField1} is also an analytically weak solution to \eqref{eq:SPDE} in the sense that
			\begin{equation*}
				 \iprod*{X_t}{\phi}_{L^2(\Lambda)}-\iprod*{X_0}{\phi}_{L^2(\Lambda)} = \int_0^t \left(\iprod*{X_s}{ \Updelta \phi}_{L^2(\Lambda)} + \iprod*{F(X_s)}{\phi}_{L^2(\Lambda)}\right)\,\D s+\int_0^t\iprod*{\phi}{\D W_s}_{L^2(\Lambda)}
			\end{equation*}
			for all $\phi\in \operatorname{dom}(\Updelta)$ and $0\le t\le T$.
			\end{enumerate}
		\end{lemma}

        \begin{lemma}[Lemma C.3 of \citet{gaudlitzNonparametricEstimationReaction2023}]\label{lem:UniformBoudnednessSolution}
		Let $\lambda\ge 1$, $p\ge 1$ and $X_0\in C(\Lambda)$ be any deterministic initial condition. Then there exists a constant $0<C<\infty$, depending only on $p$, $\norm{X_0}_{L^\infty(\Lambda)}$, $T$, $f(0)$ and $\Lip{f}$, such that for all domain sizes $\lambda\ge 1$, time points $0\le t\le T$ and locations $y\in\Lambda$ we have the bound
		\begin{equation*}
			\EV*[f]{\abs*{X_{t}(y)}^p}\le C<\infty.
		\end{equation*}
		\end{lemma}

        \begin{proposition}[Proposition 4.1 of \citet{gaudlitzNonparametricEstimationReaction2023}]\label{prop:DensityBounds}
			There exist constants $0<c_1\le C_1<\infty$, $0<c_2\le C_2<\infty$, depending only on $\Lip{f}$ and $T$, such that for all domain sizes $\lambda\ge 1$, locations $y\in\Lambda$ and time points $0<t\le T$ the Lebesgue-density $p_{f,\lambda}(t,y,\MTemptyplaceholder)$ of $X_{t}(y)$ started at the deterministic initial condition $X_0\in C(\Lambda)$ exists and satisfies the bound
			\begin{equation*}
				p_{f,\lambda}(t,y,x-\EV[f]{X_{t}(y)})\le C_1 t^{-1/4}\exp\left(-\frac{x^2}{2C_2t^{1/2}}\right),\quad x\in\mathbb{R}.
			\end{equation*}
			Moreover, there exists $0<t_1\le T$ such that
			\begin{equation*}
				p_{f,\lambda}(t,y,x-\EV[f]{X_{t}(y)})\ge c_1 t^{-1/4}\exp\left(-\frac{x^2}{2c_2t^{1/2}}\right),\quad x\in\mathbb{R},\quad 0<t\le t_1.
			\end{equation*}
		\end{proposition}

    		\begin{corollary}[Corollary 4.3 of \citet{gaudlitzNonparametricEstimationReaction2023}]\label{cor:DensityBounds}
            For any $\lambda\ge 1$ and deterministic initial condition $X_0\in C(\Lambda)$ we have the following.
			\begin{enumerate}[(a)]
				\item\label{num:cordensitybounds_a} There exists a constant $0<p_{\max}<\infty$, depending only on $\Lip{f}$ and $T$, such that for all locations $y\in\Lambda$ and time points $0<t \le T$ the Lebesgue-density $p_{f,\lambda}(t,y,\MTemptyplaceholder)$ of $X_{t}(y)$ started at $X_0$ exists and satisfies
			\begin{equation*}
				p_{f,\lambda}(t,y,x)\le p_{\max}t^{-1/4}<\infty,\quad x\in\mathbb{R}.
			\end{equation*}
			\item\label{num:cordensitybounds_b} There exist time points $0<t_0<t_1\le T$ and a constant $0<p_{\min}<\infty$, depending on $\norm{X_0}_{L^\infty(\Lambda)}$, $\Xi$, $t_0$, $t_1$, $\Lip{f}$ and $T$, such that
			\begin{equation*}
				p_{f,\lambda}(t,y,x) \ge p_{\min}>0,\quad x\in\Xi,
			\end{equation*}
			for all $y\in\Lambda$ and $t_0 \le t\le t_1$.
            \item\label{num:cordensitybounds_c} For every $\lambda\ge 1$, $0<t\le T$ and $y\in\Lambda$ the density $p_{f,\lambda}(t,y,\MTemptyplaceholder)$ has Gaussian tails.
			\end{enumerate}
		\end{corollary}
        \begin{proof}
            \eqref{num:cordensitybounds_a} and \eqref{num:cordensitybounds_b} follow directly from Proposition \ref{prop:DensityBounds}. The Gaussian tails in \eqref{num:cordensitybounds_c} follows by combining Proposition \ref{prop:DensityBounds} with the bound $\abs{\EV[f]{X_t(y)}}\le \EV[f]{\abs{X_t(y)}}\le C$ from Lemma \ref{lem:UniformBoudnednessSolution}.
        \end{proof}




\subsection{Upper bounds for the derivative of densities}\label{subsec:DensityDerivatives}

        This subsection contains the upper bound for the derivative of the density $\partial_x p_{f,\lambda}(t,y,x)$, which is required for Step 1 (Lemma \ref{lem:Bayes_BoundConditionalExpectation}) in the proof of the sub-Gaussian concentration in Theorem \ref{thm:SubgaussianConcentration}. We introduce $\mathfrak{H}\coloneq L^2([0,T],L^2(\Lambda))$ and continue with bounding the growth of the Green function $G_t^\lambda$.
        \begin{lemma}\label{lem:aux_GreenfunctionsGrowth}
            For any $\lambda\ge 1$ and $0<t\le T$ we have
            \begin{equation*}
                \norm{G_{t-\MTemptyplaceholder}^\lambda(y,\MTemptyplaceholder)}_{\mathfrak{H}}^2\le \bar{C} t^{1/2}
            \end{equation*}
            for some constant $0<\bar{C}<\infty$ depending on $T$.
        \end{lemma}
        \begin{proof}
            Define $\bar{y} \coloneq y/\lambda\in\bar{\Lambda}$. Then we have
            \begin{equation*}
                \norm{G_{t-\MTemptyplaceholder}^\lambda(y,\MTemptyplaceholder)}_{\mathfrak{H}}^2 = \int_0^t \int_\Lambda G_{t-s}^\lambda(\lambda\bar{y},\eta)^2\,\D \eta\D s = \lambda \int_0^t\int_{\bar{\Lambda}} G_{t-s}^\lambda(\lambda\bar{y},\lambda\bar{\eta})^2\,\D\bar{\eta}\D s.
            \end{equation*}
            Using the rescaling of the Green function $G_t^\lambda(\lambda\bar{y},\lambda{\bar{\eta}}) = \lambda^{-1}G_{\lambda^{-2}t}^1(\bar{y},\bar{\eta})$ for $\bar{y},\bar{\eta}\in\bar{\Lambda}$ from \eqref{eq:Scaling_Heat_Kernel}, we find
            \begin{equation*}
                \norm{G_{t-\MTemptyplaceholder}^\lambda(y,\MTemptyplaceholder)}_{\mathfrak{H}}^2 = \lambda^{-1}\int_0^t\int_{\bar{\Lambda}} G_{\lambda^{-2}(t-s)}^1(\bar{y},\bar{\eta})^2\,\D\bar{\eta}\D s.
            \end{equation*}
            Applying the bound $G_{t}^1(\bar{y},\bar{\eta})\le c (t^{-1/2}\vee 1)\exp(-(\bar{y}-\bar{\eta})^2/(\tilde{c}t))$ for some constants $0<c,\tilde{c}<\infty$ from Theorem 3.2.9 of \citet{daviesHeatKernelsSpectral1990}, we find
            \begin{equation*}
                \norm{G_{t-\MTemptyplaceholder}^\lambda(y,\MTemptyplaceholder)}_{\mathfrak{H}}^2\le c^2\tilde{c}^{1/2}\lambda^{-1}\int_0^t ((\lambda^{-2}(t-s))^{-1/2}\vee 1)^2 \lambda^{-1}(t-s)^{1/2}\,\D s\lesssim_T t^{1/2}.
            \end{equation*}\qedhere
        \end{proof}
    With this preparation, we can proceed to the proof of Proposition \ref{prop:DensityBoundedDerivative}. It relies on the explicit formula 
    \begin{equation*}
        \partial_x^n p_{f,\lambda}(t,y,x) = (-1)^n\EV[f]{\indicator(X_t(y)> x)H_{1^{\otimes (n+1)}}},\quad x\in\mathbb{R}, n\in\mathbb{N}_0,
    \end{equation*}
    which is based on the integration-by-parts formula of the Malliavin calculus and can be found in the proof of Theorem 2.1.4 of \citet{nualartMalliavinCalculusRelated2006}. With the Skorodhod integral $\delta$, the quantity $H_{1^{\otimes (n+1)}}$ is defined as
    \begin{equation*}
        H_{1^{\otimes 1}}\coloneq \delta \left(\frac{\mathcal{D} X_t(y)}{\norm{\mathcal{D} X_t(y)}_{\mathfrak{H}}^2}\right),\quad H_{1^{\otimes (n+1)}}\coloneq \delta\left(\frac{\mathcal{D}X_t(y)}{\norm{\mathcal{D}X_t(y)}_{\mathfrak{H}}^2} H_{1^{\otimes n}}\right),\quad n\in\mathbb{N}.
    \end{equation*}
    Subsequently, $\abs{\partial_x^n p_{f,\lambda}(t,y,x)}$ can be bounded by an successive application of the Hölder-inequality given in Proposition 1.5.6 of \citet{nualartMalliavinCalculusRelated2006} and upper and lower bounds on $\norm{\mathcal{D}X_t(y)}_{\mathfrak{H}}$. The latter bounds are based on the Green function bound of Lemma \ref{lem:aux_GreenfunctionsGrowth} and the Gronwall inequality.
	\begin{proof}[Proof of Proposition \ref{prop:DensityBoundedDerivative}]
		Fix a time point $0<t\le T$ and a location $y\in\Lambda$. Let $\gamma_{t,y}\coloneq \norm{\mathcal{D}X_t(y)}_\mathfrak{H}^2$ and define as in Equations (1.32) and (1.37) of \citet{nualartMalliavinCalculusRelated2006} the semi-norms
		\begin{align*}
			\norm{H}_{k,p}^p&\coloneq \EV[f]{\abs{H}^p}+\sum_{l=1}^{k} \EV[f]{\norm{\mathcal{D}^l H}_{\mathfrak{H}^{\otimes l}}^{p}},\quad k\in\mathbb{N},\quad p\ge 1,\\
            \norm{\tilde{H}}_{k,p}^p&\coloneq \EV[f]{\norm{\tilde{H}}_{\mathfrak{H}}^p}+\sum_{l=1}^{k} \EV[f]{\norm{\mathcal{D}^l \tilde{H}}_{\mathfrak{H}^{\otimes l}}^{p}},\quad k\in\mathbb{N},\quad p\ge 1,
		\end{align*}
		for any sufficiently Malliavin-differentiable random variable $H\in\mathbb{R}$ and $\tilde{H}\in\mathfrak{H}$. For $n\in\Set*{0,\dots, N}$, we use Theorem 2.1.4 and Proposition 2.1.4 of \citet{nualartMalliavinCalculusRelated2006}, to obtain
		\begin{equation*}
			\abs{\partial_x^n p_{f,\lambda}(t,y,x)} = \abs{\EV[f]{\indicator_{\{X_t(y)>x\}}H_{1^{\otimes (n+1)}}}}\le \EV[f]{\abs{H_{1^{\otimes (n+1)}}}^p}^{1/p}\le c_p \norm{\gamma_{t,y}^{-1}\mathcal{D}X_t(y)}_{n+1,q}^{n+1}
		\end{equation*}
		 for any $x\in\mathbb{R}$, where $p\ge 1$ is arbitrary and $q\ge 1$ and $0<c_p<\infty$ depend only on $p$. The application of Hölder-inequality for the norms $\norm{}_{r,s}$ (Proposition 1.5.6 of \citet{nualartMalliavinCalculusRelated2006}) yields
		\begin{equation}
			\abs{\partial_x^n p_{f,\lambda}(t,y,x)}\le \tilde{c}_p \norm{\gamma_{t,y}^{-1}}_{n+1,r}^{n+1}\norm{\mathcal{D}X_t(y)}_{n+1,s}^{n+1}\label{eq:aux_density_deriv}
		\end{equation}
		uniformly in $x\in\mathbb{R}$, where $1/q = 1/r+1/s$ and $0<\tilde{c}_p<\infty$ only depends on $p,r$ and $s$, compare page 102 of \citet{nualartMalliavinCalculusRelated2006}.\\
		\textbf{Step 1 (Controlling $\norm{\mathcal{D}X_t(y)}_{n,s}^n$).}
		We claim that for each $0<t\le T$ we can bound
		\begin{align}
			\begin{split}
				\sup_{\lambda\ge 1,y\in\Lambda}\norm{\mathcal{D} X_t(y)}_{\mathfrak{H}}& \le C_1t^{1/4},                                  \\
				\sup_{\lambda\ge 1, y\in\Lambda}\norm{\mathcal{D}^n X_t(y)}_{\mathfrak{H}^{\otimes n}} & \le C_n t^{1+n/4},\quad n=2,\dots, N+2,
			\end{split}\label{eq:Deriv_Momentbounds}
		\end{align}
		almost surely, where the constants $0<C_n<\infty$ depend on $n$, $K$ and $T$, but not on the domain size $\lambda\ge 1$, the time point $0<t\le T$ or the location $y\in\Lambda$. The deterministic bounds \eqref{eq:Deriv_Momentbounds} imply
		\begin{equation}
			\norm{\mathcal{D}X_t(y)}_{n,s}\lesssim _{n,T,K}t^{1/4},\label{eq:aux_DerivNorm}
		\end{equation}
		uniformly in $s\ge 1$, $0<t\le T$ and $y\in\Lambda$. We prove \eqref{eq:Deriv_Momentbounds} by induction over $n\in\Set*{1,\dots,N+2}$, similarly to Proposition 4.3 of \citet{ballyMalliavinCalculusWhite1998}.\\
		\textbf{Base case ($n=1$).} For $n=1$ and $0<t\le T$ we apply the expression \eqref{eq:malliavin_derivative} for the Malliavin derivative and Lemma \ref{lem:aux_GreenfunctionsGrowth} to obtain
		\begin{align*}
			\sup_{y\in\Lambda}\norm{\mathcal{D}X_t(y)}_{\mathfrak{H}} & \le \norm{G_{t-\MTemptyplaceholder}^\lambda(y,\MTemptyplaceholder)}_{\mathfrak{H}} + \norm{f'}_{L^\infty(\mathbb{R})}\int_0^t \int_{\Lambda} G_{t-s}^\lambda(y,\eta)\sup_{z\in\Lambda}\norm{\mathcal{D}X_s(z)}_{\mathfrak{H}}\,\D \eta\D s \\
            & \le \bar{C}t^{1/4} + \norm{f'}_{L^\infty(\mathbb{R})}  \int_0^t \sup_{z\in\Lambda}\norm{\mathcal{D}X_s(z)}_{\mathfrak{H}}\,\D s.
		\end{align*}
		Applying Gronwall's inequality yields the (deterministic) bound
		\begin{equation}
			\sup_{y\in\Lambda}\norm{\mathcal{D}X_t(y)}_{\mathfrak{H}} \le \bar{C}t^{1/4} e^{\norm{f'}_{L^\infty(\mathbb{R})}  t} =\colon C_1(t),\quad 0<t\le T,\label{eq:C_1}
		\end{equation}
		uniformly in $\lambda \ge 1$.\\
		\textbf{Intermezzo.} For the reader's convenience, we treat the case $n=2$ separately before continuing the induction. We have for all times $0< t\le T$ and locations $y\in\Lambda$ the equality
		\begin{equation*}
			\mathcal{D}^2X_t(y)=\begin{multlined}[t]
				\int_0^t \int_{\Lambda}  G_{t-s}^\lambda(y,\eta)f''(X_s(\eta))\mathcal{D}X_s(\eta)\otimes\mathcal{D} X_s(\eta)\,\D\eta \D s\\
				+ \int_0^t \int_{\Lambda} G_{t-s}^\lambda(y,\eta)f'(X_s(\eta))\mathcal{D}^2X_s(\eta)\,\D \eta\D s
			\end{multlined}
		\end{equation*}
		and thus
		\begin{align*}
			\sup_{y\in\Lambda}\norm{\mathcal{D}^2X_t(y)}_{\mathfrak{H}^{\otimes 2}} & \le  \begin{multlined}[t]
            \sup_{y\in\Lambda}\norm{f''}_{L^\infty(\mathbb{R})}\int_0^t \int_{\Lambda}  G_{t-s}^\lambda(y,\eta)\norm{\mathcal{D}X_s(\eta)}_{\mathfrak{H}}^2\,\D\eta \D s\\
            + \sup_{y\in\Lambda}\norm{f'}_{L^\infty(\mathbb{R})}\int_0^t \int_{\Lambda} G_{t-s}^\lambda(y,\eta)\norm{\mathcal{D}^2X_s(\eta)}_{\mathfrak{H}^{\otimes 2}}\,\D \eta\D s
            \end{multlined}\\
            & \le \begin{multlined}[t]
            \sup_{y\in\Lambda}\norm{f''}_{L^\infty(\mathbb{R})}\int_0^t\int_{\Lambda} G_{t-s}^\lambda(y,\eta)C_1(s)^2\,\D\eta\D s \\
            + \norm{f'}_{L^\infty(\mathbb{R})} \sup_{y\in\Lambda}\int_0^t\sup_{z\in\Lambda}\norm{\mathcal{D}^2X_s(z)}_{\mathfrak{H}^{\otimes 2}}\int_{\Lambda} G_{t-s}^\lambda(y,\eta)\,\D\eta\D s
		      \end{multlined} \\
              & \le \norm{f''}_{L^\infty(\mathbb{R})}  C_1(t)^2t + \norm{f'}_{L^\infty(\mathbb{R})} \int_0^t \sup_{z\in\Lambda}\norm{\mathcal{D}^2X_s(z)}_{\mathfrak{H}^{\otimes 2}}\,\D s
		\end{align*}
		for all $0<t\le T$. An application of Gronwall's inequality yields the bound
		\begin{equation}
			\sup_{y\in\Lambda}\norm{\mathcal{D}^2X_t(y)}_{\mathfrak{H}^{\otimes 2}} \le \norm{f''}_{L^\infty(\mathbb{R})} C_1(t)^2t e^{\norm{f'}_{L^\infty(\mathbb{R})} t}=\colon C_2(t),\quad 0<t\le T,\label{eq:Bayes_aux_C2}
		\end{equation}
		uniformly in $\lambda\ge 1$.\\
		\textbf{Induction step ($n-1\leadsto n$, $n\le N+2$).} For the induction step we use the chain rule for Malliavin derivatives in the form of (3.20) of \citep{SanzSole2005}. It implies
		\begin{equation*}
			\mathcal{D}^nX_t(y)=\begin{multlined}[t]
				\int_0^t \int_{\Lambda}  G_{t-s}^\lambda(y,\eta)\sum_{l=2}^{n}\sum_{P_l} c_l f^{(l)}(X_s(\eta))\bigotimes_{i=1}^l\mathcal{D}^{\abs{p_i}}X_s(\eta)\,\D\eta \D s\\
				+ \int_0^t \int_{\Lambda} G_{t-s}^\lambda(y,\eta)f'(X_s(\eta))\mathcal{D}^n X_s(\eta)\,\D \eta\D s,
			\end{multlined}
		\end{equation*}
		where $P_l$ denotes the set of partitions of $\Set{1,\dots,n}$ consisting of $l$ disjoint sets $p_1,\dots,p_l$ and $c_l>0$. In addition to $C_1(t)$ defined in \eqref{eq:C_1}, we define the quantities
		\begin{equation*}
			C_n(t)\coloneq \sum_{l=2}^{n}\sum_{P_l} c_l \norm{f^{(l)}}_{L^\infty(\mathbb{R})}\prod_{i=1}^lC_{\abs{p_i}}(t) t e^{\norm{f'}_{L^\infty(\mathbb{R})}  t},\quad n\in\mathbb{N}, n\ge 2,\quad 0<t\le T.
		\end{equation*}
		Note that $C_2(t)$ agrees with \eqref{eq:Bayes_aux_C2} and that for any $n\in\mathbb{N}$, $0<s\le t\le T$, the monotonicity $C_n(s)\le C_n(t)$ holds. Furthermore, for $n\ge 2$ and $0<t\le T$ holds $C_n(t)\lesssim_{K,T} t^{1+n/4}$. Then we find
		\begin{align*}
			\sup_{y\in\Lambda}\norm{\mathcal{D}^n X_t(y)}_{\mathfrak{H}^{\otimes n}} & \le
			\sup_{y\in\Lambda}\int_0^t \int_{\Lambda}  G_{t-s}^\lambda(y,\eta)\sum_{l=2}^{n}\sum_{P_l} c_l \norm{f^{(l)}}_{L^\infty(\mathbb{R})}\prod_{i=1}^l\norm{\mathcal{D}^{\abs{p_i}}X_s(\eta)}_{\mathfrak{H}^{\otimes \abs{p_i}}}\,\D\eta \D s\\
            & \quad + \sup_{y\in\Lambda}\norm{f'}_{L^\infty(\mathbb{R})}\int_0^t \int_{\Lambda} G_{t-s}^\lambda(y,\eta)\norm{\mathcal{D}^nX_s(\eta)}_{\mathfrak{H}^{\otimes n}}\,\D \eta\D s\\
            & \le
			\sup_{y\in\Lambda}\int_0^t \int_{\Lambda}  G_{t-s}^\lambda(y,\eta)\sum_{l=2}^{n}\sum_{P_l} c_l \norm{f^{(l)}}_{L^\infty(\mathbb{R})}\prod_{i=1}^lC_{\abs{p_i}}(s)\,\D\eta\D s\\
            & \quad+ \norm{f'}_{L^\infty(\mathbb{R})} \sup_{y\in\Lambda}\int_0^t\sup_{z\in\Lambda}\norm{\mathcal{D}^nX_s(z)}_{\mathfrak{H}^{\otimes n}}\int_{\Lambda} G_{t-s}^\lambda(y,\eta)\,\D\eta\D s
			\\
            & \le \sum_{l=2}^{n}\sum_{P_l} c_l \norm{f^{(l)}}_{L^\infty(\mathbb{R})} \prod_{i=1}^lC_{\abs{p_i}}(t)t+ \norm{f'}_{L^\infty(\mathbb{R})} \int_0^t \sup_{z\in\Lambda}\norm{\mathcal{D}^nX_s(z)}_{\mathfrak{H}^{\otimes n}}\,\D s.
		\end{align*}
		An application of Gronwall's inequality shows
		\begin{equation*}
			\sup_{y\in\Lambda}\norm{\mathcal{D}^nX_t(y)}_{\mathfrak{H}^{\otimes n}} \le \sum_{l=2}^{n}\sum_{P_l} c_l \norm{f^{(l)}}_{L^\infty(\mathbb{R})}\prod_{i=1}^lC_{\abs{p_i}}(t) t e^{\norm{f'}_{L^\infty(\mathbb{R})}  t}= C_n(t),\quad 0<t\le T,
		\end{equation*}
		uniformly in the domain size $\lambda\ge 1$ and $n\in\mathbb{N}$.\\
		\textbf{Step 2 (Controlling $\norm{\gamma_{t,y}^{-1}}_{n,r}^n$).}\\
		The upper bound for $n=1$ from \eqref{eq:Deriv_Momentbounds} and the lower bound from the proof of Lemma C.1 of \citet{gaudlitzNonparametricEstimationReaction2023} show
		\begin{equation*}
			\gamma_{t,y} = \norm{\mathcal{D}X_t(y)}_{\mathfrak{H}}^2\sim t^{1/2},
		\end{equation*}
		uniformly in $\lambda\ge 1$, $0< t\le T$ and $y\in\Lambda$. The recursion (2.24) of \citep{nualartMalliavinCalculusRelated2006} together with \eqref{eq:Deriv_Momentbounds} reveal that $\norm{\gamma_{t,y}^{-1}}_{n,r}^r$, $r\ge 1$, is dominated by its zeroth component when no derivative is taken, such that
		\begin{equation*}
			\norm{\gamma_{t,y}^{-1}}_{n,r}^r \lesssim_T \EV[f]{\abs{\gamma_{t,y}^{-1}}^r}\lesssim t^{-r/2},\quad 0<t\le T,\quad y\in\Lambda,
		\end{equation*}
		and thus
		\begin{equation}
			\norm{\gamma_{t,y}^{-1}}_{n,r}^{n}\lesssim_T t^{-n/2}\label{eq:aux_gamma_bounds}
		\end{equation}
		uniformly in $\lambda\ge 1$, $0< t\le T$ and $y\in\Lambda$.\\
		\textbf{Step 3 (Conclusion).}\\
		The claim follows from \eqref{eq:aux_density_deriv}, \eqref{eq:aux_DerivNorm} and \eqref{eq:aux_gamma_bounds}: There exists a constant $0<\tilde{C}<\infty$ depending on $T$ and $K$ such that for all $\lambda\ge 1$, $0<t\le T$, $y\in\Lambda$ and $x\in\mathbb{R}$ the bound
		\begin{equation*}
			\abs{\partial_x^n p_{f,\lambda}(t,y,x)} \le \tilde{C} t^{-(n+1)/2}t^{(n+1)/4} = \tilde{C}t^{-(n+1)/4}
		\end{equation*}
		holds.
	\end{proof}


