	\subsection{Convergence to the global solution}\label{chap:Convergence}

	This section explores the behaviour of the semi-linear stochastic heat equation driven by space-time white noise on the growing spatial domain $\Lambda=\lambda\bar{\Lambda}$ with $\lambda\to\infty$. Without loss of generality we assume $0\in \bar{\Lambda}$ such that $\Lambda = \lambda\bar{\Lambda}\to \mathbb{R}$ as $\lambda\to\infty$. The goal is to show the weak convergence $X_t(\lambda \bar{y})\xrightarrow{d}Z_t^{\bar{y}}(0)$ as $\lambda\to\infty$ for every $0\le t\le T$ and $\bar{y}\in\bar{\Lambda}$ and proving Theorem \ref{thm:ErgodicProperties} \eqref{num:thm_Ergodicity1}. Denote by $\star$ the operation
	\begin{equation*}
		(u\star v)(y)\coloneq \int_{\mathbb{R}}u(y,\eta)v(\eta)\,\D\eta,\quad y\in\mathbb{R},
	\end{equation*}
	for any functions $u\colon \mathbb{R}^2\to\mathbb{R}$, $v\colon\mathbb{R}\to\mathbb{R}$ such that $u(y,\MTemptyplaceholder)v(\MTemptyplaceholder)\in L^1(\mathbb{R})$ for all $y\in\mathbb{R}$.
	 Let $\phi_t$ be the heat kernel on $\mathbb{R}$, that is
	\begin{equation*}
		\phi_t(y,\eta) = \frac{1}{\sqrt{4\pi t}}\exp\left(-\frac{(y-\eta)^2}{4t}\right),\quad t>0,\quad y,\eta\in\mathbb{R}.
	\end{equation*}
	Recall that the process $(Z_t^{\bar{y}}(y)\,\vert \, y\in\mathbb{R}, 0\le t\le T)$ solving the semi-linear heat equation \eqref{eq:Z} can be written as
	\begin{equation}
		Z_t^{\bar{y}}(y)= \int_0^t (\phi_{t-s}\star f(Z_s^{\bar{y}}))(y)\,\D s + \bar{Z}_t^{\bar{y}}(y),\quad  \bar{Z}_t^{\bar{y}}(y)\coloneq \chi(\bar{y})+\int_{\mathbb{R}}\phi_{t-s}(y,\eta)\mathcal{W}(\D\eta,\D s),\label{eq:ConvGlobal_Z}
	\end{equation}
	where $\mathcal{W}$ is understood as spatially homogeneous (space-time white) noise $\mathcal{W}$ on $\mathbb{R}$, compare \citep{Dalang2011}.
     Denote by $G_t^\lambda(y,\eta)$ for $t>0$ and $y,\eta\in\Lambda$ the Neumann heat kernel on $\Lambda$. Without further mentioning we will extend $G_t^\lambda$ by zero to a function on $\mathbb{R}\times\mathbb{R}$. Define the process
	\begin{align}
    \begin{split}
    \bar{X}_t(y)&\coloneq (G_{t}^\lambda \star X_0)(y) +  \int_{\mathbb{R}}G_{t-s}^\lambda(y,\eta)\mathcal{W}(\D\eta,\D s),\\
		X_t(y)&\coloneq \int_0^t (G_{t-s}^\lambda\star f(X_s))(y)\,\D s + \bar{X}_t(y),
    \end{split}\label{eq:ConvGlobal_X}
	\end{align}
	for $0\le t\le T, y\in \mathbb{R}$, driven by the same noise $\mathcal{W}$ as $Z_t^{\bar{y}}$. Note that the process $(X_t)_{t\in[0,T]}$ defined in \eqref{eq:ConvGlobal_X} and the process $(X_t)_{t\in[0,T]}$ defined in \eqref{eq:SPDE} have the same marginal laws for every $0\le t\le T$ and $y\in\Lambda$.
	 Since we are only aiming to prove convergence in distribution $X_t(\lambda\bar{y})\xrightarrow{d}Z_t^{\bar{y}}(0)$ as $\lambda\to\infty$ for every $0\le t\le T$ and $\bar{y}\in\bar{\Lambda}$, we keep the notation $X$ for both processes for notational simplicity.

	For a standard Brownian motion $(B_t)_{t\ge 0}$ define the stopping time
	\begin{equation*}
		\tau_\lambda\coloneq \inf\Set{t\ge 0\,\colon\,B_{2t}\not\in \lambda\bar{\Lambda}}.
	\end{equation*}
	For any location $y\in\Lambda$ and time $t\ge 0$, the probability of the event $\Set{\tau_\lambda\le t}$, given that $B_0=y$, is denoted by $\prob[y]{\tau_\lambda\le t}$. Lemma \ref{lem:Stopping_time} implies $\prob[\lambda\bar{y}]{\tau_\lambda\le t}\to 0$ as $\lambda\to \infty$ for every $\bar{y}\in\bar{\Lambda}$ and $t>0$. Recall that for $A\subset\mathbb{R}$ and $y\in\mathbb{R}$ we define their distance as $\operatorname{dist}(y,A)\coloneq \inf\Set{\abs{y-\eta}\given\eta\in A}$. The main result of this section is the following (pointwise) convergence of $X_t(\lambda \bar{y})$ to $Z_t^{\bar{y}}(\lambda \bar{y})$.


	\begin{proposition}\label{prop:Convergencetoglobal}
		Assume that $f\colon\mathbb{R}\to\mathbb{R}$ is Lipschitz-continuous and that $\chi\in H^{\tilde{s}}(\bar{\Lambda})$ for some $\tilde{s}>1/2$. For any $p\ge 1$ we have convergence
		\begin{equation*}
			\EV[f]{\abs{Z_t^{\bar{y}}(\lambda \bar{y}) - X_t(\lambda \bar{y})}^p}\to 0,\quad \bar{y}\in\bar{\Lambda},\quad  0\le t\le T,
		\end{equation*}
		as $\lambda\to \infty$ for the process $X$ defined in \eqref{eq:ConvGlobal_X}. In particular, the process $X$ defined in \eqref{eq:SPDE} satisfies $X_t(\lambda \bar{y})\xrightarrow{d}Z_t^{\bar{y}}(0)$ for all $0\le t\le T$ and $\bar{y}\in\bar{\Lambda}$. More precisely, for any exponent $p\ge 1$ and location $y\in\Lambda$ define
		\begin{equation*}
			K(y,\lambda,p)\coloneq \exp\left(-\frac{\operatorname{dist}(y,\partial\Lambda)^2}{8 c T p}\right)\begin{cases}(1 + \log(\lambda) + \operatorname{dist}(y,\partial\Lambda)^2),&p=2\\ 2,& p\neq 2,\end{cases}
		\end{equation*}
		where $c>1$ is arbitrary. Then, for all $0\le t\le T$, $y=\lambda\bar{y} \in \Lambda$ and $0<\epsilon<\tilde{s}-1/2$,
		\begin{align}
			\EV[f]{\abs{Z_t^{\bar{y}}(y)-X_t(y)}^p}\le C \left(\prob[y]{\tau_\lambda\le t}^{p/2}+ K(y,\lambda,p)+K(y,\lambda,2p)+\lambda^{-p\epsilon}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}^p\right),\label{eq:ConvergenceGlobal_Claim}
		\end{align}
		where the constant $C$ depends only on $T$, $\Lip{f}$ and $p$.
	\end{proposition}
	Before proving Proposition \ref{prop:Convergencetoglobal}, a few remarks are in order.
	\begin{remark}[On $K(y,\lambda,p)$]~
		\begin{enumerate}[(a)]
		\item For any location $\bar{y}\in\bar{\Lambda}$, we have $K(\lambda \bar{y},\lambda,p)\sim \exp(-\lambda^2/(8cTP))\to 0$ as $\lambda\to \infty$. This convergence is not uniform in $\bar{y}\in\bar{\Lambda}$ due to the effect of the boundary conditions.
				\item By integration we find for all $1\le \lambda<\infty$ and $r>0$ the bound
				\begin{equation}
					\frac{1}{\lambda}\int_\Lambda K(y,\lambda,p)^r\,\D y\lesssim_{T,p} \lambda^{-1}\begin{cases}\log(\lambda)^r,&p=2,\\ 1,&p\neq 2.\end{cases}\label{eq:Greenfunction_IntegratedProb2}
				\end{equation}
		\end{enumerate}
	\end{remark}


	\begin{corollary}\label{cor:Convergence_polynomials}
		Assume that $f\colon\mathbb{R}\to\mathbb{R}$ is Lipschitz-continuous and that $\chi\in H^{\tilde{s}}(\bar{\Lambda})$ for some $\tilde{s}>3/2$. Let $(X_t)_{t\in[0,T]}$ be either the process defined in \eqref{eq:SPDE} or in \eqref{eq:ConvGlobal_X}. For any Lipschitz-continuous function $h\colon\mathbb{R}\to\mathbb{R}$ and $k\in\mathbb{N}$ we have
		\begin{equation*}
			\abs[\bigg]{\EV[f][][\Big]{\frac{1}{\lambda}\int_0^T\int_\Lambda h(X_t(y))^k\,\D y\D t}-\int_0^T\int_{\bar{\Lambda}}\EV[f][][\Big]{h(Z_t^{\bar{y}}(0))^k}\,\D\bar{y}\D t}\le C\Lip{h} \lambda^{-1},
		\end{equation*}
        where the constant $0<C<\infty$ depends on $T$, $\Lip{f}$, $k$ and $\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}$.
	\end{corollary}
	\begin{proof}
		Note that $Z_t^{\bar{y}}(0) \overset{d}{=} Z_t^{\bar{y}}(y)$ by the stationarity of the process $y\mapsto Z_t^{\bar{y}}(y)$. This implies
		\begin{align*}
			\abs[\bigg]{\EV[f][][\Big]{\frac{1}{\lambda}\int_0^T\int_\Lambda h(X_t(y))^k\,\D y\D t}-\int_0^T\int_{\bar{\Lambda}}\EV[f][][\Big]{h(Z_t^{\bar{y}}(0))^k}\,\D\bar{y}\D t}\hspace{-18em} &\\
			& =  \frac{1}{\lambda}\abs[\bigg]{\EV[f][][\Big]{\int_0^T\int_\Lambda h(X_t(y))^k\,\D y\D t}-\EV[f][][\Big]{\int_0^T\int_{\Lambda} h(Z_t^{y/\lambda}(y))^k\,\D y\D t}}\\
			& \le \frac{1}{\lambda}\int_0^T\int_\Lambda \EV[f][][\Big]{\abs[\Big]{\left(h(X_t(y))- h(Z_t^{y/\lambda}(y))\right)\Big(\sum_{i=1}^k h(X_t(y))^{k-i}h\Big(Z_t^{y/\lambda}(y)\Big)^{i-1}\Big)}}\,\D y\D t.
            \end{align*}
            Applying Hölder's inequality with $r>1$, $r\neq 2$ and $1/r+1/\tilde{r}=1$ we find
        \begin{align*}
			\abs[\bigg]{\EV[f][][\Big]{\frac{1}{\lambda}\int_0^T\int_\Lambda h(X_t(y))^k\,\D y\D t}-\int_0^T\int_{\bar{\Lambda}}\EV[f][][\Big]{h(Z_t^{\bar{y}}(0))^k}\,\D\bar{y}\D t}\hspace{-21em} &\\
            & \le \frac{1}{\lambda}\int_0^T\int_\Lambda \Big(\EV[f][][\Big]{\left(h(X_t(y))- h(Z_t^{y/\lambda}(y)\right)^r}^{1/r}\EV[f][][\Big]{\Big(\sum_{i=1}^k h(X_t(y))^{k-i}h(Z_t^{y/\lambda}(y))^{i-1}\Big)^{\tilde{r}}}^{1/{\tilde{r}}}\,\D y\D t.
		\end{align*}
		By Lemma \ref{lem:UniformBoudnednessSolution} and Theorem 25 of \citet{Dalang2011}, we can deduce for all $n\in\mathbb{N}$ the bounds
		\begin{equation*}
			\sup_{\lambda\ge 1 ,y\in \Lambda, 0\le t\le T}\EV[f]{\abs{X_t(y)}^n}\le c,\quad\sup_{y\in \mathbb{R}, 0\le t\le T,\bar{y}\in\bar{\Lambda}}\EV[f]{\abs{Z_t^{\bar{y}}(y)}^n}\le \tilde{c},
		\end{equation*}
        where the constants $0<c,\tilde{c}<\infty$ depend on $T$, $\Lip{f}$, $n$ and $\norm{\chi}_{L^\infty(\bar{\Lambda})}$. Using the Lipschitz-continuity of $h$, Proposition \ref{prop:Convergencetoglobal} with $p=r\neq 2$ and finally the bounds \eqref{eq:Greenfunction_IntegratedProb2} and \eqref{eq:Greenfunction_IntegratedProb1} we find
		\begin{align*}
			\abs[\bigg]{\EV[f][][\Big]{\frac{1}{\lambda}\int_0^T\int_\Lambda h(X_t(y))^k\,\D y\D t}-\int_0^T\int_{\bar{\Lambda}}\EV[f][][\Big]{h(Z_t^{\bar{y}}(0))^k}\,\D\bar{y}\D t}\hspace{-13em} &\\
			  & \lesssim_{T,\Lip{f},k,\norm{\chi}_{L^\infty(\bar{\Lambda})}}\Lip{h}\frac{1}{\lambda}\int_0^T\int_{\Lambda} \EV*[f]{\abs[\Big]{X_t(y)-Z_t^{y/\lambda}(y)}^r}^{1/r}\,\D y\D t \\
			& \lesssim_{T,\Lip{f},r}\Lip{h}\frac{1}{\lambda}\int_0^T\int_{\Lambda} \sqrt{\prob[y]{\tau_\lambda\le t}} + K(y,\lambda,r)^{1/r}+K(y,\lambda,2r)^{1/r}\\
            &\quad +\lambda^{-\epsilon}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}\,\D y\D t \\
			  & \lesssim_{T}\Lip{h} \left(\lambda^{-1}+\lambda^{-1}+\lambda^{-1} + \lambda^{-\epsilon}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}\right)\\
              & \lesssim_{\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}} \Lip{h} \lambda^{-1},
		\end{align*}
        where we chose $\epsilon\ge 1$ in the last line.
	\end{proof}


	\subsubsection{Proving Proposition \ref{prop:Convergencetoglobal}}

	The proof of the bound \eqref{eq:ConvergenceGlobal_Claim} is based on two ingredients. First, it requires the convergence of the stochastic integrals $\bar{X}$ to $\bar{Z}^{\bar{y}}$ in \eqref{eq:ConvGlobal_Z} and \eqref{eq:ConvGlobal_X}, which is proved using the convergence of the corresponding Green functions. The impact of the varying initial conditions can be controlled by understanding the action of the heat semi-group $t\mapsto G_t\star\MTemptyplaceholder$ for short times, as the subsequent Lemma shows. To this end, a convenient tool is the scaling property of the Neumann heat kernel $G_t^\lambda$ on $\Lambda$ in terms of the Neumann heat kernel $G_t^1$ on $\bar{\Lambda}$ such that
    \begin{equation}
        G_t^\lambda(y,\eta) = \lambda^{-1} G_{\lambda^{-2}t}^1(\lambda^{-1}y,\lambda^{-1}\eta),\quad t>0, y,\eta\in\Lambda.\label{eq:Scaling_Heat_Kernel}
    \end{equation}
    Second, we perform a Gronwall argument to extend the convergence to the semi-linear case.

    \begin{lemma}\label{lem:Impact_Initial_Condition}
    Assume that $\chi\in H^{\tilde{s}}(\bar{\Lambda})$ for some $\tilde{s}>1/2$ and let $0<\epsilon< \tilde{s}-1/2$. Then there exists an absolute constant $0<C<\infty$ such that
    \begin{equation*}
        \norm{X_0 - G_t^\lambda \star X_0}_{L^\infty(\Lambda)}=\norm{\chi-G_{\lambda^{-2}t}^1\star \chi}_{L^\infty(\bar{\Lambda})}\le C t^{\epsilon/2}\lambda^{-\epsilon}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})},\quad 0<t\le T.
    \end{equation*}
\end{lemma}
\begin{proof}
Using the scaling of the Green kernel from \eqref{eq:Scaling_Heat_Kernel}, we deduce for every $y\in\Lambda$
\begin{align*}
  (G_t^\lambda\star X_0)(y) &=\int_\Lambda G_t^\lambda (y,\eta)X_0(\eta)\,\D \eta =\lambda\int_{\bar{\Lambda}}G_t^\lambda (y,\lambda\bar{\eta})\chi(\bar{\eta})\,\D\bar{\eta}= \int_{\bar{\Lambda}}G_{\lambda^{-2}t}^1 (y/\lambda,\bar{\eta})\chi(\bar{\eta})\,\D\bar{\eta}\\
  &= (G_{\lambda^{-2}t}^1 \star \chi)(y/\lambda),
\end{align*}
which shows the claimed equality. Since $\tilde{s}-\epsilon>1/2$, the Sobolev embedding (Theorem 4.12 of \citet{fournierSobolevSpaces2003}) yields
\begin{equation*}
    \norm{\chi-G_{\lambda^{-2}t}^1\star \chi}_{L^\infty(\bar{\Lambda})}\lesssim \norm{\chi-G_{\lambda^{-2}t}^1\star \chi}_{H^{\tilde{s}-\epsilon}(\bar{\Lambda})}.
\end{equation*}
 By Theorem 16.6 of \citet{Yagi2010}, the interpolation norm $\norm{}_{\gamma}\coloneq \norm{(-\Updelta)^{\gamma}\MTemptyplaceholder}_{L^2(\bar{\Lambda})}$ of the Neumann Laplacian on $\bar{\Lambda}$ is equivalent to the Sobolev norm $\norm{}_{H^{2\gamma}(\bar{\Lambda})}$, $0\le\gamma\le 1$. Since $\chi\in \operatorname{dom}(-\Updelta)^{(\tilde{s}-\epsilon)/2}$ and powers of $(-\Updelta)$ commute with its semi-group $t\mapsto G_t^1\star \MTemptyplaceholder$, we find
\begin{equation*}
    \norm{\chi-G_{\lambda^{-2}t}^1\star \chi}_{L^\infty(\bar{\Lambda})}\lesssim \norm{(-\Updelta)^{(\tilde{s}-\epsilon)/2}\chi - G_{\lambda^{-2}t}^1\star (-\Updelta)^{(\tilde{s}-\epsilon)/2}\chi}_{L^2(\bar{\Lambda})}.
\end{equation*}
Since the Neumann Laplacian generates an analytic semi-group $t\mapsto G_t^1\star \MTemptyplaceholder$ on $L^2(\bar{\Lambda})$, we can apply Theorem 6.13 (d) of \citet{Pazy1983} to deduce
\begin{equation*}
    \norm{\chi-G_{\lambda^{-2}t}^1\star \chi}_{L^\infty(\bar{\Lambda})}\lesssim (\lambda^{-2}t)^{\epsilon/2}\norm{(-\Updelta)^{\tilde{s}/2}\chi}_{\epsilon/2}\lesssim \lambda^{-\epsilon}t^{\epsilon/2}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}.
\end{equation*}\qedhere
\end{proof}

	%\subsubsection{Preliminaries on Green functions}
    \textbf{Step 1: Preliminaries on Green functions.}

