	\begin{lemma}\label{lem:DomainDifferences}
		Let $1\le\lambda<\infty$, $0<t\le T$, $y\in\Lambda$. Then
		\begin{align}
			\int_{\mathbb{R}}\abs{\phi_{t}(y,\eta) - G_{t}^\lambda(y,\eta)}\,\D\eta & \le 2\prob[y]{\tau_\lambda\le t},\label{eq:domainDifferences_Neu_1}                      \\
			\int_{\mathbb{R}}(\phi_{t}(y,\eta) - G_{t}^\lambda(y,\eta))^2\,\D\eta   & \le C t^{-1/2}\prob[y]{\tau_\lambda\le t}, \label{eq:domainDifferences_Neu_2}
		\end{align}
		where the constant $0<C<\infty$ depends only on $T$.
	\end{lemma}
	\begin{proof}
        The domain monotonicity \eqref{eq:Greenfunction_Monotonicity_neumann} implies for any Borel set $A\subset \mathbb{R}$, location $y\in \Lambda$ and time $0< t\le T$ the bound
		\begin{align*}
			\int_{A}\abs{G_t^\lambda(y,\eta) - \phi_t(y,\eta)}\,\D\eta &= \int_{A\cap \Lambda} (G_t^\lambda(y,\eta)-\phi_t(y,\eta))\,\D\eta + \int_{A\cap \Lambda^c}\phi_t(y,\eta)\,\D\eta\\
			&= \int_{A\cap \Lambda} G_t^\lambda(y,\eta)\,\D\eta -\int_{A\cap \Lambda}\phi_t(y,\eta)\,\D\eta + \int_{A\cap \Lambda^c}\phi_t(y,\eta)\,\D\eta.
		\end{align*}
		Recalling that $\phi_t$ and $G_t^\lambda$ are the transition kernels of $B_t$ and $B_{2t}^\leftrightarrow$, respectively, we find
		\begin{align*}
			\int_{A}\abs{G_t^\lambda(y,\eta) - \phi_t(y,\eta)}\,\D\eta & = \prob[y]{B_{2t}^\leftrightarrow\in A\cap \Lambda} - \prob[y]{B_{2t}\in A\cap \Lambda} + \prob[y]{B_{2t}\in A\cap \Lambda^c} \\
			  & = \prob[y]{B_{2t}^\leftrightarrow\in A\cap \Lambda } - \prob[y]{B_{2t}\in A} + 2 \prob[y]{B_{2t}\in A\cap \Lambda^c}              \\
			  & \le \prob[y]{B_{2t}^\leftrightarrow\in A\cap \Lambda} - \prob[y]{B_{2t}\in A} + 2\prob[y]{\tau_\lambda\le t}.
		\end{align*}
		Choosing $A=\mathbb{R}$ yields \eqref{eq:domainDifferences_Neu_1}. Since $G_t^\lambda(y,\eta) =\lambda^{-1} G_{\lambda^{-2} t}^1(\lambda^{-1}y,\lambda^{-1}\eta)$ by \eqref{eq:Scaling_Heat_Kernel}, where the latter is the Green kernel on $\bar{\Lambda}$, we can apply Theorem 3.2.9 of \citet{daviesHeatKernelsSpectral1990} to obtain
		\begin{equation}
			G_t^\lambda(y,\eta) = \lambda^{-1} G_{\lambda^{-2} t}^1(\lambda^{-1}y,\lambda^{-1}\eta)\lesssim \lambda^{-1}((\lambda^{-2} t)^{-1/2}\vee 1)\lesssim_T t^{-1/2} ,\quad y,\eta\in\Lambda.
		\end{equation}
		This implies the bound
		\begin{align*}
			\int_{\mathbb{R}}(G_t^\lambda(y,\eta) - \phi_t(y,\eta))^2\,\D\eta & \le \int_{\mathbb{R}} \max(G_t^\lambda(y,\eta), \phi_t(y,\eta))\abs{G_t^\lambda(y,\eta)-\phi_t(y,\eta)}\,\D\eta \\
			& \lesssim_{T}  t^{-1/2} \int_{\mathbb{R}}\abs{G_t^\lambda(y,\eta) - \phi_t(y,\eta)}\,\D\eta                          \\
			 & \lesssim t^{-1/2}\prob[y]{\tau_\lambda\le T}.
		\end{align*}\qedhere
	\end{proof}
	The following Lemma quantifies the convergence $\prob[\lambda\bar{y}]{\tau_\lambda\le t}\to 0$ as $\lambda\to\infty$ for any fixed $\bar{y}\in\bar{\Lambda}$ and follows by classical arguments.
	\begin{lemma}\label{lem:Stopping_time}
		For all $y\in\Lambda$ and $t> 0$ we have
		\begin{equation}
			\prob[y]{\tau_\lambda \le t}\lesssim 1\wedge \frac{\sqrt{t}}{\operatorname{dist}(y,\partial\Lambda)}\exp\left(-\frac{\operatorname{dist}(y,\partial\Lambda)^2}{4t}\right)\label{eq:Greenfunction_StoppingTimeEstimate}
		\end{equation}
		and
		\begin{equation}
			\frac{1}{\lambda}\int_\Lambda \sqrt{\prob[y]{\tau_\lambda\le T}}\,\D y \lesssim_T \lambda^{-1}.\label{eq:Greenfunction_IntegratedProb1}
		\end{equation}
	\end{lemma}
	\begin{proof}
		Using the estimate (2.8.3') of \citet{karatzasBrownianMotionStochastic1998} we can bound
		\begin{align*}
			\prob[y]{\tau_\lambda \le t} & =\prob[y]{\Exists 0\le s\le t\given  B_{2s}\in\partial\Lambda}\le \prob[y]{\max_{s\in[0,t]}\abs{B_{2s}-y}\ge \operatorname{dist}(y,\partial\Lambda)}        \\
			   & = \prob[0]{\max_{s\in[0,t]}\abs{B_{2s}}\ge \operatorname{dist}(y,\partial \Lambda)} = \prob[0]{\max_{s\in[0,t]}\abs{B_s}\ge \operatorname{dist}(y,\partial \Lambda)/\sqrt{2}} \\
	           & \le \sqrt{\frac{t}{\pi}}\frac{4}{\operatorname{dist}(y,\partial \Lambda)}\exp\left(-\frac{\operatorname{dist}(y,\partial \Lambda)^2}{4t}\right)                               \\
			%&=\prob[0]{\abs{B_t}\ge \operatorname{dist}(y,\partial\Lambda)}=\frac{2}{\sqrt{2\pi t}}\int_{\operatorname{dist}(y,\partial\Lambda)}^\infty \exp\left(-\frac{x^2}{2t}\right)\,\D x\\
			%&\le \frac{4}{\sqrt{2\pi}}\frac{\sqrt{t}}{\operatorname{dist}(y,\partial\Lambda)}\exp\left(-\frac{\operatorname{dist}(y,\partial\Lambda)^2}{2t}\right)\\
			     & \lesssim \frac{\sqrt{t}}{\operatorname{dist}(y,\partial\Lambda)}\exp\left(-\frac{\operatorname{dist}(y,\partial\Lambda)^2}{4t}\right).
		\end{align*}
		The bound \eqref{eq:Greenfunction_IntegratedProb1} follows from taking the square root and integrating over $y\in\Lambda$.
	\end{proof}


    \textbf{Step 2: A Gronwall argument.}\\
    The subsequent lemma follows from the semi-group property of the heat kernel and is the basis for the upcoming Gronwall argument.
	\begin{lemma}\label{lem:Convolution}
		Let $n\in\mathbb{N}_0$ and let $g\colon [0,T]\times\mathbb{R}\to\mathbb{R}_{\ge 0}$ be measurable. Then
		\begin{equation*}
			\int_0^t \bigg(G_{t-s}^\lambda\star \int_0^s (s-r)^n G_{s-r}^\lambda\star g(r,\MTemptyplaceholder)\,\D r\bigg)(y)\,\D s=(n+1)^{-1}\int_0^t (t-r)^{n+1} (G_{t-r}^\lambda \star g(r,\MTemptyplaceholder))(y)\,\D r
		\end{equation*}
		for all $0\le t\le T$ and $y\in\mathbb{R}$.
	\end{lemma}
	\begin{proof}
		Using $G_{t_1}\star G_{t_2}=G_{t_1+t_2}$ for any $0< t_1,t_2<\infty$ we compute
		\begin{align*}
			\int_0^t \left(G_{t-s}^\lambda\star \int_0^s (s-r)^n G_{s-r}^\lambda\star g(r,\MTemptyplaceholder)\,\D r\right)(y)\,\D s & = \int_0^t \int_0^s (s-r)^n (G_{t-s}^\lambda\star (G_{s-r}^\lambda \star g(r,\MTemptyplaceholder)))(y)\,\D r\D s \\
			 & = \int_0^t\int_0^s (s-r)^n (G_{t-r}^\lambda \star g(r,\MTemptyplaceholder))(y)\,\D r\D s                     \\
	       & =\int_0^t (G_{t-r}^\lambda \star g(r,\MTemptyplaceholder))(y) \int_r^t (s-r)^n\,\D s\D r                     \\
	       & =(n+1)^{-1}\int_0^t (t-r)^{n+1} (G_{t-r}^\lambda \star g(r,\MTemptyplaceholder))(y)\,\D r.
		\end{align*}\qedhere
	\end{proof}
	We continue with a Gronwall argument based on Lemma \ref{lem:Convolution} and represent $Z_t(y)-X_t(y)$ in terms of differences of the Green functions $G_t^\lambda$ and $\phi_t$ in Lemma \ref{lem:Expansion/Gronwall}. Subsequently, Lemma \ref{lem:Aux_Convergence} bounds the terms individually using Lemmas \ref{lem:DomainDifferences} and \ref{lem:Stopping_time}.

	\begin{lemma}\label{lem:Expansion/Gronwall}
		Assume that $f\colon\mathbb{R}\to\mathbb{R}$ is Lipschitz-continuous. Let $y=\lambda\bar{y}\in\Lambda$ and $0\le t\le T$. We can bound
		\begin{align*}
			\abs{Z_t^{\bar{y}}(y)-X_t(y)}^p&\lesssim_{p,T,\Lip{f}}\abs{\bar{Z}^{\bar{y}}_t(y)-\bar{X}_t(y)}^p\\
            & \quad  +\prob[y]{\tau_\lambda\le t}^{p-1}\int_0^t(\abs{\phi_{t-s}-G_{t-s}^\lambda}\star\abs{f(Z_s^{\bar{y}})}^p)(y)\,\D s\\
            & \quad +\int_0^t (G_{t-s}^\lambda \star\abs{\bar{Z}_s^{\bar{y}}-\bar{X}_s}^p)(y)\,\D s\\
            & \quad +\int_0^t \left(G_{t-s}^\lambda \star\left(\prob[\MTemptyplaceholder]{\tau_\lambda\le t}^{p-1}\int_0^s \abs{\phi_{s-r}-G_{s-r}^\lambda}\star \abs{f(Z_r^{\bar{y}})}^p\,\D r\right)\right)(y)\,\D s,
		\end{align*}
		where the hidden constant in $\lesssim$ depends only on $p$, $T$, $\Lip{f}$ and $\norm{\chi}_{L^\infty(\bar{\Lambda})}$.
	\end{lemma}


	\begin{proof}
		\textbf{Step 1 ($p=1$ using a Gronwall expansion).} First expanding $X_t-Z_t^{\bar{y}}$ using \eqref{eq:ConvGlobal_Z} and \eqref{eq:ConvGlobal_X} into their linear and nonlinear parts, then using the triangle inequality for $\abs{\MTemptyplaceholder}$ and finally using the Lipschitz-continuity of $f$, we find
		\begin{align}
			\abs{Z_t^{\bar{y}}(y) -X_t(y)}\hspace{-0em} & \hspace{0em}\le \abs{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)} + \abs[\bigg]{\int_0^t (\phi_{t-s}\star f(Z_s^{\bar{y}}))(y) - (G_{t-s}^\lambda\star f(X_s))(y)\,\D s}\nonumber \\
            & \le \abs[bigg]{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)} + \abs[\bigg]{\int_0^t ((\phi_{t-s}-G_{t-s}^\lambda)\star f(Z_s^{\bar{y}}))(y)\,\D s} \nonumber  \\
            & \quad +\abs[\bigg]{\int_0^t (G_{t-s}^\lambda\star (f(X_s) - f(Z_s^{\bar{y}})))(y)\,\D s}\nonumber \\
            & \le\abs{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)} + \int_0^t (\abs{\phi_{t-s}-G_{t-s}^\lambda}\star \abs{f(Z_s^{\bar{y}})})(y)\,\D s \nonumber\\
            & \quad +\Lip{f} \int_0^t (G_{t-s}^\lambda\star \abs{X_s - Z_s^{\bar{y}}})(y)\,\D s.\label{eq:Conv_aux_lastSummand}
		\end{align}
		Analogously expanding \eqref{eq:Conv_aux_lastSummand} yields the expression
		\begin{align*}
			\int_0^t (G_{t-s}^\lambda\star \abs{X_s - Z_s^{\bar{y}}})(y)\,\D s \hspace{-0em} & \hspace{0em}\le  \int_0^t (G_{t-s}^\lambda\star \abs{\bar{Z}_s^{\bar{y}}-\bar{X}_s})(y)\,\D s\\
            & \quad + \int_0^t \left(G_{t-s}^\lambda\star \int_0^s \abs{\phi_{s-r}-G_{s-r}^\lambda}\star \abs{f(Z_r^{\bar{y}})}\,\D r\right)(y)\,\D s        \\
            & \quad + \Lip{f}\int_0^t \left(G_{t-s}^\lambda\star \int_0^s G_{s-r}^\lambda\star \abs{X_r - Z_r^{\bar{y}}}\,\D r\right)(y)\,\D s.
		\end{align*}
		Lemma \ref{lem:Convolution} with $n=0$ and $g(r,\eta)=\abs{X_t(\eta) - Z_t^{\bar{y}}(\eta)}$ implies
		\begin{equation*}
			\int_0^t \bigg(G_{t-s}^\lambda\star \int_0^s G_{s-r}^\lambda\star \abs{X_r- Z_r^{\bar{y}}}\,\D r\bigg)(y)\,\D s = \int_0^t (t-s) (G_{t-s}^\lambda\star \abs{X_s - Z_s^{\bar{y}}})(y)\,\D s.
		\end{equation*}
		%  \begin{align*}
		%  \abs{Z_t(y) -X_t(y)}\hspace{-7em}&\hspace{7em}\le \abs{\bar{Z}_t(y)-\bar{X}_t(y)} + \int_0^t ((\abs{\phi_{t-s}-G_{t-s}^\lambda})\star \abs{f(Z_s)})(y)\,\D s\\
		%		&\quad +\Lip{f} \int_0^t (G_{t-s}^\lambda\star \abs{\bar{Z}_s-\bar{X}_s})(y)\,\D s + \Lip{f}\int_0^t (G_{t-s}^\lambda\star \int_0^s (\abs{\phi_{s-r}-G_{s-r}^\lambda})\star \abs{f(Z_r)})\,\D r)(y)\,\D s \\
		%		&\quad +\Lip{f}^2\int_0^t (G_{t-s}^\lambda\star \int_0^s (G_{s-r}^\lambda\star \abs{X_r- Z_r})(y)\,\D r)(y)\,\D s\\
		%		&= \abs{\bar{Z}_t(y)-\bar{X}_t(y)} + \int_0^t ((\abs{\phi_{t-s}-G_{t-s}^\lambda})\star \abs{f(Z_s)})(y)\,\D s \\
		%		&\quad +\Lip{f} \int_0^t (G_{t-s}^\lambda\star \abs{\bar{Z}_s-\bar{X}_s})(y)\,\D s + \Lip{f}\int_0^t (G_{t-s}^\lambda\star \int_0^s (\abs{\phi_{s-r}-G_{s-r}^\lambda})\star \abs{f(Z_r)})(y)\,\D r)(y)\,\D s \\
		%		&\quad +\Lip{f}^2\int_0^t (t-s) (G_{t-s}^\lambda\star \abs{X_s - Z_s}))(y)\,\D s.
		%  \end{align*}
		%Recursively, for $N\in\mathbb{N}$, we find
		%\begin{align*}
		%		&\le \textcolor{blue}{\abs{\bar{Z}_t(y)-\bar{X}_t(y)} + \int_0^t ((\abs{\phi_{t-s}-G_{t-s}^\lambda})\star \abs{f(Z_s)})(y)\,\D s} \\
		%	&\quad +\textcolor{orange}{\Lip{f} \int_0^t (G_{t-s}^\lambda\star \abs{\bar{Z}_s-\bar{X}_s})(y)\,\D s + \Lip{f}\int_0^t (G_{t-s}^\lambda\star \int_0^s (\abs{\phi_{s-r}-G_{s-r}^\lambda})\star \abs{f(Z_r)})\,\D r)(y)\,\D s} +\\
		%	&\quad \textcolor{red}{\Lip{f}^2\int_0^t (t-s) (G_{t-s}^\lambda\star \abs{\bar{X}_s - \bar{Z}_s})(y))(y)\,\D s + \Lip{f}^2\int_0^t (t-s)G_{t-s}^\lambda \star \int_0^s (\abs{\phi_{s-r}-G_{s-r}^\lambda})\star \abs{f(Z_r)})\,\D r)(y)\,\D s}+\\
		%	&\quad\textcolor{green}{\frac{\Lip{f}^3}{2}\int_0^t (t-s)^2 (G_{t-s}^\lambda\star \abs{X_s - Z_s}))(y)\,\D s}.
		%\end{align*}
		Recursively, we obtain for any $N\in\mathbb{N}$ the bound
		\begin{align*}
			\abs{Z_t^{\bar{y}}(y)-X_t(y)}\hspace{-3em} & \hspace{3em}\le \abs{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)} +\int_0^t(\abs{\phi_{t-s}-G_{t-s}^\lambda}\star\abs{f(Z_s^{\bar{y}})})(y)\,\D s\\
            & \quad +\sum_{n=0}^N\frac{\Lip{f}^{n+1}}{n!}\int_0^t (t-s)^{n}(G_{t-s}^\lambda \star\abs{\bar{Z}_s^{\bar{y}}-\bar{X}_s})(y)\,\D s\\
            & \quad +\sum_{n=0}^N\frac{\Lip{f}^{n+1}}{n!}\int_0^t (t-s)^{n}\bigg(G_{t-s}^\lambda \star\int_0^s \abs{\phi_{s-r}-G_{s-r}^\lambda}\star \abs{f(Z_r^{\bar{y}})}\,\D r\bigg)(y)\,\D s \\
            & \quad +R_N,
		\end{align*}
		with \begin{align*}
			R_N & = \frac{\Lip{f}^{N+2}}{(N+1)!}\int_0^t (t-s)^{N+1}(G_{t-s}^\lambda\star \abs{X_s - Z_s^{\bar{y}}})(y)\,\D s\\
            & \le \sup_{\eta\in\mathbb{R},s\in [0,T]} (\abs{X_s(\eta)} + \abs{Z_s^{\bar{y}}(\eta)})\frac{\Lip{f}^{N+2}}{(N+1)!}\int_0^t (t-s)^{N+1}(G_{t-s}^\lambda\star 1)(y)\,\D s \\
            & \lesssim \frac{\Lip{f}^{N+2}}{(N+1)!}\int_0^t (t-s)^{N+1}\,\D s\lesssim  \frac{\Lip{f}^{N+2}}{(N+2)!}\xrightarrow{N\to\infty} 0,
		\end{align*}
		uniformly in $1\le\lambda<\infty$ by Lemma \ref{lem:UniformBoudnednessSolution} and Theorem 4.3 of \citet{Dalang2011}. This implies the representation
		\begin{align*}
			\abs{Z_t^{\bar{y}}(y)-X_t(y)}&\le \abs{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)} +\int_0^t(\abs{\phi_{t-s}-G_{t-s}^\lambda}\star\abs{f(Z_s^{\bar{y}})})(y)\,\D s\\
            & \quad +\sum_{n\in\mathbb{N}_0}\frac{\Lip{f}^{n+1}}{n!}\int_0^t (t-s)^{n}(G_{t-s}^\lambda \star\abs{\bar{Z}_s^{\bar{y}}-\bar{X}_s})(y)\,\D s \\
            & \quad +\sum_{n\in\mathbb{N}_0}\frac{\Lip{f}^{n+1}}{n!}\int_0^t (t-s)^{n}\bigg(G_{t-s}^\lambda \star\int_0^s \abs{\phi_{s-r}-G_{s-r}^\lambda}\star \abs{f(Z_r^{\bar{y}})}\,\D r\bigg)(y)\,\D s.
		\end{align*}
		Estimating $t-s\le t$ and using the exponential series, we obtain
		\begin{align*}
			\abs{Z_t^{\bar{y}}(y)-X_t(y)} & \le \abs{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)} +\int_0^t(\abs{\phi_{t-s}-G_{t-s}^\lambda}\star\abs{f(Z_s^{\bar{y}})})(y)\,\D s\\
            & \quad +\Lip{f} e^{\Lip{f} t}\int_0^t (G_{t-s}^\lambda \star\abs{\bar{Z}_s^{\bar{y}}-\bar{X}_s})(y)\,\D s\\
            & \quad +\Lip{f} e^{\Lip{f} t} \int_0^t \bigg(G_{t-s}^\lambda \star\int_0^s (\phi_{s-r}-G_{s-r}^\lambda)\star \abs{f(Z_r^{\bar{y}})}\,\D r\bigg)(y)\,\D s.
		\end{align*}
		\textbf{Step 2 ($p\ge 1$ using Jensen's inequality).} Note that $G_{t-s}^\lambda(y,\eta)\D\eta$ and $\abs{\phi_{t-s}(y,\eta)-G_{t-s}^\lambda(y,\eta)}\D \eta$ are finite measures (with total mass $= 1$ and $\le2\prob[y]{\tau_\lambda\le t-s}$, respectively) for all $0\le s\le t\le T$ and $y\in\mathbb{R}$ by Lemma \ref{lem:DomainDifferences}. We can use Jensen's inequality to infer for any $p\ge1$ the bound
		\begin{align*}
			\abs{Z_t^{\bar{y}}(y)-X_t(y)}^p&\lesssim_{p,T} \abs{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)}^p\\
            & \quad +\prob[y]{\tau_\lambda\le t}^{p-1}\int_0^t(\abs{\phi_{t-s}-G_{t-s}^\lambda}\star\abs{f(Z_s^{\bar{y}})}^p)(y)\,\D s\\
            & \quad +\Lip{f}^pe^{p\Lip{f} t}\bigg[\int_0^t (G_{t-s}^\lambda \star\abs{\bar{Z}_s^{\bar{y}}-\bar{X}_s}^p)(y)\,\D s\\
            & \quad +\int_0^t \bigg(G_{t-s}^\lambda \star\bigg(\prob[\MTemptyplaceholder]{\tau_\lambda\le t}^{p-1}\int_0^s \abs{\phi_{s-r}-G_{s-r}^\lambda}\star \abs{f(Z_r^{\bar{y}})}^p\,\D r\bigg)\bigg)(y)\,\D s\bigg] \\
            & \lesssim_{T,\Lip{f}}\abs{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)}^p +\prob[y]{\tau_\lambda\le t}^{p-1}\int_0^t(\abs{\phi_{t-s}-G_{t-s}^\lambda}\star\abs{f(Z_s^{\bar{y}})}^p)(y)\,\D s\\
            & \quad +\int_0^t (G_{t-s}^\lambda \star\abs{\bar{Z}_s^{\bar{y}}-\bar{X}_s}^p)(y)\,\D s\\
            & \quad +\int_0^t \left(G_{t-s}^\lambda \star\left(\prob[\MTemptyplaceholder]{\tau_\lambda\le t}^{p-1}\int_0^s \abs{\phi_{s-r}-G_{s-r}^\lambda}\star \abs{f(Z_r^{\bar{y}})}^p\,\D r\right)\right)(y)\,\D s.
		\end{align*}\qedhere
	\end{proof}
	\begin{lemma}\label{lem:Aux_Convergence}
		Assume that $f\colon\mathbb{R}\to\mathbb{R}$ is globally Lipschitz-continuous and that $\chi\in H^{\tilde{s}}(\bar{\Lambda})$ for some $\tilde{s}>1/2$. Let $0<\epsilon<\tilde{s}-1/2$, $p\ge 1$ and $y=\lambda\bar{y}\in\Lambda$. We have the following bounds, where the hidden constant in $\lesssim$ does not depend on the time $0\le t\le T$, location $y\in\Lambda$ or domain size $1\le\lambda<\infty$.
		\begin{enumerate}[(a)]
			\item\label{num:Aux_convergence_a} Linear part I:
			      \begin{align*}
				      \EV[f]{\abs{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)}^p} %&
                      %\lesssim_p \Big(\int_0^t \int_{\mathbb{R}}(\phi_{t-s}(y,\eta)-G_{t-s}^\lambda(y,\eta))^2\,\D \eta\D s\Big)^{p/2}\\
                      & \lesssim_{T,p} t^{p/4}\prob[y]{\tau_\lambda\le t}^{p/2}+t^{p\epsilon/2}\lambda^{-p\epsilon}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}^p.
			      \end{align*}
			\item\label{num:Aux_convergence_b} Linear part II:
			      \begin{equation*}
				      \EV[f][][\bigg]{\int_0^t (G_{t-s}^\lambda\star \abs{\bar{Z}_s^{\bar{y}}-\bar{X}_s}^p)(y)\D s}
                      %& \lesssim_p \int_0^t \int_{\mathbb{R}}G_{t-s}^\lambda(y,z)\Big(\int_0^s \int_{\mathbb{R}}(\phi_{s-r}(z,\eta)-G_{s-r}^\lambda(z,\eta))^2\,\D\eta\D r\Big)^{p/2}\D z\D s \\
                       \lesssim_{T,p} K(y,\lambda,p) + t^{p\epsilon/2+1}\lambda^{-p\epsilon}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}^p.
			      \end{equation*}
			\item Remainder I:
			      \begin{equation*}
				      \prob[y]{\tau_\lambda\le t}^{p-1}\EV[f][][\bigg]{\int_0^t \abs{\phi_{t-s}-G_{t-s}^\lambda}\star \abs{f(Z_s^{\bar{y}})}^p)(y)\,\D s}\lesssim_{T,\Lip{f},p} t\prob[y]{\tau_\lambda\le t}^p.
			      \end{equation*}
			\item  Remainder II:
			      \begin{align*}
				      \EV[f][][\bigg]{\int_0^t \left(G_{t-s}^\lambda \star\left(\prob[\MTemptyplaceholder]{\tau_\lambda\le t}^{p-1}\int_0^s \abs{\phi_{s-r}-G_{s-r}^\lambda}\star \abs{f(Z_r^{\bar{y}})}^p\,\D r\right)\right)(y)\,\D s}\hspace{-10em} &\\
                      & \lesssim_{T,\Lip{f},p}K(y,\lambda,2p).
			      \end{align*}
		\end{enumerate}
	\end{lemma}
	\begin{proof}~
		\begin{enumerate}[(a)]
			\item Using the triangle inequality, Gaussian hypercontractivity and Itô's isometry we can write
            \begin{align*}
                \EV[f]{\abs{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)}^p}&\lesssim_p  \EV[f][][\bigg]{\abs[\bigg]{\int_0^t\int_{\mathbb{R}} (\phi_{t-s}(y,\eta)-G_{t-s}^\lambda(y,\eta)) \mathcal{W}(\D\eta,\D s)}^p}\\
                &\quad+ \abs{X_0(y) - (G_t^\lambda \star X_0)(y)}^p\\
                &\lesssim_p \Big(\int_0^t \int_{\mathbb{R}}(\phi_{t-s}(y,\eta)-G_{t-s}^\lambda(y,\eta))^2\,\D\eta\D s\Big)^{p/2}\\
                &\quad+ \abs{X_0(y) - (G_t^\lambda \star X_0)(y)}^p.
            \end{align*}
            The claim follows Lemmas \ref{lem:DomainDifferences} and \ref{lem:Impact_Initial_Condition}.
			\item Using the triangle inequality, Gaussian hypercontractivity and Itô's isometry we find 
            \begin{align*}
                \EV[f][][\bigg]{\int_0^t (G_{t-s}^\lambda\star \abs{\bar{Z}_s^{\bar{y}}-\bar{X}_s}^p)(y)\,\D s}\hspace{-4em} &\\
                      &\lesssim_p \int_0^t \int_{\Lambda}G_{t-s}^\lambda(y,z)\Big(\int_0^s \int_{\mathbb{R}}(\phi_{s-r}(z,\eta)-G_{s-r}^\lambda(z,\eta))^2\,\D\eta\D r\Big)^{p/2}\D z\D s\\
                      &\quad+ \int_0^t (G_{t-s}^\lambda \star \abs{X_0(y)-G_s^\lambda\star X_0}^p)(y)\,\D s.
            \end{align*}
            By Lemma \ref{lem:Impact_Initial_Condition} the second summand is bounded by $C t^{p\epsilon/2+1}\lambda^{-p\epsilon}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}^p$ for some constant $0<C<\infty$ depending on $p$. We proceed by bounding the first summand. 
            Take some $h=h(\lambda)>0$ such that $h<\operatorname{diam}(\bar{\Lambda})/2$ and set $\mathcal{C}_h = (B_h(0)+\partial \bar{\Lambda})\cap \bar{\Lambda}$. Using first Itô's isometry, then the Property \eqref{num:Aux_convergence_a} and finally the bound \eqref{eq:Greenfunction_StoppingTimeEstimate}, we compute
			      \begin{align}
				      \int_0^t \int_{\Lambda}G_{t-s}^\lambda(y,z)\Big(\int_0^s \int_{\mathbb{R}}(\phi_{s-r}(z,\eta)-G_{s-r}^\lambda(z,\eta))^2\,\D\eta\D r\Big)^{p/2}\D z\D s\hspace{-25em}&\nonumber\\
                      & \lesssim_{T}\int_0^t  \int_{\Lambda}G_{t-s}^\lambda(y,z)\prob[z]{\tau_\lambda\le T}^{p/2}\,\D z\D s\label{eq:Convergence_Global_aux1}\\
                      & =\lambda\int_0^t  \int_{\bar{\Lambda}}G_{t-s}^\lambda(y,\lambda z)\prob[\lambda z]{\tau_\lambda\le T}^{p/2}\,\D z\D s\nonumber\\
                      & \lesssim_T \lambda\int_0^t  \int_{\bar{\Lambda}\setminus \mathcal{C}_h}G_{t-s}^\lambda(y,\lambda z)\frac{\exp\left(-\frac{p\lambda^2\operatorname{dist}(z,\partial\bar{\Lambda})^2}{8 T}\right)}{\lambda^{p/2}\operatorname{dist}(z,\partial\bar{\Lambda})^{p/2}}\,\D z\D s+ +\lambda\int_0^t  \int_{ \mathcal{C}_h}G_{t-s}^\lambda(y,\lambda z)\,\D z\D s\nonumber  \\
                      & \lesssim_T \lambda \int_0^t  \int_{\bar{\Lambda}\setminus \mathcal{C}_h}G_{t-s}^\lambda(y,\lambda z)\frac{\exp\left(-\frac{p\lambda^2\operatorname{dist}(z,\partial\bar{\Lambda})^2}{8 T}\right)}{\lambda^{p/2}\operatorname{dist}(z,\partial\bar{\Lambda})^{p/2}}\,\D z\D s+\lambda h\nonumber \\
                      & =\colon I + \lambda h\nonumber.
			      \end{align}
			      Recall the scaling of the heat kernel from \eqref{eq:Scaling_Heat_Kernel}. Applying the bound $G_t^1\lesssim_{T} \phi_{ct}$, for $0\le t\le T$ and any constant $c>1$ from Theorem 3.2.9 of \citet{daviesHeatKernelsSpectral1990}, we obtain
			      \begin{align*}
				      I & =\int_0^t  \int_{\bar{\Lambda}\setminus \mathcal{C}_h}G_{\lambda^{-2}(t-s)}^1(\lambda^{-1}y,z)\frac{\exp\left(-\frac{p\lambda^2\operatorname{dist}(z,\partial \bar{\Lambda})^2}{8 T}\right)}{\lambda^{p/2}\operatorname{dist}(z,\partial \bar{\Lambda})^{p/2}}\,\D z\D s                                                                      \\
				        & \lesssim_{T}\lambda\int_0^t  (t-s)^{-1/2}\int_{\bar{\Lambda}\setminus \mathcal{C}_h}\frac{\exp\left(-\frac{\lambda^2(\lambda^{-1}y-z)^2}{4c (t-s)}\right)\exp\left(-\frac{p\lambda^2\operatorname{dist}(z,\partial \bar{\Lambda})^2}{8 T}\right)}{\lambda^{p/2}\operatorname{dist}(z,\partial \bar{\Lambda})^{p/2}}\,\D z\D s \\
				        & \le \lambda^{1-p/2}\int_0^t  (t-s)^{-1/2}\int_{\bar{\Lambda}\setminus \mathcal{C}_h}\frac{\exp\left(-\frac{\lambda^2(\lambda^{-1}y-z)^2}{8c T}\right)\exp\left(-\frac{\lambda^2\operatorname{dist}(z,\partial \bar{\Lambda})^2}{8c T}\right)}{\operatorname{dist}(z,\partial \bar{\Lambda})^{p/2}}\,\D z\D s.                          %\\
				      %&\le \nu^{-1/2}\int_0^t (t-s)^{-1/2}  \int_{\Lambda\setminus \mathcal{C}_h}\exp\left(-\frac{(y-z)^2}{4\nu T}\right)\exp\left(-\frac{\operatorname{dist}(z,\partial \Lambda)^2}{4\nu T}\right)\\
				      %&\quad \exp\left(-(p-1)\frac{\operatorname{dist}(z,\partial \Lambda)^2}{4\nu T}\right)(\operatorname{dist}(z,\partial \Lambda))^{-p/2}\nu^{p/4}\,\D z\D s.
			      \end{align*}
			      Since\footnote{Consider two cases: If $a$ and $b$ project to the same boundary point $p$, use triangle inequality. Otherwise, with projection points $p_{a},p_b\in\partial\bar{\Lambda}$, we find $\abs{p_{a}-a}=\operatorname{dist}(a,\partial\bar{\Lambda}) \le \abs{p_b-a}=\abs{p_b-b}+\abs{b-a}$.}
			      \begin{equation*}
				      \operatorname{dist}(a,\partial \bar{\Lambda})\le \abs{a-b} + \operatorname{dist}(b,\partial \bar{\Lambda}),\quad a,b\in\bar{\Lambda},
			      \end{equation*}
			      we find
			      \begin{align*}
				      I & \lesssim \lambda^{1-p/2}\exp\left(-\frac{\lambda^2\operatorname{dist}(\lambda^{-1}y,\partial\bar{\Lambda})^2}{16c T}\right)\int_0^t (t-s)^{-1/2}\D s \int_{\bar{\Lambda}\setminus \mathcal{C}_h}\operatorname{dist}(z,\partial \bar{\Lambda})^{-p/2}\,\D z \\
				        & \lesssim_{T,p} \lambda^{1-p/2}\exp\left(-\frac{\lambda^2\operatorname{dist}(\lambda^{-1}y,\partial \bar{\Lambda})^2}{16c T}\right) \begin{cases}\log(h^{-1}),&p=2,\\ h^{-p/2+1},&p\neq 2.\end{cases}
			      \end{align*}
			      Define $\zeta\coloneq \exp\left(-\frac{\lambda^2\operatorname{dist}(\lambda^{-1}y,\partial \bar{\Lambda})^2}{16c T}\right)$, then the choice $h=\zeta^{2/p}/\lambda$ ensures that
			      \begin{align*}
				      \int_0^t \int_{\Lambda}G_{t-s}^\lambda(y,z)\Big(\int_0^s \int_{\mathbb{R}}(\phi_{s-r}(z,\eta)-G_{s-r}^\lambda(z,\eta))^2\,\D\eta\D r\Big)^{p/2}\D z\D s\hspace{-24em} &\\
                      & \lesssim_{T,p} \lambda h + \lambda^{1-p/2}\zeta \begin{cases}\log(h^{-1}),&p=2,\\h^{1-p/2},&p\neq 2,\end{cases}\\
                      & \lesssim_{T,p} \zeta^{2/p}\begin{cases}(1 + \log(\lambda) + \operatorname{dist}(\lambda^{-1}y,\partial\bar{\Lambda})^2),&p=2\\ 2,& p\neq 2,\end{cases} \\
                      & =K(y,\lambda,p).
			      \end{align*}
			\item Using Lemma \ref{lem:DomainDifferences} in the second estimate we compute
			      \begin{align*}
				      \prob[y]{\tau_\lambda\le t}^{p-1}\EV[f][][\bigg]{\int_0^t (\abs{\phi_{t-s}-G_{t-s}^\lambda}\star \abs{f(Z_s^{\bar{y}})}^p)(y)\,\D s}\hspace{-17em} &\\
                      & \lesssim \prob[y]{\tau_\lambda\le t}^{p-1}\sup_{\eta\in\mathbb{R}, s\in[0,T]}\EV[f]{\abs{f(Z_s^{\bar{y}}(\eta))}^p}\int_0^t\int_{\mathbb{R}}\abs{\phi_{t-s}(y,\eta)-G_{t-s}^\lambda(y,\eta)}\,\D\eta\D s \\
                      & \le 2\prob[y]{\tau_\lambda\le t}^{p-1}\sup_{\eta\in\mathbb{R}, s\in[0,T]}\EV[f]{\abs{f(Z_s^{\bar{y}}(\eta))}^p}\int_0^t\prob[y]{\tau_\lambda\le t-s}\,\D s\\
                      & \lesssim\sup_{\eta\in\mathbb{R}, s\in[0,T]}\EV[f]{\abs{f(Z_s^{\bar{y}}(\eta))}^p}t\prob[y]{\tau_\lambda\le t}^p.
			      \end{align*}
			      The claim follows by noting $\sup_{\eta\in\mathbb{R}, s\in[0,T]}\EV[f]{\abs{f(Z_s^{\bar{y}}(\eta))}^p}\le \tilde{C}$ for some constant $0<\tilde{C}<\infty$ depending on $T$, $\Lip{f}$, $p$ and $\norm{\chi}_{L^\infty(\bar{\Lambda})}$ by Theorem 4.3 of \citet{Dalang2011}.
			\item Using Lemma \ref{lem:DomainDifferences} and Theorem 4.3 of \citet{Dalang2011} in the second estimate we compute
			      \begin{align*}
				      \EV[f][][\bigg]{\int_0^t \left(G_{t-s}^\lambda \star\left(\prob[\MTemptyplaceholder]{\tau_\lambda\le t}^{p-1}\int_0^s \abs{\phi_{s-r}-G_{s-r}^\lambda}\star \abs{f(Z_r^{\bar{y}})}^p\,\D r\right)\right)(y)\,\D s}\hspace{-22em} & \\
                      & \le \sup_{\eta\in\mathbb{R}, s\in[0,T]}\EV[f]{\abs{f(Z_s^{\bar{y}}(\eta))}^p}\\
                      & \quad \int_0^t \int_{\Lambda} G_{t-s}^\lambda(y,z)\prob[z]{\tau_\lambda\le t}^{p-1} \int_0^s \int_{\mathbb{R}}\abs{\phi_{s-r}(z,\eta)-G_{s-r}^\lambda(z,\eta)}\,\D\eta \D r\D z\D s \\
                      & \lesssim_{T,\Lip{f},p,\norm{\chi}_{L^\infty(\bar{\Lambda})}}\int_0^t \int_{\Lambda} G_{t-s}^\lambda(y,z)\prob[z]{\tau_\lambda\le s}^p\, \D z\D s.
			      \end{align*}
			      Proceeding exactly as in the proof of Property \eqref{num:Aux_convergence_b} with $2p$ instead of $p$ (compare \eqref{eq:Convergence_Global_aux1}), we find
			      \begin{equation*}
				      \EV[f][][\bigg]{\int_0^t \left(G_{t-s}^\lambda \star\left(\prob[\MTemptyplaceholder]{\tau_\lambda\le t}^{p-1}\int_0^s \abs{\phi_{s-r}-G_{s-r}^\lambda}\star \abs{f(Z_r^{\bar{y}})}^p\,\D r\right)\right)(y)\,\D s} \lesssim_{T,\Lip{f},p} K(y,\lambda,2p).
			      \end{equation*}
		\end{enumerate}
	\end{proof}


	\subsubsection{Proof of Proposition \ref{prop:Convergencetoglobal}}\label{subsec:Proof_Convergence_global}

	\begin{proof}[Proof of Proposition \ref{prop:Convergencetoglobal}]
		Using first Lemma \ref{lem:Expansion/Gronwall} and then Lemma \ref{lem:Aux_Convergence} implies
		\begin{align*}
			\EV[f]{\abs{Z_t^{\bar{y}}(y)-X_t(y)}^p}\hspace{-6em} & \hspace{6em}\lesssim_{p,T,\Lip{f}}\EV[f]{\abs{\bar{Z}_t^{\bar{y}}(y)-\bar{X}_t(y)}^p}\\
            &\quad +\EV[f][][\bigg]{\int_0^t (G_{t-s}^\lambda \star\abs{\bar{Z}_s^{\bar{y}}-\bar{X}_s}^p)(y)\,\D s}\\
            & \quad + \prob[y]{\tau_\lambda\le t}^{p-1}\EV[f][][\bigg]{\int_0^t(\abs{\phi_{t-s}-G_{t-s}^\lambda}\star\abs{f(Z_s^{\bar{y}})}^p)(y)\,\D s}\\
            & \quad+\EV[f][][\bigg]{\int_0^t \left(G_{t-s}^\lambda \star\left(\prob[\MTemptyplaceholder]{\tau_\lambda\le t}^{p-1}\int_0^s \abs{\phi_{s-r}-G_{s-r}^\lambda}\star \abs{f(Z_r^{\bar{y}})}^p\,\D r\right)\right)(y)\,\D s} \\
            & \lesssim_{T,\Lip{f},p} t^{p/4}\prob[y]{\tau_\lambda\le t}^{p/2}+t^{p\epsilon/2}\lambda^{-p\epsilon}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}^p+t \prob[y]{\tau_\lambda\le t}^p\\
            &\quad +t^{p\epsilon/2+1}\lambda^{-p\epsilon}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}^p+K(y,\lambda,p)+K(y,\lambda,2p)\\
            & \lesssim_{T} \prob[y]{\tau_\lambda\le t}^{p/2}+ K(y,\lambda,p)+K(y,\lambda,2p)+\lambda^{-p\epsilon}\norm{\chi}_{H^{\tilde{s}}(\bar{\Lambda})}^p,
		\end{align*}
        which shows \eqref{eq:ConvergenceGlobal_Claim}. Given the bound \eqref{eq:ConvergenceGlobal_Claim}, the claimed convergence of $X_t(\lambda\bar{y})$ to $Z_t^{\bar{y}}(0)$ follows from $Z_t^{\bar{y}}(y)\overset{d}{=}Z_t^{\bar{y}}(0)$ for all $y\in\mathbb{R}$ and $0\le t\le T$ by Lemma 7.1 of \citet{chenSpatialErgodicitySPDEs2021}.
	\end{proof}
