\section{Appendix A: Proofs of Theorem~\ref{thm:main} and Lemma~\ref{lem:kick-to-kick-permanence-implies-flow-kick-permanence}}\label{proof:main_theorem}
To prove Theorem~\ref{thm:main}, I use a characterization of permanence for maps due to \citet{hofbauer-so-1989-persistence}. To state this characterization, recall that the stable set $W^s(A)$ for an invariant set $A\subset \S$ for $\kappa$ is 
\[
W^s(A)=\{z\in \S: \omega(z)\subset A\}.
\]
Let $\{M_1,\dots,M_\ell\}$ be a Morse decomposition of $\Gamma_0$. 

\begin{theorem}[\citet{hofbauer-so-1989-persistence}]\label{thm:hofbauer-so} Assume each Morse set $M_i$ is isolated with respect to $\S$ i.e. $M_i$ is the largest invariant set in some neighborhood $U_i\subset \S$ of $M_i$. Then \eqref{eq:flow-kick} is permanent if and only if $W^s(M_i)\subset \S_0$ for all $i$
\end{theorem}


To use Theorem~\ref{thm:hofbauer-so}, one needs to verify two properties for each Morse set $M_i$: (i) $W^s(M_i)\subset \S_0$ and (ii) $M_i$ is isolated in $\S$. Let $M_i$ be a Morse set.   Lemma~\ref{lem:key:one} holds the key to verifying both properties.    

\begin{proof}[Proof of Lemma~\ref{lem:key:one}.]
Let $\tilde z\in \S_+$. Define a sequence of probability measures $\mu_n$ by 
\[
\int h(z)\mu_{n}(dz)=\frac{1}{n}\sum_{m=1}^{n} h(\kappa^m(\tilde z)) \mbox{ for all continuous functions }h:\S\to\R 
\]
i.e. the time average of the forward orbit of $\tilde z$ until time $n$. By assumption \textbf{A5}
and weak* compactness, there is a subsequence $n_\ell \to \infty$ such that $\mu_{n_\ell}$ converges in the weak* topology to  a Borel probability measure $\mu$ as $\ell\to\infty$. By the definition of $\mu_n$ and weak* convergence, $\mu(\omega(\tilde z))=1$. By assumption \textbf{A5}, $\omega(\tilde z)\subset \Gamma$. I claim that $\mu$ is an invariant measure for the kick-to-kick map $\kappa$. To see why, it suffices to verify that $\int h(\kappa(z))\mu(dz) = \int h(z)\mu(dz)$ for any continuous function $h: \Gamma \to \R$. Let $h: \Gamma \to \R$ be a continuous function. Then
\[
\begin{aligned}
\left| \int (h(\kappa(z)) - h(z)) \mu(dz) \right| &=& \lim_{\ell \to \infty} \frac{1}{n_\ell} \left| \sum_{m=1}^{n_\ell} h(\kappa^{m+1}(\tilde z))-h(\kappa^m(\tilde z)) \right|\\
&=& \lim_{\ell \to \infty} \frac{1}{n_\ell} \left| h(\kappa^{n_\ell+1}(\tilde z))-h(\kappa(\tilde z)) \right|\\
& \le & \limsup_{\ell \to \infty} \frac{1}{n_\ell} 2\max_{z\in \Gamma}|h(z)|=0
\end{aligned}
\]
As this holds for any continuous $h:\Gamma\to \R$, $\mu$ is an invariant measure. 

For each $i\in [k]$ and $z=(x,y)$, let $\pi_i(z)=x_i$ be the projection onto the density of species $i$. For any initial condition $z$ with $\pi_i(z)>0$, the fundamental theorem of calculus implies 
\[
\ln \frac{\pi_i(z.t)}{\pi_i(z)}=\int_0^t f_i(z.s)ds
\]
and, after exponentiating,  
\begin{equation}\label{eq:percapita_representation}
\pi_i(z.t)=\pi_i(z)\exp\left(\int_0^t f_i(z.s)ds\right).
\end{equation}
Equation~\eqref{eq:percapita_representation} holds trivially when $\pi_i(z)=0$.
Thus, the kick-to-kick map satisfies $\pi_i(\kappa (z))=\pi_i(z) \Psi_i(z)$ where 
\begin{equation}\label{eq:fitness}
\Psi_i(z)=\exp\left(\int_0^{\tau(z)} f_i(z.s) \,ds\right) F_i(z.\tau(z)).
\end{equation}
Using this representation recursively, one gets
\[
\pi_i\left(\kappa^n(z)\right)=\pi_i(z) \prod_{m =0}^{n-1} \Psi_i\left(\kappa^m(z)\right).
\]
and when $\pi_i(z)>0$,
\[
\ln \frac{\pi_i\left(\kappa^n(z)\right)}{\pi_i (z)}=\sum_{m =0}^{n-1} \ln \Psi_i\left(\kappa^m(z)\right).
\]
The definition of $\mu_n$, $r_i(\mu)$, and the weak* convergence   imply
\[
r_i(\mu)=\lim_{\ell\to\infty}\frac{1}{n_\ell}\sum_{m =0}^{n_\ell-1} \ln \Psi_i\left(\kappa^m(\tilde z)\right).
\]
Assumption \textbf{A3} implies 
\begin{equation}\label{eq:ri_upperbound}
\lim_{\ell\to\infty}\frac{1}{n_\ell}\sum_{m =0}^{n_\ell-1} \ln \Psi_i\left(\kappa^m(\tilde z)\right)=\lim_{\ell\to\infty}\ln \frac{\pi_i\left(\kappa^{n_\ell}(\tilde z)\right)}{\pi_i (\tilde z)}\le \limsup_{\ell\to\infty}\ln \frac{K}{\pi_i (\tilde z)} = 0.
\end{equation}
where $K$ comes from assumption \textbf{A5}. Thus, $r_i(\mu)\le 0$ for all $i\in[k]$.

Now, let $\mathcal{O}^-=\{z(-n)\}_{n=0}^\infty\subset \S_+\cap \Gamma$ be a negative orbit for the kick-to-kick map, i.e., $z(-n+1)=\kappa(z(-n))$ for all $n\le 1$. For $n\ge 1$ define the probability measure $\mu_n$ by
\[
\int h(z)\mu_n(dz)=\frac{1}{n}\sum_{m=1-n}^{0} h(z(m)) \mbox{ for all continuous }h:\Gamma\to \R.
\]
Passing to a subsequence if necessary, let $\mu$ be a weak* limit point $\mu_n$ as $n\to \infty$. By construction, $\mu(\alpha(\mathcal{O}^-))=1$. I claim that $\mu$ is invariant for the kick-to-kick map. As in the case of the forward orbits, it suffices to show that 
\[
\int_\S h(z)\mu(dz)=\int_\S h(\kappa(z))\mu(dz) \mbox{ for all continuous }h:\Gamma\to \R.
\]
By weak* convergence
\[
\begin{aligned}
\left|\int_\S \left(h(z)- h(\kappa (z))\right)\mu(dz)\right|=&\lim_{n\to\infty}\frac{1}{n}\left|\sum_{m=1-n}^{0} h(z(m))- h(\kappa(z(m)))\right|\\
=&\lim_{n\to\infty}\frac{1}{n}\left|h(z(1-n))- h(\kappa(z(0)))\right|
= 0.
\end{aligned}
\]
As this holds for any continuous $h:\Gamma\to \R$,  $\mu$ is $\kappa$ invariant. By construction $\mu(\alpha(\mathcal{O}^-)=1$.

To prove $r_i(\mu)\le 0$ for all $i\in[k]$, one needs to slightly modify the argument used in the case of an $\omega$-limit set.  Let $\Psi_i(z)$ be defined by \eqref{eq:fitness}. As $\pi_i(\kappa(z))=\pi_i(z)\Psi_i(z)$, one has
\[
\pi_i(z(0))=\pi_i(z(-n))\prod_{m=-n}^1 \Psi_i(z(m))
\]
and if $\pi_i(z(-n))>0$,
\[
\ln\frac{ \pi_i(z(0))}{\pi_i(z(-n))}=\sum_{m=-n}^1 \ln \Psi_i(z(m)).
\]
By the definition of $\Psi_i$ and weak* convergence of the $\mu_n$, 
\[
r_i(\mu)=\lim_{n\to\infty}\frac{1}{n}\ln\frac{ \pi_i(z(0))}{\pi_i(z(-n))}
\ge \lim_{n\to\infty}\frac{1}{n}\ln\frac{\pi_i(z(0))}{K}=0
\]
for all $i\in [k]$ and where $K$ comes from assumption \textbf{A5}.  Thus, $r_i(\mu)\ge 0$ for all $i\in[k]$.
\end{proof}

To verify that the Morse sets $M_i$ are isolated in $\S$, I need the following lemma.

\begin{lemma}\label{lem:key:two} Let $M\subset \Gamma_0$ be a compact,  invariant set for $\kappa$ that is isolated with respect $\Gamma_0$. If $M$ is not isolated with respect to $\S$, then there exist invariant probability measures $\mu_+,\mu_-$ such that $r_i(\mu_+)\ge 0$ and $r_i(\mu_-)\le 0$ for all $i$  and $\mu_+(M)=\mu_-(M)=1$.
\end{lemma}

For a compact set $M$, define $\rm{dist}(z,M)=\max_{\tilde z\in M}\|z-\tilde z|$.

\begin{proof}[Proof of Lemma~\ref{lem:key:two}]
    As $M$ is not isolated in $\S$, for every natural number $\ell$ there is a compact invariant set $K_\ell\subset \Gamma$ such that $K_\ell \setminus M\neq \emptyset$ and $K_\ell\subset\{z\in \Gamma: \rm{dist}(z,M)\le 1/\ell\}$. As $M$ is isolated with respect to $\Gamma_0$, $K_\ell\cap \Gamma_0=M$ which implies that $K_\ell \cap \Gamma_+\neq \emptyset$. 

    For each $\ell$, choose a point $z\in K_\ell \cap \Gamma_+$. As $K_\ell$ is invariant, $\omega(z)\subset K_\ell$.  Lemma~\ref{lem:key:one} implies there is an invariant measure $\mu_\ell$ such that $\mu_\ell(K_\ell)=1$ and $r_i(\mu_\ell)\le 0$ for all $i\in [k]$. Let $\mu$ be a weak* limit point of $\mu_\ell$ as $\ell\to\infty$. As the set of invariant probability measures supported by $\Gamma$ is compact with respect to the weak* topology, $\mu$ is an invariant measure. As $\mu(K_\ell)=1$ and $K_\ell\subset\{z\in \Gamma: \rm{dist}(z,M)\le 1/\ell\}$, $\mu(M)=1$. Weak* convergence implies that $r_i(\mu)\le 0$ for $i\in [k]$.

    Next, I prove the existence of an invariant probability measure $\mu$ such that $r_i(\mu)\ge 0$ for $i\in [k]$ and $\mu(M)=1$. For each $\ell$, choose $z\in K_\ell\cap \Gamma_+$ and a negative orbit $\mathcal{O}^-=\{z(n)\}_{n=-\infty}^0\subset \Gamma_+\cap K_\ell$ with $z(0)=z$. Lemma~\ref{lem:key:one} implies there is an invariant measure $\mu_\ell$ such that $\mu_\ell(K_\ell)=1$ and $r_i(\mu_\ell)\ge 0$ for all $i\in [k]$. Let $\mu$ be a weak* limit point of $\mu_\ell$ as $\ell\to\infty$. For the same reasoning as in the previous paragraph, $\mu$ is an invariant probability measure that satisfies $\mu(M)=1$ and $r_i(\mu)\ge 0$ for $i\in [k]$.
\end{proof}

Armed with these two lemmas,  the proof of Theorem~\ref{thm:main} is straightforward. 

\begin{proof}[Proof of Theorem~\ref{thm:main}.] Let $M_i$ be a Morse set. The first assertion of Lemma~\ref{lem:key:one} and the assumption that $\max_i r_i(\mu)>0$ for all invariant probability measures with $\mu(M_i)=1$ implies that $W^s(M_i)\subset \S_+$. Similarly, Lemma~\ref{lem:key:two} implies that $M_i$ is isolated with respect to $\S$. Applying Theorem~\ref{thm:hofbauer-so} implies that $\kappa$ is permanent. 
\end{proof}


To link the permanence of the kick-to-kick map to the permanence of the flow-kick dynamics, I conclude this section with a proof of lemma~\ref{lem:kick-to-kick-permanence-implies-flow-kick-permanence}. \vskip 0.1in

\begin{proof}[Proof of Lemma~\ref{lem:kick-to-kick-permanence-implies-flow-kick-permanence}.] Assumption \textbf{A5} implies that there exists $K>0$ is such that 
\[
\limsup_{n\to\infty}\|\kappa^n(z)\|\le K \mbox{ for all }z\in \S.
\]
Define 
\[
\widetilde K=\sup_{z\in \S, \|z\|\le 1.01 K} \{\|z.t\|:0\le t\le \tau(z)\} \times 1.01
\]
By compactness of $\{z\in \S: \|z\|\le 1.01 K\}$, the continuity of flow $(z,t)\to z.t$ and the continuity of $\tau$, one has $\widetilde K<\infty$. Given any $z\in \S$, choose $n^*$ (depending on $z$) such that 
\[
\|\kappa^n(z)\|\le 1.01 K \mbox{ for }n\ge n^*.
\]
By the definition of $\widetilde K$, 
\[
\Psi(t,z)\le \widetilde K \mbox{ for }t\ge \sum_{m=1}^{n^*}\tau(\kappa^m(z)). 
\]

Assume $M>0$ is such that 
\[
\liminf_{n\to\infty}\pi_i(\kappa^n(z))\ge M \mbox{ for all }z\in \S_+ \mbox{ and }i\in[k].
\]
Define
\[
\rho=\inf \left\{ \int_0^t f_i(z.s)ds : z\in \S, \|z\|\le 1.01 K, i\in [k], 0\le t\le \tau(z)\right\} -0.01
\]
By the compactness of $\{z\in \S:\|z\|\le 1.01K\}$, continuity of $\tau$ and the continuity of $f_i$, one has $\rho>-\infty$. Moreover, as $\int_0^0 f_i(z.s)ds=0$, one has $\rho\le -0.01$. Given any $z\in \S_+$, choose $n^*$ (depending on $z$) sufficiently large so that 
\[
\|\kappa^n(z)\|\le 1.01 K \mbox{ and }\min_i\pi_i(\kappa^n (z))\ge e^{-0.01} M \mbox{ for }n\ge n^*.
\]
Then, the definition of $\rho$ implies that 
\[
\min_i \pi_i(\Psi(t,z)) \ge e^{\rho-0.01}  M \mbox{ for }t\ge \sum_{m=1}^{n^*}\tau(\kappa^m(z)).
\]
Choosing $\widetilde M =e^{\rho-0.01}  M$ completes the proof of the lemma. \end{proof}

