Throughout this proof,  assume that  \textbf{A1}--\textbf{A7} hold. For any $z=(x,y)$, define $\pi_i( z) =x_i$. I begin with a proof of Lemma~\ref{lemma:critical} that naturally follows from Lemma~\ref{lem:key:one}.


\begin{proof}[Proof of Lemma~\ref{lemma:critical}.] Assume $z\in \S_I$ for some $I\subset [k]$ and $\omega(z)\in \S_J$ for some $J\subset I$. Lemma~\ref{lem:key:one} implies there exists an invariant measure $\mu$ with compact support such that $\mu(\S_J)=1$ and $r_i(\mu)\le 0$ for all $i\in I$. Assumption \textbf{A6} implies that $r_i(\mu)<0$ for all $i\in I\setminus J$. 

Let $\mathcal{O}^-=\{z(n)\}_{n=-\infty}^0$ be a negative orbit for the kick-to-kick map i.e. $z(n+1)=\kappa(z(n))$ for all $n\le -1$.  Assume that $z(0)\in \S_I$ for some $I\subset[k]$ and $\alpha(\mathcal{O}^-)\subset \S_J$ for some $J\subset [k]$. Lemma~\ref{lem:key:one} implies there exists an invariant measure $\mu$ with compact support such that $\mu(\S_J)=1$ and $r_i(\mu)\ge 0$ for all $i\in I$. Assumption \textbf{A6} implies that $r_i(\mu)>0$ for all $i\in I\setminus J$. 
\end{proof}


The following lemma constructs a Morse decomposition of $\Gamma_0$ using the invasion graph. The proof closely follows the logic of \citet{hofbauer-schreiber-2022-permanence} but is included for the convenience of the reader.

\begin{lemma} \label{lemma:acyclic:build:morse:demposition}
Let $\ell \in \{ 0,1,\dots , k-1\}$ and $\C_\ell =\{I \in \C: \abs{I} \leq \ell\}$. Suppose $\IG$ is acyclic. Then, for each $I \in \C_\ell$ there is a nonempty compact invariant subset $M_I  \subset \S_I$ such that
\begin{itemize}
    \item[1.] $\omega(z)\subset \bigcup_{I \in \C_\ell} M_I$ for all $z\in \bigcup_{I \in \C_\ell} \S_I$.
    \item[2.] For each negative orbit $\mathcal{O}^- \subset \Gamma_0 \cap \bigcup_{I \in \C_\ell} \S_I$, $\alpha(\mathcal{O}^-)\subset \bigcup_{I \in \C_\ell} M_I$.
    \item[3.]  Each $M_I$ is isolated in $\S$.
     \item[4.] The family of invariant sets $\{ M_I: I \in \C_\ell \}$ is a Morse decomposition of $\bigcup_{I \in \C_\ell} \S_I \cap \Gamma_0$.
\end{itemize}
\end{lemma}

%\texttt{Need to define $\mbox{dist}(A,B)$}

\begin{proof}[Proof of Lemma~\ref{lemma:acyclic:build:morse:demposition}.] We prove this lemma by induction on $\ell$. If $\ell = 0$, then $M_{\emptyset} = \{z=(0,y):z\in \Gamma_0\}$ is hyperbolic by Assumptions \textbf{A6}-\textbf{A7}, and, consequently,  isolated in $\S_0$. Properties 1, 2, and 4, hold immediately. 

Suppose that the lemma holds for $\ell-1$, and all the $M_I$ for $\abs{I} < \ell$ are given.  Let $I\in \C_\ell$. By induction (property 4), the family of $M_J$ such that $J\subsetneq I$ and $J\in \C_{\ell-1}$ form a Morse decomposition of the boundary $\partial (\S_I\cap \Gamma)$ of $\S_I\cap \Gamma$. By induction (property 3), each $M_J$ is isolated in $\S$. Hence, $\partial (\S_I\cap \Gamma)$ is isolated in $\S$ and there exists a maximal compact invariant set $M_I$ in $\S_I$. 

To show property 3., suppose to the contrary that $M_I$  is not isolated in $\S$. Lemma~\ref{lem:key:two} implies there exist invariant measures $\mu_+,\mu_-$ such that $\mu_+(M_I)=\mu_-(M_I)=1$ and $r_j( \mu_+) \ge 0$ and $r_j( \mu_-) \le 0$ for all $j\in [k]$. Assumption \textbf{A7} implies that $r_j( \mu_+) > 0$ and $r_j( \mu_-) < 0$ for $j\notin I$. This contradicts assumption \textbf{A6}. Thus, property 3. holds. 

Finally, the assumption that $\IG$ is acyclic implies property 4 by choosing a suitable order on $\S_\ell$.
\end{proof}


Taking $\ell =k-1$ in Lemma~\ref{lemma:acyclic:build:morse:demposition}, one gets that the family of invariant sets $\{ M_I: I \in \S \}$ is a Morse decomposition of $\Gamma_0$. Applying Theorem~\ref{thm:main} completes the proof. 
