			\includegraphics[width=.3\textwidth]{simul_fig1.pdf} 
			&
			\includegraphics[width=.3\textwidth]{simul_fig2.pdf}
			&
			\includegraphics[width=.3\textwidth]{simul_fig3.pdf}
		\end{tabular} 
