\section{Proofs for Sections~\ref{sec:model} and \ref{sec:est}}
\label{sec:proofs}

\subsection{Proof of Theorem \ref{thm:main}}
\label{subsec:thm.main.proof}
\begin{proof}[Proof of Theorem \ref{thm:main}]
	We provide the proof of Theorem~\ref{thm:main}(i) in two parts. The first part, which takes $\sigma$ as known, is similar to the proof of the homoskedastic Tweedie's formula as in \cite{Liu2020}. The second part then integrates out the unknown $\sigma$ using the law of iterated expectations. We will exploit the conditional independence $y \indep s \mid \mu,\sigma$ throughout, which is a consequence of the Gaussianity assumption \eqref{eq:disagg.model}.

	Let us first take $\sigma$ as known. Further let $p(\cdot)$ denote a probability density of a random variable, with the identity of the random variable inferred from the argument. Let ``$A\implies B$'' mean statement $A$ implies statement $B$. Then since $\int p(\mu\mid y,s^2,\sigma^2)d\mu=1$, 
	\begin{equation}
		\begin{aligned}[b]
			&\frac{\partial}{\partial y} \int p(\mu\mid y,s^2,\sigma^2)d\mu
			=
			0
			\\
			\implies&
			\int 
			\frac{\partial}{\partial y}
			\left\{
			p(y,s^2 \mid \mu , \sigma^2)
			\frac{p(\mu,\sigma^2)}{p(y,s^2,\sigma^2)}
			\right\}
			d\mu
			=
			0
			\\
			\implies&_{(1)}
			\int 
			\frac{\partial}{\partial y}
			\left\{
			p(y \mid \mu , \sigma^2)
			p(s^2 \mid \mu , \sigma^2)
			\frac{p(\mu,\sigma^2)}{p(y,s^2,\sigma^2)}
			\right\}
			d\mu
			=
			0
			\\
			\implies& 
			\int 
			\frac{\partial}{\partial y}
			\left\{
			p(y \mid \mu , \sigma^2)
			p(s^2 \mid \mu , \sigma^2)
			\frac{p(\mu,\sigma^2)}{p(y,s^2,\sigma^2)}
			\right\}
			d\mu
			=
			0
			\\
			\implies&
			\int 
			-\frac{y-\mu}{\sigma J^{-1}}
			p(\mu \mid y,s^2,\sigma^2)
			-
			p(y \mid \mu , \sigma^2)
			p(s^2 \mid \mu , \sigma^2)
			\frac{p(\mu,\sigma^2)\frac{\partial p(y,s^2,\sigma^2)}{\partial  y}}{p^2(y,s^2,\sigma^2)}
			d\mu
			=
			0
			\\
			\implies&_{(2)} 
			\int 
			-\frac{y-\mu}{\sigma J^{-1}}
			p(\mu \mid y,s^2,\sigma^2)
			-
			p(\mu\mid y,s^2,\sigma^2)
			\frac{\frac{\partial p(y,s^2,\sigma^2)}{\partial  y}}{p(y,s^2,\sigma^2)}
			d\mu
			=
			0
			\\
			\implies& 
			\mathbb{E}_{G}[\mu \mid y,s,\sigma]
			=
			y + \frac{\sigma^2}{J}  \cdot \frac{1}{p(y,s^2 \mid \sigma^2)} \cdot \frac{\partial p(y,s^2 \mid \sigma^2)}{\partial y}
			\label{eq:thm.main.proof.1}
		\end{aligned}
	\end{equation}
	where $\implies_{(1),(2)}$ follow by $y \indep s^2 \mid \mu,\sigma$ such that $p(y,s^2\mid\mu,\sigma^2)=p(y\mid\mu,\sigma^2)p(s^2\mid\mu,\sigma^2)$.

	We then apply the law of iterated expectations to integrate out $\sigma^2$:
	\begin{equation}
		\begin{aligned}[b]
			\mathbb{E}_G [\mu \mid y,s]
			=&
			\mathbb{E}_G \left\{\mathbb{E}_G [\mu \mid y,s,\sigma] \mid y,s\right\}
			\\
			=&
			y
			+ 
			\frac{1}{J}
			\mathbb{E}_G 
			\left[
			\sigma^2 \cdot \frac{1}{p(y,s^2 \mid \sigma^2)} \cdot \frac{\partial p(y,s^2 \mid \sigma^2)}{\partial y}
			\mid y,s
			\right] \\
			=&
			y
			+ 
			\frac{1}{J}
			\int
			\left[
			\sigma^2 \cdot \frac{1}{p(y,s^2 \mid \sigma^2)} \cdot \frac{\partial (y,s^2 \mid \sigma^2)}{\partial y}
			\right] p(\sigma^2 \mid y,s^2) d\sigma^2 \\
			=&
			y
			+ 
			\frac{1}{J}
			\int
			\left[
			\sigma^2 \cdot \frac{1}{p(y,s^2 , \sigma^2)} \cdot \frac{\partial p(y,s^2 , \sigma^2)}{\partial y}
			\right] \frac{p(y,s^2,\sigma^2)}{p(y,s^2)} d\sigma^2 \\
			=&
			y
			+ 
			\frac{1}{J}
			\cdot
			\frac{1}{p(y,s^2)}
			\int
			\sigma^2 \cdot \frac{\partial p(y,s^2 , \sigma^2)}{\partial y} d\sigma^2 \\
			=&_{(1)}
			y
			+ 
			\frac{1}{J}
			\cdot
			\frac{1}{p(y,s^2)}
			\frac{\partial}{\partial y}
			\left\{\int
			\sigma^2 \cdot p(y,s^2 , \sigma^2) d\sigma^2\right\} \\
			=&
			y
			+ 
			\frac{1}{J}
			\cdot
			\frac{1}{p(y,s^2)}
			\frac{\partial}{\partial y}
			\left\{\int
			\sigma^2 \cdot p(\sigma^2 \mid y,s^2)  p(y,s^2) d\sigma^2\right\} \\
			=&
			y 
			+ 
			\frac{1}{J}
			\cdot
			\frac{1}{p(y,s^2)}
			\frac{\partial}{\partial y}
			\left\{p(y,s^2) \mathbb{E}_G [\sigma^2 \mid y,s]\right\}
			\label{eq:alt.mu}
			\\
			=&_{(2)}
			y 
			+ 
			\frac{\mathbb{E}_G [\sigma^2\mid y,s]}{J} \cdot \frac{\partial}{\partial y} \log p(y \mid s) 
			+ 
			\frac{1}{J}\frac{\partial}{\partial y} \mathbb{E}_G [\sigma^2\mid y,s]
		\end{aligned}
	\end{equation}
	where $=_{(1)}$ interchanged the order of integration and differentiation, and $=_{(2)}$ is an application of the product rule.

	We will next prove Theorem~\ref{thm:main}(ii) and (iii), which again proceeds in two parts. The first which we separately provide in Lemma~\ref{lm:mgftau}, involves deriving the posterior moment generating function (MGF) of $\tau:=\sigma^{-2}$ and the proof follows \cite{Banerjee2023}. The second involves an application of Proposition 6 of \cite{Cressie1986} to the posterior MGF of $\tau$, which allows us to recover the negative moments of $\tau$ (that is, moments of $\sigma$ and $\sigma^2$) from its MGF. The application of Proposition 6 of \cite{Cressie1986} requires us to verify the following two integrability statements, which we do below: 
	\begin{equation}
		\int_0^\infty M_{\tau \mid y,s} (-t) dt < \infty 
		\quad\text{and}\quad
		\int_0^\infty \left[\frac{1}{t}\right]^{1/2} M_{\tau \mid y,s} (-t) dt < \infty. 
	\end{equation}
	The first integrability condition is direct since 
	\begin{equation}
		\begin{aligned}[b]
			\int_0^\infty M_{\tau \mid y,s} (-t) dt 
			=&_{(1)}
			\frac{[s^2]^{k-1}}{p(y,s^2)}\int_0^\infty \left[\frac{1}{s^2+tk^{-1}}\right]^{k-1} p(y,s^2+tk^{-1})dt
			\\
			\leq&
			\frac{[s^2]^{k-1}}{p(y,s^2)}
			\left[\frac{1}{s^2}\right]^{k-1}
			\int_0^\infty  p(y,s^2+tk^{-1})dt 
			\\
			\leq&
			\frac{1}{p(y,s^2)}
			p(y) 
			\\
			<& \infty 
		\end{aligned}
	\end{equation}
	where $=_{(1)}$ follows by Lemma~\ref{lm:mgftau}.

	The second integrability condition is more tedious but follows as 
	\begin{equation}
		\begin{aligned}[b]
			&\int_0^\infty M_{\tau \mid y,s} (-t) dt 
			\\
			=&_{(1)}
			\frac{[s^2]^{k-1}}{p(y,s^2)}
			\int_0^\infty
			\frac{1}{t^{1/2}} 
			\left[\frac{1}{s^2+tk^{-1}}\right]^{k-1} p(y,s^2+tk^{-1})dt
			\\
			\lesssim&
			\int_0^\infty
			\frac{1}{t^{1/2}} 
			\left[\frac{1}{s^2+tk^{-1}}\right]^{k-1}
			p(y,s^2+tk^{-1})dt
			\\
			=&
			\int_0^\infty
			\frac{1}{t^{1/2}} 
			\left[\frac{1}{s^2+tk^{-1}}\right]^{k-1}
			\int \phi(y\mid \mu,\sigma) \gamma(s^2+tk^{-1}\mid \sigma)
			dG(\mu,\sigma)
			dt
			\\
			\leq&_{(2)}
			\int_0^\infty
			\frac{1}{t^{1/2}} 
			\left[\frac{1}{s^2+tk^{-1}}\right]^{k-1}
			\int \frac{1}{\pi\sigma}
			\frac{k^k}{\sigma^{2k}} [s^2+tk^{-1}]^{k-1}  \exp\left(-\frac{ks^2+tk^{-1}}{\sigma^2}\right)
			dG(\mu,\sigma)
			dt
			\\
			\lesssim&
			\int_0^\infty
			\frac{1}{t^{1/2}} 
			\left[\frac{1}{s^2+tk^{-1}}\right]^{k-1}
			\int \frac{1}{\sigma^{2k+1}}
			\exp\left(-\frac{ks^2}{\sigma^2}\right)
			dG(\mu,\sigma)
			dt
			\\
			\lesssim&_{(3)}
			\int_0^\infty
			\int dG(\mu,\sigma)
			\frac{1}{t^{1/2}} 
			\left[\frac{1}{s^2+tk^{-1}}\right]^{k-1}
			dt
			\\
			=&
			\int_0^\infty
			\frac{1}{t^{1/2}} 
			\left[\frac{1}{s^2+tk^{-1}}\right]^{k-1}
			dt
			\\
			\leq&
			\left[\frac{1}{s^2}\right]^{k-1}
			\int_0^1
			\frac{1}{t^{1/2}} 
			dt
			+
			\int_1^\infty
			\left[\frac{1}{s^2+tk^{-1}}\right]^{k-1}
			dt
			\\
			<& \infty
		\end{aligned}
	\end{equation}
	where $=_{(1)}$ follows by Lemma~\ref{lm:mgftau}, $\leq_{(2)}$ follows by substituting the expressions for the sampling densities, and $\lesssim_{(3)}$ follows because the function
	\begin{equation}
		z(\sigma) := 
		\frac{1}{\sigma^{2k+1}}
		\exp\left(-\frac{ks^2}{\sigma^2}\right)
	\end{equation}
	is continuous over $(0,\infty)$, tends to $0$ as $\sigma\downarrow0$ and as $\sigma\uparrow\infty$ and is therefore uniformly bounded by some constant.  
\end{proof}



\begin{lemma}[Posterior MGF of $\sigma^{-2}$]
	\label{lm:mgftau}
	Suppose $J > 3$ and define $\tau:=\sigma^{-2}$. Then 
	\begin{equation}
		M_{\tau \mid y,s}(t) 
		= 
		\left[\frac{s^2}{s^2 - tk^{-1}}\right]^{k-1}\frac{p(y,s^2 - tk^{-1})}{p(y,s^2)}
		.
	\end{equation}
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lm:mgftau}]
	The proof follows closely Proposition 2 of \cite{Banerjee2023}.
	Again, let $p(\cdot)$ denote a probability density of a random variable, with the identity of the random variable obvious from the argument. 
	Note that Bayes' rule gives 
	\begin{equation}
		\begin{aligned}[b]
			p(\mu,\tau \mid y,s^2)
			=&
			\frac{p(y,s^2 \mid \mu,\tau)}{p(y,s^2)}p(\mu,\tau) \\
			=&
			\frac{p(y \mid \mu,\tau) p(s^2 \mid \mu,\tau)}{p(y,s^2)}\\
			\propto&
			\text{exp}\left\{-\frac{1}{2} \tau J(y-\mu)^2 \right\}
			\text{exp}\left\{-k\tau s^2 + (k-1)\log s^2\right\} 
			\frac{1}{p(y,s^2)} \\
			\propto&
			\text{exp}\left\{Jy \cdot \tau\mu - \frac{1}{2}\left(Jy^2 + 2ks^2\right) \cdot \tau + (k-1)\log s^2 - \log p(y,s^2) \right\}
			\\
			=&
			\text{exp}\left\{ \langle\bs{\eta}_i \; , \; [\tau\mu,\tau]^\prime \rangle - A(\bs{\eta})\right\}
		\end{aligned}
	\end{equation}
	where 
	\begin{equation}
		\begin{aligned}[b]
			\bs{\eta} 
			:=& 
			[\bs{\eta}_{1} \ , \ \bs{\eta}_{2}]^\prime := \left[Ty \ , \ -\frac{1}{2}\left(Jy^2 + 2ks^2\right)\right]^\prime, 
			\\
			A(\bs{\eta}) 
			:=& 
			-(k-1)\log\left[-\frac{\bs{\eta}_{2}+(2J)^{-1}\bs{\eta}_{1}^2}{k} \right] + \log f\left(\frac{\bs{\eta}_{1}}{J} \ , \ -\frac{\bs{\eta}_{2}+(2J)^{-1}\bs{\eta}_{1}^2}{k} \right) 
			\\
			=&
			-(k-1)\log\left[s^2 \right] + \log p\left(y , s^2 \right).
		\end{aligned} 
	\end{equation}

	Therefore, $p(\mu,\tau \mid y,s^2)$ is a member of the exponential family with sufficient statistics $(\tau\mu,\tau)$. This then identifies the posterior moment generating function of the sufficient statistic as
	\begin{equation}
		M_{(\tau\mu,\tau) \mid y,s}(\bs{t}) 
		=
		\text{exp} \left\{ A(\bs{\eta} + \bs{t}) - A(\bs{\eta})  \right\}
	\end{equation}
	for $\bs{t}\in\mathbb{R}^2$, and the marginal posterior moment generating function of $\tau$ is then
	\begin{equation}
		M_{\tau \mid y,s}(t) =
		\text{exp} \left\{ A(\bs{\eta}_i + [0,t]^\prime) - A(\bs{\eta})  \right\}
	\end{equation}
	for $t\in\mathbb{R}$. Substituting out $(\bs{\eta}_{1},\bs{\eta}_{2})$ for $(y,s^2)$ and a little more algebraic manipulation will yield us the expression in the lemma.
\end{proof}

\subsection{Proofs of Lemmas \ref{lm:threshold.detect}, \ref{lm:main.quant}, and \ref{lem:main.hetj}}
\begin{proof}[Proof of Lemma~\ref{lm:threshold.detect}]
	Define $d_i:= \{\hat{\mu}_i \leq c\}$ for a generic estimator $\hat{\mu}:\mathcal{Y}\mapsto\mathbb{R}^n$. 
	Note that 
	\begin{equation}
		\lvert \mu_i-c\rvert
		\left(
		\left\{\mu_i>c\right\} - \left\{\mu_i \leq c\right\}
		\right) \cdot d_i
		=
		(\mu_i-c) \cdot d_i
	\end{equation}
	so that 
	\begin{equation}
		\begin{aligned}[b]
			&\argmin_{\hat{\mu}}
			\mathbb{E}_{G_0}^{(\mu,\sigma)}
			\mathbb{E}_{(\mu,\sigma)}^{\mathcal{Y}}
			\frac{1}{n}
			\sum_{i=1}^n
			\big[
			\lvert \mu_i-c \rvert
			\cdot
			\big(
			d_i
			\left\{\mu_i>c\right\}
			+
			(1-d_i)
			\left\{\mu_i<c\right\}
			\big)
			\big] 
			\\
			=&
			\argmin_{\hat{\mu}}
			\mathbb{E}_{G_0}^{(\mu,\sigma)}
			\mathbb{E}_{(\mu,\sigma)}^{\mathcal{Y}}
			\frac{1}{n}
			\sum_{i=1}^n
			\left[
			(\mu_i-c) \cdot d_i
			\right]
			\\
			=&
			\argmin_{\hat{\mu}}
			\mathbb{E}_{G_0}^{\mathcal{Y}}
			\frac{1}{n}
			\sum_{i=1}^n
			\left(\mathbb{E}_{G_0}[\mu_i\mid \mathcal{Y}_i]-c\right) \cdot d_i
		\end{aligned}
	\end{equation}
	and the solution to the last equality is 
	\begin{equation}
		d_i^*
		=
		\begin{cases}
			1 &\text{if } \mathbb{E}_{G_0}[\mu_i\mid y_i,s_i]\leq c \\
			0 &\text{otherwise.}
		\end{cases}
	\end{equation}
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lm:main.quant}]
	Follows by Theorem~\ref{thm:main} and the linearity of expectations. 
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:main.hetj}]
	Denote the conditional distribution of $(\mu_i,\sigma_i)$ given $J_i=J$ as $H_{(\mu_i,\sigma_i)|J}$.
	Clearly $\check{\mu}^*=\mathbb{E}_{H_0}[\mu\mid y_i,s_i,J_i]$, and so we only have to characterize $\mathbb{E}_{H_0}[\mu\mid y_i,s_i,J_i]$ for the model
	\begin{equation}
		y_{ij} \mid \mu_i,\sigma_i,J \sim \mathcal{N}[\mu_i,\sigma_i],
		\quad
		(\mu_i,\sigma_i) \mid J \sim H_{(\mu_i,\sigma_i) | J}
		\label{eq:main.ext.proof.1}
	\end{equation}
	for $j=1,\dots,J$. 
	The desired result follows once we apply the proof of Theorem~\ref{thm:main} to the model \eqref{eq:main.ext.proof.1} and condition on $J$ throughout, 
	and noting that by assumption, $\mathbb{E}_{H_0}\{J_i > 3\} =1$.
\end{proof}




\section{Proofs for Section~\ref{sec:theory}}


\noindent \textit{Notations.} 
Let $\phi(\cdot)$ denote the standard normal density, and $\gamma(\cdot | k,\theta)$ denote the density of a gamma random variable with shape $k$ and scale $\theta$.
We sometimes use $\{ A \}$ as an indicator function that takes on a value of 1 when the event $A$ occurs and 0 otherwise; for instance, $\{ x \geq y \}$ takes on a value of 1 when $x \geq y$ and 0 otherwise.
Let $C>0$ denote a generic constant depending only on $\underline{\sigma}$ and $k$. 
Let $\bar{\mu}_{G}$ and $\bar{\sigma}_{G}$ denote the maximum supports of $\mu$ and $\sigma$ for a distribution $G$ respectively.
Let $\bar{\mu}_{\mathcal{G}}$ and $\bar{\sigma}_{\mathcal{G}}$ denote the maximum supports for $\mu$ and $\sigma$ of the class of distributions $\mathcal{G}$ respectively. That is, $\bar{\mu}_{\mathcal{G}} := \sup_{G \in \mathcal{G}}\bar{\mu}_{G}$.
We will further define a class of distributions in addition to $\mathcal{G}_n$ defined in Assumption~\ref{ass:latent}: 
\begin{equation}
	\tilde{\mathcal{G}}_n
	:= 
	\left\{
	G : G\left( [-2L(\log n)^{\tilde{\gamma}_1},2L(\log n)^{\tilde{\gamma}_1}] \times [\underline{\sigma},2L(\log n)^{\tilde{\gamma}_2}] \right) = 1
	\right\}
	\label{eq:G.tilde}
\end{equation}
where 	
$\tilde{\gamma}_1 := \gamma_1 + \gamma_2 + \tfrac{1}{2}$ and
$\tilde{\gamma}_2 := \gamma_2 + \tfrac{1}{2}$.
Finally, we will sometimes drop the subscript $n$ (which indicates the row of the triangular array) for notational compactness. 

\subsection{Proof of Theorem~\ref{thm:eb.opt}}

In this section, we split the proof of Theorem~\ref{thm:eb.opt} into three parts, each corresponding to one of the three bounds.
We provide the proof for the regret bounds of estimating $\{\sigma_i^2\}_{i\in[n]}$ in detail, and then specify how it is modified to complete the proofs for $\{\sigma_i\}_{i\in[n]}$ and $\{\mu_i\}_{i\in[n]}$ respectively. 


\begin{proof}[Regret bounds for $\{\sigma_i^2\}_{i\in[n]}$]
	Using Lemma~\ref{lem:loo.regret}, we have 
	\begin{align}
		R_{G_0}(\hat{\sigma}^2,\sigma^2) - R_{G_0}(\hat{\sigma}^{2*},\sigma^2)
		\leq&
		\mathbb{E}_{G_0}^{\mathcal{Y}^{(1)},\mathcal{Y}_1}
		\left[
		\hat{\sigma}^2(y_1,s_1 \mid \hat{G}^{(1)},\rho_n)
		-
		\hat{\sigma}^2(y_1,s_1 \mid G_0,\rho_n) 
		\right]^2
		\label{eq:reg.sigma2.1a}\\
		+&
		\mathbb{E}_{G_0}^{\mathcal{Y}_1}
		\left[
		\left\{\tfrac{f_{G_0}(y_1,s_1^2)}{f_{G_0}(y_1,s_1^2)\vee\rho_n} - 1\right\}\hat{\sigma}^{2*}(y_1,s_1)
		\right]^2.
		\label{eq:reg.sigma2.1}
	\end{align}

	The term \eqref{eq:reg.sigma2.1} is handled by $\rho\asymp n^{-1}\downarrow0$ fast enough:
	\begin{align}
		&\mathbb{E}_{G_0}^{\mathcal{Y}_1}
		\left[\big(\tfrac{f_{G_0}(y_1,s_1^2)}{f_{G_0}(y_1,s_1^2)\vee\rho} - 1\big)
		\hat{\sigma}^{2*}(y_1,s_1)\right]^2
		\nonumber\\
		\leq&
		\bar{\sigma}_{G_0}^4 \cdot 
		\int \big(\tfrac{f_{G_0}(y,s^2)}{f_{G_0}(y,s^2)\vee\rho} - 1\big)^2
		f_{G_0}(y,s^2) d(y,s^2)
		\nonumber\\
		=_{(1)}&
		\bar{\sigma}_{G_0}^4 \cdot 
		O(n^{-1})
		\label{eq:reg.sigma2.2}
	\end{align}
	where $=_{(1)}$ follows because in the region where $\rho_n < f_{G_0}(y,s^2)$, the first term in the integral is exactly zero, whereas in the region where $\rho_n > f_{G_0}(y,s^2)$, the first term in the integral is bounded and the second is $O(n^{-1})$ by Dominated Convergence Theorem and Assumption~\ref{ass:truncations}.

	The term \eqref{eq:reg.sigma2.1a} is handled by splitting the region of integration for $\mathcal{Y}_1$ into two disjoint regions: $\mathbb{R}\times\mathbb{R}_+ = \mathcal{R}\cup\mathcal{R}^c$ where $\mathcal{R}:=\{|y|\leq \bar{y}_n\}\cap\{s \leq \bar{s}_n\}$, defined by
	\begin{equation}
		\bar{y}_n 
		:= \bar{\mu}_{G_0} + \bar{\sigma}_{G_0} (\log n^2)^{1/2}
		\text{ and }
		\bar{s}_n := \tfrac{1}{k^{1/2}}\bar{\sigma}_{G_0} (\log n^2)^{1/2}.
		\label{eq:regions}
	\end{equation}
	The integration over $\mathcal{R}^c$ is bounded by Lemma~\ref{lem:R.complement} to be of the order
	\begin{align}
		&\left( \mathbb{E}_{G_0}^{\mathcal{Y}^{(1)}}[\bar{\sigma}_{\hat{G}^{(1)}}^4] + \bar{\sigma}_{G_0}^4
		\right) \cdot 
		o(n^{-1})
		\nonumber\\
		\leq_{(1)}& 
		\left( \bar{\sigma}_{\tilde{\mathcal{G}}}^4 + \bar{\sigma}_{G_0}^4
		\right) \cdot 
		o(n^{-1})
	\end{align}
	and $\leq_{(1)}$ further follows from Lemma~\ref{lem:trunc}. 
	The integration over $\mathcal{R}$ is handled by Theorem~\ref{thm:jz.p3.sigma2} to be bounded by
	\begin{equation}
		C \cdot 
		\mathbb{E}_{G_0}^{\mathcal{Y}^{(1)}} 
		\left[ 
		\left( \bar{\sigma}_{\hat{G}^{(1)}}^4 + \bar{\sigma}_{G_0}^4 + \bar{s}_n^4 \right) 
		\cdot d^2\big(f_{\hat{G}^{(1)}},f_{G_0}\big)
		\right] .
		\label{eq:reg.sigma2.3}
	\end{equation} 

	In the regions where either $\bar{\sigma}_{\hat{G}^{(1)}}> \bar{\sigma}_{\tilde{\mathcal{G}}}$ or $\bar{\mu}_{\hat{G}^{(1)}}> \bar{\mu}_{\tilde{\mathcal{G}}}$, we will have \eqref{eq:reg.sigma2.3} to be $o(n^{-1})$ by Lemmas~\ref{lem:trunc}~or~\ref{lem:trunc.cross}, since the maximum Hellinger distance between any two densities is 1. For example, 
	\begin{align}
		&\mathbb{E}_{G_0}^{\mathcal{Y}^{(1)}} 
		\left[ 
		\left( \bar{\sigma}_{\hat{G}^{(1)}}^4 + \bar{\sigma}_{G_0}^4 + \bar{s}_n^4 \right) 
		\cdot d^2\big(f_{\hat{G}^{(1)}},f_{G_0}\big)
		\cdot \{ \bar{\sigma}_{\hat{G}^{(1)}} \leq \bar{\sigma}_{\tilde{\mathcal{G}}} \}
		\{ \bar{\mu}_{\hat{G}^{(1)}} > \bar{\mu}_{\tilde{\mathcal{G}}} \}
		\right] 
		\nonumber\\
		\leq& 
		\left( \bar{\sigma}_{\tilde{\mathcal{G}}}^4 + \bar{\sigma}_{G_0}^4 + \bar{s}_n^4 \right) 
		\mathbb{E}_{G_0}^{\mathcal{Y}^{(1)}}\{ \bar{\mu}_{\hat{G}^{(1)}} > \bar{\mu}_{\tilde{\mathcal{G}}} \}
		\nonumber\\
		=_{(1)}& o(n^{-1}).
		\label{eq:reg.sigma2.4}
	\end{align}
	where $=_{(1)}$ follows from Lemma~\ref{lem:trunc.cross}.

	We therefore assume for the remainder of the proof that $\bar{\sigma}_{\hat{G}^{(1)}}\leq \bar{\sigma}_{\tilde{\mathcal{G}}}$ and $\bar{\mu}_{\hat{G}^{(1)}}\leq \bar{\mu}_{\tilde{\mathcal{G}}}$. 
	Then \eqref{eq:reg.sigma2.3} is bound by 
	\begin{equation}
		C \cdot 
		\left( \bar{\sigma}_{\tilde{\mathcal{G}}}^4 + \bar{\sigma}_{G_0}^4 + \bar{s}_n^4 \right) 
		\cdot \mathbb{E}_{G_0}^{\mathcal{Y}^{(1)}}  d^2\big(f_{\hat{G}^{(1)}},f_{G_0}\big)
	\end{equation}
	and by Theorem~\ref{lem:vdv.thm.4.1}, there exists positive constants $c_1$ and $c_2$ such that
	\begin{align}
		\mathbb{E}_{G_0}^{\mathcal{Y}}[d^2\big(f_{\hat{G}^{(1)}},f_{G_0}\big)]
		\leq&
		\mathbb{E}_{G_0}^{\mathcal{Y}}
		d^2\big(f_{\hat{G}^{(1)}},f_{G_0}\big)
		\left\{d\big(f_{\hat{G}^{(1)}},f_{G_0}\big) > c_1\epsilon_n\right\}
		+
		c_1\epsilon_n^2
		\nonumber\\
		\leq&
		2\exp\big(-c_2 (\log n)^3\big)
		+
		c_1
		\tfrac{1}{n}
		(\log n)^{4\left[\tilde{\gamma}_1\vee \frac{1}{2}+\tilde{\gamma}_2\right]+1}
		\nonumber\\
		\leq&
		C
		\tfrac{1}{n}
		(\log n)^{4\left[\tilde{\gamma}_1\vee \frac{1}{2}+\tilde{\gamma}_2\right]+1}.
		\label{eq:reg.sigma2.5}
	\end{align}

	Therefore, by combining \eqref{eq:reg.sigma2.1a}--\eqref{eq:reg.sigma2.5}, we have 
	\begin{align}
		R_{G_0}(\hat{\sigma}^2,\sigma^2) - R_{G_0}(\hat{\sigma}^{2*},\sigma^2)
		\leq& 
		C 
		[\bar{\sigma}_{\tilde{\mathcal{G}}}^4 + \bar{\sigma}_{G_0}^4 + \bar{s}_n^4 ]
		\cdot 
		\tfrac{1}{n}
		(\log n)^{4\left[\tilde{\gamma}_1\vee\frac{1}{2} + \tilde{\gamma}_2\right] +1 }
		\nonumber\\
		\leq&
		C 
		\left[
		(\log n)^{4\tilde{\gamma}_2} + (\log n)^{4\gamma_2 + 2}
		\right]
		\cdot 
		\tfrac{1}{n}
		(\log n)^{4\left[\tilde{\gamma}_1\vee\frac{1}{2} + \tilde{\gamma}_2\right] + 1 }
		\nonumber\\
		\leq&
		C 
		(\log n)^{4\tilde{\gamma}_2}
		\cdot 
		\tfrac{1}{n}
		(\log n)^{4\left[\tilde{\gamma}_1\vee\frac{1}{2} + \tilde{\gamma}_2\right] + 1 }
		\nonumber\\
		=&
		C 
		(\log n)^{4\tilde{\gamma}_2}
		\cdot 
		\tfrac{1}{n}
		(\log n)^{4\left[\tilde{\gamma}_1 + \tilde{\gamma}_2\right] + 1 }.
		\label{eq:reg.sigma2.6}
	\end{align}
	and the final equality follows by definition of $\tilde{\gamma}_1$.
\end{proof}




\begin{proof}[Regret bounds for $\{\sigma_i\}_{i\in[n]}$]
	Following the proof of regret bound for $\{\sigma_i\}_{i\in[n]}$, we have 
	\begin{align}
		&R_{G_0}(\hat{\sigma},\sigma) - R_{G_0}(\hat{\sigma}^{*},\sigma)
		\nonumber\\
		\leq&
		\bar{\sigma}_{G_0}^2 \cdot O(n^{-1})
		+
		\left[
		\bar{\sigma}_{\tilde{\mathcal{G}}}^2 +\bar{\sigma}_{G_0}^2
		\right] \cdot o(n^{-1})
		+
		\mathbb{E}_{G_0}^{\mathcal{Y}}
		\left[
		\hat{\sigma}(y_1,s_1|\hat{G}^{(1)},\rho_n) - \hat{\sigma}(y_1,s_1 |G_0,\rho_n)
		\right]^2 \mathcal{R}
	\end{align}
	and by Theorem~\ref{thm:jz.p3.sigma} we have
	\begin{align}
		\mathbb{E}_{G_0}^{\mathcal{Y}}
		\left[\hat{\sigma}(y_1,s_1 | \hat{G}^{(1)},\rho_n) - \hat{\sigma}(y_1,s_1 | G_0,\rho_n)\right]^2 \mathcal{R}
		\leq&
		C \cdot 
		\mathbb{E}_{G_0}^{\mathcal{Y}^{(1)}}
		\left[(\bar{\sigma}_{\hat{G}^{(1)}}^2+\bar{s}_n^4) \cdot d^2\big(f_{\hat{G}^{(1)}},f_{G_0}\big)\right]
	\end{align}
	and thus by arguments identical as \eqref{eq:reg.sigma2.4}--\eqref{eq:reg.sigma2.6} we have 
	\begin{equation}
		R_{G_0}(\hat{\sigma},\sigma) - R_{G_0}(\hat{\sigma}^{*},\sigma)
		\lesssim
		(\log n)^{4\tilde{\gamma}_2}
		\cdot
		\tfrac{1}{n}
		(\log n)^{4\left[\tilde{\gamma}_1 + \tilde{\gamma}_2\right] + 1 }.
	\end{equation}
\end{proof}





\begin{proof}[Regret bounds for $\{\mu_i\}_{i\in[n]}$]
	Following the proof of regret bound for $\{\sigma_i\}_{i\in[n]}$ 
	and replacing the application of Theorem~\ref{thm:jz.p3.sigma2} with Theorem~\ref{thm:jz.p3.mu}, 
	we have 
	\begin{align}
		R_{G_0}(\hat{\mu},\mu) - R_{G_0}(\hat{\mu}^{*},\mu)
		\leq&
		\bar{\mu}_{G_0}^2 \cdot O(n^{-1})
		+
		[\bar{\mu}_{\tilde{\mathcal{G}}}^2+\bar{\mu}_{G_0}^2] \cdot o(n^{-1})
		\nonumber\\
		+&
		C\mathbb{E}_{G_0}^{\mathcal{Y}^{(1)}}
		\left\{ 
		\big[\bar{\mu}_{\hat{G}^{(1)}}^2+\bar{\mu}_{G_0}^2 + \bar{s}_n^4\big(\tilde{L}(\rho)x_n^2+a_n^2\big)\big] 
		d^2(f_{\hat{G}^{(1)}},f_{G_0})
		\right\}
		\label{eq:reg.mu.1}
	\end{align}
	where 
	\begin{align}
		x_n 
		:=& \bar{\mu}_{\hat{G}^{(1)}} + \bar{\mu}_{G_0} + 2\bar{y}_n,
		\nonumber\\
		a_n
		:=& \max\{\tilde{L}(\rho_n)+1, |\log d^2(f_{\hat{G}^{(1)}},f_{G_0})|\},
		\nonumber\\
		\tilde{L}(\rho) 
		:=& \sqrt{-\log(2\pi \rho^2)} \text{ for } 0<\rho\leq\tfrac{1}{\sqrt{2\pi}}.
	\end{align}

	Note that $\tilde{L}(\rho_n)\asymp \log n$ is of a larger order than $| \log \epsilon_n^2 |$ when 
	$\epsilon_n^2 := \tfrac{1}{n} (\log n)^{4\left[ \tilde{\gamma}_1\vee\frac{1}{2} + \tilde{\gamma}_2 \right]+1}$. 
	Now we follow  \eqref{eq:reg.sigma2.4}--\eqref{eq:reg.sigma2.6} to obtain bounds on \eqref{eq:reg.mu.1} as 
	\begin{align}
		&\mathbb{E}_{G_0}^{\mathcal{Y}^{(1)}}
		\left\{\big[\bar{\mu}_{\hat{G}^{(1)}}^2+\bar{\mu}_{G_0}^2 + \bar{s}_n^4\{\tilde{L}(\rho_n)x_n^2+a_n^2\}\big] 
		d^2(f_{\hat{G}^{(1)}},f_{G_0})\right\}
		\nonumber\\ 
		\leq_{(1)}&
		C \cdot \bar{s}_n^4 \log (n) \bar{\mu}_{\tilde{\mathcal{G}}}^2  \cdot
		\mathbb{E}_{G_0}^{\mathcal{Y}^{(1)}} [d^2(f_{\hat{G}^{(1)}},f_{G_0}) ]
		\nonumber\\ 
		\leq_{(2)}&
		C \cdot \bar{s}_n^4 \log (n) \bar{\mu}_{\tilde{\mathcal{G}}}^2 \cdot
		\tfrac{1}{n} (\log n)^{4\left[\tilde{\gamma}_1\vee\frac{1}{2} + \tilde{\gamma}_2\right]+1}
		\nonumber\\ 
		\leq& 
		C \cdot 
		(\log n)^{4\tilde{\gamma}_2 + 2\tilde{\gamma}_1 + 1}
		\cdot 
		\tfrac{1}{n} (\log n)^{4\left[\tilde{\gamma}_1 + \tilde{\gamma}_2\right] + 1 }.
	\end{align}
	where $\leq_{(1)}$ follows by comparing rates within the block parenthesis, and $\leq_{(2)}$ follows by Lemma~\ref{lem:vdv.thm.4.1}.
\end{proof}







\subsection{Leave-one-out regret}
The following reduces the regret of using leave-one-out NPMLEs to a form more amenable for analysis.
\begin{lemma}[Leave-one-out Regret]
	\label{lem:loo.regret}
	Suppose that $\hat{G}^{(i)}$ satisfy Assumption~\ref{ass:npmle} for all $i$. Then 
	\begin{align}
		&R_{G_0}(\hat{\mu},\mu) - R_{G_0}(\hat{\mu}^{*},\mu)
		\nonumber\\
		=&
		\mathbb{E}_{G_0}^{\mathcal{Y}}
		\left[
		\hat{\mu}(y_1,s_1 \mid \hat{G}^{(1)},\rho_n)
		-
		\hat{\mu}(y_1,s_1 \mid G_0,\rho_n)
		+
		\left\{\tfrac{f_{G_0}(y_1,s_1^2)}{f_{G_0}(y_1,s_1^2)\vee\rho_n} - 1\right\}\hat{\mu}^{*}(y_1,s_1)
		\right]^2,
		\nonumber\\
		&R_{G_0}(\hat{\sigma},\sigma) - R_{G_0}(\hat{\sigma}^{*},\sigma)
		\nonumber\\			
		=&
		\mathbb{E}_{G_0}^{\mathcal{Y}}
		\left[
		\hat{\sigma}(y_1,s_1 \mid \hat{G}^{(1)},\rho_n)
		-
		\hat{\sigma}(y_1,s_1 \mid G_0,\rho_n)
		+
		\left\{\tfrac{f_{G_0}(y_1,s_1^2)}{f_{G_0}(y_1,s_1^2)\vee\rho_n} - 1\right\}\hat{\sigma}^{*}(y_1,s_1)
		\right]^2,
		\nonumber\\
		&R_{G_0}(\hat{\sigma}^2,\sigma^2) - R_{G_0}(\hat{\sigma}^{2*},\sigma^2)
		\nonumber\\
		=&
		\mathbb{E}_{G_0}^{\mathcal{Y}}
		\left[
		\hat{\sigma}^2(y_1,s_1 \mid \hat{G}^{(1)},\rho_n)
		-
		\hat{\sigma}^2(y_1,s_1 \mid G_0,\rho_n)
		+
		\left\{\tfrac{f_{G_0}(y_1,s_1^2)}{f_{G_0}(y_1,s_1^2)\vee\rho_n} - 1\right\}\hat{\sigma}^{2*}(y_1,s_1)
		\right]^2
		\nonumber.
	\end{align}
\end{lemma}
\begin{proof}
	Note that 
	\begin{align}
		&
		R_{G_0}(\hat{\sigma}^2,\sigma^2) - R_{G_0}(\hat{\sigma}^{2*},\sigma^2)
		\nonumber\\
		=_{(1)}&
		\mathbb{E}^{\mathcal{Y}} \left[ \hat{\sigma}_1^{2}  - \sigma_1^2 \right]^2
		- 
		\mathbb{E}^{\mathcal{Y}} \left[ \hat{\sigma}_1^{2*} - \sigma_1^2 \right]^2
		\nonumber\\
		=_{(2)}&
		\mathbb{E}^{\mathcal{Y}^{(1)}}\mathbb{E}_{\mathcal{Y}^{(1)}}^{\mathcal{Y}_1}
		\left[\hat{\sigma}^2(y_1,s_1 | \hat{G}^{(1)},\rho_n) - \hat{\sigma}^{2*}(y_1,s_1)\right]^2
		\nonumber\\
		=&
		\mathbb{E}^{\mathcal{Y}^{(1)}}\mathbb{E}_{\mathcal{Y}^{(1)}}^{\mathcal{Y}_1}
		\left[
		\tfrac{k}{f_{\hat{G}^{(1)}}(y_1,s_1^2)\vee \rho_n} \cdot \int_{s_1^2}^\infty \left[\tfrac{s_1^2}{t}\right]^{k-1} f_{\hat{G}^{(1)}}(y_1,t) dt
		- 
		\tfrac{k}{f_{G_0}(y_1,s_1^2) } \cdot \int_{s_1^2}^\infty \left[\tfrac{s_1^2}{t}\right]^{k-1} f_{G_0}(y_1,t) dt
		\right]^2
		\nonumber\\
		=&
		\mathbb{E}^{\mathcal{Y}^{(1)}}\mathbb{E}_{\mathcal{Y}^{(1)}}^{\mathcal{Y}_1}
		\bigg[
		\underbrace{\tfrac{k}{f_{\hat{G}^{(1)}}(y_1,s_1^2)\vee \rho_n} \cdot \int_{s_1^2}^\infty \left[\tfrac{s_1^2}{t}\right]^{k-1} f_{\hat{G}^{(1)}}(y_1,t) dt}_{=\hat{\sigma}^2(y_1,s_1|\hat{G}^{(1)},\rho_n)}
		- 
		\underbrace{\tfrac{k}{f_{G_0}(y_1,s_1^2) \vee \rho_n} \cdot \int_{s_1^2}^\infty \left[\tfrac{s_1^2}{t}\right]^{k-1} f_{G_0}(y_1,t) dt}_{=\hat{\sigma}^2(y_1,s_1|G_0,\rho_n)}
		\nonumber\\
		&\, \qquad\qquad+
		\left\{\tfrac{f_{G_0}(y_1,s_1^2)}{f_{G_0}(y_1,s_1^2)\vee\rho_n} - 1\right\} \underbrace{\tfrac{k}{f_{G_0}(y_1,s_1^2)} \int_{s_1^2}^\infty \left[\tfrac{s_1^2}{t}\right]^{k-1}f_{G_0}(y_1,t)dt}_{=\hat{\sigma}^{2*}(y_1,s_1)}
		\bigg]^2 
		\label{eq:regret.1}
	\end{align}
	where $=_{(1)}$ follows by the i.i.d. set-up, and $=_{(2)}$ by expanding and using the law of iterated expectations coupled with the fact that $\hat{\sigma}_1^{2*}$ is the Bayes' estimator under $G_0$. 

	The regret statements for estimation of $\{\mu_i\}_{i\in[n]}$ and $\{\sigma_i\}_{i\in[n]}$ follow along identical lines and are thus omitted.
\end{proof}


\subsection{Support of NPMLE maximization}

First recall the definition of $\tilde{\mathcal{G}}$ in \eqref{eq:G.tilde}.

\begin{lemma} 
	\label{lem:trunc}
	Suppose Assumptions~\ref{ass:latent} and \ref{ass:npmle} hold, and $J>3$. Then
	\begin{align}
		\mathbb{E}_{G_0}
		\left[ \bar{\sigma}_{\hat{G}^{(1)}}^2 \{ \bar{\sigma}_{\hat{G}^{(1)}}^2 > \bar{\sigma}_{\tilde{\mathcal{G}}}^2  \} \right]
		=& o(n^{-1}) ,
		\nonumber\\
		\mathbb{E}_{G_0}
		\left[ \bar{\sigma}_{\hat{G}^{(1)}}^4 \{ \bar{\sigma}_{\hat{G}^{(1)}}^4 > \bar{\sigma}_{\tilde{\mathcal{G}}}^4  \} \right]
		=& o(n^{-1}) ,
		\nonumber\\
		\mathbb{E}_{G_0}
		\left[ \bar{\mu}_{\hat{G}^{(1)}}^2 \{ \bar{\mu}_{\hat{G}^{(1)}}^2 > \bar{\mu}_{\tilde{\mathcal{G}}}^2  \} \right]
		=& o(n^{-1}). 
		\nonumber
	\end{align}
\end{lemma}
\begin{proof}
	Now for the first result: by the tail-sum expectation formula\footnote{That is, for any non-negative random variable $X$, we have $\mathbb{E}[X]=\int_{0}^{\infty}\mathbb{E}\{X > t\} dt$.}, we have
	\begin{align}
		\mathbb{E}_{G_0}
		\left[ \bar{\sigma}_{\hat{G}^{(1)}}^2 \{ \bar{\sigma}_{\hat{G}^{(1)}}^2 > \bar{\sigma}_{\tilde{\mathcal{G}}}^2  \} \right]
		=&
		\int_{\bar{\sigma}_{\tilde{\mathcal{G}}}^2}^\infty 
		\mathbb{E}_{G_0}\{ \bar{\sigma}_{\hat{G}^{(1)}}^2 > t \} dt
		\nonumber\\
		\leq_{(1)}&
		\int_{\bar{\sigma}_{\tilde{\mathcal{G}}}^2}^\infty
		\sum_i^n \mathbb{E}_{G_0}\{ s_i^2 > t \} dt
		\nonumber\\
		\leq_{(2)}&
		\int_{\bar{\sigma}_{\tilde{\mathcal{G}}}^2}^\infty
		n\cdot\exp\left(-k \left[\tfrac{t}{\bar{\sigma}_{G_0}^2} - \sqrt{\tfrac{2t}{\bar{\sigma}_{G_0}^2}-1}\right]\right)
		dt
		\nonumber\\
		=&
		\int_0^\infty
		\{ t > \bar{\sigma}_{\tilde{\mathcal{G}}}^2\}
		\exp\left(-k \tfrac{t}{\bar{\sigma}_{G_0}^2} + \log n + k\sqrt{\tfrac{2t}{\bar{\sigma}_{G_0}^2}-1}\right)
		dt
		\nonumber\\
		=_{(3)}&
		o(n^{-1})
	\end{align}
	where $\leq_{(1)}$ is a union bound coupled with Assumption~\ref{ass:npmle}, and $\leq_{(2)}$ follows from Lemma~\ref{lem:trunc.aux}. 
	The integrand in the second-to-last equality is $o(n^{-1})$ for each $t$, because $kt/\bar{\sigma}_{G_0}^2 = 2k \log n$ for $t>\bar{\sigma}_{\tilde{\mathcal{G}}}^2$, and furthermore $2k>2$. Thus  $=_{(3)}$ follows from the Monotone Convergence Theorem.

	The second and third results follow in a similar fashion.
\end{proof}

\begin{lemma}
	\label{lem:trunc.cross}
	Suppose Assumptions~\ref{ass:latent} and \ref{ass:npmle} hold, and $J>3$. Then,
	\begin{align}
		v_n \cdot \mathbb{E}_{G_0} 
		\{ \bar{\sigma}_{\hat{G}^{(1)}}^2 > \bar{\sigma}_{\tilde{\mathcal{G}}}^2 \} 
		=& o(n^{-1}) 
		\nonumber\\
		v_n \cdot \mathbb{E}_{G_0} \{ \bar{\mu}_{\hat{G}^{(1)}}^2 >  \bar{\mu}_{\tilde{\mathcal{G}}}^2 \} 
		=& o(n^{-1})
		\nonumber
	\end{align}
	where $v_n$ is any sub-polynomial sequence\footnote{A sub-polynomial sequence $v_n$ is one that satisfies $v_n = o(n^\epsilon)$ for every $\epsilon>0$.}.
\end{lemma}
\begin{proof}
	Follows from Lemma~\ref{lem:trunc.aux} and the union bound. 
\end{proof}

\begin{lemma} 
	\label{lem:trunc.aux}
	Suppose Assumption~\ref{ass:latent} holds. Then,
	\begin{align}
		\mathbb{E}_{G_0} \{s_i^2 > t\}
		\leq& 
		\exp\left(-k \left[\tfrac{t}{\bar{\sigma}_{G_0}^2} - \sqrt{\tfrac{2t}{\bar{\sigma}_{G_0}^2}-1}\right]\right)
		\nonumber\\
		\mathbb{E}_{G_0}\left\{ |y_i| > t \right\}
		\leq& 
		2
		\exp\left( -\tfrac{1}{2} \left[ \tfrac{t-\bar{\mu}_{G_0}}{\bar{\sigma}_{G_0}/\sqrt{J}}  \right]^2 \right).
		\nonumber
	\end{align}
\end{lemma}
\begin{proof}
	For the first result: note that for all $i$,we have\footnote{ That is, $\tfrac{s_i^2}{\sigma_i^2}-1$ is sub-gamma on the right tail with variance factor $k^{-1}$ and scale factor $k^{-1}$. See e.g., Section 2.4 of \cite{Boucheron2013}.} 
	\begin{equation}
		\tfrac{s_i^2}{\sigma_i^2}-1 \in\Gamma_+(k^{-1},k^{-1}).
		\label{eq:trunc.aux.sigma.1}
	\end{equation}
	Therefore
	\begin{align}
		\mathbb{E}_{G_0} \left\{ s_i^2 > t \right\}
		\leq&
		\mathbb{E}_{G_0} 
		\left\{ \tfrac{s_i^2}{\sigma_i^2} -1 > \tfrac{t}{\bar{\sigma}_{G_0}^2} -1 \right\}
		\nonumber\\
		\leq_{(1)}& 
		\exp\left(-k \left[\tfrac{t}{\bar{\sigma}_{G_0}^2} - \sqrt{\tfrac{2t}{\bar{\sigma}_{G_0}^2}-1}\right]\right).
	\end{align}
	where $\leq_{(1)}$ follows from\footnote{Again, see Section 2.4 of \cite{Boucheron2013}.} \eqref{eq:trunc.aux.sigma.1}.

	For the second result: note that $\frac{y_i-\mu_i}{\sigma_i/\sqrt{J}}$ is a standard normal variable.
	\begin{align}
		\mathbb{E}_{G_0}\left\{ |y_i| > t \right\}
		\leq&
		\mathbb{E}_{G_0}\left\{ 
		\left| \tfrac{y_i-\mu_i}{\sigma_i/\sqrt{J}} \right| > \tfrac{t-\bar{\mu}_{G_0}}{\bar{\sigma}_{G_0}/\sqrt{J}} 
		\right\}
		\nonumber\\
		\leq&
		2
		\mathbb{E}_{G_0}\left\{ 
		\tfrac{y_i-\mu_i}{\sigma_i/\sqrt{J}} > \tfrac{t-\bar{\mu}_{G_0}}{\bar{\sigma}_{G_0}/\sqrt{J}} 
		\right\}
		\nonumber\\
		\leq_{(1)}&
		2
		\exp\left( -\tfrac{1}{2} \left[ \tfrac{t-\bar{\mu}_{G_0}}{\bar{\sigma}_{G_0}/\sqrt{J}}  \right]^2 \right)
	\end{align}
	and $\leq_{(1)}$ follows from the sub-Gaussianity\footnote{See Section 2.3 of \cite{Boucheron2013}.} of $\frac{y_i-\mu_i}{\sigma_i/\sqrt{J}}$.
\end{proof}

\subsection{MSEs within region $\mathcal{R}$}

This section provides adaptations of results from \cite{Jiang2009} that reduce the MSE from using a density estimate in place of the true density $f_{G_{0,n}}$ to the Hellinger distance between the density estimate and the true density. 
In this regard, Theorems~\ref{thm:jz.p3.sigma2}, \ref{thm:jz.p3.sigma} and \ref{thm:jz.p3.mu} are adaptations of Proposition 3 of \cite{Jiang2020} to the setting of unknown heteroskedasticity for the estimation objectives of $\{\sigma_i^2\}_{i\in[n]}$, $\{\sigma_i\}_{i\in[n]}$ and $\{\mu_i\}_{i\in[n]}$ respectively.
Lemmas~\ref{lem:jz.lem.a1.sub} is used in the proofs of all three theorems, whereas Lemmas~\ref{lem:jz.lem.a1} and \ref{lem:jz.lem.a1.aux} are specifically for handling the additional differentiation term required in the proof of Theorem~\ref{thm:jz.p3.mu}.

Recall that the indicator function $\mathcal{R}$ is defined as in \eqref{eq:regions}. 
We maintain the following assumption for this subsection: 
\begin{assumption}[Lower bound on $\sigma$]
	\label{ass:lb.sigma}
	$G_0$ and $G_1$ are two bivariate distributions satisfying $G_l\left( \mathbb{R} \times [\underline{\sigma},\infty) \right)=1$ for $l=0,1$ for some fixed constant $\underline{\sigma}$.
\end{assumption}



\begin{theorem}
	\label{thm:jz.p3.sigma2}
	We have
	\begin{align}
		&\mathbb{E}_{G_0}^{(y,s)}
		\left\{\big[
		\hat{\sigma}^2(y,s|G_1,\rho_n)
		- 
		\hat{\sigma}^2(y,s|G_0,\rho_n)
		\big]^2\mathcal{R}\right\}
		\nonumber\\
		\leq& 
		\big(\bar{\sigma}_{G_1}^4 + \bar{\sigma}_{G_0}^4\big)
		2d^2(f_{G_1},f_{G_0})
		+
		4k^2
		\tfrac{\bar{s}_n^4}{k-2}
		d^2\big(f_{G_1},f_{G_0}\big).
	\end{align}
\end{theorem}
\begin{proof}
	Recall that by definition of $\hat{\sigma}^2(y,s, | G,\rho_n)$,
	\begin{align}
		&\mathbb{E}_{G_0}^{(y,s)}
		\left\{\big[
		\hat{\sigma}^2(y,s|G_1,\rho_n)
		- 
		\hat{\sigma}^2(y,s|G_0,\rho_n)
		\big]^2\mathcal{R}\right\}
		\nonumber\\	
		=&
		\mathbb{E}_{G_0}^{(y,s)}
		\bigg[
		\frac{k}{f_{G_1}(y,s^2)\vee \rho_n} \cdot \int_{s^2}^\infty \left[\frac{s^2}{t}\right]^{k-1} f_{G_1}(y,t) dt
		- 
		\frac{k}{f_{G_0}(y,s^2)\vee \rho_n} \cdot \int_{s^2}^\infty \left[\frac{s^2}{t}\right]^{k-1} f_{G_0}(y,t) dt
		\bigg]^2
		\mathcal{R}.
		\label{eq:jz.p3.sigma2.1}
	\end{align}
	Now define 
	\begin{equation}
		w^* := [f_{G_1}(y,s^2)\vee\rho_n + f_{G_0}(y,s^2)\vee\rho_n]^{-1}
		\label{eq:defn.wstar}
	\end{equation}
	and note that for $\tilde{G}=G_1$ or $G_0$,
	\begin{align}
		&\mathbb{E}_{G_0}^{(y,s)} \bigg[
		\left(\tfrac{k}{f_{\tilde{G}}(y,s^2)\vee\rho_n} - 2kw^*\right)
		\int_{s^2}^\infty \left[\tfrac{s^2}{t}\right]^{k-1} f_{\tilde{G}}(y,t)dt
		\bigg]^2 \mathcal{R}
		\nonumber\\
		=&
		\mathbb{E}_{G_0}^{(y,s)} \bigg[
		\tfrac{f_{G_0}(y,s^2)\vee\rho_n - f_{G_1}(y,s^2)\vee\rho_n}{f_{G_0}(y,s^2)\vee\rho_n + f_{G_1}(y,s^2)\vee\rho_n}
		\cdot
		\underbrace{\tfrac{k}{f_{\tilde{G}}(y,s^2)\vee\rho_n}
			\int_{s^2}^\infty \left[\tfrac{s^2}{t}\right]^{k-1} f_{\tilde{G}}(y,t)dt}_{\hat{\sigma}^2(y,s |\tilde{G},\rho_n)}
		\bigg]^2 \mathcal{R}
		\nonumber\\
		\leq&
		\bar{\sigma}_{\tilde{G}}^4
		\cdot 
		\mathbb{E}_{G_0}^{(y,s)} \bigg[
		(f_{G_0}(y,s^2)\vee\rho_n - f_{G_1}(y,s^2)\vee\rho_n)w^* 
		\bigg]^2 \mathcal{R}
		\nonumber\\
		\leq_{(1)}&
		\bar{\sigma}_{\tilde{G}}^4
		\cdot 
		\mathbb{E}_{G_0}^{(y,s)} \big[
		(f_{G_0}(y,s^2)  - f_{G_1}(y,s^2) )w^* 
		\big]^2 \mathcal{R}
		\label{eq:jz.p3.sigma2.triangle.1}
	\end{align}
	where $\leq_{(1)}$ follows because for instance if 
	$f_{G_0}(y,s^2) < \rho_n < f_{G_1}(y,s^2)$, then
	\begin{align}
		[f_{G_0}(y,s^2)\vee\rho_n - f_{G_1}(y,s^2)\vee\rho_n]^2 
		=& [\rho_n-f_{G_1}(y,s^2)]^2
		\nonumber\\ 
		\leq& 
		[f_{G_0}(y,s^2)-f_{G_1}(y,s^2)]^2
	\end{align}
	with the other cases such as 
	$\{\rho_n< f_{G_0}(y,s^2)\} \cap \{\rho_n<f_{G_1}(y,s^2)\}$ 
	being obvious.

	Inserting \eqref{eq:jz.p3.sigma2.triangle.1} into \eqref{eq:jz.p3.sigma2.1} and bounding using the triangle inequality will give us 
	\begin{align}
		&\mathbb{E}_{G_0}^{(y,s)}
		[\hat{\sigma}(y,s|G_1,\rho_n) - \hat{\sigma}^2(y,s |G_0,\rho_n)]^2 \mathcal{R}
		\nonumber\\
		\leq&
		\big(\bar{\sigma}_{G_1}^4 + \bar{\sigma}_{G_0}^4\big)
		\mathbb{E}_{G_0}^{(y,s)} \big[
		(f_{G_0}  - f_{G_1} )w^* 
		\big]^2
		\nonumber\\
		+&
		4k^2
		\mathbb{E}_{G_0}^{(y,s)}
		\left(
		w^*
		\int_{s^2}^\infty 
		\left[\tfrac{s^2}{t}\right]^{k-1}
		\left[f_{G_1}(y,t) - f_{G_0}(y,t)\right] dt
		\right)^2 \mathcal{R}. 
		\label{eq:jz.p3.sigma2.triangle.2}
	\end{align}
	We bound the two terms on the RHS of the inequality in \eqref{eq:jz.p3.sigma2.triangle.2} in turn. For the first term, we have
	\begin{align}
		&\mathbb{E}_{G_0}^{(y,s)} \big[
		(f_{G_0}(y,s^2)  - f_{G_1}(y,s^2) )w^* 
		\big]^2 
		\nonumber\\
		=&
		\mathbb{E}_{G_0}^{(y,s)} \bigg[
		(f_{G_0}^{1/2}(y,s^2)  - f_{G_1}^{1/2}(y,s^2) ) (f_{G_0}^{1/2}(y,s^2)  + f_{G_1}^{1/2}(y,s^2) ) w^* 
		\bigg]^2
		\nonumber\\
		=&
		\int 
		\left[f_{G_0}^{1/2}(y,s^2)  - f_{G_1}^{1/2}(y,s^2) \right]^2
		\cdot 
		\left[ f_{G_0}^{1/2}(y,s^2)  + f_{G_1}^{1/2}(y,s^2) \right]^2 w^* 
		\cdot 
		w^* f_{G_0}(y,s^2)d(y,s^2)
		\nonumber\\
		\leq&
		d^2(f_{G_1},f_{G_0}) \cdot 2
	\end{align}
	because $w^*f_{G_0}(y,s^2) \leq 1$ and $\big[f_{G_0}(y,s^2)^{1/2} + f_{G_1}^{1/2}(y,s^2)\big]^2w^* \leq 2$ for all $(y,s^2)$.

	For the second term on the RHS of the inequality \eqref{eq:jz.p3.sigma2.triangle.2}:
	\begin{align}
		&\mathbb{E}_{G_0}^{(y,s)}
		\left(
		w^*
		\int_{s^2}^\infty 
		\left[\tfrac{s^2}{t}\right]^{k-1}
		\left[f_{G_1}(y,t) - f_{G_0}(y,t)\right]dt
		\right)^2 \mathcal{R}
		\nonumber\\
		=&
		\int_{\mathcal{R}} 
		\left(
		w^*
		\int_{s^2}^\infty 
		\left[\tfrac{s^2}{t}\right]^{k-1}
		\left[f_{G_1}(y,t) - f_{G_0}(y,t)\right]dt
		\right)^2 f_{G_0}(y,s^2)d(y,s^2) 
		\nonumber\\
		\leq_{(1)}&
		\int_{\mathcal{R}}  
		\frac{
			\big(\int_{s^2}^\infty 
			\big[\tfrac{s^2}{t}\big]^{k-1}
			\big[f_{G_1}(y,t) - f_{G_0}(y,t)\big]dt\big)^2
		}{
			f_{G_1}(y,s^2)\vee\rho_n + f_{G_0}(y,s^2)\vee\rho_n
		}
		d(y,s^2)
		\nonumber\\
		=&
		\int_{\mathcal{R}}  
		\left\{
		\int_{s^2}^\infty 
		\big[\tfrac{s^2}{t}\big]^{k-1}
		\left[ 
		\tfrac{
			f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n
		}{
			f_{G_1}(y,s^2)\vee\rho_n + f_{G_0}(y,s^2)\vee\rho_n
		}
		\right]^{1/2}
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]
		dt
		\right\}^2
		d(y,s^2)
		\nonumber\\
		\leq_{(2)}&
		\int_{\mathcal{R}}  
		\left\{
		\int_{s^2}^\infty 
		\big[\tfrac{s^2}{t}\big]^{k-1}\cdot \big[\tfrac{s^2}{t}\big]^{k-1}
		\left[ 
		\tfrac{
			f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n
		}{
			f_{G_1}(y,s^2)\vee\rho_n + f_{G_0}(y,s^2)\vee\rho_n
		}
		\right]
		dt
		\cdot 
		\int_{s^2}^\infty 
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dt
		\right\}
		d(y,s^2)
		\label{eq:jz.p3.sigma2.triangle.3}
	\end{align}
	where $\leq_{(1)}$ follows by $\tfrac{f_{G_0}(y,s^2)}{f_{G_1}(y,s^2)\vee\rho_n+f_{G_0}(y,s^2)\vee\rho_n}\leq 1$ for all $(y,s^2)$ and $\leq_{(2)}$ by Cauchy-Schwarz.

	We now focus on the first term within the first inner integral of \eqref{eq:jz.p3.sigma2.triangle.3}. First note that 
	\begin{align}
		&\{t>s^2\}\big[\tfrac{s^2}{t}\big]^{k-1}
		\tfrac{
			f_{G_1}(y,t)
		}{
			f_{G_1}(y,s^2)
		}
		\nonumber\\
		=&
		\{t>s^2\}\big[\tfrac{s^2}{t}\big]^{k-1}
		\tfrac{
			\int \sigma^{-1}\phi(\tfrac{y-\mu}{\sigma}) \gamma(t|k,\theta) dG_1(\mu,\sigma)
		}{
			\int \sigma^{-1}\phi(\tfrac{y-\mu}{\sigma}) \gamma(s^2|k,\theta) dG_1(\mu,\sigma)
		}
		\nonumber\\
		=&
		\{t>s^2\}\big[\tfrac{s^2}{t}\big]^{k-1}
		\tfrac{
			\int \sigma^{-1}\phi(\tfrac{y-\mu}{\sigma}) (\Gamma(k)\theta^k)^{-1}t^{k-1}\exp(-\tfrac{t}{\theta}) dG_1(\mu,\sigma)
		}{
			\int \sigma^{-1}\phi(\tfrac{y-\mu}{\sigma}) (\Gamma(k)\theta^k)^{-1}(s^2)^{k-1}\exp(-\tfrac{s^2}{\theta}) dG_1(\mu,\sigma)
		}
		\nonumber\\
		=&
		\{t>s^2\}
		\tfrac{
			\int \sigma^{-1}\phi(\tfrac{y-\mu}{\sigma}) (\Gamma(k)\theta^k)^{-1} \exp(-\tfrac{t}{\theta}) dG_1(\mu,\sigma)
		}{
			\int \sigma^{-1}\phi(\tfrac{y-\mu}{\sigma}) (\Gamma(k)\theta^k)^{-1} \exp(-\tfrac{s^2}{\theta}) dG_1(\mu,\sigma)
		}
		\nonumber\\
		\leq_{(1)}&
		1
		\label{eq:jz.p3.sigma2.triangle.4}
	\end{align}
	where $\leq_{(1)}$ follows because $\exp(-\tfrac{t}{\theta})<\exp(-\tfrac{s^2}{\theta})$ for all $t>s^2$. The same reasoning gives
	\begin{equation}
		\{t>s^2\}\big[\tfrac{s^2}{t}\big]^{k-1}
		\tfrac{
			f_{G_0}(y,t)
		}{
			f_{G_0}(y,s^2)
		}
		\leq 1.
		\label{eq:jz.p3.sigma2.triangle.5}
	\end{equation}
	Now plugging \eqref{eq:jz.p3.sigma2.triangle.4} and \eqref{eq:jz.p3.sigma2.triangle.5} into \eqref{eq:jz.p3.sigma2.triangle.3}
	gives an upper bound on \eqref{eq:jz.p3.sigma2.triangle.3} as 
	\begin{align}
		&\int_{\mathcal{R}}
		\left\{
		\int_{s^2}^\infty 
		\big[ \tfrac{s^2}{t} \big]^{k-1} 2 
		dt
		\cdot 
		\int_{s^2}^\infty 
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dt
		\right\}
		d(y,s^2)
		\nonumber\\
		\leq&
		\int_{s\leq\bar{s}_n} \int_{|y|\leq\bar{y}_n}
		\left\{
		\tfrac{2}{k-2}s^2
		\cdot 
		\int_{\mathbb{R}_+} 
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dt
		\right\}
		dyds^2
		\nonumber\\
		=&
		\tfrac{2}{k-2}
		\int_{s\leq\bar{s}_n} 
		s^2
		ds^2
		\cdot 
		\int_{|y|\leq\bar{y}_n} 
		\int_{\mathbb{R}_+} 
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dtdy
		\nonumber\\
		=&
		\tfrac{1}{k-2}
		\bar{s}_n^4
		\cdot 
		\int_{|y|\leq\bar{y}_n} 
		\int_{\mathbb{R}_+} 
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dtdy 
		\nonumber\\
		\leq &
		\tfrac{1}{k-2}
		\bar{s}_n^4
		\cdot d^2\big(f_{G_1},f_{G_0}\big)
		\label{eq:jz.p3.sigma2.triangle.6}
	\end{align}
	and the last inequality follows by Lemma~\ref{lem:jz.lem.a1.sub}.
\end{proof}






\begin{theorem}
	\label{thm:jz.p3.sigma}
	We have
	\begin{align}
		&\mathbb{E}_{G_0}^{(y,s)}
		[\hat{\sigma}(y,s|G_1,\rho_n) - \hat{\sigma}(y,s |G_0,\rho_n)]^2 \mathcal{R}
		\nonumber\\
		\leq&
		\left\{
		\bar{\sigma}_{G_1}^2  +
		\bar{\sigma}_{G_0}^2
		\right\} 
		\cdot 2d^2\big(f_{G_1},f_{G_0}\big)
		+
		C \left[\bar{s}_n^2 \log n + \bar{s}_n^4 \right] \left[\tfrac{1}{n} + d^2\big(f_{G_1},f_{G_0}\big)\right]
	\end{align}
	where $C$ is a universal constant.
\end{theorem}
\begin{proof}
	Following through the arguments as in \eqref{eq:jz.p3.sigma2.1} to \eqref{eq:jz.p3.sigma2.triangle.2} gives us 
	\begin{align}
		&\mathbb{E}_{G_0}^{(y,s)}
		[\hat{\sigma}(y,s|G_1,\rho_n) - \hat{\sigma}^2(y,s |G_0,\rho_n)]^2 \mathcal{R}
		\nonumber\\
		\leq&
		\left\{
		\bar{\sigma}_{G_1}^2  +
		\bar{\sigma}_{G_0}^2
		\right\}
		\cdot 2d^2\big(f_{G_1},f_{G_0}\big)
		\nonumber\\
		+&
		4k^2
		\mathbb{E}_{G_0}^{(y,s)}
		\left(
		w^*
		\int_{s^2}^\infty 
		\tfrac{1}{\sqrt{k(t-s^2)}}
		\left[\tfrac{s^2}{t}\right]^{k-1}
		\left[f_{G_1}(y,t) - f_{G_0}(y,t)\right] dt
		\right)^2 \mathcal{R}
		\label{eq:jz.p3.sigma.triangle.0}
	\end{align}
	And further following the arguments in \eqref{eq:jz.p3.sigma2.triangle.3} to \eqref{eq:jz.p3.sigma2.triangle.5} gives us 
	\begin{align}
		&
		\mathbb{E}_{G_0}^{(y,s)}
		\left(
		w^*
		\int_{s^2}^\infty 
		\left[\tfrac{1}{(t-s^2)^{1/2}}\right]
		\left[\tfrac{s^2}{t}\right]^{k-1}
		\left[f_{G_1}(y,t) - f_{G_0}(y,t)\right] dt
		\right)^2 \mathcal{R}
		\nonumber\\
		\leq&
		\int_{\mathcal{R}}  
		\bigg\{
		\int_{s^2}^\infty 
		\tfrac{1}{(t-s^2)^{2\gamma_n}} \cdot
		\big[\tfrac{s^2}{t}\big]^{k-1}\cdot \big[\tfrac{s^2}{t}\big]^{k-1}
		\left[ 
		\tfrac{
			f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n
		}{
			f_{G_1}(y,s^2)\vee\rho_n + f_{G_0}(y,s^2)\vee\rho_n
		}
		\right]
		dt
		\nonumber\\
		&\,\qquad \cdot 
		\int_{s^2}^\infty 
		\tfrac{1}{(t-s^2)^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dt
		\bigg\}
		d(y,s^2)
		\nonumber\\
		\leq&
		\int_{ \mathcal{R}}    
		\bigg\{
		\int_{s^2}^\infty 
		\tfrac{1}{(t-s^2)^{2\gamma_n}} \cdot
		\big[\tfrac{s^2}{t}\big]^{k-1} 
		dt
		\cdot 
		\int_{s^2}^\infty 
		\tfrac{1}{(t-s^2)^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dt
		\bigg\}
		d(y,s^2)
		\nonumber\\
		=&
		\int_{ s\leq\bar{s}_n}    
		\bigg\{
		\int_{s^2}^\infty 
		\tfrac{1}{(t-s^2)^{2\gamma_n}} \cdot
		\big[\tfrac{s^2}{t}\big]^{k-1} 
		dt
		\cdot 
		\int_{|y|\leq\bar{y}_n}  
		\int_{s^2}^\infty 
		\tfrac{1}{(t-s^2)^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dt dy
		\bigg\}
		ds^2
		\label{eq:jz.p3.sigma.triangle.1}
	\end{align}
	for $\gamma_n:=\frac{1}{2}-\frac{1}{\log n}$.

	We bound the first (inner) term on the RHS of the final equality \eqref{eq:jz.p3.sigma.triangle.1} as follows:
	\begin{align}
		\int_{s^2}^\infty 
		\tfrac{1}{(t-s^2)^{2\gamma_n}} \cdot
		\big[\tfrac{s^2}{t}\big]^{k-1} 
		dt
		\leq&
		\int_{s^2}^{s^2+l_n}
		\tfrac{1}{(t-s^2)^{2\gamma_n}}
		dt + 
		\tfrac{1}{l_n^{2\gamma_n}}
		\int_{s^2+l_n}^\infty 
		\big[\tfrac{s^2}{t}\big]^{k-1} 
		dt
		\nonumber\\
		=&
		\tfrac{ l_n^{1-2\gamma_n} }{ 1-2\gamma_n }
		+
		\tfrac{1}{l_n^{2\gamma_n}} 
		\tfrac{1}{k-2}  (s^2+l_n) \left[\tfrac{s^2}{s^2+l_n}\right]^{k-1}  
		\nonumber\\
		\leq&
		\tfrac{1}{l_n^{2\gamma_n}} 
		\left[\tfrac{l_n}{1-2\gamma_n} + \tfrac{1}{k-2}(s^2+l_n)\right]
		\nonumber\\
		=&
		\tfrac{1}{l_n^{2\gamma_n}} 
		\left[l_n \tfrac{1}{2}\log n + \tfrac{1}{k-2}(s^2+l_n)\right]
		\nonumber\\
		\leq_{(1)}&
		l_n^{\tfrac{1}{\log n}} \left[ \tfrac{1}{2}\log n + \tfrac{1}{k-2}(s^2+1) \right]
		\nonumber\\
		\leq_{(2)}&
		C\left[\log n + s^2 \right]
		\label{eq:jz.p3.sigma.triangle.2}
	\end{align}
	where $l_n \uparrow\infty$ is some sub-polynomial sequence\footnote{A sub-polynomial sequence $l_n$ is one that satisfies $l_n = o(n^{\epsilon})$ for every $\epsilon>0$.}, and $\leq_{(1)}$ follows from substituting in the definition of $\gamma_n$, and $\leq_{(2)}$ follows from $l_n^{\frac{2}{\log n}} \downarrow 0$. 

	We bound the second (inner) term on the RHS of the final equality \ref{eq:jz.p3.sigma.triangle.1} as follows:
	\begin{align}
		&\int_{y\leq\bar{y}_n} \int_{s^2}^\infty 
		\tfrac{1}{(t-s^2)^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dt dy
		\nonumber\\
		\leq_{(1)}&
		2
		\int_{\mathbb{R}} \int_{ [s^2,s^2+\delta_n] \cup [s^2+\delta_n,\infty] } 
		\tfrac{1}{(t-s^2)^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		\left[
		f_{G_1}^{1/2}(y,t) - f_{G_0}^{1/2}(y,t)
		\right]^2 
		dt dy
		\label{eq:jz.p3.sigma.triangle.3}
	\end{align}
	where $\delta_n := \tfrac{1}{n}\downarrow0$, and $\leq_{(1)}$ follows like in the proof of Lemma~\ref{lem:jz.lem.a1.sub}.
	Now for the integration over $[s^2,s^2+\delta_n]$, we have 
	\begin{align}
		&\int_{ [s^2,s^2+\delta_n] } 
		\tfrac{1}{(t-s^2)^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		\int_{\mathbb{R}} \left[
		f_{G_1}^{1/2}(y,t) - f_{G_0}^{1/2}(y,t)
		\right]^2 
		dy dt
		\nonumber\\
		\leq&
		2 \int_{ [s^2,s^2+\delta_n] } 
		\tfrac{1}{(t-s^2)^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		\int_{\mathbb{R}} \left[
		f_{G_1}(y,t) + f_{G_0}(y,t)
		\right]
		dy dt
		\nonumber\\
		\leq&	
		2 \sup_{t>0}| f_{G_1}(t) + f_{G_0}(t) | \cdot
		\int_{ [s^2,s^2+\delta_n] } \tfrac{1}{(t-s^2)^{2\left(\frac{1}{2}-\gamma_n\right)}} dt
		\nonumber\\
		\leq_{(1)}&	
		C \cdot \tfrac{\delta_n^{2\gamma_n}}{2\gamma_n}
		\label{eq:jz.p3.sigma.triangle.4}
	\end{align}
	and $\leq_{(1)}$ follows by Lemma~\ref{lem:unif.bd.dens}, 
	whereas for the integration over $[s^2+\delta_n,\infty]$ we have
	\begin{align}
		&\int_{ [s^2+\delta_n,\infty] } 
		\tfrac{1}{(t-s^2)^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		\int_{\mathbb{R}} \left[
		f_{G_1}^{1/2}(y,t) - f_{G_0}^{1/2}(y,t)
		\right]^2 
		dy dt
		\nonumber\\
		\leq&
		\tfrac{1}{\delta_n^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		\int_{ [s^2+\delta_n,\infty] } 
		\int_{\mathbb{R}}
		\left[
		f_{G_1}^{1/2}(y,t) - f_{G_0}^{1/2}(y,t)
		\right]^2 
		dy dt
		\nonumber\\
		\leq&
		\tfrac{1}{\delta_n^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		d^2\big(f_{G_1},f_{G_0}\big).
		\label{eq:jz.p3.sigma.triangle.5}
	\end{align}
	By substituting \eqref{eq:jz.p3.sigma.triangle.4} and \eqref{eq:jz.p3.sigma.triangle.5} into
	\eqref{eq:jz.p3.sigma.triangle.3}, together with substituting in the definitions of $\gamma_n$ and $\delta_n$ we get 
	\begin{align}
		&\int_{y\leq\bar{y}_n} \int_{s^2}^\infty 
		\tfrac{1}{(t-s^2)^{2\left(\frac{1}{2}-\gamma_n\right)}} \cdot
		\left[
		\tfrac{
			f_{G_1}(y,t) - f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dt dy
		\nonumber\\
		\leq&
		C \left[
		n^{\frac{2}{\log n}}  \cdot \tfrac{1}{n}
		+ n^{-\frac{2}{\log n}}\cdot d^2\big(f_{G_1},f_{G_0}\big)
		\right].
		\label{eq:jz.p3.sigma.triangle.6}
	\end{align}
	Note that $n^{\frac{2}{\log n}}$ is a constant. 

	Therefore, combining \eqref{eq:jz.p3.sigma.triangle.0}, \eqref{eq:jz.p3.sigma.triangle.1}, \eqref{eq:jz.p3.sigma.triangle.2}, and \eqref{eq:jz.p3.sigma.triangle.6} we get
	\begin{align}
		&\mathbb{E}^{(y,s)}
		[\hat{\sigma}(y,s|G_1,\rho_n) - \hat{\sigma}(y,s |G_0,\rho_n)]^2 \mathcal{R}
		\nonumber\\
		\leq&
		\left\{
		\bar{\sigma}_{G_1}^2  +
		\bar{\sigma}_{G_0}^2
		\right\}
		\cdot 2d^2\big(f_{G_1},f_{G_0}\big)
		\nonumber\\
		+&
		C \cdot 
		\left[\bar{s}_n^2 \log n + \bar{s}_n^4 \right]
		\cdot 
		\left[\tfrac{1}{n}
		+ d^2\big(f_{G_1},f_{G_0}\big)
		\right].
	\end{align}
\end{proof}






\begin{theorem}
	\label{thm:jz.p3.mu}
	We have
	\begin{align}
		&\mathbb{E}^{(y,s)}
		[\hat{\mu}(y,s|G_1,\rho_n) - \hat{\mu}^2(y,s |G_0,\rho_n)]^2 \mathcal{R}
		\nonumber\\
		\leq&
		C\big[\bar{\mu}_{G_1}^2+\bar{\mu}_{G_0}^2 + \bar{s}_n^4\big(\tilde{L}(\rho_n)x_n^2+a_n^2\big)\big] d^2\big(f_{G_1},f_{G_0}\big)
		\nonumber
	\end{align}
	for some universal constant $C>0$, and where
	\begin{align}
		x_n 
		:=& \bar{\mu}_{G_1} + \bar{\mu}_{G_0} + 2\bar{y}_n,
		\nonumber\\
		a_n
		:=& \max\{\tilde{L}(\rho_n)+1, |\log d^2(f_{G_1},f_{G_0})|\}
		\nonumber\\ 
		\tilde{L}(\rho) 
		:=& \sqrt{-\log(2\pi \rho^2)} \text{ for } 0<\rho\leq\tfrac{1}{\sqrt{2\pi}}.
	\end{align}
\end{theorem}
\begin{proof}
	Following through the proof of Theorem~\ref{thm:jz.p3.sigma2} (i.e., from \eqref{eq:jz.p3.sigma2.1} up to before the final inequality of \eqref{eq:jz.p3.sigma2.triangle.6}), we will have 
	\begin{align}
		&\mathbb{E}^{(y,s)}
		[\hat{\mu}(y,s|G_1,\rho_n) - \hat{\mu}^2(y,s |G_0,\rho_n)]^2 \mathcal{R}
		\nonumber\\
		\leq&
		\big(\bar{\mu}_{G_1}^2 + \bar{\mu}_{G_0}^2\big)
		2d^2\big(f_{G_1},f_{G_0}\big)
		\nonumber\\
		+&
		4\left[\tfrac{k}{J}\right]^2
		\tfrac{1}{k-2}
		\bar{s}_n^4
		\cdot 
		\int_{|y|\leq\bar{y}_n} 
		\int_{\mathbb{R}_+} 
		\left[
		\tfrac{
			\tfrac{\partial}{\partial y}f_{G_1}(y,t) - \tfrac{\partial}{\partial y}f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dtdy
	\end{align}
	where by Lemma~\ref{lem:jz.lem.a1} we have 
	\begin{align}
		\int_{|y|\leq\bar{y}_n} 
		\int_{\mathbb{R}_+} 
		\left[
		\tfrac{
			\tfrac{\partial}{\partial y}f_{G_1}(y,t) - \tfrac{\partial}{\partial y}f_{G_0}(y,t)
		}{(f_{G_1}(y,t)\vee\rho_n + f_{G_0}(y,t)\vee\rho_n)^{1/2}}
		\right]^2
		dtdy
		\leq 
		C \left[\tilde{L}(\rho_n)x_n^2 + a_n^2 \right] d^2(f_{G_1},f_{G_0}).
	\end{align}
	and therefore 
	\begin{align}
		&\mathbb{E}^{(y,s)}
		[\hat{\mu}(y,s|G_1,\rho_n) - \hat{\mu}^2(y,s |G_0,\rho_n)]^2 \mathcal{R}
		\nonumber\\
		\leq&
		C\big[\bar{\mu}_{G_1}^2+\bar{\mu}_{G_0}^2 + \bar{s}_n^4\big(\tilde{L}(\rho_n)x_n^2+a_n^2\big)\big] d^2\big(f_{G_1},f_{G_0}\big).
	\end{align}
\end{proof}


\begin{lemma}
	\label{lem:jz.lem.a1.sub}
	\begin{equation}
		\int 
		\left[
		f_{G_1}(y,s^2) - f_{G_0}(y,s^2)
		\right]^2 w^*
		d(y,s^2)
		\leq 2d^2(f_{G_1},f_{G_0})
		\nonumber
	\end{equation}
	where $w^*$ is defined as in \eqref{eq:defn.wstar}.
\end{lemma}
\begin{proof}
	\begin{align}
		&\int
		\left[
		f_{G_1}(y,s^2) - f_{G_0}(y,s^2)
		\right]^2 w^*
		d(y,s^2)
		\nonumber\\
		=_{(1)}&
		\int
		\left[
		f_{G_1}^{1/2}(y,s^2) - f_{G_0}^{1/2}(y,s^2)
		\right]^2 
		\cdot 
		\left[
		f_{G_1}^{1/2}(y,s^2) + f_{G_0}^{1/2}(y,s^2)
		\right]^2
		w^*
		d(y,s^2)
		\nonumber\\
		\leq_{(1)}&
		2\int
		\left[
		f_{G_1}^{1/2}(y,s^2) - f_{G_0}^{1/2}(y,s^2)
		\right]^2 
		d(y,s^2)
		\nonumber\\
		=&
		2d^2(f_{G_1},f_{G_0})
	\end{align}
	where $=_{(1)}$ follows by the identity $x^2-y^2 = (x-y)(x+y)$, and $\leq_{(2)}$ follows because 
	$[f_{G_1}^{1/2}(y,s^2) + f_{G_0}^{1/2}(y,s^2)]^2 w^* \leq 2$.
\end{proof}

The following lemma (and Lemma~\ref{lem:jz.lem.a1.aux}) is an extension of Lemma~1 of \cite{Jiang2009} from a univariate to a bivariate density of sufficient statistics, which is relevant for our framework of unknown heteroskedasticity.
\begin{lemma}
	\label{lem:jz.lem.a1}
	\begin{align}
		&\int_{\{|y|\leq\bar{y}_n\}\times\mathbb{R}_+} 
		\left[
		\tfrac{\partial}{\partial y}f_{G_1}(y,s^2) - \tfrac{\partial}{\partial y}f_{G_0}(y,s^2)
		\right]^2 w^*
		d(y,s^2)
		\nonumber\\
		\leq& 
		C\cdot d^2(f_{G_1},f_{G_0})
		\left[ \tilde{L}^2(\rho_n)x_n^2 + a^2 \right]
		\nonumber
	\end{align}
	for $a^2:=\max\{\tilde{L}^2(\rho_n)+1,|\log d^2(f_{G_1},f_{G_0})| \}$ and $x_n:=\left[ \bar{\mu}_{G_1} + \bar{\mu}_{G_0} + 2|y| \right] $.
\end{lemma}
\begin{proof}
	We abbreviate the densities $f_{G_0}(y,s^2)$ and $f_{G_1}(y,s^2)$ as $f_{G_0}$ and $f_{G_1}$ respectively for notational compactness. 
	Let $D^l(\cdot)$ denote the derivative with respect to $y$; e.g., $D^lf_{G_0} := \tfrac{\partial^l}{\partial y^l} f_{G_0}(y,s^2)$.	

	First define
	\begin{equation}
		\triangle_l := 
		\left(\int_{\{|y|\leq\bar{y}_n\}\times\mathbb{R}_+} \left[D^l (f_{G_1}-f_{G_0})\right]^2 w^* d(y,s^2)\right)^{1/2} 
	\end{equation}
	and note that integration by parts (with respect to the argument $y$) gives
	\begin{align}
		&\triangle_l^2 
		\nonumber\\
		=&
		\int_{\{|y|\leq\bar{y}_n\}\times\mathbb{R}_+}  D^l (f_{G_1}-f_{G_0})w^* \cdot D^l (f_{G_1}-f_{G_0}) dy ds^2
		\nonumber\\
		=&
		0 - 
		\int_{\{|y|\leq\bar{y}_n\}\times\mathbb{R}_+}  D^{l-1} (f_{G_1}-f_{G_0})
		\left\{ 
		D^{l+1}(f_{G_1}-f_{G_0})w^* + [D^l(f_{G_1}-f_{G_0})][Dw^*]
		\right\} dy ds^2
		\nonumber\\
		\leq& 
		\bigg| 
		\int_{\{|y|\leq\bar{y}_n\}\times\mathbb{R}_+}  D^{l-1} (f_{G_1}-f_{G_0}) w^{*1/2} \cdot 
		D^{l+1}(f_{G_1}-f_{G_0})w^{*1/2} dyds^2
		\bigg|
		\nonumber\\
		+&
		\bigg|
		\int_{\{|y|\leq\bar{y}_n\}\times\mathbb{R}_+}  D^{l-1} (f_{G_1}-f_{G_0}) \cdot 
		D^{l}(f_{G_1}-f_{G_0})Dw^* dyds^2
		\bigg|
		\nonumber\\
		\leq_{(1)}&
		\triangle_{l-1}\triangle_{l+1} 
		\nonumber\\
		+& 
		\left(
		\int_{\{|y|\leq\bar{y}_n\}\times\mathbb{R}_+}  \left\{ 
		D^{l-1} (f_{G_1}-f_{G_0})
		\right\}^2 |Dw^*| dyds^2
		\right)^{1/2}
		\nonumber\\
		&\cdot
		\left(
		\int_{\{|y|\leq\bar{y}_n\}\times\mathbb{R}_+}  \left\{ 
		D^{l} (f_{G_1}-f_{G_0})
		\right\}^2 |Dw^*| dyds^2
		\right)^{1/2}
		\label{eq:jz.lem.a1.1}
	\end{align}
	where $\leq_{(1)}$ follows by Cauchy-Schwarz. Now (let $f_{G_0'}$ denote the derivative of $f_{G_0}$ with respect to $y$)
	\begin{align}
		| Dw^* |
		=&
		\big| \tfrac{\partial}{\partial y} \tfrac{1}{f_{G_1}\vee\rho_n + f_{G_0}\vee\rho_n} \big|
		\nonumber\\
		=&
		\begin{cases}
			0 &\text{if } \rho_n>f_{G_1} \text{ and } \rho_n>f_{G_0}  
			\\
			\big|w^* \tfrac{f'_{G_0}}{f_{G_1}\vee\rho_n + f_{G_0}\vee\rho_n} \big| &\text{if } f_{G_0}>\rho_n>f_{G_1}
			\\
			\big|w^* \tfrac{f'_{G_1}}{f_{G_1}\vee\rho_n + f_{G_0}\vee\rho_n} \big| &\text{if } f_{G_1}>\rho_n>f_{G_0}
			\\
			\big|w^* \tfrac{f'_{G_1}+f'_{G_0}}{f_{G_1}\vee\rho_n + f_{G_0}\vee\rho_n} \big| &\text{if } f_{G_1}>\rho_n \text{ and } f_{G_0}>\rho_n
		\end{cases} 
		\nonumber\\
		\leq&
		w^*\left[\tfrac{|f'_{G_1}|}{f_{G_1}\vee\rho_n} + \tfrac{|f'_{G_0}|}{f_{G_0}\vee\rho_n}\right] 
    	\nonumber\\
		\leq&
		w^*\left[\tfrac{|f'_{G_1}|}{f_{G_1}} + \tfrac{|f'_{G_0}|}{f_{G_0}}\right] 
		\nonumber\\
		=_{(1)}&
		w^*\left[
		\tfrac{J\left|\mathbb{E}_{G_1}[\mu | y,s,\sigma] - y\right| }{\sigma^2}
		+ 
		\tfrac{J\left|\mathbb{E}_{G_0}[\mu | y,s,\sigma] - y\right|}{\sigma^2}
		\right]
		\nonumber\\
		\leq& 
		w^*
		\tfrac{J}{\underline{\sigma}^2}\left[ \bar{\mu}_{G_1} + \bar{\mu}_{G_0} + 2|y| \right]
		\label{eq:jz.lem.a1.2}
	\end{align}
	where $=_{(1)}$ follows from \eqref{eq:thm.main.proof.1}.
	Inserting \eqref{eq:jz.lem.a1.2} into \eqref{eq:jz.lem.a1.1} gives 
	\begin{equation}
		\triangle_l^2 
		\leq 
		\triangle_{l-1}\triangle_{l+1}
		+
		\tfrac{J}{\underline{\sigma}^2}
		\underbrace{\left[ \bar{\mu}_{G_1} + \bar{\mu}_{G_0} + 2|y| \right]}_{=: x_n}
		\triangle_{l-1}\triangle_{l}.
		\label{eq:jz.lem.a1.3}
	\end{equation}

	We now define $l_0\in\mathbb{N}$ to be the integer satisfying $l_0 < \tfrac{\tilde{L}(\rho_n)}{2} < l_0+1$, and
	\begin{equation}
		l^*:= \min\{l : \triangle_{l+1} \leq \tfrac{J}{\underline{\sigma}^2} x_nl_0\triangle_l \}.
	\end{equation}
	We split the analysis of $\triangle_1$ according to whether $l^* \leq l_0$.

	When $l^*\leq l_0$, we have for every $l<l^*$ that $\triangle_{l+1}>\tfrac{J}{\underline{\sigma}^2}x_nl_0\triangle_l$, or equivalently, that $\triangle_l < \tfrac{1}{J\underline{\sigma}^{-2}x_nl_0} \triangle_{l+1}$. Inserting this final inequality into \eqref{eq:jz.lem.a1.3} gives
	\begin{equation}
		\triangle_l^2 \leq \triangle_{l-1}\triangle_{l+1}[1+l_0^{-1}]
		\label{eq:jz.lem.a1.3.0}
	\end{equation}
	and dividing throughout by $\triangle_{l}\triangle_{l-1}$ gives 
	\begin{equation}
		\tfrac{\triangle_{l}}{\triangle_{l-1}} \leq [1+l_0^{-1}] \tfrac{\triangle_{l+1}}{\triangle_{l}}
	\end{equation}
	for every $l<l^*$. And thus iterating this through every $l<l^*$ gives
	\begin{equation}
		\tfrac{\triangle_1}{\triangle_0} 
		\leq 
		[1+l_0^{-1}] \tfrac{\triangle_2}{\triangle_1} 
		\leq
		[1+l_0^{-1}]^{l^*-1} \tfrac{\triangle_{l^*}}{\triangle_{l^*-1}}.
		\label{eq:jz.lem.a1.4}
	\end{equation}
	We now divide \eqref{eq:jz.lem.a1.3} for $l=l^*$ by $\triangle_{l^*}\triangle_{l^*-1}$ to get 
	\begin{equation}
		\tfrac{\triangle_{l^*}}{\triangle_{l^*-1}} 
		\leq 
		\tfrac{\triangle_{l^*+1}}{\triangle_{l^*}} + \tfrac{J}{\underline{\sigma}^2} x_n
	\end{equation}
	which we insert into \eqref{eq:jz.lem.a1.4} to get 
	\begin{align}
		\tfrac{\triangle_1}{\triangle_0} 
		\leq&
		[1+l_0^{-1}]^{l^*-1} \left[
		\tfrac{\triangle_{l^*+1}}{\triangle_{l^*}}+\tfrac{J}{\underline{\sigma}^2}x_n
		\right]
		\nonumber\\
		\leq_{(1)}&
		[1+l_0^{-1}]^{l^*-1}[l_0+1] \tfrac{J}{\underline{\sigma}^2}x_n
		\nonumber\\
		\leq_{(2)}&
		\tfrac{1}{1+l_0^{-1}} e [1+l_0] \tfrac{J}{\underline{\sigma}^2}x_n
		\nonumber\\
		=&
		e\cdot l_0 \cdot \tfrac{J}{\underline{\sigma}^2} x_n 
		\nonumber\\
		\leq_{(3)}&
		\tfrac{eJ}{\underline{\sigma}^2} \tfrac{\tilde{L}(\rho_n)}{2} x_n
	\end{align}
	where $\leq_{(1)}$ follows from definition of $l^*$ and $\leq_{(2)}$ follows\footnote{By assumption of this part of analysis -- see line before \eqref{eq:jz.lem.a1.3.0}.} from $l^* \leq l_0$ and $\leq_{(3)}$ follows from the definition of $l_0$. We thus have $\triangle_1^2 \leq \tfrac{(eJ)^2}{4\underline{\sigma}^4}\cdot d^2(f_{G_1},f_{G_0})\tilde{L}^2(\rho_n)x_n^2$ by Lemma~\ref{lem:jz.lem.a1.sub}. This concludes the analysis under $l^*\leq l_0$.

	Now when $l_0 < l^*$, we use arguments identical to the above to show that for every $l\leq l_0$, 
	\begin{equation}
		\tfrac{\triangle_1}{\triangle_0}
		\leq 
		[1+l_0^{-1}]^l \tfrac{\triangle_{l+1}}{\triangle_{l}}
	\end{equation} 
	so that 
	\begin{equation}
		\left(\tfrac{\triangle_1}{\triangle_0}\right)^{l_0+1}
		\leq 
		\left[
		\prod_{l=0}^{l_0} (1+l_0)^l \tfrac{\triangle_{l+1}}{\triangle_{l}}
		\right]
	\end{equation}
	or 
	\begin{align}
		\tfrac{\triangle_1}{\triangle_0}
		\leq&
		\left[
		\prod_{l=0}^{l_0} (1+l_0)^l
		\right]^{\tfrac{1}{l_0+1}} 
		\left[\tfrac{\triangle_{l_0+1}}{\triangle_0}\right]^{\tfrac{1}{l_0+1}}
		\nonumber\\
		=& 
		(1+l_0^{-1})^{l_0/2}
		\cdot 
		\left[\tfrac{\triangle_{l_0+1}}{\triangle_0}\right]^{\tfrac{1}{l_0+1}}
		\label{eq:jz.lem.a1.5}
	\end{align}
	where the final equality of \eqref{eq:jz.lem.a1.5} may be directly verified. 

	Now since $w^*\leq (2\rho_n)^{-1}$, coupled with the fact that $a^2\geq 2(l_0+1)-1$ by definitions of $(a,l_0)$ for small enough $\rho_n$, this would allow application of Lemma~\ref{lem:jz.lem.a1.aux} to give
	\begin{align}
		&\triangle_{l_0+1}^2
		\nonumber\\
		\leq&
		\tfrac{1}{2\rho_n} \cdot 
		\int_{|y|\leq\bar{y}_n} 
		\int_{\mathbb{R}_+} 
		\{
		D^{l_0+1} (f_{G_1} - f_{G_0})
		\}^2 d(y,s^2)
		\nonumber\\
		\leq& 
		\tfrac{1}{2\rho_n} \cdot C
		\cdot
		\left[
		a^{2(l_0+1)} d^2(f_{G_1},f_{G_0}) + a^{2(l_0+1)-1}\exp(-a^2)
		\right]
		\nonumber\\
		\leq_{(1)}&
		C
		\tfrac{1}{\rho_n}d^2(f_{G_1},f_{G_0})a^{2(l_0+1)}
		\left[ 1 + \tfrac{1}{a} \right]
		\nonumber\\
		\leq_{(2)}&
		C
		\tfrac{1}{\rho_n\sqrt{2\pi}}d^2(f_{G_1},f_{G_0})a^{2(l_0+1)}
		\label{eq:jz.lem.a1.6}
	\end{align}
	where $\leq_{(1)}$ follows by $\exp(-a^2)\leq d^2(f_{G_1},f_{G_0})$ by definition of $a$, and $\leq_{(2)}$ follows by $a\geq1$. 
	We then insert \eqref{eq:jz.lem.a1.6} into \eqref{eq:jz.lem.a1.5} to get 
	\begin{align}
		\triangle_1
		\leq&
		(1+l_0^{-1})^{l_0/2} \cdot \triangle_0^{\tfrac{l_0}{l_0+1}}
		\cdot 
		\left[
		\tfrac{1}{\rho_n\sqrt{2\pi}}d^2(f_{G_1},f_{G_0})a^{2(l_0+1)} C
		\right]^{\tfrac{1}{2(l_0+1)}}
		\nonumber\\
		\leq_{(1)}&
		\sqrt{e} d(f_{G_1},f_{G_0}) a \cdot (2\pi\rho_n^2)^{-\tfrac{1}{4l_0+4}} \cdot C^{\frac{1}{2(l_0+1)}}
		\nonumber\\
		\leq_{(2)}&
		\sqrt{e} d(f_{G_1},f_{G_0}) a \cdot \exp(\tfrac{1}{2}) \cdot C^{\frac{1}{2(l_0+1)}}
	\end{align}
	where $\leq_{(1)}$ follows by using Lemma~\ref{lem:jz.lem.a1.sub}, and $\leq_{(2)}$ follows because 
	\begin{align}
		-\tfrac{1}{4l_0+4}\log(2\pi\rho_n^2) 
		=&
		\tfrac{1}{4l_0+4} \tilde{L}(\rho_n)
		\nonumber\\
		\leq_{(3)}&
		\tfrac{1}{4l_0+4} (2l_0+2)
		\nonumber\\
		=&\tfrac{1}{2}
	\end{align}
	where $\leq_{(3)}$ follows by definition of $l_0$.
	Note that $C^{\frac{1}{2(l_0+1)}}\rightarrow 1$, because $l_0\uparrow\infty$ by $\rho_n\downarrow0$.
\end{proof}


\begin{lemma}
	\label{lem:jz.lem.a1.aux}
	For all $l\in\mathbb{N}$ and $a\geq \sqrt{2l-1}$,
	\begin{align}
		&\int_{|y|\leq\bar{y}_n} 
		\int_{\mathbb{R}_+} 
		\{
		D^l (f_{G_1} - f_{G_0})
		\}^2 d(y,s^2)
		\nonumber\\
		\leq& 
		C \cdot
		\left[ a^{2l} d^2(f_{G_1},f_{G_0}) 
		+ a^{2l-1}\exp(-a^2)\right]
	\end{align}
	where $D^l$ represents the $l^{th}$ derivative with respect to $y$.
\end{lemma}
\begin{proof}
	First define $h^*(u;s^2) := \int e^{iux} h(y,s^2) dy$ where $h(y,s^2)$ is an arbitrary integrable function. Now 
	\begin{align}
		&| f_{G_1}^*(u;s^2) | 
		\nonumber\\
		=&
		\bigg| \int e^{iuy} 
		\int \tfrac{1}{\sigma/\sqrt{J}} 
		\phi\left(\tfrac{y-\mu}{\sigma/\sqrt{J}}\right) 
		\gamma(s^2 | k,\theta) dG(\mu,\sigma)
		dy
		\bigg| 
		\nonumber\\
		=&
		\bigg| \int
		\tfrac{1}{\sigma/\sqrt{J}}  \int 
		e^{iuy} \phi\left(\tfrac{y-\mu}{\sigma/\sqrt{J}}\right) dy \cdot 
		\gamma(s^2 | k,\theta) dG(\mu,\sigma)
		\bigg| 
		\label{eq:jz.lem.a1.a.1}
		\\
		\text{and } &
		\tfrac{1}{\sigma/\sqrt{J}}  \int 
		e^{iuy} \phi\left(\tfrac{y-\mu}{\sigma/\sqrt{J}}\right) dy
		\nonumber\\
		=_{(1)}&
		\int \exp\left(iu\left[\tfrac{y\sigma}{\sqrt{J}} + \mu\right]\right) \phi(y)dy
		\nonumber\\
		=&
		\tfrac{1}{\sqrt{2\pi}} \exp(iu\mu) \int \exp\left(iu\tfrac{\sigma}{\sqrt{J}}y - \tfrac{y^2}{2}\right)dy
		\nonumber\\
		=_{(2)}&
		\exp(iu\mu)\exp(-\tfrac{u^2}{2}).
		\label{eq:jz.lem.a1.a.2}
	\end{align}
	where $=_{(1)}$ follows by a change of variables $\tilde{y} = \tfrac{y-\mu}{\sigma/\sqrt{J}}$, and $=_{(2)}$ follows by completing the square within the second exponential term and taking the fourier transform of the Gaussian density. Now inserting \eqref{eq:jz.lem.a1.a.2} into \eqref{eq:jz.lem.a1.a.1} gives us 
	\begin{align}
		| f_{G_1}^*(u;s^2) | 
		=&
		\bigg| 
		\exp(iu\mu) \exp(-\tfrac{u^2}{2}) \int \gamma(s^2 | k,\theta) dG(\mu,\sigma) 
		\bigg|
		\nonumber\\
		\leq& 
		|\exp(iu\mu)|  \exp(-\tfrac{u^2}{2}) f_{G_1}(s^2)
		\nonumber\\
		\leq& 
		\exp(-\tfrac{u^2}{2}) f_{G_1}(s^2).
		\label{eq:jz.lem.a1.a.3}
	\end{align}
	Therefore it follows from the Plancherel identity that 
	\begin{align}
		&\int \{
		D^l (f_{G_1} - f_{G_0})
		\}^2 dy
		\nonumber\\
		=&
		\tfrac{1}{2\pi} \int u^{2l} | f_{G_1}^*(u;s^2) - f_{G_0}^*(u;s^2) |^2 du
		\nonumber\\
		=&
		\tfrac{1}{2\pi} \int_{ \{ |u| \leq a\} \cup \{ |u| > a \}  } u^{2l} | f_{G_1}^*(u;s^2) - f_{G_0}^*(u;s^2) |^2 du
		\nonumber\\
		\leq_{(1)}&
		\tfrac{1}{2\pi}a^{2l} \int_{\{ |u| \leq a\}} 
		| f_{G_1}^*(u;s^2) - f_{G_0}^*(u;s^2) |^2 du
		+
		\tfrac{1}{2\pi} \int_{ |u| > a } u^{2l} \exp(-u^2) [f_{G_1}(s^2) + f_{G_0}(s^2)]^2 du
		\nonumber\\
		\leq &
		\tfrac{1}{2\pi}a^{2l} \int | f_{G_1}^*(u;s^2) - f_{G_0}^*(u;s^2) |^2 du
		+
		\tfrac{1}{2\pi} \int_{ |u| > a } u^{2l} \exp(-u^2) [f_{G_1}(s^2) + f_{G_0}(s^2)]^2 du
		\nonumber\\
		\leq_{(2)}& 
		a^{2l} \int | f_{G_1}(y,s^2) - f_{G_0}(y,s^2) |^2 dy
		+ \tfrac{1}{2\pi} [f_{G_1}(s^2) + f_{G_0}(s^2)]^2 \cdot a^{2l-1} \exp(-a^2)
		\nonumber\\
		\implies 
		&\int \{
		D^l (f_{G_1} - f_{G_0})
		\}^2 d(y,s^2)
		\nonumber\\
		\leq&
		a^{2l} \int | f_{G_1}(y,s^2) - f_{G_0}(y,s^2) |^2 d(y,s^2)
		+ 
		\tfrac{1}{2\pi} \int[f_{G_1}(s^2) + f_{G_0}(s^2)]^2ds^2 \cdot a^{2l-1} \exp(-a^2)
		\nonumber\\
		\leq_{(3)}&
		a^{2l} \int \left[f_{G_1}^{1/2}(y,s^2) + f_{G_0}^{1/2}(y,s^2)\right]^2 d(y,s^2) \cdot d^2(f_{G_1},f_{G_0})
		\nonumber\\ 
		+& \tfrac{1}{2\pi} \int[f_{G_1}(s^2) + f_{G_0}(s^2)]^2ds^2 \cdot a^{2l-1} \exp(-a^2)
		\nonumber\\
		\leq_{(4)}& 
		C \cdot \left[ a^{2l} d^2(f_{G_1},f_{G_0}) + a^{2l-1}\exp(-a^2) \right]
	\end{align}
	where $\leq_{(1)}$ follows from \eqref{eq:jz.lem.a1.a.3}, and $\leq_{(2)}$ follows from the calculus inequality for $a\geq\sqrt{2l-1}$ (see JZ proof)
	\begin{equation}
		\int_{\{|u| > a\}} u^{2l} \exp(-u^2)du \leq a^{2a-1}\exp(-a^2). 
	\end{equation}
	and $\leq_{(3)}$ follows from the identity $x^2-y^2=(x+y)(x-y)$ then applying Cauchy-Schwarz. Finally, $\leq_{(4)}$ follows from Lemma~\ref{lem:unif.bd.dens}, and that both $f_{G}(y,s^2)$ and $f_{G}(s^2)$ integrate to 1 for $G=G_0$ or $G_1$. 
\end{proof}


\subsection{MSEs over region $\mathcal{R}^c$}

Recall that the indicator function $\mathcal{R}$ is defined as in \eqref{eq:regions}, with $\mathcal{R}^c$ being its complement. 

\begin{lemma}[Bounding over $\mathcal{R}^c$]
	\label{lem:R.complement}
	\begin{align}
		\mathbb{E}_{G_0}^{\mathcal{Y}_1}
		\left\{\big[
		\hat{\sigma}^2(y_1,s_1 | \hat{G}^{(1)},\rho)
		- 
		\hat{\sigma}^2(y_1,s_1 | G_0,\rho)
		\big]^2 \mathcal{R}^c\right\}
		\leq& 
		\big[\bar{\sigma}_{\hat{G}^{(1)}}^4 + \bar{\sigma}_{G_0}^4 ] \cdot 
		o(n^{-1}) ,
		\nonumber\\
		\text{and }
		\mathbb{E}_{G_0}^{\mathcal{Y}_1}
		\left\{\big[
		\hat{\sigma}(y_1,s_1 | \hat{G}^{(1)},\rho)
		- 
		\hat{\sigma}(y_1,s_1 | G_0,\rho)
		\big]^2 \mathcal{R}^c\right\}
		\leq& 
		\big[\bar{\sigma}_{\hat{G}^{(1)}}^2 + \bar{\sigma}_{G_0}^2 ] \cdot 
		o(n^{-1}) ,
		\nonumber\\
		\text{and }
		\mathbb{E}_{G_0}^{\mathcal{Y}_1}
		\left\{\big[
		\hat{\mu}(y_1,s_1 | \hat{G}^{(1)},\rho)
		- 
		\hat{\mu}(y_1,s_1 | G_0,\rho)
		\big]^2 \mathcal{R}^c\right\}
		\leq& 
		\big[\bar{\mu}_{\hat{G}^{(1)}}^2 + \bar{\sigma}_{G_0}^2 ] \cdot 
		o(n^{-1}) .
		\nonumber
	\end{align}
\end{lemma}
\begin{proof}
	Observe that
	$
	\mathcal{R}^c \leq \{ |y_1| > \bar{y}_n \} + \{s_1 > \bar{s}_n\},
	$
	and thus by Lemma~\ref{lem:convg.rate.int}, we have 
	$
	\mathbb{E}_{G_0}^{\mathcal{Y}_1}
	\mathcal{R}^c
	=
	o(n^{-1}).
	$
	For example, 
	\begin{align}
		\mathbb{E}_{G_0}^{\mathcal{Y}_1}\{ |y_1| > \bar{y}_n \} =&
		\int \int_{\{|y| > \bar{y}_n\}} f_{G_0}(y \mid s^2) dy f_{G_0}(s^2) ds^2 
		\nonumber\\
		=&
		\int \int 
		\int_{\{|y| > \bar{y}_n\}} \tfrac{1}{\sigma}\phi\left(\tfrac{y-\mu}{\sigma}\right) dy dG_0(\mu,\sigma) f_{G_0}(s^2) ds^2 
		\nonumber\\
		=_{(1)}&
		o(n^{-1}) \int \int dG_0(\mu,\sigma) f_{G_0}(s^2) ds^2 
		\nonumber\\
		=& 
		o(n^{-1})
	\end{align}
	where $=_{(1)}$ is a consequence of Lemma~\ref{lem:convg.rate.int}.
\end{proof}

\subsection{Auxiliary Lemmas}


\begin{lemma}[Convergence rates for integrals]
	\label{lem:convg.rate.int}
	Let $\theta:=\sigma^2/k$. For $\mu\leq\bar{\mu}_{G_0}$ and $\sigma\leq\bar{\sigma}_{G_0}$,
	\begin{equation}
		\begin{aligned}[b]
			\int_{|y| > \bar{y}_n } \phi(y | \mu,\sigma) dy 
			=& o\big(n^{-1}\big)
			\nonumber\\
			\int_{s > \bar{s}_n } \gamma(s^2 | k,\theta) ds 
			&= o\big(n^{-1}\big)  
			\nonumber
		\end{aligned}
		\label{eq:convg.rate.int}
	\end{equation}
	where $\bar{y}_n$ and $\bar{s}_n$ are defined as in \eqref{eq:regions}.
\end{lemma}
\begin{proof}	
	For the first statement of \eqref{eq:convg.rate.int}, 
	\begin{equation}
		\begin{aligned}[b]
			\phi(y\mid\mu,\sigma)
			&= 
			\tfrac{1}{\sqrt{2\pi}\sigma} \exp \left(-0.5\left(\tfrac{y-\mu}{\sigma}\right)^2\right)
			\nonumber\\
			&\leq_{(1)}
			\tfrac{1}{\sqrt{2\pi}\bar{\sigma}_{G_0}} \exp\left(-0.5 \log n^2\right)
			\nonumber\\
			&=
			\tfrac{1}{\sqrt{2\pi}\bar{\sigma}_{G_0}} n^{-1}
			\nonumber\\
			&=o(n^{-1})
		\end{aligned}
	\end{equation}
	where $\leq_{(1)}$ follows because for our selection of $\bar{y}_n$, the function $\tfrac{1}{\sigma}\phi\big(\tfrac{y-\mu}{\sigma}\big)$ is maximized by $\sigma$ being as large as possible.
	An application of dominated convergence then yields the desired result of \eqref{eq:convg.rate.int}. 

	For the second statement of \eqref{eq:convg.rate.int}, we first note that there exists a large enough $\bar{x}$ such that the function $x^k\exp(-x)$ is strictly decreasing in $x$ for $x>\bar{x}$. Now recall that $\theta:=\sigma^2/k$, and so
	\begin{equation}
		\begin{aligned}[b]
			\gamma(s^2\mid k,\theta)
			= &
			\tfrac{1}{\Gamma(k)\theta^k}[s^2]^{k-1}\exp\left(-\tfrac{s^2}{\theta}\right)
			\nonumber\\
			= & 
			\tfrac{1}{\Gamma(k)}  
			\tfrac{1}{s^2}
			\cdot
			\left[\tfrac{s^2}{\theta}\right]^k \exp\left(-\tfrac{s^2}{\theta}\right)
			\nonumber\\
			\leq &
			\tfrac{1}{\Gamma(k)} 
			\tfrac{1}{\bar{s}_n^2}
			\cdot
			\log^{k}(n) \cdot \exp(-\log n^2)
			\nonumber\\
			=& 
			\tfrac{k}{\Gamma(k)} \tfrac{1}{\bar{\sigma}_{G_0}^2} \log^{k-1}(n) \cdot n^{-2} 
			\\
			=&
			o\left(n^{-1}\right).
		\end{aligned}
	\end{equation}
\end{proof}


\begin{lemma}[Bounded densities]
	\label{lem:unif.bd.dens}
	Let $\theta:=\sigma^2/k$, and suppose that $\sigma\geq\underline{\sigma}$. Then
	\begin{align}
		\phi(y | \mu,\sigma) \leq& \tfrac{1}{\sqrt{2\pi} \underline{\sigma}^2 } \nonumber\\
		\gamma(s^2\mid k,\theta) \leq& \tfrac{k(k-1)^{k-1}}{\Gamma(k)} \tfrac{1}{\underline{\sigma}^2}.
		\nonumber
	\end{align}
\end{lemma}
\begin{proof}
	For the first statement, $\phi(y | \mu_,\sigma) \leq \tfrac{1}{\sqrt{2\pi} \underline{\sigma}^2 }$ is immediate. 
	For the second statement, note that the gamma density $\gamma(s^2 \mid k,\theta)$ attains a maximum (over $s^2$) of  
	\begin{equation}
		\begin{aligned}[b]
			\tfrac{1}{\Gamma(k)\theta^k} [(k-1)\theta]^{k-1} \exp\left(-(k-1)\right)
			\leq&
			\tfrac{k(k-1)^{k-1}}{\Gamma(k)} \tfrac{1}{\underline{\sigma}^2}.
		\end{aligned}
	\end{equation}
\end{proof}




\subsection{NPMLE density estimation}

This section provides adaptations of results in \cite{Ghosal2001} on maximum likelihood estimation of normal mixtures to accommodate our setting\footnote{That is, to accommodate bivariate distributions on $(\mu,\sigma)$ with possibly growing supports for both $\mu$ and $\sigma$ and also multiple observations per unit.}. In this regard, Lemmas~ \ref{lem:vdv.lem.3.4}, \ref{lem:vdv.thm.3.3.1}+\ref{lem:vdv.thm.3.3.2}  and \ref{lem:vdv.thm.4.1} are extensions of Lemma~3.4, Theorem~3.3 and Theorem~4.1 of \cite{Ghosal2001} respectively. 

\noindent\textit{Notations.} 
The notation $G(A \times B)$ for a bivariate distribution $G$ and sets $A,B\subset\mathbb{R}$ denotes the probability that $G$ places on the event $(\mu\in A,\sigma\in B)$.
The notation $X\lesssim Y$ means that there exists a constant $C$, possibly dependent on $(\gamma_1,\gamma_2,\underline{\sigma},L)$ but independent of $\epsilon$, such that $X \leq C Y $. Furthermore, all (generic) constants $C$ defined are also possibly dependent on $(\gamma_1,\gamma_2,\underline{\sigma},L)$ but independent of $\epsilon$.
Let $\vee_i x_i$ denote the maximum of $\{x_i\}_{i\in[k]}$. 
Let $|| \cdot ||_{\infty}$ denote the sup-norm and for two densities $f$ and $f'$, let $d(f,f')$ denotes their Hellinger distance. 
Let $N_{[\,]}(\epsilon,\mathcal{F},m)$ and $N(\epsilon,\mathcal{F},m)$ denote the $\epsilon$-bracketing and $\epsilon$-covering numbers respectively for the set $\mathcal{F}$ under metric $m$ (see, e.g., \cite{Ghosal2001} for precise definitions). 

First introduce the following definition 
\begin{equation}
	\mathcal{G}(\epsilon)
	:=
	\left\{
	G: 
	G\left(
	\left[-L  (\log \tfrac{1}{\epsilon})^{\gamma_1}, L  (\log \tfrac{1}{\epsilon})^{\gamma_1}]
	\times 
	\right[\underline{\sigma},L (\log \tfrac{1}{\epsilon})^{\gamma_2}] 
	\right)
	=1
	\right\}
	\label{eq:G.epsilon}
\end{equation}
where $(\gamma_1,\gamma_2,\underline{\sigma},L)>0$ are taken to be constants throughout our analysis. 

Let $x\in\mathbb{R}^k$ and define
\begin{equation}
	p_G(x) := \int \prod_{i=1}^{k} \tfrac{1}{\sigma} \phi\big(\tfrac{x_i-\mu}{\sigma}\big) dG(\mu,\sigma)
\end{equation}
for $G\in \mathcal{G}(\epsilon)$ and $k$ is also a constant throughout our analysis. Finally let
\begin{equation}
	\mathcal{F}(\epsilon):=\{p_G: G\in\mathcal{G}(\epsilon)\}.
\end{equation} 




\begin{lemma}
	\label{lem:vdv.thm.4.1}
	Suppose $p_{0,n}\in\mathcal{F}(n^{-1})$. Define
	\begin{equation}
		\varepsilon_n := n^{-1/2} (\log n)^{2\left[\gamma_1\vee\frac{1}{2} + \gamma_2\right] + \frac{1}{2}}.
	\end{equation}
	Let $\hat{p}_n \in\mathcal{F}(n^{-1})$ satisfy
	\begin{equation}
		n^{-1}\sum_{i=1}^n \hat{p}_n(X_i) \geq 
		\sup_{p\in\mathcal{F}(n^{-1})}
		n^{-1}\sum_{i=1}^n p(X_i)
		- 
		\tfrac{1}{24} \varepsilon_n^2.
	\end{equation}
	Then there exist positive constants\footnote{See e.g., final remark of Section 3 of \cite{Wong1995} for choice of constants.} $(c_1,c_2)$ such that
	\begin{equation}
		\mathbb{P}\left\{
		d(\hat{p}_n,p_{0,n}) > c_1 \varepsilon_n
		\right\}
		\lesssim 
		\exp\big(-c_2 (\log n)^3\big).
	\end{equation}

\end{lemma}
\begin{proof}
	By Lemma~\ref{lem:vdv.thm.3.3.2}, we have that 
	\begin{equation}
		\log N_{[\,]}\big(\varepsilon_n,\mathcal{F}(n^{-1}),d\big) 
		\lesssim 
		\big(\log\tfrac{1}{\varepsilon_n}\big)^{4\big[\gamma_1\vee\frac{1}{2}+\gamma_2\big]+1}.
	\end{equation}
	Then 
	\begin{align}
		&\int_0^{\varepsilon_n} \sqrt{\log N_{[\,]}\big(u,\mathcal{F}(n^{-1}),d\big) } du
		\nonumber\\
		\lesssim&
		\big( \log \sqrt{n} - \big[2\big(\gamma_1\vee\tfrac{1}{2}+\gamma_2\big)+\tfrac{1}{2}\big]\log\log n \big)^{2\big[\gamma_1\vee\tfrac{1}{2}+\gamma_2\big]+\tfrac{1}{2}} 
		\cdot \varepsilon_n
		\nonumber\\
		=&
		\frac{
			\left(
			\tfrac{1}{2}\log n - \big[2\big(\gamma_1\vee\frac{1}{2}+\gamma_2\big)+\frac{1}{2}\big]\log\log n
			\right)^{2\big[\gamma_1\vee\frac{1}{2}+\gamma_2\big]+\frac{1}{2}} 
		}{
			\big(\log n\big)^{2\big[\gamma_1\vee\frac{1}{2}+\gamma_2\big]+\frac{1}{2}}
		}
		\cdot \sqrt{n} \varepsilon_n^2
		\nonumber\\
		\lesssim&
		\sqrt{n} \varepsilon_n^2.
	\end{align}
	Thus by Theorem 2 of \cite{Wong1995}, there exists positive constants $(c_1,c_2)$ such that
	\begin{align}
		\mathbb{P}\left\{
		d(\hat{p}_n,p_{0,n} > c_1 \varepsilon_n)
		\right\}
		\leq& 
		4\exp\big(-c_2 n\varepsilon_n^2\big)
		\nonumber\\
		=&
		4\exp \left(-c_2 \big[\log n\big]^{4\big[\gamma_1\vee\frac{1}{2}+\gamma_2\big]+1} \right)
		\nonumber\\
		\lesssim& 
		\exp\big(-c_2 (\log n)^3\big).
	\end{align}
\end{proof}





\begin{lemma}
	\label{lem:vdv.thm.3.3.2}
	Let $\gamma_1 \geq 1/2$, $\gamma_2 \geq 0 $. We have
	\begin{equation}
		\log N_{[\,]}(\epsilon , \mathcal{F}(\epsilon),d)
		\lesssim 
		\big(\log\tfrac{1}{\epsilon}\big)^{4[\gamma_1+\gamma_2]+1}.
	\end{equation}
\end{lemma}
\begin{proof}
	Again let 
	$\bar{\mu}:= L(\log \frac{1}{\epsilon})^{\gamma_1}$ and $\bar{\sigma} := L (\log \frac{1}{\epsilon})^{\gamma_2}$,
	and $\eta$ satisfying
	$\eta\leq\epsilon$ be a positive constant to be chosen later.
	Let $f_1,\dots,f_N$ be an $\eta$-net for $\mathcal{F}(\epsilon)$ with the $||\cdot||_\infty$ norm, where $N$ is again a positive constant to be chosen later. 

	Define
	\begin{equation}
		E(x_j) := 
		\{x_j\leq 2\bar{\mu}\} \tfrac{1}{\underline{\sigma}}\phi(0) 
		+
		\{x_j > 2\bar{\mu}\} \tfrac{1}{\underline{\sigma}} \phi\big(\tfrac{x_j}{2\bar{\sigma}}\big)
	\end{equation}
	and note that $\textstyle\prod_{j=1}^k E(x_j)$ is an envelope for $\mathcal{F}(\epsilon)$, 
	because we have that for every $| \mu | \leq \bar{\mu} $ and $\underline{\sigma}\leq\sigma\leq\bar{\sigma}$,
	\begin{equation}
		\{x_j\leq 2\bar{\mu}\} 
		\left[
		\tfrac{1}{\underline{\sigma}}\phi(0) - \tfrac{1}{\sigma} \phi\big(\tfrac{x_j-\mu}{\sigma}\big) 
		\right]
		+
		\{x_j > 2\bar{\mu}\}
		\left[
		\tfrac{1}{\underline{\sigma}} \phi\big(\tfrac{x_j}{2\bar{\sigma}}\big) - \tfrac{1}{\sigma} \phi\big(\tfrac{x_j-\mu}{\sigma}\big) 
		\right]
		\geq 0 
	\end{equation}
	for every $j=1,\dots,k$.

	Now define $l_i := \max(f_i-\eta,0)$ and $u_i:=\min\big(f_i+\eta,\textstyle\prod_j E(x_j)\big)$, and note that we have\footnote{Here $[l_i,u_i]$ represents the set of all functions $f:\mathbb{R}^k\mapsto\mathbb{R}$ such that $l_i(x)\leq f(x) \leq u_i(x)$ for all $x$.} $\mathcal{F}(\epsilon) \subset \cup_{i=1}^N [l_i,u_i]$, because if\footnote{Here $B(\eta,f_i,||\cdot||_\infty)$ represents the set of all $p\in\mathcal{F}(\epsilon)$ satisfying $||f_i - p||_\infty<\eta$.} $p \in B(\eta,f_i,||\cdot||_\infty)$, then 
	\begin{align}
		&|| f_i - p ||_\infty < \eta 
		\nonumber\\ 
		\implies &l_i(x) \leq p(x) \leq u_i(x) 
		\nonumber\\ 
		\implies &p(x) \in [l_i,u_i].
	\end{align}

	Now $u_i - l_i \leq \min\big(2\eta,\textstyle\prod_j E(x_j)\big)$, and therefore for any $B>0$, we have 
	\begin{equation}
		\int u_i(x)-l_i(x) dx 
		\leq 
		\int \prod_{j=1}^{k} \left[ \{x_j\leq B\} + \{x_j > B\} \right] \min(2\eta,\textstyle\prod_j E(x_j))
		dx.
		\label{eq:npmle.int}
	\end{equation}
	We choose  $B:=\max\big(2L,\sqrt{8}\bar{\sigma}\big[\log\tfrac{1}{\eta}\big]^{\gamma_1}\big)$ and
	now study each term that results from the product expansion within the integral. The term 
	\begin{equation}
		\int \prod_{j=1}^{k} \{x_j\leq B\}  \min(2\eta,\textstyle\prod_j E(x_j))
		dx
		\leq
		2\eta B^k		
	\end{equation}
	is the term of the leading order since for any arbitrary set $S\subset\{1,\dots,k\}$,
	\begin{align}
		&\int \prod_{j\in S} \{x_j\leq B\} \prod_{j\in S^c} \{x_j > B\} \min\big(2\eta,\textstyle\prod_jE(x)\big)
		dx
		\nonumber\\
		\leq& 
		B^{ |S| } \cdot \big[\tfrac{1}{\underline{\sigma}}\phi(0)\big]^{ |S| } 
		\cdot \prod_{j\notin S} \int_{x_j>B} E(x_j) dx_j
		\nonumber\\
		\lesssim_{(1)}&
		B^{ |S| } \prod_{j\in S^c} E(B) 
		\nonumber\\
		\leq&
		B^{ |S| } \eta^{ | S^c| }.
	\end{align}
	where $\lesssim_{(1)}$ follows by $B\geq2\bar{\mu}$ and the Mill's ratio. Thus by returning to the integral \eqref{eq:npmle.int} we have 
	\begin{equation}
		\int u_i(x)-l_i(x) dx 
		\lesssim \eta B^k
		\lesssim \eta [\log\tfrac{1}{\eta}]^{k[\gamma_1+\gamma_2]}
	\end{equation}
	and therefore
	\begin{equation}
		N_{[\,]} \big(C\eta [\log\tfrac{1}{\eta}]^{k[\gamma_1+\gamma_2]}, \mathcal{F}(\epsilon),||\cdot||_1\big)
		\leq N
	\end{equation}
	for some constant $C$. 
	By Lemma~\ref{lem:vdv.thm.3.3.1}, we can choose $N\lesssim \big(\log\tfrac{1}{\eta}\big)^{4[\gamma_1+\gamma_2]+1}$, and we then choose $\eta$ to satisfy the equation 
	\begin{equation}
		C \eta [\log\tfrac{1}{\eta}]^{k[\gamma_1+\gamma_2]} = \epsilon.
	\end{equation}   
	Note that $\log \tfrac{1}{\eta} \sim \log \tfrac{1}{\epsilon}$, so that we have 
	\begin{equation}
		N_{[\,]} \big(\epsilon, \mathcal{F}(\epsilon),||\cdot||_1\big)
		\lesssim 
		\big(\log\tfrac{1}{\epsilon}\big)^{4[\gamma_1+\gamma_2]+1}.
	\end{equation}
	By the inequality $d^2(f,g) \leq ||f-g||_1$, we have 
	\begin{equation}
		N_{[\,]} \big(\epsilon, \mathcal{F}(\epsilon), d \big)
		\leq
		N_{[\,]} \big(\epsilon^2, \mathcal{F}(\epsilon),||\cdot||_1\big)
		\lesssim 
		\big(\log\tfrac{1}{\epsilon^2}\big)^{4[\gamma_1+\gamma_2]+1}
		\lesssim
		\big(\log\tfrac{1}{\epsilon}\big)^{4[\gamma_1+\gamma_2]+1}.
	\end{equation}
\end{proof}






\begin{lemma}
	\label{lem:vdv.thm.3.3.1}
	Let $\gamma_1 \geq 1/2$, $\gamma_2 \geq 0 $. We have
	\begin{equation}
		\log N(\epsilon , \mathcal{F}(\epsilon) ,||\cdot||_\infty)
		\lesssim 
		\big(\log\tfrac{1}{\epsilon}\big)^{4[\gamma_1+\gamma_2]+1}
	\end{equation}
\end{lemma}
\begin{proof}
	Let $\mathcal{F}_{\text{d}}(\epsilon):= \{ p_G : G\in\mathcal{G}_{\text{d}}(\epsilon) \}$ where 
	\begin{equation}
		\mathcal{G}_{\text{d}}(\epsilon) 
		:=
		\big\{
		G\in\mathcal{G}(\epsilon)
		\text{ is discrete with at most 
			$N\leq C\big(\log\tfrac{1}{\epsilon}\big)^{4[\gamma_1+\gamma_2]}$} 
		\text{ support points}
		\big\}.
	\end{equation}

	By Lemma~\ref{lem:vdv.lem.3.4}, $C$ is a constant that can be chosen such that $\mathcal{F}_{\text{d}}(\epsilon)$ is an $\epsilon$-net\footnote{In the $|| \cdot ||_\infty$ norm.} over $\mathcal{F}(\epsilon)$. Thus an $\epsilon$-net over $\mathcal{F}_{\text{d}}(\epsilon)$ will be an $2\epsilon$-net\footnote{Also in the $|| \cdot ||_\infty$ norm.} over $\mathcal{F}(\epsilon)$.

	Now we choose an $\epsilon$-net $\mathcal{S}$ over the $N$-dimensional simplex for the $L_1$ norm. By Lemma A.4 of \cite{Ghosal2001}, this can be chosen such that $|\mathcal{S}|\leq \big(\tfrac{5}{\epsilon}\big)^N$. 

	We further define $\mathcal{F}_{\text{d}}'(\epsilon) := \{ p_{G} : G\in\mathcal{G}_{\text{d}}'(\epsilon)\}$ where
	\begin{align}
		\mathcal{G}_{\text{d}}'(\epsilon)
		:=
		\big\{
		&G\in\mathcal{G}_{\text{d}}(\epsilon)
		\text{ with $N$ support points of the form } 
		(\pm\eta_1\epsilon,\underline{\sigma}+\eta_2\epsilon)
		\nonumber\\
		& \text{where $\eta_1,\eta_2=0,1,\dots,$ with its weights coming from $\mathcal{S}$}
		\big\}.
	\end{align}
	Clearly we have $\mathcal{F}_{\text{d}}'(\epsilon)\subset \mathcal{F}_{\text{d}}(\epsilon)$.

	Now for each
	\begin{equation}
		p_{G}(x) := \textstyle\sum_{j=1}^N w_j \prod_{i=1}^{k} \tfrac{1}{\sigma_j} \phi\big(\tfrac{x_i-\mu_j}{\sigma_j}\big) \in \mathcal{F}_{\text{d}}(\epsilon),
	\end{equation}
	we choose the 
	\begin{equation}
		p_{G'}(x) := \textstyle\sum_{j=1}^N w_j' \prod_{i=1}^{k} \tfrac{1}{\sigma_j'} \phi\big(\tfrac{x_i-\mu_j'}{\sigma_j'}\big) \in \mathcal{F}_{\text{d}}'(\epsilon),
	\end{equation}
	that is closest in the sense that 
	$|\mu_j-\mu_j^\prime| < \epsilon$, and $|\sigma_j - \sigma_j'| < \epsilon$, and 
	$\textstyle\sum_{j=1}^N |w_j - w_j'| < \epsilon$ for all $j=1,\dots,N$.

	Then
	\begin{align}
		&\sup_x
		\big|
		p_G(x) - p_{G'}(x)
		\big|
		\nonumber\\
		\leq&
		\sup_x 
		\bigg|
		\sum_j^N w_j 
		\bigg\{\prod_{i=1}^{k} \tfrac{1}{\sigma_j} \phi\big(\tfrac{x_i-\mu_j}{\sigma_j}\big) - \prod_{i=1}^{k} \tfrac{1}{\sigma_j} \phi\big(\tfrac{x_i-\mu_j'}{\sigma_j}\big)\bigg\}
		\bigg|
		\nonumber\\
		+&
		\sup_x 
		\bigg|
		\sum_j^N w_j 
		\bigg\{\prod_{i=1}^{k} \tfrac{1}{\sigma_j} \phi\big(\tfrac{x_i-\mu_j'}{\sigma_j}\big)
		- \prod_{i=1}^{k} \tfrac{1}{\sigma_j'} \phi\big(\tfrac{x_i-\mu_j'}{\sigma_j'}\big)\bigg\}
		\bigg|
		\nonumber\\
		+&
		\sup_x 
		\bigg|
		\sum_j^N [w_j - w_j'] \prod_{i=1}^{k} \tfrac{1}{\sigma_j'} \phi\big(\tfrac{x_i-\mu_j'}{\sigma_j'}\big)
		\bigg|.
		\label{eq:vdv.lem.3.4.1}
	\end{align}
	Using the identity 
	\begin{equation}
		\prod_{i=1}^{k} z_i - \prod_{i=1}^{k} y_i = 
		\sum_{i=1}^k \big(\textstyle\prod_{s=1}^{i-1}y_s\big) (z_i-y_i) \big(\textstyle\prod_{s=i+1}^{k} z_s\big)
	\end{equation}
	and the fact that the derivatives of $\tfrac{1}{\sigma}\phi\big(\tfrac{x}{\sigma}\big)$ with respect to $\sigma$ and $x$ are uniformly bounded for $\sigma > \underline{\sigma}$, we show that the first and second terms on the RHS of \eqref{eq:vdv.lem.3.4.1} are bounded by constant multiples of $\sup_{j\leq N}|\mu_j-\mu_j'| < \epsilon$ and $\sup_{j\leq N}|\sigma_j-\sigma_j'| < \epsilon$ respectively. And again using a similar argument we can show that the final term on the RHS of \eqref{eq:vdv.lem.3.4.1} is bounded by a constant multiple of $\textstyle\sum_{j=1}^N |w_j-w_j'|<\epsilon$.

	Thus we have $\sup_x
	\big|
	p_G(x) - p_{G'}(x)
	\big| \lesssim \epsilon$, which implies that $\mathcal{F}_{\text{d}}'(\epsilon)$ is a $\epsilon$-net over $\mathcal{F}_{\text{d}}(\epsilon)$, and consequently a $2\epsilon$-net over $\mathcal{F}(\epsilon)$.
	Furthermore, the cardinality of $\mathcal{F}_{\text{d}}'(\epsilon)$ is 
	\begin{equation}
		| \mathcal{F}_{\text{d}}'(\epsilon)| 
		\lesssim 
		\big( \tfrac{2\bar{\mu}}{\epsilon}\big)^N \cdot 
		\big( \tfrac{\bar{\sigma}-\underline{\sigma}}{\epsilon}\big)^N \cdot 
		\big( \tfrac{5}{\epsilon}\big)^N 
		=\big(10\bar{\mu}[\bar{\sigma}-\underline{\sigma}]\big)^N \epsilon^{-3N}.
	\end{equation}
	This implies we have for some constants $(C_1,C_2)$
	\begin{align}
		&\log N(C_1\epsilon , \mathcal{F}(\epsilon),||\cdot||_\infty)
		\nonumber\\
		\leq&
		N \log\big( 10 \bar{\mu} [\bar{\sigma}-\underline{\sigma}] \big)
		+ 3N \log\big(\tfrac{1}{\epsilon}\big) + C_2
		\nonumber\\
		\lesssim&
		\big(\log\tfrac{1}{\epsilon}\big)^{4[\gamma_1+\gamma_2]} 
		\cdot \log\big(10L^2 \log\big[\tfrac{1}{\epsilon}\big]^{\gamma_1+\gamma_2}\big)
		+ 
		\big(\log\tfrac{1}{\epsilon}\big)^{4[\gamma_1+\gamma_2]} \log\big(\tfrac{1}{\epsilon}\big)
		\nonumber\\
		\lesssim&
		\big(\log\tfrac{1}{\epsilon}\big)^{4[\gamma_1+\gamma_2] + 1}.
	\end{align}
\end{proof}





\begin{lemma}
	\label{lem:vdv.lem.3.4}
	Suppose $\gamma_1\geq \frac{1}{2}$, $\gamma_2\geq 0$. For any $G\in \mathcal{G}(\epsilon)$, there exists 
	a discrete $G'\in\mathcal{G}(\epsilon)$ 
	with at most $N\lesssim (\log\tfrac{1}{\epsilon})^{4[\gamma_1+\gamma_2]}$ support points such that 
	\begin{equation}
		|| p_G - p_{G'} ||_\infty < \epsilon. 
	\end{equation}
\end{lemma}
\begin{proof}
	Throughout this proof, let 
	$\bar{\mu}:= L (\log \frac{1}{\epsilon})^{\gamma_1}$, $\bar{\sigma}:= L (\log \frac{1}{\epsilon})^{\gamma_2}$ 
	and
	\begin{equation}
		M := \max\left(\bar{\mu} + \bar{\sigma}\bar{\mu} , \sqrt{8} \bar{\sigma} (\log\tfrac{1}{\epsilon})^{1/2}\right).
	\end{equation}
	Note that we have 
	\begin{align}
		\sup_{\max_i|x_i| > M}
		|p_G(x) - p_{G'}(x)| 
		\leq_{(1)}& 
		2\tfrac{1}{\underline{\sigma}^{k-1}} \phi^{k-1}(0) 
		\tfrac{1}{\bar\sigma}\phi\left(\tfrac{M-\bar{\mu}}{\bar{\sigma}}\right) 
		\nonumber\\
		\leq_{(2)}&
		2\tfrac{1}{(\sqrt{2\pi}\underline{\sigma})^{k-1}}
		\tfrac{1}{\bar\sigma}\phi\left(\tfrac{M}{2\bar{\sigma}}\right) 
		\nonumber\\
		=& 
		2\tfrac{1}{(\sqrt{2\pi}\underline{\sigma})^{k-1}}
		\tfrac{1}{\sqrt{2\pi}\bar{\sigma}}\exp(-\tfrac{1}{8\bar{\sigma}^2} M^2 )
		\nonumber\\
		\leq& 
		2\tfrac{1}{(\sqrt{2\pi}\underline{\sigma})^{k-1}}
		\tfrac{1}{\sqrt{2\pi}\bar{\sigma}}\exp(-\log\tfrac{1}{\epsilon} ) )
		\\
		\lesssim& 
		\tfrac{1}{\underline{\sigma}^{k-1}} \epsilon
	\end{align}
	where $\leq_{(1)}$ follows by the triangle inequality and the fact that the function $\tfrac{1}{\sigma} \phi(\tfrac{y}{\sigma})$ has a derivative (w.r.t. $\sigma$) of $\tfrac{1}{\sigma^2}[\tfrac{y^2}{\sigma}-1]\phi(\tfrac{y}{\sigma})$ that is positive for the region $y^2>\sigma$. Furthermore $\leq_{(2)}$ follows because we can assume WLOG\footnote{This is because this lemma is only utilized for small enough $\epsilon$.} $\bar{\sigma}\geq1$, such that $M \leq 2(M-\bar{\mu})$.

	Next note that
	\begin{equation}
		\prod_{i=1}^k \tfrac{1}{\sigma} \phi(\tfrac{x_i-\mu}{\sigma}) 
		= 
		\tfrac{1}{(\sqrt{2\pi}\sigma)^{k-1}} \cdot 
		\tfrac{1}{\sqrt{2\pi}\sigma } \exp \left( -\tfrac{[\sum_i(x_i-\mu)^2]}{2\sigma^2} \right)
	\end{equation}
	and use the approximation 
	\begin{equation}
		\big|
		e^y - \sum_{j=1}^{l-1} \tfrac{1}{j!} y^j 
		\big|
		\leq
		\tfrac{(e{y})^l}{l^l}
	\end{equation}
	for all $y<0$ and $l>1$, together with the substitution $y=-\tfrac{z}{2\sigma^2}$ for $z>0$, 
	to arrive at 
	\begin{equation}
		\bigg| 
		\tfrac{1}{\sqrt{2\pi}\sigma} \exp(-\tfrac{z}{2\sigma^2})
		- 
		\underbrace{\tfrac{1}{\sqrt{2\pi}\sigma} \sum_{j=1}^{l-1} \tfrac{1}{j!} \big(-\tfrac{z}{2\sigma^2}\big)^j	}_{=\sum_{j=1}^{l-1} \tfrac{(-1)^j}{\sqrt{2\pi}\sigma\cdot j!} \big(\tfrac{z}{2\sigma^2}\big)^j}	
		\bigg|
		\leq
		\underbrace{\tfrac{1}{l^l} (e\tfrac{z}{2\sigma^2})^l \tfrac{1}{\sqrt{2\pi}\sigma} }_{=\tfrac{1}{\sqrt{2\pi}\sigma}\tfrac{(e2^{-1}z/\sigma^2)^l}{l^l}}
	\end{equation}
	then by substituting $z$ with $\sum_{i=1}^{k}[x_i-\mu]^2$ we have 
	\begin{align}
		&
		\underbrace{\tfrac{1}{(\sqrt{2\pi}\sigma)^{k-1}}\bigg|
			\tfrac{1}{\sqrt{2\pi}\sigma} \exp\big(-\tfrac{\sum_i[x_i-\mu]^2}{2\sigma^2}\big)}_{=\prod_{i=1}^k \tfrac{1}{\sigma}\phi(\tfrac{x_i-\mu}{\sigma})}
		-
		\tfrac{1}{\sqrt{2\pi}\sigma} \sum_{j=1}^{l-1} (-1)^j \tfrac{1}{\sqrt{2\pi}j!} \big(-\tfrac{1}{2\sigma^2}\sum_i[x_i-\mu]^2\big)^j
		\bigg|
		\nonumber\\
		\leq& 
		\tfrac{1}{(\sqrt{2\pi}\sigma)^{k-1}}
		\tfrac{1}{\sqrt{2\pi}} \tfrac{1}{l^l} \big(e\tfrac{1}{2\sigma^2}\sum_i[x_i-\mu]^2\big)^l.
	\end{align}

	Thus we have 
	\begin{align}
		&\sup_{\vee_i|x_i| \leq M} \big| p_G(x) - p_{G'}(x)\big|
		\nonumber\\
		\leq &
		\sup_{\vee_i|x_i| \leq M} 
		\bigg| 
		\int \tfrac{1}{(\sqrt{2\pi}\sigma)^k} \sum_{j=1}^{l-1} (-1)^j \tfrac{1}{\sqrt{2\pi}j!}
		\big(\tfrac{1}{2\sigma^2}\sum_{i=1}^{k}[x_i-\mu]^2\big)^j d(G-G')(\mu,\sigma)
		\bigg|
		\nonumber\\
		&+	
		2 \sup_{\substack{ \vee_i|x_i| \leq M, \\ |\mu|\leq\bar{\mu} \ , \ \underline{\sigma}\leq\sigma\leq\bar{\sigma} }}
		\bigg|
		\tfrac{1}{(\sqrt{2\pi}\sigma)^k} \tfrac{1}{l^l} \big(e\tfrac{1}{2\sigma^2} \sum_{i=1}^{k}[x_i-\mu]^2\big)^l
		\bigg|
		\nonumber\\
		=&
		\sup_{\vee_i|x_i| \leq M} 
		\bigg| 
		\int \tfrac{1}{(\sqrt{2\pi})^k} \sum_{j=1}^{l-1} (-1)^j \tfrac{1}{\sqrt{2\pi}j!}
		\tfrac{1}{2^j} \sigma^{-(2j+k)} \big(\sum_{i=1}^{k}[x_i-\mu]^2\big)^j d(G-G')(\mu,\sigma)
		\bigg|
		\nonumber\\
		&+	
		2 \sup_{\substack{ \vee_i|x_i| \leq M, \\ |\mu|\leq\bar{\mu} \ , \ \underline{\sigma}\leq\sigma\leq\bar{\sigma} }}
		\tfrac{1}{(\sqrt{2\pi})^k} \tfrac{1}{l^l} e^l \tfrac{1}{2^l} \sigma^{-(2l+k)} \big(\sum_{i=1}^{k} [x_i-\mu]^2\big)^2.
		\label{eq:vdv.2}
	\end{align}
	The first term on the RHS of \eqref{eq:vdv.2} contains $(l-1)$ different powers of $\sigma^{-1}$ and $2(l-1)$ different powers of $\mu$. This term will therefore be zero if we are able to match the corresponding $2(l-1)^2$ moments of $G$ and $G'$. 

	Now consider the second term on the RHS of \eqref{eq:vdv.2}. First note that 
	\begin{align}
		&\sup_{ \vee_i|x_i| \leq M \ , \ |\mu|\leq\bar{\mu} }
		|x_i-\mu| 
		\nonumber\\
		\leq& M + \bar{\mu} 
		\nonumber\\
		\leq& \max([2+\bar{\sigma}]\bar{\mu}, \sqrt{8}\bar{\sigma}(\log \tfrac{1}{\epsilon})^{1/2})
		\nonumber\\
		\leq& \max\big(C_1 (\log\tfrac{1}{\epsilon})^{\gamma_1+\gamma_2}, C_2 (\log\tfrac{1}{\epsilon})^{1/2+\gamma_2}\big) 
		\nonumber\\
		\leq&
		C_3 (\log\tfrac{1}{\epsilon})^{\gamma_1+\gamma_2}
	\end{align}
	where the final inequality follows by $\gamma_1\geq\tfrac{1}{2}$, and therefore we have that the second term on the RHS of \eqref{eq:vdv.2} is smaller than 
	\begin{align}
		&\tfrac{1}{(\sqrt{2\pi})^k} \cdot \underline{\sigma}^{-(2l+k)} \big(\tfrac{e}{2}\sum_{i=1}^{k}[x_i-\mu]^2\big)^l \tfrac{1}{l^l} 
		\nonumber\\
		\leq& 
		\tfrac{1}{(\sqrt{2\pi})^k} \cdot \underline{\sigma}^{-(2l+k)}
		\big[C_4 k \cdot (\log\tfrac{1}{\epsilon})^{2(\gamma_1+\gamma_2)}\big]^l \tfrac{1}{l^l}
		\nonumber\\
		\leq&
		\tfrac{1}{(\sqrt{2\pi})^k} \cdot \underline{\sigma}^{-(2l+k)}
		\exp\left(
		-l\big[\log l - 2\log(C_5[\log\tfrac{1}{\epsilon}]^{\gamma_1+\gamma_2})\big]
		\right)
		\label{eq:vdv.3}
	\end{align}
	and by choosing $l=l^*$ where $l^*$ is the smallest integer exceeding $(1+C_5^2)(\log\tfrac{1}{\epsilon})^{2[\gamma_1+\gamma_2]}$ we will have that
	\begin{equation}
		\log\left[
		\frac{l^*}{C_5^2 [\log\tfrac{1}{\epsilon}]^{2[\gamma_1+\gamma_2]} }
		\right]
		\geq 
		\log\big[1+\tfrac{1}{C_5^2}\big] =: C_6 > 0
	\end{equation}
	so that the exponential term of \eqref{eq:vdv.3} is smaller than 
	\begin{align}
		\exp(-l^*\cdot C_6) \leq& 
		\exp(-C_7 (\log\tfrac{1}{\epsilon})^{2[\gamma_1+\gamma_2]}) 
		\nonumber\\
		\leq& \exp(-\log\tfrac{1}{\epsilon}) = \epsilon
	\end{align}
	where the final inequality follows because $2\gamma_1\geq1$,
	and we conclude that 
	\begin{equation}
		\tfrac{1}{(\sqrt{2\pi})^k} \cdot \underline{\sigma}^{-(2l+k)}
		\exp\left(
		-l\big[\log l - 2\log(C_5[\log\tfrac{1}{\epsilon}]^{\gamma_1+\gamma_2})\big]
		\right)
		\lesssim \epsilon.
	\end{equation}

	Therefore, by Lemma A.1. of \cite{Ghosal2001}, we can find a discrete distribution $G'$ with
	\begin{equation}
		2(l^*-1)^2\asymp (\log\tfrac{1}{\epsilon})^{4[\gamma_1+\gamma_2]}
	\end{equation} 
	number of support points such that $|| p_G - p_{G'} ||_\infty \lesssim \epsilon$.
\end{proof}



