\section{Variational Inference with Linear Constraints}
\label{app:VI_FE}

This appendix derives the optimal variational distribution for a Gaussian likelihood with linear equality constraints on parameter $\bm{\gamma}$ such that $\bm{L}\bm{\gamma} = \bm{0}$. It further shows that if $\bm{\gamma}$ represents (high-dimensional) fixed effects, then inference can be performed extremely efficiently---in linear computational cost and memory. Thus, this establishes that representing multinomial logistic regression as Poisson regression with high-dimensional fixed effects and performing CAVI assuming independence between the fixed effects and other parameters is a computationally feasible methodology even for large problems.

Result~\ref{result:fe}, stated below, first considers the case of arbitrary equality constraints.

\begin{result}(Variational Inference with Linear Equality Constraints)
	\label{result:fe}
	Define $\bm{X}$ as an $N \times p$ matrix with rank $p$. Define $\bm{L}$ as a $C \times p$ matrix with rank $C$. Consider the coordinate ascent variational inference (CAVI) update of $q(\bm{\gamma})$ where the variational distribution of all other parameters $\bm{\theta}$ is $q(\bm{\theta})$ and $q(\bm{\theta},\bm{\gamma}) = q(\bm{\theta})q(\bm{\gamma})$. Assume the expectation of the log-posterior with respect to $q(\bm{\theta})$ is as follows and $\bm{L}\bm{\gamma} = \bm{0}$.

	\begin{equation*}
	E_{q(\bm{\theta})}\left[\ln p(\bm{y}, \bm{\theta}, \bm{\gamma})\right] \propto -\frac{1}{2} || \bm{v} - \bm{X} \bm{\gamma}||_2^2 \quad \mathrm{s.t.} \quad \bm{L}\bm{\gamma}=\bm{0}    
	\end{equation*}

	Then, the optimal approximating distribution on $\bm{\gamma}$ is a \emph{singular} multivariate Gaussian with rank $p-C$ with mean $\bm{\mu}_{\bm{\gamma}}$ and variance $\bm{\Lambda}_{\bm{\gamma}}$ as shown below as well as the log pseudo-determinant (the sum of the log of the non-zero singular values) of $\bm{\Lambda}_{\bm{\gamma}}$, i.e. $\ln|\bm{\Lambda}_{\bm{\gamma}}|_+$,

	\begin{align*}
	\hat{\bm{\gamma}}_{OLS} &= \left(\bm{X}^T\bm{X}\right)^{-1} \bm{X}^T\bm{v}; ~\bm{P}_{\bm{L},\bm{X}} = \bm{L}^T\left(\bm{L}\left[\bm{X}^T\bm{X}\right]^{-1}\bm{L}^T\right)^{-1}\bm{L} \\
	\bm{\mu}_{\bm{\gamma}} &= \hat{\bm{\gamma}}_{OLS} - \left(\bm{X}^T\bm{X}\right)^{-1} \bm{P}_{\bm{L},\bm{X}}~\hat{\bm{\gamma}}_{OLS}; \quad \bm{\Lambda}_{\bm{\gamma}} = \left(\bm{X}^T\bm{X}\right)^{-1} - \left(\bm{X}^T\bm{X}\right)^{-1} \bm{P}_{\bm{L},\bm{X}}\left(\bm{X}^T\bm{X}\right)^{-1} \\
	\ln|\bm{\Lambda}_{\bm{\gamma}}|_{+} &= \ln|\bm{L}\bm{L}^T| - \ln|\bm{X}^T\bm{X}| - \ln|\bm{L}\left(\bm{X}^T\bm{X}\right)^{-1}\bm{L}^T|
	\end{align*}

	Further, the ELBO takes the following form:
	\begin{align*}
	\mathrm{ELBO} = \mathbb{E}_{q(\bm{\theta})q(\bm{\gamma})}\left[\ln p(\bm{y}, \bm{\theta}, \bm{\gamma})\right] - \mathbb{E}_{q(\bm{\theta})}[\ln q(\bm{\theta})] + \frac{1}{2} \ln|\bm{\Lambda}_{\bm{\gamma}}|_+
	\end{align*}
\end{result}

\begin{proof}
	Define $\bm{M}$ as any orthogonal basis of the nullspace of $\bm{L}$, i.e. $\bm{L}\bm{M}\bm{a} = \bm{0}$ for any vector $\bm{a}$ and $\bm{M}^T\bm{M} = \bm{I}$. Standard results on constrained least squares (e.g., \citealt{lawson1974linear}) imply that one can re-parameterize the problem to perform inference on a $p-C$ unconstrained parameter vector $\bm{\gamma}^*$ where $\bm{\gamma} = \bm{M}\bm{\gamma}^*$. In this case, the expectation of the log-posterior over $q(\bm{\theta})$ becomes
	\begin{equation*}
	E_{q(\bm{\theta})}\left[\ln p(\bm{y}, \bm{\theta}, \bm{\gamma}^*)\right] \propto -\frac{1}{2} || \bm{v} - \bm{X} \bm{M} \bm{\gamma}^*||_2^2.
	\end{equation*}

	Standard results (e.g., \citealt{bishop2006ml}) give the optimal variational approximation as

	$$q(\bm{\gamma}^*) \sim N\left(\left[\bm{M}^T\bm{X}^T\bm{X}\bm{M}\right]^{-1} \bm{M}^T\bm{X}^T\bm{v}, \left[\bm{M}^T\bm{X}^T\bm{X}\bm{M}\right]^{-1} \right).$$

	If we return to the parameterization on $\bm{\gamma}$, the optimal variational approximation is 

	$$q(\bm{\gamma}) \sim N\left(\bm{M}\left[\bm{M}^T\bm{X}^T\bm{X}\bm{M}\right]^{-1} \bm{M}^T\bm{X}^T\bm{v}, \bm{M}\left[\bm{M}^T\bm{X}^T\bm{X}\bm{M}\right]^{-1}\bm{M}^T \right).$$

	Given that $\bm{X}^T\bm{X}$ is invertible, the following identity holds
	\begin{align*}
	&\bm{M}\left[\bm{M}^T\bm{X}^T\bm{X}\bm{M}\right]^{-1}\bm{M}^T = \left(\bm{X}^T\bm{X}\right)^{-1}\left[\bm{X}^T\bm{X} - \bm{P}_{\bm{L},\bm{X}} \right]\left(\bm{X}^T\bm{X}\right)^{-1} \\
	&\bm{P}_{\bm{L},\bm{X}} = \bm{L}^T\left(\bm{L}\left[\bm{X}^T\bm{X}\right]\bm{L}\right)^{-1}\bm{L}.
	\end{align*}
	Thus, $q(\bm{\gamma})$ can be re-arranged to as follows:
	\begin{align*}
	q(\bm{\gamma}) &\sim N\left(\bm{\mu}_{\bm{\gamma}}, \bm{\Lambda}_{\bm{\gamma}}\right) \\
	\bm{\mu}_{\bm{\gamma}} &= \left(\bm{X}^T\bm{X}\right)^{-1}\left[\bm{X}^T\bm{X} - \bm{P}_{\bm{L},\bm{X}}\right] \hat{\bm{\gamma}}_{OLS}; \quad \hat{\bm{\gamma}}_{OLS} = \left(\bm{X}^T\bm{X}\right)^{-1}\bm{X}^T\bm{\nu} \\
	\bm{\Lambda}_{\bm{\gamma}} &= \left(\bm{X}^T\bm{X}\right)^{-1}\left[\bm{X}^T\bm{X} - \bm{P}_{\bm{L},\bm{X}} \right]\left(\bm{X}^T\bm{X}\right)^{-1}
	\end{align*}
	\cite{ameli2023singular} provide results on evaluating pseudo-determinants; their results can be used to show that

	$$\ln|\bm{\Lambda}_{\bm{\gamma}}|_+ = \ln|\bm{L}\bm{L}^T| - \ln|\bm{X}^T\bm{X}| - \ln|\bm{L}\left(\bm{X}^T\bm{X}\right)^{-1} \bm{L}^T|.$$

	This establishes the first part of the result. For evaluating the ELBO, consider if inference were performed on the unconstrained $\bm{\gamma}^*$. In this case,
	$$\mathrm{ELBO} = \mathbb{E}_{q(\bm{\theta})q(\bm{\gamma}^*)}\left[\ln p(\bm{y}, \bm{\theta}, \bm{\gamma}^*)\right] - \mathbb{E}_{q(\bm{\theta})}[\ln q(\bm{\theta})] + \frac{1}{2} \ln\left|\left[\bm{M}^T\bm{X}^T\bm{X}\bm{M}\right]^{-1}\right|.$$

	Note that if we re-parameterize and use $q(\bm{\gamma})$ instead of $q(\bm{\gamma}^*)$, the first term remains unchanged by definition. The final term, the entropy of $q(\bm{\gamma}^*)$, can be evaluated as follows. \cite{knill2014pseudo} establishes the following identity of pseudo-determinants: $|\bm{F}^T\bm{G}|_+ = |\bm{F}\bm{G}^T|_+$. Noting this and that $\bm{M}^T\bm{M} = \bm{I}$,
	$$\left|\left[\bm{M}^T\bm{X}^T\bm{X}\bm{M}\right]^{-1}\right| = \left|\bm{\Lambda}_{\bm{\gamma}}\right|_+.$$

	To establish the remaining claim, we re-parameterize the ELBO in terms $\bm{\gamma}$, 
	$$\mathrm{ELBO} = \mathbb{E}_{q(\bm{\theta})q(\bm{\gamma})}\left[\ln p(\bm{y}, \bm{\theta}, \bm{\gamma})\right] - \mathbb{E}_{q(\bm{\theta})}[\ln q(\bm{\theta})] + \frac{1}{2} \ln\left|\bm{\Lambda}_{\bm{\gamma}}\right|_+.$$
\end{proof}

In interpreting Result~\ref{result:fe}, we thus note that CAVI can be performed on $\bm{\gamma}$, and is equivalent to performing CAVI on the unconstrained $\bm{\gamma}^*$, but it does not require explicitly forming or using a basis $\bm{M}$. We note that the optimal variational distribution $q(\bm{\gamma})$ also exactly coincides with the distribution of an OLS estimator with linear constraints (e.g., \citealt{greeneRLS1991}).

However, in practice, Result~\ref{result:fe} is not computationally feasible for large-scale problems. Consider the case of fixed effects where $\bm{X}$ is high-dimensional, i.e. $p$ is large, and $\bm{1}^T\bm{\gamma} = 0$. Note that $q(\bm{\gamma})$ is a \textbf{dense} $p \times p$ (singular) multivariate Gaussian and thus extremely computationally expensive to store and manipulate. Result~\ref{result:simple_fe} shows that in the case of fixed effects, this high cost can be avoided.

\begin{result}{(Simplified Inference for Classical Fixed Effects)}
	\label{result:simple_fe}
	Assume that $\bm{\gamma}$ has a variational distribution as defined from Result~\ref{result:fe}. Further assume that each row $\bm{x}_i$ of $\bm{X}$ is ``one-hot'', i.e. has one element with value 1 and all others with value 0. Define $\bm{d}$ as a vector corresponding to the diagonal elements of $\bm{X}^T\bm{X}$  and that $\bm{L} = \bm{1}^T$. Define $\bm{u}$ as a vector such that $u_j = 1/d_j$. $\bm{a} \odot \bm{b}$ denotes the Hadamard (elementwise) product. Then, the mean, the diagonal of $\bm{\Lambda}_{\bm{\gamma}}$ and log pseudo-determinant of $q(\bm{\gamma})$ are shown below. These can all be evaluated and stored at cost $\mathcal{O}(p)$.
	$$\hat{\bm{\gamma}}_{\mathrm{OLS}} = \bm{u} \odot \left(\bm{X}^T\bm{v}\right)$$
	$$\bm{\mu}_\gamma = \hat{\bm{\gamma}}_{OLS} - \bm{u} \cdot \frac{\left[\hat{\bm{\gamma}}_{OLS}\right]^T \bm{1}}{\bm{u}^T\bm{1}}$$
	$$\mathrm{diagonal}(\bm{\Lambda}_{\bm{\gamma}}) =  \bm{u} - \left(\bm{u} \odot \bm{u}\right) \cdot \frac{1}{\bm{u}^T\bm{1}} $$
	$$\ln\mathrm{det}^*(\bm{\Lambda}_{\bm{\gamma}}) =  \ln(\bm{u})^T\bm{1}  - \ln|\bm{u}^T\bm{1}|$$

	Further, $E_{q(\bm{\gamma})}[\bm{x}_i^T\bm{\gamma}]$ and $\mathrm{Var}_{q(\bm{\gamma})}[\bm{x}_i^T \bm{\gamma}]$ can be evaluated at $\mathcal{O}(1)$ for any row $\bm{x}_i$ of $\bm{X}$.
\end{result}
\begin{proof}
	The simplification of the moments and log-determinant of $q(\bm{\gamma})$ follows directly with simple algebraic re-arrangement from Result~\ref{result:fe}, noting $\bm{X}^T\bm{X}$ is a diagonal matrix by definition. For the second claim, as $\bm{x}_i$ is a one-hot vector, define index $j[i]$ as the position of the single non-zero element for row $i$. Then, note that $\bm{x}_i^T\bm{\gamma} = \bm{\gamma}_{j[i]}$, i.e. it picks out only the $j$-th element of $\bm{\gamma}$. Thus, its mean and variance can be directly read off of the simplified moments above. 
\end{proof}

The key implication of Result~\ref{result:simple_fe} is that, in the case of fixed effects---i.e. a sparse $\bm{X}$ with each row being one-hot---inference can be performed at a cost and memory requirement that scales linearly in the number of fixed effects $p$. Thus, even for huge problems, CAVI can be implemented cheaply as the only terms in the ELBO that depend on $\bm{\gamma}$ are the log-determinants and functions of the mean and variance of $\bm{x}_i^T\bm{\gamma}$. 

Interestingly, even if there are multiple high-dimensional fixed effects, this variational model can be easily implemented assuming independence between the fixed effects. Exploring this for other high-dimensional fixed effects problems is an interesting area for future research.

\section{Variational Inference for Poisson Likelihood}
\label{app:VI_poisson}

This appendix derives the ELBO and coordinate ascent variational inference (CAVI) algorithm for estimating the optimal variational distribution. The exposition follows the ``general design'' notation from \cite{zhao2006mlm}. Equation~\ref{eq:model_gendesign} replicates the generative model in \cite{goplerud2022mavb}, adapting only the likelihood to be Poisson. As that paper notes,

\begin{quote}
	``[this model] uses conditionally conjugate Inverse-Wishart priors on the variance components $\bm{\Sigma}_j$, a flat prior on the fixed effects $\bm{\beta}$, and the conventional normal prior on the random effects. $\bm{z}^b_{i,j}$ represents the covariates for individual $i$ for random effect $j$, e.g. $\bm{z}^b_{i,j} = 1$ for a random intercept. Each random effect $j \in \{1, \cdots, J\}$ has $g_j$ levels ... and a dimensionality of $d_j$ (e.g., $d_j = 1$ for a random intercept). \end{quote}

\begin{align}
\label{eq:model_gendesign}
\begin{split}
&y_i | \bm{\beta}, \bm{\alpha} \sim \mathrm{Poisson}(\lambda_i), \quad \lambda_i = \exp(\psi_i), \quad \psi_i = \bm{x}_i^T\bm{\beta} + \bm{z}_i^T\bm{\alpha} \\
&\bm{\alpha}_{j} | \bm{\Sigma}_j \sim N\left(\bm{0}, \bm{I}_{g_j} \otimes \bm{\Sigma}_j\right), \quad \bm{\Sigma}_j \sim \mathrm{IW}(\nu_j, \bm{\Phi}_j), \quad p(\bm{\beta}) \propto 1  \\
& \bm{z}_{i,j} = \bm{m}_{i,j} \otimes \bm{z}^b_{i,j}, \quad \bm{\alpha}^T = [\bm{\alpha}^T_1, \cdots, \bm{\alpha}^T_J], \quad \bm{z}_i^T = [\bm{z}_{i,1}^T, \cdots, \bm{z}_{i,J}^T]
\end{split}
\end{align}

A second presentation of the model follows the notation in \cite{gelman2006multi} and separately presents each random effect.

\begin{align}
\label{eq:model_gh}
\begin{split}
y_i | \bm{\beta}, \{\{\bm{\alpha}_{j,g}\}_{g=1}^{g_j}\}_{j=1}^J &\sim \mathrm{Poisson}(\lambda_i), \quad \lambda_i = \exp(\psi_i), \quad \psi_i = \bm{x}_i^T\bm{\beta} + \sum_{j=1}^J \left[\bm{z}^b_{i,j}\right]^T \bm{\alpha}_{j, g[i]} \\
&\bm{\alpha}_{j,g} | \bm{\Sigma}_j \sim N(\bm{0}_{d_j}, \bm{\Sigma}_j), \quad \bm{\Sigma}_j \sim \mathrm{IW}(\nu_j, \bm{\Phi}_j) \quad \forall (j,g), \quad p(\bm{\beta}) \propto 1
\end{split}
\end{align}

Following existing work, we assume that the variational distributions $q(\bm{\beta}, \{\bm{\alpha}_j\}_{j=1}^J)$ factorizes into independent distributions: $q(\bm{\beta})\prod_{j=1}^J q(\bm{\alpha}_j)$. As is common for variational inference with Poisson outcomes (e.g., \citealt{wand2014fully}), we further assume that each of those variational distributions has a multivariate Gaussian form. As is standard, we assume that $q(\{\bm{\Sigma}_j\}_{j=1}^J)$ is independent from the other parameters. This is sufficient to imply that the variational distribution of each $\bm{\Sigma}_j$ is independent from all others.

With this in hand, the ELBO can be derived as shown below (e.g., \citealt{wand2014fully}). Define $\mathrm{diagonal}(\bm{W})$ to take the diagonal elements of some matrix $\bm{W}$ and $\mathrm{diag}(\bm{w})$ to create a diagonal matrix with some vector $\bm{w}$ along the diagonal. For simplicity, we only show the portion of the ELBO that involves $q(\bm{\alpha}_j)$ and $q(\bm{\beta})$ as all updates for $q(\bm{\Sigma}_j)$ are standard. We show this using the most compact notation although note that $\bm{\Lambda}_{\alpha,j}$ is (block) diagonal.

\begin{equation}
\begin{split}
&\bm{w} = \exp\left(\bm{X} \bm{\mu}_{\beta} + \frac{1}{2} \mathrm{diagonal}\left[\bm{X} \bm{\Lambda}_{\beta}\bm{X}^T\right] + \sum_{j=1}^T \bm{Z}_j\bm{\mu}_{\alpha,j} + \frac{1}{2} \mathrm{diagonal}\left[\bm{Z} \bm{\Lambda}_{\alpha,j}\bm{Z}^T\right]\right) \\ 
& [\bm{w}]_i = \exp\left(\bm{x}_i^T\bm{\mu}_\beta + \frac{1}{2} \bm{x}_i^T\bm{\Lambda}_{\beta} \bm{x}_i + \sum_{j=1}^J \bm{z}_{i,j}^T\bm{\mu}_{\alpha,j} + \frac{1}{2} \bm{z}_{i,j}^T\bm{\Lambda}_{\alpha,j} \bm{z}_{i,j} \right) \\
&\mathrm{ELBO}_{q(\bm{\theta})} =~ \cdots + \bm{y}^T\left[\bm{X} \bm{\mu}_{\bm{\beta}} + \bm{Z}\bm{\mu}_{\bm{\alpha}}\right] - \bm{1}^T\bm{w} + \\
&\frac{1}{2}\ln|\bm{\Lambda}_\beta| + \sum_{j=1}^J - \frac{1}{2} \mathrm{tr}\left(\left[\bm{\mu}_{\alpha,j}\bm{\mu}_{\alpha,j}^T + \bm{\Lambda_{\alpha,j}}\right] \left[\bm{I} \otimes E_{q(\bm{\Sigma}_j)}\left[\bm{\Sigma}_j^{-1}\right]\right]\right) + \frac{1}{2} \ln|\bm{\Lambda}_{\alpha,j}| + \cdots
\end{split}
\end{equation}

Updating $q(\bm{\beta})$ and $q(\bm{\alpha}_j)$ is more challenging because of the dependence of the weights $\bm{w}$ on those variational distributions. \cite{wand2014fully} proposes non-conjugate variational message passing that can be adapted to this case; he presents an algorithm for a Poisson hierarchical model with a single random effect. This can be adapted into a cyclical algorithm for arbitrary $J$. Algorithm~\ref{alg:CAVI} reports how to update $q(\bm{\beta})$ and $q(\bm{\alpha})$.

\begin{algorithm}[!ht]
	\caption{CAVI Updates for $q(\bm{\beta})$ and $q(\bm{\alpha})$}
	\label{alg:CAVI}
	\begin{algorithmic}	
		\State{\textbf{Initialize Variational Parameters}: Assume that $\{q(\bm{\Sigma}_j)\}_{j=1}^J$ are known and define the initial values of the variational parameters as $\bm{\mu}^{(0)}_{\bm{\beta}}$, $\bm{\Lambda}^{(0)}_{\bm{\beta}}$ for $q(\bm{\beta})$ and $\{\bm{\mu}^{(0)}_{\alpha,j}, \bm{\Lambda}^{(0)}_{\alpha,j}\}_{j=1}^J$  for $\{q(\bm{\alpha}_j)\}_{j=1}^J$}

		\vspace{1em}

		\State{0. Compute $\bm{w}$. Define $\bm{W} = \mathrm{diag}(\bm{w})$.}

		$$\ln \bm{w}^{(0)} = \bm{X}\bm{\mu}^{(0)}_{\bm{\beta}} + \bm{Z}\bm{\mu}^{(0)}_{\bm{\alpha}} + \frac{1}{2} \mathrm{diagonal}\left(\bm{X}\bm{\Lambda}^{(0)}_{\bm{\beta}}\bm{X}^T\right) + \sum_{j=1}^J \frac{1}{2} \mathrm{diagonal}\left(\bm{Z}_j\bm{\Lambda}^{(0)}_{\alpha,j}\bm{Z}_j^T\right)$$

		\State{1. Update $q(\bm{\beta})$}

		$$\bm{\Lambda}_{\bm{\beta}}^{*} = \left(\bm{X}^T \bm{W}^{(0)} \bm{X}\right)^{-1}; \quad \bm{\mu}_{\bm{\beta}}^{*} = \bm{\mu}_{\bm{\beta}}^{(0)} + \bm{\Lambda}_{\bm{\beta}}^{*}\bm{X}^T\left[\bm{y} - \bm{w}^{(0)}\right] $$

		$$\ln \bm{w}^{(1)} = \ln \bm{w}^{(0)} + \bm{X}\left(\bm{\mu}_{\bm{\beta}}^* - \bm{\mu}_{\bm{\beta}}^{(0)}\right) + \frac{1}{2} \mathrm{diagonal}\left(\bm{X} \left[\bm{\Lambda}^*_{\bm{\beta}} - \bm{\Lambda}^{(0)}_{\bm{\beta}}\right]\bm{X}^T\right)$$
		\For{$j$ in $\{1, \cdots, J\}$}

		\vspace{0.5em}

		\State{2.j: Update $q(\bm{\alpha}_j)$. Define $\bm{S}_j = \left(\bm{I} \otimes E_{q(\bm{\Sigma}_j)}[\bm{\Sigma}_j^{-1}]\right)$}

		$$\bm{\Lambda}_{\alpha, j}^{*} = \left(\bm{Z}_j^T \bm{W}^{(j)} \bm{Z}_j + \bm{S}_j\right)^{-1}; \quad \bm{\mu}_{\alpha,j}^{*} = \bm{\mu}_{\alpha,j}^{(0)} + \bm{\Lambda}_{\alpha,j}^{*}\left(\bm{Z}_j^T\left[\bm{y} - \bm{w}^{(j)}\right] - \bm{S}_j \bm{\mu}^{(0)}_{\alpha,j}\right) $$
		$$\ln \bm{w}^{(j+1)} = \ln \bm{w}^{(j)} + \bm{Z}_j\left(\bm{\mu}^*_{\alpha,j} - \bm{\mu}_{\alpha,j}^{(0)}\right) + \frac{1}{2} \mathrm{diagonal}\left(\bm{X} \left[\bm{\Lambda}^*_{\alpha,j} - \bm{\Lambda}^{(0)}_{\alpha,j}\right]\bm{X}^T\right)$$
		\EndFor

	\end{algorithmic}
\end{algorithm}

This algorithm is not guaranteed to increase the objective at each iteration; to address this, we fall back to ``damped'' updates (\citealt{knowles2011non}) if necessary. The updates for $q(\bm{\beta})$ and $q(\bm{\alpha})$, the updates for $q(\{\bm{\Sigma}_j\}_{j=1}^J)$ follow existing research (e.g., \citealt{wand2014fully}). As proposed in \citet{goplerud2023reeval}, all priors on $\bm{\Sigma}_j$ are weakly informative. In terms of including fixed effects, one can use an update for $q(\bm{\alpha}_j)$ where $\bm{S}_j = \bm{0}$ and the constraints are addressed as noted in Appendix~\ref{app:VI_FE}.

\section{Other Methodologies for Predicting Categorical Variables}
\label{app:other_methods}

This section provides additional details on other methods for predicting categorical outcomes. Specifically, it first discusses the ``One-vs-All'' approach (see, e.g., \citealt{rifkin2004defense}) for a review. Second, it notes some additional details about two stage models.

\subsection{Separate Regressions and One-vs-All}\label{app:separate_reg}

The main manuscript discussed an approach for estimating categorical outcomes using separate regressions following \citet{taddy2015distributed}'s work. This approach plugs in an estimate of the fixed effect, $\hat{\gamma}_i$, and then estimates separate models. In our setting, $\hat{\gamma}_i = 0$ and thus it is equivalent to ignoring the fixed effect entirely. After fitting $\bar{L}$ separate Poisson regressions, one obtains an estimate of the linear predictor $\hat{\psi}_{i,\ell} = \hat{\gamma}_i + \bm{z}_{i,\ell}^T \hat{\bm{\theta}}_\ell$ for each response category $\ell$ where we use $\bm{z}_{i,\ell}$ and $\bm{\theta}_\ell$ as a placeholder for the design matrix and coefficients for response category $\ell$. To obtain a prediction, these are combined in the usual ``softmax'' formulation for a multinomial logistic regression, i.e. $\hat{p}_{i,\ell} = \exp(\hat{\psi}_{i,\ell})/\sum_{k=1}^{\bar{L}} \exp(\hat{\psi}_{i,k})$. This can be done in a numerically stable way even if all $\hat{\psi}_{i,\ell}$ are small---see Appendix~\ref{app:software_demo} for an illustration.

In the remainder of this subsection, we note a close but under-appreciated connection between \citet{taddy2015distributed}'s approach and the popular approach ``One-vs-All'' in machine learning for multi-class classification, i.e. predicting a categorical outcome (see \citealt{bishop2006ml} for a textbook treatment and \citealt{rifkin2004defense} for a more in-depth discussion of this and other methods). At its core, One-vs-All argues that instead of trying to estimate a complex model for all categories, one can estimate $\bar{L}$ separate \emph{binary} classifiers. For each response category $\ell \in \bar{L}$, one predicts whether observation $y_i=\ell$ (or not)---hence the name ``one versus all'' or ``one versus rest.'' This produces a collection of probabilities $\{p^{\texttt{OvA}}_{i,\ell}\}$ that are generally normalized to sum to one using a ratio, i.e. $p_{i,\ell} = p^{\texttt{OvA}}_{i,\ell}/\sum_k p^{\texttt{OvA}}_{i,k}$, although more sophisticated methods exist (\citealt{rifkin2004defense}). 

The connection to \cite{taddy2015distributed}'s approach is clear: His method fits a Poisson regression where the outcomes are either zero or one, i.e., $I(y_i = \ell)$; One-vs-All would use a logistic regression. In general, one would expect the two methods to give very similar predictions. Thus, One-vs-All can be seen as one additional approximation beyond \citet{taddy2015distributed}'s approach to allow the use of any binary classifier versus a Poisson regression. In our numerical simulations in Section~\ref{app:validation_separate}, we thus compare both binary and Poisson regressions to see if One-vs-All versus \cite{taddy2015distributed}'s approach yields better results, although we do not expect much difference.

Finally, Section~\ref{sec:separate_reg} notes that one could partially pool either \cite{taddy2015distributed}'s approach or One-vs-All. While this is perhaps infeasible if $\bar{L}$ is enormous---although one might partially pool across some subset of $\bar{L}$ response categories, we suspect it will be rather important for performance given the limitsed data available for MRP and the ability to include alternative-specific covariates. To formally outline how this would work, assume that one estimated separate logistic regressions with linear predictor $\psi_{i,\ell} = \bm{z}_{i,l}^T \bm{\theta}_\ell$. The partially pooled One-vs-Rest would put a hierarchical prior on these coefficients $\bm{\theta}_\ell$ and estimate a single model---albeit without the fixed effect that is required to make it \emph{exactly} equivalent to multinomial regression. To run this in code, one simply takes the the model in the main text for \texttt{mvMRP} (see also Appendix~\ref{app:software_demo}) and simply removes the fixed effect, i.e. \verb@v_fe(case_id)@.

\color{black}
We note that this partially pooled separate regressions approach is somewhat similar in spirit to recent work by \citet{marble2025improving}. In their paper, a key methodological innovation to obtain the \emph{marginal} distribution of opinion on $J$ questions by fitting a partially pooled model---i.e. stack marginal responses to $J$ questions together and fit a model with random slopes on, e.g., ``age'' by question. The fundamental distinction from our approach is that they do not estimate the joint opinion on multiple questions. Rather, they seek to gain information from partially pooling across marginal models and use with auxiliary information on known results to calibrate MRP. We suspect their calibration could be applied to \texttt{mvMRP} and this is an interesting question for future research.
\color{black}

\subsection{Two-Stage MRP}\label{app:twostage_equiv}

This section briefly illustrates the equivalence of the two-stage procedure and the single multinomial logistic regression in a simple setting. In the example in Section~\ref{sec:twostep_validation}, the two-step model uses the following generative models for (i) a multinomial logistic regression to predict party using a demographic such as race and (ii) a logistic regression to predict policy choice using race and party. They are shown below.

$$\mathrm{Pr}(\texttt{partyID}_i = \ell~) \propto \exp(\beta^{\texttt{Stage1}}_{0,\ell} + \alpha^{\texttt{Stage1}}_{g[i],\ell})$$
$$\mathrm{Pr}(\texttt{policy}_i = 1~|~\texttt{partyID}_i, \bm{z}_i) \propto \exp(\alpha^{\texttt{Stage2}}_{g[i]} + \xi_{\texttt{partyID}_i})$$

Consider the multinomial logistic formulation:

$$\mathrm{Pr}(\texttt{partyID}_i = \ell, \mathrm{policy}_i = \ell' | \bm{z}_i) \propto \exp\left(\beta_{0,(\ell,\ell')} + \alpha_{g[i],(\ell,\ell')}\right)$$

In the unregularized model, the multinomial logistic regression generates predictions that correspond to the share of each combination of party and policy $(\ell,\ell')$ found in the estimation data as it is a fully saturated model. In the original two-stage model, this does not occur as the second stage model, i.e. predicting policy conditional on party, assumes that the effect of party is the same across racial groups. Thus, \emph{interacting} party and race together in the second model is necessary to create a fully saturated model. If one thus replaced the second model in the two-stage MRP with the following, the predictions of the two-stage and single multinomial logistic regression are identical.

$$\mathrm{Pr}(\texttt{policy}_i = 1~|~\texttt{partyID}_i,~\bm{z}_i) \propto \exp\left(\alpha^{\texttt{Stage2}^*}_{g[i], \texttt{partyID}_i} + \xi_{\texttt{partyID}_i}\right)$$

In the case where random effects or multiple demographic predictors are used, this exact equivalence does not hold. However, there are two implications for applied research: If one is performing Two-Stage MRP, one should interact party and demographics in the second stage model as this captures dependencies that a multinomial logistic regression would capture but an additive two stage model would miss. Second, standard uses of Two-Stage MRP can be seen as an approximation to multivariate MRP where a simpler model is assumed for the second stage. This both gives a solid footing to \texttt{mvMRP} as estimating the ``true'' quantity of interest (the joint distribution of party and policy) as well as giving a more formal justification to Two-Stage MRP.

\section{Validation}\label{app:validation}

This section contains additional information on the validation of \texttt{mvMRP} in Section~\ref{sec:twostep_validation} in the main text. It first describes the data from the Cooperative Election Study (CES) and post-stratification weights in more details and then proceeds to compare \texttt{mvMRP} against other specifications or ways of presenting the results.

\subsection{Additional Details on CES}\label{app:validation_CCES}

This section first outlines the exact question wording, with differences noted, for each policy used in our analysis. Survey data were downloaded from the CES (\citealt{dagonel2023cces}).

\begin{itemize}
	\item Abortion---20 Weeks (2016-20): ``Do you support or oppose each of the following proposals? [Ban ('18); Prohibit ('16,'20)] abortions after the 20th week of pregnancy.''
	\item Abortion---Ban (2016-20): ``Do you support or oppose each of the following proposals? Make abortion illegal in all circumstances.''
	\item Ban Assault Weapons (2016-20): ``On the issue of gun regulation, do you support or oppose each of the following proposals? Ban assault rifles.''
	\item Same-sex Marriage (2012-16): ``Do you favor or oppose allowing gays and lesbians to marry legally?''
	\item Immigration (2012-16): ``What do you think the U.S. government should do about immigration? Select all that apply... Grant legal status to all illegal immigrants who have held jobs and paid taxes for at least 3 years, and not been convicted of any felony crimes.''
	\item Renewable Energy (2016-20): ``Do you support or oppose each of the following proposals? Require that each state use a minimum amount of renewable fuels (wind, solar, and hydroelectric) in the generation of electricity even if electricity prices increase [somewhat ('16); a little ('20)].''
\end{itemize}

For post-stratification, we aggregate 5-year American Community Survey microdata from IPUMS USA (\citealt{ruggles2025ipums}) to construct the joint distribution of the following variables: sex (2 levels); age (6 levels: 18-29, 30-39, 40-49, 50-59, 60-69, 70+); race (5 levels: white, Black, Latino, Asian, other); education (4 levels: no high school diploma, high school, some college, college degree). For questions occurring in the CES from 2012-16, microdata are from the 2016 ACS; for those occurring 2016-20, microdata are from the 2019 ACS.\footnote{Ideally, we would have used the 2020 ACS, sampled over the period 2016-2020. However, the Covid-19 pandemic disrupted the Census Bureau's ACS data collection in 2020; see \url{https://www.census.gov/newsroom/blogs/random-samplings/2021/10/pandemic-impact-on-2020-acs-1-year-data.html}.} The poststratification frame also includes state-level Democratic presidential vote share in 2012/2016 and state percent Evangelical measured in 2010 from the Association of Religion Data Archives.

In terms of sample size, the main text notes that the median state/party combination has around 750 respondents. This is computing using the survey weights, as is all of our ground truth estimates from the superpoll. The lower 25th percentile is around 359 respondents. In terms of respondents per state, the median state has 2480 respondents, with the smallest state having 273 respondents. Thus, our superpool is large enough for us to reliably estimate the joint distribution of the questions as well as downstream quantites such as support for a policy by party.

