Hence $\mu(X_G)$  is equal to

	\begin{align*}
	& \lim_{R\to \infty} \lim_{r\to\infty}\lim_{\mathcal{U}}\sum_{h_i\in B_H(e_H,R)} \PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n\mid \rho_n(x)=0, 
 \forall j<i\colon \uu_n(x)h_i^{-1}h_j\notin \uu_n(B_{\mathcal{G}_n}(x,r)) \Big\}\Big)\\
	& \ge \lim_{R\to \infty}\lim_{\mathcal{U}}\sum_{h_i\in B_H(e_H,R)} \PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n\mid \rho_n(x)=0, \forall j<i\colon \uu_n(x)h_i^{-1}\notin \Im(\uu_n)h_j^{-1} \Big\}\Big).
	\end{align*}

	Recall that for every $y\in \Im(\uu_n)$ there exists a unique $x\in \mathcal{G}_n$ such that $\rho_n(x)=0$ and $\uu_n(x)=y$. So,
	\begin{align*}
	\mu(X_G) & \ge \lim_{R\to \infty} \lim_{\mathcal{U}}\sum_{h_i\in B_H(e_H,R)} \frac{\#(\Im(\uu_n)h_i^{-1}\setminus \bigcup_{j<i}\Im(\uu_n)h_j^{-1})}{\#\mathcal{G}_n}
	\\
	& = \lim_{R\to \infty} \lim_{\mathcal{U}} \frac{1}{\#\mathcal{G}_n}\#\big\{y\in\mathcal{H}_n\mid d_{\mathcal{H}_n}(y,\Im(\uu_n))\le R \big\}\\
	& =  \lim_{\mathcal{U}} \frac{\#\mathcal{H}_n}{\#\mathcal{G}_n},
	\end{align*}
	as the maps $\uu_n$ are $\mathcal{U}$-statistically coarsely surjective.


	We now turn to the upper bound:

	\begin{align*}
	\mu(X_G) 	
	& = \lim_{R\to \infty} \lim_{r\to\infty}\lim_{\mathcal{U}}\sum_{h_i\in B_H(e_H,R)} \PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n\mid \rho_n(x)=0, \\
	& \AlignRight{ \forall j<i\colon \uu_n(x)h_i^{-1}h_j\notin \uu_n(B_{\mathcal{G}_n}(x,r)) \Big\}\Big)}.\\
	& \le \lim_{R\to \infty} \lim_{r\to\infty}\lim_{\mathcal{U}}\sum_{h_i\in B_H(e_H,R)} \PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n\mid \rho_n(x)=0, \forall j<i\colon \uu_n(x)h_i^{-1}\notin \Im(\uu_n)h_j^{-1}  \Big\}\Big)\\
	& + \lim_{R\to \infty} \lim_{r\to\infty}\lim_{\mathcal{U}}\sum_{h_i\in B_H(e_H,R)}  \PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n \mid \exists x'\colon \; d_{\mathcal{G}_n}(x,x')>r,\\
	& \AlignRight{\exists j<i\colon \uu_n(x)h_i^{-1}= \uu_n(x')h_j^{-1} \Big\}\Big) }\\
	& = \lim_{\mathcal{U}} \frac{\#\mathcal{H}_n}{\#\mathcal{G}_n} + \lim_{R\to \infty} \sum_{h_i\in B_H(e_H,R)}\lim_{r\to\infty}\lim_{\mathcal{U}} \PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n \mid \exists x'\colon \; d_{\mathcal{G}_n}(x,x')>r,\qquad\\
	& \AlignRight{d_{\mathcal{H}_n}(\uu_n(x),\uu_n(x')) \le 2R \Big\}\Big) }\\
	& = \lim_{\mathcal{U}} \frac{\#\mathcal{H}_n}{\#\mathcal{G}_n}.
	\end{align*}
Let us explain:  for the first equality, we considered two cases, depending on whether $\uu_n(x)h_i^{-1}h_j$ is or not in $\Im(\uu_n)$. When it is  (the second term), then it equals $\uu_n(x')$ for some $x'$ such that $d_{\mathcal{G}_n}(x,x')>r$, which explains the inequality. The second equality follows from the computation we had performed just above. Finally we conclude thanks to the fact that the maps $\uu_n$ are $\mathcal{U}$-statistically expansive.

Thus, $\mu(X_G)=\lim\limits_{\mathcal{U}} \frac{\#\mathcal{H}_n}{\#\mathcal{G}_n}$ and we are done.
\end{proof}
Collecting the above results, we deduce the following theorem.
\begin{proposition}\label{prop:ME}
	Let $G$ and $H$ be two finitely generated groups with sofic approximations $(\mathcal{G}_n)_n$ and $(\mathcal{H}_n)_n$. Assume that  the  sequence of maps $\uu_n\colon \mathcal{G}_n\to \mathcal{H}_n$ is $\mathcal{U}$-statistically a coarse equivalence. Then, there exists a measure equivalence coupling $(\Omega,\mu)$ between be the groups $G$ and $H$ such that 
	\[\frac{\mu(\Omega/G)}{\mu(\Omega/H)}=\lim_{\mathcal{U}}\frac{\#\mathcal{H}_n}{\#\mathcal{G}_n}.\]	.
\end{proposition}
\begin{proof}
	This is an immediate consequence of Propositions \ref{prop:existenceofmu}, \ref{prop:X_H} and \ref{prop:fundDom}.
\end{proof}


\subsection{A criterion implying $X_G=X_H$ a.e.}

Proposition \ref{prop:OECoupling} results from the following more general fact.

\begin{proposition}\label{prop:fundamentalDomainBis}
	Assume that $\uu_n:\mathcal{G}_n\to \mathcal{H}_n$ are $\mathcal{U}$-statistically Lipschitz  and $\mathcal{U}$-statistically coarsely bijective.
	\begin{itemize}
		\item If in addition the maps $\uu_n$ have fibers with diameter at most $R$, then $\mu(X_H\setminus B_G(e_G,R)*X_G)=0$. In particular, if the maps are  injective, then $\mu(X_H\setminus X_G)=0$.
		\item 
		If the maps $\uu_n$ are $\mathcal{U}$-statistically a coarse equivalence and have $C$-dense image, then $\mu(X_G\setminus B_H(e_H,C)*X_H)=0$. In particular, if the maps are surjective, then $\mu(X_G\setminus X_H)=0$. 
		\item if both conditions are satisfied, then the resulting coupling is mutually cobounded, and if $\uu$ is  bijective, then $X_H=X_G$ a.e.
	\end{itemize}
\end{proposition}
\begin{proof}
The third item is simply a consequence of the first two. 
	So suppose that the diameters of the fibers of the maps $\uu_n$ are at most $R$. Then, we get
	\begin{align*}
	\mu(X_H \! \setminus\! B_G(e_G,R)*X_G) & \le \mu(X_H \! \setminus\! B_G(e_G,R)*Y_0) \\
%	& = \lim\limits_{\mathcal{U}} \PP_{\mathcal{G}_n}\Big(\Big\{x\in \mathcal{G}_n\mid \exists h\in H \text{ s.t. } T_n(x,e_G)=h,\\
%	&  \AlignRight{ \text{ and } \forall g\in B_G(e_G,R)\colon T_n(x,g)\neq h \text{ or } \rho_n(xg) \neq 0\Big\}\Big) }\\
%	& = \lim\limits_{\mathcal{U}} \PP_{\mathcal{G}_n}\Big(\Big\{x\in \mathcal{G}_n\mid \forall g\in B_G(e_G,R)\colon T_n(x,g)\neq e_H \text{ or } \rho_n(xg) \neq 0\Big\}\Big) \\
	& = \lim\limits_{\mathcal{U}} \PP_{\mathcal{G}_n}\Big(\Big\{x\in \mathcal{G}_n\mid \forall g\!\in\! B_G(e_G,R)\colon \uu_n(xg)\neq \uu_n(x) \text{ or } \rho_n(xg)\neq 0 \Big\}\Big)\\
	& = \lim\limits_{\mathcal{U}} \PP_{\mathcal{G}_n}\Big(\Big\{x\in \mathcal{G}_n\mid \forall x'\in \uu_n^{-1}(\uu_n(x))\colon  \rho_n(x')\neq 0 \Big\}\Big)\\
	& = 0,
	\end{align*}
	as every fiber contains an element $x'$ such that $\rho_n(x')=0$. %Note that we have used that $T_n(x,e_G)=h$ implies that $h=e_H$. 

	To show the second item, it suffices to show that $\mu(Y_i)=0$ whenever $|h_i|>C$. We denote $\eta= \lim_{\mathcal{U}} \frac{\#\mathcal{H}_n}{\#\mathcal{G}_n}$.
	Recall that by Remark \ref{rem:Yi}, we have 
	\begin{align*}
	\mu(Y_i) & = \lim_{R\to\infty}\lim_{\mathcal{U}} \PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n\mid \rho_n(x)=0, \forall j<i\colon \uu_n(x)h_i^{-1}\notin \uu_n(B_{\mathcal{G}_n}(x,R))h_j^{-1} \Big\}\Big)
	\\
	& \le \lim_{R\to\infty}\lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n\mid\forall g\in B_G(e_G,R)\colon \uu_n(x)h_i^{-1} \notin\uu_n(xg)B_H(e_H,C)\Big\}\Big)\\
	& = \lim_{R\to\infty}\lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n\mid \forall x' \in B_{\mathcal{G}_n}(x,R)\colon \uu_n(x)h_i^{-1}\notin B_{\mathcal{H}_n}(\uu_n(x'),C) \Big\}\Big)\\
	& \le \lim_{R\to\infty}\lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n\mid  \exists x'' \in B_{\mathcal{G}_n}(x,R)^c\colon \uu_n(x)h_i^{-1}\in B_{\mathcal{H}_n}(\uu_n(x''),C) \Big\}\Big)\\
%	& \le \lim_{r\to\infty}\lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\Big(\Big\{x\in\mathcal{G}_n\mid \exists x'' \in \mathcal{G}_n\colon d_{\mathcal{G}_n}(x,x'')> r, d_{\mathcal{H}_n}(\uu_n(x), \uu_n(x''))\le |h_i|+C \Big\}\Big)\\
	& \le \lim_{R\to\infty} \lim_\mathcal{U}\PP_{\mathcal{G}_n}\left(\left\{x\in \mathcal{G}_n\mid \diam_{\mathcal{G}_n}(\uu^{-1}(B_{\mathcal{H}_n}(\uu_n(x),C+|h_i|))\geq R\right\}\right)\\
	& = 0,
	\end{align*}
	where we have used for the first inequality that $B_H(e_H,C)\subset \{y_j\mid j<i\}$. For the second inequality in the fourth line, we have used that $\uu_n$ is $C$-dense. Indeed, this means that with proba tending to $1$, any $y\in \mathcal{H}_n$ lies in $B_{\mathcal{H}_n}(\uu_n(x''),C)$ for some $x''\in \mathcal{G}_n$. %For the third inequality, we have used that $\uu_n$ is injective in restriction to $\{x\in \mathcal{G}_n\mid \rho_n(x)=0\}$. 
	Finally, we concluded thanks to the assumption that $\uu_n$ is $\mathcal{U}$-statistically expansive.
	\end{proof}






\section{Cocycles and their integrability}\label{sec:integrability}
In this section we calculate the length of the cocycles of the measure equivalence obtained in \cref{prop:fundDom}.
We briefly recall basic facts about our coupling from $G$ to $H$: the action of $G\times H$ on $\Omega$ is given by 
$(g,h)*\aaa=(\aaa_H(g^{-1}\cdot)h,\aaa_\N(g^{-1}\cdot))$, 
the fundamental domain for the $H$-action is given by $X_H = \{\aaa\in \Omega''\mid \aaa_H(e_G)=e_H\}$. Finally, the cocycle $\alpha\colon G\times X_H\to H$, is defined by $g*\aaa\in\alpha(g,\aaa)^{-1}*X_H$ for every $g\in G$ and almost every $\aaa\in X_H$. We deduce a very simple formula for $\alpha$:
\[\alpha(g,\aaa)=\aaa_H(g^{-1})^{-1}.\]

First, we look at the integrability of the cocycle $\alpha\colon G\times X_H\to H$. 
The integrability of this cocycle entirely depends on the convergence rate of the $\mathcal{U}$-statistically Lipschitz condition.
\begin{proposition}\label{prop:QuantSubgroup}
	Let $\varphi\colon \R^+\to \R^+$ be a non-decreasing map.
	Let $(\Omega,X_H,\mu)$ be a measure subgroup coupling from $G$ to $H$ as in \cref{thm:ME} and let $\alpha\colon G\times X_H\to H$ be associated cocycle. % given by $g*\aaa\in\alpha(g,\bb)^{-1}*X_H$ for every $g\in G$ and almost every $\bb\in X_H$.
	 Then, $\alpha$ is $\varphi$-integrable if  for every $g\in S_G$ there exists a $\delta>0$ such that
	\begin{equation}\label{eq:UQuantLip}
	\sum_{r=0}^\infty \varphi\!\left(\delta r\right)\lim_{\mathcal{U}} \PP_{ \mathcal{G}_n}\left(\left\{x\in \mathcal{G}_n\mid d_{\mathcal{H}_n}(\uu_n(x),\uu_n(xg^{-1}))=r\right\}\right)<\infty.
	\end{equation}
	Similarly, $\alpha$ is strongly $\varphi$-integrable (or $\varphi^\diamond$-integrable)  if for every $\varepsilon>0$ there exists a $\delta>0$ and $C>0$ such that for every $g \in G$ we have that
	\begin{equation}\label{eq:UQuantLipStrong}
	\sum_{r=0}^\infty\varphi\!\left(\delta r\right)\lim_{\mathcal{U}} \PP_{ \mathcal{G}_n}\left(\left\{x\in \mathcal{G}_n\mid d_{\mathcal{H}_n}(\uu_n(x),\uu_n(xg^{-1}))=r\right\}\right)\le C\varphi(\varepsilon |g|).
	\end{equation}
\end{proposition}
\begin{proof}
For all $h\in H$, and $g\in G$, we have
\begin{eqnarray*}
\mu\left(\left\{\aaa\in X_H\mid \aaa_H(g)=h\right\}\right) & = & \mu\left(X_H\cap\left\{\aaa\in \Omega \mid \aaa_H(g)=h\right\}\right) \\
& = & \mu\left(\left\{\aaa\in \Omega''\mid \aaa_H(e_G)=e_H,\;  \aaa_H(g)=h\right\}\right)\\
&= &\lim_{\mathcal{U}} \PP_{\mathcal{G}_n}\left(\left\{x\in\mathcal{G}_n \mid \uu_n(xg)=\uu_n(x)h\right\}\right).
\end{eqnarray*}
%Note that $g*\bb \in \alpha(g,\bb)^{-1}*X_H = A_{\alpha(g,\bb)^{-1}*\aaa,\{e_G\},\Theta}$ for every $g\in G$ and $\bb = (\bb_H,\bb_\R)\in X_H$, hence $\bb_H(g^{-1}) = g*\bb_H(e_G) = \alpha(g,\bb)^{-1}\aaa(e_G) = \alpha(g,\bb)^{-1}$ and $|\alpha(g,\bb)|=|\bb(g^{-1})|$.

Then, for every $g\in G$ we have:
	\begin{align*}
	&\int_{X_H} \varphi\!\left(\delta|\alpha(g^{-1},\aaa)^{-1}|\right) d\mu(\aaa)\\
	& = \int_{X_H} \varphi\!\left(\delta|\aaa_H(g)|\right) d\mu(\aaa)\\
	& = \sum_{h\in H} \varphi\!\left(\delta |h|\right)\mu\left(\left\{\aaa\in X_H\mid \aaa_H(g)=h\right\}\right)\\
	& =\sum_{h\in H} \varphi\!\left(\delta |h|\right)\mu\left(\left\{\aaa\in X_H\mid \aaa_H(g)=h\right\}\right)\\
	& = \sum_{h\in H}\varphi\!\left(\delta |h|\right)\lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\left(\left\{x\in\mathcal{G}_n \mid \uu_n(xg)=\uu_n(x)h\right\}\right)\\
	& = \sum_{r=0}^{\infty} \sum_{|h|=r} \varphi\!\left(\delta |h|\right)\lim_{\mathcal{U}}  \PP_{\mathcal{G}_n}\left(\left\{x\in\mathcal{G}_n \mid \uu_n(xg)=\uu_n(x)h\right\}\right)\\
	& =  \sum_{r=0}^{\infty}  \varphi\!\left(\delta r\right) \lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\left(\left\{x\in\mathcal{G}_n \mid d_{\mathcal{H}_n}(\uu_n(xg),\uu_n(x))=r\right\}\right)
	\end{align*}
where for the fourth equality, we have used (as in \S \ref{sec:BasicSubsets}) that \[\mu\left(\left\{\aaa\in X_H\mid \aaa_H(g)=h\right\}\right)=\overline{\mu}\left(\Big\{x\in \overline{\Omega}_0\mid T(g,x)=h\Big\}\right),\]
which equals \[\lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\left(\left\{x\in\mathcal{G}_n \mid \uu_n(xg)=\uu_n(x)h\right\}\right).\]
Now both claims follow from the definitions of $\varphi$-integrable and strongly $\varphi$-integrable.
\end{proof}

Next, we look at the integrability of $\beta\colon H\times X_G\to G$. For this cocycle, its integrability depends on the convergence rate of the $\mathcal{U}$-statistically expansive condition. 
\begin{proposition}\label{prop:Cocycle}
Let $\varphi\colon \R^+\to \R^+$ be a non-decreasing map,
let $(\Omega,X_G,X_H,\mu)$ be a measure equivalence coupling from $G$ to $H$ as in \cref{thm:ME} and let $\beta\colon H\times X_G\to G$ be the measure equivalence cocycle given by $h*\aaa\in\beta(h,\aaa)^{-1}*X_G$ for every $h\in H$ and almost every $\aaa\in X_G$.
Suppose there exists a $C>0$ such that the maps $\uu_n$ are $C$-dense.
Then, $\beta$ is $\varphi$-integrable if for every $h\in B_H(e,2C+1)$ there exists a $\delta>0$ such that
	\begin{equation}\label{eq:UQuantExp}
\sum_{r=0}^\infty\varphi(\delta r) \lim_{\mathcal{U}} \PP_{\mathcal{H}_n}\left(\left\{y\in \uu_n(\mathcal{G}_n)\mid \diam_{\mathcal{G}_n}(\uu_n^{-1}(y)\cup \uu_n^{-1}(yh))\geq r\right\}\right)<\infty.
\end{equation}
Similarly, $\beta$ is strongly $\varphi$-integrable (or $\varphi^\diamond$-integrable) if  if for every $\varepsilon>0$ there exists a $\delta>0$ and $C'>0$ such that for every $h\in H$ we have that
	\begin{equation}\label{eq:UQuantExpstrong}
	\sum_{r=0}^\infty \varphi(\delta r)\lim_{\mathcal{U}} \PP_{\mathcal{H}_n}\left(\left\{y\in \uu_n(\mathcal{G}_n)\mid \diam_{\mathcal{G}_n}(\uu_n^{-1}(y)\cup \uu_n^{-1}(yh))\geq r\right\}\right)\le C'\varphi(\varepsilon |h|).
	\end{equation}
Besides, if we assume that the point-preimages of $\uu_n$ has diameter at most $C$, then these two conditions can respectively be relaxed to the following ones\footnote{where the inequality for the diameter is replaced by an equality. Note that if $\varphi$ is a quickly growing function (e.g.\ a stretched exponential), then the two conditions are equivalent, so there is no gain in assuming the bound on the diameter of preimages.}
	\begin{equation}\label{eq:UQuantExpC}
\sum_{r=0}^\infty\varphi(\delta r) \lim_{\mathcal{U}} \PP_{\mathcal{H}_n}\left(\left\{y\in \uu_n(\mathcal{G}_n)\mid \diam_{\mathcal{G}_n}(\uu_n^{-1}(y)\cup \uu_n^{-1}(yh))= r\right\}\right)<\infty.
\end{equation}
and 
	\begin{equation}\label{eq:UQuantExpCstrong}
\sum_{r=0}^\infty \varphi(\delta r)\lim_{\mathcal{U}} \PP_{\mathcal{H}_n}\left(\left\{y\in \uu_n(\mathcal{G}_n)\mid \diam_{\mathcal{G}_n}(\uu_n^{-1}(y)\cup \uu_n^{-1}(yh))= r\right\}\right)\le C'\varphi(\varepsilon |h|).
\end{equation}
\end{proposition}
\begin{proof}
First, note that by \cref{prop:fundamentalDomainBis} we have that $\mu(X_G\setminus B_H(e_H,C)*X_H)=0$, so $\mu(Y_i)=0$ for $|h_i|>C$. We let $I$ be the largest integer such that $|h_I|\le C$.

Next, note that for every $h\in H$ and $\aaa\in X_G$ there exists an $i\le I$ such that $h*\aaa\in \beta(h,\aaa)^{-1}*Y_i$. So, $\aaa(\beta(h,\aaa)^{-1})=(h^{-1}h_i,0)$. 
Besides, recall that by definition of $Y_i$, we have \[Y_i\subset h_i*Y_0=\{\aaa\in \Omega''\mid  \aaa(e_G)=(h_i,0)\}.\]
Using $X_G=\bigsqcup_{i=0}^\infty Y_i$, and arguing as in \S \ref{sec:BasicSubsets}, we have, denoting $h_{ij}=h_j^{-1}h^{-1}h_i$:
\begin{align*}
\int_{X_G}\hspace{-2pt} \varphi\!\left(\delta|\beta(h,\aaa)|\right)d\mu(\aaa) & = \sum_{g\in G} \varphi\!\left(\delta|g|\right)\mu\left(\{\aaa\in X_G\mid \beta(h,\aaa)=g\}\right)\\
& = \sum_{i,j\leq I}\sum_{g\in G} \varphi\!\left(\delta|g|\right) \mu\left(\{\aaa\in Y_j\mid \aaa(g^{-1})=(h^{-1}h_i,0)\}\right)\\
& \le  \sum_{i,j\leq I}\sum_{g\in G} \varphi\!\left(\delta|g|\right)\mu\left(\{\aaa\in \Omega''\mid \aaa(e_G)=(h_j,0),\; \aaa(g^{-1})=(h^{-1}h_i,0)\}\right)\\
& =\sum_{i,j\leq I} \sum_{g\in G} \varphi\!\left(\delta|g|\right) \lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\big(\{x\in\mathcal{G}_n\mid \uu_n(xg^{-1})=\uu_n(x)h_{ij}, \\
&\AlignRight{\rho_n(x)=\rho_n(xg^{-1})=0\big\}\big)}\\
& \le \sum_{i,j\leq I}\sum_{g\in G} \varphi\!\left(\delta|g|\right) \lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\big(\{x\in\mathcal{G}_n\mid \uu_n(xg^{-1})=\uu_n(x)h_{ij},
\rho_n(x)=0\big\}\big)\\
& =  \sum_{i,j\leq I} \sum_{r=0}^{\infty} \varphi\!\left(\delta r\right)\sum_{|g|=r} \lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\big(\{x\in\mathcal{G}_n\mid \uu_n(xg^{-1})=\uu_n(x)h_{ij},
\rho_n(x)=0\big\}\big).
%& = \sum_{g\in G} \aaa\!\left(\delta|g|\right) \sum_{i=0}^I\sum_{j=0}^I\lim_{\mathcal{U}}\frac{1}{\#\mathcal{G}_n}\#\big\{(x,x')\in\mathcal{G}_n^2\mid x' = x.g^{-1},\\
%& \AlignRight{\uu_n(x')=\uu_n(x).h_j^{-1}h^{-1}h_i, \rho_n(x)=\rho_n(x')=0\big\}}\\
%& = \sum_{r= 1}^\infty \aaa\!\left(\delta r\right) \sum_{i=0}^I\sum_{j=0}^I\lim_{\mathcal{U}}\frac{1}{\#\mathcal{G}_n}\#\big\{(x,x')\in\mathcal{G}_n^2\mid d_{\mathcal{G}_n}(x,x') = r,\\
%& \AlignRight{\uu_n(x')=\uu_n(x).h_j^{-1}h^{-1}h_i, \rho_n(x)=\rho_n(x')=0\big\}} \\
%& = \sum_{r= 1}^\infty \aaa\!\left(\delta r\right) \sum_{i=0}^I\sum_{j=0}^I\lim_{\mathcal{U}}\frac{1}{\#\mathcal{G}_n}\#\big\{(y,y')\in\mathcal{H}_n^2\mid \diam(\uu_n^{-1}(y)\cup\uu_n^{-1}(y')) = r,\\
%& \AlignRight{y'=y.h_j^{-1}h^{-1}h_i\big\}}
\end{align*}



For every $x$ such that $\uu_n(xg^{-1})=\uu_n(x)h_{ij}$ and 
$\rho_n(x)=0$, denote $y=\uu_n(x)$. 
Note that $x\in \uu_n^{-1}(y)$ and $xg^{-1}\in \uu_n^{-1}(yh_{ij})$. 
Restricting to $x\in{\mathcal{G}_n}^{(2r)}$ we can assume that $d(x,xg^{-1})=r$. Hence we get 
\[r\le \diam(\uu_n^{-1}(y)\cup \uu_n^{-1}(yh_{ij})).\]
 If we assume that pre-images of $\uu_n$ have diameter at lost $C$, we get by triangular inequality
\[r\le \diam(\uu_n^{-1}(y)\cup \uu_n^{-1}(yh_{ij}))\le r+2C.\]
Recall that $\uu_n$ is injective in restriction  to $\{x\in\mathcal{G}_n\mid 
\rho_n(x)=0\big\}$. 
Hence denoting $\eta= \lim_{\mathcal{U}} \frac{\#\mathcal{H}_n}{\#\mathcal{G}_n}$, we deduce that
\begin{align*}
& \sum_{|g|=r} \lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\big(\{x\in\mathcal{G}_n\mid \uu_n(xg^{-1})=\uu_n(x)h_{ij}, \;
\rho_n(x)=0\big\}\big)\\
& \le
\eta \lim_{\mathcal{U}}\PP_{\mathcal{H}_n}\big(\{y\in\mathcal{H}_n \mid r\le \diam_{\mathcal{G}_n}(\uu_n^{-1}(y)\cup \uu_n^{-1}(yh_{ij}))\big\}\big),
\end{align*}
and if we assume the diameter bound on the pre-images, this becomes:
\begin{align*}
& \sum_{|g|=r} \lim_{\mathcal{U}}\PP_{\mathcal{G}_n}\big(\{x\in\mathcal{G}_n\mid \uu_n(xg^{-1})=\uu_n(x)h_{ij}, \;
\rho_n(x)=0\big\}\big)\\
& \le
\eta \lim_{\mathcal{U}}\PP_{\mathcal{H}_n}\big(\{y\in\mathcal{H}_n \mid r\le \diam_{\mathcal{G}_n}(\uu_n^{-1}(y)\cup \uu_n^{-1}(yh_{ij}))\le r+2C\big\}\big).
\end{align*}
We deduce that 
\begin{align*}
& \int_{X_G}\hspace{-2pt} \varphi\!\left(\delta|\beta(h,\aaa)|\right)d\mu(\aaa)\\ & \le \eta \sum_{i,j\leq I} \sum_{r=0}^{\infty} \varphi\!\left(\delta r \right)\lim_{\mathcal{U}}\PP_{\mathcal{H}_n}\big(\{y\in\mathcal{H}_n \mid r\le \diam_{\mathcal{G}_n}(\uu_n^{-1}(y)\cup \uu_n^{-1}(yh_{ij}))\big\}\big),
\end{align*}
which implies $\varphi$-integrability and strong $\varphi$-integrability under respectively (\ref{eq:UQuantExp}) and (\ref{eq:UQuantExpstrong}). Indeed, for integrability, we only need it for $h\in S_H$, in which case each $h_{ij}$ has word length at most $2C+1$.
Under the diameter bound we get
\begin{align*}
& \int_{X_G}\hspace{-2pt} \varphi\!\left(\delta|\beta(h,\aaa)|\right)d\mu(\aaa)\\ & \le \eta \sum_{i,j\leq I} \sum_{r=0}^{\infty} \varphi\!\left(\delta r \right)\lim_{\mathcal{U}}\PP_{\mathcal{H}_n}\big(\{y\in\mathcal{H}_n \mid r\le \diam_{\mathcal{G}_n}(\uu_n^{-1}(y)\cup \uu_n^{-1}(yh_{ij}))\le r+2C\big\}\big). 
\end{align*}
By monotonicity of $\varphi$, this implies $\varphi$-integrability under (\ref{eq:UQuantExpC}). Strong integrability follows from (\ref{eq:UQuantExpCstrong}), combined with the fact that $|h|-2C\leq |h_{ij}|\leq |h|+2C$. 
 \end{proof}


\section{Proofs of theorems from the introduction}\label{sec:Proofs}

Let us start with the qualitative statements: 
Theorem \ref{thm:Subgroup} and Theorem \ref{thm:ME} are immediate corollaries of \cref{prop:SubgroupCoupling} and \ref{prop:OECoupling} respectively.

We now turn to the proofs of Theorems \ref{thm:quantSubgroup} and \ref{thm:quantME}. 
We start showing that (\ref{eq:quantLip})  implies that $\uu_n$ is $\mathcal{U}$-statistically Lipschitz. Let us argue by contradiction. Then, by \cref{prop:StatBiLGroups} there exists an $\varepsilon>0$ such that for all $C_0$ there exists $C'>C_0$ such that for some $s\in S_G$ we have that 
\[\lim_{\mathcal U}\PP_{\mathcal{G}_n}\left(\left\{x\in \mathcal{G}_n\mid d_{\mathcal{H}_n}(\uu_n(x),\uu_n(x.s))\ge C'\right\}\right)\ge \varepsilon.\]
Note that the events $\left[\{x\in \mathcal{G}_n\mid d_{\mathcal{H}_n}(\uu_n(x),\uu_n(x.s))\ge C'\}\right]_{\mathcal U}$ are disjoint, hence by $\sigma$-additivity of $\nu$, we have
\[\lim_{\mathcal U}\PP_{\mathcal{G}_n}\left(\left\{x\in \mathcal{G}_n\mid d_{\mathcal{H}_n}(\uu_n(x),\uu_n(x.s))\ge C'\right\}\right)=\sum_{r\geq C'}\lim_{\mathcal U}\PP_{\mathcal{G}_n}\left(\{x\in \mathcal{G}_n\mid d_{\mathcal{H}_n}(\uu_n(x),\uu_n(x.s))=r\}\right)\]

By (\ref{eq:quantLip}), and using that $\varphi$ is unbounded and nondecreasing,  for every $\delta>0$ we can take $C_0$ large enough such that
\begin{align*}
	\varphi\left(\delta C_0\right) \varepsilon & >  \sum_{r=0}^R \varphi\!\left(\delta r\right)\lim_{\mathcal U}\PP_{\mathcal{G}_n}\left(\{x\in \mathcal{G}_n\mid d_{\mathcal{H}_n}(\uu_n(x),\uu_n(x.s))=r\}\right)\\
	& \ge \varphi\left(\delta C'\right) \lim_{\mathcal U} \PP_{\mathcal{G}_n}\left(\{x\in \mathcal{G}_n\mid d_{\mathcal{H}_n}(\uu_n(x),\uu_n(x.s))\ge C'\}\right)\\
	& \ge \varphi\left(\delta C'\right) \varepsilon,
\end{align*}
leading to the desired contradiction. 
 This is enough to end the proof of Theorem \ref{thm:quantSubgroup}. Indeed, we have seen that it is $\mathcal U$-statistically Lipschitz, and since it has pre-images of diameter  at most $C$, it satisfies the assumptions of \cref{prop:SubgroupCoupling}, which provides a measure subgroup subgroup coupling from $G$ to $H$. We then conclude thanks to \cref{prop:QuantSubgroup}

To prove  Theorem \ref{thm:ME}, we need to show that the sequence $(\uu_n)_n$ is $\mathcal U$- statistically expansive. The proof is similar: suppose it is not, then, by \cref{prop:expsofic}, there exists an $\varepsilon>0$ and an $h\in B_H(e_H,2C+1)$ such that for all $C_0$ there exists $C'>C_0$ such that
\[\lim_{\mathcal U}\PP_{\mathcal{H}_n}\left(\left\{z\in \uu_n(\mathcal{G}_n)\mid zh\in \uu_n(\mathcal{G}_n), \diam_{\mathcal{G}_n}(\uu_n^{-1}(z)\cup \uu_n^{-1}(zh))\ge C'\right\}\right)\ge \varepsilon.\]
Since $\varphi$ is unbounded, for any $\delta>0$,  we can take $C_0$ such that
\begin{align*}
\varphi\left(\delta C_0\right) \varepsilon & >\sum_{r=0}^\infty \varphi\!\left(\delta r\right) \lim_{\mathcal U} \PP_{\mathcal{H}_n}\left(\{z\in \uu_n(\mathcal{G}_n)\mid zh \in \uu_n(\mathcal{G}_n),  \diam_{\mathcal{G}_n}(\uu_n^{-1}(z)\cup \uu_n^{-1}(zh))=r\}\right)\\
& \ge \varphi\left(\delta C'\right)\lim_{\mathcal U}\PP_{\mathcal{H}_n}\left(\{z\in \uu_n(\mathcal{G}_n)\mid zh\in \uu_n(\mathcal{G}_n),  \diam_{\mathcal{G}_n}(\uu_n^{-1}(z)\cup \uu_n^{-1}(zh))\ge C\}\right)\\
& \ge \varphi\left(\delta C'\right) \varepsilon.
\end{align*}
We deduce that under the assumptions of \cref{thm:quantME}, the sequence $(\uu_n)$ is $\mathcal U$-statistically a coarse equivalence. Hence \cref{prop:OECoupling} provides us with an ME coupling (OE if we assume in addition that $\uu_n$ is bijective). The conclusion now follows from \cref{prop:Cocycle}.

\begin{remark}\label{rem:Strong}
	In \cref{thm:quantSubgroup} (and \cref{thm:quantME}), we obtain {\bf strong} integrability if we assume the stronger version of (\ref{eq:quantLip}): that for every $\varepsilon>0$ there exists a $\delta>0$ and $C'>0$ such that
	\[\sum_{r=0}^\infty \varphi\!\left(\delta r\right)\lim_{\mathcal U}\PP_{\mathcal{G}_n}\left(\{x\in \mathcal{G}_n\mid d_{\mathcal{H}_n}(\uu_n(x),\uu_n(xg))=r\}\right)\le C'\varphi(\varepsilon|g|)\]
	for every $g\in G$. Similarly the coupling is $(\varphi,\psi^\diamond)$-integrable if for every $\varepsilon>0$ there exists a $\delta>0$ and $C'>0$ such that
	\begin{equation}\label{eq:quantExpStrong}
	\sum_{r=0}^\infty \psi\!\left(\delta r\right)\lim_{\mathcal U} \PP_{\mathcal{H}_n}\left(\{y \in \uu_n(\mathcal{G}_n)\mid \diam_{\mathcal{G}_n}(\uu_n^{-1}(y)\cup\uu_n^{-1}(yh)) = r\}\right)\le C'\psi(\varepsilon |h|)\end{equation}
	for every $h\in H$ and it is $(\varphi^\diamond,\psi^\diamond)$-integrable if both conditions are satisfied.
	\end{remark}



\section{Application to the class $\mathcal M$}\label{sec:M}
This section is dedicated to the proof of \cref{thm:SolvableExpME}. Our main contribution is the following more specific theorem.

\begin{theorem}\label{thm:example}
	Let $k\ge 2$ and  $A\in \GL_2(\Z)$ has a real eigenvalue $\lambda>1$. 
 Then there exists a mutually cobounded $(\LL^\infty,\exp^\diamond)$-measure equivalence coupling from $\Lamp_k$ to $\SOL_A=\Z^2\rtimes_A\Z$.
\end{theorem}
\begin{proof}
Recall that according to our notation, $\Lamp_k=\Z/k\Z\wr \Z$. Let $\pi:\Lamp_k\to \Z$ be the projection to $\Z$. Given $q\geq 1$, the pre-image of $q\Z$ by $\pi$ is isomorphic to $(\Z/k\Z)^q\wr \Z$, which itself is bi-Lipschitz equivalent to $\Lamp_{k^q}$. In particular, $\Lamp_{k^q}$ and $\Lamp_k$ are quasi-isometric. Hence in order to prove the theorem, it is harmless to assume that $k$ is arbitrarily large. For reasons that will appear later (which are not essential), we will assume from now on that $k\geq \lambda$. 


We will use the fact that $\SOL_A$ is a uniform lattice in the group $\SOL_\R=\R^2\rtimes \R$ where $\R$ acts by $t\cdot (x,y)=(k^tx,k^{-t}y)$. %We shall also work with the group  $\SOL_\R=\R^2\rtimes \Z$ where $\Z$ acts by $t\cdot (x,y)=(k^tx,k^{-t}y)$, which is a closed cocompact subgroup of $\SOL_\R$. 

The proof of the theorem goes in three steps: first we construct a sequence of maps between F\o lner sequences of $\Lamp_k$ and  $\SOL_\R$ (by far the main step of the proof). Actually we will construct a unique map between the groups and consider its restriction to a F\o lner sequence. Second,  we will perturb this map slightly (at bounded distance) to have it land in a copy of $\SOL_A$ embedded as a lattice in $\SOL_\R$. 
Along the way all the metric estimates will be in terms of the word metrics of the groups. Hence a last technical step will be required to translate them in terms of the intrinsic graph distances of the F\o lner sets.

\

\noindent{\bf First step: constructing a map from $\Lamp_k$ to $\SOL_\R$.}

We start defining generating sets for the groups $\Lamp_k$ and $\SOL_\R$. 
We let $S^\Lamp=S_1^\Lamp\cup S_2^\Lamp$, where $S_1^\Lamp$ consists of elements $(x,0)$, where $x$ is supported at $0$, and $S_2^\Lamp=\{(0,\pm 1\}$.
Similarly we let $S^{\SOL}=S_1^{\SOL}\cup S_2^{\SOL}$, where $S_1^{\SOL}$ consists of elements $(x,0)$, where $\|x\|_\infty\leq 1$, and $S_2^{\SOL}=\{(0,t\}$, with $|t|\leq 1$. We shall denote by $|g|$ the word length of an element of either $\Lamp_k$ or $\SOL_\R$.
We shall use repeatedly the following easy estimates, whose verifications are left to the reader.
 For $g=(x,j)\in \Lamp_k$, 
\[\max \left\{\diam(\supp x\cup \{0\}),|j|\right\} \leq |g|\leq 2\diam(\supp x\cup \{0\})+|j|.\]
and for $g=(x,j)\in \SOL_\R,$
 \[\max \left\{\log_k\|x\|_{\infty},|j|\right\} \leq |g|\leq 2\log_k(1+ \|x\|_{\infty})+2|j|.\]


We consider the following F\o lner sequences of $\Lamp_k$ and $\SOL_\R$: 
\[F_n^\Lamp=\left\{(x,m)\mid \supp x\subset [-n,n], \; 0\leq m\leq n\right\},\] 
and 
\[F_n^{\SOL}=\left\{(x,m)\in \R_+^2\times \R\mid \|x\|_\infty \leq k^{n+1}, \; 0\leq m\leq n\right\}.\] 
Let us check that these are indeed right F\o lner sequences. For both, almost invariance under right multiplication by $S_2^\Lamp$ (resp.\ $S_2^{\SOL}$) is true because it only changes the second coefficient. For $F_n^\Lamp$, we observe that it is invariant under right multiplication by $S_1^\Lamp$, so it is duly a F\o lner sequence. Note that right multiplication by $S_1^{\SOL}$ preserves each coset of $\R^2$. Besides, for every $j\in \R$, we have 
\[([0,k^{n+1}]^2\times\{j\}) S_1^{\SOL}\subset [-k^j,k^{n+1}+k^j]^2\times\{j\}. \]
The Haar measure $\lambda$ on  $\SOL_\R$ is simply the product of the Lebesgue measure on $\R^3$.
Therefore, we have 
\[\lambda(([0,k^{n+1}]^2\times\{j\}) S_1^{\SOL})\leq (k^{n+1}+2k^j)^2,\]
so
\[\lambda(F_n^{\SOL}S_1^{\SOL})\leq \int_{0}^n (k^{n+1}+2k^j)^2dj=nk^{2n+2}+4k^{n+1}\int_{0}^nk^jdj+2\int_{0}^nk^{2j}dj\leq (n+6)k^{2n+2},\]
And since $\lambda(F_n^{\SOL})=nk^{2n+2}$, we deduce that 
\[\frac{\lambda(F_n^{\SOL}S_1^{\SOL})}{\lambda(F_n^{\SOL})}\leq \frac{n+6}{n},\]
which tends to $1$ as $n\to \infty$. Hence $F_n^{\SOL}$ is a F\o lner sequence.

\

We now define a map $\vv:\Lamp_k\to \SOL_\R$  as follows. For $x=(\eps_i)\in \oplus_\Z \Z/k\Z$, we set
\[\vv(x,m)=\left(\sum \eps_i k^i, \sum \eps_i k^{-i},m\right).\]

Before analyzing the properties of this map, let us pause, and work out  the following baby case as a warmup. Consider the function $f:\oplus_n \Z/k\Z\to \R_+$ defined  for each $x=(\eps_i)$ by $f(x)=\sum \eps_i k^i$. Suppose we equip the group  $\oplus_n \Z/k\Z$ with the length $|x|=\max (\supp x)$, and  $\R_+$ is equipped with the distance $d(x,y)=\log (1+|x-y|)$. Note that this is similar to the restriction of $\vv$ to $\bigoplus_\Z \Z/k\Z$.  It is easy to see that the map $f$ is injective, Lipschitz, and takes values in $\N$. Besides, for all $n\in \N$, $f$ maps bijectively $K_n=\{x\mid \supp x\subset [0,n]\}$ to $I_n=[0, k^{n+1}-1]\cap \N$. By contrast, this map is not coarsely expansive. This results from the fact that $\R$ is Archimedean, which manifests itself through carries: assume we add $1$ to $x=\sum \eps_i k^i$, and then write the $k$-adic decomposition of the resulting number, we get $x+1=\sum_i \eps_i'$, where $\eps_i'\neq \eps_i$ for all $i\leq m$, where $m$ is the smallest integer such that $\eps_i\neq k-1$. Hence the pre-image of $x+1$ lies at distance $m$ from $x$, and $m$ can be arbitrarily large. However, large values of $m$ happen ``exponentially rarely''. Let us indeed evaluate the proportion of elements of $x\in K_n$ such that $d(x,f^{-1}(f(x)+1))\geq m$: since it imposes that the first $m-1$ coordinates of $x$ are equal to $k-1$, this proportion is at most $k^{-m+1}$. 

We are now ready to study our map $\vv$, for which a similar phenomenon occurs, although in a more complicated way, as shown by the following lemma.

\begin{lemma}\label{lem:psi}
The map $\vv$ is $2$-Lipschitz, and maps $F_n^\Lamp$ to a $(1+\log_k (1+2k))$-coarsely dense subset of $F_n^{\SOL}$. 
It satisfies the following (statistic expansivity) property: for all integers $q,m\geq 1$,
the proportion of points $g\in F_n^\Lamp$ such that $\diam\vv^{-1}(B_{\SOL}(\vv_n(g),q))\geq 2m+3q$ is at most $4k^{-m+1}$. Finally, For every $r$, the preimage of balls of radius $q$ has cardinality at most $(2q+1)k^{2q+1}$.
\end{lemma}

\begin{proof}
Let us prove Lipschitz: for this it is enough to consider neighboring vertices: for those who differ by their $\Z$-coordinate, the statement is obvious, so consider the case of two elements $g,g'\in \Lamp_k$ such that $g'=gs$ for some $s\in S_1^{\Lamp}$. We then have $g=(x,j)$ and $gs=(x',j)$ where $x=(\eps_i)$ and $x'=(\eps'_i)$ only differ in their $j$-coordinate. We have $\vv(g)=(y,j)$, where $y=(\sum_i \eps_i k^i, \sum_i \eps_i k^{-i})$ and $\vv(g')=(y',j)$ with $y'=(\sum_i \eps'_i k^i, \sum_i \eps'_i k^{-i})$. So
\[\vv(g)^{-1}\vv(g')=\left(\sum_i(\eps'_i-\eps_i) k^{i-j},\sum_i(\eps'_i-\eps_i) k^{j-i},0\right)=(\eps'_j-\eps_j,\eps_j-\eps'_j,0),\] 
which has length at most $2$. Hence the map is $2$-Lipschitz.

Let us prove that $\vv$ maps $F_n^\Lamp$ to a coarsely dense subset of $F_n^{\SOL}$. The fact that $\vv(F_n^\Lamp)\subset F_n^{\SOL}$ is obvious, so we focus on the coarse density. We shall prove that every element $h=(a,b,j)\in F_n^{\SOL}$ lies at bounded distance from $\vv(F_n^\Lamp)$. Perturbating $h$ at distance at most one, we can assume that $j\in \Z$. Let $g=(x,j)\in \Lamp_k$, with $x=(\eps_i)$.
We have $\vv(g)=\left(\sum_i\eps_ik^i,\sum_i \eps_ik^{-i}, j\right)$. Hence,
\[\vv(g)^{-1}h=\left(\left(k^{-j}a-\sum_i \eps_ik^{i-j}\right), \left(k^jb-\sum_i \eps_ik^{-i+j}\right), 0\right).\] 
Since $h\in  F_n^{\SOL}$, we have $\lfloor k^{-j}a\rfloor\leq k^{n-j+1}$ and $\lfloor k^{j-1}b\rfloor\leq k^{n+j}$, so their  $k$-adic decompositions are respectively supported in $[0,n-j]$ and $[0,n+j-1]$. Now, choose $\eps_i$ be such that $\sum_{i\geq j} \eps_ik^{i-j}$ is the $k$-adic decomposition of $\lfloor k^{-j}a\rfloor$, and  $\sum_{i< j} \eps_ik^{-i+j-1}$ is the $k$-adic decomposition of $\lfloor k^{j-1}b\rfloor$. It follows that $\eps_i$ is supported on $[-n,n]$, hence that $g\in F_n^\Lamp$. 
Besides, \[\left|k^{-j}a-\sum_{i\geq j} \eps_ik^{i-j}\right|=k^{-j}a-\lfloor k^{-j}a\rfloor
\leq 1\] and  \[\left|k^jb-\sum_{i<j} \eps_ik^{-i+j}\right|=k\left|k^{j-1}b-\sum_{i<j} \eps_ik^{-i+j-1}\right|=k(k^{j-1}b-\lfloor k^{j-1}b\rfloor)\leq k.\]
We therefore have $\left|k^{-j}a-\sum_{i} \eps_ik^{i-j}\right|\leq 2$ and $\left|k^jb-\sum_{i} \eps_ik^{-i+j}\right|\leq 2k$, and so we have duly constructed an element $g\in F_n^\Lamp$ such that $d(\vv(g),h)\leq \log_k (1+2k)$. 


We now turn our attention to the last two properties, which will be proved all at once. 
For this we fix some $g\in F_n^\Lamp$.
Let $g'\in \Lamp_k$ such that $d(\vv(g'), \vv(g))\leq q.$ Note that if $g=(x,j)$ and $g'=(x',j')$, we have \[g^{-1}g' = ((-j)\cdot (x'-x), j'-j).\]
Write $x=(\eps_i)$ and $x'=(\eps'_i)$. We have
\[\vv(g)^{-1}\vv(g')=\left(\sum_i(\eps'_i-\eps_i) k^{i-j},\sum_i(\eps'_i-\eps_i) k^{j-i},j'-j\right).\]
The condition that $d(\vv(g'), \vv(g))\leq q$ implies that $|j-j'|\leq q$. So $d(g,g')\geq 2m+3q$ implies that $2\diam((\supp(x'-x)-j)\cup \{0\})+q\geq 2m+3q$, hence  $\diam((\supp(x'-x)-j)\cup \{0\})\geq m+q$.
We let $\ell_+,\ell_-$ be respectively the maximal, minimal integer such that $\eps_{\ell_+}\neq \eps'_{\ell_+}$,  $\eps_{\ell_-}\neq \eps'_{\ell_-}$.
Note that either $\ell_+\geq  j+m+q$ or $\ell_-\leq j-m-q$.
Let $J_-=[\ell_-+1,j-q-1]$ and $J_+=[j+q+1,\ell_+-1]$. Note that one of these intervals can possibly be empty, but one of them has size at least $m-1$.
\begin{clai}\label{clai:J}
In each interval $J_-$ and $J_+$, either $\eps_i$ is identically $0$, and $\eps'_i$ is identically $k-1$, or vice versa.
\end{clai}
\begin{proof}
Both cases are treated similarly, so we only consider $J_+$, which we can assume to be non empty.  
We have
\[\sum_i(\eps'_i-\eps_i) k^{i-j}=(\eps'_{\ell_+}-\eps_{\ell_+})k^{{\ell_+}-j}+\sum_{i<\ell_+}(\eps'_i-\eps_i)k^{i-j}.\]
By symmetry, we can assume without loss of generality that $\eps'_{\ell_+}>\eps_{\ell_+}$.
Therefore,
\[\left|\sum_i(\eps'_i-\eps_i) k^{i-j}\right|=\sum_i(\eps'_i-\eps_i) k^{i-j}\geq k^{\ell_+-j}+\sum_{i<\ell_+}(\eps'_i-\eps_i)k^{i-j}.\]
We let $t$ be the maximal integer  $<\ell_+$ such that $\eps'_{t}-\eps_{t}\neq -k+1$. We have
\[\left|\sum_i(\eps'_i-\eps_i) k^{i-j}\right|\geq k^{\ell_+-j}-(k-1)\sum_{i=t}^{\ell_+-1}k^{i-j}=k^{t-j}.\]
On the other hand, since $d(\vv(g'), \vv(g))\leq q$, we have $t-j\leq q$. In other words, $\eps_i'-\eps_i=-k+1$ for all $r+j<i< \ell_+$, hence for all $r+j<i<m+q+j$. This imposes for such values of $i$ that $\eps_i=k-1$ and $\eps'_i=0$, and the claim is proven.
\end{proof}
It is now straightforward to deduce our two properties from the claim. First, since the coordinates of $x$ on $J_+$ and $J_-$ are prescribed, with two possible values, the proportion of such $g\in F_n^\Lamp$ is at most $4k^{-m+1}$. 
Second, if $x$ is given, we see that the coordinates of $x'$ outside the interval $[j-q,j+q]$ are determined by those of $x$. This leaves $k^{2q+1}$ possibilities for choosing $x'$, and since $|j'-j|\leq q$, we have $(2q+1)k^{2q+1}$ for the choice of $g$. This ends the proof of the lemma.
\end{proof}

\noindent{\bf Second step: constructing a map from $\Lamp_k$ and  $\SOL_A$.} 

Let us describe an embedding of  $\SOL_A$ in  $\SOL_\R$. We start with the obvious embedding of $\SOL_A$ in the semi-direct product $\R^2\rtimes_A \R$, where the notation means that $t\in \R$ acts by multiplication by the matrix $A^t$. Denote by $\Gamma_0'$ the image of $\SOL_A$. A relatively compact fundamental domain $D_0'$ for the action by left-translations of $\Gamma_0$ on $\R^2\rtimes_A \R$ is simply given by $[0,1)^3$.
Choose a basis $(v_+,v_-)$ of eigenvectors of $A$ associated to the eigenvalues $\lambda$ and $\lambda^{-1}$. We have an isomorphism $ \SOL_\R\to \R^2\rtimes_A \R$ given by \[(a,b,t)\mapsto (av_++bv_-, \frac{\log \lambda}{\log k}t),\]
whose inverse will be denoted by $\mathfrak{p}$. Denote $\Gamma_0=\mathfrak{p}(\Gamma_0')$ and  $D_0=\mathfrak{p}(D_0')$.  By construction, $\Gamma_0$ is a copy of $\SOL_A$ embedded as a lattice in $\SOL_\R$, and $D_0$ is a fundamental domain for its action by left-translations. Note that $D_0$
 is relatively compact, and with no-empty interior and contains the neutral element.

Although $\vv$ is obviously injective, its image is a priori not uniformly discrete\footnote{It is indeed  not the case as the elements  $(x,0)$ and $(x',0)$, where $x=(k-1)1_{[-m,m]}$ and $x'=1_{\{-m-1,m+1\}}$ are at distance  $O(q^{-m})$ from each other.}.
We start modifying $\vv$ so that while remaining injective, its image is a uniformly discrete subset of $\SOL_\R$. By Lemma \ref{lem:psi},  the preimage of any (left) $\Gamma_0$-translate of $D_0$ has cardinality bounded above by some constant $N$. In other words, every such translate of $D_0$ contains at most $N$ elements of $\Im\vv$. Since $D_0$ has non-empty interior, we can therefore modify $\vv$ to a map $\vv_0$ such that for all $g$, $\vv_0(g)$ belongs to the same $\Gamma_0$-translate of $D_0$ as $\vv(g)$, and such that $\vv_0$ has uniformly discrete image.

Our next step consists in modifying $\vv'$ further to have it land in some (different) copy of $\SOL_A$ in $\SOL_\R$.  Our goal is to do it in order to get an injective map from $\Lamp_k$ to $\SOL_A$. 
Since we have assumed (from the beginning) that $k\geq \lambda$, we already have that two elements of $D_0\cap \Im\vv$ have same $\R$-coordinate, which ensures that $\vv_0$ is already injective in restriction to the $\Z$ coordinates.  In order to obtain an injective map, we will replace $\Gamma_0$ by a copy which is ``denser' in the $\R^2$-coordinate.

For all $t>0$, consider the automorphism $\theta_t$ which multiplies the $\R^2$-coordinate by $t$. Let $\tau_t=\theta_t\circ \tau_0$, $\Gamma_t=\Im(\tau_t)$ and let $D_t=\theta_t(D_0)$. Observe that $D_t$ is a fundamental domain for the left $\Gamma_t$ action on $\SOL_\R$. Hence by choosing $t$ small enough, we can assume that the euclidean diameter of $D_t\cap \R^2$ is arbitrarily small. Combined with the fact that $\Im\vv_0$ is uniformly discrete, and that  $\theta_t$ does not affect the $\R$ coordinate, we can choose $t\leq 1$ small enough so  that  every $\Gamma_t$-translate of $D_t$  contains at most one element of $\Im\vv_0$. From now on, we fix such $t$ and omit the subscript $t$.

We define a map $\uu:\Lamp_k\to \Gamma$ as follows: $\uu(g)=\gamma\in \Gamma$ where $\gamma$ is the unique element such that $\vv_0(g)\in \gamma D$. Since $\gamma D$ contains at most one element of $\Im\vv_0$, the map $\uu$ is injective.

Now, let $C$ be such that $D_0\subset B_{\SOL_\R}(e,C/2)$. Note that we also have  $D\subset B_{\SOL_\R}(e,C/2)$. 
By construction,  $d(\uu(g),\vv(g))\leq C$ for all $g\in \Lamp_k$ (where the distance is measured with respect to the word metric of $\SOL_\R$). 

We let $\mathcal G_n=F_n^\Lamp$ and $\mathcal H_n=F_n^{\SOL}B_{\SOL_\R}(e, C)\cap \Gamma$. Since $\vv$ maps $F_n^\Lamp$ to a coarsely dense subset of $F_n^{\SOL}$, we have that $\uu$ maps it to a coarsely dense subset of $\mathcal H_n$. Restricting $\uu$ to $\mathcal G_n$, we therefore get a sequence of maps $\uu_n: \mathcal G_n\to \mathcal H_n$.

Let us check that $\mathcal H_n$ is a F\o lner sequence of $\Gamma$. Let $R$ be such that $T=B_{\SOL_\R}(e,R)\cap \Gamma$ defines a generating set of $\Gamma$. Then it is enough to prove that $\lim_{n\to \infty}\frac{\#\mathcal{H}_nT}{\#\mathcal{H}_n}=1$.  Note that
\[\frac{\#\mathcal{H}_nT}{\#\mathcal{H}_n}=\frac{\lambda(\mathcal{H}_nTD)}{\lambda(\mathcal{H}_nD)}.\]
On the other hand, suppose $g\in \SOL_\R$, then it belongs to a unique $\gamma D$, where $\gamma\in \Gamma$. In particular we have $d(g,\gamma)\leq C.$ So if $g\in F_n^{\SOL}$, then $\gamma\in \mathcal{H}_n$.
Hence,  $F_n^{\SOL}\subset \mathcal{H}_nD$, which implies that $\lambda(\mathcal{H}_nD)\geq \lambda(F_n^{\SOL})$.
Now, we have that $TD\subset B(e,R+C)$, hence $\mathcal{H}_nTD\subset F_n^{\SOL}B(e,R+2C)$. We deduce that 
\[\frac{\#\mathcal{H}_nT}{\#\mathcal{H}_n}\leq \frac{\lambda(F_n^{\SOL}B(e,R+2C))}{\lambda(F_n^{\SOL})},\]
which converges to $1$ since $F_n^{\SOL}$ is a F\o lner sequence.

We fix an arbitrary finite generating set for $\Gamma$.
Observe that since $\Gamma$ is a uniform lattice in $\SOL_\R$, its word metric is bi-Lischitz equivalent to the restriction the word metric of $\SOL_\R$.
We deduce from Lemma \ref{lem:psi} and the previous discussion that $\uu$ satisfies the following properties.

\begin{lemma}\label{lem:phi}
There exists a constant $L\geq 1$ such that $\uu$ satisfies the following properties:
\begin{itemize}
\item[(i)] it is $L$-Lipschitz;
\item[(ii)] it is injective;
\item[(iii)] it has $L$-dense image;
\item[(iv)] for all integers $q,m\geq 1$,
the proportion of points $g\in \mathcal G_n$ such that $\diam\uu^{-1}(B_{\Gamma}(\uu(g),q/L-L))\geq 2m+3q$ is at most $4k^{-m+1}$.
\end{itemize}
\end{lemma}
Our next step is the following consequence of (ii) and (iv) from the previous lemma.
\begin{lemma}\label{lem:Last}
There exists a constant $C'$ such that for all $\delta>0$, there exists $C'''$ such that for all $h\in \Gamma$,
\[\sum_{r\geq 0}e^{\delta r}\PP_{ \mathcal{H}_n}\left(\left\{y\in \uu( \mathcal{G}_n) \mid  \diam(\uu^{-1}(y)\cup \uu^{-1}(yh))\geq r \right\}\right)\leq C'''e^{C'\delta |h|}.\]
\end{lemma}
\begin{proof}
Reformulating (iv), we have 
\[ \PP_{ \mathcal{G}_n}\left(\left\{g \mid \diam\uu^{-1}(B_{\Gamma}(\uu(g),q/L-L))\geq 2m+3q\right\}\right)\leq 4 k^{-m+1}.  \]
By (ii), this implies that 
\[\PP_{ \mathcal{H}_n}\left(\left\{y\in \uu( \mathcal{G}_n)\mid \diam\uu^{-1}(B_{\Gamma}(y,q/L-L))\geq 2m+3q\right\}\right)\leq 4 k^{-m+1}.\]
We set $p=q/L-L$. Then the previous inequality implies the following one:
\[\PP_{ \mathcal{H}_n}\left(\left\{y\in \uu( \mathcal{G}_n)\mid \diam\uu^{-1}(B_{\Gamma}(y,p))\geq 2m+3pL+L^2p\right\}\right)\leq 4 k^{-m+1}.\]
Letting $r=2m+3pL+L^2p$, and $C=(3L+L^2)/2$ and we deduce 
\[\PP_{ \mathcal{H}_n}\left(\left\{y\in \uu( \mathcal{G}_n)\mid \diam\uu^{-1}(B_{\Gamma}(y,p))\geq r \right\}\right)\leq 4 k^{-r/2+Cp+1}.\]
Hence we deduce that for all $h\in \Gamma$, 
\[\PP_{ \mathcal{H}_n}\left(\left\{y\in \uu( \mathcal{G}_n)\mid  \diam(\uu^{-1}(y)\cup \uu^{-1}(yh))\geq r \right\}\right)\leq 4 k^{-r/2+C|h|+1}.\]
Let $r_0=4C|h|+4$.
Then for $r\geq r_0$, we have
\[\PP_{ \mathcal{H}_n}\left(\left\{y\in \uu( \mathcal{G}_n) \mid  \diam(\uu^{-1}(y)\cup \uu^{-1}(yh))\geq r \right\}\right)\leq 4 k^{-r/4}.\]
Besides for all $\delta>0$, $|h|\geq 1$
\[\sum_{r=0}^{r_0-1}e^{\delta r}\leq \frac{e^{\delta(4C|h|+4)}}{e^{\delta}-1}\leq C''e^{C'\delta |h|},\] where $C'=4C+4$, and $C''=1/(e^\delta-1)$.
We can now conclude that for $\delta\leq (\log k)/8$.
\begin{align*}
\sum_{r\geq 0}e^{\delta r}[\PP_{ \mathcal{H}_n}\left(\left\{y\in\uu( \mathcal{G}_n)\mid  \diam(\uu^{-1}(y)\cup \uu^{-1}(yh))\geq r \right\}\right)
& \leq C''e^{C'\delta |h|} +4\sum_{r=r_0}^{\infty}k^{-r/4} e^{\delta r}\\
& \leq C''e^{C'\delta |h|} +4 e^{\delta r_0} \sum_{r=0}^{\infty} k^{-r/4} e^{\delta r}\\
& \leq C''e^{C'\delta |h|} +4 e^{C'\delta |h|} \sum_{r=0}^{\infty} k^{-r/8}\\
& \leq C'''e^{C'\delta |h|},
\end{align*}
where $C'''=C''+4 \sum_{r=0}^{\infty} k^{-r/8}$, and the lemma is proven.
\end{proof}

\noindent{\bf Last step: from word distance to intrinsic distance.}

Note that in Lemmas \ref{lem:phi} and \ref{lem:Last}, we use the distance in the groups and not the intrinsic graph distance in the F\o lner sets. Obviously the last one is larger or equal than the first one, and it coincides for elements $x,y$ at distance at most $r$ in $\mathcal{H}_n$, such that $x\in \mathcal{H}_n^{(r)}$. Actually here,  $\mathcal{H}_n^{(r)}$ contains all vertices of $\mathcal{H}_n$ which are at $\Gamma$-distance at least $r+1$ from the complement of $\mathcal{H}_n$. 

Passing to the intrinsic distance, we might loose $L$-density of the map $\uu: \mathcal{G}_n\to \mathcal{H}_n$. But it can be restored by modifying slightly $\mathcal H_n$ as follows: replace it by $\mathcal H_n'=\mathcal H_nB_\Gamma(e_\Gamma,L)$ (which is still a F\o lner seqence). Now $\mathcal H_n$ lies in $\mathcal{H}_n'^{(L)}$ and by  the previous remark,
$\uu(\mathcal{G}_n)$ is $L$-dense in $\mathcal H_n$ for the {\it intrinsic distance} in $\mathcal H_n'$. But by construction $\mathcal H_n$ is $L$-dense in $\mathcal H'_n$ for the intrinsic distance: indeed the latter equals $\bigcup_{y\in \mathcal H_n}B_\Gamma(y,L)$.
Hence we deduce that $\uu(\mathcal{G}_n)$ is $2L$-dense in $\mathcal H_n'$ for the intrinsic distance of $\mathcal H_n'$. 
A similar argument shows that $\uu: \mathcal{G}_n\to \mathcal{H}'_n$ is $L$-Lipschitz.

To get a $\mathcal U$-statistical version of \cref{lem:Last} in intrinsic distance, we use the following lemma.
\begin{lemma}\label{lem:intrinsic}
We have
\[\lim_{\mathcal U}\PP_{ \mathcal{H}'_n}\left(\left\{y\in\uu( \mathcal{G}_n)\mid  \diam(\uu^{-1}(y)\cup \uu^{-1}(yh))= \diam_{\mathcal H_n'}(\uu^{-1}(y)\cup \uu^{-1}(yh))\right\}\right)=1. \]
\end{lemma}
\begin{proof}
Denote $r_y= \diam(\uu^{-1}(y)\cup \uu^{-1}(yh))$. 
By the previous discussion it suffices to prove that 
\begin{equation}\label{eq:r_y1}
\lim_{\mathcal U}\PP_{ \mathcal{H}'_n}\left(\left\{y\in\uu( \mathcal{G}_n)\mid \uu^{-1}(y)\in \mathcal{G}_n^{r_y}\right\}\right)=1.
\end{equation}
By \cref{lem:Last}, we know that 
\begin{equation}\label{eq:r_y2}
\lim_{r\to \infty}\lim_{\mathcal U}\PP_{ \mathcal{H}'_n}\left(\left\{y\in\uu( \mathcal{G}_n)\mid  r_y\leq r\right\}\right)=1.
\end{equation}
Denoting $\eta=\lim_{\mathcal U}|\mathcal G_n|/|\mathcal H'_n|$, we have, for each $r\geq 0$
\[\lim_{\mathcal U}\PP_{ \mathcal{H}'_n}\left(\left\{y\in\uu( \mathcal{G}_n)\mid \uu^{-1}(y)\notin \mathcal{G}_n^{(r)}\right\}\right)=\eta\PP_{ \mathcal{G}_n}\left(\left\{x\in \mathcal{G}_n\mid x\notin \mathcal{G}_n^{(r)}\right\}\right)=0.\]
Therefore, 
\[\lim_{\mathcal U}\PP_{ \mathcal{H}'_n}\left(\left\{y\in\uu( \mathcal{G}_n)\mid \uu^{-1}(y)\in \mathcal{G}_n^{(r)}\right\}\right)=1,\]
which combined with (\ref{eq:r_y2}) implies (\ref{eq:r_y1}). This proves the lemma. 
\end{proof}


Let us consider the sequence of maps $\uu_n: \mathcal{G}_n\to \mathcal{H}'_n$, induced by $\uu$. By the previous discussion, $\uu_n$ is injective, $L$-Lipschitz, has $2L$-dense image. 
Besides, combining \cref{lem:Last} and \cref{lem:intrinsic}, we deduce that $\uu_n$ satisfies 
\[\sum_{r\geq 0}e^{\delta r}\lim_{\mathcal U}\PP_{ \mathcal{H}'_n}\left(\left\{y\in \uu( \mathcal{G}_n) \mid  \diam_{\mathcal H'_n}(\uu^{-1}(y)\cup \uu^{-1}(yh))\geq r \right\}\right)\leq C'''e^{C'\delta |h|}.\]

\noindent{\bf Concluding step.}

 We are now ready to end the proof of Theorem \ref{thm:example}. 
The conditions of \cref{thm:quantME}  and Remark \ref{rem:Strong} being satisfied\footnote{Recall that the $L^{\infty}$ condition is formally equivalent to $\varphi$-integrability for a function $\varphi:\R_+\to \R_+\cup \{+\infty\}$, where $\varphi(t)=\infty$ for $t\geq 1$.}, we obtain the desired integrability conditions. The fact that the resulting ME coupling is mutually cobounded follows from \cref{prop:fundamentalDomainBis} together with the fact that $\uu_n$  is
injective, and has $2L$-dense image.
\end{proof}

\begin{proof}[Proof of \cref{thm:SolvableExpME}]
By Proposition 2.30 of \cite{DKLMT-22}, we know that the existence of such a measure equivalence is an equivalence relation. 
Then, by \cite[Theorem 8.1]{DKLMT-22}, we have that $(\Z/k\Z)\wr\Z$ and $\operatorname{BS}(1,k)$ are in the same equivalence class for any $k$.
By \cref{thm:example}, we have that $(\Z/k\Z)\wr\Z$ lies in the equivalence class of $\SOL_A$. The groups $\SOL_A$, for different matrices $A$, are all equivalent since they are uniform lattices in the same connected Lie group. So the theorem is proved.
\end{proof}


