\section{Pseudo-inverse of statistical coarsely bijective maps} 

By anology with quasi-isometries which admit pseudo-inverses which are again quasi-isometries, we show that for statistically coarsely bijective maps, such a pseudo-inverse exists and satisfies good properties. This is not used in the core of the paper, but we believe it could have future applications.


\begin{proposition}\label{prop:bijec}
	Let $(Y_n)_n$ and $(Z_n)_n$ be two sequences of uniformly locally finite metric spaces, let $\uu_n\colon Y_n\to Z_n$ be a sequence maps. There exists a sequence of  maps $\vv_n\colon Z_n\to Y_n$ such that
	\[d_{Z_n}(z,\Im(\uu_n))=d_{Z_n}(z,\uu_n(\vv_n(z))).\]

Moreover, if $(\uu_n)$ is $\mathcal{U}$-statistically coarsely injective (resp.\ surjective), then $(\vv_n)_n$ is  $\mathcal{U}$-statistically coarsely surjective (resp.\ injective).
\end{proposition}
\begin{proof}
Set $\uu_n:=\theta_n\circ \pi_n$, where $\theta_n:\uu_n(Y_n)\to Y_n$ is an injective right-inverse of $\uu_n:Y_n\to\uu_n(Y_n)$, and where $\pi_n$ is a projection from $Z$ to $\uu_n(Y)$ such that $d_{Z_n}(z,\pi_n(z))=d_{Z_n}(z,\uu_n(Y))$	
(Note that such a map always exists).

Note that for all $y\in Y_n$, $\vv_n(\uu_n(y))$ belongs to $\uu_n^{-1}(\uu_n(y))$. Therefore,
\[d_{Y_n}(y,\vv_n(Z_n))\leq d_{Y_n}(y,\vv_n(\uu_n(y)))\leq  \diam(\uu_n^{-1}(\uu_n(y))). \]
Hence the $\mathcal{U}$-statistical coarse surjectivity of  $(\vv_n)_n$ follows from the $\mathcal{U}$-statistical coarse injectivity of $(\uu_n)_n$.

For the other direction, 
it is enough to show that $\pi_n$ is $\mathcal{U}$-statistically coarsely injective. We let $\eps>0$. Let $C_0$ be such that the proportion of $z\in Z_n$ at distance at least $C_0$ from $\uu_n(Y_n)$ is at most $\eps/2$.


We then observe that for every $z\in \uu_n(Y_n)$ such that $\diam(\pi_n^{-1}(z))\geq C$, there exists $z'\in \pi_n^{-1}(z)$ that lies at distance at least $C/2$ from $\uu_n(Y_n)$. Let $A_n(C)$ be the subset of elements of $\uu_n(Y_n)$ whose pre-images under $\pi_n$ have diameter at least $C$. The previous argument, together with the $\mathcal{U}$-statistical coarse surjectivity of $(\uu_n)$ shows that $\lim_\mathcal{U}\#A_n(C)/\#Z_n$ tends to $0$ as $C$ tends to infinity.
Note that the elements $z\in Z_n$ that are at distance at most $C_0$ from $\uu_n(Y_n)$ and satisfy $\diam(\pi_n^{-1}(\pi_n(z)))\geq C$ lie in the $C_0$-neighborhood of $A_n(C)$, whose size is at most $N\#A_n(C)$ where $N$ is the maximal size of a ball of radius $C_0$ in $Z_n$ (for all $n$). Hence its proportion is $\mathcal{U}$-a.e at most $\eps/2$ for $C$ large enough. With our choice of $C_0$, we deduce that the proportion of points of $Z$ such that $\diam(\pi_n^{-1}(z))\geq C$ is $\mathcal{U}$-a.e. at most $\eps$, so we are done. 
\end{proof}


\begin{proposition}\label{prop:biLip}
	Let $(Y_n)_n$ and $(Z_n)_n$ be two sequences of finite metric spaces that are uniformly locally finite and $\uu_n\colon Y_n\to Z_n$ be a sequence of $\mathcal{U}$-statistically coarsely surjective maps, and let $(\vv_n)_n$ be an ``inverse map'', as defined in \cref{prop:bijec}.
	\begin{itemize}
	\item  If $(\uu_n)_n$ is $\mathcal{U}$-statistically expansive, then $(\vv_n)_n$ is $\mathcal{U}$-statistically Lipschitz,
	\item  If $(\uu_n)_n$ is $\mathcal{U}$-statistically Lipschitz, then $(\vv_n)_n$ is $\mathcal{U}$-statistically expansive,
	\item If $(\uu_n)_n$ is $\mathcal{U}$-statistically a coarse equivalence, then so is $(\vv_n)_n$.
	\end{itemize}
\end{proposition}
\begin{proof}
	By \cref{prop:bijec}, the third statement follows from the two first ones. We start proving the first statement. In what follows, we let $r>0$. We start showing that they are $\mathcal{U}$-statistically Lipschitz. We fix some $\eps>0$.
We want to show that for $C$ large enough,
\begin{equation}\label{eq:statCoarLip}\lim_\mathcal{U} \frac{\#\left\{(z,z')\in Z_n^2\mid d(z,z')\le r, d(\vv_n(z),\vv_n(z'))\ge C\right\}}{\#Z_n}\leq \eps.
\end{equation}
We 
distinguish two cases, whether $d(z',\uu_n(Y_n))$ is larger or smaller than some suitable constant $C_0$. For every $R>0$ we let $N_R$ be the maximal cardinality of a ball of radius $R$ in $Z_n$ for all $n$. We have
\[ \frac{\#\left\{(z,z')\in Z_n^2\mid d(z,z')\le r, d(z',\Im(\uu_n))\ge C_0\right\}}{\#Z_n}\leq N_r\frac{\#\left\{z'\in Z_n,   d(z',\Im(\uu_n))\ge C_0\right\}}{\#Z_n}.\]
Using that $(\uu_n)$ is $\mathcal{U}$-statistically coarsely surjective, there exists $C_0$ such that the latter is $\mathcal{U}$-a.e. at most $\eps/2$.

On the other hand, by the property defining $\vv$, the  two conditions $d(z,z')\le r$ and $d(z',\Im(\uu_n))\le C_0$ imply that $d(z,\uu_n(\vv_n(z')))\le r+C_0$. 
Hence the quantity
\[ \frac{\#\left\{(z,z')\in Z_n^2\mid d(z,z')\le r, d(\vv_n(z),\vv_n(z'))\ge C,  d(z',\Im(\uu_n))\le C_0 \right\}}{\#Z_n}\]
is at most 
\[ \frac{\#\left\{(z,z')\in Z_n^2\mid d(\vv_n(z),\vv_n(z'))\ge C, d(z,\uu_n(\vv_n(z')))\le r+C_0, d(z',\Im(\uu_n))\le C_0  \right\}}{\#Z_n}.\]

Note that  the condition $d(z',\Im(\uu_n))\le C_0$ implies that two such values of $z'$ with same image under $\vv_n$ lie in the ball $B_{Z_n}(\uu_n(y),C_0)$. Hence with a change of variable $y=\vv_n(z')$, we obtain that the latter is at most
\[ \sum_{y\in Y_n}N_{C_0}\frac{\#\left\{z\in Z_n\mid d(z,\uu_n(y))\le r+C_0,d(\vv_n(z),y)\ge C \right\}}{\#Z_n}.\]
Note that, with the notation of Proposition \ref{prop:bijec}, $\vv_n(z)\in \uu_n^{-1}(\pi_n(z))$, and recall that $d(z,\pi_n(z))=d(z,\Im(\uu_n)$. Hence the subset
$\left\{z\in Z_n\mid d(z,\uu_n(y))\le r+C_0,d(\vv_n(z),y)\ge C \right\}$
 is contained in the $(r+C_0)$-neighborhood of elements $z''\in \Im(\uu_n)$ such that $d(z'',\uu_n(y))\le 2r+2C_0$ and
$\diam(\uu_n^{-1}(\pi_n(z))\cup \{y\})\geq C$.
In other words the above expression is at most 
\[ \sum_{y\in Y_n}N_{C_0}N_{r+C_0}\frac{\#\left\{z''\in Z_n\mid d(z'',\uu_n(y))\le 2r+2C_0,\diam(\uu_n^{-1}(z'')\cup \{y\})\geq C) \right\}}{\#Z_n},\]
which by the $\mathcal{U}$-statistical coarse expansivity of $(\uu_n)$ and Proposition \ref{prop:compaireSize} (which allows us to replace $\#Z_n$ by $\#Y_n$), can be made ($\mathcal{U}$-a.e.) at most $\eps/2$ by choosing $C$ large enough.
This concludes the proof of (\ref{eq:statCoarLip}), and thus of the fact that $(\vv_n)$ is $\mathcal{U}$-statistically Lipschitz.


Let us now assume that $(\uu_n)_n$ is $\mathcal{U}$-statistically Lipschitz. Note that we can deduce from the assumptions that $\uu_n$, and therefore $\vv_n$ are $\mathcal{U}$-statistically coarsely bijective.  We need to show that the expression
\[\frac{\#\left\{(y,z)\in Y_n\times Z_n \mid d_{Y_n}(y,\vv_n(z))\le r, \diam(\{z\}\cup\vv^{-1}_n(y))\ge C \right\}}{\#Z_n}\]
tends to zero as $C\to \infty$.
We first note that we can assume that $d(z,\Im\uu_n)\leq C_0$ for some large enough constant $C_0$. Indeed, the set  
\[\frac{\#\left\{(y,z)\in Y_n\times Z_n \mid d_{Y_n}(y,\vv_n(z))\le r, d(z,\Im\uu_n)\geq C_0 \right\}}{\#Z_n}\]
is at most 
\[N_r\frac{\#\left\{(z)\in Z_n \mid d(z,\Im\uu_n)\geq C_0 \right\}}{\#Z_n}\]
which can be made arbitrarily small  ($\mathcal{U}$-a.e.) by choosing $C_0$ large enough, as $\uu_n$ is $\mathcal{U}$-statistically coarsely surjective. Hence  we are left to bound the expression
\[N_{C_0}\frac{\#\left\{(y,y')\in Y_n^2 \mid d_{Y_n}(y,\vv_n(\uu_n(y')))\le r,  \diam(\{\uu_n(y')\}\cup\vv^{-1}_n(y))\ge C \right\}}{\#Z_n}.\]
Since $N_{C_0}$ is a constant, we can simply ignore it. Moreover, by \cref{prop:compaireSize}, it is enough to show that 
\[\lim_{C\to \infty}\left(\lim_\mathcal{U}\frac{\#\left\{(y,y')\in Y_n^2 \mid d_{Y_n}(y,\vv_n(\uu_n(y')))\le r,  \diam(\{\uu_n(y')\}\cup\vv^{-1}_n(y))\ge C \right\}}{\#Y_n}\right)=0.\]
Note that $\vv_n(\uu_n(y'))\in \uu_n^{-1}(\uu_n(y'))$. So reasoning as before, using that $(\uu_n)$ is $\mathcal{U}$-statistically coarsely injective, we are left to show that
\[\lim_\mathcal{U}\frac{\#\left\{(y,y')\in Y_n^2 \mid d_{Y_n}(y,y'))\le r+C_0,  \diam(\{\uu_n(y')\}\cup\vv^{-1}_n(y))\ge C-C_0 \right\}}{\#Y_n}\]
tends to zero as $C\to \infty$, for some given large enough constant $C_0$. 
if $C>0$, this forces $y$ to be in the image of $\vv_n$, and by definition of $\vv_n$, we have that $\Im \vv_n=\Im\vv_n\circ \uu_n$. 
Hence there exists $y''\in Y_n$ such that $y=\vv_n(\uu_n(y''))$. Again by definition of $\vv_n$, this implies that $y\in \uu_n^{-1}(\uu_n(y'')$ and therefore that $y=y''$. In conclusion we have that $\uu_n(y)\in \vv_n^{-1}(y)$.
Hence the above expression is at most 
\[\lim_\mathcal{U}\frac{\#\left\{(y,y')\in Y_n^2 \mid d_{Y_n}(y,y'))\le r+C_0, d(\uu_n(y'),\uu_n(y)\ge C-C_0 \right\}}{\#Y_n},\]
which tends to zero as $C\to \infty$, independently of $n$, as $(\uu_n)$ is $\mathcal{U}$-statistically Lipschitz. This ends the proof the second statement, hence of the proposition.
\end{proof}

Finally, we prove a more quantitative statement about pseudo-inverses.

\begin{proposition}
Let $\uu:Y\to Z$ be a map between two finite metric spaces and let $\vv$ be the pseudo-inverse map of $\uu$.
We let $K,L,C$ be positive integers, and $\eps, \delta$ be positive real numbers. Assume that:
	\begin{itemize}
	\item[(i)] $\PP(y\mid \diam\uu^{-1}(B(\uu(y),2(K+L)))\geq C)\leq \eps$;	
	\item[(ii)]  $\PP(z\mid d(z,\uu(Y))\geq K))\leq \delta$; 
	\end{itemize}
	Then 
	\[\PP(z\mid \diam(\vv(B(z,L) \geq C)\leq \frac{\#Y}{\#Z}V_Z(K)\eps+\delta\]
\end{proposition}
\begin{proof}
We let $Z'=[\uu(Y)]_K$. By (ii), we have $\PP(Z\setminus Z')\leq \delta$. 
Since for every $z\in Z'$, there exists $z'\in B(z,K)\cap\uu(Y)$, we deduce that the event 
$\{z\in Z'\mid  \diam(\vv(B(z,L) \geq C \}$ is included in the event  $\{z\mid \exists z'\in B(z,K)\cap\uu(Y)\mid \diam(\vv(B(z',K+L) \geq C \}$. We deduce that
\[ \PP(z\in Z'\mid \diam(\vv(B(z,L) \geq C)\leq V_Z(K)\PP(z\in \uu(Y)\mid \diam(\vv(B(z,K+L) \geq C). \]
On the other hand, we have
\[\PP(z\in\uu(Y)\mid \diam(\vv(B(z,K+L) \geq C)\leq \frac{\#Y}{\#Z}\PP(y\in Y \mid \diam(\vv(B(\uu(y),K+L) \geq C) \]
Now observe that since $\vv=\vv\circ\theta$, where $\theta$ is a minimal distance projection from $Z$ to $\uu(Y)$,
for every $z\in B(\uu(y),K+L)$, we have $\theta(z)\in B(\uu(y),2(K+L))\cap \uu(Y)$. Moreover, for every $y\in Y$, we have $\vv(\uu(y))\in \uu^{-1}(\uu(y)).$ Hence we deduce that
\[\vv(B(\uu(y),K+L)\subset \uu^{-1}(B(\uu(y),2(K+L)))\]
Hence we have
\[\PP(y\in Y \mid \diam(\vv(B(\uu(y),K+L) \geq C) \leq \PP(y\in Y\mid \diam\uu^{-1}(B(\uu(y),2(K+L)))\geq C)\leq \eps.\]
The conclusion follows by combining these inequalities.
\end{proof}
