\section{Multiscale geodesic flows (MGF)}
Geodesic flows on the manifold of smooth invertible maps 
$G$ acting on $\mathbb{R}^N$ may be lifted as curves $g_t\in G$ parametrised by time $t$ 
as $x_t = {g_t}x_0\in \mathbb{R}^N$. The flows $g_t\in G$ may be derived via Hamilton's principle 
$0 = \de S = \de \int \ell(u)\,dt$ for a kinetic energy 
Lagrangian $\ell(u)=\tfrac12 \|u\|^2 = \tfrac12\int_\mathbb{R} u\, Q^{op} u \,dx$ 
with vector-field velocity $u=\dot{g}_t{g_t}^{-1}\in \mathfrak{g}\simeq T_eG$ and positive definite, symmetric differential 
operator $Q^{op}$
\[
0 = \de S =  \de \int_0^T \ell(u) + \scp{m}{\dot{g}_t{g_t}^{-1} - u}_{\mathfrak{g}^*\times \mathfrak{g}}\,dt
\,.\]
Here, the brackets $\scp{\cdot}{\cdot}_{\mathfrak{g}^*\times \mathfrak{g}}$ denote $L^2$ pairing between 
the Lie algebra of vector fields $\mathfrak{g}$ and its dual $\mathfrak{g}^*$. 
The dual Lie algebra $\mathfrak{g}^*$ is a Poisson manifold, whose Lie--Poisson bracket is to be discussed momentarily.

Variations of this Hamilton principle yield an evolution equation expressed by the \emph{Lie chain rule} \cite{holm1998euler,crisan2020variational}
\[
\frac{d}{dt}{g_t}_*m(x,t)  = - \,{g_t}_*({\cal L}_{u} m)
\,,\quad\hbox{with}\quad u =  \dot{g}_t g_t^{-1}
\,.\]
Thus, the coordinate-free \emph{Lie derivative} ${\cal L}_{u}$ is defined as (minus) the tangent to the push-forward ${g_t}_*$
along the Eulerian vector field $u=\dot{g}_t g_t^{-1}\in T_eG$ which generates the Lagrangian flow $g_t$ and satisfies the motion equation
\[
\partial_t m  = -\, {\cal L}_{u} m = -\, (\partial_x m + m \partial_x)u  
\,,\]
with $m(x,t) = \de \ell/\de u = Q^{op} u$ for geodesic flow.  Inverting the operator $Q^{op}$
solves for $u =  \dot{g}_t g_t^{-1}$ from which $g_t$ may be reconstructed for 
Lagrangian fluid trajectories.

After Legendre transforming to the conserved energy Hamiltonian
$
h(m) = \scp{m}{u}_{\mathfrak{g}^*\times \mathfrak{g}} - \ell(u)
\,,$
the Lie-Poisson Hamiltonian formulation of geodesic flow on the Poisson manifold $m\in P=\mathfrak{g}^*$, 
with Lie-Poisson bracket $\{ f , h \}$ written in terms of Lie algebra bracket $ [u,v] =: {\rm ad}_uv$,
\begin{align*}%\label{eqn:LPB}
\{ f , h \} &= - \scp{m} { [ \de f / \de m ,\de h / \de m ] }_{\mathfrak{g}^*\times \mathfrak{g}}
    \\&= - \scp{ {\rm ad}^*_{\de h / \de m} m } {\de f / \de m }_{\mathfrak{g}^*\times \mathfrak{g}}
    \\&= - \scp{ {\cal L}_{\de h / \de m} m } {\de f / \de m }_{\mathfrak{g}^*\times \mathfrak{g}}
\,,
\end{align*}
which will be extended here from GF to MGF.
%


\subsection{Lie--Poisson Hamiltonian MGF in 1D} 
The Hamiltonian for a 1D MGF system in $\mathbb{R}$ is 
\begin{align}
H(\{m)\} = \frac12\sum_{k=1}^n \int_\mathbb{R} m_{\alpha_k} K_{\alpha_k} * m_{\alpha_k}\,dx
%= \frac12\sum_{k=1}^n \int_\mathbb{R}  u_{\alpha_k} m_{\alpha_k}\,dx
\,,
\label{Ham-0}
\end{align}
with Eulerian fluid velocity $u_{\alpha_k}(x,t)$ in the sum over finer and finer discrete scales, 
$\alpha_k\in \mathbb{R}$ where $k=1,2,\dots,n,$ $\alpha_{k+1}/\alpha_k=2^{-k}$ and
$m_{\alpha_k}(x,t)$ is defined as 
%
\begin{align*}
m_{\alpha_k}(x,t) &= {Q^{op}}_{\alpha_k} u_{\alpha_k} := (1-\alpha_k^2\p_x^2)u_{\alpha_k}(x,t)
\,,\\
u_{\alpha_k} &= K_{\alpha_k} * m_{\alpha_k} 
=: \int_{\mathbb{R}} K_{\alpha_k}(|x-y|) m_{\alpha_k} (y,t)\,dy
\,,
%\label{In-def}
\end{align*}
where $K_{\alpha_k}(|x-y|)$ is the Green function for the Helmholtz operator $(1-\alpha_k^2\p_x^2)$ on the real line, 
for boundary conditions $\lim_{|x|\to\infty}u_{\alpha_k}(x,t)=0$. 
%decreasing filter widths $\alpha_k$ of $\alpha_{k+1}/\alpha_k=2^{-k}$ .

The Lie--Poisson form of the dynamics for the starting Hamiltonian with $\delta h/\delta m_{\alpha_k}=u_{\alpha_k}$
and $n=3$ is \cite{holm2025geometric}
\begin{align*}
\p_t\begin{pmatrix} m_{\alpha_1} \\  \\ m_{\alpha_2} \\  \\ m_{\alpha_3} \end{pmatrix}
&= -
	\begin{bmatrix} 
	\mathrm{ad}^*_{\Box} m_{\alpha_1} &  \mathrm{ad}^*_{\Box} m_{\alpha_2}  & \mathrm{ad}^*_{\Box} m_{\alpha_3}
	\\ \\
	\mathrm{ad}^*_{\Box} m_{\alpha_2} & \mathrm{ad}^*_{\Box} m_{\alpha_2} & \mathrm{ad}^*_{\Box} m_{\alpha_3}
	\\ \\
	\mathrm{ad}^*_{\Box} m_{\alpha_3} & \mathrm{ad}^*_{\Box} m_{\alpha_3} & \mathrm{ad}^*_{\Box} m_{\alpha_3}
	\end{bmatrix} 
  \begin{pmatrix}
    u_{\alpha_1} \\ \\
    u_{\alpha_2} \\ \\
    u_{\alpha_3}
    \end{pmatrix}
%\label{Poisson-Part1}
    \\&= -
    \begin{pmatrix} \mathrm{ad}^*_{u_{\alpha_1}} m_{\alpha_1} +  \mathrm{ad}^*_{u_{\alpha_2}} m_{\alpha_2} +  \mathrm{ad}^*_{u_{\alpha_3}} m_{\alpha_3} 
    \\ \\
    \mathrm{ad}^*_{u_{\alpha_1} + u_{\alpha_2}} m_{\alpha_2} +  \mathrm{ad}^*_{u_{\alpha_3}} m_{\alpha_3} 
    \\ \\
    \mathrm{ad}^*_{u_{\alpha_1} + u_{\alpha_2} + u_{\alpha_3}} m_{\alpha_3}
    \end{pmatrix},
%\label{Poisson-Part2}
\end{align*}
in which the higher (smaller) scales are seen to apply forces to the lower (larger) scales, while the sum of velocities of the lower (larger) 
scales transports the momenta of the higher (smaller) scales.

The matrix operator in square brackets above defines the following semidirect-product Lie-Poisson bracket \cite{holm1998euler}
\begin{align}
\begin{split}
\frac{df}{dt} = \big\{f,h\big\} &= \sum_{k=1}^n\scp{ m_{\alpha_k}} {\left[ \frac{\delta f}{\delta m_{\alpha_k}} , \frac{\delta h}{\delta m_{\alpha_k}}\right] }
\\& = - \sum_{k=1}^n \scp{ m_{\alpha_k} } { {\rm ad}_{ \frac{\delta h}{\delta m_{\alpha_k} }  }  \frac{\delta f}{\delta m_{\alpha_k}}  }
\\& = - \sum_{k=1}^n \scp{  {\rm ad}^*_{ \frac{\delta h}{\delta m_{\alpha_k} }  }  m_{\alpha_k} } { \frac{\delta f}{\delta m_{\alpha_k}}  }
,\end{split}
\label{LiePoisson-Brkt}
\end{align}
where $\scp{\cdot}{\cdot}$ denotes $L^2$ pairing of functions and  $[\cdot, \cdot]$ denotes the Lie algebra bracket of vector fields. That is,
\[
\bigg[\frac{\delta f}{\delta m}
, \frac{\delta h}{\delta m}\bigg]
=
{\rm ad}_\frac{\delta h}{\delta m}\frac{\delta f}{\delta m}
=
\frac{\delta f}{\delta m}\partial_x\frac{\delta h}{\delta m}
-
\frac{\delta h}{\delta m}\partial_x\frac{\delta f}{\delta m}
.
\]
%
on the dual  of the following \emph{nested} semidirect product Lie algebra 
$
\mathfrak{s} = \mathfrak{g}_{\alpha_1}\ \circledS  \big(\mathfrak{g}_{\alpha_2}\ \circledS\ \mathfrak{g}_{\alpha_3} \ \big)
$,
with dual coordinates given by $m_{\alpha_k}\in \mathfrak{g}_{\alpha_k}^*$ dual to $u_{\alpha_k}\in \mathfrak{g}_{\alpha_k}$ 
correspondingly for $k=1,2,3$, and symbol $\circledS$ denotes the semidirect product operation \cite{holm1998euler}.

Physically, the Lie-Poisson bracket $\{f,h\}$ in \eqref{LiePoisson-Brkt} refers to three types of nested fluid flow.
Its decreasing filter widths $\alpha_k$ for $\alpha_{k+1}/\alpha_k=2^{-k}$ mimic L. F. Richardson's famous ``whorls within whorls within whorls'' reference in characterising fluid dynamics \cite{richardson1922weather}.
\begin{quote}
Big whorls have little whorls, that feed on their velocity, \\and little whorls have lesser whorls, and so on to viscosity

-- L. F. Richardson (1922)
\end{quote}
In a mathematical sense, then, the Lie--Poisson dynamics $\frac{df}{dt}=\{f,h\}$ in \eqref{LiePoisson-Brkt} mimics `Richardson's triple'.
Namely, Richardson's triple is modelled as the composition of three non-commutative right group actions of the smooth invertible maps 
$G_{\alpha_1}\times G_{\alpha_2}\times G_{\alpha_3}$. the corresponding fluid velocities are
\begin{align*}
u_{\alpha_1} &\in \mathfrak{g}_{\alpha_1} \otimes u_{\alpha_2} \in \mathfrak{g}_{\alpha_2}/G_{\alpha_1}
\otimes u_{\alpha_3} \in  (\mathfrak{g}_{\alpha_3}/G_{\alpha_2})/G_{\alpha_1}
\,.\end{align*}
Here, the flow of $G_{\alpha_1}$ can represent the big whorls,  the flow of $G_{\alpha_2}$ can represent the little whorls carried in the frame of motion of  the big whorls, and the flow of $G_{\alpha_3}$ can represent the lesser whorls carried along successively by the two other whorls. 

\subsection{Diagonalising the Hamiltonian formulation} 

The linear transformation of variables to 
\[
\mu_{\alpha_1}= m_{\alpha_1} -m_{\alpha_2}\,,\quad\mu_{\alpha_2}= m_{\alpha_2} -m_{\alpha_3}\,,\quad \mu_{\alpha_3} = m_{\alpha_3}\,,
\]
diagonalises the previous \textit{entangled} Lie--Poisson matrix %in \eqref{Poisson-Part1}
 and leads to equivalent untangled equations, 
%with an \textit{untangled} diagonal Poisson matrix,
\begin{align*}
\begin{split}
\p_t\begin{pmatrix} \mu_{\alpha_1}  \\ \mu_{\alpha_2}  \\ \mu_{\alpha_3} \end{pmatrix}
%&= -
%	\begin{bmatrix}
%	\mathrm{ad}^*_{\Box} \mu_{\alpha_1} & 0 & 0
%	\\
%	0 & \mathrm{ad}^*_{\Box} \mu_{\alpha_2} & 0
%	\\
%	0 & 0 & \mathrm{ad}^*_{\Box} \mu_{\alpha_3}
%	\end{bmatrix}  
% \begin{pmatrix}
%    \frac{\delta h}{\delta \mu_{\alpha_1}} = u_{\alpha_1} \\ 
%    \frac{\delta h}{\delta \mu_{\alpha_2}} = u_{\alpha_1} + u_{\alpha_2} \\ 
%    \frac{\delta h}{\delta \mu_{\alpha_3}} = u_{\alpha_1} + u_{\alpha_2} + u_{\alpha_3}
%    \end{pmatrix}
%
&= -
    \begin{pmatrix} \mathrm{ad}^*_{u_{\alpha_1}} \mu_{\alpha_1} 
    \\
    \mathrm{ad}^*_{(u_{\alpha_1}+u_{\alpha_2})} \mu_{\alpha_2}
    \\
    \mathrm{ad}^*_{(u_{\alpha_1}+u_{\alpha_2}+u_{\alpha_3})} \mu_{\alpha_3}    \end{pmatrix} 
\\&= -
    \begin{pmatrix}  \big(\p_x \mu_{\alpha_1} + \mu_{\alpha_1}\p_x \big)u_{\alpha_1}
    \\
    \big(\p_x \mu_{\alpha_2} + \mu_{\alpha_2}\p_x\big)(u_{\alpha_1}+u_{\alpha_2})
    \\
    \big(\p_x \mu_{\alpha_3} + \mu_{\alpha_3}\p_x\big)(u_{\alpha_1}+u_{\alpha_2}+u_{\alpha_3}) 
    \end{pmatrix} 
,\end{split}
%\label{Poisson_untangled}
\end{align*}
where $\p_x$ denotes partial derivative along the real line, $\mathbb{R}$ and boundary conditions are chosen so that $\lim_{|x|\to\infty}u_{\alpha_k}(x,t)=0$ for $k=1,2,3$.
The untangled equations arise from a diagonal Poisson bracket $\{f,h\}=\langle\mu,[df,dh]\rangle$ on the dual of the following direct product Lie algebra
%\begin{align*}
$\mathfrak{s}_{diag} = \mathfrak{g}_{\alpha_1}\ \otimes  \mathfrak{g}_{\alpha_2}\ \otimes\ \mathfrak{g}_{\alpha_3} $.
%\end{align*}

Untangled equations for momentum differences is typical of Lagrangian reduction by stages 
based on the composition of Lie group actions \cite{holm1998euler}.
%
Consequently, the sum of velocities of larger scales transports the pairwise differences of momentum densities of the smaller scales, 
\begin{equation}
\p_t \mu_{\alpha_k} + {\rm ad}^*_{\sum_{j=1}^k\! u_{\alpha_j} }\mu_{\alpha_k}   = 0
\,.
\label{1D-mom-transport}
\end{equation}

