\subsection{Probability-Raising Causality}
For convenience, we use linear temporal logic (LTL)-like notations such as $\neg$ (negation), $\land$ (and),  $\Diamond$ (eventually), and $\mathrm{U}$ (until) to represent some path properties. For any $X_0, X_1 \subseteq S$, the formula $X_0 \mathrm{U} X_1$ is satisfied by a (state) path $\rho = s_0 s_1 \ldots$ such that there exists $j \geq 0$ such that, for any $i < j$, $s_i \in X_0$ and $s_j \in X_1$ hold, and we denote $\Diamond X_1 = S \mathrm{U} X_1$. Furthermore, $\neg \Diamond X_1$ is satisfied by a path $\rho$ such that all states in $\rho$ are not contained by $X_1$.
% and $\Diamond T \land \neg \Diamond T'$ is satisfied by a path $\rho = s_0 s_1 \ldots$ such that there exists $s_i \in T$ but all states in $\rho$ are not contained by $T'$.
For simplicity, we abbreviate $\{s_0\} \mathrm{U} \{ s_1\}$ and $\Diamond \{s_2\}$ as $s_0 \mathrm{U} s_1$ and $\Diamond s_2$, respectively, for any $s_0, s_1, $ and $s_2 \in S$.

We consider a cause-effect relation over an MDP based on the probability-raising principle introduced in \citep{baier2022probability, baier2024foundations}.
\begin{definition}[SPR cause \citep{baier2022probability}]
\label{def:SPR_cause}
    For any MDP $\mathcal{M}_u$ with a parameter $u \in \mathcal{V}$, the set of terminal states $E \subseteq S$, and a subset $C \subseteq S \setminus E$, we say that $C$ is a strict probability-raising (SPR) cause for $E$ on $\mathcal{M}_u$ if and only if the following conditions (M) and (S) hold:
    \begin{description}
        \item[(M)] $\forall c \in C, \exists \pi$ such that $\mathrm{Pr}_{\mathcal{M}_u}^\pi(\neg C \mathrm{U} c) > 0$.
        \item[(S)] $\forall c \in C, \forall \pi \mbox{ where } \mathrm{Pr}_{\mathcal{M}_u}^\pi (\neg C \mathrm{U} c) > 0$,
        \begin{align}
        \mathrm{Pr}_{\mathcal{M}_u}^\pi(\Diamond E \;|\; \neg C \mathrm{U} c) > \mathrm{Pr}_{\mathcal{M}_u}^\pi(\Diamond E).
        \end{align}
    \end{description}
\end{definition}
Intuitively, $\Diamond E$ means that a path eventually reaches a state in $E$, and $\neg C \mathrm{U} c$ denotes that a path eventually reaches $c$ avoiding others in $C$.
SPR cause is a minimal subset $C$ of states and is interpreted as waypoints that raise the probability of reaching terminal states $E$. This probability-raising condition is defined by $\textbf{(S)}$, implying that visiting any state in $C$ increases the probability of reaching $E$. The minimality of the subset is defined by $\textbf{(M)}$, removing states in $C$ that can only be reached by passing through the others.
% The condition \textbf{(M)} can be viewed as a minimality requirement for a set of states $C$ to omit any state that is not reachable from the initial state without going through others in $C$. 
We denote that $C$ satisfies the above conditions \textbf{(M)} and \textbf{(S)} on an MDP $\mathcal{M}_u$ by $(\mathcal{M}_u, C) \models \textbf{(M)}$ and $(\mathcal{M}_u, C) \models \textbf{(S)}$, respectively.
% Furthermore, we denote by $(\mathcal{M}_\mathbb{P}, C) \models \textbf{(M)}$ when $C$ satisfies the above condition \textbf{(M)} for every $\mathcal{M}_u$ with $u \in \mathcal{V}$ such that $p(u) > 0$, where $p$ is the probability density function for $\mathbb{P}$. Since $\mathcal{M}_\mathbb{P}$ is graph-preserving, for any $C \subseteq S$, we have $(\mathcal{M}_\mathbb{P}, C) \models \textbf{(M)}$ when $(\mathcal{M}_u, C)$ for some $u \in \mathcal{V}$.

In Example \ref{example1}, the set of states $C=\{s_2, s_3\}$ is an SPR cause on the MDP $\mathcal{M}_{u}$ with $p=0.3$ and $q=0.6$ for the following reasons: First, there exist two paths $s_0 a s_2$ and $s_0 b s_1 a s_3$. Hence, $C$ satisfies the condition \textbf{(M)} on $\mathcal{M}_u$. Second, the minimal probabilities over any policies $\mathrm{Pr}^\mathrm{min}_{\mathcal{M}_u}(\Diamond s_5 \;|\; \neg C \mathrm{U} s_2) = 0.6$ and $\mathrm{Pr}^\mathrm{min}_{\mathcal{M}_u}(\Diamond s_5 \;|\; \neg C \mathrm{U} s_3) = 1$ are greater than the maximal probability $\mathrm{Pr}^\mathrm{max}_{\mathcal{M}_u}(\Diamond s_3) = 0.48$. Thus, $C$ satisfies \textbf{(S)} on $\mathcal{M}$.

In the following, we do not mention the set of terminal states $E$ for any upMDP when it is clear from the context.
\begin{definition}[SPR-cause probability]
    For any upMDP $\mathcal{M}_\mathbb{P}$ and any $C \subset S$, we define the probability that $C$ is an SPR cause on $\mathcal{M}_\mathbb{P}$ as:
\begin{align}
\label{cause_prob}
    F(\mathcal{M}_\mathbb{P}, C) = \int_{u \in \mathcal{V}} I(u, C) \mathrm{d} \mathbb{P}(u),
\end{align}
where $I: \mathcal{V} \times 2^S \to \{ 0, 1 \}$ is an indicator function such that, for any $u \in \mathcal{V}$ and any $C \subset S$, $I(u, C) = 1$ if $C$ is an SPR cause on $\mathcal{M}_u$ and otherwise $0$. We call the probability defined by (\ref{cause_prob}) the \textit{SPR-cause probability} for $C$.
\end{definition}

% 直感的な/要約的な(?) 定義の振り返り．
% cause自体の最適性を考えたいというモチベーションを書く．その後に，「既存研究の～～という定義を採用する，さらにそれをupMDPに拡張する」のように導入していく．
To evaluate how often an SPR cause covers paths reaching $E$ on the upMDP, we consider the probability of paths passing through an SPR cause $C$ conditioned on reaching $E$ as a probabilistic coverage of SPR causes.
% Moreover, assessing the coverage by ignoring some rare SPR causes is useful since such SPR causes can be seen as outliers for $\mathbb{P}$. 
\begin{definition}[Recall]
    For any MDP $\mathcal{M}_u$, any policy $\pi$, and any $C \subseteq S$, we introduce the conditional probability called recall for $C$ under $\pi$ as
\begin{align}
\label{def:recall}
    \mathrm{Pr}_{\mathcal{M}_u}^\pi (\Diamond C \;|\; \Diamond E),
\end{align}
and $\mathrm{Pr}^\pi_{\mathcal{M}_u}(\Diamond C \;|\; \Diamond E) = 0$ if $\mathrm{Pr}^\pi_{\mathcal{M}_u}(\Diamond E) = 0$.
\end{definition}
% Intuitively, the probability defined as (\ref{def:recall}) is the probability that the paths reaching $E$ go through $C$.
\begin{definition}[Recall optimality]
\label{def:recall_optimality}
    For any MDP $\mathcal{M}_u$, any $C \subseteq S$, and any $\mathcal{S} \subseteq 2^S$, we say that $C$ is recall-optimal on $\mathcal{M}_u$ over $\mathcal{S}$ if and only if $C$ is an SPR cause and satisfies
    \begin{align}
    \label{PR-recall_optimal}
        & \forall C' \in \mathcal{S}, C' \mbox{ is an SPR cause on $\mathcal{M}_u$} \nonumber \\
        & \implies \min_{\pi} \mathrm{Pr}_{\mathcal{M}_u}^\pi (\Diamond C | \Diamond E) - \mathrm{Pr}_{\mathcal{M}_u}^\pi (\Diamond C' | \Diamond E) \!\geq\! 0,
    \end{align}
\end{definition}
Intuitively, when the conditional probability of passing through $C$ before making undesired paths is maximal among all SPR causes, $C$ is recall optimal.
\begin{definition}[Recall-optimal probability]
\label{def:recall_optimal_probability}
    For any MDP $\mathcal{M}_u$ and any $\mathcal{C}, \mathcal{S} \in 2^S$, we define the probability that $\mathcal{C} \subseteq 2^S$ covers recall-optimal SPR causes over $\mathcal{S} \subseteq 2^S$ under $\mathcal{M}_\mathbb{P}$ as:
    \begin{align}
    \label{recall_opt_prob}
        R(\mathcal{M}_\mathbb{P}, \mathcal{C}, \mathcal{S}) = \int_{u \in \mathcal{V}} I'(u, \mathcal{C}, \mathcal{S}) \mathrm{d} \mathbb{P}(u),
    \end{align}
    where $I': \mathcal{V} \times 2^{2^S} \times 2^{2^S} \to \{ 0, 1 \}$ is an indicator function such that, for any $u \in \mathcal{V}$, any $\mathcal{C} \subseteq 2^S$, and any $\mathcal{S} \subseteq 2^S$, $I'(u, \mathcal{C}, \mathcal{S}) = 1$ if there exists $C \in \mathcal{C}$ such that $C$ is recall-optimal over $\mathcal{S}$ under $\mathcal{M}_u$ and otherwise $0$. We call the probability defined by (\ref{recall_opt_prob}) the \textit{recall-optimal probability} for $\mathcal{C}$ over $\mathcal{S}$.
\end{definition}
Recall optimal probability is interpreted as the probability over the parameter space of a upMDP that a given collection of subsets of states contains a recall optimal SPR cause.
% That is, the probability that the collection has an SPR cause $C$ to achieve the maximal conditional probability of passing through $C$ before reaching terminal states.

Moreover, we define a collection of subsets of states whose SPR-cause probabilities exceed $\delta > 0$ as 
\begin{align}
\label{S_delta}
    \mathcal{S}_\delta = \{ C \subset S \;|\; F(\mathcal{M}_\mathbb{P}, C) > \delta \}.
\end{align}
% In the following, we mainly treat $\mathcal{S}$ in Defs. \ref{def:recall_optimality} and \ref{def:recall_optimal_probability} as $\mathcal{S}_\delta$.

%% Problem Setting
\section{Problem Setting}

% The goal of this paper is to find a nonredundant but exhaustive collection of subsets of states $\mathcal{C}^*$ such that $\mathcal{C}^*$ maximizes the recall-optimal probability while the SPR-cause probability for each $C \in \mathcal{C}^*$ exceeds a certain threshold on the given upMDP. Formally, we consider the following problem.
Our goal is to find a nonredundant but exhaustive collection of potential SPR causes $\mathcal{C}^* \subset 2^S$ on the given upMDP. To reflect this intuition, we consider the following problem.
\begin{problem}
\label{problem:exact}
    For any $\delta$, compute $\mathcal{C}^* \subset 2^S$ that satisfies the following two conditions:
    \begin{description}
        \item[(C1)] $\mathcal{C}^* \in \argmax_{\mathcal{C} \subseteq \mathcal{S}_\delta} R(\mathcal{M}_\mathbb{P}, \mathcal{C}, \mathcal{S}_\delta)$, 
        \item[(C2)] $\forall \mathcal{C}' \subset \mathcal{C}^*, R(\mathcal{M}_\mathbb{P}, \mathcal{C}^*, \mathcal{S}_\delta) > R(\mathcal{M}_\mathbb{P}, \mathcal{C}', \mathcal{S}_\delta)$,
    \end{description}
    where $\mathcal{S}_\delta$ is defined by (\ref{S_delta}).
\end{problem}
In Problem \ref{problem:exact}, \textbf{(C1)} and \textbf{(C2)} state an exhaustiveness and a nonredundancy conditions for $\mathcal{C}^*$, respectively, for the recall-optimal probability.
Intuitively, \textbf{(C1)} requires that $\mathcal{C}^*$ maximally covers the paths reaching some terminal states in a probabilistic sense while the SPR-cause probability for each $C \in \mathcal{C}^*$ exceeds a given threshold $\delta$. The maximality of recall-optimal probability corresponds to exhaustiveness, and the threshold for the SPR-cause probability reflects our intuition for potential causes. Plus, \textbf{(C2)} requires that the collection $\mathcal{C}^*$ is nonredundant in the sense that removing any member of $\mathcal{C}^*$ reduces the recall-optimal probability.
We can analyticaly compute $F$ defined by (\ref{cause_prob}) and $R$ defined by (\ref{recall_opt_prob}) if $\mathcal{V}$ is finite and $\mathbb{P}$ is known.
However, in practice, $\mathcal{V}$ can be infinite, and $\mathbb{P}$ can be unknown. Hence, it is generally undecidable to compute the probabilities \citep{arming2018parameter}. Thus, we relax Problem \ref{problem:exact} by a probably approximately correct (PAC) style formulation. We consider the following two problems, assuming we can sample parameters identically and independently distributed from $\mathbb{P}$.
\begin{problem}
\label{problem:PACbound}
    For any $C \subset S$, any $\mathcal{C}, \mathcal{S} \subset 2^S$, any $N > 0$, and any $\beta \in (0,1)$, compute $\eta_N(C, \beta)$ and $\zeta_N(\mathcal{C}, \mathcal{S}, \beta)$  that satisfy the following conditions:
    \begin{align}
    \label{problem:eta}
        &\mathbb{P}^N( F(\mathcal{M}_\mathbb{P}, C) \geq \eta_N(C, \beta) ) \geq \beta, \\
    \label{problem:zeta}
        &\mathbb{P}^N( R(\mathcal{M}_\mathbb{P}, \mathcal{C}, \mathcal{S}) \geq \zeta_N(\mathcal{C}, \mathcal{S}, \beta) ) \geq \beta,
    \end{align}
    where $\mathbb{P}^N$ is the $N$ product measure of $\mathbb{P}$.
\end{problem}
\begin{problem}
\label{problem:PACoptimal_diff}
    For any $N > 0$ and any $\delta, \beta \in (0,1)$, compute $\mathcal{C}^* \subset 2^S$ that satisfies the following two conditions:
    \begin{description}
        \item[(PC1)] $\mathcal{C}^* \in \argmax_{\mathcal{C} \subseteq \mathcal{S}_{N, \delta, \beta}} \zeta_N(\mathcal{C}, \mathcal{S}_{N, \delta, \beta}, \beta)$, 
        \item[(PC2)] $\forall \mathcal{C}' \subset \mathcal{C}^*$, \\ $\mathbb{P}^N(  R(\mathcal{M}_\mathbb{P}, \mathcal{C}^*, \mathcal{S}_{N, \delta, \beta}) > R(\mathcal{M}_\mathbb{P}, \mathcal{C}', \mathcal{S}_{N, \delta, \beta}) ) > \beta$,
    \end{description}
    where both $\eta_N$ and $\zeta_N$ are the solutions to Problem \ref{problem:PACbound}, and $\mathcal{S}_{N, \delta, \beta}$ is defined as \begin{align}
    \label{S_delta_beta}
        \mathcal{S}_{N, \delta, \beta} = \{ C \subset 2^S \;|\; \eta_N(C, \beta) > \delta \}.
    \end{align}
\end{problem}
In Problem \ref{problem:PACbound}, we compute probabilistically guaranteed lower bounds for the SPR-cause probability and recall-optimal probability. Problem \ref{problem:PACoptimal_diff} relaxes Problem \ref{problem:exact} based on the PAC bounds.

