In the following, we denote by $\mathcal{U}_N = (u_i)_{i=1}^N$ the sequence of $N$ parameter vectors sampled from the parameter space $\mathcal{V}$ of the upMDP $\mathcal{M}_\mathbb{P}$.

\subsection{PAC Guarantees for Probability-Raising Causes on Uncertain Parametric MDPs}
\label{subsection:ProbGuarantee}

In this section, we provide a solution to Problem \ref{problem:PACbound}.
We first give a lower bound of the SPR-cause probability for any subset of states $C \subseteq S \setminus E$ as a solution to (\ref{problem:eta}).
For any $u \in \mathcal{V}$ and any $S' \subseteq S$, we define $\mathscr{C}_{S',u} \subset S$ as 
\begin{align}
    \label{all_cause_states}
    \mathscr{C}_{S',u} = \{ c \in S' \;|\; (\mathcal{M}_u, \{c\}) \models \textbf{(S)} \},
\end{align}
where \textbf{(S)} is defined in Def. \ref{def:SPR_cause}.
For any $C \subseteq S$, we define $n(C, \mathcal{U}_N)$ as the number of samples $u \in \mathcal{U}_N$ that satisfy the following condition:
\begin{align}
\label{n_count}
    C \subseteq \mathscr{C}_{S,u}, (\mathcal{M}_u, C) \models \textbf{(M)}.
\end{align}
Note that $n(C, \mathcal{U}_N)$ is regarded as the number of times that each $c \in C$ is an SPR cause on $\mathcal{M}_u$ and $C$ satisfies the condition \textbf{(M)} of SPR cause in Def. \ref{def:SPR_cause}.
Then, we define the function $\eta_N : 2^S \times (0,1) \to \mathbb{R}$ as
\begin{align}
\label{eta}
    \eta_N(C, \beta) = t^*(N - n(C, \mathcal{U}_N), \beta),
\end{align}
where the function $t^* : [N] \times [0,1] \to \mathbb{R}$ is defined such that, for any $\beta$, 
\begin{align}
\label{t_star_maxmin}
    t^*(0, \beta) = (1 - \beta)^{1/N}, \ t^*(N, \beta)=0,
\end{align}and, for any $k = 1, \ldots, N-1$, $t^*(k, \beta)$ is the solution of
\begin{align}
\label{t_star}
    \frac{1 - \beta}{N} = \sum_{i=0}^k \binom{N}{i} (1 - t)^i t^{N-i}.
\end{align}

\begin{theorem}
\label{thm_certif}
    For any upMDP $\mathcal{M}_\mathbb{P}$, any $N>0$, any $C \subseteq S \setminus E$, and any $\beta \in (0, 1]$, we have
    \begin{align}
        \mathbb{P}^N \{ F(\mathcal{M}_\mathbb{P}, C) \geq \eta_N(C, \beta) \} \geq \beta,
    \end{align}
    where $\eta_N$ is defined as (\ref{eta}).
\end{theorem}
By Theorem \ref{thm_certif}, $\eta_N$ defined as (\ref{eta}) is a solution to (\ref{problem:eta}).

We provide the lower bound of the recall-optimal probability of any collection of subsets of states as a solution to (\ref{problem:zeta}).
For any $u \in \mathcal{V}$ and any $S' \subset S$, we define a canonical SPR cause $C^*_{S',u}$ for $S'$ as
\begin{align}
\label{canonical_cause}
    C^*_{S',u} \! =\! \{ c \in \mathscr{C}_{S',u} | \exists \pi \mbox{ s.t. } \mathrm{Pr}_{\mathcal{M}_u}^\pi(\neg \mathscr{C}_{S',u} \mathrm{U} c) > 0 \},
\end{align}
Intuitively, $C^*_{S',u}$ is interpreted as the ``front" of all singleton SPR causes over $S'$.
For any $\mathcal{C}, \mathcal{S} \subseteq 2^{S}$, we define $m(\mathcal{C}, \mathcal{S}, \mathcal{U}_N )$ as the number of samples $u \in \mathcal{U}_N$ such that there exists $C \in \mathcal{C}$ that satisfies the following three conditions: (i) $C$ covers all path reaching $E$ that passes through $C^*_{S',u}$ for the union $S'$ of $\mathcal{S}$, (ii) $C$ is a subset of $\mathscr{C}_{S',u}$, and (iii) $C$ satisfies \textbf{(M)} in Def. \ref{def:SPR_cause}, that is,
\begin{align}
\label{m_count}
    \exists C \in \mathcal{C}& \mbox{ s.t. } C \subseteq \mathscr{C}_{S',u}, (\mathcal{M}_u, C) \models \textbf{(M)}, \nonumber \\
    & \forall \rho \in \mathrm{FinPath}, \rho \models \Diamond C^*_{S',u} \land \Diamond E \implies \Diamond C,
\end{align}
where $\rho \models \varphi$ denotes that the path $\rho$ on an MDP $\mathcal{M}_u$ satisfies the formula $\varphi$ and $S' = \cup_{C' \in \mathcal{S}} C'$.
We define the function $\zeta_N : 2^{2^S} \times 2^{2^S} \times (0,1) \to \mathbb{R}$ as
\begin{align}
\label{zeta}
    \zeta_N(\mathcal{C}, \mathcal{S}, \beta) = t^*(N - m(\mathcal{C}, \mathcal{S}, \mathcal{U}_N), \beta),
\end{align}
where $t^*$ is defined as (\ref{t_star}).

\begin{theorem}
\label{thm_optimality}
    For any upMDP $\mathcal{M}_\mathbb{P}$, any $N>0$, any $\mathcal{C}, \mathcal{S} \subseteq 2^{S}$, and any $\beta \in (0,1]$, we have
        \begin{align}
        \label{PR-recall_optimality_bound}
            &\mathbb{P}^N \{ R(\mathcal{M}_\mathbb{P}, \mathcal{C}, \mathcal{S}) \geq \zeta_N(\mathcal{C}, \mathcal{S}, \beta) \} \geq \beta,
        \end{align}
        where $\zeta_N$ is defined as (\ref{zeta}).
\end{theorem}
By Theorem \ref{thm_optimality}, $\zeta_N$ defined by (\ref{zeta}) is a solution to (\ref{problem:zeta}).

\begin{remark}[On Lower Bounds in Theorems \ref{thm_certif} and \ref{thm_optimality}]
    The right-hand side of (\ref{t_star}) is the cumulative distribution function of the binary distribution for $k$ with the success probability $1 - t$. Clearly, the maximum and minimum values of $t^*$ defined by (\ref{t_star_maxmin}) and (\ref{t_star}) are $(1-\beta)^{1/N}$ and $0$.
    Thus, the values of $\eta_N(C, \beta)$ and $\zeta_N(\mathcal{C}, \mathcal{S}, \beta)$ defined by (\ref{eta}) and (\ref{zeta}), respectively, are strictly decreasing for $\beta$, and they converge to $0$ as $\beta$ goes to $1$. Moreover, $t^*$ is strictly decreasing for $k$. Hence, $\eta_N(C, \beta)$ and $\zeta_N(\mathcal{C}, \mathcal{S}, \beta)$ are strictly increasing for $n(C, \mathcal{U}_N)$ and $m(\mathcal{C}, \mathcal{S}, \mathcal{U}_N)$, respectively, and they converge to $(1 - \beta)^{1/N}$ when $n(C, \mathcal{U}_N)$ and $m(\mathcal{C}, \mathcal{S}, \mathcal{U}_N)$ go to $N$. Please see Section 5.4 in \citep{badings2022scenario} for a more detailed discussion about the behavior of $t^*$.
\end{remark}

\begin{remark}[Proof idea for Theorems \ref{thm_certif} and \ref{thm_optimality}]
Our probabilistic lower bounds for SPR-cause and recall-optimal probabilities are based on optimization formulations known as \textit{scenario optimization programs} (SOPs) \citep{campi2008exact, campi2011sampling}. We consider two SOPs whose
constraints require that a given set of states $C \subseteq S$ is an SPR cause, and a given collection of sets of states $\mathcal{C} \subseteq 2^S$ contains a recall-optimal SPR cause, respectively, in some sampled MDPs. Please see Appendices \ref{appendix:scenario} and \ref{Appendix_thm12} for details.
\end{remark}

\subsection{PAC-Guaranteed Recall-Optimal Probability-Raising Causes on Uncertain Parametric MDPs}
\label{subsection:Estimation}

In this section, we provide the solution to Problem \ref{problem:PACoptimal_diff}.
For any $\beta, \delta \in (0,1)$ and any $N>0$, we define the collection $\mathcal{C}^*$ of subsets of states as
\begin{align}
\label{C_star}
    \mathcal{C}^* = \{ C^*_{S_N, u_i} \;|\; i \in \mathcal{I} \},
\end{align}
where $\mathcal{I}$ is a set of indices for sampled parameter vectors defined such that
\begin{align}
    \bigcup_{i \in \mathcal{I}} \mathcal{U}^i_N = \mathcal{U}_N \land \bigcup_{i \in \mathcal{I}'}\mathcal{U}^i_N \neq \mathcal{U}_N, \forall \mathcal{I}' \subset \mathcal{I},
\end{align}
$\mathcal{U}^i_N$ is defined as
\begin{align}
\label{recall_optimal_samples}
    \mathcal{U}^i_N = & \{ u_j \in \mathcal{U}_N \;|\; C^*_{S_N, u_i} \subseteq \mathscr{C}_{u_j} \nonumber \\
    & \land \forall \rho, \rho \models \Diamond C^*_{S_N, u_j} \land \Diamond E \implies \Diamond C^*_{S_N, u_i} \}
\end{align}
and $C^*_{S_N, u_i}$ is defined by (\ref{canonical_cause}) with $S_N = \cup_{C' \in \mathcal{S}_{N, \delta, \beta}} C'$.

\begin{theorem}
\label{thm_solution_certif}
    For any upMDP $\mathcal{M}_\mathbb{P}$, any $\delta, \beta \in (0,1)$, and any $N>0$, $\mathcal{C}^*$ defined by (\ref{C_star}) is a solution to Problem \ref{problem:PACoptimal_diff}.
\end{theorem}

In the following Example \ref{example1_SPR}, we show how the condition in (\ref{recall_optimal_samples}) eliminates redundant samples for the recall-optimal probability from all sampled parameters and how to construct the exhaustive solution $\mathcal{C}^*$ defined by (\ref{C_star}).
\begin{example}
    \label{example1_SPR}
    We consider solving Problem \ref{problem:PACoptimal_diff} for the upMDP in Example \ref{example3}. Let $\delta=0$ and $\beta=0.99$. We sampled $N=1000$ parameters. We obtained a solution $\mathcal{C}^* = \{ \{s_3\} \}$ with $\mathcal{S}_{N, \delta, \beta}$ $ =\{ \{s_1\}, \{s_2\}, \{s_3\}, \{s_1, s_3\}, \{s_2, s_3\} \}$, where $\{s_3\}$, $\{s_1, s_3\}$, and $\{s_2, s_3\}$ are the canonical SPR causes on the sampled $7$, $2$, and $991$ MDPs with $p = q$, $p > q$, and $p < q$, respectively. $\{s_3\}$ is a subset of $\{s_1, s_3\}$ and $\{s_2, s_3\}$, and all paths passing through $\{s_1, s_3\}$ or $\{s_2, s_3\}$ go through $\{s_3\}$. Thus, $\mathcal{U}^i_N$ defined by (\ref{recall_optimal_samples}) that corresponds to $\{s_3\}$ is equal to $\mathcal{U}_N$. According to Theorem \ref{thm_certif}, the subsets of states $\{s_1\}$, $\{s_2\}$, $\{s_3\}$, $\{s_1, s_3\}$, and $\{s_2, s_3 \}$ provide the lower bounds of SPR-cause probabilities $4.3 \times 10^{-6}$, $0.98$, $0.995$, $4.3 \times 10^{-6}$, and $0.98$ with the confidence probability $\beta=0.99$, respectively, and they exceed $\delta$. For \textbf{(PC1)}, the lower bound $\zeta_N(\mathcal{C}^*, \mathcal{S}_{N, \delta, \beta}, \beta)$ of recall-optimal probability is the maximum value $(1 - \beta)^{1/N} = 0.995$. 
    For \textbf{(PC2)}, the subset $\mathcal{C} = \emptyset \subset \mathcal{C}^*$ clearly does not contain any SPR cause for all parameters. So, $R(\mathcal{M}_\mathbb{P}, \mathcal{C}^*, S_{N, \delta, \beta}) > R(\mathcal{M}_\mathbb{P}, \mathcal{C}, S_{N, \delta, \beta})$ holds.
\end{example}
\begin{remark}[Interpretation for (\ref{C_star})]
    Intuitively, $\mathcal{U}^i_N$ defined by (\ref{recall_optimal_samples}) collects all sampled parameters $u_j$ such that $C^*_{S_N, u_i}$ for $i$-th sample $u_i$ is recall optimal on $\mathcal{M}_{u_j}$ (See Lemma \ref{lemma_recall_optimal_necessary_sufficient} in Appendix \ref{Appendix_thm3}). So, $\mathcal{C}^*$ is constructed to contain some recall-optimal SPR causes for each sampled MDP.
\end{remark}
An easier example is shown in Appendix \ref{appendix:other_example}. Further, additional discussion about the interpretability of the resulting SPR causes is provided in Appendix \ref{appendix:interpretability}.

%% Algorithm
\subsection{Causal Identification Algorithm}
\label{subsection:Algorithm}
We provide an algorithm to obtain the solution to Problem \ref{problem:PACoptimal_diff}. The overall procedure is shown in Algorithm \ref{Alg_PG_SPREst}.
In Lines from 1 to 6, we compute the canonical SPR cause $C^*_{S_N, u}$ defined as (\ref{canonical_cause}) for each sampled parameter vector, where $S_N = \cup_{C' \in \mathcal{S}_{N,\delta,\beta}}C'$, for each $\mathcal{M}_u$ with $u \in \mathcal{U}_N$ by applying Algorithm \ref{Alg_SinCheck} to all states in $S \setminus E$.
Then, in Line 8, we obtain $\mathcal{C}^*_{\mathcal{U}_N, \delta, \beta}$ defined by (\ref{C_star}) as the solution to Problem \ref{problem:PACoptimal_diff}. We compute the lower bounds of SPR-cause probabilities and recall-optimal probability through (\ref{eta}) and (\ref{zeta}). 
Note that we can check the conditions of (\ref{canonical_cause}), (\ref{m_count}), and (\ref{C_star}) using a standard graph algorithm for path finding over $\mathcal{M}_u$.
Algorithm \ref{Alg_SinCheck} is identical to Algorithm 2 in \citep{baier2022probability} and checks whether a given state $\{c \}$ is an SPR cause on a given MDP $\mathcal{M}_u$, that is, $(\mathcal{M}_u, \{c\}) \models \text{(S)}$. The computation of $\tau_u$ is sound and complete, i.e.,  $\tau_u(c) = 1$ if and only if $\{ c \}$ is an SPR cause on $\mathcal{M}_u$, by Lemma 4 in \citep{baier2022probability}. In Lines 1 and 2, we compute the minimum probability $w_c$ of reaching $E$ from $c$ on $\mathcal{M}_u$ and the maximum probability $q_s$ of reaching $E$ from any $s \in S$ on a modified MDP $\mathcal{M}_u^{[c]}$. The computation is conducted by existing model checking algorithms such as value iteration. 
The modified MDP $\mathcal{M}_u^{[c]}$ is defined by removing all actions at $c$ and adding a terminal state $\mathrm{noeff}$ that is not in $E$ and an action $\gamma$ that is enabled at $c$ with the transition probabilities $P_u(c, \gamma, \mathrm{eff}) = \mathrm{Pr}^\mathrm{min}_{\mathcal{M}_u,c}(\Diamond E)$ and $P_u(c, \gamma, \mathrm{noeff}) = 1 -\mathrm{Pr}^\mathrm{min}_{\mathcal{M}_u,c}(\Diamond E)$, where $\mathrm{eff}$ is a fixed state in $E$ and $\mathrm{Pr}^\mathrm{min}_{\mathcal{M}_u,c}(\Diamond E) = \min_{\pi} \mathrm{Pr}^\pi_{\mathcal{M}_u,c}(\Diamond E)$. $\tau_u(c)$ is calculated depending on the following 3 cases. When $w_c - q_{s_0} > 0$ and $w_c - q_{s_0} < 0$, we set $\tau_u(c) = 1$ and $-1$, respectively. In the corner case $w_c - q_{s_0} = 0$, we consider the set of actions $\mathcal{A}_{res}(s)\{ a \in A | q_s\! =\! \sum_{s' \in S^{[c]}} P_u(s,a,s') q_{s'} \}$ for any state $s$, where $S^{[c]}$ is the set of states in $\mathcal{M}^{[c]}_u$. We construct a sub-MDP $\mathcal{M}^{\mathrm{max}, [c]}_u$ of $\mathcal{M}^{[c]}_u$ induced from $\mathcal{A}_{res}$. In Lines from 8 to 12, if $c$ is reachable from $s_0$ in the sub-MDP $\mathcal{M}^{\mathrm{max},[c]}_u$, then we set $\tau_u(c) = -1$, and otherwise $\tau_u(c) = 1$.
The complexity of Algorithm \ref{Alg_PG_SPREst} is polynomial for $|S|$ and $N$ in practice. Please see Appendix \ref{appendix:complexity} for details.

\begin{algorithm}[htbp]
\caption{Probabilistically Guaranteed Recall-Optimal SPR Cause Identification for upMDP}
\begin{algorithmic}[1] 
\label{Alg_PG_SPREst}
\REQUIRE upMDP $\mathcal{M}_\mathbb{P}$, $N > 0$, $\delta \geq 0$, and $\beta \in [0,1]$.
\ENSURE $\mathcal{C}^*$, $\eta_N$, and $\zeta_N$.
\STATE Sample $N$ parameters $\mathcal{U}_N$ from $\mathcal{V}$ according to $\mathbb{P}$.
\FOR{each $u \in \mathcal{U}_N$}
\FOR{each $c \in S \setminus E$}
\STATE $\tau_u(c) \gets$ Algorithm\ref{Alg_SinCheck}($\mathcal{M}_u, c)$.
\ENDFOR
\STATE Compute $\mathscr{C}_{S_N, u}$ as $\mathscr{C}_{S_N, u} \! =\! \{ c \in S | \tau_u(c) = 1 \}$ and $C^*_{S_N,u}$ defined by (\ref{canonical_cause}), where $S_N = \cup_{C' \in \mathcal{S}_{N,\delta,\beta}} C'$.
\ENDFOR
\STATE Initialize $\mathcal{I} = \emptyset$.
\WHILE{$\bigcup_{i \in \mathcal{I}} \mathcal{U}^i_N \neq \mathcal{U}_N$.}
\STATE $\mathcal{I} \gets \mathcal{I} \cup\{i\}$ such that $\mathcal{U}^i_N \setminus \bigcup_{j \in \mathcal{I}} \mathcal{U}^j_N \neq \emptyset$.
\ENDWHILE
\STATE Compute $\mathcal{C}^*$ from $\mathcal{I}$.
\STATE Compute $\eta_N$ and $\zeta_N$ for $\mathcal{C}^*$ and $\mathcal{S}_{N, \delta, \beta}$ using Theorems \ref{thm_certif} and \ref{thm_optimality}.
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[htbp]
\caption{SPR Cause Checking for Single State}
\begin{algorithmic}[1] 
\label{Alg_SinCheck}
\REQUIRE MDP $\mathcal{M}_u$, $c \in S$.
\ENSURE $\tau_u(c) \in \{-1, 1\}$.
\STATE Compute $w_c = \min_\pi \mathrm{Pr}^{\pi}_{\mathcal{M}_u, c}(\Diamond E)$.
\STATE Compute $q_{s} = \max_\pi \mathrm{Pr}^{\pi}_{\mathcal{M}^{[c]}_u, s}(\Diamond E)$ for each $s \in S$.
\IF{ $w_c - q_{s_0} > 0$ }
\STATE $\tau_u(c) = 1$
\ELSIF{$w_c - q_{s_0} < 0$}
\STATE $\tau_u(c) = -1$.
\ELSIF{$w_c - q_{s_0} = 0$}
\IF{ c is reachable from $s_0$ in $\mathcal{M}^{\mathrm{max},[c]}_u$}
\STATE $\tau_u(c) = -1$.
\ELSE
\STATE $\tau_u(c) = 1$.
\ENDIF
\ENDIF
\end{algorithmic}
\end{algorithm}

\section{Example}
\subsection{Setup}
We demonstrate that the proposed method exhaustively and nonredundantly finds SPR-causes on a $10 \times 10$ grid world with $3$ obstacles, where the robot behaves as depicted in Figs. \ref{ex:env1} and \ref{ex:env2}. The undesired behavior is reaching the terminal red cells. The blue arrows represent the enabled actions for each set of cells surrounded by the green dashed line. 
The actions the robot can take are $\mathrm{Up}, \mathrm{Right}, \mathrm{Down}, \mathrm{Left}, \mbox{ and } \mathrm{Stay}$. 
In Fig. \ref{ex:env1}, the cells $\{(4, i) \}_{i=6,7,8}$ is the one-way aisle where the robot is allowed to choose to go up. On the other hand, in Fig. \ref{ex:env2}, the robot can choose to move up and down the aisle. 
The robot transits in the intended direction with probability $p_0$ and moves perpendicularly with probability $(1 - p_0)/2$. The robot always stays in the same cell when it chooses $\mathrm{Stay}$ or is about to collide with the obstacles or go outside. The robot enters the red cell with probability $p_1$ (resp., $p_2$) regardless of the selected action when it is in the cell $(9, 5)$ (resp., $(8, 9)$) and moves in the intended way with the remaining probability. The robot moves carefully in the intended direction with probability 1 in the cells adjacent to the red cells, other than $(9, 5)$ and $(8, 9)$. 
We set the probability distributions followed by $p_0$, $p_1$, and $p_2$ as the uniform distributions over the intervals $[0.85, 0.9]$, $[0.45, 0.6]$, and $[0.5, 0.7]$. We sampled $N=100$ parameter vectors from the parameter space. We conducted the experiments $10$ times for each environment with $\beta= \beta_0 (=0.9), \beta_1(=0.99)$ and $\delta=\delta_0(=0.001), \delta_1(=0.1)$. We implemented Algorithm \ref{Alg_SinCheck} based on value iteration to compute $w_c$ and $q_s$ and to check some path conditions. We computed ${\eta}_N$ and ${\zeta}_N$ defined in (\ref{eta}) and (\ref{zeta}), respectively, using bi-section search.

SPR causes are cells whose traversal increases the probability of reaching red cells.
All true SPR causes when $p_1 < p_2$ and $p_1 > p_2$ are shown as the yellow and orange/green cells, respectively. This is because crossing the yellow cells leads to entering the red cells by going through the top side when $p_1 < p_2$. Likewise, passing through the orange/green cells causes entry into the red cells from below when $p_1 > p_2$.
Our method identifies and consolidates them through model checking for sampled MDPs and set covering.
A detailed explanation for SPR causes in Example is described in Appendix \ref{appendix:explain_example_sec}.

We compared our proposed method with two na\"ive approaches: $\mathrm{NA1}$ and $\mathrm{NA2}$. $\mathrm{NA1}$ computes the canonical SPR cause $C^*_{S,u}$ defined by (\ref{canonical_cause}) based on Algorithm 2 in \citep{baier2022probability} for the mean parameters. $\mathrm{NA2}$ collects the canonical SPR causes $C^*_{S,u}$ for 8 parameter vectors corresponding to the vertices of the parameter region.

