\section{Derivation of Main Theorems}
\subsection{Scenario Optimization}
\label{appendix:scenario}
In this section, we briefly review the scenario optimization programs (SOPs) \citep{campi2008exact, campi2011sampling}, and how the obtained solutions are guaranteed with PAC bounds. We consider a family of constraints $K^u \subseteq \mathbb{R}^d$ with a natural number $d$ parameterized by $u \in \mathcal{V}$, where $\mathcal{V}$ is an uncountable (and possibly continuous) parameter space, and $K^u$ is convex and closed for each $u$. We assume that $\mathcal{V}$ is endowed with a $\sigma$-algebra $\mathcal{B}(\mathcal{V})$ and a probability measure $\mathbb{P}$. Suppose that $N$ i.i.d. samples sequence $\mathcal{U}_N = (u_i)_{i=1,\ldots,N}$ are available.

For any $\mathcal{U}'_N \subseteq \mathcal{U}_N$, we consider the following optimization program called SOP:
\begin{align}
\label{SOP_template}
    \max_{\gamma} \quad &\gamma \nonumber \\
    \mathrm{s. t.} \quad & \gamma \in  \bigcap_{u \in \mathcal{U}'_{N}} K^u,
\end{align}
We introduce the following assumptions.
\begin{assumption}[Assumption 2.1 in \citep{campi2011sampling}]
\label{assum:exist_unique}
    Every optimization problem subject to a finite set $F \subset \mathcal{V}$, i.e., 
    \begin{align}
    \label{finite_SOP}
        \max_{\gamma} \quad &\gamma \nonumber \\
    \mathrm{s. t.} \quad & \gamma \in  \bigcap_{u \in F} K^u,
    \end{align}
    is feasible, and its feasibility domain has a nonempty interior. Moreover, the solution of (\ref{finite_SOP}) exists and is unique.
\end{assumption}
\begin{assumption}[Assumption 2.2 in \citep{campi2011sampling}]
    \label{assum:violates}
    Almost surely with respect to multi-sample $\mathcal{U}_N$, the solution $\gamma^*$ of the optimization program in (\ref{SOP_template}) violates constraints for all $u \in \mathcal{U}_N \setminus \mathcal{U}'_N$.
\end{assumption}


Then, we have the following arguments.
\begin{theorem}[Theorem 1 in \citep{campi2008exact}]
    \label{thm_scenario_exact}
    Under Assumption \ref{assum:exist_unique}, if $|\mathcal{U}'_N| = 0$, then we have
    \begin{align}
        \mathbb{P}^N \left\{ \mathbb{P}(\gamma^* \not \in K^u) > \varepsilon \right\} < \sum_{i=0}^{d-1} \varepsilon^i (1 - \varepsilon)^{N - i},
    \end{align}
    where $\gamma^*$ is the solution to (\ref{SOP_template}).
\end{theorem}

\begin{theorem}[Theorem 2.1 in \citep{campi2011sampling}]
    \label{thm_scenario_discarding}
    Under Assumptions \ref{assum:exist_unique} and \ref{assum:violates}, we have that
    \begin{align}
        \mathbb{P}^N \left\{ \mathbb{P}(\gamma^* \not \in K^u) > \varepsilon \right\} < \binom{k + d -1}{k}\sum_{i=0}^{k+d-1} \varepsilon^i (1 - \varepsilon)^{N - i},
    \end{align}
    where $\gamma^*$ is the solution to (\ref{SOP_template}).
\end{theorem}

\subsection{Derivation of Theorems \ref{thm_certif} and \ref{thm_optimality}}
\label{Appendix_thm12}
In this section, we prove Theorems \ref{thm_certif} and \ref{thm_optimality} based on scenario optimization program (SOP) formulations.
We first review the following lemma to show the necessary and sufficient condition of SPR causes.
\begin{lemma}[Lemma 21 in \citep{baier2022probability}]
    \label{lemma_SPR_cause_necessary_sufficient}
    For any pMDP $\mathcal{M}_u$, any $C \subset S$, and any $u_j \in \mathcal{V}$, $C$ is an SPR cause on $\mathcal{M}_{u_j}$ if and only if $C \subseteq \mathscr{C}_{S, u_j}$ and $C$ satisfies \textbf{(M)} in Def.\ref{def:SPR_cause}, where $\mathscr{C}_{S, u_j}$ is defined by (\ref{all_cause_states}).
\end{lemma}

For any MDP $\mathcal{M}_u$ and any $C \subset S$, we define $\gamma^u_C$ as 
\begin{align}
    \gamma^u_C = 
    \begin{cases}
        1 & \mbox{ if } C \mbox{ is an SPR cause on $\mathcal{M}_u$},\\
        0 & \mbox{ otherwise},
    \end{cases}
    % \min_{c \in C} \min_{\pi} \mathrm{Pr}_{\mathcal{M}_u}^\pi (\Diamond E \;|\; \neg C \mathrm{U} c) - \mathrm{Pr}_{\mathcal{M}_u}^\pi(\Diamond E).
\end{align}
% Clearly, $\gamma^u_C > 0 $ holds if and only if $C$ is an SPR cause on $\mathcal{M}_u$.
For any $C \subseteq S$, let $K^u_C = [0, \gamma^u_C]$. For any sequence of $N$ sampled parameters $\mathcal{U}_N \in \mathcal{V}^N$, we define $\mathcal{U}^C_{N,1} = \{ u \in \mathcal{U}_N \;|\; C \subseteq \mathscr{C}_{S,u}, (\mathcal{M}_\mathbb{P}, C) \models \textbf{(M)} \}$, where we treat the same elements in $\mathcal{U}_N$ as duplicates. Then, we define $\mathcal{U}^C_{N,0} = \mathcal{U}_N \setminus \mathcal{U}^C_{N,1}$, where $\mathscr{C}_{S,u}$ is defined as (\ref{all_cause_states}).
Then, we consider the following SOP:

\begin{align}
\label{SOP_SPR_cause}
    \max_{\gamma} \quad &\gamma \nonumber \\
    \mathrm{s. t.} \quad & \gamma \in  \bigcap_{u \in \mathcal{U}'_N} K^u_C,
    & 
\end{align}
where $\mathcal{U}'_N \subseteq \mathcal{U}_N$.
% Note that the solution $\gamma^*_C = \min_{u \in \mathcal{U}^C_{N, 1}} \gamma^u_C$ of (\ref{SCP}) is positive.
Let $\gamma^*_C$ be the solution of (\ref{SOP_SPR_cause}). Note that $\gamma^*_C = \min_{u \in \mathcal{U}'_N} \gamma^u_C$.

\begin{proof}[proof of Theorem \ref{thm_certif}]
For any $C \subset S$, we consider the two cases (1) $\mathcal{U}^C_{N,0} = \emptyset$ and (2) $\mathcal{U}^C_{N,0} \neq \emptyset$.

(1): We set $\mathcal{U}'_N = \mathcal{U}^C_{N,1}$. By Lemma \ref{lemma_SPR_cause_necessary_sufficient}, for any $u \in \mathcal{U}_{N, 1}^C$, $C$ is an SPR cause on $\mathcal{M}_u$. Thus, the intersection of all $K^u_C$ with $u \in \mathcal{U}^C_{N, 1}$ is $[0,1]$ and hence there exists a unique solution $\gamma^*_C = 1$ to (\ref{SOP_SPR_cause}). Thus, for any $\varepsilon > 0$, by Theorem \ref{thm_scenario_exact}, we have
\begin{align}
    \mathbb{P}^N \left\{ \mathbb{P}(\gamma^*_C \not\in K^u_C) > \varepsilon \right\} < (1 - \varepsilon)^N,
\end{align}
and hence
\begin{align}
    \mathbb{P}^N \left\{ \mathbb{P}(\gamma^*_C \in K^u_C) \geq 1 - \varepsilon \right\} \geq 1 - (1 - \varepsilon)^N,
\end{align}
where the internal probability $\mathbb{P}$ measures the frequency of $u$ for $K^u_C$.
We choose $\beta = 1 - (1 - \varepsilon)^N$ and hence
\begin{align}
    \mathbb{P}^N \left\{ \mathbb{P}(\gamma^u_C \geq \gamma^*_C) \geq (1 - \beta)^{1/N} \right\} \geq \beta.
\end{align}
We have that $ \gamma^*_C = 1$ and thus 
\begin{align}
    \mathbb{P}^N \left\{ \mathbb{P}(\gamma^u_C = 1) \geq (1 - \beta)^{1/N} \right\} \geq \beta.
\end{align}
% Moreover, $\mathcal{M}_\mathbb{P}$ is graph-preserving and hence $(\mathcal{M}_u, C) \models \mbox{(M)}$ for all $u \in \mathcal{V}$ when $\mathcal{U}_{N, 1}^C \neq \emptyset$. 
Therefore, we have
\begin{align}
    \mathbb{P}^N \left\{ F(\mathcal{M}_\mathbb{P}, C) \geq (1- \beta)^N \right\} \geq \beta.
\end{align}

(2): For any $\mathcal{U}'_N \neq \emptyset$ in (\ref{SOP_SPR_cause}), the intersection of all $K^u_C$ with $u \in \mathcal{U}'_N$ is nonempty and there exists a unique solution $\gamma^*_C$ to (\ref{SOP_SPR_cause}). Thus, for any $\varepsilon > 0$ and any a-priori number of discarded sampled parameters $q = |\mathcal{U}_N \setminus \mathcal{U}'_N|$, by Theorem \ref{thm_scenario_discarding}, we have
\begin{align}
\label{eq_PACbound_case2}
    \mathbb{P}^N \left\{ \mathbb{P}(\gamma^*_C(q) \not\in K^u_C) \leq \varepsilon \right\} & = \mathbb{P}^N \left\{ \mathbb{P} (\gamma^*_C(q) \in K^u_C) \geq 1 - \varepsilon \right\} \nonumber \\
    & \geq 1 - \sum_{i=0}^{q} \binom{N}{i} \varepsilon^i (1 - \varepsilon)^{N-i}.
\end{align}
We set $t = 1 - \varepsilon$ and equate the right-hand side of (\ref{eq_PACbound_case2}) to $1 - (1- \beta)/N$. Then, we have
\begin{align}
\label{q_bound_for_F}
    \mathbb{P}^N \left\{ \mathbb{P} (\gamma^u_C \geq \gamma^*_C(q)) \geq t^*(q) \right\} \geq 1 - \frac{1 - \beta}{N},
\end{align}
where $t^*(q)$ is the solution of
\begin{align}
        \frac{1 - \beta}{N} = \sum_{i=0}^{q} \binom{N}{i} (1 - t)^i t^{N-i}.
\end{align}
We consider the case $q = |\mathcal{U}^C_{N,0}|$ to derive the lower bound of $F(\mathcal{M}_\mathbb{P}, C)$ for $\mathcal{U}'_N = \mathcal{U}^C_{N,1}$. Since the number $|\mathcal{U}_{N,0}^C|$ is not known before observing actual samples, we simultaneously consider the bound for all $q=1, \ldots, N-1$. By Bool's inequality and (\ref{q_bound_for_F}), we have
\begin{align}
    \mathbb{P}^N \left\{ \cap_{q=1}^{N} \mathcal{E}_q
\right\} & = 1 - \mathbb{P}^N \left\{ \cup_{q=1}^{N} \mathcal{E}_q^c \right\} \nonumber \\
         & \geq 1 - \sum_{q=1}^{N} \mathbb{P}^N \left\{ \mathcal{E}_q^c \right\} \nonumber \\
         & \geq \beta,
\end{align}
where $\mathcal{E}_q$ denotes the event $\mathbb{P} (\gamma^u_C \geq \gamma^*_C(q)) \geq t^*(q)$ and $\mathcal{E}_q^c$ is its complement event.
Clearly, we have
\begin{align}
\label{beta_bound_case2}
    \mathbb{P}^N \left\{ \mathbb{P} (\gamma^u_C \geq \gamma^*_C) \geq t^*(|\mathcal{U}^C_{N,0}|) \right\} & \geq \mathbb{P}^N \left\{ \forall q'=1,\ldots,N, \mathbb{P} (\gamma^u_C \geq \gamma^*_C) \geq t^*(q') \right\} \nonumber \\
    & \geq \beta. 
\end{align}
Note that we can take $\mathcal{U}'_N = \mathcal{U}^C_{N, 1}$ when $q = |\mathcal{U}^C_{N,0}|$. By Lemma \ref{lemma_SPR_cause_necessary_sufficient}, for any $u \in \mathcal{U}_{N, 1}^C$, $C$ is an SPR cause on $\mathcal{M}_u$. Thus, the intersection of all $K^u_C$ with $u \in \mathcal{U}^C_{N, 1}$ is $[0,1]$ and hence there exists a unique solution $\gamma^*_C = 1$ to (\ref{SOP_SPR_cause}) when $\mathcal{U}'_N = \mathcal{U}^C_{N,1}$. Thus, we have
\begin{align}
    \mathbb{P}^N \left\{ \mathbb{P} (\gamma^u_C \geq \gamma^*_C) = t^* (|\mathcal{U}^C_{N,0}|) \right\}
    & = \mathbb{P}^N \left\{ \mathbb{P} (\gamma^u_C = 1) \geq t^*(|\mathcal{U}^C_{N,0}|) \right\} \nonumber \\
    & = \mathbb{P}^N \left\{ F(\mathcal{M}_\mathbb{P}, C) \geq t^*(|\mathcal{U}^C_{N,0}|) \right\}.
\end{align}
Therefore, by (\ref{beta_bound_case2}), we have
\begin{align}
    \mathbb{P}^N \left\{ F(\mathcal{M}_\mathbb{P}, C) \geq t^*(|\mathcal{U}^C_{N,0}|) \right\} \geq \beta.
\end{align}
\end{proof}

