For any path property $\varphi$ and any path $\rho$ of an MDP, we denote $\rho \models \varphi$ if and only if $\rho$ satisfies $\varphi$. Moreover, recall that we denote all finite paths on the pMDP as $\mathrm{FinPath}$.
\begin{lemma}
\label{lemma_path_implication}
    For any MDP $\mathcal{M}_u$, any $S' \subseteq S$, any SPR cause $C'$ on $\mathcal{M}_u$ that is a subset of $S'$, we have that
    \begin{align}
    % \label{C_star_u_condition1}
        % & \rho \models \neg \Diamond C \land \Diamond E \implies \rho \models \neg \Diamond C' \land \Diamond E, \\
    \label{C_star_u_conditoin2}
        & \forall \rho \in \mathrm{FinPath}, \rho \models \Diamond C' \implies \Diamond C^*_{S',u},
    \end{align}
    where $C^*_{S',u}$ is defined by (\ref{canonical_cause}).
\end{lemma}
\begin{proof}
    Suppose that $\rho \models \neg \Diamond C^*_{S',u} \land \Diamond C'$. This implies that there exists $s \in C'$ such that $\rho \models \neg C^*_{S',u} \mathrm{U} s$. 
    By (\ref{canonical_cause}), for any $c \in \mathscr{C}_{S', u} \setminus C^*_{S', u}$ and for any $\rho \in \mathrm{FinPath}$, we have $\rho \not\models \neg \mathscr{C}_{S', u} \mathrm{U} c$. Thus, there exist $c' \in \mathscr{C}_{S', u}$ with $c' \neq c$ and a path $\rho'$ such that $\rho' \models \Diamond ( c' \land \Diamond c)$ and $\rho' \models \neg \mathscr{C}_{S', u} \mathrm{U} c'$. This implies that, for any path $\rho$, we have $\rho \not\models \neg C^*_{S', u} \mathrm{U} c$ since $C^*_{S',u}$ is constructed from (\ref{canonical_cause}). However, this contradicts the assumption.
\end{proof}

\begin{lemma}
\label{lemma_recall_inequality}
    For any MDP $\mathcal{M}_u$, any $S' \subset S$, and any SPR cause $C \subseteq S'$, $C^*_{S',u}$ is recall optimal over $\mathcal{S}$ for any $\mathcal{S} \subseteq 2^{S'}$,
    where $C^*_{S', u}$ is defined as (\ref{canonical_cause}).
\end{lemma}
\begin{proof}
    By Lemma \ref{lemma_path_implication}, for any policy $\pi$ and any SPR cause $C' \in \mathcal{S}$ on $\mathcal{M}_u$, we have that
    \begin{align}
        % & \mathrm{Pr}^\pi_{\mathcal{M}_u}(\neg \Diamond C' \land \Diamond E) \geq \mathrm{Pr}^\pi_{\mathcal{M}_u}(\neg \Diamond C \land \Diamond E), \\
        & \mathrm{Pr}^\pi_{\mathcal{M}_u}(\Diamond C' \land \Diamond E) \leq \mathrm{Pr}^\pi_{\mathcal{M}_u}(\Diamond C^*_{S',u} \land\Diamond E).
    \end{align} 
    This yields the claim.
\end{proof}

\begin{lemma}
\label{lemma_recall_sufficient}
    For any MDP $\mathcal{M}_u$, any $S' \subseteq S$, and any $C \subseteq \mathscr{C}_{S', u}$ that satisfies \textbf{(M)} in Def. \ref{def:SPR_cause}, if (\ref{recall_sufficient}) holds, then $C$ is recall-optimal on $\mathcal{M}_{u}$ over $\mathcal{S} = 2^{S'}$.
    \begin{align}
    \label{recall_sufficient}
        & \forall \rho \in \mathrm{FinPath}, \rho \models \Diamond C^*_{S', u} \land \Diamond E \implies \Diamond C,
    \end{align}
    where $\mathscr{C}_{S',u}$ is defined by (\ref{all_cause_states}), and $C^*_{S',u}$ is defined by (\ref{canonical_cause}).
\end{lemma}
\begin{proof}
    By (\ref{recall_sufficient}), we have
    \begin{align}
    \label{recall_inequality}
        \forall \pi, \mathrm{Pr}^\pi_{\mathcal{M}_{u_j}}(\Diamond C^*_{S', u_j} \;|\; \Diamond E) \leq \mathrm{Pr}^\pi_{\mathcal{M}_{u_j}}(\Diamond C \;|\; \Diamond E).
    \end{align}
    By Lemma \ref{lemma_recall_inequality}, $C^*_{S', u_j}$ is recall optimal on $\mathcal{M}_{u_j}$ over $\mathcal{S}$. Thus, by (\ref{recall_inequality}), for any SPR cause $C' \subseteq S'$, we have
    \begin{align}
        \forall \pi, \mathrm{Pr}^\pi_{\mathcal{M}_{u_j}}(\Diamond C' \;|\; \Diamond E) \leq \mathrm{Pr}^\pi_{\mathcal{M}_{u_j}}(\Diamond C^*_{S', u_j} \;|\; \Diamond E) \leq \mathrm{Pr}^\pi_{\mathcal{M}_{u_j}}(\Diamond C \;|\; \Diamond E).
    \end{align}
    By Lemma \ref{lemma_SPR_cause_necessary_sufficient}, $C$ is SPR cause on $\mathcal{M}_{u_j}$.
    Therefore, $C$ is recall optimal on $\mathcal{M}_{u_j}$ over $\mathcal{S}$.
\end{proof}

