    \begin{align}
        \mathbb{P}^N \left\{ \mathbb{P}(\xi^u_{\mathcal{C}, \mathcal{S}} \geq \xi^*_{\mathcal{C}, \mathcal{S}}) \geq (1 - \beta)^{1/N} \right\} \geq \beta.
