        & = \mathbb{P}^N \left\{ \mathbb{P} (\xi^u_{\mathcal{C}, \mathcal{S}} = 1) \geq t^*(|\mathcal{U}^{\mathcal{C}, \mathcal{S}}_{N,0}|) \right\} \nonumber \\
        & = \mathbb{P}^N \left\{ R(\mathcal{M}_\mathbb{P}, \mathcal{C}, \mathcal{S}) \geq t^*(|\mathcal{U}^{\mathcal{C}, \mathcal{S}}_{N,0}|) \right\}.
