    Therefore, by (\ref{beta_bound_case2_thm2}), we have
    \begin{align}
        \mathbb{P}^N \left\{ R(\mathcal{M}_\mathbb{P}, \mathcal{C}, \mathcal{S}) \geq t^*(|\mathcal{U}^{\mathcal{C}, \mathcal{S}}_{N,0}|) \right\} \geq \beta.
    \end{align}
\end{proof}

