\begin{lemma}
\label{lemma_recall_optimal_necessary_sufficient}
    For any pMDP $\mathcal{M}_u$, any $S' \subset S$, any $C \subseteq S'$ that satisfies \textbf{(M)} in Def. \ref{def:SPR_cause}, and any $u_j \in \mathcal{V}$, $C$ is recall-optimal on $\mathcal{M}_{u_j}$ over $\mathcal{S} = 2^{S'}$ if and only if $\varphi_\mathrm{cause}(C, \mathscr{C}_{S', u_j}) \land \varphi_\mathrm{recall}(C, C^*_{S', u_j})$ holds, where $\mathscr{C}_{S', u_j}$ is defined by (\ref{all_cause_states}) and $C^*_{S', u_j}$ is defined by (\ref{canonical_cause}). 
\end{lemma}
\begin{proof}
\begin{description}
    \item [$(\Leftarrow)$] This immediately follows from Lemma \ref{lemma_recall_sufficient}.
    \item [$(\Rightarrow)$] Suppose that $\neg \varphi_\mathrm{cause}(C, \mathscr{C}_{S', u_j}) \lor \neg \varphi_\mathrm{recall}(C, C^*_{S',u_j})$ holds. Then, we consider two cases (i) $\varphi_\mathrm{cause}(C, \mathscr{C}_{S', u_j})$ does not hold and (ii) $\varphi_\mathrm{cause}(C, \mathscr{C}_{S', u_j})$ holds but $\varphi_\mathrm{recall}(C, C^*_{S',u_j})$ does not hold.
    \begin{description}
        \item [(i)] By Lemma \ref{lemma_SPR_cause_necessary_sufficient}, $C$ is not SPR cause on $\mathcal{M}_{u_j}$, and hence $C$ is not recall optimal $\mathcal{M}_{u_j}$ over $\mathcal{S}$.
        \item [(ii)] By $\neg \varphi_\mathrm{recall}(C, C^*_{S', u_j})$, we have
        \begin{align}
        \label{path_baypass_C}
            \exists \rho \mbox{ s.t. } \rho \models \Diamond C^*_{S',u_j} \land \Diamond E \land \neg \Diamond C.
        \end{align}
        By $\varphi_\mathrm{cause}(C, \mathscr{C}_{S', u_j})$ and Lemma \ref{lemma_SPR_cause_necessary_sufficient}, $C$ is an SPR cause on $\mathcal{M}_u$, and hence, by Lemma \ref{lemma_recall_sufficient},
        \begin{align}
        \label{path_set_inclusion}
            \{ \rho \in \mathrm{FinPath} \;|\; \rho \models \Diamond C^*_{S',u_j} \land \Diamond E \} \supseteq \{ \rho \in \mathrm{FinPath} \;|\; \rho \models \Diamond C \land \Diamond E \}.
        \end{align}
        Thus, by (\ref{path_set_inclusion}) and (\ref{path_baypass_C}), we have
        \begin{align}
            \{ \rho \in \mathrm{FinPath} \;|\; \rho \models \Diamond C^*_{S',u_j} \land \Diamond E \} \supset \{ \rho \in \mathrm{FinPath} \;|\; \rho \models \Diamond C \land \Diamond E \}.
        \end{align}
        Hence, we have
        \begin{align}
            \exists \pi \mbox{ s.t. } \mathrm{Pr}^\pi_{\mathcal{M}_{u_j}}(\Diamond C^*_{S',u_j} \;|\; \Diamond E) > \mathrm{Pr}^\pi_{\mathcal{M}_{u_j}}(\Diamond C \;|\; \Diamond E).
        \end{align}
        Therefore, $C$ is not recall optimal $\mathcal{M}_{u_j}$ over $\mathcal{S}$.
    \end{description}
\end{description}
\end{proof}

\begin{lemma}
\label{lemma_recall_optimality_max}
    For any upMDP $\mathcal{M}_\mathbb{P}$, any $\delta, \beta \in [0,1]$, and any $N > 0$, $\mathcal{C}^*$ defined by (\ref{C_star}) satisfies the following two conditions:
    \begin{align}
        \label{complete_recall_optimality_Cstar}
        \forall u \in \mathcal{U}_N, \exists C \in \mathcal{C}^* \mbox{ s.t. } C \mbox{ is recall-optimal on } \mathcal{M}_u \mbox{ over } \mathcal{S}_{N, \delta, \beta},
    \end{align}
    and
    \begin{align}
    \label{bound_tightness_Cstar}
        {\zeta}_N(\mathcal{C}^*, \mathcal{S}_{N, \delta, \beta}, \beta) = (1 - \beta)^{1/N},
    \end{align}
    where $\zeta_N$ is defined as (\ref{zeta}).
\end{lemma}

\begin{proof}
By (\ref{C_star}), for any $u_j \in \mathcal{U}_N$, there exists $C_i \in \mathcal{C}^*$ such that $C_i \subseteq \cup_{C' \in \mathcal{S}_{N, \delta, \beta}} C'$, $C$ satisfies \textbf{(M)}, and $\varphi_\mathrm{cause}(C_i, \mathscr{C}_{j}) \land \varphi_\mathrm{recall}(C_i, C^*_j)$ holds. Hence, by Lemma \ref{lemma_recall_optimal_necessary_sufficient}, $C_i$ is recall-optimal on $\mathcal{M}_{u_j}$ over $\mathcal{S}_{N, \delta, \beta}$.
Thus, we have (\ref{complete_recall_optimality_Cstar}) and
\begin{align}
    m(\mathcal{C}^*, \mathcal{S}_{N,\delta,\beta}, \mathcal{U}_N) = |\mathcal{U}_N| = N,
\end{align}
where $m$ is he number of samples in $\mathcal{U}_N$ such that there exists $C \in \mathcal{C}^*$ that satisfies condition defined by(\ref{m_count}).
Therefore, since the maximum value of $t^*$ defined by (\ref{t_star}) is $t^*(0,\beta) = (1 - \beta)^{1/N}$ for any $\beta$ and any $N$, (\ref{bound_tightness_Cstar}) holds by (\ref{zeta}) and (\ref{complete_recall_optimality_Cstar}).
% 定義よりC^*はCを通ってEに行くパスを全てカバーするので，C^*もまたrecall最適なものを任意のu in U_Nに対して持つ．
\end{proof}

By Lemma \ref{lemma_recall_optimality_max}, $\mathcal{C}^*$ defined by (\ref{C_star}) achieves the condition \textbf{(PC1)} in Problem \ref{problem:PACoptimal_diff} since the maximum value of $\zeta_N$ defined in (\ref{zeta}) is $(1-\beta)^{1/N}$.
\begin{lemma}
\label{lemma_recall_optimality_diff}
    For any upMDP $\mathcal{M}_\mathbb{P}$, any $\mathcal{C}, \mathcal{S} \subseteq 2^S$, and any $\mathcal{C}' \subseteq \mathcal{C}$, we have the following equation:
    \begin{align}
        R(\mathcal{M}_\mathbb{P}, \mathcal{C}, \mathcal{S}) - R(\mathcal{M}_\mathbb{P}, \mathcal{C}', \mathcal{S}) = \int_{\mathcal{V}} \xi_{\mathrm{diff}}(u, \mathcal{C}, \mathcal{C}', \mathcal{S}) \mathrm{d}\mathbb{P}(u),
    \end{align}
    where $\xi^\mathrm{diff} : \mathcal{V} \times 2^{2^S} \times 2^{2^S} \times 2^{2^S}$ is defined as
    \begin{align}
    \label{xi_diff}
        \xi_\mathrm{diff}(u, \mathcal{C}, \mathcal{C}', \mathcal{S}) = 
         \begin{cases}
            1 & \mbox{ if } \xi^u_{\mathcal{C}, \mathcal{S}} =1 \land \xi^u_{\mathcal{C}', \mathcal{S}} = 0, \\
            0 & \mbox{ otherwise},
        \end{cases}
    \end{align}
    where $\xi^u_{\mathcal{C}, \mathcal{S}}$ is defined by (\ref{xi_u_CS}).
\end{lemma}
\begin{proof}
    \begin{align}
        R(\mathcal{M}_\mathbb{P}, \mathcal{C}, \mathcal{S}) -  R(\mathcal{M}_\mathbb{P}, \mathcal{C}', \mathcal{S})
        & = \int_{\mathcal{V}} I'(u, \mathcal{C}, \mathcal{S}) - I'(u, \mathcal{C}', \mathcal{S})\mathrm{d}\mathbb{P}(u), \\
        \intertext{and $I'(u, \mathcal{C}, \mathcal{S}) - I'(u, \mathcal{C}', \mathcal{S})$ is nonnegative for all $u \in \mathcal{V}$ since $\mathcal{C}' \subseteq \mathcal{C}$. Thus,}
        & = \int_{\mathcal{V}} \xi_{\mathrm{diff}}(u, \mathcal{C}, \mathcal{C}', \mathcal{S}) \mathrm{d}\mathbb{P}(u).
    \end{align}
\end{proof}

Based on Lemmas \ref{lemma_recall_optimality_max}, \ref{lemma_recall_optimal_necessary_sufficient}, and \ref{lemma_recall_optimality_diff}, we show that $\mathcal{C}^*$ defined by (\ref{C_star}) achieves the condition \textbf{(PC2)} in Problem \ref{problem:PACoptimal_diff}.
In the following, we abbreviate $\mathcal{S}_{N, \delta, \beta}$ as $\mathcal{S}$, for simplicity.
For any $\mathcal{C}' \subset \mathcal{C}^*$, we define the subset of sampled parameters $\mathcal{U}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}_{N, 1}$ as
\begin{align}
\label{U_C*C'Stilde_N1}
    \mathcal{U}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}_{N, 1} = \mathcal{U}^{\mathcal{C}^*, \mathcal{S}}_{N, 1} \setminus \mathcal{U}^{\mathcal{C}', \mathcal{S}}_{N, 1},
\end{align}
where $\mathcal{U}^{\mathcal{C}, \mathcal{S}}_{N, 1}$ is defined by (\ref{U_CS'_N1}). Then, we define $\mathcal{U}_{N, 0}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}$ as $\mathcal{U}_N \setminus \mathcal{U}_{N,1}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}$.
We consider the following SOP:
\begin{align}
\label{SCP_for_thm3}
    \max_{\xi}\quad & \xi \nonumber \\
    \mathrm{s. t.} \quad & \xi \in  \bigcap_{u \in \mathcal{U}'_{N}} J^u_{\mathcal{C}^*, \mathcal{C}', \mathcal{S}},
\end{align}
where ${J}^u_{\mathcal{C}^*, \mathcal{C}', \mathcal{S}} = [0, \xi_\mathrm{diff}(u, \mathcal{C}^*, \mathcal{C}', \mathcal{S})]$, $\mathcal{U}'_N \subset \mathcal{U}_N$, and $\xi_\mathrm{diff}$ and $\xi^u_{\mathcal{C}, \mathcal{S}}$ are defined by (\ref{xi_diff}) and (\ref{xi_u_CS}), respectively. We denote the solution of (\ref{SCP_for_thm3}) by $\xi^*$. Note that $\xi^* = \min_{u \in \mathcal{U}'_{N}} \xi_\mathrm{diff}(u, \mathcal{C}^*, \mathcal{C}', \mathcal{S})$. For simplicity, we denote $\xi_\mathrm{diff}(u, \mathcal{C}^*, \mathcal{C}', \mathcal{S})$ as $\xi^u_\mathrm{diff}$.
\begin{proposition}
\label{prop_certify_PC2}
    For any upMDP $\mathcal{M}_\mathbb{P}$, any $N > 0$, any $\beta \in (0,1)$, if $\mathcal{C}^* \neq \emptyset$, then, for any proper subset $\mathcal{C}' \subset \mathcal{C}^*$, we have 
    \begin{align}
    \label{recall_optimal_inequality_diff}
        \mathbb{P}^N \left\{  R(\mathcal{M}_\mathbb{P}, \mathcal{C}^*, \mathcal{S}) > R(\mathcal{M}_\mathbb{P}, \mathcal{C}', \mathcal{S}) \right\} > \beta,
    \end{align}
    where $\mathcal{C}^*$ is defined by (\ref{C_star}), and $\mathcal{S}$ is defined by (\ref{S_delta_beta}).
\end{proposition}
\begin{proof}[Proof of Proposition \ref{prop_certify_PC2}]
% Theorem2の証明の(2)と基本は同じ．全てのu in U^{C*, C', S}に対して，Lemma4からxi^u_C*の方は正の値で，Lemma5からxi^u_C'の方は負の値を取る．
For any $\mathcal{U}'_N \neq \emptyset$ in (\ref{SCP_for_thm3}), the intersection of all $J^u_{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}$ with $u \in \mathcal{U}'_N$ is nonempty and there exists a unique solution $\xi^*$ to (\ref{SCP_for_thm3}).
Thus, for any $\varepsilon > 0$ and any a-priori number of discarded sampled parameters $q = |\mathcal{U}_N \setminus \mathcal{U}'_N| < N$, by Theorem \ref{thm_scenario_discarding}, we have
    \begin{align}
    \label{eq_recall_opt_PACbound_joint}
        \mathbb{P}^N \left\{ \mathbb{P}(\xi^u_\mathrm{diff} \geq \xi^* ) \geq 1- \varepsilon
         \right\}
         \geq 1 - \sum_{i=0}^{q} \binom{N}{i} \varepsilon^i (1 - \varepsilon)^{N - i}.
        % \geq \left( 1 - \sum_{i=0}^{q} \binom{N}{i} \varepsilon^i (1 - \varepsilon)^{N - i} \right)^2.
    \end{align}
    % Since $\xi^*_0$ and $\xi^*_1$ are independently determined each other, we have
    % \begin{align}
    % \label{eq_recall_opt_PACbound_joint}
        % \mathbb{P}^N \left\{ \mathbb{P}(\xi^u_0 \geq \xi^*_0 \land \xi^u_1 \leq \xi^*_1) \geq (1- \varepsilon)^2 \right\} 
        % \geq 1 - \binom{q+1}{q} \sum_{i=0}^{q+1} \binom{N}{i} \varepsilon^i (1 - \varepsilon)^{N - i}.
        % \geq \left( 1 - \sum_{i=0}^{q} \binom{N}{i} \varepsilon^i (1 - \varepsilon)^{N - i} \right)^2.
    % \end{align}
    We set $t = 1 - \varepsilon$ and equate the right-hand side of (\ref{eq_recall_opt_PACbound_joint}) to $1 - (1- \beta)/N$, where $\beta \in (0,1)$. Then, we have
    \begin{align}
    \label{q_bound_for_relativeR}
        \mathbb{P}^N \left\{ \mathbb{P}(\xi^u_\mathrm{diff} \geq \xi^* ) \geq t^*(q) \right\} \geq 1 - \frac{1 - \beta}{N},
    \end{align} 
    where $t^*(q)$ is the solution of
    \begin{align}
    \label{t_root_solution}
        \frac{1 - \beta}{N} = \sum_{i=0}^{q} \binom{N}{i} (1-t)^i t^{N - i},
        % \beta = \left( 1 - \sum_{i=0}^{q} \binom{N}{i} (1 - t)^i t^{N-i} \right)^2,
    \end{align}
    By Bool's inequality, we have
    \begin{align}
    \label{Bool_inequality_relativeR}
        \mathbb{P}^N \left\{ \cap_{q=1}^{N} \mathcal{E}_q
    \right\} & \geq 1 - \sum_{q=1}^{N} \mathbb{P}^N \left\{ \mathcal{E}_q^c \right\} \nonumber \\
      & \geq \beta,
    \end{align}
    where $\mathcal{E}_q$ denotes the event $\mathbb{P}(\xi^u_\mathrm{diff} \geq \xi^*) \geq t(q)$ and $\mathcal{E}^c_q$ is its complement, and clearly
    \begin{align}
    \label{inequality_N_all_relativeR}
        \mathbb{P}^N \left\{ \mathcal{E}_{|\mathcal{U}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}_{N,0}|} \right\} 
        \geq \mathbb{P}^N \left\{ \cap_{q=1}^{N} \mathcal{E}_q \right\}.
    \end{align}
    Note that we can take $\mathcal{U}'_N = \mathcal{U}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}_{N,1}$ when $q = |\mathcal{U}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}_{N,0}|$, and $\mathcal{U}'_N \neq \emptyset$ by (\ref{C_star}). Then, we have $\xi^u_{\mathcal{C}^*, \mathcal{S}} = 1$ and $\xi^u_{\mathcal{C}', \mathcal{S}} = 0$ for all $u \in \mathcal{U}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}_{N,1}$ by Lemma \ref{lemma_recall_optimal_necessary_sufficient} and hence $\xi^* = 1$. Thus, by (\ref{Bool_inequality_relativeR}) and (\ref{inequality_N_all_relativeR}), we have
    \begin{align}
        \mathbb{P}^N \left\{ \mathbb{P}(\xi^u_\mathrm{diff} =  1) \geq t(|\mathcal{U}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}_{N,0}|) \right\} & \geq \beta,
        \intertext{and $t(|\mathcal{U}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}_{N,0}|) > 0$ holds since $\beta < 1$ and $|\mathcal{U}^{\mathcal{C}^*, \mathcal{C}', \mathcal{S}}_{N, 0}| < N$, thus,}
        \mathbb{P}^N \left\{ \mathbb{P}(\xi^u_\mathrm{diff} =  1) > 0 \right\} & \geq \beta,
    \end{align}
    Therefore , by Lemma \ref{lemma_recall_optimality_diff}, we have (\ref{recall_optimal_inequality_diff}).
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm_solution_certif}]
    By Theorems \ref{thm_certif} and \ref{thm_optimality}, $\eta_N$ defined by (\ref{eta}) and $\zeta_N$ defined by (\ref{zeta}) are the solutions to Problem \ref{problem:PACbound}. Moreover, $\mathcal{C}^*$ fulfills \textbf{(PC1)} in Problem \ref{problem:PACoptimal_diff} by (\ref{bound_tightness_Cstar}) in Lemma \ref{lemma_recall_optimality_max} and fulfills \textbf{(PC2)} in Problem \ref{problem:PACoptimal_diff} by Proposition \ref{prop_certify_PC2}. Thus, we have the claim.
\end{proof}

\section{Computational Complexity of Algorithm \ref{Alg_PG_SPREst}}
\label{appendix:complexity}
The computational complexity of Algorithm 1 is in 
\begin{align}
    \mathcal{O} \left(N \cdot \mathrm{poly}(|S|) + N^2 |S| + 2^{|S|} \log{ \frac{1}{\varepsilon}} \right),
\end{align}
where $N$ is the number of sampled parameters, $|S|$ denotes the number of states, $\mathrm{poly}(n)$ denotes a polynomial function of $n$, and $\varepsilon$ is the approximation error for computing $\eta_N$, that is, $\varepsilon$ denotes the length of each sub-interval when dividing the unit interval $[0,1]$ with equal length to conduct bisection search for $\eta_N$.

The breakdown of the computational complexity is as follows. The complexity of computing the solution $\mathcal{C}^*$ to Problem 3 is in $\mathcal{O}(N \cdot \mathrm{poly}(|S|) + N^2|S|)$. The complexity of computing the lower bounds $\eta_N$ for all members $C \in \mathcal{C}^*$ is in $\mathcal{O}(2^{|S|} \cdot \log{\frac{1}{\varepsilon}})$ because we compute $\eta_N$ for all subsets $C \in 2^S$ in the worst case, and the complexity of bisection search to approximately compute $\eta_N$ is in $\mathcal{O}(\log{\frac{1}{\varepsilon}})$. However, in general, the computation of $\eta_N$ for all $C \in \mathcal{C}^*$ is not intensive. This is because the number of obtained potential causes is much smaller than $2^{|S|}$ in practice. For example, the number of potential causes obtained in Example is at most three. The complexity of computing $\zeta_N$ is in $\mathcal{O}(1)$ because $\zeta_N$ is immediately given as $(1 - \beta)^{1/N}$ by Theorem 3.

In what follows, we intuitively describe the details for the complexity to obtain the solution $\mathcal{C}^*$.

\begin{itemize}
    \item In Lines from 1 to 7:\\
    The complexity in Lines from 1 to 7 is in $\mathcal{O}(N \cdot \mathrm{poly}(|S|))$.
The complexity of Algorithm 2 is in $\mathcal{O}(\mathrm{poly}(|S|))$ by Lemma 4 in \citep{baier2022probability}. Also, please see \citep{baier2008principles} if you are not familiar with temporal model checking and its complexity. The complexity of probabilistic verifications for reachability properties in MDPs is in $\mathcal{O}(\mathrm{poly}(|S|))$ and is described by Corollary 10.107 in \citep{baier2008principles}, on which the result of Lemma 4 in \citep{baier2022probability} relies. $S_N$ can be computed by $S_N = \{ c \in S \;|\; \eta_N(\{c\}, \beta) \geq \delta \}$. This is because, for any $C \subset S$ and any $l \in \mathbb{R}$, satisfaction of $\eta_N(\{c\}, \beta) \geq l$ is a necessary condition for $\eta_N(C, \beta) \geq l$ by Definition 1, and hence $S_N$ can be constructed by gathering all states which satisfy the condition $\eta_N(\{c\}, \beta) \geq l$. So, the complexity for computing $S_N$ is in $\mathcal{O}(N \cdot |S|)$. Obviously, the computational complexity of obtaining $\mathscr{C}_{S_N, u}$ using $\tau$ is in $\mathcal{O}(|S|)$. The complexity of computing $C^*_{S_N, u}$ is in $\mathcal{O}(2^{|\phi_1|} \cdot |S|)$, where $ \phi_1 = \mathscr{C}_{S_N, u} \mathrm{U} c $ and $|\phi_1|$ denote the number of operators in $\phi_1$ and hence $|\phi_1| = 1$. This is because the complexity of model checking for a transition system (directed graph) and an LTL formula $\phi$ is in $\mathcal{O}(2^{|\phi|} \cdot |S|)$ by Theorem 3.3 in [Shonoebelen2002]. Thus, the computational complexity for $C^*_{S_N, u}$ is in $\mathcal{O}(|S|)$.

Hence, the complexity for Lines from 1 to 7 is in $\mathcal{O}(N \cdot \mathrm{poly}(|S|) )$.

\item In Lines from 9 to 11:\\
The complexity in Lines from 9 to 11 is in $\mathcal{O}(N^2 \cdot |S|)$.
For each $u_i \in \mathcal{U}_N$, the complexity of checking the condition in (22) for any $u_j \in \mathcal{U}_N$ is in $\mathcal{O}(|S|)$ by Theorem 3.3 in \citep{schnoebelen2002complexity}. Hence, the complexity to obtain $\mathcal{U}^i_N$ is in $\mathcal{O}(N \cdot |S|)$. So, the complexity of computing $\mathcal{U}^i_N$ for all $u_i \in \mathcal{U}_N$ is in $\mathcal{O}(N^2 \cdot |S|)$.

So, the overall computational complexity in Lines from 9 to 11 is in $\mathcal{O}(N^2 \cdot |S|)$.
\end{itemize}
Thus, the complexity of computing solution $\mathcal{C}^*$ is in $\mathcal{O}\left(N \cdot \mathrm{poly}(|S|) + N^2 |S|\right)$.

\section{Interpretability}
\label{appendix:interpretability}
Obtained SPR causes are interpreted through a probability-raising perspective and recall optimality as follows: They are subsets of states whose traversal increases the probability of undesired behavior in a certain portion of the parameter space of the upMDP, Moreover, the obtained collection of them cover the undesired paths maximally in most of the parameter space of the upMDP.

We can also give an interpretation similar to causal interventional interpretability \citep{moraffah2020causal}. For example, considering the following differences in conditional probabilities: $$\max_{\pi} \mathrm{Pr}^{\pi}_{\mathcal{M}_u} (\Diamond E \;|\; \Diamond C) - \mathrm{Pr}^{\pi}_{\mathcal{M}_u} (\Diamond E \;|\; \neg \Diamond C),$$ and $$\min_{\pi} \mathrm{Pr}^{\pi}_{\mathcal{M}_u}(\Diamond E \;|\; \Diamond C) - \mathrm{Pr}^{\pi}_{\mathcal{M}_u}(\Diamond E \;|\; \neg \Diamond C).$$

Intuitively, the differences in probability, respectively, represent how much passage of the cause $C$ affects the probability values of undesired behavior pessimistically and optimistically. These can be seen as variants of "what if" scenarios usually considered in a causal analysis context \citep{moraffah2020causal}. However, the above comparisons are not for an actual path but for the overall behavior of the system. 

As for larger systems modeled by upMDPs, such as the number of states that they have can reach millions, a possible difficulty for interpretability is the case where we have massive potential SPR causes, and hence we may fall into the situation where we struggle to grasp how much each potential cause affect the undesired behavior. In this case, we take various approaches to enhance ease of understanding for humans as follows:

\begin{enumerate}
    \item We calculate the aforementioned differences in probability for the union of potential causes rather than each potential cause. Then, we can interpret the differences in probability as how much the passage of any potential causes affects the probability of undesired behavior.
    \item We pick up the obtained potential causes to be interpreted. For example, we can choose $k$ potential causes from all of them in order of the values of lower bounds $\eta_N$ for SPR cause probability. Then, we can interpret the differences in probability as how much the passage of each top-$k$ potential cause affects the probability of undesired behavior.
\end{enumerate}

\section{Another example to comprehend how (\ref{recall_optimal_samples}) works}
\label{appendix:other_example}

\begin{example}
\label{example3}
We consider the upMDP depicted in Fig. \ref{example1:upMDP} with the set of parameter variables $u = [p, q]^\top$, the set of actions $A=\{a, b\}$, and the terminal bad state $E = \{s_3\}$. $p$ and $q$ follow the uniform distributions over $[0.11, 0.51]$ and $[0.3, 0.7]$, respectively.
\begin{figure}[htbp]
\centering
    \includegraphics[width=0.5\linewidth]{Example1_upMDP_4states.pdf}
\caption{The upMDP with the parameter variables $V=\{p, q\}$, the set of actions $A=\{ a, b\}$, and the terminal state $E = \{ s_3 \}$. The enabled action is only $a$ at states other than $s_0$ and thus we omit it.}
\label{example1:upMDP}
\end{figure}
\end{example}


In Fig. \ref{example1:upMDP}, we have no SPR cause when $q > p$. This is because there exists a policy $\pi$ such that $\pi(s_0, a) > (p - p^2 \pi(s_0, b) ) / q$, and hence we have 
\begin{align}
    \mathrm{Pr}^\pi_{\mathcal{M}_u} (\Diamond s_3) & = \pi(s_0, a) q + \pi(s_0, b) p^2 \nonumber \\
         & > p - p^2 \pi(s_0, b) + p^2 \pi(s_0, b) \nonumber \\
         & = \mathrm{Pr}^\pi_{\mathcal{M}_u}(\Diamond s_3 \;|\; \Diamond s_1)
\end{align}

However, when $p > q$, $\{s_1\}$ is the unique SPR cause. Let us explain the reason for this in two cases.

(1) When $q \geq p^2$, for any policy $\pi$, the probability of reaching $s_3$ from $s_0$ is $\mathrm{Pr}^\pi_{\mathcal{M}_u} (\Diamond s_3) = \pi(s_0, a) q + \pi(s_0, b) p^2$ and, since $q > p^2$, we have $\pi(s_0, a) q + \pi(s_0, b) p^2 < q$. So, we have $\mathrm{Pr}^\pi_{\mathcal{M}_u} (\Diamond s_3) < \mathrm{Pr}^\pi_{\mathcal{M}_u} (\Diamond s_3 \;|\; \Diamond s_1)$ since $q < p$. Thus, $\{s_1\}$ is the SPR cause.

(2) When $q < p^2$, the maximal probability of reaching $s_3$ from $s_1$ is $p^2$ and obviously $p^2 < p$. So, we have $\{s_1\}$ as the SPR cause.


We consider solving Problem \ref{problem:PACoptimal_diff} for the upMDP in Example \ref{example3}. Let $\delta=0.1$ and $\beta=0.99$. We sampled $N=1000$ parameters. We obtained a solution $\mathcal{C}^* = \{ \{s_1\} \}$ with $\mathcal{S}_{N, \delta, \beta}$ $ =\{ \{s_1\} \}$, where $\{s_1\}$ is the canonical SPR causes on the sampled $992$ MDPs with $p > q$. Obviously, $\mathcal{U}^i_N$ that corresponds to $\{s_1\}$ is equal to $\mathcal{U}_N$. According to Theorem \ref{thm_certif}, $\{s_1\}$ provides the lower bounds of SPR-cause probabilities $0.98$ with the confidence probability $\beta=0.99$, respectively, and they exceed $\delta$. For \textbf{(PC1)}, the lower bound $\zeta_N(\mathcal{C}^*, \mathcal{S}_{N, \delta, \beta}, \beta)$ of recall-optimal probability is the maximum value $(1 - \beta)^{1/N} = 0.995$. 
    For \textbf{(PC2)}, the subset $\mathcal{C} = \emptyset \subset \mathcal{C}^*$ clearly does not contain any SPR cause for all parameters. So, $R(\mathcal{M}_\mathbb{P}, \mathcal{C}^*, S_{N, \delta, \beta}) > R(\mathcal{M}_\mathbb{P}, \mathcal{C}, S_{N, \delta, \beta})$.

\section{Intuitive explanation for SPR causes on Example section}
\label{appendix:explain_example_sec}
The undesired behavior of the two environments depicted in \ref{ex:env1} and \ref{ex:env2} in Example is to enter the red cells. That is, the red cells are "undesired" terminal states. Our demonstration has aimed to nonredundantly and exhaustively find the causes of the undesired behavior. In this example, causes are seen as the states such that passing through the states raises the probability of the undesired behavior. Yellow, orange, and green cells correspond to the causes for some parameters of the upMDP. Our proposed method finds these potential causes by sampling upMDP parameters, model checking-based cause synthesis for each sampled MDP, and consolidating them by the proposed set covering technique.

We can observe that the three causes, depending on the parameter values in these environments, have been found well. Intuitively, in both environments, when the probability of entering the red cells from above is greater than that of entering the red cells from below, that is $p_1 < p_2$, the robot passing through the yellow cells is more likely to enter the red cells from above than other behavior that does not pass through the yellow cells. Likewise, when $p_1 > p_2$, the probability of entering the red cells from below rises after passing through the orange/green cells. The difference between the orange cells and green cells as the SPR causes is subtle. When $p_0$ is sufficiently large, that is $p_0$ is close to the upper limit $0.9$, the chance to unintentionally go up from the cell $(4, 5)$ is sufficiently small. Hence, the chance to visit the red cells from above is sufficiently small. So, in this case, the set of orange cells is an SPR cause. On the contrary, when $p_0$ is relatively small, that is $p_0$ is close to the lower limit $0.8$, the set of green cells is an SPR cause. Moreover, we can intuitively find that these three potential causes cover all undesired paths, and removing any potential cause makes an uncovered undesired path appear.

Our algorithm has effectively found these intuitive potential causes by combining three ingredients: (i) sampling parameters of the environment and PAC-bound we introduced, (ii) model checking-based SPR cause synthesis for each sampled MDP based on \citep{baier2022probability}, and (iii) consolidation of these synthesized causes by the proposed set covering based on (22). In detail, when we have tried to obtain subsets of states that become SPR causes with positive probability, we have obtained all three SPR causes. On the other hand, when we have tried to obtain subsets of states that have become SPR causes with the probability threshold $\delta=0.1$, we obtain only yellow cells. This is because the probability of $p_1 > p_2$ is sufficiently small.

\section{Detailed Results for Example}
\label{appendix:detailed_results}
Fig. \ref{ex:result_env1} and Fig. \ref{ex:results_env2}  show the results obtained from our proposed method for two environments depicted in Figs. \ref{ex:env1} and \ref{ex:env2}, respectively, with all experimental parameters $\beta = \beta_0, \beta_1$ and $\delta = \delta_0, \delta_1$. We depict the results with blue, green, magenta, and red lines for the parameters $(\delta_0, \beta_0)$, $(\delta_0, \beta_1)$, $(\delta_1, \beta_0)$, and $(\delta_1, \beta_1)$, respectively.
The top row in Fig. \ref{ex:results} shows the recall-optimal probabilities $R$, their lower bounds $\zeta$, and the minimum recall-optimal probabilities over all proper subsets of the obtained solution $\mathcal{C}^*$ under each sample size $N$ as dotted, solid, and dashed lines, respectively. We find that $\zeta$ and $R_\mathrm{sub}$ bound $R$ from below for all sample sizes and parameters. Moreover, $\zeta$ takes a higher value when $\beta = \beta_0$ than when $\beta = \beta_1$.
The middle row (resp., the bottom row) shows the maximum (resp., minimum) SPR-cause probabilities $F_\mathrm{max}$ (resp., $F_\mathrm{min}$) and the maximum (resp., minimum) lower bounds $\eta_\mathrm{max}$ (resp., $\eta_\mathrm{min}$) for all state sets $C$ in the obtained solution $\mathcal{C}^*$ as dotted and solid lines, respectively, for each sample size $N$. We observe that $\eta_\mathrm{max}$ (resp., $\eta_\mathrm{min}$) bounds $F_\mathrm{max}$ (resp., $\eta_\mathrm{min}$) from below and exceeds $\delta$ for all sample sizes and all experimental parameters.

