% \keywords{Basis pursuit denoising, Lasso, $\ell_{1}$-regularized least-squares, compressive sensing, statistics, machine learning, inverse problems, optimization, convex analysis, differential inclusions, projected dynamical systems, variational inequalities, exact solution, algorithms.\break}

