\section{Preliminaries of group-theoretical results}\label{sect 2}


In this section,  let $\Gamma$ be a centerless group (i.e. the center $C(\Gamma)$ is trivial), and let $G$ be a finitely generated nilpotent group. Let
$$\varphi: \Gamma\times G \rightarrow \Gamma\times G$$
be an automorphism. In \cite[Lemma 2.4]{N20} Neofytidis showed the following:

\begin{lem}[\cite{N20}]\label{auto for product}
	 The automorphism $\varphi: \Gamma\times G \rightarrow \Gamma\times G$ has a form
	 $$\varphi(\gamma,g)=(\alpha(\gamma),\rho(\gamma)L(g)),$$
	 where $\alpha : \Gamma\rightarrow \Gamma$ and $L : G \rightarrow G$ are automorphisms and $\rho :  \Gamma\rightarrow C(G)$ is a homomorphism into the center of $G$.
\end{lem}

Now, we suppose that the fixed subgroup of $L$ is trivial, that is,
$$\fix(L):=\{ g\in G\mid L(g)=g\}=1.$$
Consider the endomorphism $\psi: C(G)\to C(G)$ defined by
\begin{equation}\label{eq. psi}
\psi(g)=L(g)g^{-1}.
\end{equation}
Note that
$\ker\psi=\fix(L)=1,$ so $\psi$ is injective and hence $\psi^{-1}:\psi(C(G))\to C(G)$ is an isomorphism. Let
\begin{equation}\label{eq. Normal subgp}
\Gamma':=\rho^{-1}(\psi(C(G)))\lhd \Gamma.
\end{equation}
Then $\Gamma'=\Gamma$ if $\psi$ is an automorphism of $C(G)$.  Moreover, we have the following observation.
\begin{lem}
    $\Gamma'$ is a finite-index normal subgroup of $\Gamma$.
\end{lem}
\begin{proof}
Recall that a finitely generated nilpotent group has any subgroup again finitely generated. So the center $C(G)$ of the finitely generated nilpotent group $G$ is finitely generated and abelian. Moreover, note that the endomorphism $\psi: C(G)\to C(G)$ is injective, so the index $[C(G): \psi(C(G))]$ is finite. It follows that $$[\Gamma:\Gamma']\leq [C(G): \psi(C(G))]<\infty.$$ The normality of $\Gamma'$ is apparent.
\end{proof}

Now we suppose that the automorphism $\a\in \aut(\Gamma)$ is an inner automorphism of $\Gamma$. Then we can define a homomorphism
$$\theta=\psi^{-1}\comp \rho : ~\Gamma' \to  C(G)$$
and an automorphism $h_\#: \Gamma'\times G\to \Gamma'\times G$ as follows,
\begin{equation}\label{equ. h}
 h_\#(\gamma, g)=(\gamma, ~\theta(\gamma)g)
\end{equation}
with $h_\#^{-1}(\gamma, g)=(\gamma, \theta(\gamma)^{-1}g)$.
Moreover, for any $(\gamma, g)\in \Gamma'\times G$, we have
\begin{eqnarray}
h_\#\comp\varphi\comp h_\#^{-1}(\gamma, g)
&=& h_\#\big(\alpha(\gamma), ~\rho(\gamma)L(\theta(\gamma)^{-1}g)\big)\notag\\
&=& \big(\alpha(\gamma), ~\theta(\alpha(\gamma)) \rho(\gamma)L(\theta(\gamma)^{-1})L(g)\big)\notag\\
&=& \big(\alpha(\gamma), ~L(\theta(\gamma)^{-1})\theta(\gamma)\cdot \rho(\gamma)L(g)\big)\notag\\
&=& \big(\alpha(\gamma), ~\psi(\theta(\gamma)^{-1})\cdot \rho(\gamma)L(g)\big)\notag\\
&=& \big(\alpha(\gamma), ~\rho(\gamma^{-1})\cdot \rho(\gamma)L(g)\big)\notag\\
&=& \big(\alpha(\gamma), ~L(g)\big)\in  \Gamma'\times G.\notag
\end{eqnarray}
In conclusion, we have proved:

\begin{lem}\label{auto for product on finite index normal subgroup}
Using the same notations as above. If the automorphism $\a\in \aut(\Gamma)$ is an inner automorphism of $\Gamma$ and $L\in\aut(G)$ satisfies $\fix(L)=1$, then
$$h_\# \comp \varphi \comp h_\#^{-1}=\alpha\times L: ~\Gamma'\times G\to \Gamma'\times G,$$
namely,  ~$h_\#\comp\varphi\comp h_\#^{-1}(\gamma, g)=(\alpha(\gamma), L(g))$ for any $(\gamma, g)\in \Gamma'\times G$. In particular, $\Gamma'=\Gamma$ if the homomorphism $\psi$ in Eq. (\ref{eq. psi}) is an automorphism of $C(G)$.
\end{lem}

