\section{Several useful lemmas}\label{sect 3}

In this section, let $M$ be a compact connected aspherical polyhedron with centerless fundamental group $\pi_1(M)=\Gamma$, and let $N=\widehat{N}/G$ be a closed nilmanifold with fundamental group $\pi_1(N)=G$, where $\widehat{N}$ is a simply connected nilpotent Lie group and $G \subset \widehat{N}$ is a co-compact lattice.

Note that all the spaces $M, N$ and $M\times N$ are aspherical and $C(G)=G\cap C(\widehat{N}).$ Moreover,  the product $M\times N$ satisfies the following mild condition: it is a compact connected polyhedron without local separating points, but it is not a surface (closed or with boundary) of negative Euler characteristic. Then by Jiang's deep result \cite[Main Theorem]{J80} or \cite[p.22, Theorem 6.3]{J83}, we have the following.

\begin{lem}\label{Jiang's deep thm Mf=Nf}
$\Min(f)=\Nie(f)$ for any selfmap $f$ of $M\times N$.
\end{lem}

Now, let $f : M \times N \rightarrow M \times N$ be a homotopy equivalence. Then by the above Lemma \ref{auto for product}, $f$ induces an automorphism $f_\#$ on the fundamental group:
\begin{eqnarray}\label{eq. aut on fundamental group}
f_\#: \Gamma\times G &\to& \Gamma\times G\\
 (\gamma, g)&\mapsto& (\a(\gamma), \rho(\gamma)L(g)).\notag
\end{eqnarray}
 where $\alpha : \Gamma\rightarrow \Gamma$ and $L : G \rightarrow G$ are automorphisms and $\rho :  \Gamma\rightarrow C(G)$ is a homomorphism into the center of $G$.
Since all of $M, N$ and $M\times N$ are aspherical, $f$ can be homotopied to a
fiber-preserving map (still denoted by $f$) as follows:
\begin{equation}\label{fibration map}
	f(x,y) = (f_1 (x),f_2 (x,y)),
\end{equation}
where $f_1 : M \rightarrow M$ induces $f_{1\#} = \alpha\in \aut(\Gamma)$, and for any $x \in M$,
$$f_{2,x}(\cdot)=f_2(x,\cdot) : N \rightarrow N$$
induces $f_{2,x \#} = L\in \aut(G).$ Since $G=\pi_1(N)$ is the fundamental group of the nilmanifold $N$, the automorphism $L$ can be represented by an invertible matrix over the integers (also denoted by $L$, see \cite{K05}). Note that $\fix(L)=\{g\in G\mid L(g)=g\}$, so we have the following observation.

\begin{lem}
The matrix $L$ has an eigenvalue $1$ $\Longleftrightarrow$ $\fix(L)\neq 1$ $\Longleftrightarrow$  $\det(L-I)=0$ where $I$ is the identity matrix.
\end{lem}



\begin{lem}\label{periodic point}
	Let $f : M \times N \rightarrow M \times N$ be a homotopy equivalence, and let $L : G \rightarrow G$ be the automorphism as above. If the determinant $\det(L^k-I)= 0$ for some integer $k>0$, then $$\Lef(f^k)=\Min(f^k)=\Nie(f^k)=0,$$
    that is, after homotopy, $f^k$ has no fixed points.
\end{lem}

\begin{proof}
By Eq. (\ref{fibration map}), after homotopy, we can assume that the homotopy equivalence $f^k:  M \times N \rightarrow M \times N$ is a fiber-preserving map as follows:
	$$f^k(x,y)=(f^k_1(x),f'_{2,x}(y)),$$
where the map $f'_{2,x}: N\to N$ induces $(f'_{2,x})_\#=L^k: G\to G$ for every $x\in M$.  Recall that the nilmanifold $N$ is a Jiang space, the Nielsen number
  $$\Nie(f'_{2,x})=|\Lef(f'_{2,x})|=|\det(L^k-I)|= 0.$$
Hence, by the ``Product formula for the Nielsen number'' \cite[p.88, Corollary 4.3]{J83}, we have
	$$\Nie(f^k)=\Nie(f^k_1)\cdot \Nie(f'_{2,x})= 0.$$
Therefore, by Lemma \ref{Jiang's deep thm Mf=Nf}, we have
$$\Lef(f^k)=\Min(f^k)=\Nie(f^k)=0,$$
that is, $f^k$ is fixed point free after homotopy.
\end{proof}

 As in Eq. (\ref{eq. Normal subgp}), let
 $$\Gamma':=\rho^{-1}(\psi(C(G)))\lhd \Gamma= \pi_1(M)$$
and let $\widetilde{M}$ be the finite cover of $M$ with $\pi_1(\widetilde{M})=\Gamma'.$ Denote by $\widehat{M}$ the universal cover of $M$. The fundamental groups $\Gamma $ and $\Gamma'$ act on $\widehat{M}$ cocompactly by deck transformations, and we identify $\Gamma$ with an orbit of a base-point in $\widehat{M}$. Recall that $G=\pi_1(N)$. For the automorphism $h_\#: \Gamma'\times G\to \Gamma'\times G$ given in Eq. (\ref{equ. h}), we can show:

\begin{lem}\label{h realise a homeomorphism}
There exists a homeomorphism $h: \widetilde{M}\times N\to   \widetilde{M}\times N$ inducing the automorphism $h_\#(\gamma, g)=(\gamma, ~\theta(\gamma)g)$ given in Eq. (\ref{equ. h}).
\end{lem}

Although Lemma \ref{h realise a homeomorphism} can be directly derived from \cite[Lemma 6.3 \& Lemma 6.6]{GL16}, for the sake of readability and completeness, we provide the detailed proof as follows.

\begin{proof}
Triangulate the universal cover $\widehat{M}$ in an equivariant way so that $\Gamma'\subset \widehat{M}$ belongs to the $0$-skeleton. Extend  the homomorphism
$$\theta=\psi^{-1}\comp \rho: ~\Gamma'\rightarrow C(G)\subset \widehat N$$
to the $0$-skeleton of  $\widehat{M}$ equivariantly in an arbitrary way. Recall that the universal cover $\widehat{N}$ is connected, simply connected and aspherical. Therefore, we can extend $\theta$ equivariantly to all skeleta of $\widehat{M}$ by induction on dimension, and we approximate the resulting map by an equivariant map (still denoted by $\theta$) $\theta: \widehat M\to \widehat{N}$, that is,
$$\theta(\gamma \hat x)=\theta(\gamma)\theta(\hat x), ~~\forall \gamma\in \Gamma', ~\hat x\in\widehat M.$$
It is easy to see (by using charts) that this can be done without changing the values on $\Gamma' \subset \widehat{M}$.  Note that $\theta(\gamma)\in C(G)$ for every $\gamma\in \Gamma'$. Therefore, the above equivariant map $\theta: \widehat M\to \widehat{N}$ descends to a map
$$\theta: \widetilde{M} =\widehat{M}/\Gamma'\longrightarrow N=\widehat{N}/G.$$ Then the posited homeomorphism $h: \widetilde{M}\times N\to   \widetilde{M}\times N$ can be defined as follows:
$$h(x,y)=(x,\theta(x)y).$$
\end{proof}



%Put $f$ be a self-homotopy equivalence of $M\times N$, we have the following proposition.
\begin{lem}\label{alpha is inner}
	Let $f : M \times N \rightarrow M \times N$ be a homotopy equivalence with a fixed point, and let $\a:\Gamma\to \Gamma$ and $L: G \rightarrow G$ be automorphisms as above. If $\a$ is an inner automorphism of $\Gamma$ and the determinant $\det(L-I)\neq 0$, then there exists a finite cover $\widetilde{M}\times N$ of $M\times N$, and exists a lifting $\tilde{f}$ of $f$ in $\widetilde{M}\times N$ such that the following diagram is homotopy commutative:
$$
\xymatrix{
\widetilde{M}\times N \ar[r]^{\tilde{f}}\ar[d]^{\cong}_{h} & \widetilde{M}\times N \ar[d]^{h}_{\cong}\\
\widetilde{M}\times N \ar[r]^{f_1\times f_2} & \widetilde{M}\times N
}
$$
where $h$ is a homeomorphism, and $f_1:\widetilde{M}\to \widetilde{M}$,  $f_2: N\to N$ are homotopy equivalences. In particular, if $|\det(L-I)|=1$, then $\widetilde{M}=M$, and $f=\tilde f$ with
$$\Lef(f)=\Lef(f_1)\cdot \Lef(f_2), \quad \Nie(f)=\Nie(f_1)\cdot \Nie(f_2).$$
\end{lem}

\begin{proof}
Suppose $(x,y)\in M\times N$ is a fixed point of $f$, $\Gamma=\pi_1(M, x)$ and $G=\pi_1(N, y)$ throughout the proof. Then
the automorphism $f_\#$ of $\Gamma\times G$ induced by $f$ has the following form as in Eq. (\ref{eq. aut on fundamental group}):
$$f_\#(\gamma, g)=(\alpha(\gamma),\rho(\gamma)L(g)),~\mathrm{for}~(\gamma,g)\in \Gamma\times G,$$
where $\alpha : \Gamma\rightarrow \Gamma$ and $L : G \rightarrow G$ are automorphisms and $\rho :  \Gamma\rightarrow C(G)$ is a homomorphism into the center of $G$. Since the determinant $\det(L-I)\neq 0$, i.e., the fixed subgroup $\fix(L)=1$, by Lemma \ref{auto for product on finite index normal subgroup}, there exists a finite-index normal subgroup $\Gamma'$ of $\Gamma$, and an automorphism $h_\#: \Gamma'\times G\to \Gamma'\times G$ such that
\begin{equation}\label{conjugate product on pi}
h_\# \comp f_\# \comp h_\#^{-1}=\alpha\times L: ~\Gamma'\times G\to \Gamma'\times G.
\end{equation}

Let $\widetilde{M}$ be the finite cover of $M$ corresponding to $\Gamma'=\pi_1(\widetilde{M}, \tilde x)$ for $\tilde x\in p^{-1}(x)$, and let $p\times\mathrm{id}:\widetilde{M}\times N\rightarrow M\times N$ be the covering map corresponding to the subgroup $\Gamma'\times G$ of $\Gamma\times G$. Recall that $\Gamma'\leq \Gamma $ is normal and $\a\in \inn(\Gamma)$, so $f_\#(\Gamma'\times G)\leq \Gamma'\times G$. Therefore, we have a commutative diagram
$$
\xymatrix{
\widetilde{M}\times N \ar[r]^{\tilde{f}}\ar[d]_{p\times \mathrm{id}} & \widetilde{M}\times N \ar[d]^{p\times \mathrm{id}}\\
M\times N \ar[r]^{f} & M\times N
}
$$
where $\tilde{f}$ is a lifting of $f$.  Since all the spaces above are aspherical, there are homotopy equivalences
\begin{eqnarray}
f_1: (\widetilde{M}, \tilde{x}) &\to& (\widetilde{M}, \tilde{x}),\notag\\
f_2: (N, y)&\to& (N, y), \notag\\
h: (\widetilde{M}\times N, (\tilde{x},y))&\to& (\widetilde{M}\times N, (\tilde{x},y))\notag
\end{eqnarray}
inducing $f_{1\#}=\a|_{\Gamma'}, ~f_{2\#}=L$ and $h_\#$ respectively. Note that $h$  can be realized as a homeomorphism by Lemma \ref{h realise a homeomorphism}. Then on the fundamental group $\Gamma'\times G$, we have
\begin{eqnarray}\nonumber
  (h\comp \tilde{f})_\# = h_\# \comp f_\# =(\alpha\times L)\comp h_\#=((f_1\times f_2)\comp h)_\#,
\end{eqnarray}
where the second ``=" holds by Eq. (\ref{conjugate product on pi}).
Therefore, $h\comp \tilde{f}$ is homotopic to $(f_1\times f_2)\comp h$.

In particular, if $|\det(L-I)|=1$, then $(L-I)^{-1}$ is an integer matrix and hence the homomorphism $\psi$ in Eq. (\ref{eq. psi}) is an automorphism. It follows $\Gamma'=\Gamma$ from Lemma \ref{auto for product on finite index normal subgroup}, and hence $\widetilde{M}=M$ and $\tilde f=f$. Therefore, $f$  is conjugate to $f_1\times f_2$ , by the ``Homotopy type invariance of the Nielsen number" \cite[p.21, Theorem 5.4]{J83}, ``Product formula for the Lefschetz number" \cite[p.85, Theorem 3.2]{J83} and ``Product formula for the Nielsen number" \cite[p.88, Theorem 4.1]{J83}, we have $\Lef(f)=\Lef(f_1)\cdot \Lef(f_2)$ and $\Nie(f)=\Nie(f_1)\cdot \Nie(f_2).$
\end{proof}

