\section{Proof of Theorem \ref{main thm 0}}\label{sect 4}

Recall that $\Sigma_g$ denotes the closed orientable surface of genus $g>1$. The fundamental group $\pi_1(\Sigma_g)$ has a canonical presentation:
$$
\pi_1(\Sigma_g)=\langle a_1,b_1,\ldots,a_g,b_g\mid [a_1,b_1]\cdots[a_g,b_g]=1 \rangle,
$$
where $[a, b]=aba^{-1}b^{-1}$.
First, we have the following product formula for the index of a fixed point class.

\begin{lem}\label{product formula for the index}
Let $p: E=\Sigma_g\times T^n\to \Sigma_g$ be the projection to the first factor, where $T^n$ ($n\geq 1$) is an $n$-torus. Let $f:E\to E$ be a fiber-preserving map inducing the identity $\id:\Sigma_g\to \Sigma_g$ on the base space, i.e., the following diagram is commutative.
$$
\xymatrix{
E \ar[r]^f\ar[d]_p & E \ar[d]^p\\
\Sigma_g \ar[r]^{\id} & \Sigma_g
}
$$
Then, for any essential fixed point class $\F$ of $f$, the projection $p(\F)=\Sigma_g$ and
$$|\ind(f,\F)|=[\pi_1(\Sigma_g) : p_{\#}(\fix f_{\#})]\cdot|\chi(\Sigma_g)|,$$
where $f_{\#}: \pi_1(E, e)\to\pi_1(E,e)$ is the natural homomorphism induced by $f$  for $e\in \F$.
\end{lem}

\begin{proof}
Note that for any map of $T^n$, its essential fixed point classes have the same index $\pm 1$ \cite{B75, H79}. Then the conclusion follows from \cite[p.78, Theorem 1.6]{J83} and the ``Product formula for the index of a fixed point class" \cite[p.85, Theorem 3.3]{J83}.
\end{proof}

Now, we show the following lemmas for convenience of our discussion.

\begin{lem}\label{invert}
	Let $L_m=
	\begin{pmatrix}
		m+1 & m \\
		1 & 1  \\
	\end{pmatrix}
	$ be a matrix and let $I$ be the identity matrix. Then the matrix $I-L_m^k$ is invertible for all  integers $k,m>0$.
\end{lem}

\begin{proof}
	By direct calculation, we obtain the eigenvalues of $L_m$ are $\lambda_{1,2}=\frac{m+2\pm \sqrt{m^2+4m}}{2},$ which are not unit roots for every integer $m>0$. So the eigenvalues of $L^k$ are not equal to $1$ and hence  $I-L_m^k$ is invertible for all  integers $k,m>0$.
\end{proof}

\begin{lem}\label{lem index m}
Let $p: \pi_1(\Sigma_g)\times \Z\to \pi_1(\Sigma_g)$ be the projection to the first factor, and let
 $\rho: \pi_1(\Sigma_g)\to \Z$ be an epimorphism.	
For any integer $m>0$, let
$$H_m=\{(u,s)\in\pi_1(\Sigma_g)\times \Z \mid s=-\frac{\rho(u)}{m}, ~\rho(u)\equiv0\mod m\}.$$
Then $p(H_m)$ is a subgroup of $\pi_1(\Sigma_g)$ of index
$[\pi_1(\Sigma_g):p(H_m)]=m.$
\end{lem}

\begin{proof}
Note that $\rho: \pi_1(\Sigma_g)\to \Z$ is an epimorphism, and $$p(H_m)=\{u\in\pi_1(\Sigma_g)\mid \rho(u)\equiv0\mod m\},$$
so
$[\pi_1(\Sigma_g): p(H_m)]=[\Z:m\Z]=m.$
\end{proof}

\begin{proof}[\textbf{Proof of Theorem \ref{main thm 0}}]
By Theorem \ref{ZZ cout-examp.}, $\Sigma_g\times S^1$ has BIPH and hence it has BIPH$_k$ for any $k>0$ clearly. Now, let
 $\rho: \pi_1(\Sigma_g)\to \pi_1(S^1)=\Z$ be an epimorphism defined as follows:
\begin{equation}\label{eq. rho to torus}\nonumber
	\rho(a_1)=1, ~\rho(b_1)=\rho(a_2)=\rho(b_2)=\cdots=\rho(a_g)=\rho(b_g)=0.  \end{equation}

\textbf{(1).} Let $G=\pi_1(\Sigma_g)\times \pi_1(S^1)$. For any $m>0$, we pick an endomorphism $\phi\in\mathrm{End}(G)$ as
	$$\phi(u,s)=(u, \rho(u)+(m+1)s).$$
	By direct calculation, we obtain
	$$\phi^k(u,s)=(u, \sum^{k-1}_{i=0}(m+1)^i\rho(u)+(m+1)^ks).$$
	Hence
	\begin{eqnarray}
		\fix(\phi^k)
		& = & \{(u,s)\mid s=\sum^{k-1}_{i=0}(m+1)^i\rho(u)+(m+1)^ks\}\notag\\
		& = & \{(u,s)\mid (1-(m+1))^k)s=\sum^{k-1}_{i=0}(m+1)^i\rho(u)\}\notag\\
		& = & \{(u,s)\mid s=-\frac{\rho(u)}{m}, ~\rho(u)\equiv0\mod m\}.\notag
	\end{eqnarray}
By Lemma \ref{lem index m}, we have $[\pi_1(\Sigma_g): p(\fix (\phi^k))]=m.$

Moreover, note that $S^1$ is aspherical, we can pick a fiber-preserving map
\begin{eqnarray}
 f: \Sigma_g\times S^1&\to& \Sigma_g\times S^1\notag\\
 (x, ~y)&\mapsto& (x, ~f_2(x, y))\notag
\end{eqnarray}
such that the induced homomorphism $f_{\#}=\phi$ on the fundamental group. The restriction of $f^k$ on each fiber $S^1$ is a selfmap of degree $(m+1)^k$, and hence has Lefschetz number $1-(m+1)^k$. By ``Product formula for the Lefschetz number" \cite[p.85, Theorem 3.2]{J83}, we have
\begin{equation}\label{eq-Lef1}\nonumber
  \Lef(f^k) = (1-(m+1)^k)\cdot \Lef(\id) = (1-(m+1)^k)\cdot \chi(\Sigma_g)\neq 0.
\end{equation}
Therefore, there is an essential fixed point class $\F$ of $f^k$ and by Lemma \ref{product formula for the index}, we have
    $$|\ind(f^k,\F)|=[\pi_1(\Sigma_g): p(\fix (\phi^k))]\cdot |\chi(\Sigma_g)|=m|\chi(\Sigma_g)|=m(2g-2).$$
Recall that $m$ can be arbitrarily large,  we have proven that $\Sigma_g\times S^1$ does not have BIP$_k$ for any $k\geq 1$.\\

\textbf{(2).} We first consider the case $n=2$. Let $G=\pi_1(\Sigma_g)\times \pi_1(T^2)$. For any integer $m>0$, let the matrix $L_m=
	\begin{pmatrix}
		m+1 & m \\
		1 & 1  \\
	\end{pmatrix}$  as in Lemma \ref{invert}, which can be viewed as an automorphism of $\pi_1(T^2)=\Z\times \Z$.  Now, we pick  an automorphism $\phi\in\aut(G)$ as
	$$\phi(u,{{s_1}\choose{s_2}})=(u,{{\rho(u)}\choose{0}}+L_m{{s_1}\choose{s_2}})$$
	where $u\in \pi_1(\Sigma_g)$ and $(s_1,s_2)^T\in \pi_1(T^2)= \Z\times \Z$. Then for any integer $k>0$,
	$$\phi^k(u,{{s_1}\choose{s_2}})=(u,\sum^{k-1}_{i=0}L_m^{i}{{\rho(u)}\choose{0}}+L_m^k{{s_1}\choose{s_2}}).$$
	Note that the matrix $I-L_m^k=(I-L_m)(\sum^{k-1}_{i=0}L_m^{i})$ is invertible by Lemma \ref{invert},  we have
	\begin{eqnarray}
		\fix(\phi^k)
		& = & \{(u,{{s_1}\choose{s_2}})\mid {{s_1}\choose{s_2}}=\sum^{k-1}_{i=0}L_m^{i}{{\rho(u)}\choose{0}}+L_m^k{{s_1}\choose{s_2}}\}\notag\\
		& = & \{(u,{{s_1}\choose{s_2}})\mid (I-L_m^k){{s_1}\choose{s_2}}=\sum^{k-1}_{i=0}L_m^{i}{{\rho(u)}\choose{0}}\}\notag\\
		& = & \{(u,{{s_1}\choose{s_2}})\mid (I-L_m){{s_1}\choose{s_2}}={{\rho(u)}\choose{0}}\}\notag\\
		& = & \{(u,{{s_1}\choose{s_2}})\mid {{s_1}\choose{s_2}}={{0}\choose{-\frac{\rho(u)}{m}}}, ~\rho(u)\equiv 0\mod m\},\notag
	\end{eqnarray}
	where the condition ``$\rho(u)\equiv 0\mod m$'' is necessary because $s_2\in \Z$.
Then, by Lemma \ref{lem index m}, we have
    $$[\pi_1(\Sigma_g): p(\fix (\phi^k))]=m,$$
where $p: \pi_1(\Sigma_g)\times \pi_1(T^2)\to \pi_1(\Sigma_g)$ is the projection to the first factor.

Moreover, note that $T^2$ is aspherical, we can pick a fiber-preserving homeomorphism
\begin{eqnarray}\label{eq. f on T2}
 f: \Sigma_g\times T^2&\to& \Sigma_g\times T^2\\
 (x, ~y)&\mapsto& (x, ~f_2(x, y))\notag
\end{eqnarray}
such that the induced automorphism $f_{\#}=\phi$ on the fundamental group. The restriction of $f^k$ on each fiber $T^2$ has Lefschetz number $\det(I-L^k_m)\ne0$ from Lemma \ref{invert}. By ``Product formula for the Lefschetz number" \cite[p.85, Theorem 3.2]{J83}, we have
\begin{equation}\label{eq-Lef1}\nonumber
  \Lef(f^k) = \det(I-L^k_m)\cdot \chi(\Sigma_g)\ne 0.
\end{equation}
Therefore, there is an essential fixed point class $\F$ of $f^k$ and by Lemma \ref{product formula for the index}, we have
\begin{equation}\label{eq. ind fk}
|\ind(f^k,\F)|=[\pi_1(\Sigma_g): p(\fix (\phi^k))]\cdot |\chi(\Sigma_g)|=m|\chi(\Sigma_g)|=m(2g-2).
\end{equation}
Recall that $m$ can be arbitrarily large,  we have proven that $\Sigma_g\times T^2$ does not have BIPH$_k$ for any $k\geq 1$.\\

Finally, for the remaining case $\Sigma_g\times T^n(n>2)$,  let $G=\pi_1(\Sigma_g)\times \pi_1(T^n)$. For any integer $m>0$, let the $n\times n$ matrix
    $$
	L_m=\begin{pmatrix}
		m+1&m&m&\cdots&m&m\\
		1&1&0&\cdots&0&0\\
        1&1&1&\cdots&0&0\\
		\vdots&\vdots&\vdots&\ddots&\vdots&\vdots\\
		1&1&1&\cdots&1&0\\
		1&1&1&\cdots&1&1\\
	\end{pmatrix}.
$$
Note that $\det(\lambda I-L_m)=(\lambda-1)^n-m\lambda^{n-1}$, for any integer $k>0$ and sufficiently large $m$, no roots of unity are eigenvalues of $L_m$ and hence $\det(I-L_m^k)\neq 0$. Moreover, $L_m$ can be viewed  as an automorphism of $\pi_1(T^n)=\Z^n$.
Let $\phi\in\aut(G)$ be defined as
	$$\phi(u,\begin{pmatrix}
	    s_1\\
        s_2\\
        \vdots\\
        s_n\\
	\end{pmatrix})=(u,\begin{pmatrix}
	    \rho(u)\\
        0\\
        \vdots\\
        0\\
	\end{pmatrix}+L_m\begin{pmatrix}
	    s_1\\
        s_2\\
        \vdots\\
        s_n\\
	\end{pmatrix})$$
	where $u\in \pi_1(\Sigma_g)$ and $(s_1,s_2,\ldots,s_n)^{T}\in \pi_1(T^n)= \Z^n$.
    Now, we can pick a fiber-preserving homeomorphism
    \begin{eqnarray}\nonumber
 f: \Sigma_g\times T^n&\to& \Sigma_g\times T^n\\
 (x, ~y)&\mapsto& (x, ~f_2(x, y))\notag
\end{eqnarray}
such that $f_\#=\phi.$ Using the same method of the above case ``$n=2$", we can show there is also an essential fixed point class $\F$ of $f^k$ such that
    $$|\ind(f^k,\F)|=m|\chi(\Sigma_g)|=m(2g-2).$$
Thereofore, $\Sigma_g\times T^n(g, n\geq 2)$ does not have BIPH$_k$ for any $k\geq 1$.
\end{proof}

\section{Proofs of Theorems \ref{main thm 1}-\ref{main thm 3}}\label{sect 5}

\begin{proof}[\textbf{Proof of Theorem \ref{main thm 1}}]
For every homotopy equivalence $f: M\times N\to M\times N$ and  any integer $k>0$ divisible by the order $|\out(\pi_1(M))|$,  by Theorem \ref{main thm 2}, we have $\Nie(f^k)=0$. Therefore, $\ind(f^k, \F)=0$ for every fixed point class $\F$ of $f^k$. Hence $M\times N$ has BIPHE$_k$.
\end{proof}

\begin{proof}[\textbf{Proof of Theorem \ref{main thm 2}}]
Since $M$ is a closed negatively curved Riemannian manifold of odd dimension, $\chi(M)=0$, $\pi_1(M)$ is centerless and $\out(\pi_1(M))$ is a finite group by Rips and Sela \cite{RS} building on ideas of Paulin. Let $k>0$ be divisible by the order $|\out(\pi_1(M))|$.
If $f^{k}$ is fixed point free, it is clear that
$$\Lef(f^k)=\Min(f^k)=\Nie(f^k)=0.$$

Now, we suppose that $(s,t)\in M\times N$ is a fixed point of $f^k$, $\Gamma=\pi_1(M, s)$ and $G=\pi_1(N, t)$ throughout the proof. By Eq. (\ref{fibration map}), after a homotopy, we can assume that the homotopy equivalence $f^k:  M \times N \rightarrow M \times N$ is a fiber-preserving map as follows:
	$$f^k(x,y)=(f^k_1(x),f'_{2,x}(y)),$$
where the map $f^k_1: M\to M$ induces $(f^k_1)_\#=\alpha^k\in\aut(\Gamma)$, $f'_{2,x}: N\to N$ induces $(f'_{2,x})_\#=L^k\in\aut(G)$ for every $x\in M$.
Since $\a\in \aut(\Gamma)$ and $k>0$ is divisible by the order $|\out(\Gamma)|$, we have $\alpha^k\in \inn(\Gamma)$. Moreover, recall that a closed negatively curved Riemannian manifold is aspherical,  so $M$ is aspherical and hence the map $f^k_1: M\to M$ can be homotopied to the identity $\id_M$ of $M$. Since $\chi(M)=0$, the unique nonempty fixed point class of $\id_M$ is $M$ itself with index
$$\ind(\id_M,  M)=\chi(M)=0.$$
It  follows that $\Nie(\id_M)=0$ and hence
$$\Nie(f^k_1)=\Lef(f_1^k)=\Lef(\id_M)=\Nie(\id_M)=0.$$
Then by the ``Product formula for the Nielsen number'' \cite[p.88, Corollary 4.3]{J83}, we have
$$\Nie(f^k)=\Nie(f_1^k)\cdot \Nie(f'_{2,x})=0.$$
Therefore, by Lemma \ref{Jiang's deep thm Mf=Nf}, we have
$$\Lef(f^k)=\Min(f^k)=\Nie(f^k)=0.$$
We complete our proof.
\end{proof}



\begin{proof}[\textbf{Proof of Theorem \ref{main thm 3}}]
If $\Nie(f^k)=0$, then, by Lemma \ref{Jiang's deep thm Mf=Nf}, we obtain that
$$\Lef(f^k)=\Min(f^k)=\Nie(f^k)=0.$$
So Conclusion (1) holds.

If $\Nie(f^k)\neq 0,$ then $f^k$ has a fixed point $(x,y)=f^k(x,y)\in M\times N$. Suppose $\Gamma=\pi_1(M)$ and $G=\pi_1(N)$ throughout the proof. Then
the automorphism $f_\#$ of $\Gamma\times G$ induced by $f$ has the following form as in Eq. (\ref{eq. aut on fundamental group}):
	$$f_\#(\gamma, g)=(\alpha(\gamma),\rho(\gamma)L(g)),~\mathrm{for}~(\gamma,g)\in \Gamma\times G,$$
	where $\alpha : \Gamma\rightarrow \Gamma$ and $L : G \rightarrow G$ are automorphisms and $\rho :  \Gamma\rightarrow C(G)$ is a homomorphism into the center of $G$. Recall that $k>0$ is an integer divisible by the order $|\Out(\Gamma)|$, hence $\alpha^k : \Gamma\rightarrow \Gamma$ is an inner automorphism and
\begin{equation}\label{fk on on group}
f^k_\#(\gamma,g)=(\alpha^k(\gamma),\rho'(\gamma)L^k(g)),
\end{equation}
where $L^k : G \rightarrow G$ is an automorphism and $\rho' :  \Gamma\rightarrow C(G)$ is a homomorphism. Note that $\det(I-L^k_m)\neq 0$. Otherwise, if $\det(I-L^k_m)=0$ we obtain $\Nie(f^k)=0$ by Lemma \ref{periodic point}, it contradicts our assumption. Then applying Lemma \ref{alpha is inner} to $f^k$,
there exists a lifting $\widetilde{f^k}$ of $f^k$ in a finite cover $\widetilde{M}\times N$ of $M\times N$, and a homeomorphism $h: \widetilde{M}\times N\to \widetilde{M}\times N$, such that $$h\comp \widetilde{f^k}\comp h^{-1}\simeq f_1\times f_2,$$
    where $f_1:\widetilde{M}\to \widetilde{M}$ and $f_2: N\to N$ are homotopy equivalences.
So Conclusion (2) holds.
\end{proof}




\section{Some examples}\label{sect 6}


In \cite{PZ}, for each pair of integers $n, \ell$ such that $n\geq 3$, $0\leq \ell < n$ and $\mathrm{gcd}(n,2-\ell) = 1$, Paoluzzi and Zimmermann constructed a compact orientable hyperbolic 3-manifold $M_{n,\ell}$ with totally geodesic boundary (a surface of genus $n-1$). The fundamental group $\pi_1(M_{n,\ell})=G_{n,\ell}$ has the following presentation
$$G_{n,\ell}=\langle x_0,x_1,\ldots, x_{n-1}\mid \prod \limits^{n-1}_{i=0}x_{i(2-\ell)}x^{-1}_{i(2-\ell)+1}x^{-1}_{(i+1)(2-\ell)-1}=1 \rangle,$$
where we take indices $\mathrm{mod}~n$. Note that $\out(\pi_1(M_{n,\ell}))$ is finite (which can be obtain by applying Mostow rigidity to the double of $M_{n,\ell}$), but $M_{n,\ell}$ is not closed. The following example shows that the product $M_{n,\ell}\times T^2$ does not necessarily have BIPH$_k$ (and hence not have BIP$_k$). It implies that the condition ``$M$ is closed" in Theorem \ref{main thm 1} is necessary.

\begin{exam}\label{eg. 3-mfd with boudary} Set $n=3$ and $\ell=1$. The fundamental group of $M_{3,1}$ has the following presentation
	$$G_{3,1}=\langle x_0,x_1, x_2\mid x_0x_1^{-1}x_0^{-1}x_1x_2^{-1}x_1^{-1}x_2x_0^{-1}x_2^{-1}=1 \rangle,$$
	where $M_{3,1}$ has totally geodesic boundary $\Sigma_2$. Let $G=G_{3,1}\times \pi_1(T^2)$. For any integer $
 m>0$,  let the matrix $L_m=
\begin{pmatrix}
  m+1 & m \\
  1 & 1  \\
\end{pmatrix}$  as in Lemma \ref{invert}. We pick $\phi\in\aut(G)$ as
$$\phi(u,{{s_1}\choose{s_2}})=(u,{{\rho(u)}\choose{0}}+L_m{{s_1}\choose{s_2}})$$
where $u\in G_{3,1}$, $(s_1,s_2)^T\in \pi_1(T^2)\cong \Z\times \Z$ and $\rho: G_{3,1}\to \Z$ is defined as follows:
$$\rho(x_0)=1, ~\rho(x_1)=0,~\rho(x_2)=-1.$$
By direct calculation, we obtain
$$\phi^k(u,{{s_1}\choose{s_2}})=(u,\sum^{k-1}_{i=0}L_m^{i}{{\rho(u)}\choose{0}}+L_m^k{{s_1}\choose{s_2}}).$$
Recall that $(I-L_m^k)=(I-L_m)(\sum^{k-1}_{i=0}L_m^{i})$ is invertible by Lemma \ref{invert}, hence
\begin{eqnarray}
\fix(\phi^k)
& = & \{(u,{{s_1}\choose{s_2}})\mid {{s_1}\choose{s_2}}=\sum^{k-1}_{i=0}L_m^{i}{{\rho(u)}\choose{0}}+L_m^k{{s_1}\choose{s_2}}\}\notag\\
& = & \{(u,{{s_1}\choose{s_2}})\mid (I-L_m^k){{s_1}\choose{s_2}}=\sum^{k-1}_{i=0}L_m^{i}{{\rho(u)}\choose{0}}\}\notag\\
& = & \{(u,{{s_1}\choose{s_2}})\mid (I-L_m){{s_1}\choose{s_2}}={{\rho(u)}\choose{0}}\}\notag\\
& = & \{(u,{{s_1}\choose{s_2}})\mid {{s_1}\choose{s_2}}={{0}\choose{-\frac{\rho(u)}{m}}}, ~\rho(u)\equiv 0\mod m\}\notag.
\end{eqnarray}
Since $\rho:G_{3,1}\rightarrow \Z $ is an epimorphism,
it is not hard to see that
$$[G_{3,1}:p(\fix(\phi^k))]=m,$$
where $p: M_{3,1}\times T^2\to M_{3,1}$ is the projection to the first factor.

Now, we can pick a homeomorphism
\begin{eqnarray}\nonumber
 f: M_{3,1}\times T^2&\to& M_{3,1}\times T^2\\
 (x, ~y)&\mapsto& (x, ~f_2(x, y))\notag
\end{eqnarray} such that $f$ induces $\phi$ on the fundamental group. The restriction of $f^k$ on each fiber $T^2$ has Lefschetz number $\det(I-L^k_m)\ne0$ from Lemma \ref{invert}. By ``Product formula for the Lefschetz number" \cite[p.85, Theorem 3.2]{J83}, we have
\begin{equation}\label{eq-Lef1}\nonumber
  \Lef(f^k) = \det(I-L^k_m)\cdot \chi(M_{3,1})\ne 0.
\end{equation}
Therefore, there is an essential fixed point class $\F$ of $f^k$ and
$$
|\ind(f^k,\F)|=[G_{3,1}: p(\fix (\phi^k))]\cdot |\chi(M_{3,1})|=m|\chi(M_{3,1})|.
$$
Recall that $m$ can be arbitrarily large,  we have proven that $M_{3,1}\times T^2$ does not have BIPH$_k$ for any $k\geq 1$.
\end{exam}


Finally, the following example shows that the condition ``$k>0$ divisible by $|\Out(\pi_1(M ))|$'' is necessary in Theorem \ref{main thm 1}, even if $M$ is a closed hyperbolic $3$-manifold.

\begin{exam}\label{eg. closed 3-mfd}
Let $M$ be a closed orientable hyperbolic $3$-manifold with a retraction
$$r: M\to\Sigma_g,$$
where $\Sigma_g\subset M (g>1)$ is a totally geodesic embedded closed orientable hyperbolic surface fixed pointwise by an orientation-reversing isometry $f_1: M\to M$ of order $2$. (Such a manifold $M$ does exist, see \cite[Theorem 1.9]{BHW11}).
Then, for any integer $m>0$, there is a homeomorphism
\begin{eqnarray}\nonumber
f: M\times T^2 &\to& M\times T^2\\
(x, ~y)&\mapsto& (f_1(x), ~f_2(r(x),y))\notag
\end{eqnarray}
where $f_2: \Sigma_g\times T^2 \to T^2$ is defined as in Eq. (\ref{eq. f on T2}). Note that $$f|_{\Sigma_g\times T^2}(x, y)=(x, ~f_2(x,y)),$$
and the fixed point set
$$\fix f=\fix(f|_{\Sigma_g\times T^2}:\Sigma_g\times T^2\to\Sigma_g\times T^2)$$
which is a nonempty fixed point class $\F:=\fix f$ (see \cite[Sect. 4]{ZZ23}). Since the restriction of $f_1$ to the neighborhood of $\Sigma_g$ in $M$ is a reflection, by Eq. (\ref{eq. ind fk}), we have the index
$$\ind(f, \F)=\ind(f|_{\Sigma_g\times T^2}, \F)=m(2g-2).$$
Since $m$ can be arbitrarily large, we have proven that $M\times T^2$ does not have BIPH. But it has BIPH$_k$ for $k>0$ divisible by $|\Out(\pi_1(M ))|$ according to Theorem \ref{main thm 1}.
\end{exam}




