\hypertarget{AppA}{}
\section*{APPENDIX A.\\FROM LINEAR HAMILTONIANS TO SEPARABLE HAMILTONIANS}\label{AppA}

To ease the mathematical manipulations, let us focus on binary, undiretced networks (BUNs). Linear ERGs are described by Hamiltonians reading

\begin{equation}
H(\mathbf{A})=\sum_i\sum_{j(>i)}H_{ij}(a_{ij})=\sum_i\sum_{j(>i)}\theta_{ij}a_{ij},
\end{equation}
hence inducing models that can be factorised as

\begin{equation}
P(\mathbf{A})=\prod_i\prod_{j(>i)}p_{ij}^{a_{ij}}(1-p_{ij})^{1-a_{ij}}
\end{equation}
with

$$
p_{ij}=\frac{e^{-\theta_{ij}}}{1+e^{-\theta_{ij}}}=\frac{x_{ij}}{1+x_{ij}}.
$$

The related ensembles are easy to sample since $a_{ij}\sim\text{Ber}[p_{ij}]$ and $a_{ij}\perp\!\!\!\perp a_{kl}$, with $(i,j)\neq(k,l)$. Separable Hamiltonians, instead, read

\begin{align}\label{eq:17}
H(\mathbf{A})=\sum_i\sum_{j(>i)}H_{ij}(\mathbf{A})=\sum_i\sum_{j(>i)}a_{ij}\cdot f_{ij}(\mathbf{A},\theta_{ij}),
\end{align}
hence inducing models that can be factorised as well as

\begin{equation}
P(\mathbf{A})=\prod_i\prod_{j(>i)}p_{ij}^{a_{ij}}(1-p_{ij})^{1-a_{ij}}
\end{equation}
but with

\begin{equation}
p_{ij}=\frac{e^{-f_{ij}(\mathbf{P},\theta_{ij})}}{1+e^{-f_{ij}(\mathbf{P},\theta_{ij})}},
\end{equation}
where $\mathbf{P}=\langle\mathbf{A}\rangle$. The mean-field approximation consists precisely in replacing $\mathbf{A}$ with $\mathbf{P}$, inside $f_{ij}$, in eq.~\ref{eq:17}.

\clearpage

\hypertarget{AppB}{}
\section*{APPENDIX B.\\THE TWO-STAR MODEL AND ITS DEGREE-CORRECTED VERSION}\label{AppB}

Let us provide a concrete example of the mean-field approximation above, by considering the so-called two-star model (2SM). It is defined by

\begin{align}
H_\text{2SM}(\mathbf{A})&=\theta L+\psi S\nonumber\\
&=\theta L+\psi\sum_i\sum_{l(>i)}V_{il}\nonumber\\
&=\theta L+\psi\sum_i\sum_{l(>i)}\sum_ja_{ij}a_{jl}\nonumber\\
&=\theta L+\frac{\psi}{2}\sum_i\sum_{l(\neq i)}\sum_ja_{ij}a_{jl}\nonumber\\
&=\theta L+\frac{\psi}{2}\sum_j\sum_i\sum_{l(\neq i)}a_{ij}a_{jl}\nonumber\\
&=\theta L+\frac{\psi}{2}\sum_j\sum_i\left[\sum_la_{ij}a_{jl}-a_{ji}\right]\nonumber\\
&=\theta L+\frac{\psi}{2}\left[\sum_i\sum_j\sum_la_{ij}a_{jl}-\sum_jk_j\right]\nonumber\\
&=\theta L+\frac{\psi}{2}\left[\sum_i\sum_ja_{ij}k_j-\sum_jk_j\right]\nonumber\\
&=\theta L+\frac{\psi}{2}\left[\sum_i\sum_{j(>i)}(a_{ij}k_j+a_{ji}k_i)-\sum_jk_j\right]\nonumber\\
&=\theta L+\frac{\psi}{2}\left[\sum_i\sum_{j(>i)}a_{ij}(k_i+k_j)-\sum_jk_j\right]\nonumber\\
&=\theta L+\frac{\psi}{2}\left[\sum_i\sum_{j(>i)}a_{ij}(k_i+k_j)\right]-\frac{\psi}{2}\sum_jk_j\nonumber\\
&=\theta L+\frac{\psi}{2}\left[\sum_i\sum_{j(>i)}a_{ij}(k_i+k_j)\right]-\psi L\nonumber\\
&=(\theta-\psi)L+\frac{\psi}{2}\left[\sum_i\sum_{j(>i)}a_{ij}(k_i+k_j)\right];
\end{align}
upon renaming $\theta-\psi$ as $\alpha$ and $\psi/2$ as $\beta$, one finds

\begin{align}
H_\text{2SM}(\mathbf{A})&=\alpha L+\beta\left[\sum_i\sum_{j(>i)}a_{ij}(k_i+k_j)\right]\nonumber\\
&=\alpha\sum_i\sum_{j(>i)}a_{ij}+\beta\left[\sum_i\sum_{j(>i)}a_{ij}(k_i+k_j)\right]\nonumber\\
&=\sum_i\sum_{j(>i)}a_{ij}[\alpha+\beta(k_i+k_j)]
\end{align}
and identifying $f_{ij}$ with $\alpha+\beta(k_i+k_j)$ leads to

\begin{equation}\label{eq:score_TwoStar}
p_{ij}^\text{2SM}=\frac{e^{-\alpha-\beta(k_i+k_j)}}{1+e^{-\alpha-\beta(k_i+k_j)}}=\frac{xy^{k_i+k_j}}{1+xy^{k_i+k_j}}.
\end{equation}

Since the information about the degrees is not supposed to be available, consistency requires that

\begin{equation}
p=\frac{xy^{2(N-1)p}}{1+xy^{2(N-1)p}};
\end{equation}
in case the information about the degrees is, instead, available, the Hamiltonian becomes 

\begin{equation}
H_\text{dc2SM}(\mathbf{A})=\sum_i\theta_ik_i+\psi S
\end{equation}
and induces the expression

\begin{equation}
p_{ij}^\text{dc2SM}=\frac{e^{-(\alpha_i+\alpha_j)-\beta(k_i+k_j)}}{1+e^{-(\alpha_i+\alpha_j)-\beta(k_i+k_j)}}=\frac{x_ix_jy^{k_i+k_j}}{1+x_ix_jy^{k_i+k_j}}.
\end{equation}

Let us now consider that

\begin{equation}
\sum_i\binom{\langle k_i\rangle}{2}=\frac{1}{2}\sum_i[\langle k_i\rangle^2-\langle k_i\rangle]=\frac{1}{2}\sum_i[\langle k_i^2\rangle-\text{Var}[k_i]-\langle k_i\rangle]=\langle S\rangle-\frac{1}{2}\sum_i\text{Var}[k_i]:
\end{equation}
as a consequence, the expected number of two-stars reads

\begin{equation}
\langle S\rangle=\sum_i\binom{\langle k_i\rangle}{2}+\frac{1}{2}\sum_i\text{Var}[k_i].
\end{equation}

Since $S=\sum_i\binom{k_i}{2}$, requiring $\langle k_i\rangle=k_i$ leads one to obtain

\begin{equation}
\langle S\rangle=\sum_i\binom{k_i}{2}+\frac{1}{2}\sum_i\text{Var}[k_i]=S+\frac{1}{2}\sum_i\text{Var}[k_i]\geq S,
\end{equation}
the equivalence holding true in case $\text{Var}[k_i]=0$, $\forall\:i$ (i.e. either in the microcanonical case or in the canonical, deterministic case). If, instead, the following relationship holds true

\begin{equation}
\label{condition_for_two_stars}
\sum_i\binom{\langle k_i\rangle}{2} < \sum_i\binom{k_i}{2}
\end{equation}
one finds that

\begin{align}
\langle S\rangle&=\sum_i\binom{\langle k_i\rangle}{2}+\frac{1}{2}\sum_i\text{Var}[k_i]<\sum_i\binom{k_i}{2}+\frac{1}{2}\sum_i\text{Var}[k_i]=S+\frac{1}{2}\sum_i\text{Var}[k_i],
\end{align}
i.e. that

\begin{equation}
\langle S\rangle<S+\frac{1}{2}\sum_i\text{Var}[k_i],
\end{equation}
or, even more explicitly,

\begin{equation}
\langle S\rangle-S<\frac{1}{2}\sum_i\text{Var}[k_i].
\end{equation}

In order for eq.~\ref{condition_for_two_stars} to hold true, the condition $\langle k_i\rangle<k_i$ must be verified for \emph{at least} one node: in other words, reproducing $S$ requires \emph{at least} one degree to be underestimated.

